model = load(selection_path.with_suffix(".joblib"))["model"]
original = np.load(selection_path.with_suffix(".npz"))
score = prior[heldout].copy()
score[valid[heldout]] += (model.predict(forward[test_valid]) - model.predict(reverse[test_valid])) / 2.
