level_control_diagnosis_parts.append(pd.DataFrame({"trace_id": trace_id[heldout],
    "level_control_zero_signal_period_h": periods[heldout][np.arange(heldout.sum()), selected]}))
print("level_control_diagnosis", fold, int(heldout.sum()), flush=True)
'''
level_control_diagnose_stage = r'''
level_control_diagnosis_parts = []
list(map(lambda current_fold: (setattr(args, "heldout_run", current_fold), exec(compile(level_control_diagnose_fold, __file__, "exec"))), range(application["lemna_expected_runs"])))
stem = application["paths"]["lemna_candidate_diagnosis"]
records = pd.read_csv(stem.with_suffix(".csv"), encoding="utf-8", float_precision="round_trip").set_index("trace_id")
