'''
level_increment_export_stage = r'''
# Preserve the old score and add only the fitted change due to the new evidence.
# This is a counterfactual score decomposition, not a causal effect estimate.
base_stem = application["paths"][increment_base_key]
base_path = base_stem.with_name(base_stem.name + "_fold" + str(fold))
base = np.load(base_path.with_suffix(".npz"))
assert np.array_equal(base["trace_id"], trace_id[heldout])
assert np.array_equal(base["train_trace_id"], trace_id[train])
assert np.array_equal(base["periods"], periods[heldout], equal_nan=True)
assert np.max(np.abs(base["prior"][valid[heldout]] - prior[heldout][valid[heldout]])) < 1e-12
increment_score = base["scores"].copy()
increment_score[valid[heldout]] += original["scores"][valid[heldout]] - score[valid[heldout]]
selected = increment_score.argmax(axis=1)
absolute_stem = application["paths"]["lemna_prior_evidence"]
