exec(compile({"transfer-source-diagnose": transfer_source_diagnosis_stage}.get(args.stage, ""), __file__, "exec"))

transfer_covariance_prepare_stage = r'''
import ast
source_path = application["paths"]["source"]
source_text = source_path.read_text(encoding="utf-8")
source_scope = {"__file__": str(source_path)}
exec(compile(source_text[:source_text.index('\nimport sys\nphase_mode=')], str(source_path), "exec"), source_scope)
mechanism_path = application["paths"]["mechanism"]
mechanism_text = mechanism_path.read_text(encoding="utf-8")
tree = ast.parse(mechanism_text)
node = next(filter(lambda item: isinstance(item, ast.Assign) and isinstance(item.targets[0], ast.Name)
    and item.targets[0].id == "natural_context_code", tree.body))
scope = {"p": mechanism_path, "s": mechanism_text, "output": OUTPUT, "mode": "lemna_dual", "np": np, "Path": Path}
exec(compile(ast.literal_eval(node.value), str(mechanism_path), "exec"), scope)
geometry = scope["d"]
feature_body = source_scope["residual_source_predict_code"][:source_scope["residual_source_predict_code"].index('source_prediction=np.empty')]
exec(compile(feature_body, str(source_path), "exec"), geometry)
bank = np.load(application["paths"]["controlled_source_bank"])
external = np.load(application["paths"]["transfer_source_diagnosis"].with_name(
    application["paths"]["transfer_source_diagnosis"].name + "_external.npz"))
natural_count = len(geometry["y"])
controlled_count, external_count = len(bank["trace_id"]), len(external["trace_id"])
time = geometry["time"]
step = np.diff(time)[0]
assert np.allclose(np.diff(time), step)
indices = np.concatenate([bank["index"], external["index"] + np.array([controlled_count, 0]),
    np.column_stack([geometry["qi"] + controlled_count + external_count, geometry["ti"]])])
residual = np.full((controlled_count + external_count + natural_count, len(time)), np.nan)
residual[tuple(indices.T)] = np.r_[bank["features"][:, 2], external["features"][:, 2], geometry["source_features"][:, 2]]
lag = np.rint(np.asarray(application["transfer_covariance_lags_h"]) / step).astype(int)
right_position = np.arange(len(time))[None] + lag[:, None]
left_value = residual[:, None, :]
right_value = residual[:, right_position.clip(0, len(time) - 1)]
supported = np.isfinite(left_value) & np.isfinite(right_value) & (right_position[None] < len(time))
count = supported.sum(axis=-1)
left_mean = np.divide(np.where(supported, left_value, 0.).sum(axis=-1), count,
    out=np.full(count.shape, np.nan), where=count > 0)
right_mean = np.divide(np.where(supported, right_value, 0.).sum(axis=-1), count,
    out=np.full(count.shape, np.nan), where=count > 0)
left_centered = np.where(supported, left_value - left_mean[..., None], 0.)
right_centered = np.where(supported, right_value - right_mean[..., None], 0.)
denominator = np.sqrt(np.square(left_centered).sum(axis=-1) * np.square(right_centered).sum(axis=-1))
covariance = np.divide((left_centered * right_centered).sum(axis=-1), denominator,
    out=np.full(denominator.shape, np.nan), where=denominator > 0)
ids = np.r_[bank["trace_id"], external["trace_id"], geometry["signals"]["trace_id"]]
domains = np.r_[np.repeat("controlled", controlled_count), np.repeat("lemna_injection", external_count),
    np.repeat("natural", natural_count)]
assert not np.isinf(covariance).any() and np.isfinite(covariance).any(axis=1).all()
assert np.nanmax(np.abs(covariance)) <= 1. + 1e-12
np.savez_compressed(application["paths"]["transfer_covariance"], trace_id=ids, domain=domains,
    features=covariance, pair_count=count, lags_h=np.asarray(application["transfer_covariance_lags_h"]))
print("transfer_covariance", covariance.shape, "finite", np.isfinite(covariance).sum(axis=0), flush=True)
print(pd.DataFrame(covariance, columns=application["transfer_covariance_lags_h"]).groupby(domains).median().to_string(), flush=True)
raise SystemExit(0)
'''
exec(compile({"transfer-covariance-prepare": transfer_covariance_prepare_stage}.get(args.stage, ""), __file__, "exec"))

