transfer_background_controlled_fit_stage = r'''
from sklearn.base import clone
from joblib import dump
bank = np.load(application["paths"]["controlled_source_bank"])
labels = np.load(application["paths"]["source_targets"])
reference = np.load(application["paths"]["controlled_reference"])
external = np.load(application["paths"]["transfer_source_diagnosis"].with_name(
    application["paths"]["transfer_source_diagnosis"].name + "_external.npz"))
metadata = pd.read_parquet(application["paths"]["external_injection_metadata"]).set_index("trace_id").loc[external["trace_id"]]
assert np.array_equal(bank["trace_id"], reference["trace_id"])
assert np.array_equal(bank["index"], labels["index"])
external_fold = pd.Series(reference["folds"], index=reference["trace_id"]).loc[metadata.source_trace_id].to_numpy()
fold = args.heldout_run
train = bank["folds"] != fold
train_external = external_fold != fold
qi, ti = bank["index"].T
ei, et = external["index"].T
source = load(Path(str(application["paths"]["source_model_pattern"]).format(fold=fold)))
model = clone(source)
assert model.random_state == 12345
print("background_controlled_source_fit", fold, int(train.sum()), int(train_external.sum()), flush=True)
model.fit(np.concatenate([bank["features"][train[qi]], external["features"][train_external[ei]]]),
    np.r_[labels["response"][train[qi]], external["residual_response"][train_external[ei]]],
    sample_weight=np.r_[labels["weight"][train[qi]], external["residual_weight"][train_external[ei]]] * len(bank["features"]) / len(bank["trace_id"]))
test_rows = ~train[qi]
prediction = model.predict(bank["features"][test_rows]).clip(0., 1.)
previous = source.predict(bank["features"][test_rows]).clip(0., 1.)
weight = labels["weight"][test_rows]
truth = labels["response"][test_rows]
records = pd.DataFrame({"index": qi[test_rows], "q_true": weight * truth, "old": weight * previous,
    "calibrated": weight * prediction, "old_mse": weight * (previous-truth)**2,
    "calibrated_mse": weight * (prediction-truth)**2}).groupby("index").sum()
records["trace_id"] = bank["trace_id"][records.index]
records["domain"] = np.where(records.index < len(external["trace_id"]), "primary", "crossed")
records["fold"] = fold
stem = application["paths"]["transfer_background_source"].with_name(
    application["paths"]["transfer_background_source"].name + "_controlled_fold" + str(fold))
dump({"model": model, "training_controlled_trace_id": bank["trace_id"][train],
    "training_external_trace_id": external["trace_id"][train_external], "fold": fold}, stem.with_suffix(".joblib"))
np.savez_compressed(stem.with_suffix(".npz"), prediction=prediction, frozen=previous,
    index=bank["index"][test_rows], trace_id=bank["trace_id"][~train])
records.to_csv(stem.with_suffix(".csv"), index=False, encoding="utf-8")
print(records.groupby("domain")[["old_mse", "calibrated_mse"]].mean().to_string(), flush=True)
raise SystemExit(0)
'''
exec(compile({"transfer-background-controlled-fit": transfer_background_controlled_fit_stage}.get(args.stage, ""), __file__, "exec"))

