coordinate_controlled_report_stage = r'''
stem = application["paths"]["coordinate_report"]
paths = list(map(lambda fold: application["paths"]["coordinate_controlled"].with_name(
    application["paths"]["coordinate_controlled"].name + "_fold" + str(fold)).with_suffix(".csv"), range(application["controlled_folds"])))
new = pd.concat(list(map(lambda path: pd.read_csv(path, encoding="utf-8", float_precision="round_trip"), paths)), ignore_index=True)
new = new.loc[new.kind.eq("prior_contrast_coordinate_invariant_absolute_report")].copy()
new["method"] = "coordinate_invariant_transfer"
old = pd.read_csv(application["paths"]["controlled_prior_balanced_floor_control"].with_suffix(".csv"), encoding="utf-8", float_precision="round_trip")
old = old.loc[old.kind.eq("prior_contrast_balanced_floor_absolute_report")].copy()
old["method"] = "current_transfer"
reference = np.load(application["paths"]["controlled_reference"])
meta = old.set_index("trace_id").loc[reference["trace_id"], ["dataset", "group", "fold"]]
meta["truth_h"] = reference["truth"]
assert np.array_equal(meta.fold, reference["folds"])
assert new.fold.eq(new.trace_id.map(meta.fold)).all()
columns = ["trace_id", "method", "estimate", "confidence"]
controlled = pd.concat([old[columns], new[columns]], ignore_index=True).join(meta, on="trace_id", validate="many_to_one")
assert controlled.groupby("method").trace_id.nunique().eq(len(reference["trace_id"])).all()
controlled = controlled.rename(columns={"dataset": "domain", "group": "background_group", "estimate": "estimate_h"})
controlled["reference_usable"] = True
controlled["error_h"] = np.abs(controlled.estimate_h - controlled.truth_h)
controlled["bad2h"] = controlled.error_h > application["risk_tolerance_h"]
external = pd.read_csv(application["paths"]["coordinate_external"].with_suffix(".csv"), encoding="utf-8", float_precision="round_trip").assign(
    domain="lemna_injection", reference_usable=True)
natural = pd.read_csv(application["paths"]["coordinate_natural"].with_suffix(".csv"), encoding="utf-8", float_precision="round_trip").assign(domain="natural")
natural = natural.rename(columns={"run": "background_group", "reference_period_h": "truth_h"})
columns = ["domain", "trace_id", "method", "background_group", "truth_h", "estimate_h", "confidence", "error_h", "bad2h", "reference_usable"]
records = pd.concat([controlled[columns], external[columns], natural[columns]], ignore_index=True)
records["bad2h"] = records.bad2h.astype(float)
assert not records.duplicated(["domain", "method", "trace_id"]).any()
scoped = pd.concat([records.assign(scope="all"), records.assign(scope=records.background_group.astype(str))], ignore_index=True)
keys = ["domain", "scope", "method"]
summary = scoped.groupby(keys).agg(total=("trace_id", "size"), qualified=("reference_usable", "sum"),
    bad=("bad2h", "sum"), mae_h=("error_h", "mean"), median_h=("error_h", "median"))
curve = scoped.loc[scoped.reference_usable].sort_values(keys + ["confidence", "trace_id"], ascending=[True, True, True, False, True], kind="stable").copy()
curve["accepted"] = curve.groupby(keys).cumcount() + 1
curve["risk"] = curve.groupby(keys).bad2h.cumsum() / curve.accepted
points = summary.reset_index()[keys + ["qualified"]].merge(pd.DataFrame({"coverage": np.linspace(.1, 1., 10)}), how="cross")
points["accepted"] = np.ceil(points.qualified * points.coverage).astype(int)
points = points.merge(curve[keys + ["accepted", "risk"]], on=keys + ["accepted"], validate="many_to_one")
points["area"] = points.risk * np.where(points.coverage.isin([.1, 1.]), .5, 1.)
summary["aurc"] = points.groupby(keys).area.sum() / 9.
summary = summary.reset_index()
summary["aurc_definition"] = "deciles_10_to_100_percent"
natural_summary = pd.read_csv(application["paths"]["coordinate_natural"].with_name(
    application["paths"]["coordinate_natural"].name + "_summary.csv"), encoding="utf-8").set_index(["scope", "method"])
natural_all = summary.domain.eq("natural") & summary.scope.eq("all")
summary.loc[natural_all, "aurc"] = summary.loc[natural_all, "method"].map(natural_summary.loc["all", "matched_aurc"])
summary.loc[natural_all, "aurc_definition"] = "natural_existing_common_coverage"
baseline = records.loc[records.method.eq("current_transfer"), ["domain", "trace_id", "bad2h", "error_h"]].rename(
    columns={"bad2h": "old_bad2h", "error_h": "old_error_h"})
paired = records.loc[records.method.eq("coordinate_invariant_transfer")].merge(baseline, on=["domain", "trace_id"], validate="one_to_one")
paired["fixed"] = paired.old_bad2h.eq(1) & paired.bad2h.eq(0)
paired["harmed"] = paired.old_bad2h.eq(0) & paired.bad2h.eq(1)
paired_scoped = pd.concat([paired.assign(scope="all"), paired.assign(scope=paired.background_group.astype(str))], ignore_index=True)
changes = paired_scoped.groupby(keys).agg(fixed=("fixed", "sum"), harmed=("harmed", "sum"))
summary = summary.merge(changes, on=keys, how="left", validate="one_to_one")
records.to_csv(stem.with_suffix(".csv"), index=False, encoding="utf-8")
summary.to_csv(stem.with_name(stem.name + "_summary.csv"), index=False, encoding="utf-8")
paired.to_csv(stem.with_name(stem.name + "_paired.csv"), index=False, encoding="utf-8")
print(summary.loc[summary.scope.eq("all")].to_string(index=False), flush=True)
raise SystemExit(0)
'''
exec(compile({"transfer-coordinate-controlled-report": coordinate_controlled_report_stage}.get(args.stage, ""), __file__, "exec"))

evidence_reference_transform = prior_contrast_transform_stage.replace(
    'reference_candidate = np.where(valid, prior, -np.inf).argmax(axis=1)',
    'reference_candidate = np.where(valid, anchor, -np.inf).argmax(axis=1)')
