exec(compile({"transfer-coordinate-shift": coordinate_shift_stage}.get(args.stage, ""), __file__, "exec"))

secant_input_stage = r'''
# A tolerance-scaled secant retains short-distance contrasts and expresses
# longer comparisons per two-hour interval. Symmetric context is unchanged.
secant_scale = np.maximum(np.abs(periods - reference_period[:, None]) / application["risk_tolerance_h"], 1.)
directional_columns = np.setdiff1d(np.r_[np.arange(observed.shape[-1]), observed.shape[-1] + 4], context)
forward[..., directional_columns] /= secant_scale[..., None]
reverse[..., directional_columns] /= secant_scale[..., None]
contrast_config["comparison_normalization"] = "period_secant_at_risk_tolerance"
'''
secant_transform_stage = prior_contrast_transform_stage + secant_input_stage
secant_full_stage = coordinate_full_stage.replace('prior_contrast_transform_stage', 'secant_transform_stage').replace(
    '"coordinate_full"', '"secant_full"').replace('prior_contrast_coordinate_invariant_', 'prior_contrast_period_secant_').replace(
    '"target": target}', '"target": target / secant_scale}')
secant_external_stage = coordinate_external_stage.replace('prior_contrast_transform_stage', 'secant_transform_stage').replace(
    '"coordinate_full"', '"secant_full"').replace('"coordinate_external"', '"secant_external"').replace(
    '"coordinate_invariant_transfer"', '"period_secant_transfer"').replace(
    'bundle["selector"].predict(reverse[..., columns][valid])) / 2.',
    'bundle["selector"].predict(reverse[..., columns][valid])) / 2. * secant_scale[valid]')
