coordinate_columns = np.r_[context, application["node_period_column"], np.arange(application["node_profile_start"], observed.shape[-1]),
    np.arange(observed.shape[-1] + len(application["coordinate_omitted_context"]) + 1, forward.shape[-1])]
contrast_config["comparison_evidence"] = "record_context_and_current_node"
