anchor_level_report_stage = node_report_stage.replace('"node_report"', '"anchor_level_report"').replace(
    '"node_controlled"', '"anchor_level_controlled"').replace('"node_external"', '"anchor_level_external"').replace(
    '"node_natural"', '"anchor_level_natural"').replace('prior_contrast_node_evidence_', 'prior_contrast_anchor_level_').replace(
    '"node_evidence_transfer"', '"anchor_level_transfer"')
