level_fusion_fold_stage = r'''
# Combine the two fitted modules on their common Laplace-utility scale.
# The equal weight is fixed, not estimated from outer-fold labels.
domain, fold = args.density_domain, args.heldout_run
base_stem = application["paths"][{"primary": "controlled_prior_level", "natural": "lemna_prior_level"}[domain]]
density_stem = OUTPUT / {"primary": "event_prior_density_fivefold", "natural": "lemna_dual_density_loro"}[domain]
absolute_stem = application["paths"][{"primary": "controlled_prior_evidence", "natural": "lemna_prior_evidence"}[domain]]
output_stem = application["paths"][{"primary": "controlled_prior_level_fusion", "natural": "lemna_prior_level_fusion"}[domain]]
suffix = "_fold" + str(fold)
base = np.load(base_stem.with_name(base_stem.name + suffix).with_suffix(".npz"))
density = np.load(density_stem.with_name(density_stem.name + suffix).with_suffix(".npz"))
absolute = np.load(absolute_stem.with_name(absolute_stem.name + suffix).with_suffix(".npz"))
trace_id, periods, valid = base["trace_id"], base["periods"], base["valid"]
density_order = pd.Index(density["trace_id"]).get_indexer(trace_id)
assert (density_order >= 0).all() and np.array_equal(absolute["trace_id"], trace_id)
assert np.array_equal(np.sort(base["train_trace_id"]), np.sort(density["train_trace_id"]))
assert not np.isin(trace_id, base["train_trace_id"]).any()
assert np.array_equal(absolute["periods"], periods, equal_nan=True)
mass = density["mass"][density_order, :, 0]
assert np.allclose(mass.sum(axis=1), 1., rtol=0., atol=1e-10)
density_utility = np.sum(mass[:, None] * np.exp(-np.abs(
    np.where(valid, periods, density["periods"][0])[..., None] - density["periods"][None, None]) / application["risk_tolerance_h"]), axis=-1)
mix_weight = application["fusion_density_weight"]
score = (1. - mix_weight) * base["scores"] + mix_weight * density_utility
score = np.where(valid, score, -np.inf)
selected = score.argmax(axis=1)
row = np.arange(len(trace_id))
estimate = periods[row, selected]
confidence = np.column_stack([absolute["scores"][:, :, 0][row, selected], score[row, selected]])
stem = output_stem.with_name(output_stem.name + suffix)
np.savez_compressed(stem.with_suffix(".npz"), trace_id=trace_id, periods=periods, valid=valid,
    scores=score, selected=selected, confidence=confidence, density_utility=density_utility,
    train_trace_id=base["train_trace_id"], fusion_density_weight=mix_weight)
predictions = pd.read_csv(base_stem.with_name(base_stem.name + suffix).with_suffix(".csv"), encoding="utf-8")
assert np.array_equal(predictions.trace_id.to_numpy(), np.repeat(trace_id, 2))
predictions[{"primary": "kind", "natural": "method"}[domain]] = np.tile(
    ["prior_level_fusion_absolute_report", "prior_level_fusion_utility"], len(trace_id))
predictions[{"primary": "estimate", "natural": "estimate_h"}[domain]] = np.repeat(estimate, 2)
predictions["confidence"] = confidence.ravel()
predictions.to_csv(stem.with_suffix(".csv"), index=False, encoding="utf-8")
print("level_fusion_fold", domain, fold, "heldout", len(trace_id), flush=True)
raise SystemExit(0)
'''
