folds = {"primary": application["controlled_folds"], "natural": application["lemna_expected_runs"]}[args.density_domain]
list(map(lambda fold: subprocess.run([sys.executable, "-X", "utf8", __file__, "--stage", "level-fusion-fold",
    "--density-domain", args.density_domain, "--heldout-run", str(fold)], check=True), range(folds)))
raise SystemExit(0)
