assert args.dataset == "per2"
production_path = application["paths"]["application"]
production_text = production_path.read_text(encoding="utf-8")
inference = {"__file__": str(production_path), "ROOT": ROOT, "args": args, "os": os,
             "ast": ast, "np": np, "pd": pd, "torch": torch, "nn": nn,
             "Parallel": Parallel, "delayed": delayed, "least_squares": least_squares,
             "fftconvolve": fftconvolve, "lombscargle": lombscargle, "kendalltau": kendalltau}
config_start = production_text.index("CONFIG = {")
config_end = production_text.index('\nos.environ["OMP_NUM_THREADS"]', config_start)
exec(compile(production_text[config_start:config_end], str(production_path), "exec"), inference)
setup_start = production_text.index('torch.set_num_threads(CONFIG["threads"])')
setup_end = production_text.index("\nper2_observation_code =", setup_start)
exec(compile(production_text[setup_start:setup_end], str(production_path), "exec"), inference)
inference["observations"] = pd.read_parquet(application["paths"]["observations"])
forward_start = production_text.index('trace_groups = list(observations.groupby("trace_id", sort=True))')
forward_end = production_text.index("\nestimated =", forward_start)
exec(compile(production_text[forward_start:forward_end], str(production_path), "exec"), inference)
trace_id = inference["trace_ids"].to_numpy(dtype=str)
posterior = inference["period_probability"]
period_grid = inference["P_GRID"]
mean = inference["neural_period"]
std = inference["neural_spread"]
assert len(trace_id) == application["posterior_expected_traces"]
assert posterior.shape == (len(trace_id), inference["CONFIG"]["spec_n"])
assert np.isfinite(posterior).all() and (posterior >= 0.).all()
assert np.max(np.abs(posterior.sum(axis=1) - 1.)) < 1e-6
inputs = pd.read_parquet(application["paths"]["predictions"]).set_index("trace_id").loc[trace_id]
comparison = pd.read_csv(application["paths"]["comparison"], encoding="utf-8",
                         float_precision="round_trip", usecols=["trace_id", "method", "estimate_h", "confidence"])
neural = comparison.loc[comparison["method"].eq("neural_network")].set_index("trace_id").loc[trace_id]
replay_error = np.array([
    np.max(np.abs(mean - inputs["nn_frozen_period"].to_numpy())),
    np.max(np.abs(std - inputs["nn_frozen_pstd"].to_numpy())),
    np.max(np.abs(mean - neural["estimate_h"].to_numpy())),
    np.max(np.abs(std + neural["confidence"].to_numpy())),
])
assert replay_error.max() < application["posterior_replay_tolerance_h"]
records = comparison.loc[comparison["method"].isin(application["posterior_period_sources"]),
                         ["trace_id", "method", "estimate_h"]].rename(columns={"method": "period_source"})
assert len(records) == len(trace_id) * len(application["posterior_period_sources"])
assert not records.duplicated(["trace_id", "period_source"]).any()
assert records.groupby("period_source").size().eq(len(trace_id)).all()
address = pd.Index(trace_id).get_indexer(records["trace_id"])
assert (address >= 0).all()
within = np.abs(period_grid[None, :] - records["estimate_h"].to_numpy()[:, None]) <= application["risk_tolerance_h"]
records["posterior_mass_2h"] = np.sum(posterior[address] * within, axis=1)
assert np.isfinite(records["posterior_mass_2h"]).all()
np.savez_compressed(application["paths"]["neural_posterior"], posterior=posterior, P_GRID=period_grid,
                    trace_id=trace_id, mean=mean, std=std)
records.to_csv(application["paths"]["posterior_confidence"], index=False, encoding="utf-8")
print("per2_posterior_recovery", posterior.shape, "max_abs_error_input_mean_std_comparison_mean_std_h",
      replay_error, "confidence_rows", len(records), flush=True)
raise SystemExit(0)
'''
exec(compile({True: posterior_stage, False: ""}[args.stage == "posterior-confidence"], __file__, "exec"))

neural_distance_stage = r'''
assert args.dataset == "per2"
decision_path = application["paths"]["decision"]
decision_text = decision_path.read_text(encoding="utf-8")
saved_argv = sys.argv.copy()
sys.argv = [str(decision_path), "event_ownership_marked_event", "--stage", args.dataset]
scope = {"__file__": str(decision_path)}
stop = decision_text.index('exec(compile({False:"",True:event_external_decision_code}')
exec(compile(decision_text[:stop], str(decision_path), "exec"), scope)
sys.argv = saved_argv
body = scope["event_external_decision_code"]
exec(compile(body[:body.index('selected=raw_score.argmax(-1)')], str(decision_path), "exec"), scope)
official = np.load(application["paths"]["main_scores"])
trace_id = scope["trace_id"]
periods = scope["periods"]
valid = scope["candidate_valid"]
assert len(trace_id) == application["posterior_expected_traces"]
assert np.array_equal(trace_id, official["trace_id"])
assert np.array_equal(valid, official["valid"])
assert np.array_equal(periods[valid], official["periods"][valid])
replay_error = np.max(np.abs(scope["raw_score"][valid] - official["raw_scores"][valid]))
assert replay_error < 1e-12
inputs = pd.read_parquet(application["paths"]["predictions"]).set_index("trace_id").loc[trace_id]
nn_period = inputs["nn_frozen_period"].to_numpy()
nn_std = inputs["nn_frozen_pstd"].to_numpy()
features144 = scope["node_features"]
assert features144.shape == (*valid.shape, 144)
assert np.array_equal(features144[:, 0, 3], nn_std)
distance = np.abs(periods - nn_period[:, None])
features = np.concatenate([features144, distance[..., None]], axis=-1)
model = load(application["paths"]["neural_distance_model"])
assert model.n_features_in_ == 145
anchor = scope["raw_score"] - scope["residual_score"]
score = anchor.copy()
score[valid] += model.predict(features[valid])
score = np.where(valid, score, -np.inf)
selected = score.argmax(axis=1)
estimate = periods[np.arange(len(trace_id)), selected]
confidence = score.max(axis=1) - np.where(valid, score, 0.).sum(axis=1) / valid.sum(axis=1)
assert np.isfinite(estimate).all() and np.isfinite(confidence).all()
out = application["paths"]["neural_distance_output"]
np.savez_compressed(out.with_suffix(".npz"), trace_id=trace_id, periods=periods,
    valid=valid, scores=score, anchor=anchor, selected=selected, estimate=estimate,
    confidence=confidence, nn_period=nn_period, nn_std=nn_std, nn_distance=distance,
    added_feature=np.array("abs(candidate_period - nn_frozen_period)"))

# Temporal references enter only after every prediction has been computed.
comparison = pd.read_csv(application["paths"]["comparison"], encoding="utf-8",
                         float_precision="round_trip")
main = comparison.loc[comparison["method"].eq("main144")].set_index("trace_id").loc[trace_id]
assert np.max(np.abs(main["estimate_h"].to_numpy() - official["estimate"])) < application["alignment_tolerance_h"]
base_methods = ["main144", "main144_selection", "legacy26", "early_ls", "neural_network"]
columns = ["trace_id", "method", "estimate_h", "confidence"]
baseline = comparison.loc[comparison["method"].isin(base_methods), columns].copy()
new = pd.DataFrame({"trace_id": trace_id, "method": "neural_candidate_distance",
                    "estimate_h": estimate, "confidence": confidence})
new_common = new.assign(method="neural_candidate_distance_nnstd", confidence=-nn_std)
main_common = pd.DataFrame({"trace_id": trace_id, "method": "main144_nnstd",
    "estimate_h": official["estimate"], "confidence": -nn_std})
records = pd.concat([baseline, new, new_common, main_common], ignore_index=True)
records["position"] = records.groupby("method", sort=False).cumcount()
reference = pd.read_csv(application["paths"]["per2_reference"], encoding="utf-8",
                       float_precision="round_trip").set_index("cell").loc[trace_id]
header = pd.read_csv(application["paths"]["per2_source"], encoding="utf-8-sig", nrows=1)
ranges = header.iloc[0].dropna().astype(str).str.extract(r"Cells\s+(\d+)-(\d+)")
ranges = ranges.dropna().drop_duplicates().astype(int)
intervals = pd.IntervalIndex.from_arrays(ranges[0], ranges[1], closed="both")
group_index = intervals.get_indexer(reference["cell_number"])
assert (group_index >= 0).all()
group_labels = ("Cells " + ranges[0].astype(str) + "-" + ranges[1].astype(str)).to_numpy()
metadata = pd.DataFrame({"trace_id": trace_id,
    "late_ls_period_h": reference["late_ls_period_h"].to_numpy(),
    "culture": group_labels[group_index]})
assert np.array_equal(np.sort(metadata.groupby("culture").size().to_numpy()), [30, 49])
records = records.merge(metadata, on="trace_id", validate="many_to_one")
records["error_h"] = (records["estimate_h"] - records["late_ls_period_h"]).abs()
records["bad2h"] = records["error_h"] > application["risk_tolerance_h"]
assert records.groupby("method").size().eq(len(trace_id)).all()
ranked = records.sort_values(["method", "confidence", "position"],
    ascending=[True, False, True], kind="stable")
ranked["rank"] = ranked.groupby("method", sort=False).cumcount() + 1
coverage = np.arange(.1, 1.01, .1)
expanded = ranked.merge(pd.DataFrame({"coverage": coverage}), how="cross")
expanded["global_accepted"] = np.ceil(len(trace_id) * expanded["coverage"]).astype(int)
expanded["retained"] = expanded["rank"].le(expanded["global_accepted"])
expanded["retained_bad"] = expanded["retained"] & expanded["bad2h"]
curve = expanded.groupby(["method", "coverage"], as_index=False).agg(
    n_total=("trace_id", "size"), accepted=("retained", "sum"), bad=("retained_bad", "sum"))
curve["risk"] = curve["bad"] / curve["accepted"]
wide = curve.pivot(index="method", columns="coverage", values="risk").reindex(columns=coverage)
area = pd.Series(np.trapezoid(wide.to_numpy(), x=coverage, axis=1) /
    (coverage[-1] - coverage[0]), index=wide.index, name="aurc_10_100")
curve = curve.merge(area.reset_index(), on="method", validate="many_to_one")
groups = expanded.groupby(["method", "coverage", "culture"], as_index=False).agg(
    culture_n=("trace_id", "size"), global_accepted=("global_accepted", "first"),
    accepted=("retained", "sum"), bad=("retained_bad", "sum"))
groups["risk"] = groups["bad"] / groups["accepted"]
summary = records.groupby("method", as_index=False).agg(
    n=("trace_id", "size"), bad=("bad2h", "sum"), median_error_h=("error_h", "median"))
summary["risk_2h"] = summary["bad"] / summary["n"]
summary = summary.merge(area.reset_index(), on="method", validate="one_to_one")
half = curve.loc[curve["coverage"].eq(.5), ["method", "accepted", "bad"]].rename(
    columns={"accepted": "half_accepted", "bad": "half_bad"})
summary = summary.merge(half, on="method", validate="one_to_one")
records.to_csv(out.with_suffix(".csv"), index=False, encoding="utf-8", lineterminator="\n")
summary.to_csv(out.with_name(out.name + "_summary.csv"), index=False, encoding="utf-8", lineterminator="\n")
curve.to_csv(out.with_name(out.name + "_curve.csv"), index=False, encoding="utf-8", lineterminator="\n")
groups.to_csv(out.with_name(out.name + "_groups.csv"), index=False, encoding="utf-8", lineterminator="\n")
print("neural_candidate_distance_natural", len(trace_id), flush=True)
print(summary.to_string(index=False), flush=True)
print(groups.loc[groups["coverage"].eq(.5)].to_string(index=False), flush=True)
raise SystemExit(0)
'''
neural_distance_report_stage = r'''
assert args.dataset == "per2"
out = application["paths"]["neural_distance_output"]
saved = np.load(out.with_suffix(".npz"))
official = np.load(application["paths"]["main_scores"])
trace_id = saved["trace_id"]
estimate = saved["estimate"]
confidence = saved["confidence"]
nn_std = saved["nn_std"]
assert np.array_equal(trace_id, official["trace_id"])
''' + neural_distance_stage[neural_distance_stage.index("# Temporal references"):]
exec(compile({"neural-candidate-distance": neural_distance_stage,
    "neural-candidate-distance-report": neural_distance_report_stage}.get(args.stage, ""), __file__, "exec"))

confidence_stage = r'''
decision_path=application["paths"]["decision"]
decision_text=decision_path.read_text(encoding="utf-8")
saved_argv=sys.argv.copy()
sys.argv=[str(decision_path),"event_ownership_marked_event","--stage",args.dataset]
decision_scope={"__file__":str(decision_path)}
stop=decision_text.index('exec(compile({False:"",True:event_external_decision_code}')
exec(compile(decision_text[:stop],str(decision_path),"exec"),decision_scope)
sys.argv=saved_argv
body=decision_scope["event_external_decision_code"]
exec(compile(body[:body.index('selected=raw_score.argmax(-1)')],str(decision_path),"exec"),decision_scope)
official=np.load(application["paths"]["main_scores"])
valid=decision_scope["candidate_valid"]
raw_score=decision_scope["raw_score"]
periods=decision_scope["periods"]
trace_id=decision_scope["trace_id"]
assert np.array_equal(trace_id,official["trace_id"])
assert np.array_equal(valid,official["valid"])
assert np.array_equal(periods[valid],official["periods"][valid])
replay_error=np.max(np.abs(raw_score[valid]-official["raw_scores"][valid]))
assert replay_error<1e-12
selected=raw_score.argmax(-1)
estimate=periods[np.arange(len(trace_id)),selected]
assert np.array_equal(estimate,official["estimate"])
old_confidence=raw_score.max(-1)-np.where(valid,raw_score,0.).sum(-1)/valid.sum(-1)
rival=np.max(np.where(valid&(np.abs(periods-estimate[:,None])>application["risk_tolerance_h"]),raw_score,-np.inf),axis=-1)
summary=np.column_stack([old_confidence,raw_score.max(-1)-rival,
    np.sqrt(np.where(valid,raw_score**2,0.).sum(-1)/valid.sum(-1))])
features=np.column_stack([decision_scope["node_features"][np.arange(len(trace_id)),selected],summary])
confidence_model=load(application["paths"]["confidence_model"])
assert features.shape==(len(trace_id),confidence_model.n_features_in_)
confidence=confidence_model.predict(features)
assert np.isfinite(confidence).all()
assert np.max(np.abs(old_confidence-official["scores"].max(-1)))<1e-12
records=pd.DataFrame({"trace_id":trace_id,"estimate_h":estimate,
    "main144_confidence":old_confidence,"selection_confidence":confidence})
records.to_csv(application["paths"]["confidence_predictions"],index=False,encoding="utf-8")
print(args.dataset+"_selection_confidence",len(records),"raw_score_replay_error",replay_error,
    "periods_unchanged",np.array_equal(estimate,official["estimate"]),flush=True)
raise SystemExit(0)
'''
exec(compile({True:confidence_stage,False:""}[args.stage=="confidence"],__file__,"exec"))

application["background_templates"] = {"optical_coefficients": [-.741, 4.04], "output_stem": "lemna_empirical_background_probe", "covariance_output_stem": "lemna_optical_background_covariance_probe"}

application["natural_hankel"] = {"source": ROOT / "software/sota_adaptive_spectral_probe.py", "output": OUTPUT / "lemna_hankel_phase_structure"}

density_feature_stage = r'''
from scipy.special import logsumexp
# Gaussian coefficients with proper unit precision; integrate the common noise scale.
# Times are the actual acquisition coordinates, including irregular sampling.
density_periods = np.arange(*application["period_bounds_h"], application["density"]["grid_step_h"])
density_periods = np.r_[density_periods, application["period_bounds_h"][1]]
grid_weight = np.ones(len(density_periods))
grid_weight[[0, -1]] = .5
grid_weight /= grid_weight.sum()
count = density_mask.sum(axis=1)
mean_y = np.sum(np.where(density_mask, density_y, 0.), axis=1) / count
centered_y = np.where(density_mask, density_y - mean_y[:, None], 0.)
scale_y = np.sqrt(np.sum(centered_y ** 2, axis=1) / count)
y = centered_y / scale_y[:, None]
start = np.min(np.where(density_mask, density_time, np.inf), axis=1)
span = np.max(np.where(density_mask, density_time, -np.inf), axis=1) - start
tau = np.where(density_mask, density_time - start[:, None], 0.)
base = np.stack([np.ones_like(tau), tau / span[:, None] - .5], axis=-1) * density_mask[..., None]
base /= np.sqrt(np.sum(base ** 2, axis=1) / count[:, None])[:, None]
harmonic_order = np.arange(1, application["density"]["harmonics"] + 1)
harmonic_dimension = 2 * len(harmonic_order)
angle = 2. * np.pi * tau[:, None, None] * harmonic_order[None, None, :, None] / density_periods[None, :, None, None]
# A common sine/cosine scale preserves phase invariance; 1/h gives a finite smoothness prior.
harmonic = np.stack([np.cos(angle), np.sin(angle)], axis=3)
harmonic *= density_mask[:, None, None, None] * np.sqrt(2.) / harmonic_order[None, None, :, None, None]
harmonic_flat = harmonic.reshape(len(y), len(density_periods) * harmonic_dimension, -1)
del angle
precision = application["density"]["coefficient_precision"]
base_gram = np.einsum("nti,ntj->nij", base, base) + precision * np.eye(2)
base_rhs = np.einsum("nti,nt->ni", base, y)
base_inv = np.linalg.inv(base_gram)
base_coef = np.einsum("nij,nj->ni", base_inv, base_rhs)
cross_base = (harmonic_flat @ base).reshape(len(y), len(density_periods), harmonic_dimension, 2)
rhs = (harmonic_flat @ y[..., None]).reshape(len(y), len(density_periods), harmonic_dimension) - np.einsum("npij,nj->npi", cross_base, base_coef)
gram = (harmonic_flat @ harmonic_flat.transpose(0, 2, 1)).reshape(len(y), len(density_periods), harmonic_dimension, len(density_periods), harmonic_dimension).transpose(0, 1, 3, 2, 4)
grid_index = np.arange(len(density_periods))
unprojected_gram = gram[:, grid_index, grid_index].copy()
del harmonic_flat, harmonic
gram -= np.einsum("npia,nab,nqjb->npqij", cross_base, base_inv, cross_base, optimize=True)
single_gram = gram[:, grid_index, grid_index] + precision * np.eye(harmonic_dimension)
single_inv = np.linalg.inv(single_gram)
single_coef = np.einsum("npij,npj->npi", single_inv, rhs)
base_rss = np.sum(y ** 2, axis=1) - np.einsum("ni,ni->n", base_rhs, base_coef)
single_rss = base_rss[:, None] - np.einsum("npi,npi->np", rhs, single_coef)
schur_map = single_inv[:, :, None] @ gram
schur = single_gram[:, None] - gram.swapaxes(-1, -2) @ schur_map
remaining_rhs = rhs[:, None] - (gram.swapaxes(-1, -2) @ single_coef[:, :, None, :, None])[..., 0]
background_coef = np.linalg.solve(schur, remaining_rhs[..., None])[..., 0]
target_coef = single_coef[:, :, None] - np.einsum("npqij,npqj->npqi", schur_map, background_coef, optimize=True)
double_rss = single_rss[:, :, None] - np.einsum("npqi,npqi->npq", remaining_rhs, background_coef)
single_sign, single_logdet = np.linalg.slogdet(single_gram)
double_sign, double_logdet = np.linalg.slogdet(schur)
assert np.all(single_sign == 1) and np.all(double_sign == 1)
assert np.all(single_rss > 0.) and np.all(double_rss > 0.)
single_log_evidence = -.5 * single_logdet - count[:, None] / 2. * np.log(single_rss) + harmonic_dimension / 2. * np.log(precision)
pair_log_evidence = -.5 * (single_logdet[:, :, None] + double_logdet) - count[:, None, None] / 2. * np.log(double_rss) + harmonic_dimension * np.log(precision)
del gram, schur_map, schur, remaining_rhs
# Model exchange is exact: neither source is designated background by peak strength.
assert np.max(np.abs(pair_log_evidence - pair_log_evidence.transpose(0, 2, 1))) < 1e-7
double_log_evidence = logsumexp(pair_log_evidence + np.log(grid_weight)[None, None], axis=2)
conditional_log_mass = pair_log_evidence + np.log(grid_weight)[None, None] - double_log_evidence[..., None]
conditional_mass = np.exp(conditional_log_mass)
background_entropy = -np.sum(conditional_mass * conditional_log_mass, axis=2) / np.log(len(density_periods))
target_energy = np.einsum("npqi,npij,npqj->npq", target_coef, unprojected_gram, target_coef, optimize=True)
background_energy = np.einsum("npqi,nqij,npqj->npq", background_coef, unprojected_gram, background_coef, optimize=True)
energy_share = np.sum(conditional_mass * target_energy / (target_energy + background_energy), axis=2)
single_log_mass = single_log_evidence + np.log(grid_weight)[None]
single_log_mass -= logsumexp(single_log_mass, axis=1)[:, None]
double_log_mass = double_log_evidence + np.log(grid_weight)[None]
double_log_mass -= logsumexp(double_log_mass, axis=1)[:, None]
density_features = np.stack([single_log_mass, double_log_mass, double_log_evidence - single_log_evidence,
    background_entropy, energy_share], axis=-1)
assert np.isfinite(density_features).all()
'''

correlated_density_feature_stage = r'''
assert application["density"]["harmonics"] == 1
# Pack valid observations in time order; missing samples do not break the OU chain.
observed_order = np.argsort(~density_mask, axis=1, kind="stable")
density_y = np.take_along_axis(density_y, observed_order, axis=1)
density_time = np.take_along_axis(density_time, observed_order, axis=1)
density_mask = np.take_along_axis(density_mask, observed_order, axis=1)
''' + density_feature_stage[:density_feature_stage.index("harmonic_order = ")] + r'''
# A white-noise atom plus a log-uniform correlation-time prior on the resolved range.
quad_node, quad_weight = np.polynomial.legendre.leggauss(application["density"]["correlation_quadrature"])
edge_mask = density_mask[:, 1:] & density_mask[:, :-1]
gap = np.where(edge_mask, np.diff(tau, axis=1), 1.)
assert np.all(gap[edge_mask] > 0.)
resolved_interval = np.min(np.where(edge_mask, gap, np.inf), axis=1)
log_lo, log_hi = np.log(resolved_interval), np.log(span)
correlation_time = np.exp((log_lo + log_hi)[:, None] / 2. + (log_hi - log_lo)[:, None] / 2. * quad_node[None])
correlation_time = np.column_stack([np.ones(len(y)), correlation_time])
white_mass = application["density"]["white_background_mass"]
noise_weight = np.r_[white_mass, (1. - white_mass) * quad_weight / 2.]
correlated = (np.arange(len(noise_weight)) > 0)[None, :, None] & edge_mask[:, None]
rho = np.where(correlated, np.exp(-gap[:, None] / correlation_time[:, :, None]), 0.)
innovation_variance = np.where(correlated, -np.expm1(-2. * gap[:, None] / correlation_time[:, :, None]), 1.)
noise_logdet = np.log(innovation_variance).sum(axis=-1)
# Exact tridiagonal precision of exp(-|t_i-t_j|/tau), including the initial state.
precision_diagonal = np.zeros((len(y), len(noise_weight), y.shape[1]))
precision_diagonal[:, :, 0] = 1.
precision_diagonal[:, :, 1:] = edge_mask[:, None] / innovation_variance
precision_diagonal[:, :, :-1] += rho ** 2 / innovation_variance
precision_offdiagonal = -rho / innovation_variance
precision_y = precision_diagonal * y[:, None]
precision_y[:, :, 1:] += precision_offdiagonal * y[:, None, :-1]
precision_y[:, :, :-1] += precision_offdiagonal * y[:, None, 1:]
precision_base = precision_diagonal[..., None] * base[:, None]
precision_base[:, :, 1:] += precision_offdiagonal[..., None] * base[:, None, :-1]
precision_base[:, :, :-1] += precision_offdiagonal[..., None] * base[:, None, 1:]
base_gram = np.einsum("nti,nrtj->nrij", base, precision_base, optimize=True)
base_rhs = np.einsum("nti,nrt->nri", base, precision_y, optimize=True)
signal_quadratic = np.sum(y[:, None] * precision_y, axis=-1)
angle = 2. * np.pi * tau[:, None] / density_periods[None, :, None]
cos_value = np.sqrt(2.) * np.cos(angle) * density_mask[:, None]
sin_value = np.sqrt(2.) * np.sin(angle) * density_mask[:, None]
del angle, rho, innovation_variance
gram = np.empty((len(y), len(noise_weight), len(density_periods), 4, 4))
gram[..., :2, :2] = base_gram[:, :, None]
# Contract the shared record axis directly, avoiding repeated small BLAS thread launches.
cos_base = np.einsum("nrti,npt->nrpi", precision_base, cos_value, optimize=False)
sin_base = np.einsum("nrti,npt->nrpi", precision_base, sin_value, optimize=False)
gram[..., :2, 2], gram[..., 2, :2] = cos_base, cos_base
gram[..., :2, 3], gram[..., 3, :2] = sin_base, sin_base
gram[..., 2, 2] = np.einsum("nrt,npt->nrp", precision_diagonal, cos_value ** 2, optimize=False) + 2. * np.einsum(
    "nrt,npt->nrp", precision_offdiagonal, cos_value[:, :, 1:] * cos_value[:, :, :-1], optimize=False)
gram[..., 3, 3] = np.einsum("nrt,npt->nrp", precision_diagonal, sin_value ** 2, optimize=False) + 2. * np.einsum(
    "nrt,npt->nrp", precision_offdiagonal, sin_value[:, :, 1:] * sin_value[:, :, :-1], optimize=False)
gram[..., 2, 3] = np.einsum("nrt,npt->nrp", precision_diagonal, cos_value * sin_value, optimize=False) + np.einsum(
    "nrt,npt->nrp", precision_offdiagonal, cos_value[:, :, 1:] * sin_value[:, :, :-1] + sin_value[:, :, 1:] * cos_value[:, :, :-1], optimize=False)
gram[..., 3, 2] = gram[..., 2, 3]
rhs = np.empty(gram.shape[:-1])
rhs[..., :2] = base_rhs[:, :, None]
rhs[..., 2] = np.einsum("nrt,npt->nrp", precision_y, cos_value, optimize=False)
rhs[..., 3] = np.einsum("nrt,npt->nrp", precision_y, sin_value, optimize=False)
del cos_value, sin_value, precision_y, precision_base, precision_diagonal, precision_offdiagonal, cos_base, sin_base
coefficient_precision = application["density"]["coefficient_precision"]
gram += coefficient_precision * np.eye(4)
base_gram += coefficient_precision * np.eye(2)
base_coef = np.linalg.solve(base_gram, base_rhs[..., None])[..., 0]
base_rss = signal_quadratic - np.sum(base_rhs * base_coef, axis=-1)
coef = np.linalg.solve(gram, rhs[..., None])[..., 0]
rss = signal_quadratic[:, :, None] - np.sum(rhs * coef, axis=-1)
sign, logdet = np.linalg.slogdet(gram)
assert np.all(sign == 1.) and np.all(rss > 0.) and np.all(base_rss > 0.)
log_evidence = -.5 * (noise_logdet[:, :, None] + logdet) - count[:, None, None] / 2. * np.log(rss) + 2. * np.log(coefficient_precision)
integrated_log_evidence = logsumexp(log_evidence + np.log(noise_weight)[None, :, None], axis=1)
noise_mass = np.exp(log_evidence + np.log(noise_weight)[None, :, None] - integrated_log_evidence[:, None])
periodic_gain = (base_rss[:, :, None] - rss) / base_rss[:, :, None]
assert periodic_gain.min() > -1e-8 and periodic_gain.max() < 1. + 1e-8
white_log_mass = log_evidence[:, 0] + np.log(grid_weight)[None]
white_log_mass -= logsumexp(white_log_mass, axis=1)[:, None]
correlated_log_mass = integrated_log_evidence + np.log(grid_weight)[None]
correlated_log_mass -= logsumexp(correlated_log_mass, axis=1)[:, None]
correlated_log_bf = integrated_log_evidence - log_evidence[:, 0]
# 1 - Pr(white | y, P): avoid learning roundoff from summing probabilities near one.
correlated_background_mass = -np.expm1(np.minimum(np.log(white_mass) - correlated_log_bf, 0.))
density_features = np.stack([white_log_mass, correlated_log_mass, correlated_log_bf,
    correlated_background_mass, (noise_mass * periodic_gain).sum(axis=1)], axis=-1)
assert np.isfinite(density_features).all()
'''

density_prepare_stage = r'''
domain = args.density_domain
observations = pd.read_parquet(OUTPUT / application["density"]["observations"][domain])
observations = observations.sort_values(["trace_id", "x"], kind="stable")
observations["position"] = observations.groupby("trace_id", sort=False).cumcount()
signal = observations.pivot(index="trace_id", columns="position", values="signal_y")
clock = observations.pivot(index="trace_id", columns="position", values="x").reindex(signal.index)
trace_id = signal.index.to_numpy(dtype=str)
density_y, density_time = signal.to_numpy(), clock.to_numpy()
density_mask = np.isfinite(density_y) & np.isfinite(density_time)
exec(compile({"white": density_feature_stage, "ou": correlated_density_feature_stage}[application["density"]["background"]], __file__, "exec"))
np.savez_compressed(OUTPUT / (application["density"]["prefix"] + "_" + domain + "_features.npz"), trace_id=trace_id,
    periods=density_periods, features=density_features, duration=np.max(np.where(density_mask, density_time, -np.inf), axis=1),
    grid_weight=grid_weight, feature_names=application["density"]["feature_names"][:5], observed_count=count)
print("density_features_complete", domain, density_features.shape, "sample_range", count.min(), count.max(), flush=True)
raise SystemExit(0)
'''

deshape_prepare_stage = r'''
# Generalized-cepstrum evidence adapted from Lin, Su and Wu (2017).
# Use a floating linear-trend spectrum at the actual acquisition times;
# this global-window adaptation is not the paper's local de-shape SST.
domain = args.density_domain
observations = pd.read_parquet(OUTPUT / application["density"]["observations"][domain])
observations = observations.sort_values(["trace_id", "x"], kind="stable")
signal = observations.pivot(index="trace_id", columns="x", values="signal_y")
trace_id = signal.index.to_numpy(dtype=str)
time = signal.columns.to_numpy(dtype=float)
raw_y = signal.to_numpy()
mask = np.isfinite(raw_y)
count = mask.sum(axis=1)
weight = mask.astype(float)
centered = np.where(mask, raw_y - np.nanmean(raw_y, axis=1)[:, None], 0.)
y = centered / np.sqrt(np.sum(centered ** 2, axis=1) / count)[:, None]
start = np.min(np.where(mask, time[None], np.inf), axis=1)
span = np.max(np.where(mask, time[None], -np.inf), axis=1) - start
clock = time / application["density"]["duration_scale_h"]
base_gram = np.empty((len(y), 2, 2))
base_gram[:, 0, 0] = count
base_gram[:, 0, 1] = base_gram[:, 1, 0] = weight @ clock
base_gram[:, 1, 1] = weight @ clock ** 2
base_rhs = np.stack([y.sum(axis=1), y @ clock], axis=-1)
base_inverse = np.linalg.inv(base_gram)
base_coef = np.einsum("nij,nj->ni", base_inverse, base_rhs)
residual = y - (base_coef[:, :1] + base_coef[:, 1:] * clock[None]) * weight
residual_energy = np.sum(residual ** 2, axis=1)
frequency_step = 1. / (application["deshape"]["frequency_oversampling"] * application["density"]["duration_scale_h"])
maximum_frequency = application["deshape"]["maximum_harmonic"] / application["period_bounds_h"][0]
frequency = np.arange(int(np.ceil(maximum_frequency / frequency_step)) + 1) * frequency_step
angle = 2. * np.pi * time[:, None] * frequency[None]
cosine, sine = np.cos(angle), np.sin(angle)
cross = np.stack([np.stack([weight @ cosine, (weight * clock) @ cosine], axis=-1),
    np.stack([weight @ sine, (weight * clock) @ sine], axis=-1)], axis=-2)
gram = np.empty((len(y), len(frequency), 2, 2))
double_cosine = weight @ np.cos(2. * angle)
gram[..., 0, 0] = (count[:, None] + double_cosine) / 2.
gram[..., 1, 1] = (count[:, None] - double_cosine) / 2.
gram[..., 0, 1] = gram[..., 1, 0] = (weight @ np.sin(2. * angle)) / 2.
gram -= np.einsum("nfia,nab,nfjb->nfij", cross, base_inverse, cross, optimize=True)
rhs = np.stack([residual @ cosine, residual @ sine], axis=-1)
eigenvalue, eigenvector = np.linalg.eigh(gram)
projection = np.einsum("nfji,nfj->nfi", eigenvector, rhs)
resolved = eigenvalue > np.finfo(float).eps * len(time) * count[:, None, None]
gain = np.sum(np.divide(projection ** 2, eigenvalue, out=np.zeros_like(projection), where=resolved), axis=-1) / residual_energy[:, None]
assert gain.min() > -1e-8 and gain.max() < 1. + 1e-8
amplitude = np.sqrt(np.clip(gain, 0., 1.))
# Exclude frequencies above each record's median-sampling resolution.
observations["gap"] = observations.groupby("trace_id", sort=False).x.diff()
interval = observations.groupby("trace_id").gap.median().reindex(signal.index).to_numpy()
frequency_valid = (frequency[None] > 0.) & (frequency[None] <= .5 / interval[:, None])
root_spectrum = amplitude ** application["deshape"]["gamma"] * frequency_valid
quadrature = np.ones(len(frequency))
quadrature[[0, -1]] = .5
root_spectrum *= quadrature
period_grid = np.r_[np.arange(*application["period_bounds_h"], application["density"]["grid_step_h"]), application["period_bounds_h"][1]]
cepstrum = root_spectrum @ np.cos(2. * np.pi * frequency[:, None] * period_grid[None]) / root_spectrum.sum(axis=1)[:, None]
frequency_position = 1. / period_grid / frequency_step
left = np.floor(frequency_position).astype(int)
fraction = frequency_position - left
fundamental_amplitude = amplitude[:, left] * (1. - fraction) + amplitude[:, left + 1] * fraction
features = np.stack([cepstrum, fundamental_amplitude * np.maximum(cepstrum, 0.)], axis=-1)
assert np.isfinite(features).all()
np.savez_compressed(OUTPUT / ("deshape_" + domain + "_features.npz"), trace_id=trace_id,
    periods=period_grid, features=features, duration=span, observed_count=count,
    feature_names=application["deshape"]["feature_names"])
print("deshape_features_complete", domain, features.shape, "sample_range", count.min(), count.max(), flush=True)
raise SystemExit(0)
'''
exec(compile({"deshape-prepare": deshape_prepare_stage}.get(args.stage, ""), __file__, "exec"))

multitaper_prepare_stage = r'''
from scipy.interpolate import CubicSpline
from scipy.signal.windows import dpss

# DPSS windows compress each frequency into three complex coefficients.
# Fit real damped sinusoids after the identical sampling/trend projection;
# this retains negative-frequency leakage and the full window covariance.
domain = args.density_domain
observations = pd.read_parquet(OUTPUT / application["density"]["observations"][domain])
signal = observations.pivot(index="trace_id", columns="x", values="signal_y")
trace_id = signal.index.to_numpy(dtype=str)
time = signal.columns.to_numpy(dtype=float)
raw_y = signal.to_numpy()
mask = np.isfinite(raw_y)
weight = mask.astype(float)
count = mask.sum(axis=1)
centered = np.where(mask, raw_y - np.nanmean(raw_y, axis=1)[:, None], 0.)
y = centered / np.sqrt(np.sum(centered ** 2, axis=1) / count)[:, None]
duration = application["density"]["duration_scale_h"]
clock = time / duration
base = np.stack([np.ones(len(time)), clock], axis=-1)
base_gram = np.einsum("nt,ti,tj->nij", weight, base, base, optimize=True)
base_inverse = np.linalg.inv(base_gram)
base_coef = np.einsum("nij,nj->ni", base_inverse, y @ base)
residual = y - (base_coef @ base.T) * weight
settings = application["multitaper"]
# The 0.1-hour grid represents only the smooth tapers, not the observations.
# It matches the finest acquisition interval in the existing controlled data.
taper_time = np.linspace(0., duration, int(round(duration / settings["taper_grid_step_h"])) + 1)
taper = CubicSpline(taper_time, dpss(len(taper_time), settings["time_bandwidth"], settings["tapers"]), axis=1)(time).T
period_grid = np.r_[np.arange(*application["period_bounds_h"], application["density"]["grid_step_h"]), application["period_bounds_h"][1]]
angle = 2. * np.pi * time[:, None] / period_grid[None]
wave = np.stack([np.cos(angle), np.sin(angle)], axis=-1)
compressed_basis = (wave[:, :, :, None] * taper[:, None, None]).reshape(len(time), len(period_grid), -1)
dimensions = compressed_basis.shape[-1]
basis_flat = compressed_basis.reshape(len(time), -1)
z = (residual @ basis_flat).reshape(len(y), len(period_grid), dimensions)
cross = np.stack([(weight @ basis_flat).reshape(z.shape), ((weight * clock) @ basis_flat).reshape(z.shape)], axis=-1)
products = (compressed_basis[..., :, None] * compressed_basis[..., None, :]).reshape(len(time), -1)
covariance = (weight @ products).reshape(len(y), len(period_grid), dimensions, dimensions)
del products
covariance -= np.einsum("npia,nab,npjb->npij", cross, base_inverse, cross, optimize=True)
eigenvalue, eigenvector = np.linalg.eigh(covariance)
resolved = eigenvalue > np.finfo(float).eps * dimensions * eigenvalue[..., -1, None]
inverse_root = np.divide(1., np.sqrt(np.maximum(eigenvalue, 0.)), out=np.zeros_like(eigenvalue), where=resolved)
z_white = np.einsum("npji,npj->npi", eigenvector, z) * inverse_root
total_energy = np.sum(z_white ** 2, axis=-1)
envelope = np.exp(-np.log(2.) * time[:, None] / np.asarray(settings["half_lives_h"])[None])
templates = wave[:, :, None, :] * envelope[:, None, :, None]
template_flat = templates.reshape(len(time), -1)
template_cross = np.stack([(weight @ template_flat).reshape(len(y), len(period_grid), len(settings["half_lives_h"]), 2),
    ((weight * clock) @ template_flat).reshape(len(y), len(period_grid), len(settings["half_lives_h"]), 2)], axis=-1)
products = (compressed_basis[..., None, None] * templates[:, :, None]).reshape(len(time), -1)
response = (weight @ products).reshape(len(y), len(period_grid), dimensions, len(settings["half_lives_h"]), 2)
del products
response -= np.einsum("npia,nab,npdhb->npidh", cross, base_inverse, template_cross, optimize=True)
response_white = np.einsum("npji,npjdh->npidh", eigenvector, response) * inverse_root[..., None, None]
template_gram = np.einsum("npidh,npidj->npdhj", response_white, response_white)
template_rhs = np.einsum("npidh,npi->npdh", response_white, z_white)
template_eigenvalue, template_eigenvector = np.linalg.eigh(template_gram)
template_resolved = template_eigenvalue > np.finfo(float).eps * dimensions * template_eigenvalue[..., -1, None]
template_projection = np.einsum("npdji,npdj->npdi", template_eigenvector, template_rhs)
explained_energy = np.sum(np.divide(template_projection ** 2, template_eigenvalue,
    out=np.zeros_like(template_projection), where=template_resolved), axis=-1)
coherence = explained_energy / total_energy[..., None]
assert np.isfinite(coherence).all() and coherence.min() > -1e-8 and coherence.max() < 1. + 1e-8
coherence = np.clip(coherence, 0., 1.)
features = np.stack([coherence[..., 0], np.max(coherence[..., 1:], axis=-1)], axis=-1)
np.savez_compressed(OUTPUT / ("multitaper_" + domain + "_features.npz"), trace_id=trace_id,
    periods=period_grid, features=features, coherence=coherence, observed_count=count,
    duration=np.max(np.where(mask, time[None], -np.inf), axis=1),
    feature_names=settings["feature_names"], half_lives_h=settings["half_lives_h"])
print("multitaper_features_complete", domain, features.shape, "sample_range", count.min(), count.max(),
    "coherence_range", coherence.min(), coherence.max(), flush=True)
raise SystemExit(0)
'''
exec(compile({"multitaper-prepare": multitaper_prepare_stage}.get(args.stage, ""), __file__, "exec"))

density_natural_setup = r'''
cache = np.load(application["paths"]["lemna_adapt_context"])
trace_id, groups = cache["trace_id"], cache["fold"]
reference = pd.read_csv(application["paths"]["lemna_reference"], encoding="utf-8").set_index("trace_id").loc[trace_id]
truth_all = reference.reference_period_h.to_numpy()
qualified = reference.reference_usable.to_numpy()
folds = groups
query_weight = cache["query_mass"].astype(float)
bank = np.load(OUTPUT / (application["density"]["prefix"] + "_natural_features.npz"))
order = pd.Index(bank["trace_id"]).get_indexer(trace_id)
physics, duration = bank["features"][order], bank["duration"][order]
domain = "natural"
stem_name = application["density"]["natural_stem"]
'''

density_controlled_setup = r'''
reference = np.load(application["paths"]["controlled_reference"])
trace_id, truth_all, groups, folds = reference["trace_id"], reference["truth"], reference["groups"], reference["folds"]
qualified = np.ones(len(trace_id), dtype=bool)
cache = np.load(Path(str(application["paths"]["controlled_context"]).format(fold=0)))
query_weight = np.where(cache["valid"], cache["weight"], 0.).sum(axis=1)
primary = np.load(OUTPUT / (application["density"]["prefix"] + "_primary_features.npz"))
bank = np.load(OUTPUT / (application["density"]["prefix"] + "_cross_features.npz"))
order = pd.Index(np.r_[primary["trace_id"], bank["trace_id"]]).get_indexer(trace_id)
physics = np.concatenate([primary["features"], bank["features"]])[order]
duration = np.r_[primary["duration"], bank["duration"]][order]
domain = "controlled"
stem_name = application["density"]["controlled_stem"]
'''

density_input_stage = r'''
periods, grid_weight = bank["periods"], bank["grid_weight"]
prior_training = groups[:, None] != groups[train][None]
prior_training &= (domain != "natural") | (duration[:, None] == duration[train][None])
assert prior_training.sum(axis=1).min() > 0
label_kernel = np.exp(-np.abs(periods[:, None] - truth_all[train][None]) / application["risk_tolerance_h"])
prior = prior_training @ label_kernel.T
prior *= grid_weight[None]
prior /= prior.sum(axis=1)[:, None]
context = np.stack([np.broadcast_to(periods[None] / periods[-1], prior.shape),
    np.broadcast_to(duration[:, None] / application["density"]["duration_scale_h"], prior.shape), np.log(prior)], axis=-1)
features = np.concatenate([physics, context], axis=-1)
'''

density_predict_core = r'''
from scipy.special import logsumexp
log_mass = np.log(prior) + density_model._raw_predict(features.reshape(-1, features.shape[-1])).reshape(prior.shape)
log_mass -= logsumexp(log_mass, axis=1)[:, None]
mass = np.exp(log_mass)
control_log_mass = np.log(prior) + control_model._raw_predict(context.reshape(-1, context.shape[-1])).reshape(prior.shape)
control_log_mass -= logsumexp(control_log_mass, axis=1)[:, None]
control_mass = np.exp(control_log_mass)
physics_mass = np.exp(physics[..., 1])
all_mass = np.stack([mass, control_mass, physics_mass], axis=-1)
decision_distance = np.abs(periods[:, None] - periods[None])
utility_kernel = {"exp": np.exp(-decision_distance / application["risk_tolerance_h"]),
    "window": (decision_distance <= application["risk_tolerance_h"]).astype(float)}[application["density"].get("decision", "exp")]
score = np.einsum("nkm,pk->npm", all_mass, utility_kernel)
choice = score.argmax(axis=1)
estimate = periods[choice]
success_window = np.abs(periods[None, :, None] - estimate[:, None]) <= application["risk_tolerance_h"]
confidence = (all_mass * success_window).sum(axis=1)
assert np.isfinite(estimate).all() and np.isfinite(confidence).all()
assert np.max(np.abs(all_mass.sum(axis=1) - 1.)) < 1e-10
'''

density_fit_stage = r'''
from sklearn.base import clone
from sklearn._loss.loss import HalfBinomialLoss
from joblib import dump
fold = args.heldout_run
full = args.stage == "density-full"
heldout = (folds == fold) & (not full)
train = qualified & ~heldout
assert full or not np.intersect1d(groups[train], groups[heldout]).size
exec(compile(density_input_stage, __file__, "exec"))
positive_mass = np.maximum(1. - np.abs(periods[None] - truth_all[train, None]) / application["density"]["grid_step_h"], 0.)
assert np.max(np.abs(positive_mass.sum(axis=1) - 1.)) < 1e-10
class_mass = positive_mass + prior[train]
target = positive_mass / class_mass
group_count = pd.Series(groups[train]).value_counts()
balance = np.maximum(pd.Series(groups[train]).map(group_count).to_numpy(), np.median(group_count)) ** application["contrast_probe"]["balance_power"]
train_query_weight = query_weight[train] / balance
train_query_weight *= query_weight[train].sum() / train_query_weight.sum()
weight = train_query_weight[:, None] * class_mass / 2.
density_model = clone(load(application["paths"]["lemna_adapt_model"])).set_params(loss=HalfBinomialLoss())
assert density_model.random_state == 12345 and not density_model.early_stopping
density_model.fit(features[train].reshape(-1, features.shape[-1]), target.ravel(), sample_weight=weight.ravel())
control_fit = 'control_model = clone(density_model)\ncontrol_model.fit(context[train].reshape(-1, context.shape[-1]), target.ravel(), sample_weight=weight.ravel())'
control_stem = {True: "marginal_density_" + domain + "_full", False: {"natural": "lemna_dual_density_loro", "controlled": "event_prior_density_fivefold"}[domain] + "_fold" + str(fold)}[full]
exec(compile({True: control_fit, False: 'control_model = load(OUTPUT / (control_stem + ".joblib"))["control"]'}[
    application["density"]["harmonics"] == 1 and application["density"]["background"] == "white"], __file__, "exec"))
stem = OUTPUT / ({True: application["density"]["prefix"] + "_" + domain + "_full", False: stem_name + "_fold" + str(fold)}[full])
dump({"method": application["density"]["methods"][0], "model": density_model, "control": control_model,
    "training_period_h": truth_all[train], "training_duration_h": duration[train], "training_trace_id": trace_id[train],
    "training_group": groups[train], "domain": domain, "periods": periods, "grid_weight": grid_weight,
    "density_config": application["density"], "utility_scale_h": application["risk_tolerance_h"],
    "period_bounds_h": application["period_bounds_h"], "feature_names": application["density"]["feature_names"]}, stem.with_suffix(".joblib"))
exec(compile({True: 'print("density_full_complete", domain, int(train.sum()), stem, flush=True)\nraise SystemExit(0)', False: ""}[full], __file__, "exec"))
physics, context, features, prior = physics[heldout], context[heldout], features[heldout], prior[heldout]
exec(compile(density_predict_core, __file__, "exec"))
np.savez_compressed(stem.with_suffix(".npz"), trace_id=trace_id[heldout], periods=periods,
    mass=all_mass, scores=score, prior=prior, selected=choice, train_trace_id=trace_id[train],
    training_groups=np.unique(groups[train]), feature_names=application["density"]["feature_names"])
records = pd.DataFrame({"trace_id": np.repeat(trace_id[heldout], 3), "method": np.tile(application["density"]["methods"], heldout.sum()),
    "estimate_h": estimate.ravel(), "confidence": confidence.ravel(), "heldout_fold": fold, "method_status": "ok"})
exec(compile({"natural": 'records["heldout_run"] = np.repeat(reference.run.to_numpy()[heldout], 3)'}.get(domain, ""), __file__, "exec"))
records = records.rename(columns={"controlled": {"method": "kind", "estimate_h": "estimate", "heldout_fold": "fold"}, "natural": {}}[domain])
records.to_csv(stem.with_suffix(".csv"), index=False, encoding="utf-8")
print("density_fold_complete", domain, fold, "training", int(train.sum()), "test", int(heldout.sum()), "features", density_model.n_features_in_, flush=True)
raise SystemExit(0)
'''

density_external_stage = r'''
model_name = {"shift2h": application["density"]["controlled_stem"] + "_fold" + str(args.heldout_run)}.get(args.density_domain, application["density"]["prefix"] + "_controlled_full")
bundle = load(OUTPUT / (model_name + ".joblib"))
bank = np.load(OUTPUT / (application["density"]["prefix"] + "_" + args.density_domain + "_features.npz"))
trace_id, periods, grid_weight = bank["trace_id"], bank["periods"], bank["grid_weight"]
physics, duration = bank["features"], bank["duration"]
exec(compile({"shift2h": density_shift_subset_stage}.get(args.density_domain, ""), __file__, "exec"))
prior = np.exp(-np.abs(periods[:, None] - bundle["training_period_h"][None]) / bundle["utility_scale_h"]).mean(axis=1) * grid_weight
