main_estimate = periods[heldout][test_row, main_selected]
main_confidence = absolute_score[test_row, main_selected]
joint_absolute_confidence = np.take_along_axis(absolute_score, joint_selected, axis=1)

# Refit the H1 and matched-prior strong baselines within the same inner split.
bank = np.load(OUTPUT.parent / "recomputed" / "marginal_density_natural_features.npz")
bank_order = pd.Index(bank["trace_id"]).get_indexer(trace_id)
grid = bank["periods"]
physics = bank["features"][bank_order]
grid_label_kernel = np.exp(-np.abs(grid[:, None] - truth[None]) / application["risk_tolerance_h"])
grid_prior = prior_training @ grid_label_kernel.T
grid_prior *= bank["grid_weight"][None]
grid_prior /= grid_prior.sum(axis=1)[:, None]
grid_context = np.stack([np.broadcast_to(grid[None] / grid[-1], grid_prior.shape),
    np.broadcast_to(duration[:, None] / application["density"]["duration_scale_h"], grid_prior.shape),
    np.log(grid_prior)], axis=-1)
