control_model = clone(density_model)
control_model.fit(grid_context[train].reshape(-1, grid_context.shape[-1]),
    class_target.ravel(), sample_weight=class_weight.ravel())
baseline_logits = np.stack([
    np.log(grid_prior[heldout]) + density_model._raw_predict(
        grid_features[heldout].reshape(-1, grid_features.shape[-1])).reshape(grid_prior[heldout].shape),
    np.log(grid_prior[heldout]) + control_model._raw_predict(
        grid_context[heldout].reshape(-1, grid_context.shape[-1])).reshape(grid_prior[heldout].shape)], axis=-1)
baseline_mass = np.exp(baseline_logits - logsumexp(baseline_logits, axis=1)[:, None])
baseline_window = (np.abs(grid[:, None] - grid[None]) <= application["risk_tolerance_h"]).astype(float)
baseline_score = np.einsum("nkm,pk->npm", baseline_mass, baseline_window)
baseline_selected = baseline_score.argmax(axis=1)
baseline_estimate = grid[baseline_selected]
baseline_confidence = baseline_score.max(axis=1)
