train_features = joint_features[train]
train_mask = valid[train]
train_query_weight = cache["query_mass"][train] / np.maximum(
    group_n[cache["fold"][train]], count_floor) ** application["contrast_probe"]["balance_power"]
objective_weight = train_query_weight / train_query_weight.sum()
ridge = joint_config["ridge"] / train.sum()
density_offset = log_proposal[train]
density_label = positive_mass
density_objective = lambda beta: (
    (logits := np.where(train_mask, np.einsum("nkf,f->nk", train_features, beta) + density_offset, -np.inf)),
    (normalizer := logsumexp(logits, axis=1)),
    (probability := np.exp(logits - normalizer[:, None])),
    (losses := normalizer - np.sum(density_label * np.where(train_mask, logits, 0.), axis=1)),
    (gradients := np.einsum("nk,nkf->nf", probability - density_label, train_features)),
    (objective_weight @ losses + ridge * np.dot(beta, beta) / 2.,
     objective_weight @ gradients + ridge * beta))[-1]
started = time.perf_counter()
fit = minimize(density_objective, np.zeros(forward.shape[-1]), jac=True, method="L-BFGS-B",
    options={"maxiter": joint_config["max_iter"], "ftol": joint_config["ftol"], "gtol": joint_config["gtol"]})
