test_logits = np.where(valid[heldout],
    np.einsum("nkf,f->nk", joint_features[heldout], fit.x) + log_proposal[heldout], -np.inf)
mass = np.exp(test_logits - logsumexp(test_logits, axis=1)[:, None])
decision_window = (np.abs(safe_period[heldout, :, None] - safe_period[heldout, None, :])
    <= application["risk_tolerance_h"]) & valid[heldout, :, None] & valid[heldout, None, :]
score = np.einsum("nkl,nl->nk", decision_window, mass)
score = np.where(valid[heldout], score, -np.inf)
selected = score.argmax(axis=1)
