absolute_stem = application["paths"]["lemna_prior_evidence"]
absolute = np.load(absolute_stem.with_name(absolute_stem.name + "_fold" + str(fold)).with_suffix(".npz"))
assert np.array_equal(absolute["trace_id"], trace_id[heldout])
assert np.array_equal(absolute["periods"][valid[heldout]], periods[heldout][valid[heldout]])
confidence = np.column_stack([score[test_row, selected], absolute["scores"][:, :, 0][test_row, selected]])
stem = application["paths"]["lemna_prior_level_joint"]
stem = stem.with_name(stem.name + "_fold" + str(fold))
dump({"joint_config": joint_config, "contrast_config": contrast_config,
    "imputer": imputer, "scaler": scaler, "beta": fit.x,
    "fit_iterations": fit.nit, "fit_loss": fit.fun, "train_trace_id": trace_id[train]}, stem.with_suffix(".joblib"))
np.savez_compressed(stem.with_suffix(".npz"), trace_id=trace_id[heldout], periods=periods[heldout], valid=valid[heldout],
    mass=mass, scores=score, selected=selected, confidence=confidence, train_trace_id=trace_id[train],
    reference_candidate=reference_candidate[heldout], prior=prior[heldout])
