from scipy.special import logsumexp
saved_stem = OUTPUT / ("lemna_joint_objective_probe_outer" + str(fold) + "_inner" + str(args.inner_fold))
saved = np.load(saved_stem.with_suffix(".npz"))
models = load(saved_stem.with_suffix(".joblib"))
assert np.array_equal(saved["trace_id"], trace_id[heldout])
assert np.array_equal(saved["train_trace_id"], trace_id[train])
test_period = periods[heldout]
test_valid = valid[heldout]
safe = np.where(test_valid, test_period, application["period_bounds_h"][0])
pair_valid = test_valid[:, :, None] & test_valid[:, None, :]
delta = safe[:, None, :] - safe[:, :, None]
previous = np.max(np.where(pair_valid & (delta < 0.), safe[:, None, :], -np.inf), axis=2)
following = np.min(np.where(pair_valid & (delta > 0.), safe[:, None, :], np.inf), axis=2)
left_width = np.where(np.isfinite(previous), (safe - previous) / 2.,
    safe - application["period_bounds_h"][0])
right_width = np.where(np.isfinite(following), (following - safe) / 2.,
    application["period_bounds_h"][1] - safe)
width = left_width + right_width
assert (width[test_valid] > 0.).all()
# Differences preserve tiny cells between near-identical floating-point periods.
relative = safe[:, :, None] - safe[:, None, :]
upper = np.clip((relative + application["risk_tolerance_h"] + left_width[:, None, :]) /
    np.where(test_valid, width, 1.)[:, None, :], 0., 1.)
lower = np.clip((relative - application["risk_tolerance_h"] + left_width[:, None, :]) /
    np.where(test_valid, width, 1.)[:, None, :], 0., 1.)
window_fraction = np.where(pair_valid, upper - lower, 0.)
joint_mass = saved["mass"][:, :, [0, 2]]
score = np.einsum("nkl,nlm->nkm", window_fraction, joint_mass)
score = np.where(test_valid[:, :, None], score, -np.inf)
selected = score.argmax(axis=1)
estimate = np.take_along_axis(test_period, selected, axis=1)
native_confidence = score.max(axis=1)
absolute_score = prior[heldout].copy()
absolute_score[test_valid] += models["absolute"].predict(features[heldout][test_valid])
absolute_confidence = np.take_along_axis(absolute_score, selected, axis=1)

bank = np.load(OUTPUT.parent / "recomputed" / "marginal_density_natural_features.npz")
order = pd.Index(bank["trace_id"]).get_indexer(trace_id)
grid = bank["periods"]
grid_prior = prior_training @ np.exp(-np.abs(grid[:, None] - truth[None]) /
    application["risk_tolerance_h"]).T
grid_prior *= bank["grid_weight"][None]
grid_prior /= grid_prior.sum(axis=1)[:, None]
grid_context = np.stack([np.broadcast_to(grid[None] / grid[-1], grid_prior.shape),
    np.broadcast_to(duration[:, None] / application["density"]["duration_scale_h"], grid_prior.shape),
    np.log(grid_prior)], axis=-1)
grid_features = np.concatenate([bank["features"][order], grid_context], axis=-1)
h1_logit = np.log(grid_prior[heldout]) + models["H1"]._raw_predict(
    grid_features[heldout].reshape(-1, grid_features.shape[-1])).reshape(grid_prior[heldout].shape)
h1_mass = np.exp(h1_logit - logsumexp(h1_logit, axis=1)[:, None])
grid_left = np.r_[0., np.diff(grid) / 2.]
grid_right = np.r_[np.diff(grid) / 2., 0.]
grid_width = grid_left + grid_right
grid_relative = grid[:, None] - grid[None]
grid_fraction = np.clip((grid_relative + application["risk_tolerance_h"] + grid_left[None]) /
    grid_width[None], 0., 1.) - np.clip((grid_relative - application["risk_tolerance_h"] + grid_left[None]) /
    grid_width[None], 0., 1.)
h1_score = h1_mass @ grid_fraction.T
h1_estimate = grid[h1_score.argmax(axis=1)]
h1_confidence = h1_score.max(axis=1)
names = ["joint_continuous_absolute_report", "minimax_continuous_absolute_report",
    "joint_continuous_mass", "minimax_continuous_mass", "H1_continuous_window"]
all_estimate = np.column_stack([estimate, estimate, h1_estimate])
all_confidence = np.column_stack([absolute_confidence, native_confidence, h1_confidence])
predictions = pd.DataFrame({"trace_id": np.repeat(trace_id[heldout], len(names)),
    "method": np.tile(names, heldout.sum()), "estimate_h": all_estimate.ravel(),
    "confidence": all_confidence.ravel(),
    "reference_period_h": np.repeat(reference.reference_period_h.to_numpy()[heldout], len(names)),
    "run": np.repeat(reference.run.to_numpy()[heldout], len(names)), "outer_fold": fold, "inner_fold": args.inner_fold})
predictions["absolute_difference_h"] = np.abs(predictions.estimate_h - predictions.reference_period_h)
predictions["bad2h"] = predictions.absolute_difference_h > application["risk_tolerance_h"]
stem = saved_stem.with_name(saved_stem.name + "_readout")
predictions.to_csv(stem.with_suffix(".csv"), index=False, encoding="utf-8")
ranked = predictions.sort_values(["method", "confidence", "trace_id"], ascending=[True, False, True], kind="stable")
ranked["accepted"] = ranked.groupby("method").cumcount() + 1
ranked["risk"] = ranked.groupby("method").bad2h.cumsum() / ranked.accepted
summary = ranked.groupby("method").agg(n=("trace_id", "size"), bad=("bad2h", "sum"),
    mae=("absolute_difference_h", "mean"), aurc=("risk", "mean"))
print("joint_readout_probe_complete", fold, args.inner_fold, summary.to_string(), flush=True)
raise SystemExit(0)
