from scipy.optimize import minimize
from scipy.special import logsumexp
from sklearn.impute import SimpleImputer
from sklearn.preprocessing import StandardScaler, SplineTransformer
import time

mode = args.joint_representation
representation_config = {"mode": mode, "ridge": application["contrast_probe"]["gate_ridge"],
    "n_knots": 3, "degree": 2, "knots": "uniform", "extrapolation": "linear",
    "max_iter": 500, "ftol": 1e-10, "gtol": 1e-6}
exec(compile(level_distribution_learning_stage.split("query_weight =", 1)[0], __file__, "exec"))
# Node potentials preserve candidate evidence before reference subtraction.
node_features = np.concatenate([cache["features"], level_bank["features"], periods[..., None],
    np.log(np.where(valid, prior, 1.))[..., None], cache["anchor"][..., None]], axis=-1)
represented = {"anchor_spline": forward, "node_linear": node_features, "node_spline": node_features}[mode]
assert not np.isinf(represented[valid]).any()
imputer = SimpleImputer(strategy="median", keep_empty_features=True)
train_imputed = imputer.fit_transform(represented[train_valid])
input_scaler = StandardScaler().fit(train_imputed, sample_weight=weight)
active = input_scaler.var_ > 0.
train_standard = input_scaler.transform(train_imputed)[:, active]
transformer = {"node_linear": StandardScaler(with_mean=False, with_std=False),
    "node_spline": SplineTransformer(n_knots=representation_config["n_knots"], degree=representation_config["degree"],
        knots=representation_config["knots"], extrapolation=representation_config["extrapolation"], include_bias=False),
    "anchor_spline": SplineTransformer(n_knots=representation_config["n_knots"], degree=representation_config["degree"],
        knots=representation_config["knots"], extrapolation=representation_config["extrapolation"], include_bias=False)}[mode]
train_basis = transformer.fit_transform(train_standard)
basis_scaler = StandardScaler().fit(train_basis, sample_weight=weight)
safe_train = np.where(valid[train, :, None], represented[train], np.nan).reshape(-1, represented.shape[-1])
safe_test = np.where(valid[heldout, :, None], represented[heldout], np.nan).reshape(-1, represented.shape[-1])
train_design = basis_scaler.transform(transformer.transform(
    input_scaler.transform(imputer.transform(safe_train))[:, active])).reshape(train.sum(), valid.shape[1], -1)
test_design = basis_scaler.transform(transformer.transform(
    input_scaler.transform(imputer.transform(safe_test))[:, active])).reshape(heldout.sum(), valid.shape[1], -1)
assert np.isfinite(train_design).all() and np.isfinite(test_design).all()
train_query_weight = cache["query_mass"][train] / np.maximum(
    group_n[cache["fold"][train]], count_floor) ** application["contrast_probe"]["balance_power"]
objective_weight = train_query_weight / train_query_weight.sum()
ridge = representation_config["ridge"] / train.sum()
train_mask = valid[train]
density_objective = lambda beta: (
    (logits := np.where(train_mask, np.einsum("nkf,f->nk", train_design, beta) + log_proposal[train], -np.inf)),
    (normalizer := logsumexp(logits, axis=1)),
    (probability := np.exp(logits - normalizer[:, None])),
    (losses := normalizer - np.sum(positive_mass * np.where(train_mask, logits, 0.), axis=1)),
    (gradients := np.einsum("nk,nkf->nf", probability - positive_mass, train_design)),
    (objective_weight @ losses + ridge * np.dot(beta, beta) / 2.,
     objective_weight @ gradients + ridge * beta))[-1]
started = time.perf_counter()
fit = minimize(density_objective, np.zeros(train_design.shape[-1]), jac=True, method="L-BFGS-B",
    options={"maxiter": representation_config["max_iter"], "ftol": representation_config["ftol"],
             "gtol": representation_config["gtol"]})
print("representation_optimization", mode, args.inner_fold, fit.success, fit.nit,
    fit.fun, str(fit.message), "seconds", time.perf_counter() - started, flush=True)
assert fit.success
test_logits = np.where(valid[heldout],
    np.einsum("nkf,f->nk", test_design, fit.x) + log_proposal[heldout], -np.inf)
mass = np.exp(test_logits - logsumexp(test_logits, axis=1)[:, None])
window = (np.abs(safe_period[heldout, :, None] - safe_period[heldout, None, :])
    <= application["risk_tolerance_h"]) & valid[heldout, :, None] & valid[heldout, None, :]
