# Posterior mean harmonic coefficients use the existing isotropic coefficient
# prior and actual acquisition times. Retain phase relations before pooling.
harmonic_scale = np.sqrt(2.) / harmonic_order
single_complex = (single_coef[..., 0::2] - 1j * single_coef[..., 1::2]) * harmonic_scale
target_complex = (target_coef[..., 0::2] - 1j * target_coef[..., 1::2]) * harmonic_scale
single_112 = single_complex[..., 0] ** 2 * np.conj(single_complex[..., 1])
single_123 = single_complex[..., 0] * single_complex[..., 1] * np.conj(single_complex[..., 2])
target_112 = target_complex[..., 0] ** 2 * np.conj(target_complex[..., 1])
target_123 = target_complex[..., 0] * target_complex[..., 1] * np.conj(target_complex[..., 2])
single_features = np.concatenate([np.abs(single_complex) ** 2,
    np.stack([single_112.real, single_112.imag, single_123.real, single_123.imag], axis=-1)], axis=-1)
target_features = np.concatenate([np.abs(target_complex) ** 2,
    np.stack([target_112.real, target_112.imag, target_123.real, target_123.imag], axis=-1)], axis=-1)
conditional_features = np.einsum("npq,npqf->npf", conditional_mass, target_features)
names = ["harmonic_1_energy", "harmonic_2_energy", "harmonic_3_energy",
    "coupling_112_real", "coupling_112_imag", "coupling_123_real", "coupling_123_imag"]
assert np.isfinite(single_features).all() and np.isfinite(conditional_features).all()
assert np.max(np.abs(conditional_mass.sum(axis=2) - 1.)) < 1e-10
phase_rotation = np.exp(-2j * np.pi * application["density"]["grid_step_h"] *
    harmonic_order[None] / density_periods[:, None])
rotated = single_complex * phase_rotation[None]
assert np.max(np.abs(rotated[..., 0] ** 2 * np.conj(rotated[..., 1]) - single_112)) < 1e-10
assert np.max(np.abs(rotated[..., 0] * rotated[..., 1] * np.conj(rotated[..., 2]) - single_123)) < 1e-10
stem = OUTPUT / ("harmonic_coupling_" + domain + "_features.npz")
np.savez_compressed(stem, trace_id=trace_id, periods=density_periods,
    single=single_features, conditional=conditional_features, feature_names=names,
    duration=np.max(np.where(density_mask, density_time, -np.inf), axis=1), observed_count=count,
    harmonics=harmonic_order, coefficient_precision=precision)
print("harmonic_coupling_features_complete", len(trace_id), density_periods.shape,
    single_features.shape, conditional_features.shape, "count_range", count.min(), count.max(),
    "single_range", np.column_stack([single_features.min(axis=(0,1)),single_features.max(axis=(0,1))]).tolist(),
    "conditional_range", np.column_stack([conditional_features.min(axis=(0,1)),conditional_features.max(axis=(0,1))]).tolist(),
    flush=True)
raise SystemExit(0)
