confidence = score.max(axis=1)
train_logit = np.log(grid_prior[train]) + model._raw_predict(
    features[train].reshape(-1, features.shape[-1])).reshape(grid_prior[train].shape)
train_mass = np.exp(train_logit - logsumexp(train_logit, axis=1)[:, None])
