records["bad2h"] = records.absolute_error_h > application["risk_tolerance_h"]
stem = OUTPUT / ("event_harmonic_amplitude_fivefold_fold" + str(fold))
records.to_csv(stem.with_suffix(".csv"), index=False, encoding="utf-8")
np.savez_compressed(stem.with_suffix(".npz"), trace_id=trace_id[heldout], periods=periods,
    mass=mass, scores=score, selected=selected, train_trace_id=trace_id[train],
    training_groups=np.unique(groups[train]), train_estimate=train_estimate, train_truth=truth_all[train])
dump({"model": model, "coupling_config": {"mode": "amplitude", "harmonics": 3,
    "training_loss": "existing_H1_density_ratio"}, "periods": periods, "grid_weight": grid_weight,
    "training_trace_id": trace_id[train], "training_period_h": truth_all[train],
    "training_duration_h": duration[train], "training_group": groups[train]}, stem.with_suffix(".joblib"))
ranked = records.sort_values(["confidence", "trace_id"], ascending=[False, True], kind="stable")
risk = ranked.bad2h.cumsum().to_numpy() / np.arange(1, len(ranked) + 1)
