marked_density_prepare_stage = r'''
assert args.density_domain == "natural" and application["density"]["harmonics"] == 1
observations = pd.read_parquet(application["paths"]["observations"])
source_bank = np.load(OUTPUT / "native_local_startup_residual_source_lemna_dual_features_20261004.npz")
clock_bank = np.load(application["paths"]["context"])
trace_id = source_bank["trace_id"]
clock_order = pd.Index(clock_bank["trace_id"]).get_indexer(trace_id)
assert (clock_order >= 0).all()
signal = observations.pivot(index="trace_id", columns="x", values="signal_y").reindex(trace_id)
raw = signal.to_numpy()
time = signal.columns.to_numpy(dtype=float)
mask = np.isfinite(raw)
positions = np.searchsorted(clock_bank["time"], time)
assert np.array_equal(clock_bank["time"][positions], time)
source_weight = source_bank["residual_source_mask"][:, positions]
assert source_weight.shape == raw.shape and ((source_weight >= 0.) & (source_weight <= 1.)).all()
indices = np.arange(raw.shape[1])
previous = np.maximum.accumulate(np.where(mask, indices[None], -1), axis=1)
left = np.maximum(np.c_[np.full(len(raw), -1), previous[:, :-1]], 0)
row = np.arange(len(raw))[:, None]
pair_valid = mask & (left < indices[None]) & mask[row, left]
npoints = mask.sum(axis=1)
level_mean = np.sum(np.where(mask, raw, 0.), axis=1) / npoints
level_scale = np.sqrt(np.sum(np.where(mask, raw - level_mean[:, None], 0.) ** 2, axis=1) / npoints)
level = np.where(mask, (raw - level_mean[:, None]) / level_scale[:, None], 0.)
difference = (level - level[row, left]) * pair_valid
span = np.max(np.where(mask, time, -np.inf), axis=1) - np.min(np.where(mask, time, np.inf), axis=1)
# The learned mark is a residual increment-energy fraction. It only weights
# the same increment; it is never interpreted as a pointwise brightness share.
raw_weight = np.stack([pair_valid.astype(float), pair_valid * source_weight])
pair_count = pair_valid.sum(axis=1)
weight = raw_weight * pair_count[None, :, None] / raw_weight.sum(axis=2)[:, :, None]
root_weight = np.sqrt(weight)
density_periods = np.r_[np.arange(*application["period_bounds_h"], application["density"]["grid_step_h"]),
    application["period_bounds_h"][1]]
grid_weight = np.ones(len(density_periods))
grid_weight[[0, -1]] = .5
grid_weight /= grid_weight.sum()
angle = 2. * np.pi * time[None] / density_periods[:, None]
level_harmonic = np.stack([np.cos(angle), np.sin(angle)], axis=1) * np.sqrt(2.)
increment_harmonic = level_harmonic[None] - level_harmonic[:, :, left].transpose(2, 0, 1, 3)
harmonic_flat = (increment_harmonic[None] * root_weight[:, :, None, None]).reshape(
    len(raw_weight) * len(raw), len(density_periods) * 2, len(time))
y = (difference[None] * root_weight).reshape(len(raw_weight) * len(raw), len(time))
# An intercept vanishes under differencing; keep only the transformed linear trend.
trend = (time[None] - time[left]) / span[:, None] * np.sqrt(12.)
base = (trend[None] * root_weight).reshape(len(raw_weight) * len(raw), len(time), 1)
count = np.tile(pair_count, len(raw_weight))
harmonic_dimension = 2
from scipy.special import logsumexp
precision = application["density"]["coefficient_precision"]
base_gram = np.einsum("nti,ntj->nij", base, base) + precision * np.eye(base.shape[-1])
base_rhs = np.einsum("nti,nt->ni", base, y)
base_inv = np.linalg.inv(base_gram)
base_coef = np.einsum("nij,nj->ni", base_inv, base_rhs)
cross_base = (harmonic_flat @ base).reshape(len(y), len(density_periods), harmonic_dimension, base.shape[-1])
rhs = (harmonic_flat @ y[..., None]).reshape(len(y), len(density_periods), harmonic_dimension) - np.einsum("npij,nj->npi", cross_base, base_coef)
gram = (harmonic_flat @ harmonic_flat.transpose(0, 2, 1)).reshape(len(y), len(density_periods), harmonic_dimension, len(density_periods), harmonic_dimension).transpose(0, 1, 3, 2, 4)
grid_index = np.arange(len(density_periods))
unprojected_gram = gram[:, grid_index, grid_index].copy()
del harmonic_flat
gram -= np.einsum("npia,nab,nqjb->npqij", cross_base, base_inv, cross_base, optimize=True)
single_gram = gram[:, grid_index, grid_index] + precision * np.eye(harmonic_dimension)
single_inv = np.linalg.inv(single_gram)
single_coef = np.einsum("npij,npj->npi", single_inv, rhs)
base_rss = np.sum(y ** 2, axis=1) - np.einsum("ni,ni->n", base_rhs, base_coef)
single_rss = base_rss[:, None] - np.einsum("npi,npi->np", rhs, single_coef)
schur_map = single_inv[:, :, None] @ gram
schur = single_gram[:, None] - gram.swapaxes(-1, -2) @ schur_map
remaining_rhs = rhs[:, None] - (gram.swapaxes(-1, -2) @ single_coef[:, :, None, :, None])[..., 0]
background_coef = np.linalg.solve(schur, remaining_rhs[..., None])[..., 0]
target_coef = single_coef[:, :, None] - np.einsum("npqij,npqj->npqi", schur_map, background_coef, optimize=True)
double_rss = single_rss[:, :, None] - np.einsum("npqi,npqi->npq", remaining_rhs, background_coef)
single_sign, single_logdet = np.linalg.slogdet(single_gram)
double_sign, double_logdet = np.linalg.slogdet(schur)
assert np.all(single_sign == 1) and np.all(double_sign == 1)
assert np.all(single_rss > 0.) and np.all(double_rss > 0.)
single_log_evidence = -.5 * single_logdet - count[:, None] / 2. * np.log(single_rss) + harmonic_dimension / 2. * np.log(precision)
pair_log_evidence = -.5 * (single_logdet[:, :, None] + double_logdet) - count[:, None, None] / 2. * np.log(double_rss) + harmonic_dimension * np.log(precision)
del gram, schur_map, schur, remaining_rhs
# Model exchange is exact: neither source is designated background by peak strength.
assert np.max(np.abs(pair_log_evidence - pair_log_evidence.transpose(0, 2, 1))) < 1e-7
double_log_evidence = logsumexp(pair_log_evidence + np.log(grid_weight)[None, None], axis=2)
conditional_log_mass = pair_log_evidence + np.log(grid_weight)[None, None] - double_log_evidence[..., None]
conditional_mass = np.exp(conditional_log_mass)
background_entropy = -np.sum(conditional_mass * conditional_log_mass, axis=2) / np.log(len(density_periods))
target_energy = np.einsum("npqi,npij,npqj->npq", target_coef, unprojected_gram, target_coef, optimize=True)
background_energy = np.einsum("npqi,nqij,npqj->npq", background_coef, unprojected_gram, background_coef, optimize=True)
energy_share = np.sum(conditional_mass * target_energy / (target_energy + background_energy), axis=2)
single_log_mass = single_log_evidence + np.log(grid_weight)[None]
single_log_mass -= logsumexp(single_log_mass, axis=1)[:, None]
double_log_mass = double_log_evidence + np.log(grid_weight)[None]
double_log_mass -= logsumexp(double_log_mass, axis=1)[:, None]
density_features = np.stack([single_log_mass, double_log_mass, double_log_evidence - single_log_evidence,
    background_entropy, energy_share], axis=-1)
assert np.isfinite(density_features).all()
representation_features = density_features.reshape(len(raw_weight), len(raw), len(density_periods), -1)
assert np.isfinite(representation_features).all()
stem = OUTPUT / "marked_increment_natural_features.npz"
np.savez_compressed(stem, trace_id=trace_id, periods=density_periods, grid_weight=grid_weight,
    unweighted=representation_features[0], source=representation_features[1], duration=span,
    observed_count=npoints, interval_count=pair_count, source_weight_mean=source_weight.sum(axis=1) / pair_count,
    feature_names=application["density"]["feature_names"][:5])
print("marked_increment_features_complete", representation_features.shape,
    "observations", np.unique(npoints, return_counts=True), "source_weights", np.quantile(source_weight[mask], [0,.5,1]), flush=True)
raise SystemExit(0)
'''
