raw=observations.pivot(index="trace_id",columns="time_h",values="no").reindex(ids)
background_y=-.741*observations.green+4.04*observations.red
background=observations.assign(background_y=background_y).pivot(index="trace_id",columns="time_h",values="background_y").reindex(index=ids,columns=raw.columns)
time=raw.columns.to_numpy(float)
mask=np.isfinite(raw.to_numpy())
count=mask.sum(axis=1)
center=time[None,:]-np.sum(mask*time,axis=1)[:,None]/count[:,None]
center=np.where(mask,center,0.)
base=np.stack([mask/np.sqrt(count[:,None]),center/np.sqrt(np.sum(center**2,axis=1))[:,None]],axis=-1)
y=np.where(mask,raw.to_numpy(),0.)
y-=np.einsum("nti,ni->nt",base,np.einsum("nti,nt->ni",base,y))
y/=np.linalg.norm(y,axis=1)[:,None]
b=np.where(mask,background.to_numpy(),0.)
b-=np.einsum("nti,ni->nt",base,np.einsum("nti,nt->ni",base,b))
b=np.divide(b,np.linalg.norm(b,axis=1)[:,None],out=np.zeros_like(b),where=np.linalg.norm(b,axis=1)[:,None]>0)
background_reference=pd.read_csv(OUTPUT/"lemna_dual_background_reference.csv",encoding="utf-8").set_index("trace_id").loc[ids]
known_period=background_reference.background_period_h.to_numpy()
finite_period=np.isfinite(known_period)
safe_period=np.where(finite_period,known_period,application["period_bounds_h"][0])
angle=2.*np.pi*time[None,:]/safe_period[:,None]
period_design=np.stack([np.cos(angle),np.sin(angle)],axis=-1)*mask[...,None]
period_design-=np.einsum("nti,nik->ntk",base,np.einsum("nti,ntk->nik",base,period_design))
waveform_design=np.stack([b,np.zeros_like(b)],axis=-1)
nuisance=np.stack([waveform_design,period_design],axis=1)
uq,sq,vq=np.linalg.svd(nuisance,full_matrices=False)
active_q=sq>np.finfo(float).eps*len(time)*np.sqrt(np.sum(nuisance**2,axis=(-2,-1)))[...,None]
q=uq*active_q[:,:,None,:]
remaining_y=y[:,None,:]-np.einsum("nmti,nmi->nmt",q,np.einsum("nmti,nt->nmi",q,y))
safe_candidates=np.where(valid,periods,application["period_bounds_h"][0])
candidate_angle=2.*np.pi*time[None,None,:]/safe_candidates[:,:,None]
candidate=np.stack([np.cos(candidate_angle),np.sin(candidate_angle)],axis=-1)*mask[:,None,:,None]
candidate-=np.einsum("nti,nkij->nktj",base,np.einsum("nti,nktj->nkij",base,candidate))
remaining_design=candidate[:,None]-np.einsum("nmti,nmkij->nmktj",q,np.einsum("nmti,nktj->nmkij",q,candidate))
u,s,v=np.linalg.svd(remaining_design,full_matrices=False)
norm=np.sqrt(np.sum(candidate**2,axis=(-2,-1)))
active=s>np.finfo(float).eps*len(time)*norm[:,None,:,None]
projection=np.einsum("nmkti,nmt->nmki",u,remaining_y)
gain=np.sum(projection**2*active,axis=-1)/np.sum(remaining_y**2,axis=-1)[:,:,None]
gain=np.where(valid[:,None,:],gain,-np.inf)
selected=gain.argmax(axis=2)
estimate=np.take_along_axis(periods,selected,axis=1)
estimate[:,1]=np.where(finite_period,estimate[:,1],np.nan)
truth=reference.reference_period_h.to_numpy()[train]
