exec(compile({'source-role-probe-fit': source_role_probe_fit_stage}.get(args.stage, ''), __file__, 'exec'))


background_covariance_probe_fit_stage = (
    joint_objective_probe_fit_stage.split('from scipy.optimize import minimize', 1)[0]
    + source_strength_probe_fit_stage[source_strength_probe_fit_stage.index('group_count ='):
        source_strength_probe_fit_stage.index('mixed_energy =')]
    + r'''

from scipy.special import logsumexp
from sklearn.covariance import ledoit_wolf
# Estimate a zero-mean background second-moment kernel from training residuals.
# Match acquisition duration and exclude the query's entire experiment.
count = density_mask.sum(axis=1)
time = signal.columns.to_numpy(float)
assert np.array_equal(density_mask, np.arange(len(time))[None] < count[:, None])
centered_time = np.where(density_mask, density_time -
    np.sum(density_mask * density_time, axis=1)[:, None] / count[:, None], 0.)
base = np.stack([density_mask / np.sqrt(count[:, None]),
    centered_time / np.sqrt(np.sum(centered_time ** 2, axis=1))[:, None]], axis=-1)
mixed_y = np.where(density_mask, density_y, 0.)
mixed_y -= np.einsum("nti,ni->nt", base, np.einsum("nti,nt->ni", base, mixed_y))
scale = np.sqrt(np.sum(mixed_y ** 2, axis=1) / count)
mixed_y /= scale[:, None]
assert np.max(np.abs(mixed_y[train] - waves[:, 0] / scale[train, None])) < 1e-10
background_training = (waves[:, 0] - waves[:, 1]) / scale[train, None]
source_groups, group_first, group_index = np.unique(cache["fold"],
    return_index=True, return_inverse=True)
source_eligible = (source_groups[:, None] != cache["fold"][train][None]) & (
    duration[group_first, None] == duration[train][None])
source_n = source_eligible.sum(axis=1)
assert source_n.min() > 0
source_weight = source_eligible / source_n[:, None]
empirical_covariance = np.einsum("gn,nt,nu->gtu", source_weight,
    background_training, background_training, optimize=True)
group_size = count[group_first]
trace_covariance = np.trace(empirical_covariance, axis1=1, axis2=2)
mu = trace_covariance / group_size
norm_covariance = np.sum(empirical_covariance ** 2, axis=(1, 2))
fourth_moment = np.sum(background_training ** 2, axis=1) ** 2
beta = (source_weight @ fourth_moment - norm_covariance) / (group_size * source_n)
delta = (norm_covariance - trace_covariance ** 2 / group_size) / group_size
shrinkage = np.minimum(beta, delta) / delta
assert np.all((shrinkage > 0.) & (shrinkage <= 1.))
identity = np.eye(len(time))
group_mask = density_mask[group_first]
covariance = (1. - shrinkage[:, None, None]) * empirical_covariance
covariance += (shrinkage * mu)[:, None, None] * identity[None] * group_mask[:, None]
# Missing tail coordinates are independent padding; they contribute no data or basis values.
covariance += identity[None] * (~group_mask[:, None])
short_group, long_group = group_size.argmin(), group_size.argmax()
short_size, long_size = group_size[short_group], group_size[long_group]
short_check, short_shrinkage = ledoit_wolf(
    background_training[source_eligible[short_group], :short_size], assume_centered=True)
long_check, long_shrinkage = ledoit_wolf(
    background_training[source_eligible[long_group], :long_size], assume_centered=True)
assert np.max(np.abs(short_check - covariance[short_group, :short_size, :short_size])) < 1e-10
assert np.max(np.abs(long_check - covariance[long_group, :long_size, :long_size])) < 1e-10
precision_matrix = np.linalg.inv(covariance)
assert np.max(np.abs(covariance @ precision_matrix - identity[None])) < 1e-8
grid = np.r_[np.arange(*application["period_bounds_h"], application["density"]["grid_step_h"]),
    application["period_bounds_h"][1]]
grid_weight = np.ones(len(grid))
grid_weight[[0, -1]] = .5
grid_weight /= grid_weight.sum()
angle = 2. * np.pi * time[None] / grid[:, None]
harmonic = np.sqrt(2.) * np.stack([np.cos(angle), np.sin(angle)], axis=-1)[None] * group_mask[:, None, :, None]
base_group = base[group_first]
harmonic -= np.einsum("gti,gpij->gptj", base_group,
    np.einsum("gti,gptj->gpij", base_group, harmonic))
precision_harmonic = np.einsum("gtu,gpui->gpti", precision_matrix, harmonic, optimize=True)
gram = np.einsum("gpti,gptj->gpij", harmonic, precision_harmonic)
coefficient_precision = application["density"]["coefficient_precision"]
gram += coefficient_precision * np.eye(2)
gram_inv = np.linalg.inv(gram)
precision_y = np.einsum("ntu,nu->nt", precision_matrix[group_index], mixed_y)
rhs = np.einsum("npti,nt->npi", harmonic[group_index], precision_y)
base_rss = np.sum(mixed_y * precision_y, axis=1)
coef = np.einsum("npij,npj->npi", gram_inv[group_index], rhs)
rss = base_rss[:, None] - np.sum(rhs * coef, axis=-1)
sign, logdet = np.linalg.slogdet(gram)
assert np.all(sign == 1.) and np.all(rss > 0.)
# The common signal scale is integrated after removing the two trend dimensions.
# The noise determinant is constant across candidate periods and cancels below.
log_evidence = -.5 * logdet[group_index] - (count[:, None] - 2.) / 2. * np.log(rss) + np.log(coefficient_precision)
covariance_evidence = log_evidence - logsumexp(log_evidence + np.log(grid_weight)[None], axis=1)[:, None]
label_kernel = np.exp(-np.abs(grid[:, None] - truth[None]) / application["risk_tolerance_h"])
grid_prior = (source_weight @ label_kernel.T)[group_index] * grid_weight[None]
grid_prior /= grid_prior.sum(axis=1)[:, None]
native_logit = log_evidence[heldout] + np.log(grid_prior[heldout])
native_mass = np.exp(native_logit - logsumexp(native_logit, axis=1)[:, None])
window = (np.abs(grid[:, None] - grid[None]) <= application["risk_tolerance_h"]).astype(float)
native_score = native_mass @ window.T
native_selected = native_score.argmax(axis=1)
native_estimate = grid[native_selected]
native_confidence = native_score.max(axis=1)
candidate_period = np.where(valid, periods, grid[0])
assert candidate_period.min() >= grid[0] and candidate_period.max() <= grid[-1]
left = np.clip(np.searchsorted(grid, candidate_period, side="right") - 1, 0, len(grid) - 2)
alpha = (candidate_period - grid[left]) / application["density"]["grid_step_h"]
candidate_evidence = ((1. - alpha) * np.take_along_axis(covariance_evidence, left, axis=1)
    + alpha * np.take_along_axis(covariance_evidence, left + 1, axis=1))
evidence_difference = candidate_evidence - candidate_evidence[row, reference_candidate, None]
forward = np.concatenate([forward, evidence_difference[..., None]], axis=-1)
reverse = np.concatenate([reverse, -evidence_difference[..., None]], axis=-1)
assert forward.shape[-1] == 159 and np.isfinite(evidence_difference[valid]).all()
main_model = clone(load(application["paths"]["lemna_adapt_model"]))
main_model.fit(np.concatenate([forward[train_valid], reverse[train_valid]]),
    np.concatenate([target[valid[train]], -target[valid[train]]]),
    sample_weight=np.tile(weight / 2., 2))
score = prior[heldout].copy()
score[valid[heldout]] += (main_model.predict(forward[test_valid]) -
    main_model.predict(reverse[test_valid])) / 2.
score = np.where(valid[heldout], score, -np.inf)
selected = score.argmax(axis=1)
test_row = np.arange(heldout.sum())
estimate = periods[heldout][test_row, selected]
saved = OUTPUT / ("lemna_joint_objective_probe_outer" + str(fold) + "_inner" + str(args.inner_fold) + ".joblib")
reporter_bundle = load(saved)
assert np.array_equal(reporter_bundle["train_trace_id"], trace_id[train])
absolute_score = prior[heldout].copy()
absolute_score[valid[heldout]] += reporter_bundle["absolute"].predict(features[test_valid])
confidence = absolute_score[test_row, selected]
methods = ["background_covariance_contrast_absolute_report", "background_covariance_density_window"]
records = pd.DataFrame({"trace_id": np.repeat(trace_id[heldout], 2), "method": np.tile(methods, heldout.sum()),
    "estimate_h": np.column_stack([estimate, native_estimate]).ravel(),
    "confidence": np.column_stack([confidence, native_confidence]).ravel(),
    "reference_period_h": np.repeat(reference.reference_period_h.to_numpy()[heldout], 2),
    "run": np.repeat(reference.run.to_numpy()[heldout], 2), "outer_fold": fold, "inner_fold": args.inner_fold})
records["absolute_difference_h"] = np.abs(records.estimate_h - records.reference_period_h)
records["bad2h"] = records.absolute_difference_h > application["risk_tolerance_h"]
stem = OUTPUT / ("lemna_background_covariance_probe_outer" + str(fold) + "_inner" + str(args.inner_fold))
records.to_csv(stem.with_suffix(".csv"), index=False, encoding="utf-8", lineterminator="\n")
np.savez_compressed(stem.with_suffix(".npz"), trace_id=trace_id[heldout], periods=periods[heldout],
    valid=valid[heldout], scores=score, selected=selected, train_trace_id=trace_id[train],
    covariance_trace_id=trace_id, covariance_period=grid, covariance_evidence=covariance_evidence,
    native_mass=native_mass, native_selected=native_selected, covariance=covariance,
    covariance_groups=source_groups, covariance_group_size=group_size, shrinkage=shrinkage,
    source_eligible=source_eligible, background_training=background_training)
dump({"model": main_model, "contrast_config": contrast_config,
    "new_feature": "training_background_covariance_log_evidence",
    "training_trace_id": trace_id[train], "training_duration_h": duration[train],
    "training_group": cache["fold"][train], "training_background": background_training,
    "covariance_groups": source_groups, "covariance": covariance, "shrinkage": shrinkage,
    "reporter": str(saved)}, stem.with_suffix(".joblib"))
ranked = records.sort_values(["method", "confidence", "trace_id"], ascending=[True, False, True], kind="stable")
ranked["accepted"] = ranked.groupby("method").cumcount() + 1
ranked["risk"] = ranked.groupby("method").bad2h.cumsum() / ranked.accepted
summary = ranked.groupby("method").agg(n=("trace_id", "size"), bad=("bad2h", "sum"),
    mae=("absolute_difference_h", "mean"), aurc=("risk", "mean"))
print("background_covariance_probe_complete", fold, args.inner_fold,
    "train", int(train.sum()), "shrinkage_range", np.quantile(shrinkage, [0, .5, 1]).tolist(), flush=True)
print(summary.to_string(), flush=True)
raise SystemExit(0)

''')
