native_oscillator_feature_stage = (
    correlated_density_feature_stage.split('# A white-noise atom', 1)[0]
    + r'''

# A damped oscillatory covariance centered on the observed dominant period.
# The correlation-time quadrature and white atom are inherited from the OU model.
quad_node, quad_weight = np.polynomial.legendre.leggauss(application["density"]["correlation_quadrature"])
edge_mask = density_mask[:, 1:] & density_mask[:, :-1]
gap = np.where(edge_mask, np.diff(tau, axis=1), 1.)
resolved_interval = np.min(np.where(edge_mask, gap, np.inf), axis=1)
log_lo, log_hi = np.log(resolved_interval), np.log(span)
correlation_time = np.exp((log_lo + log_hi)[:, None] / 2. +
    (log_hi - log_lo)[:, None] / 2. * quad_node[None])
correlation_time = np.column_stack([np.ones(len(y)), correlation_time])
white_mass = application["density"]["white_background_mass"]
noise_weight = np.r_[white_mass, (1. - white_mass) * quad_weight / 2.]
lag = np.abs(tau[:, :, None] - tau[:, None, :])
covariance = np.exp(-lag[:, None] / correlation_time[:, :, None, None])
covariance *= np.cos(2. * np.pi * lag / native_period[:, None, None])[:, None]
identity = np.eye(y.shape[1])
covariance[:, 0] = identity
covariance *= density_mask[:, None, :, None] * density_mask[:, None, None, :]
covariance += identity[None, None] * (~density_mask[:, None, None, :])
print("native_oscillator_covariance_ready", covariance.shape, flush=True)
noise_sign, noise_logdet = np.linalg.slogdet(covariance)
assert np.all(noise_sign == 1.)
print("native_oscillator_logdet_ready", flush=True)
angle = 2. * np.pi * tau[:, None] / density_periods[None, :, None]
harmonic = np.sqrt(2.) * np.stack([np.cos(angle), np.sin(angle)], axis=-1) * density_mask[:, None, :, None]
harmonic_matrix = harmonic.transpose(0, 2, 1, 3).reshape(len(y), y.shape[1], -1)
joint_design = np.concatenate([base, harmonic_matrix, y[..., None]], axis=-1)
precision_design = np.linalg.solve(covariance, joint_design[:, None])
del covariance
print("native_oscillator_precision_ready", flush=True)
base_precision = precision_design[..., :2]
harmonic_precision = precision_design[..., 2:-1].reshape(
    len(y), len(noise_weight), y.shape[1], len(density_periods), 2).transpose(0, 1, 3, 2, 4)
y_precision = precision_design[..., -1]
base_gram = np.einsum("nti,nrtj->nrij", base, base_precision)
base_rhs = np.einsum("nti,nrt->nri", base, y_precision)
signal_quadratic = np.einsum("nt,nrt->nr", y, y_precision)
gram = np.empty((len(y), len(noise_weight), len(density_periods), 4, 4))
gram[..., :2, :2] = base_gram[:, :, None]
cross_base = np.einsum("nti,nrptj->nrpij", base, harmonic_precision)
gram[..., :2, 2:] = cross_base
gram[..., 2:, :2] = cross_base.swapaxes(-1, -2)
gram[..., 2:, 2:] = np.einsum("npti,nrptj->nrpij", harmonic, harmonic_precision)
rhs = np.empty(gram.shape[:-1])
rhs[..., :2] = base_rhs[:, :, None]
rhs[..., 2:] = np.einsum("npti,nrt->nrpi", harmonic, y_precision)
del precision_design, harmonic_matrix, harmonic_precision, base_precision, y_precision, joint_design, cross_base, harmonic

'''
    + 'coefficient_precision =' + correlated_density_feature_stage.split('coefficient_precision =', 1)[1]
    + r'''

# Conditional evidence under the oscillatory-background component, without the white atom.
conditional_evidence = logsumexp(log_evidence[:, 1:] +
    np.log(noise_weight[1:] / (1. - white_mass))[None, :, None], axis=1)
conditional_log_density = conditional_evidence - logsumexp(
    conditional_evidence + np.log(grid_weight)[None], axis=1)[:, None]
density_features = np.concatenate([density_features, conditional_log_density[..., None]], axis=-1)

''')

