assert np.array_equal(source_bank["periods"][valid], periods[valid])
source_support = source_bank["power"][:, :, 0]
extra = source_support - source_support[row, reference_candidate, None]
forward = np.concatenate([forward, extra[..., None]], axis=-1)
reverse = np.concatenate([reverse, -extra[..., None]], axis=-1)
base_template = load(application["paths"]["lemna_adapt_model"])
main_model = clone(base_template)
main_model.fit(np.concatenate([forward[train_valid], reverse[train_valid]]),
    np.concatenate([target[valid[train]], -target[valid[train]]]), sample_weight=np.tile(weight / 2., 2))
main_score = prior[heldout].copy()
main_score[valid[heldout]] += (main_model.predict(forward[test_valid]) -
    main_model.predict(reverse[test_valid])) / 2.
main_score = np.where(valid[heldout], main_score, -np.inf)
selected = main_score.argmax(axis=1)
test_row = np.arange(heldout.sum())
