membership = source_groups[:, None] == cache["fold"][None]
peer_count = membership.sum(axis=1)[group_index] - 1
peer_mean = (membership.astype(float) @ mixed)[group_index] - mixed
peer_mean /= peer_count[:, None]
peer_rms = np.sqrt(np.sum(peer_mean ** 2, axis=1) / count)
assert (peer_count > 0).all() and (peer_rms > 0.).all()
peer_check = cache["fold"] == cache["fold"][0]
peer_check[0] = False
assert np.max(np.abs(peer_mean[0] - mixed[peer_check].mean(axis=0))) < 1e-12
peer_mean /= peer_rms[:, None]
