effect_scope = {"pd":pd,"np":np,"CONFIG":{"paths":{"natural_effect_input":Path(str(stem)+"_cells.csv"),
    "natural_effect_output":Path(str(stem)+"_effects")},"natural_effect":effect_config}}
exec(compile(effect_code.split("print(summary.to_string()",1)[0], str(report_path), "exec"),effect_scope)
print("BIOLOGICAL_EFFECT_SUMMARY",effect_scope["summary"].sort_values("mean_absolute_effect_error_h").to_string(),flush=True)
