conditional_source_uncertainty_fit_stage = conditional_source_probe_fit_stage.split("from sklearn.covariance import ledoit_wolf", 1)[0]
conditional_source_uncertainty_fit_stage += r'''
from sklearn.covariance import ledoit_wolf
from scipy.special import logsumexp
source_mode = {"conditional-source-uncertainty-fit": "conditional_source",
    "peer-conditional-source-uncertainty-fit": "peer_conditional_source"}[args.stage]
source_stem = OUTPUT / (application[source_mode]["output_stem"] + "_outer"
    + str(fold) + "_inner" + str(args.inner_fold))
bank = np.load(source_stem.with_suffix(".npz"))
assert np.array_equal(bank["trace_id"], trace_id)
assert np.array_equal(bank["train_trace_id"], trace_id[train])
assert np.array_equal(bank["heldout_trace_id"], trace_id[heldout])
assert np.array_equal(bank["mask"], mask) and np.array_equal(bank["time"], time)
target_training = target_residual / signal_rms[train, None]
# Each cached training prediction excludes its entire experiment.
prediction_error = target_training - bank["source_waveform"][train, 0]
group_size, group_first, group_index = np.unique(count,
    return_index=True, return_inverse=True)
group_mask = mask[group_first]
eligible = group_size[:, None] == count[train][None]
training_n = eligible.sum(axis=1)
weights = eligible / training_n[:, None]
empirical = np.einsum("gn,nt,nu->gtu", weights,
    prediction_error, prediction_error, optimize=True)
trace_covariance = np.trace(empirical, axis1=1, axis2=2)
mu = trace_covariance / group_size
norm_covariance = np.sum(empirical ** 2, axis=(1, 2))
fourth_moment = np.sum(prediction_error ** 2, axis=1) ** 2
beta = (weights @ fourth_moment - norm_covariance) / (group_size * training_n)
delta = (norm_covariance - trace_covariance ** 2 / group_size) / group_size
shrinkage = np.minimum(beta, delta) / delta
assert np.all((shrinkage > 0.) & (shrinkage <= 1.))
identity = np.eye(len(time))
covariance = (1. - shrinkage[:, None, None]) * empirical
covariance += (shrinkage * mu)[:, None, None] * identity[None] * group_mask[:, None]
covariance += identity[None] * (~group_mask[:, None])
short_group, long_group = group_size.argmin(), group_size.argmax()
short_size, long_size = group_size[short_group], group_size[long_group]
short_check, short_lambda = ledoit_wolf(prediction_error[eligible[short_group], :short_size],
    assume_centered=True)
long_check, long_lambda = ledoit_wolf(prediction_error[eligible[long_group], :long_size],
    assume_centered=True)
assert np.max(np.abs(short_check - covariance[short_group, :short_size, :short_size])) < 1e-10
assert np.max(np.abs(long_check - covariance[long_group, :long_size, :long_size])) < 1e-10
# Preserve the established coefficient prior scale; change covariance shape only.
noise_shape = covariance / mu[:, None, None] * group_mask[:, None]
noise_shape += identity[None] * (~group_mask[:, None])
whitener = np.linalg.solve(np.linalg.cholesky(noise_shape),
    np.broadcast_to(identity, noise_shape.shape))
assert np.max(np.abs(whitener @ noise_shape @ whitener.swapaxes(-1, -2)
    - identity[None])) < 1e-9
query_whitener = whitener[group_index[heldout]]
density_scope = dict(globals())
density_scope.update(density_y=bank["source_waveform"][heldout, 0],
    density_time=np.broadcast_to(time, (heldout.sum(), len(time))),
    density_mask=mask[heldout])
density_code = density_feature_stage.split("schur_map =", 1)[0]
density_code = density_code.replace("base_gram =", """y = np.einsum("ntu,nu->nt", query_whitener, y, optimize=True)
base = np.einsum("ntu,nui->nti", query_whitener, base, optimize=True)
harmonic_flat = harmonic_flat @ query_whitener.swapaxes(-1, -2)
base_gram =""", 1)
exec(compile(density_code, __file__, "exec"), density_scope)
log_evidence = (-.5 * np.linalg.slogdet(density_scope["single_gram"])[1]
    - density_scope["count"][:, None] / 2. * np.log(density_scope["single_rss"]))
grid = density_scope["density_periods"]
grid_weight = density_scope["grid_weight"]
# Compare the Schur calculation against one joint four-coefficient solve
# at the two observed lengths and at the grid endpoints and midpoint.
check_rows = np.array([count[heldout].argmin(), count[heldout].argmax()])
check_periods = np.array([0, len(grid) // 2, len(grid) - 1])
check_angle = 2. * np.pi * density_scope["tau"][check_rows, None] / grid[check_periods][None, :, None]
check_harmonic = np.stack([np.cos(check_angle), np.sin(check_angle)], axis=-1)
check_harmonic *= np.sqrt(2.) * mask[heldout][check_rows, None, :, None]
check_harmonic = np.einsum("ntu,nkui->nkti",
    query_whitener[check_rows], check_harmonic)
check_design = np.concatenate([np.broadcast_to(density_scope["base"][check_rows, None],
    (len(check_rows), len(check_periods), len(time), 2)), check_harmonic], axis=-1)
check_gram = np.einsum("nkti,nktj->nkij", check_design, check_design)
check_gram += application["density"]["coefficient_precision"] * np.eye(4)
check_rhs = np.einsum("nkti,nt->nki", check_design, density_scope["y"][check_rows])
check_coef = np.linalg.solve(check_gram, check_rhs[..., None])[..., 0]
check_rss = np.sum(density_scope["y"][check_rows] ** 2, axis=1)[:, None] - np.sum(check_rhs * check_coef, axis=2)
check_log = -.5 * np.linalg.slogdet(check_gram)[1] - count[heldout][check_rows, None] / 2. * np.log(check_rss)
saved_log = log_evidence[check_rows[:, None], check_periods[None]]
assert np.max(np.abs((check_log - check_log[:, :1])
    - (saved_log - saved_log[:, :1]))) < 1e-8
del density_scope
assert np.array_equal(grid, bank["native_periods"])
held_weights = weights[group_index[heldout]]
kernel = np.exp(-np.abs(grid[:, None] - truth[None]) / application["risk_tolerance_h"])
grid_prior = held_weights @ kernel.T * grid_weight[None]
grid_prior /= grid_prior.sum(axis=1)[:, None]
log_mass = log_evidence + np.log(grid_prior)
mass = np.exp(log_mass - logsumexp(log_mass, axis=1)[:, None])
window = (np.abs(grid[:, None] - grid[None]) <= application["risk_tolerance_h"]).astype(float)
window_score = mass @ window.T
estimate = grid[window_score.argmax(axis=1)]
intrinsic_confidence = window_score.max(axis=1)
selected = np.where(valid[heldout], np.abs(periods[heldout] - estimate[:, None]), np.inf).argmin(axis=1)
assert np.max(np.abs(periods[heldout][np.arange(heldout.sum()), selected] - estimate)) < 1e-10
candidate_kernel = np.exp(-np.abs(periods[heldout, :, None] - truth[None, None]) / application["risk_tolerance_h"])
candidate_prior = np.einsum("nkm,nm->nk", candidate_kernel, held_weights)
del candidate_kernel
report_features = np.concatenate([cache["features"][heldout], candidate_prior[..., None]], axis=-1)
report_stem = OUTPUT / ("lemna_joint_objective_probe_outer" + str(fold) + "_inner" + str(args.inner_fold))
reporter = load(report_stem.with_suffix(".joblib"))
assert np.array_equal(reporter["train_trace_id"], trace_id[train])
absolute_score = candidate_prior.copy()
absolute_score[valid[heldout]] += reporter["absolute"].predict(report_features[valid[heldout]])
confidence = absolute_score[np.arange(heldout.sum()), selected]
method_names = np.array([source_mode + "_uncertainty_window",
    source_mode + "_uncertainty_window_intrinsic"])
records = pd.DataFrame({"trace_id": np.repeat(trace_id[heldout], 2),
    "method": np.tile(method_names, heldout.sum()),
    "estimate_h": np.repeat(estimate, 2),
    "confidence": np.column_stack([confidence, intrinsic_confidence]).ravel(),
    "reference_period_h": np.repeat(reference.reference_period_h.to_numpy()[heldout], 2),
    "run": np.repeat(reference.run.to_numpy()[heldout], 2),
    "outer_fold": fold, "inner_fold": args.inner_fold})
records["absolute_difference_h"] = np.abs(records.estimate_h - records.reference_period_h)
records["bad2h"] = records.absolute_difference_h > application["risk_tolerance_h"]
stem = OUTPUT / (application[source_mode]["uncertainty_output_stem"]
    + "_outer" + str(fold) + "_inner" + str(args.inner_fold))
records.to_csv(stem.with_suffix(".csv"), index=False, encoding="utf-8", lineterminator="\n")
np.savez_compressed(stem.with_suffix(".npz"), trace_id=trace_id[heldout],
    train_trace_id=trace_id[train], periods=grid, native_mass=mass, selected=selected,
    group_size=group_size, noise_shape=noise_shape, shrinkage=shrinkage,
    training_n=training_n, source_prediction_path=str(source_stem.with_suffix(".npz")))
ranked = records.sort_values(["method", "confidence", "trace_id"],
    ascending=[True, False, True], kind="stable")
ranked["accepted"] = ranked.groupby("method").cumcount() + 1
ranked["risk"] = ranked.groupby("method").bad2h.cumsum() / ranked.accepted
summary = ranked.groupby("method").agg(n=("trace_id", "size"), bad=("bad2h", "sum"),
    mae=("absolute_difference_h", "mean"), aurc=("risk", "mean"))
print("source_uncertainty", source_mode, fold, args.inner_fold, "training_n", training_n,
    "shrinkage", shrinkage, "max_eigen_fraction",
    np.linalg.eigvalsh(empirical)[:, -1] / trace_covariance, flush=True)
print(summary.to_string(), flush=True)
raise SystemExit(0)
'''
exec(compile({"conditional-source-uncertainty-fit": conditional_source_uncertainty_fit_stage,
    "peer-conditional-source-uncertainty-fit": conditional_source_uncertainty_fit_stage}.get(args.stage, ""), __file__, "exec"))


conditional_source_uncertainty_report_stage = r'''
from operator import itemgetter
from functools import partial
read_csv = partial(pd.read_csv, encoding="utf-8", float_precision="round_trip")
source_names = np.array(["conditional_source", "peer_conditional_source"])
sources = pd.DataFrame({"name": source_names,
    "stem": [application["conditional_source"]["output_stem"],
        application["peer_conditional_source"]["output_stem"]],
    "uncertainty_stem": [application["conditional_source"]["uncertainty_output_stem"],
        application["peer_conditional_source"]["uncertainty_output_stem"]]})
sources["outer"] = args.heldout_run
parts = sources.merge(pd.DataFrame({"inner": np.arange(application["contrast_probe"]["inner_splits"])}), how="cross")
suffix = "_outer" + parts.outer.astype(str) + "_inner" + parts.inner.astype(str)
input_paths = parts.stem.radd(str(OUTPUT) + "/") + suffix + ".csv"
banks = list(map(np.load, input_paths.str.replace(".csv", ".npz", regex=False)))
held_ids = np.concatenate(tuple(map(itemgetter("heldout_trace_id"), banks)))
bank_sizes = np.asarray(tuple(map(len, tuple(map(itemgetter("heldout_trace_id"), banks)))))
bank_row = pd.Index(banks[0]["trace_id"]).get_indexer(held_ids)
bank_number = np.repeat(np.arange(len(banks)), bank_sizes)
source_power = np.stack(tuple(map(itemgetter("power"), banks)))[bank_number, bank_row, :, 0]
valid = banks[0]["valid"][bank_row]
peak_confidence = np.where(valid, source_power, -np.inf).max(axis=1)
mass = np.concatenate(tuple(map(itemgetter("native_mass"), banks)))[:, 0]
grid = banks[0]["native_periods"]
window = (np.abs(grid[:, None] - grid[None]) <= application["risk_tolerance_h"]).astype(float)
window_confidence = (mass @ window.T).max(axis=1)
intrinsic = pd.concat(map(read_csv, input_paths), ignore_index=True)
intrinsic = intrinsic.loc[intrinsic.method.str.match(r"^(peer_)?conditional_source_(peak|window)$")].copy()
assert np.array_equal(intrinsic.trace_id.to_numpy(), np.repeat(held_ids, 2))
intrinsic["confidence"] = np.column_stack([peak_confidence, window_confidence]).ravel()
intrinsic["method"] += "_intrinsic"
paths = parts.uncertainty_stem.radd(str(OUTPUT) + "/") + suffix + ".csv"
new = pd.concat(map(read_csv, paths), ignore_index=True)
base = read_csv(OUTPUT / (application["peer_conditional_source"]["output_stem"]
    + "_outer" + str(args.heldout_run) + "_comparison.csv"))
metadata = base[["trace_id", "condition"]].drop_duplicates("trace_id")
new = pd.concat([new, intrinsic], ignore_index=True).merge(metadata, on="trace_id", validate="many_to_one")
inner = pd.concat([base, new], ignore_index=True)
assert not inner.duplicated(["method", "trace_id"]).any()
expected_ids = pd.Index(base.trace_id.unique())
sizes = inner.groupby("method").trace_id.nunique()
assert sizes.eq(len(expected_ids)).all() and inner.trace_id.isin(expected_ids).all()
inner["absolute_difference_h"] = np.abs(inner.estimate_h - inner.reference_period_h)
inner["bad2h"] = inner.absolute_difference_h > application["risk_tolerance_h"]
ranked = inner.sort_values(["method", "confidence", "trace_id"], ascending=[True, False, True], kind="stable")
ranked["accepted"] = ranked.groupby("method").cumcount() + 1
ranked["risk"] = ranked.groupby("method").bad2h.cumsum() / ranked.accepted
ranked["coverage"] = ranked.accepted / len(expected_ids)
summary = ranked.groupby("method").agg(n=("trace_id", "size"), bad2h=("bad2h", "sum"),
    mae=("absolute_difference_h", "mean"), aurc=("risk", "mean")).reset_index()
half = ranked.loc[ranked.accepted.eq(len(expected_ids) // 2), ["method", "risk"]].copy()
half["bad_at_half"] = np.rint(half.risk * (len(expected_ids) // 2)).astype(int)
summary = summary.merge(half[["method", "bad_at_half"]], on="method")
bad = inner.pivot(index="trace_id", columns="method", values="bad2h")
new_methods = pd.Index(new.method.unique())
comparators = pd.Index(["current_level_absolute_report", "H1_window",
    "conditional_source_window", "peer_conditional_source_window"])
new_bad, old_bad = bad[new_methods].to_numpy(), bad[comparators].to_numpy()
fixed = np.sum(~new_bad[:, :, None] & old_bad[:, None], axis=0)
lost = np.sum(new_bad[:, :, None] & ~old_bad[:, None], axis=0)
paired = pd.DataFrame({"method": np.repeat(new_methods, len(comparators)),
    "comparator": np.tile(comparators, len(new_methods)),
    "fixed": fixed.ravel(), "lost": lost.ravel()})
local = inner.sort_values(["method", "run", "confidence", "trace_id"],
    ascending=[True, True, False, True], kind="stable")
local["accepted"] = local.groupby(["method", "run"]).cumcount() + 1
local["risk"] = local.groupby(["method", "run"]).bad2h.cumsum() / local.accepted
experiments = local.groupby(["method", "run", "condition"]).agg(n=("trace_id", "size"),
    bad2h=("bad2h", "sum"), mae=("absolute_difference_h", "mean"), aurc=("risk", "mean")).reset_index()
out = OUTPUT / (application["conditional_source"]["uncertainty_report_stem"] + "_outer" + str(args.heldout_run))
inner.to_csv(str(out) + "_comparison.csv", index=False, encoding="utf-8", lineterminator="\n")
summary.to_csv(str(out) + "_summary.csv", index=False, encoding="utf-8", lineterminator="\n")
ranked.to_csv(str(out) + "_curve.csv", index=False, encoding="utf-8", lineterminator="\n")
paired.to_csv(str(out) + "_paired.csv", index=False, encoding="utf-8", lineterminator="\n")
experiments.to_csv(str(out) + "_experiments.csv", index=False, encoding="utf-8", lineterminator="\n")
effect_code = conditional_source_effect_diagnostics_stage.split('stem = OUTPUT/application["conditional_source"]["full_output_stem"]', 1)[0]
effect_code = effect_code[effect_code.index("inner_run ="):]
exec(compile(effect_code, __file__, "exec"))
inner_run.to_csv(str(out) + "_effects_experiments.csv", index=False, encoding="utf-8", lineterminator="\n")
inner_effect.to_csv(str(out) + "_effects_contrasts.csv", index=False, encoding="utf-8", lineterminator="\n")
inner_summary.to_csv(str(out) + "_effects_summary.csv", encoding="utf-8", lineterminator="\n")
print(summary.merge(inner_summary, on="method").to_string(index=False), flush=True)
print(paired.loc[paired.method.str.contains("uncertainty")].to_string(index=False), flush=True)
raise SystemExit(0)
'''
exec(compile({"conditional-source-uncertainty-report": conditional_source_uncertainty_report_stage}.get(args.stage, ""), __file__, "exec"))


functional_source_projection_stage = r'''
target_training = target_residual / signal_rms[train, None]
raw_mixed = np.where(mask, normalized, 0.)
functional_periods = np.arange(*application["period_bounds_h"], application["density"]["grid_step_h"])
functional_periods = np.r_[functional_periods, application["period_bounds_h"][1]]
functional_angle = 2. * np.pi * time[:, None] / functional_periods[None]
functional_basis = np.stack([np.cos(functional_angle), np.sin(functional_angle)], axis=-1)
functional_basis = np.sqrt(2.) * functional_basis.reshape(len(time), -1)
layout_size, layout_first, layout_index = np.unique(count,
    return_index=True, return_inverse=True)
layout_base = base[layout_first]
layout_basis = functional_basis[None] * mask[layout_first, :, None]
layout_basis -= np.einsum("gti,gij->gtj", layout_base,
    np.einsum("gti,gtj->gij", layout_base, layout_basis))
functional_gram = layout_basis.swapaxes(-1, -2) @ layout_basis
functional_gram += application["density"]["coefficient_precision"] * np.eye(functional_basis.shape[1])
functional_map = np.linalg.solve(functional_gram, layout_basis.swapaxes(-1, -2))
assert np.max(np.abs(functional_gram @ functional_map - layout_basis.swapaxes(-1, -2))) < 1e-9
mixed = np.einsum("gkt,nt->gnk", functional_map, raw_mixed,
    optimize=True)[layout_index, np.arange(len(trace_id))]
target_training = np.einsum("gkt,nt->gnk", functional_map, target_training,
    optimize=True)[layout_index[train], np.arange(train.sum())]
'''

functional_source_fit_stage = conditional_source_probe_fit_stage.replace(
    'target_training = target_residual / signal_rms[train, None]\nmixed = np.where(mask, normalized, 0.)',
    functional_source_projection_stage.strip()).replace(
    'group_size = count[group_first]',
    'group_size = np.full(len(group_first), mixed.shape[1])').replace(
    'group_mask = mask[group_first]',
    'group_mask = np.ones((len(group_first), mixed.shape[1]), dtype=bool)').replace(
    'identity = np.eye(len(time))', 'identity = np.eye(mixed.shape[1])').replace(
    'short_group, long_group = group_size.argmin(), group_size.argmax()',
    'short_group, long_group = count[group_first].argmin(), count[group_first].argmax()').replace(
    'prediction *= mask',
    'prediction = prediction @ functional_basis.T\nprior_prediction = prior_prediction @ functional_basis.T\nprediction *= mask').replace(
    'source_waves = np.stack([prediction, prior_prediction, mixed], axis=1)',
    'source_waves = np.stack([prediction, prior_prediction, raw_mixed], axis=1)').replace(
    '"conditional_source_peak"', '"functional_source_peak"').replace(
    '"conditional_source_window"', '"functional_source_window"').replace(
    '"training_mean_peak"', '"functional_training_mean_peak"').replace(
    '"training_mean_window"', '"functional_training_mean_window"').replace(
    'application["conditional_source"]["output_stem"]',
    'application["functional_source"]["output_stem"]').replace(
    '"regularization": "Ledoit_Wolf_covariance_equivalent_ridge_no_label_tuning"',
    '"regularization": "Ledoit_Wolf_covariance_equivalent_ridge_no_label_tuning", "representation": "H1_coefficients_fitted_to_all_native_observations", "basis_periods": functional_periods, "basis_precision": application["density"]["coefficient_precision"]').replace(
    '"conditional_source_probe"', '"functional_source_probe"')
exec(compile({"functional-source-probe-fit": functional_source_fit_stage}.get(args.stage, ""), __file__, "exec"))


