records.to_csv(OUTPUT / application["functional_source"]["layout_output"],
    index=False, encoding="utf-8", lineterminator="\n")
print("native_layouts", len(layout), "records", len(records), "no_matching_train", int((matched == 0).sum()), flush=True)
