application["conditional_source_external"] = {
    "workspace": OUTPUT/"lemna2021_inference",
    "raw": ROOT/"data/external/lemna_watanabe2021/dual_reporter_observations.parquet",
    "reference": ROOT/"data/external/lemna_watanabe2021/author_period_references.csv",
    "stem": OUTPUT/"lemna2021_conditional_source_external",
    "peer_stem": OUTPUT/"lemna2021_peer_conditional_source_external",
    "peer_mean_cache": OUTPUT/"lemna2021_peer_background_features.npz",
    "peer_covariance_cache": OUTPUT/"lemna2021_peer_covariance_features.npz",
    "window_h": [24., 96.],
    "expected_training_records": 777,
    "expected_training_qualified": 506,
    "expected_external_records": 185,
    "expected_external_qualified": 60}

conditional_source_external_fit_stage = r'''
from sklearn.covariance import ledoit_wolf
from joblib import dump, load
from scipy.special import logsumexp

external = application["conditional_source_external"]
cache = np.load(external["workspace"]/"observed_candidates.npz")
trace_id, periods, valid = cache["trace_id"], cache["periods"], cache["valid"]
training_reference = pd.read_csv(application["paths"]["lemna_reference"], encoding="utf-8",
    float_precision="round_trip").set_index("trace_id")
training_id = training_reference.index.to_numpy(dtype=str)
training_qualified = training_reference.reference_usable.to_numpy()
training_observations = pd.read_parquet(application["paths"]["observations"])
training_table = training_observations.pivot(index="trace_id", columns="x", values="signal_y").reindex(training_id)
training_table = training_table.loc[:, training_table.columns.to_series().between(*external["window_h"]).to_numpy()]
test_observations = pd.read_parquet(external["workspace"]/"per2_main144_observations.parquet")
test_table = test_observations.pivot(index="trace_id", columns="x", values="signal_y").reindex(trace_id)
time = test_table.columns.to_numpy(dtype=float)
assert np.array_equal(training_table.columns.to_numpy(dtype=float)-external["window_h"][0], time)
assert len(training_id) == external["expected_training_records"]
assert training_qualified.sum() == external["expected_training_qualified"]
assert len(trace_id) == external["expected_external_records"]
assert not np.intersect1d(trace_id, training_id).size
signal = np.concatenate([training_table.to_numpy(dtype=float), test_table.to_numpy(dtype=float)], axis=0)
assert np.isfinite(signal).all()
count = len(time)
centered_time = time-time.mean()
base = np.stack([np.ones(count)/np.sqrt(count), centered_time/np.linalg.norm(centered_time)], axis=-1)
residual = signal-(signal@base)@base.T
signal_rms = np.sqrt(np.mean(residual**2, axis=1))
mixed = residual/signal_rms[:, None]
training_mask = np.r_[training_qualified, np.zeros(len(trace_id), dtype=bool)]
test_mask = np.r_[np.zeros(len(training_id), dtype=bool), np.ones(len(trace_id), dtype=bool)]

# Only the previously qualified 2023 training sources are read.
target_observations = pd.read_parquet(application["paths"]["lemna_dual_observations"],
    columns=["trace_id","time_h","published_target_y"],
    filters=[("trace_id","in",training_id[training_qualified].tolist()),
        ("time_h",">=",external["window_h"][0]),("time_h","<=",external["window_h"][1])])
target_table = target_observations.pivot(index="trace_id", columns="time_h",
    values="published_target_y").reindex(index=training_id[training_qualified],columns=training_table.columns)
target_signal = target_table.to_numpy(dtype=float)
assert np.isfinite(target_signal).all()
target_training = (target_signal-(target_signal@base)@base.T)/signal_rms[training_mask,None]
training_period = training_reference.reference_period_h.to_numpy()[training_qualified]

# Peer inputs contain all unfiltered records in the same experiment, excluding the query.
test_metadata = pd.read_parquet(external["raw"],columns=["trace_id","run"]).drop_duplicates().set_index("trace_id").loc[trace_id]
run = np.r_[training_reference.run.to_numpy(dtype=str),test_metadata.run.to_numpy(dtype=str)]
groups, group_index = np.unique(run,return_inverse=True)
membership = groups[:,None] == run[None]
peer_n = membership.sum(axis=1)[group_index]-1
peer_mean = ((membership.astype(float)@mixed)[group_index]-mixed)/peer_n[:,None]
peer_mean /= np.sqrt(np.mean(peer_mean**2,axis=1))[:,None]
predictor = {"peer-conditional-source-external-fit":
    np.stack([mixed,peer_mean],axis=-1).reshape(len(mixed),-1)}.get(args.stage,mixed)
fit_x = predictor[training_mask]
mean_x,mean_target = fit_x.mean(axis=0),target_training.mean(axis=0)
centered_x = fit_x-mean_x
cross_covariance = centered_x.T@(target_training-mean_target)/len(fit_x)
covariance,shrinkage = ledoit_wolf(fit_x)
coefficient = np.linalg.solve(covariance,(1.-shrinkage)*cross_covariance)
assert np.max(np.abs(covariance@coefficient-(1.-shrinkage)*cross_covariance)) < 1e-9
prediction = mean_target+(predictor[test_mask]-mean_x)@coefficient
source_waves = np.stack([prediction,np.broadcast_to(mean_target,prediction.shape),mixed[test_mask]],axis=1)
source_waves -= (source_waves@base)@base.T
source_power = np.sum(source_waves**2,axis=-1)
assert np.isfinite(source_waves).all() and (source_power>0.).all()

# The two existing period readouts and regularization rules are unchanged.
safe_periods = np.where(valid,periods,application["period_bounds_h"][0])
angle = 2.*np.pi*time[None,None]/safe_periods[:,:,None]
basis = np.stack([np.sin(angle),np.cos(angle)],axis=-1)
basis -= np.einsum("ti,nkij->nktj",base,np.einsum("ti,nktj->nkij",base,basis))
gram = np.einsum("nkti,nktj->nkij",basis,basis)
projection = np.einsum("nkti,nmt->nkmi",basis,source_waves)
harmonic_coef = np.linalg.solve(gram[:,:,None],projection[...,None])[...,0]
power = np.einsum("nkmi,nkmi->nkm",projection,harmonic_coef)/source_power[:,None]
score = np.where(valid[...,None],power,-np.inf)
peak_selected = score.argmax(axis=1)
peak_estimate = np.take_along_axis(periods,peak_selected,axis=1)
density_scope = dict(globals())
density_scope.update(density_y=source_waves.reshape(-1,count),
    density_time=np.broadcast_to(time,(len(trace_id)*3,count)),
    density_mask=np.ones((len(trace_id)*3,count),dtype=bool))
exec(compile(density_feature_stage.split("schur_map =",1)[0],__file__,"exec"),density_scope)
log_evidence = (-.5*np.linalg.slogdet(density_scope["single_gram"])[1]
    -count/2.*np.log(density_scope["single_rss"])).reshape(len(trace_id),3,-1)
grid,grid_weight = density_scope["density_periods"],density_scope["grid_weight"]
grid_prior = np.exp(-np.abs(grid[:,None]-training_period[None])/application["risk_tolerance_h"]).mean(axis=1)*grid_weight
grid_prior /= grid_prior.sum()
log_mass = log_evidence+np.log(grid_prior)[None,None]
native_mass = np.exp(log_mass-logsumexp(log_mass,axis=2)[...,None])
window = (np.abs(grid[:,None]-grid[None])<=application["risk_tolerance_h"]).astype(float)
window_score = native_mass@window.T
window_estimate = grid[window_score.argmax(axis=2)]
all_estimate = np.concatenate([peak_estimate,window_estimate],axis=1)
selected = np.where(valid[:,:,None],np.abs(periods[:,:,None]-all_estimate[:,None]),np.inf).argmin(axis=1)
assert np.max(np.abs(np.take_along_axis(periods,selected,axis=1)-all_estimate)) < 1e-10

# Reuse the controlled-training absolute reporter with the cached observed features.
reporter = load(application["paths"]["level_full_controlled"])
reference_period,reference_count = np.unique(reporter["training_period_h"],return_counts=True)
reporter_prior = (np.exp(-np.abs(periods[...,None]-reference_period[None,None])/reporter["utility_scale_h"])
    @ (reference_count/reference_count.sum()))
absolute_score = reporter_prior.copy()
absolute_score[valid] += reporter["reporter"].predict(
    np.concatenate([cache["observed"],reporter_prior[...,None]],axis=-1)[valid])
confidence = np.take_along_axis(absolute_score,selected,axis=1)
old = np.load(external["workspace"]/"main_predictions.npz")
assert np.array_equal(old["trace_id"],trace_id)
assert np.max(np.abs(absolute_score[np.arange(len(trace_id)),old["level_selected"]]-old["level_absolute"])) < 1e-10
prefix = {"peer-conditional-source-external-fit":"peer_conditional_source"}.get(args.stage,"conditional_source")
methods = np.array([prefix+"_peak","training_mean_peak","raw_H1_peak",
    prefix+"_window","training_mean_window","raw_H1_window_direct"])
predictions = pd.DataFrame({"trace_id":np.repeat(trace_id,len(methods)),
    "method":np.tile(methods,len(trace_id)),"estimate_h":all_estimate.ravel(),
    "confidence":confidence.ravel(),
    "intrinsic_confidence":np.concatenate([score.max(axis=1),window_score.max(axis=2)],axis=1).ravel(),
    "method_status":"ok"})
stem = {"peer-conditional-source-external-fit":external["peer_stem"]}.get(args.stage,external["stem"])
predictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\n")
np.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id,periods=periods,valid=valid,
    source_waveform=source_waves,power=power,native_periods=grid,native_mass=native_mass,
    prior=grid_prior,window=window,absolute_score=absolute_score,selected=selected,time=time,
    training_trace_id=training_id[training_qualified],training_period=training_period,
    training_all_trace_id=training_id,test_run=test_metadata.run.to_numpy(dtype=str))
dump({"coefficient":coefficient,"mean_x":mean_x,"mean_target":mean_target,
    "training_trace_id":training_id[training_qualified],"training_period":training_period,
    "window_h":external["window_h"],"time":time,"shrinkage":shrinkage,
    "input":prefix,"supervision":"2023_optical_target_same_raw_RMS",
    "regularization":"Ledoit_Wolf_covariance_equivalent_ridge_no_label_tuning"},stem.with_suffix(".joblib"))
print("conditional_source_external_saved",prefix,"training",len(fit_x),"test",len(trace_id),
    "window",external["window_h"],"shrinkage",shrinkage,"source_optical_test_read",False,flush=True)
raise SystemExit(0)
'''
