conditional_source_external_peer_stage = conditional_source_external_peer_stage.replace(
    'application["paths"]["lemna_peer_background_features"]','external["peer_mean_cache"]').replace("raise SystemExit(0)","")
conditional_source_external_peer_stage += "\nfrom scipy.special import logsumexp\nfrom sklearn.covariance import ledoit_wolf\n"
conditional_source_external_peer_stage += conditional_source_external_peer_header
conditional_source_external_peer_stage += "time = signal.columns" + peer_covariance_prepare_stage.split("time = signal.columns",1)[1]
conditional_source_external_peer_stage = conditional_source_external_peer_stage.replace(
    'application["paths"]["lemna_peer_covariance_features"]','external["peer_covariance_cache"]').replace("raise SystemExit(0)","")
conditional_source_external_peer_stage += r'''
mean_bank = np.load(external["peer_mean_cache"])
cov_bank = np.load(external["peer_covariance_cache"])
source_bank = np.load(external["stem"].with_suffix(".npz"))
assert np.array_equal(mean_bank["trace_id"],source_bank["trace_id"])
assert np.array_equal(cov_bank["trace_id"],source_bank["trace_id"])
periods,valid = source_bank["periods"],source_bank["valid"]
grid,prior,window = source_bank["native_periods"],source_bank["prior"],source_bank["window"]
mean_scores = np.where(valid,mean_bank["gain"],-np.inf)
mean_selected = mean_scores.argmax(axis=1)
mean_estimate = periods[np.arange(len(trace_id)),mean_selected]
cov_selected = cov_bank["conditional_gain"].argmax(axis=1)
cov_estimate = grid[cov_selected]
log_mass = cov_bank["log_density"]+np.log(prior)[None]
cov_mass = np.exp(log_mass-logsumexp(log_mass,axis=1)[:,None])
cov_window = cov_mass@window.T
cov_window_estimate = grid[cov_window.argmax(axis=1)]
estimates = np.stack([mean_estimate,cov_estimate,cov_window_estimate],axis=1)
intrinsic = np.stack([mean_scores.max(axis=1),cov_bank["conditional_gain"].max(axis=1),
    cov_window.max(axis=1)],axis=1)
selected = np.where(valid[:,:,None],np.abs(periods[:,:,None]-estimates[:,None]),np.inf).argmin(axis=1)
assert np.max(np.abs(np.take_along_axis(periods,selected,axis=1)-estimates)) < 1e-10
absolute = np.take_along_axis(source_bank["absolute_score"],selected,axis=1)
names = np.array(["peer_partial_LS","peer_covariance_LS","peer_covariance_window",
    "peer_partial_LS_absolute_report","peer_covariance_LS_absolute_report","peer_covariance_window_absolute_report"])
records = pd.DataFrame({"trace_id":np.repeat(trace_id,len(names)),"method":np.tile(names,len(trace_id)),
    "estimate_h":np.tile(estimates,(1,2)).ravel(),
    "confidence":np.concatenate([intrinsic,absolute],axis=1).ravel(),"method_status":"ok"})
prior_estimate = grid[(prior@window.T).argmax()]
prior_selected = np.where(valid,np.abs(periods-prior_estimate),np.inf).argmin(axis=1)
prior_absolute = source_bank["absolute_score"][np.arange(len(trace_id)),prior_selected]
records = pd.concat([records,pd.DataFrame({"trace_id":trace_id,"method":"source_training_period_prior_absolute_report",
    "estimate_h":prior_estimate,"confidence":prior_absolute,"method_status":"ok"}),
    pd.DataFrame({"trace_id":trace_id,"method":"source_training_period_prior",
    "estimate_h":prior_estimate,"confidence":np.nan,"method_status":"constant_no_ranking"})],ignore_index=True)
records.to_csv(str(external["stem"])+"_peer_baselines.csv",index=False,encoding="utf-8",lineterminator="\n")
print("external_peer_baselines_saved",len(trace_id),len(records.method.unique()),
    "training_prior_estimate",prior_estimate,flush=True)
raise SystemExit(0)
'''
exec(compile({"conditional-source-external-peer-baselines":conditional_source_external_peer_stage}.get(args.stage,""),__file__,"exec"))


