source_mixture_training_prepare_stage = r'''
# Deterministic integration over source contribution, using training sources only.
exec(compile(equivariant_source_probe_stage.split("# Complex linear maps",1)[0],__file__,"exec"))
settings = application["source_mixture_training"]
from numpy.polynomial.legendre import leggauss
nodes,node_weight = leggauss(settings["quadrature_order"])
fraction = (nodes+1.)/2.
fraction_weight = node_weight/2.
target_unit = target/np.sqrt(np.mean(target**2,axis=1))[:,None]
remainder = mixed[training_mask]-target
remainder_unit = remainder/np.sqrt(np.mean(remainder**2,axis=1))[:,None]
recombined = fraction[None,:,None]*target_unit[:,None]
recombined += (1.-fraction)[None,:,None]*remainder_unit[:,None]
recombined /= np.sqrt(np.mean(recombined**2,axis=2))[...,None]
augmented = recombined.reshape(-1,count)
augmented_peer = np.repeat(peer[training_mask],len(fraction),axis=0)
grid = np.r_[np.arange(*application["period_bounds_h"],application["density"]["grid_step_h"]),
    application["period_bounds_h"][1]]
angle = 2.*np.pi*time[None]/grid[:,None]
harmonic = np.stack([np.cos(angle),np.sin(angle)],axis=-1)
harmonic -= np.einsum("ti,pij->ptj",base,np.einsum("ti,ptj->pij",base,harmonic))
gram = np.einsum("pti,ptj->pij",harmonic,harmonic)
inverse = np.linalg.inv(gram)
raw_rhs = np.einsum("nt,pti->npi",augmented,harmonic)
peer_rhs = np.einsum("nt,pti->npi",augmented_peer,harmonic)
raw_coef = np.einsum("pij,npj->npi",inverse,raw_rhs)
peer_coef = np.einsum("pij,npj->npi",inverse,peer_rhs)
raw_gain = np.sum(raw_rhs*raw_coef,axis=-1)/count
peer_gain = np.sum(peer_rhs*peer_coef,axis=-1)/count
raw_complex = raw_coef[...,0]+1j*raw_coef[...,1]
peer_complex = peer_coef[...,0]+1j*peer_coef[...,1]
cross_complex = raw_complex*peer_complex.conj()
amplitude = np.abs(raw_complex)*np.abs(peer_complex)
phase_cosine = np.divide(cross_complex.real,amplitude,out=np.zeros_like(amplitude),where=amplitude>0.)
phase_sine = np.divide(cross_complex.imag,amplitude,out=np.zeros_like(amplitude),where=amplitude>0.)
global_correlation = np.mean(augmented*augmented_peer,axis=1)
unscaled_peer = ((membership.astype(float)@mixed)[all_group_index]-mixed)/peer_n[:,None]
peer_strength = np.repeat(np.sqrt(np.mean(unscaled_peer[training_mask]**2,axis=1)),len(fraction))
remaining_gram = gram[None]-np.einsum("npi,npj->npij",peer_rhs,peer_rhs)/count
remaining_rhs = raw_rhs-global_correlation[:,None,None]*peer_rhs
remaining_coef = np.einsum("npij,npj->npi",np.linalg.pinv(remaining_gram),remaining_rhs)
remaining_power = count*(1.-global_correlation**2)
partial_gain = np.sum(remaining_rhs*remaining_coef,axis=-1)/remaining_power[:,None]
retention = np.trace(remaining_gram,axis1=-2,axis2=-1)/np.trace(gram,axis1=-2,axis2=-1)[None]
features = np.stack([raw_gain,peer_gain,phase_cosine,phase_sine,
    np.broadcast_to(global_correlation[:,None],raw_gain.shape),
    np.broadcast_to(peer_strength[:,None],raw_gain.shape),np.clip(partial_gain,0.,1.),retention],axis=-1).astype(np.float32)
assert np.isfinite(features).all() and abs(fraction_weight.sum()-1.)<1e-12
assert not np.intersect1d(training_id[qualified],external_id).size
np.savez_compressed(settings["features"],training_id=training_id[qualified],
    run=reference.run.to_numpy(dtype=str)[qualified],features=features,
    source_fraction=fraction,source_weight=fraction_weight,periods=grid,
    reference_period=reference.reference_period_h.to_numpy()[qualified],
    query_group=group_index[qualified],time=time)
print("MIXTURE_TRAINING_FEATURES",features.shape,"biological_training_records",qualified.sum(),
    "deterministic_nodes",len(fraction),"test_sources_used",False,flush=True)
raise SystemExit(0)
'''
source_mixture_training_fit_stage = r'''
from sklearn.base import clone
from joblib import dump
settings = application[{True:"source_mixture_native",False:"source_mixture_training"}[args.stage=="source-mixture-native-fit"]]
augmented = np.load(settings["features"])
observed = np.load(settings["observed_features"])
fold = args.heldout_run
train = augmented["query_group"]!=fold
heldout = observed["query_group"]==fold
grid = augmented["periods"]
assert np.array_equal(grid,observed["periods"])
assert not np.intersect1d(augmented["run"][train],observed["run"][heldout]).size
nodes = len(augmented["source_fraction"])
features = augmented["features"].reshape(len(train),nodes,len(grid),-1)[train]
target = (np.abs(grid[None]-augmented["reference_period"][train,None])
    <=application["risk_tolerance_h"]).astype(float)
target = np.broadcast_to(target[:,None],features.shape[:-1])
group_count = pd.Series(augmented["run"][train]).value_counts()
balance = np.maximum(pd.Series(augmented["run"][train]).map(group_count).to_numpy(),
    np.median(group_count))**application["contrast_probe"]["balance_power"]
query_weight = 1./balance
query_weight *= train.sum()/query_weight.sum()
weight = query_weight[:,None,None]*augmented["source_weight"][None,:,None]/len(grid)
weight = np.broadcast_to(weight,features.shape[:-1])
model = clone(load(application["paths"]["lemna_adapt_model"]))
assert model.random_state==12345 and not model.early_stopping
model.fit(features.reshape(-1,features.shape[-1]),target.ravel(),sample_weight=weight.ravel())
test_features = observed["features"][heldout]
score = model.predict(test_features.reshape(-1,test_features.shape[-1])).reshape(heldout.sum(),len(grid))
selected = score.argmax(axis=1)
estimate = grid[selected]
confidence = score[np.arange(heldout.sum()),selected]
stem = settings["stem"].with_name(settings["stem"].name+"_fold"+str(fold))
predictions = pd.DataFrame({"trace_id":observed["trace_id"][heldout],
    "method":"mixture_trained_relative_success","estimate_h":estimate,
    "confidence":confidence,"method_status":"ok","heldout_fold":fold})
predictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\n")
np.savez_compressed(stem.with_suffix(".npz"),trace_id=observed["trace_id"][heldout],
    periods=grid,score=score,selected=selected,training_trace_id=augmented["training_id"][train])
dump({"model":model,"training_trace_id":augmented["training_id"][train],
    "feature_names":observed["feature_names"],"target":"training_period_within_2h",
    "source_fraction":augmented["source_fraction"],"source_weight":augmented["source_weight"],
    "training_recombination":"unit_RMS_optical_target_and_observed_remainder",
    "test_input":"original_unfiltered_query_and_original_leave_query_out_peers"},stem.with_suffix(".joblib"))
print("MIXTURE_TRAINED_SAVED",fold,"original_training_records",int(train.sum()),
    "test_records",int(heldout.sum()),"estimate_quantiles",np.quantile(estimate,[0.,.5,1.]).tolist(),flush=True)
raise SystemExit(0)
'''
exec(compile({"source-mixture-training-prepare":source_mixture_training_prepare_stage,"source-mixture-training-fit":source_mixture_training_fit_stage,"source-mixture-native-fit":source_mixture_training_fit_stage}.get(args.stage,""),__file__,"exec"))

source_mixture_native_prepare_stage = r'''
from numpy.polynomial.legendre import leggauss
settings = application["source_mixture_native"]
reference = pd.read_csv(application["paths"]["lemna_reference"],encoding="utf-8",
    float_precision="round_trip").set_index("trace_id")
trace_id = reference.index.to_numpy(dtype=str)
qualified = reference.reference_usable.to_numpy()
table = pd.read_parquet(application["paths"]["observations"]).pivot(
    index="trace_id",columns="x",values="signal_y").reindex(trace_id)
time = table.columns.to_numpy(dtype=float)
signal = table.to_numpy(dtype=float)
mask = np.isfinite(signal)
count = mask.sum(axis=1)
assert np.array_equal(mask,np.arange(len(time))[None]<count[:,None])
centered_time = np.where(mask,time[None]-np.sum(mask*time[None],axis=1)[:,None]/count[:,None],0.)
base = np.stack([mask/np.sqrt(count[:,None]),centered_time/np.linalg.norm(centered_time,axis=1)[:,None]],axis=-1)
signal = np.where(mask,signal,0.)
residual = signal-np.einsum("nti,ni->nt",base,np.einsum("nti,nt->ni",base,signal))
raw_rms = np.sqrt(np.sum(residual**2,axis=1)/count)
mixed = residual/raw_rms[:,None]
run = reference.run.to_numpy(dtype=str)
groups,first,query_group = np.unique(run,return_index=True,return_inverse=True)
membership = groups[:,None]==run[None]
peer_n = membership.sum(axis=1)[query_group]-1
peer_mean = ((membership.astype(float)@mixed)[query_group]-mixed)/peer_n[:,None]
peer_strength = np.sqrt(np.sum(peer_mean**2,axis=1)/count)
peer = peer_mean/peer_strength[:,None]
assert np.isfinite(mixed).all() and np.isfinite(peer).all()
optical = pd.read_parquet(application["paths"]["lemna_dual_observations"],
    columns=["trace_id","time_h","published_target_y"],
    filters=[("trace_id","in",trace_id[qualified].tolist())])
target = optical.pivot(index="trace_id",columns="time_h",values="published_target_y").reindex(
    index=trace_id[qualified],columns=time).to_numpy(dtype=float)
assert np.array_equal(np.isfinite(target),mask[qualified])
target = np.where(mask[qualified],target,0.)
target -= np.einsum("nti,ni->nt",base[qualified],np.einsum("nti,nt->ni",base[qualified],target))
target /= raw_rms[qualified,None]
nodes,node_weight = leggauss(settings["quadrature_order"])
fraction,fraction_weight = (nodes+1.)/2.,node_weight/2.
target_unit = target/np.sqrt(np.sum(target**2,axis=1)/count[qualified])[:,None]
remainder = mixed[qualified]-target
remainder_unit = remainder/np.sqrt(np.sum(remainder**2,axis=1)/count[qualified])[:,None]
recombined = fraction[None,:,None]*target_unit[:,None]+(1.-fraction)[None,:,None]*remainder_unit[:,None]
recombined /= np.sqrt(np.sum(recombined**2,axis=2)/count[qualified,None])[...,None]
augmented = recombined.reshape(-1,len(time))
combined = np.concatenate([mixed,augmented])
combined_peer = np.concatenate([peer,np.repeat(peer[qualified],len(fraction),axis=0)])
combined_count = np.r_[count,np.repeat(count[qualified],len(fraction))]
combined_strength = np.r_[peer_strength,np.repeat(peer_strength[qualified],len(fraction))]
layout_size,layout_first,layout_index = np.unique(count,return_index=True,return_inverse=True)
combined_layout = np.r_[layout_index,np.repeat(layout_index[qualified],len(fraction))]
grid = np.r_[np.arange(*application["period_bounds_h"],application["density"]["grid_step_h"]),
    application["period_bounds_h"][1]]
angle = 2.*np.pi*time[None]/grid[:,None]
harmonic = np.stack([np.cos(angle),np.sin(angle)],axis=-1)[None]*mask[layout_first,None,:,None]
layout_base = base[layout_first]
harmonic -= np.einsum("gti,gpij->gptj",layout_base,np.einsum("gti,gptj->gpij",layout_base,harmonic))
gram = np.einsum("gpti,gptj->gpij",harmonic,harmonic)
inverse = np.linalg.inv(gram)
row = np.arange(len(combined))
raw_rhs = np.einsum("nt,gpti->gnpi",combined,harmonic,optimize=True)[combined_layout,row]
peer_rhs = np.einsum("nt,gpti->gnpi",combined_peer,harmonic,optimize=True)[combined_layout,row]
raw_coef = np.einsum("npij,npj->npi",inverse[combined_layout],raw_rhs)
peer_coef = np.einsum("npij,npj->npi",inverse[combined_layout],peer_rhs)
raw_gain = np.sum(raw_rhs*raw_coef,axis=-1)/combined_count[:,None]
peer_gain = np.sum(peer_rhs*peer_coef,axis=-1)/combined_count[:,None]
raw_complex = raw_coef[...,0]+1j*raw_coef[...,1]
peer_complex = peer_coef[...,0]+1j*peer_coef[...,1]
cross_complex = raw_complex*peer_complex.conj()
amplitude = np.abs(raw_complex)*np.abs(peer_complex)
phase_cosine = np.divide(cross_complex.real,amplitude,out=np.zeros_like(amplitude),where=amplitude>0.)
phase_sine = np.divide(cross_complex.imag,amplitude,out=np.zeros_like(amplitude),where=amplitude>0.)
global_correlation = np.sum(combined*combined_peer,axis=1)/combined_count
remaining_gram = gram[combined_layout]-np.einsum("npi,npj->npij",peer_rhs,peer_rhs)/combined_count[:,None,None,None]
remaining_rhs = raw_rhs-global_correlation[:,None,None]*peer_rhs
remaining_coef = np.einsum("npij,npj->npi",np.linalg.pinv(remaining_gram),remaining_rhs)
remaining_power = combined_count*(1.-global_correlation**2)
partial_gain = np.sum(remaining_rhs*remaining_coef,axis=-1)/remaining_power[:,None]
retention = np.trace(remaining_gram,axis1=-2,axis2=-1)/np.trace(gram[combined_layout],axis1=-2,axis2=-1)
features = np.stack([raw_gain,peer_gain,phase_cosine,phase_sine,
    np.broadcast_to(global_correlation[:,None],raw_gain.shape),
    np.broadcast_to(combined_strength[:,None],raw_gain.shape),np.clip(partial_gain,0.,1.),retention],axis=-1).astype(np.float32)
assert np.isfinite(features).all() and abs(fraction_weight.sum()-1.)<1e-12
assert partial_gain.min()>-1e-9 and partial_gain.max()<1.+1e-9
feature_names = np.array(["raw_harmonic_gain","peer_harmonic_gain","relative_phase_cosine",
    "relative_phase_sine","raw_peer_correlation","peer_mean_strength",
    "partial_harmonic_gain","basis_retention"])
np.savez_compressed(settings["observed_features"],trace_id=trace_id,run=run,periods=grid,
    features=features[:len(trace_id)],feature_names=feature_names,query_group=query_group,
    groups=groups,time=time,mask=mask)
np.savez_compressed(settings["features"],training_id=trace_id[qualified],run=run[qualified],
    features=features[len(trace_id):],source_fraction=fraction,source_weight=fraction_weight,
    periods=grid,reference_period=reference.reference_period_h.to_numpy()[qualified],
    query_group=query_group[qualified],time=time,count=count[qualified])
print("NATIVE_MIXTURE_FEATURES",len(trace_id),"training_records",qualified.sum(),
    "layouts",layout_size.tolist(),"augmentation_training_only",True,flush=True)
raise SystemExit(0)
'''
exec(compile({True:source_mixture_native_prepare_stage,False:""}[args.stage=="source-mixture-native-prepare"],__file__,"exec"))

source_mixture_native_report_stage = r'''
import ast
from scipy.special import logsumexp
reference = pd.read_csv(application["paths"]["lemna_reference"],encoding="utf-8",
    float_precision="round_trip").set_index("trace_id")
source_reference = pd.read_csv(OUTPUT/"lemna_dual_background_reference.csv",encoding="utf-8",
    float_precision="round_trip").set_index("trace_id")
fold_text = pd.Series(np.arange(application["lemna_expected_runs"])).astype(str)
paths = fold_text.radd(str(application["source_mixture_native"]["stem"])+"_fold").add(".csv")
new = pd.concat(map(lambda p:pd.read_csv(p,encoding="utf-8",float_precision="round_trip"),paths),ignore_index=True)
assert new.trace_id.is_unique and len(new)==len(reference)
absolute_paths = fold_text.radd(str(application["paths"]["lemna_prior_evidence"])+"_fold").add(".npz")
absolute_banks = list(map(np.load,absolute_paths))
absolute_ids = np.concatenate(list(map(lambda x:x["trace_id"],absolute_banks)))
absolute_order = pd.Index(absolute_ids).get_indexer(new.trace_id)
assert (absolute_order>=0).all() and len(np.unique(absolute_ids))==len(reference)
absolute_scores = np.concatenate(list(map(lambda x:x["scores"][:,:,0],absolute_banks)))[absolute_order]
absolute_periods = np.concatenate(list(map(lambda x:x["periods"],absolute_banks)))[absolute_order]
distance = np.where(np.isfinite(absolute_periods),np.abs(absolute_periods-new.estimate_h.to_numpy()[:,None]),np.inf)
selected = distance.argmin(axis=1)
assert np.max(distance[np.arange(len(new)),selected])<1e-10
absolute = new.copy()
absolute["method"] += "_absolute_report"
absolute["confidence"] = absolute_scores[np.arange(len(new)),selected]
new = pd.concat([new,absolute],ignore_index=True)
old = pd.read_csv(str(application["conditional_source_external"]["natural_ablation_stem"])+"_cells.csv",
    encoding="utf-8",float_precision="round_trip")
columns = ["trace_id","method","estimate_h","confidence","method_status"]
d = pd.concat([old[columns],new[columns]],ignore_index=True)
common_keys = ["trace_id","method"]
body = conditional_source_full_report_stage[conditional_source_full_report_stage.index('d = d.join(reference[['):]
body = body.replace('stem = OUTPUT / application["conditional_source"]["full_output_stem"]',
    'stem = application["source_mixture_native"]["stem"].with_name(application["source_mixture_native"]["stem"].name+"_comparison")',1)
body = body.replace('print("PERIOD_AND_RISK",summary.to_string(),flush=True)',
    'print("PERIOD_AND_RISK",summary.loc[summary.index.isin(np.r_[new.method.unique(),["phase_prior_level_conditional_absolute_report","marginal_density_window","peer_conditional_source_window","ls_detrended24h","constant24","peer_covariance_window"]])].to_string(),flush=True)',1)
body = body.replace('effect_scope["summary"].sort_values("mean_absolute_effect_error_h").to_string()',
    'effect_scope["summary"].loc[effect_scope["summary"].index.isin(np.r_[new.method.unique(),["phase_prior_level_conditional_absolute_report","marginal_density_window","peer_conditional_source_window","ls_detrended24h"]])].to_string()',1)
exec(compile(body,__file__,"exec"))
'''
