class_mass = positive_mass+negative_mass
target = positive_mass/class_mass
group_count = pd.Series(groups[train]).value_counts()
balance = np.maximum(pd.Series(groups[train]).map(group_count).to_numpy(),
    np.median(group_count))**application["contrast_probe"]["balance_power"]
train_query_weight = query_weight[train]/balance
train_query_weight *= query_weight[train].sum()/train_query_weight.sum()
weight = train_query_weight[:,None]*class_mass/2.
