structural_recurrence_prepare_stage = r'''

from scipy.optimize import newton
exec(compile(structural_source_data_stage.split("\noptical =",1)[0],__file__,"exec"))
recurrence = application["structural_recurrence"]
length = len(time)
# Retain every measured time point with the author's symmetric delay padding.
delays = np.arange(recurrence["embedding_dimension"])
delay_index = np.arange(length)[None,:,None]-delays[None,None]
delay_index = np.where(delay_index<0,-delay_index-1,delay_index)
delay_index = np.minimum(delay_index,count[:,None,None]-1)
embedding = np.take_along_axis(mixed[:,:,None],delay_index,axis=1)
distance = np.sqrt(np.maximum(
    np.sum(embedding**2,axis=2)[:,:,None]+np.sum(embedding**2,axis=2)[:,None]
    -2.*np.einsum("ntd,nud->ntu",embedding,embedding),0.))
valid_pair = mask[:,:,None]&mask[:,None,:]
neighbor_distance = np.where(valid_pair&~np.eye(length,dtype=bool)[None],distance,np.inf)
nearest = np.sort(neighbor_distance,axis=-1)[:,:,:recurrence["neighbors"]][mask]
rho = nearest[:,0]
neighbor_delta = nearest-rho[:,None]
initial_sigma = neighbor_delta.mean(axis=1)/np.log(recurrence["neighbors"]/np.log2(recurrence["neighbors"]))
root = newton(lambda z:np.exp(-neighbor_delta/np.exp(z)[:,None]).sum(axis=1)-np.log2(recurrence["neighbors"]),
    np.log(initial_sigma),
    fprime=lambda z:np.sum(np.exp(-neighbor_delta/np.exp(z)[:,None])*neighbor_delta/np.exp(z)[:,None],axis=1),
    tol=recurrence["root_tolerance"],maxiter=100,full_output=True)
assert root.converged.all()
sigma_full = np.ones(mixed.shape)
rho_full = np.zeros(mixed.shape)
sigma_full[mask],rho_full[mask] = np.exp(root.root),rho
adjacency = np.exp(-np.maximum(distance-rho_full[:,:,None],0.)/sigma_full[:,:,None])*valid_pair
adjacency = adjacency+adjacency.swapaxes(1,2)-adjacency*adjacency.swapaxes(1,2)
# The query cannot contribute its own recurrence graph to its background prior.
peer_adjacency = ((membership.astype(float)@adjacency.reshape(len(mixed),-1))[all_group_index]
    -adjacency.reshape(len(mixed),-1)).reshape(adjacency.shape)/peer_n[:,None,None]
laplacian = np.eye(length)[None]*peer_adjacency.sum(axis=2)[:,:,None]-peer_adjacency
left = np.einsum("nti,ntu->niu",base,laplacian)
projected_laplacian = laplacian-np.einsum("nti,niu->ntu",base,left)
projected_laplacian -= np.einsum("nti,nui->ntu",
    np.einsum("ntu,nui->nti",projected_laplacian,base),base)
projected_laplacian = (projected_laplacian+projected_laplacian.swapaxes(1,2))/2.
eigenvalue,eigenvector = np.linalg.eigh(projected_laplacian)
active = eigenvalue>recurrence["eigen_tolerance"]
assert np.array_equal(active.sum(axis=1),count-2)
relaxation_rate = np.min(np.where(active,eigenvalue,np.inf),axis=1)
# Keep the complete heat-kernel spectrum, with diffusion time set by the slowest nonconstant mode.
kernel_spectrum = np.exp(-np.maximum(eigenvalue,0.)/relaxation_rate[:,None])*active
kernel_spectrum *= (count-2)[:,None]/kernel_spectrum.sum(axis=1)[:,None]
feature_path = recurrence["features_stem"].with_name(recurrence["features_stem"].name+
    {True:"_native",False:"_common"}[native]).with_suffix(".npz")
np.savez_compressed(feature_path,trace_id=trace_id,time=time,mask=mask,count=count,
    eigenvalue=eigenvalue,eigenvector=eigenvector,kernel_spectrum=kernel_spectrum,
    raw=mixed,base=base,run=run,query_group=query_group,peer_count=peer_n,
    embedding_dimension=recurrence["embedding_dimension"],neighbors=recurrence["neighbors"],
    relaxation_rate=relaxation_rate)
print("RECURRENCE_GEOMETRY",len(mixed),"counts",np.unique(count).tolist(),
    "valid_modes",np.unique(active.sum(axis=1)).tolist(),"same_experiment_only",True,
    "query_excluded",True,"root_residual",float(np.max(np.abs(
        np.exp(-neighbor_delta/np.exp(root.root)[:,None]).sum(axis=1)-np.log2(recurrence["neighbors"])))),
    flush=True)
raise SystemExit(0)
'''
exec(compile({True:structural_recurrence_prepare_stage,False:""}[args.stage=="structural-recurrence-prepare"],__file__,"exec"))

structural_recurrence_fit_stage = r'''

from numpy.polynomial.legendre import leggauss
from scipy.optimize import minimize
from scipy.special import logsumexp
from joblib import dump
recurrence = application["structural_recurrence"]
fold = args.heldout_run
native = fold<application["lemna_expected_runs"]
isotropic = args.stage=="structural-variance-fit"
feature_path = recurrence["features_stem"].with_name(recurrence["features_stem"].name+
    {True:"_native",False:"_common"}[native]).with_suffix(".npz")
geometry = np.load(feature_path)
trace_id,time,mask,count = geometry["trace_id"],geometry["time"],geometry["mask"],geometry["count"]
mixed,base = geometry["raw"],geometry["base"]
run,query_group = geometry["run"],geometry["query_group"]
train = (query_group<application["lemna_expected_runs"])&(query_group!=fold)
heldout = query_group==fold
assert not np.intersect1d(run[train],run[heldout]).size
reference = pd.read_csv(application["paths"]["lemna_reference"],encoding="utf-8",
    float_precision="round_trip").set_index("trace_id").reindex(trace_id)
qualified = reference.reference_usable.eq(True).to_numpy()
prior_labels = train&qualified
periods = np.r_[np.arange(*application["period_bounds_h"],application["density"]["grid_step_h"]),
    application["period_bounds_h"][1]]
grid_weight = np.ones(len(periods))
grid_weight[[0,-1]] = .5
grid_weight /= grid_weight.sum()
prior_eligible = query_group[:,None]!=query_group[prior_labels][None]
prior_eligible &= (not native)|(count[:,None]==count[prior_labels][None])
assert prior_eligible.sum(axis=1).min()>0
label_kernel = np.exp(-np.abs(periods[:,None]-reference.reference_period_h.to_numpy()[prior_labels][None])
    /application["risk_tolerance_h"])
prior = prior_eligible@label_kernel.T*grid_weight[None]
prior /= prior.sum(axis=1)[:,None]
angle = 2.*np.pi*time[None]/periods[:,None]
harmonic = np.sqrt(2.)*np.stack([np.cos(angle),np.sin(angle)],axis=-1)[None]*mask[:,None,:,None]
harmonic -= np.einsum("nti,npij->nptj",base,np.einsum("nti,nptj->npij",base,harmonic))
spectral_harmonic = np.einsum("ntk,npti->npki",geometry["eigenvector"],harmonic,optimize=True)
spectral_raw = np.einsum("ntk,nt->nk",geometry["eigenvector"],mixed,optimize=True)
active = geometry["eigenvalue"]>recurrence["eigen_tolerance"]
kernel_spectrum = (1-int(isotropic))*geometry["kernel_spectrum"]+int(isotropic)*active

from scipy.linalg import eigh_tridiagonal
order = recurrence["quadrature_order"]
diagonal_index = np.arange(1,order,dtype=float)
off_diagonal_index = np.arange(2,order,dtype=float)
# Golub-Welsch on a Beta-weighted Jacobi measure avoids overflowing normalization constants.
quadrature = lambda shape: (
    a:=shape[0],b:=shape[1],s:=a+b-2.,
    diagonal:=np.r_[(a-b)/(a+b),
        (a-b)*s/((2.*diagonal_index+s)*(2.*diagonal_index+s+2.))],
    off_diagonal:=np.r_[2.*np.sqrt(a*b/((a+b)**2*(a+b+1.))),
        2./(2.*off_diagonal_index+s)*np.sqrt(
            off_diagonal_index*(off_diagonal_index+a-1.)*(off_diagonal_index+b-1.)*(off_diagonal_index+s)/
            ((2.*off_diagonal_index+s-1.)*(2.*off_diagonal_index+s+1.)))],
    eigensystem:=eigh_tridiagonal(diagonal,off_diagonal),
    ((eigensystem[0]+1.)/2.,eigensystem[1][0]**2))[-1]
h0,h1 = spectral_harmonic[:,:,:,0],spectral_harmonic[:,:,:,1]
harmonic_moments = np.stack([h0**2,h0*h1,h1**2,
    h0*spectral_raw[:,None],h1*spectral_raw[:,None]],axis=-1)
moments = np.concatenate([spectral_raw[:,:,None]**2,
    harmonic_moments.transpose(0,2,1,3).reshape(len(trace_id),len(time),-1)],axis=2)
# Each evaluation uses quadrature nodes adapted to the current two Beta distributions.
evidence = lambda shape,moment,kappa,valid,ncount: (
    background_rule:={True:(np.array([.5]),np.ones(1)),False:quadrature(shape[:2])}[isotropic],
    target_rule:=quadrature(shape[2:]),
    background_fraction:=background_rule[0],
    target_fraction:=target_rule[0],
    covariance:=1.-background_fraction[None,:,None]+background_fraction[None,:,None]*kappa[:,None],
    inverse:=valid[:,None]/covariance,
    logdet_c:=np.sum(np.log(covariance)*valid[:,None],axis=2),
    statistics:=inverse@moment,
    rss0:=statistics[:,:,0],
    projected:=statistics[:,:,1:].reshape(len(moment),len(background_fraction),len(periods),5),
    variance:=target_fraction/(2.*(1.-target_fraction)),
    a00:=projected[:,:,None,:,0]+1./variance[None,None,:,None],
    a11:=projected[:,:,None,:,2]+1./variance[None,None,:,None],
    a01:=projected[:,:,None,:,1],
    r0:=projected[:,:,None,:,3],r1:=projected[:,:,None,:,4],
    determinant:=a00*a11-a01**2,
    coefficient0:=(a11*r0-a01*r1)/determinant,
    coefficient1:=(a00*r1-a01*r0)/determinant,
    residual:=rss0[:,:,None,None]-coefficient0*r0-coefficient1*r1,
    loge:=-.5*logdet_c[:,:,None,None]-.5*np.log(determinant*variance[None,None,:,None]**2)
        -(ncount-2)[:,None,None,None]/2.*np.log(residual),
    log_joint:=loge+np.log(background_rule[1][None,:,None,None])+np.log(target_rule[1][None,None,:,None]),
    (log_joint,coefficient0,coefficient1,background_rule,target_rule))[-1]
training_moments = moments[prior_labels]
training_kernel = kernel_spectrum[prior_labels]
training_active = active[prior_labels]
training_count = count[prior_labels]
training_prior = np.log(prior[prior_labels])
truth = reference.reference_period_h.to_numpy()[prior_labels]
target_mass = np.maximum(1.-np.abs(periods[None]-truth[:,None])/application["density"]["grid_step_h"],0.)
assert np.allclose(target_mass.sum(axis=1),1.)
training_group = query_group[prior_labels]
training_weight = 1./pd.Series(training_group).map(pd.Series(training_group).value_counts()).to_numpy()
training_weight /= training_weight.sum()
objective = lambda theta: (
    joint:=evidence(np.exp(theta),training_moments,training_kernel,training_active,training_count)[0],
    logmass:=logsumexp(joint,axis=(1,2))+training_prior,
    logmass:=logmass-logsumexp(logmass,axis=1)[:,None],
    -np.sum(training_weight[:,None]*target_mass*logmass)
        +recurrence["prior_regularization"]*np.sum(theta**2))[-1]
initial = np.zeros(4)
initial_loss = objective(initial)
uniform_rule = quadrature(np.ones(2))
assert np.allclose(uniform_rule[0],(leggauss(order)[0]+1.)/2.)
assert np.allclose(uniform_rule[1],leggauss(order)[1]/2.)
loss_history = [[0,initial_loss]]
print("RECURRENCE_TRAIN",fold,"isotropic",isotropic,"training_records",int(prior_labels.sum()),
    "initial_loss",initial_loss,"adaptive_quadrature_order",order,flush=True)
result = minimize(objective,initial,method="L-BFGS-B",
    bounds=np.tile(np.log(recurrence["shape_bounds"]),(4,1)),
    callback=lambda intermediate_result:(loss_history.append([len(loss_history),float(intermediate_result.fun)]),
        len(loss_history)%10==0 and print("RECURRENCE_PROGRESS",fold,len(loss_history)-1,
            intermediate_result.fun,flush=True)),
    options={"maxiter":recurrence["maxiter"],"ftol":recurrence["ftol"],
        "gtol":recurrence["gtol"],"eps":recurrence["finite_difference_step"],"maxls":30})
theta = result.x
fitted_rule = quadrature(np.exp(theta[2:]))
fitted_mean = np.sum(fitted_rule[0]*fitted_rule[1])
fitted_variance = np.sum((fitted_rule[0]-fitted_mean)**2*fitted_rule[1])
a_target,b_target = np.exp(theta[2:])
assert np.allclose(fitted_mean,a_target/(a_target+b_target),rtol=1e-8,atol=1e-12)
assert np.allclose(fitted_variance,a_target*b_target/((a_target+b_target)**2*(a_target+b_target+1.)),
    rtol=1e-8,atol=1e-12)
held_evidence,coef0,coef1,background_rule,target_rule = evidence(
    np.exp(theta),moments[heldout],kernel_spectrum[heldout],active[heldout],count[heldout])
joint = held_evidence+np.log(prior[heldout])[:,None,None,:]
joint -= logsumexp(joint,axis=(1,2,3))[:,None,None,None]
joint_mass = np.exp(joint)
mass = joint_mass.sum(axis=(1,2))
window = (np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)
score = mass@window.T
selected = score.argmax(axis=1)
estimate = periods[selected]
confidence = score[np.arange(len(score)),selected]
coef_mean = np.stack([(joint_mass*coef0).sum(axis=(1,2)),(joint_mass*coef1).sum(axis=(1,2))],axis=-1)
prediction = np.einsum("npti,npi->nt",harmonic[heldout],coef_mean,optimize=True)
source_method = {False:"recurrence_marginal_source_window",True:"variance_marginal_raw_window"}[isotropic]
stem = recurrence[{False:"stem",True:"isotropic_stem"}[isotropic]]
stem = stem.with_name(stem.name+{True:"_native",False:"_common"}[native]+"_fold"+str(fold))
dump({"parameters":theta,"beta_shapes":np.exp(theta),"optimization":result,
    "training_trace_id":trace_id[prior_labels],"training_weight":training_weight,
    "configuration":recurrence,"isotropic":isotropic,"training_loss_history":np.asarray(loss_history),
    "model":"shared_recurrence_heat_kernel_plus_private_periodic_source",
    "input":"unfiltered_query_and_leave_query_out_peer_recurrence_graphs",
    "target":"optically_separated_target_luminescence_period","heldout_optical_read":False},
    stem.with_suffix(".joblib"))
methods = np.array([source_method])
predictions = pd.DataFrame({"trace_id":trace_id[heldout],"method":source_method,"estimate_h":estimate,
    "confidence":confidence,"heldout_fold":fold,"heldout_run":run[heldout],"method_status":"ok"})
predictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\n")
np.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],
    source_waveform=prediction,periods=periods,mass=mass,estimate=estimate,confidence=confidence,
    methods=methods,prior=prior[heldout],background_variance_fraction=background_rule[0],
    target_variance_fraction=target_rule[0],
    background_fraction_mass=joint_mass.sum(axis=(2,3)),
    target_fraction_mass=joint_mass.sum(axis=(1,3)),beta_shapes=np.exp(theta),
    training_trace_id=trace_id[prior_labels],training_loss_history=np.asarray(loss_history))
print("RECURRENCE_OPTIMIZED","loss",result.fun,"iterations",result.nit,"status",str(result.message),
    "beta_shapes",np.exp(theta).tolist(),flush=True)
exec(compile(structural_source_readout_stage[structural_source_readout_stage.index("# Join held-out reference"):],
    __file__,"exec"))
raise SystemExit(0)
'''
