structural_population_flow_fit_stage = '\nfrom numpy.polynomial.legendre import leggauss\nfrom scipy.optimize import minimize\nfrom scipy.integrate import solve_ivp\nfrom scipy.special import logsumexp\nfrom joblib import dump\nimport torch\nfrom torch import nn\nexec(compile(structural_source_data_stage,__file__,"exec"))\nflow_settings = application["structural_population_flow"]\ntorch.set_num_threads(CONFIG["threads"])\ntorch.set_num_interop_threads(CONFIG["threads"])\ntorch.manual_seed(settings["seed"])\nrng = np.random.default_rng(settings["seed"])\nbackground_raw = (optical.assign(background=optical.green*application["background_templates"]["optical_coefficients"][0]\n    +optical.red*application["background_templates"]["optical_coefficients"][1])\n    .pivot(index="trace_id",columns="time_h",values="background")\n    .reindex(index=trace_id[train],columns=optical_time).to_numpy(dtype=float))\nassert np.array_equal(np.isfinite(background_raw),mask[train])\nbackground_raw = np.where(mask[train],background_raw,0.)\nbackground = background_raw-np.einsum("nti,ni->nt",base[train],\n    np.einsum("nti,nt->ni",base[train],background_raw))\nbackground /= raw_rms[train,None]\nsource_pair = np.stack([target,background],axis=1)\nsource_energy = np.sum(source_pair**2,axis=2)/count[train,None]\nassert (source_energy>0.).all()\ntarget_energy = source_energy[:,0]\nsource_unit = source_pair/np.sqrt(source_energy)[...,None]\nlength = len(time)\nlayout_count,layout_index = np.unique(count,return_inverse=True)\nlayout_weight = (layout_count[:,None]==count[train][None])*row_weight[None]\nlayout_weight /= layout_weight.sum(axis=1)[:,None]\nautocovariance = np.fft.irfft(np.abs(np.fft.rfft(source_unit,n=2*length,axis=2))**2,\n    n=2*length,axis=2)[:,:,:length]/count[train,None,None]\nlag = np.abs(np.arange(length)[:,None]-np.arange(length)[None])\nprior_covariance = np.einsum("ln,nrt->lrt",layout_weight,autocovariance)[:,:,lag]\neigenvalue,eigenvector = np.linalg.eigh(prior_covariance)\nassert eigenvalue.min()>-1e-9\nprior_factor = eigenvector*np.sqrt(np.maximum(eigenvalue,0.))[:,:,None,:]\ntraining_factor = prior_factor[layout_index[train]]\nnodes,node_weight = leggauss(flow_settings["training_particles"])\nflow_time,flow_weight = (nodes+1.)/2.,node_weight/2.\nprior_training = np.einsum("nqrt,nrdt->nqrd",\n    rng.standard_normal((int(train.sum()),len(nodes),2,length)),training_factor)\nprior_training *= mask[train,None,None]\nprior_training -= np.einsum("nti,nqri->nqrt",base[train],\n    np.einsum("nti,nqrt->nqri",base[train],prior_training))\nbridge = (1.-flow_time[None,:,None,None])*prior_training+flow_time[None,:,None,None]*source_unit[:,None]\nvelocity_target = source_unit[:,None]-prior_training\ntraining_count = np.repeat(count[train],len(nodes))\ntraining_mask = np.repeat(mask[train],len(nodes),axis=0)\ntraining_base = np.repeat(base[train],len(nodes),axis=0)\ntraining_input = np.concatenate([bridge.reshape(-1,2,length),\n    np.repeat(mixed[train],len(nodes),axis=0)[:,None],\n    np.broadcast_to(flow_time[None,:,None],(int(train.sum()),len(nodes),length)).reshape(-1,1,length),\n    training_mask[:,None]],axis=1)\ntraining_edge = np.minimum(np.arange(length)[None],training_count[:,None]-1)\ntraining_input = np.take_along_axis(training_input,training_edge[:,None],axis=-1)\ntraining_input[:,-1] = training_mask\ntraining_groups,training_group_index = np.unique(run[train],return_inverse=True)\ntensor_groups = torch.as_tensor(training_group_index,dtype=torch.long)\ntensor_x = torch.as_tensor(training_input,dtype=torch.float32)\ntensor_y = torch.as_tensor(velocity_target.reshape(-1,2,length),dtype=torch.float32)\ntensor_mask = torch.as_tensor(training_mask,dtype=torch.float32)\ntensor_base = torch.as_tensor(training_base.copy(),dtype=torch.float32)\ntensor_weight = torch.as_tensor(\n    (row_weight[:,None]*flow_weight[None]).ravel()[:,None]*training_mask/training_count[:,None],\n    dtype=torch.float32)\nwidth,kernel = flow_settings["width"],settings["kernel_size"]\ndilation = flow_settings["dilations"]\nencoder = nn.Sequential(\n    nn.Conv1d(5,width,kernel,padding=(kernel//2)*dilation[0],dilation=dilation[0],padding_mode="replicate"),\n    nn.Tanh(),\n    nn.Conv1d(width,width,kernel,padding=(kernel//2)*dilation[1],dilation=dilation[1],padding_mode="replicate"),\n    nn.Tanh(),\n    nn.Conv1d(width,width,kernel,padding=(kernel//2)*dilation[2],dilation=dilation[2],padding_mode="replicate"),\n    nn.Tanh(),\n    nn.Conv1d(width,width,kernel,padding=(kernel//2)*dilation[3],dilation=dilation[3],padding_mode="replicate"),\n    nn.Tanh(),nn.Conv1d(width,width+2,1))\ndecoder = nn.Sequential(nn.Conv1d(3*width,width,kernel,padding=kernel//2,padding_mode="replicate"),\n    nn.Tanh(),nn.Conv1d(width,2,1))\nflow_model = nn.Sequential(encoder,decoder)\nnn.init.zeros_(decoder[-1].weight)\nnn.init.zeros_(decoder[-1].bias)\nencoder_names = tuple(dict(encoder.named_parameters()))\nencoder_shapes = tuple(map(torch.Tensor.size,encoder.parameters()))\nencoder_sizes = tuple(map(torch.Tensor.numel,encoder.parameters()))\ndecoder_names = tuple(dict(decoder.named_parameters()))\ndecoder_shapes = tuple(map(torch.Tensor.size,decoder.parameters()))\ndecoder_sizes = tuple(map(torch.Tensor.numel,decoder.parameters()))\nencoder_size = int(np.sum(encoder_sizes))\ninitial = nn.utils.parameters_to_vector(flow_model.parameters()).detach().numpy().astype(np.float64)\nunpack_encoder = lambda vector: dict(zip(encoder_names,map(torch.reshape,\n    torch.split(vector[:encoder_size],encoder_sizes),encoder_shapes)))\nunpack_decoder = lambda vector: dict(zip(decoder_names,map(torch.reshape,\n    torch.split(vector[encoder_size:],decoder_sizes),decoder_shapes)))\n# Both named sources can carry shared trajectories. Attention is learned from all\n# cells in the same experiment; no shared/private orthogonality is imposed.\npopulation_context = lambda encoded,groups,group_n,particles: (\n    features:=encoded[:,:width].reshape(len(groups),particles,width,length),\n    logits:=encoded[:,width:].reshape(len(groups),particles,2,length),\n    group_shape:=(group_n,particles,2,length),\n    index:=groups[:,None,None,None].expand_as(logits),\n    maximum:=logits.new_full(group_shape,-torch.inf).scatter_reduce(\n        0,index,logits,reduce="amax",include_self=True),\n    weight:=(logits-maximum[groups]).exp(),\n    weight:=weight/weight.new_zeros(group_shape).index_add(0,groups,weight)[groups],\n    contribution:=(weight[:,:,:,None,:]*features[:,:,None]).reshape(len(groups),particles,2*width,length),\n    shared:=contribution.new_zeros((group_n,particles,2*width,length)).index_add(0,groups,contribution)[groups],\n    torch.cat([features.reshape(-1,width,length),shared.reshape(-1,2*width,length)],dim=1))[-1]\nforward = lambda vector,inputs,valid,basis,groups,group_n,particles: (\n    encoded:=torch.func.functional_call(encoder,unpack_encoder(vector),(inputs,)),\n    joint:=population_context(encoded,groups,group_n,particles),\n    value:=torch.func.functional_call(decoder,unpack_decoder(vector),(joint,))*valid[:,None],\n    value-torch.einsum("nti,nri->nrt",basis,torch.einsum("nti,nrt->nri",basis,value)))[-1]\nobjective = lambda vector: ((forward(vector,tensor_x,tensor_mask,tensor_base,tensor_groups,\n    len(training_groups),len(nodes))-tensor_y).square().mean(dim=1)*tensor_weight).sum() \\\n    +settings["weight_decay"]*vector.square().mean()\nautograd_objective = torch.func.grad_and_value(objective)\nto_scipy = lambda gradient,value: (value.detach().item(),gradient.detach().numpy().astype(np.float64))\nscipy_objective = lambda vector: to_scipy(*autograd_objective(torch.as_tensor(vector,dtype=torch.float32)))\ninitial_loss,initial_gradient = scipy_objective(initial)\nassert np.isfinite(initial_loss) and np.isfinite(initial_gradient).all()\nloss_history = [[0,initial_loss]]\nprint("POPULATION_FLOW_TRAIN",fold,"natural_records",int(train.sum()),"experiments",len(training_groups),\n    "source_roles",2,"quadrature_pairs",len(training_input),"parameters",len(initial),\n    "initial_loss",initial_loss,"seed",settings["seed"],flush=True)\nresult = minimize(scipy_objective,initial,jac=True,method="L-BFGS-B",\n    callback=lambda intermediate_result:(loss_history.append([len(loss_history),float(intermediate_result.fun)]),\n        len(loss_history)%50==0 and print("POPULATION_FLOW_PROGRESS",fold,len(loss_history)-1,\n            intermediate_result.fun,flush=True)),\n    options={"maxiter":flow_settings["maxiter"],"ftol":flow_settings["ftol"],\n        "gtol":settings["gtol"],"maxls":settings["maxls"]})\nstem = flow_settings["stem"].with_name(flow_settings["stem"].name+\n    {True:"_native",False:"_common"}[native]+"_fold"+str(fold))\ndump({"parameters":result.x,"encoder_names":encoder_names,"encoder_shapes":encoder_shapes,\n    "decoder_names":decoder_names,"decoder_shapes":decoder_shapes,"training_trace_id":trace_id[train],\n    "configuration":flow_settings,"optimization":result,"training_loss_history":np.asarray(loss_history),\n    "prior_covariance":prior_covariance,"layout_count":layout_count,"training_row_weight":row_weight,\n    "training_groups":training_groups,"model":"joint_target_background_population_conditional_flow",\n    "target":"unit_RMS_optically_separated_target_and_background_luminescence",\n    "input":"all_unfiltered_cells_from_the_same_experiment","seed":settings["seed"],\n    "heldout_optical_read":False},stem.with_suffix(".joblib"))\nprint("POPULATION_FLOW_OPTIMIZED","loss",result.fun,"iterations",result.nit,\n    "status",str(result.message),flush=True)\nparameters = torch.as_tensor(result.x,dtype=torch.float32)\nparticle_n = flow_settings["posterior_particles"]\n# The joint product prior uses independent cell draws in both training and inference.\nprior_pair = np.einsum("nqrt,nrdt->nqrd",\n    rng.standard_normal((int(heldout.sum()),particle_n,2,length)),prior_factor[layout_index[heldout]])\nprior_pair *= mask[heldout,None,None]\nprior_pair -= np.einsum("nti,nqri->nqrt",base[heldout],\n    np.einsum("nti,nqrt->nqri",base[heldout],prior_pair))\nheld_groups,held_group_index = np.unique(run[heldout],return_inverse=True)\nheld_groups_tensor = torch.as_tensor(held_group_index,dtype=torch.long)\nheld_count = np.repeat(count[heldout],particle_n)\nheld_edge = np.minimum(np.arange(length)[None],held_count[:,None]-1)\nheld_mask_tensor = torch.as_tensor(np.repeat(mask[heldout],particle_n,axis=0),dtype=torch.float32)\nheld_base_tensor = torch.as_tensor(np.repeat(base[heldout],particle_n,axis=0).copy(),dtype=torch.float32)\nheld_condition = np.repeat(mixed[heldout],particle_n,axis=0)\nheld_condition_tensor = torch.as_tensor(np.take_along_axis(held_condition,held_edge,axis=-1)[:,None],\n    dtype=torch.float32)\nheld_edge_tensor = torch.as_tensor(held_edge,dtype=torch.long)[:,None].expand(-1,2,-1)\node_velocity = lambda t,z: forward(parameters,torch.cat([\n    torch.as_tensor(z.reshape(-1,2,length),dtype=torch.float32).gather(2,held_edge_tensor),\n    held_condition_tensor,torch.full((len(held_count),1,length),float(t)),\n    held_mask_tensor[:,None]],dim=1),held_mask_tensor,held_base_tensor,held_groups_tensor,\n    len(held_groups),particle_n).detach().numpy().astype(np.float64).ravel()\nsolution = solve_ivp(ode_velocity,(0.,1.),prior_pair.ravel(),method="RK45",t_eval=[1.],\n    rtol=flow_settings["ode_rtol"],atol=flow_settings["ode_atol"])\nassert solution.success\nsource_pair_samples = solution.y[:,-1].reshape(int(heldout.sum()),particle_n,2,length)*mask[heldout,None,None]\nassert np.isfinite(source_pair_samples).all()\nsource_samples = source_pair_samples[:,:,0]\nprior_samples = prior_pair[:,:,0]\n# Average the period posterior over every trajectory; do not choose a favorable sample.\nreadout_code = structural_source_readout_stage.split("prior_labels =",1)[0].replace(\n    "waves = np.stack([prediction,mixed[heldout]],axis=1)",\n    "waves = np.concatenate([source_samples,prior_samples],axis=1)").replace(\n    "np.repeat(held_mask,2,axis=0)","np.repeat(held_mask,2*particle_n,axis=0)").replace(\n    "np.repeat(held_count,2)","np.repeat(held_count,2*particle_n)")\nexec(compile(readout_code,__file__,"exec"))\nparticle_logmass = log_evidence.reshape(int(heldout.sum()),2,particle_n,len(periods))+np.log(grid_weight)[None,None,None]\nparticle_mass = np.exp(particle_logmass-logsumexp(particle_logmass,axis=-1)[...,None])\nmass = particle_mass.mean(axis=2)\n# The unconditional prior is identical within each observation layout.\nprior_layout,prior_layout_index = np.unique(count[heldout],return_inverse=True)\nprior_membership = (prior_layout[:,None]==count[heldout][None]).astype(float)\npooled_prior_mass = prior_membership@mass[:,1]/prior_membership.sum(axis=1)[:,None]\nmass[:,1] = pooled_prior_mass[prior_layout_index]\nwindow = (np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nscore = mass@window.T\nselected = score.argmax(axis=2)\nestimate = periods[selected]\nconfidence = np.take_along_axis(score,selected[...,None],axis=2)[...,0]\nmethods = np.array(["population_flow_source_window","population_flow_GP_prior_window"])\npredictions = pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],2),\n    "method":np.tile(methods,int(heldout.sum())),"estimate_h":estimate.ravel(),\n    "confidence":confidence.ravel(),"heldout_fold":fold,"heldout_run":np.repeat(run[heldout],2),\n    "method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,\n    mask=mask[heldout],source_samples=source_samples,background_samples=source_pair_samples[:,:,1],\n    prior_samples=prior_samples,background_prior_samples=prior_pair[:,:,1],periods=periods,\n    mass=mass,particle_mass=particle_mass,estimate=estimate,confidence=confidence,methods=methods,\n    training_trace_id=trace_id[train],training_groups=training_groups,\n    training_loss_history=np.asarray(loss_history),ode_nfev=solution.nfev,\n    training_source_energy=source_energy)\nprint("POPULATION_FLOW_INFERENCE","ode_nfev",solution.nfev,"source_rms_quantiles",\n    np.quantile(np.sqrt(np.sum(source_pair_samples**2,axis=3)/count[heldout,None,None]),\n        [.1,.5,.9],axis=(0,1)).tolist(),flush=True)\nevaluation_code = structural_source_readout_stage[structural_source_readout_stage.index("# Join held-out reference"):]\nexec(compile(evaluation_code,__file__,"exec"))\nraise SystemExit(0)\n'
exec(compile({'structural-population-flow-fit':structural_population_flow_fit_stage}.get(args.stage,''),__file__,'exec'))

structural_hierarchy_colored_prepare_stage = '\n# Estimate the observation remainder from every training cell. A source with an\n# unusable reference is left in the remainder; it is not labeled biologically absent.\noptical_time = time+(1-int(native))*application["conditional_source_external"]["window_h"][0]\noptical = pd.read_parquet(application["paths"]["lemna_dual_observations"],\n    columns=["trace_id","time_h","published_target_y","green","red"],\n    filters=[("trace_id","in",trace_id[train].tolist())])\noptical["background"] = optical.green*application["background_templates"]["optical_coefficients"][0] \\\n    +optical.red*application["background_templates"]["optical_coefficients"][1]\noptical_target = optical.pivot(index="trace_id",columns="time_h",values="published_target_y").reindex(\n    index=trace_id[train],columns=optical_time).to_numpy(dtype=float)\noptical_background = optical.pivot(index="trace_id",columns="time_h",values="background").reindex(\n    index=trace_id[train],columns=optical_time).to_numpy(dtype=float)\noptical_pair = np.stack([optical_target,optical_background],axis=-1)\nassert np.array_equal(np.isfinite(optical_pair).all(axis=2),mask[train])\noptical_pair = np.where(mask[train,:,None],optical_pair,0.)\noptical_pair -= np.einsum("nti,nir->ntr",base[train],np.einsum("nti,ntr->nir",base[train],optical_pair))\noptical_pair /= raw_rms[train,None,None]\noptical_gain = np.linalg.solve(np.einsum("nti,ntj->nij",optical_pair,optical_pair),\n    np.einsum("nti,nt->ni",optical_pair,mixed[train])[...,None])[...,0]\nsource_angle = 2.*np.pi*time[None,None]/filled_period[:,:,None]\nsource_harmonic = np.stack([np.cos(source_angle),np.sin(source_angle)],axis=-1)*mask[train,None,:,None]\nsource_harmonic -= np.einsum("nti,nrij->nrtj",base[train],\n    np.einsum("nti,nrtj->nrij",base[train],source_harmonic))\nsource_coefficient = np.linalg.solve(np.einsum("nrti,nrtj->nrij",source_harmonic,source_harmonic),\n    np.einsum("nrti,ntr->nri",source_harmonic,optical_pair)[...,None])[...,0]\nsource_fundamental = np.einsum("nrti,nri->nrt",source_harmonic,source_coefficient)*training_usable[:,:,None]\nobservation_remainder = (mixed[train]-np.einsum("nrt,nr->nt",source_fundamental,optical_gain))*mask[train]\nremainder_energy = np.sum(observation_remainder**2,axis=1)/count[train]\nassert (remainder_energy>0.).all()\nremainder_unit = observation_remainder/np.sqrt(remainder_energy)[:,None]\nremainder_autocovariance = np.fft.irfft(\n    np.abs(np.fft.rfft(remainder_unit,n=2*len(time),axis=1))**2,\n    n=2*len(time),axis=1)[:,:len(time)]/count[train,None]\nlayout_weight = (layout_count[:,None]==count[train][None])*row_weight[None]\nassert (layout_weight.sum(axis=1)>0.).all()\nlayout_weight /= layout_weight.sum(axis=1)[:,None]\nlag = np.abs(np.arange(len(time))[:,None]-np.arange(len(time))[None])\nremainder_covariance = (layout_weight@remainder_autocovariance)[:,lag]\nprojection = np.eye(len(time))[None]*layout_mask[:,:,None]-np.einsum("lti,lsi->lts",layout_base,layout_base)\nnoise_covariance = projection@remainder_covariance@projection\nnoise_covariance *= ((layout_count-2)/np.trace(noise_covariance,axis1=1,axis2=2))[:,None,None]\nnoise_covariance += np.einsum("lti,lsi->lts",layout_base,layout_base) \\\n    +np.eye(len(time))[None]*(~layout_mask)[:,:,None]\nnoise_sign,noise_logdet = np.linalg.slogdet(noise_covariance)\nassert (noise_sign==1).all()\nnoise_inverse = np.linalg.inv(noise_covariance)\nremainder_lag1 = np.sum(remainder_unit[:,1:]*remainder_unit[:,:-1],axis=1)/np.sum(remainder_unit**2,axis=1)\nextra_source_outputs = {"noise_covariance":noise_covariance,\n    "training_observation_remainder_energy":remainder_energy,\n    "training_observation_remainder_lag1":remainder_lag1}\nprint("HIERARCHY_OBSERVATION_REMAINDER","records",len(train_rows),\n    "rms",np.quantile(np.sqrt(remainder_energy),[.1,.5,.9]).tolist(),\n    "lag1",np.quantile(remainder_lag1,[.1,.5,.9]).tolist(),flush=True)\n'
structural_hierarchy_fit_stage = '\nfrom scipy.optimize import minimize\nfrom scipy.special import logsumexp,gammaln,digamma\nfrom joblib import dump\n# All raw cells remain available. Only training experiments supply source labels.\nexec(compile(structural_source_data_stage.split("\\noptical =",1)[0],__file__,"exec"))\ncolored_observation = args.stage=="structural-hierarchy-colored-fit"\nhierarchy_settings = application[{False:"structural_hierarchy",True:"structural_hierarchy_colored"}[colored_observation]]\ntrain_rows,held_rows = np.flatnonzero(train),np.flatnonzero(heldout)\ntraining_groups,training_first,training_group = np.unique(run[train],return_index=True,return_inverse=True)\ntraining_membership = (np.arange(len(training_groups))[:,None]==training_group[None]).astype(float)\ntraining_n = training_membership.sum(axis=1)\nrow_weight = 1./training_n[training_group]\nrow_weight /= row_weight.sum()\nbackground_reference = pd.read_csv(application["source_density"]["background_reference"],encoding="utf-8",\n    float_precision="round_trip").set_index("trace_id").loc[trace_id[train]]\ntraining_period = np.stack([reference.reference_period_h.to_numpy()[train],\n    background_reference.background_period_h.to_numpy()],axis=1)\ntraining_usable = np.stack([qualified[train],background_reference.background_usable.to_numpy()],axis=1)\nperiods = np.r_[np.arange(*application["period_bounds_h"],application["density"]["grid_step_h"]),\n    application["period_bounds_h"][1]]\nperiod_n = len(periods)\ngrid_weight = np.ones(period_n)\ngrid_weight[[0,-1]] = .5\ngrid_weight /= grid_weight.sum()\nassert np.isfinite(training_period[training_usable]).all()\nassert training_period[training_usable].min()>=periods[0] and training_period[training_usable].max()<=periods[-1]\nfilled_period = np.where(training_usable,training_period,periods[0])\nbarycentric = np.maximum(1.-np.abs(periods[None,None]-filled_period[...,None])\n    /application["density"]["grid_step_h"],0.)\nassert np.allclose(barycentric.sum(axis=2)[training_usable],1.)\nsource_group_n = training_membership@training_usable.astype(float)\nsource_weight = training_usable/np.maximum(source_group_n[training_group],1.)\neligible = run[:,None]!=run[train][None]\neligible &= (not native)|(count[:,None]==count[train][None])\nkernel = np.exp(-np.abs(periods[None,None]-filled_period[...,None])/application["risk_tolerance_h"])\nprior = np.einsum("nm,mrp,mr->nrp",eligible,kernel,source_weight,optimize=True)*grid_weight[None,None]\n# Background references are sparse in short records. Pool the other training\n# experiments across durations; target priors retain the existing duration matching.\nbackground_eligible = run[:,None]!=run[train][None]\nprior[:,1] = np.einsum("nm,mp,m->np",background_eligible,kernel[:,1],\n    source_weight[:,1],optimize=True)*grid_weight[None]\nassert (prior.sum(axis=2)>0.).all()\nprior /= prior.sum(axis=2)[...,None]\ntraining_anchor = np.where(training_usable[...,None],barycentric,prior[train])\nlog_anchor = np.where(training_anchor>0.,np.log(np.maximum(training_anchor,np.finfo(float).tiny)),-np.inf)\n\n# Project the same full candidate grid off the exact intercept and linear trend.\nlayout_count,layout_first,layout_index = np.unique(count,return_index=True,return_inverse=True)\nlayout_mask,layout_base = mask[layout_first],base[layout_first]\nnoise_inverse = np.broadcast_to(np.eye(len(time)),(len(layout_count),len(time),len(time))).copy()\nnoise_logdet = np.zeros(len(layout_count))\nexec(compile({True:structural_hierarchy_colored_prepare_stage,False:""}[colored_observation],__file__,"exec"))\nangle = 2.*np.pi*time[None]/periods[:,None]\nharmonic = np.sqrt(2.)*np.stack([np.cos(angle),np.sin(angle)],axis=-1)[None]*layout_mask[:,None,:,None]\ncross_base = np.einsum("lpti,ltj->lpij",harmonic,layout_base)\nharmonic -= np.einsum("ltj,lpij->lpti",layout_base,cross_base)\nharmonic_metric = np.einsum("lts,lpsi->lpti",noise_inverse,harmonic,optimize=True)\ngram = np.einsum("lpti,lqtj->lpqij",harmonic,harmonic_metric,optimize=True)\ngrid_index = np.arange(period_n)\nsingle_gram = gram[:,grid_index,grid_index]\npair_shape = (len(layout_count),period_n,period_n,2,2)\njoint_gram = np.concatenate([\n    np.concatenate([np.broadcast_to(single_gram[:,:,None],pair_shape),gram],axis=-1),\n    np.concatenate([gram.swapaxes(-1,-2),np.broadcast_to(single_gram[:,None],pair_shape)],axis=-1)],axis=-2)\nrhs = np.einsum("nt,lpti->lnpi",mixed,harmonic_metric,optimize=True)[layout_index,np.arange(len(mixed))]\npair_rhs = np.concatenate([\n    np.broadcast_to(rhs[:,:,None],(len(mixed),period_n,period_n,2)),\n    np.broadcast_to(rhs[:,None],(len(mixed),period_n,period_n,2))],axis=-1)\nbase_rss = np.einsum("nt,lts,ns->ln",mixed,noise_inverse,mixed,optimize=True)[layout_index,np.arange(len(mixed))]\ndimension = count-2\nparameter_bounds = np.log(np.finfo(float).eps**np.array([.25,-.25]))\n\n# Distinct Gaussian coefficient variances anchor the named target/background roles.\n# The common observation scale is integrated out; optical additivity is not imposed.\nsource_evidence = lambda log_variance,rows: (\n    precision:=np.exp(-log_variance),\n    matrix:=joint_gram+np.diag(np.repeat(precision,2)),\n    inverse:=np.linalg.inv(matrix),\n    coefficient:=np.einsum("lpqij,npqj->lnpqi",inverse,pair_rhs[rows],optimize=True)[\n        layout_index[rows],np.arange(len(rows))],\n    residual:=base_rss[rows,None,None]-np.sum(pair_rhs[rows]*coefficient,axis=-1),\n    determinant:=np.linalg.slogdet(matrix)[1]+2.*log_variance.sum(),\n    evidence:=-.5*determinant[layout_index[rows]]-.5*noise_logdet[layout_index[rows],None,None]\n        -dimension[rows,None,None]/2.*np.log(residual),\n    inverse_trace:=np.diagonal(inverse,axis1=-2,axis2=-1).reshape(\n        len(layout_count),period_n,period_n,2,2).sum(axis=-1),\n    coefficient_energy:=np.sum(coefficient.reshape(len(rows),period_n,period_n,2,2)**2,axis=-1),\n    derivative:=-.5*(2.-inverse_trace[layout_index[rows]]*precision)\n        +dimension[rows,None,None,None]*coefficient_energy*precision/(2.*residual[...,None]),\n    (evidence,derivative,coefficient))[-1]\nvariance_objective = lambda vector: (\n    result:=source_evidence(vector,train_rows),\n    log_joint:=result[0]+log_anchor[:,0,:,None]+log_anchor[:,1,None,:],\n    log_normalizer:=logsumexp(log_joint,axis=(1,2)),\n    posterior:=np.exp(log_joint-log_normalizer[:,None,None]),\n    (-np.sum(row_weight*log_normalizer),\n        -np.einsum("n,npq,npqr->r",row_weight,posterior,result[1],optimize=True)))[-1]\ninitial_variance = np.full(2,np.log(hierarchy_settings["initial_variance"]))\ninitial_loss,initial_gradient = variance_objective(initial_variance)\nassert np.isfinite(initial_loss) and np.isfinite(initial_gradient).all()\nprint("HIERARCHY_TRAIN",fold,"training_records",len(train_rows),"source_labels",\n    training_usable.sum(axis=0).tolist(),"initial_loss",initial_loss,flush=True)\nvariance_result = minimize(variance_objective,initial_variance,jac=True,method="L-BFGS-B",\n    bounds=np.tile(parameter_bounds,(2,1)),options={"maxiter":hierarchy_settings["variance_maxiter"],\n        "ftol":hierarchy_settings["ftol"],"gtol":hierarchy_settings["gtol"]})\nassert np.isfinite(variance_result.fun) and np.isfinite(variance_result.x).all()\nprint("HIERARCHY_SOURCE_VARIANCE",np.exp(variance_result.x).tolist(),"loss",variance_result.fun,\n    "iterations",variance_result.nit,"status",str(variance_result.message),flush=True)\n\n# Learn how strongly cell-level period distributions vary between training experiments.\nnearest = np.abs(periods[None,None]-filled_period[...,None]).argmin(axis=2)\ncategorical = np.eye(period_n)[nearest]*training_usable[...,None]\ngroup_counts = np.einsum("gn,nrp->grp",training_membership,categorical,optimize=True)\ngroup_total = group_counts.sum(axis=2)\ngroup_prior = prior[train][training_first]\nconcentration_objective = lambda vector: (\n    strength:=np.exp(vector),\n    alpha:=strength[None,:,None]*group_prior,\n    log_probability:=gammaln(strength)[None]-gammaln(strength[None]+group_total)\n        +np.sum(gammaln(alpha+group_counts)-gammaln(alpha),axis=2),\n    derivative:=(digamma(strength)[None]-digamma(strength[None]+group_total)\n        +np.sum(group_prior*(digamma(alpha+group_counts)-digamma(alpha)),axis=2))*strength[None],\n    (-log_probability.sum()/len(training_groups),-derivative.sum(axis=0)/len(training_groups)))[-1]\nconcentration_result = minimize(concentration_objective,\n    np.full(2,np.log(hierarchy_settings["initial_concentration"])),jac=True,method="L-BFGS-B",\n    bounds=np.tile(parameter_bounds,(2,1)),options={"maxiter":hierarchy_settings["concentration_maxiter"],\n        "ftol":hierarchy_settings["ftol"],"gtol":hierarchy_settings["gtol"]})\nstrength = np.exp(concentration_result.x)\nassert np.isfinite(strength).all()\nprint("HIERARCHY_CONCENTRATION",strength.tolist(),"status",str(concentration_result.message),flush=True)\n\nheld_groups,held_first,held_group = np.unique(run[heldout],return_index=True,return_inverse=True)\nheld_membership = (np.arange(len(held_groups))[:,None]==held_group[None]).astype(float)\nheld_n = held_membership.sum(axis=1)\npopulation_prior = prior[heldout][held_first]\nassert np.allclose(population_prior[held_group],prior[heldout])\nheld_evidence,held_gradient,held_coefficient = source_evidence(variance_result.x,held_rows)\ndel held_gradient\npopulation_shape = (len(held_groups),2,period_n)\npopulation_objective = lambda vector: (\n    logits:=vector.reshape(population_shape),\n    log_probability:=logits-logsumexp(logits,axis=2)[...,None],\n    probability:=np.exp(log_probability),\n    log_joint:=held_evidence+log_probability[held_group,0,:,None]+log_probability[held_group,1,None,:],\n    normalizer:=logsumexp(log_joint,axis=(1,2)),\n    posterior:=np.exp(log_joint-normalizer[:,None,None]),\n    responsibilities:=np.stack([posterior.sum(axis=2),posterior.sum(axis=1)],axis=1),\n    group_responsibilities:=np.einsum("gn,nrp->grp",held_membership,responsibilities,optimize=True),\n    value:=-(normalizer.sum()+np.sum(strength[None,:,None]*population_prior*log_probability))/len(held_rows),\n    gradient:=((held_n[:,None,None]+strength[None,:,None])*probability\n        -group_responsibilities-strength[None,:,None]*population_prior)/len(held_rows),\n    (value,gradient.ravel()))[-1]\npopulation_result = minimize(population_objective,np.log(population_prior).ravel(),jac=True,method="L-BFGS-B",\n    options={"maxiter":hierarchy_settings["population_maxiter"],\n        "ftol":hierarchy_settings["ftol"],"gtol":hierarchy_settings["gtol"]})\npopulation_log_probability = population_result.x.reshape(population_shape)\npopulation_log_probability -= logsumexp(population_log_probability,axis=2)[...,None]\npopulation_probability = np.exp(population_log_probability)\njoint_log_mass = np.stack([\n    held_evidence+population_log_probability[held_group,0,:,None]+population_log_probability[held_group,1,None,:],\n    held_evidence+np.log(prior[heldout,0,:,None])+np.log(prior[heldout,1,None,:])],axis=1)\njoint_log_mass -= logsumexp(joint_log_mass,axis=(2,3))[...,None,None]\njoint_mass = np.exp(joint_log_mass)\nmass = joint_mass.sum(axis=3)\nwindow = (np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nscore = mass@window.T\nselected = score.argmax(axis=2)\nestimate = periods[selected]\nconfidence = np.take_along_axis(score,selected[...,None],axis=2)[...,0]\nmethods = np.array({False:["hierarchical_pair_source_window","independent_pair_source_window"],\n    True:["hierarchical_colored_source_window","independent_colored_source_window"]}[colored_observation])\ntarget_coefficient = np.einsum("npq,npqi->npi",joint_mass[:,0],held_coefficient[...,:2],optimize=True)\nbackground_coefficient = np.einsum("npq,npqi->nqi",joint_mass[:,0],held_coefficient[...,2:],optimize=True)\nsource_waveform = np.einsum("lpti,npi->lnt",harmonic,target_coefficient,optimize=True)[\n    layout_index[heldout],np.arange(len(held_rows))]\nbackground_waveform = np.einsum("lpti,npi->lnt",harmonic,background_coefficient,optimize=True)[\n    layout_index[heldout],np.arange(len(held_rows))]\nstem = hierarchy_settings["stem"].with_name(hierarchy_settings["stem"].name\n    +{True:"_native",False:"_common"}[native]+"_fold"+str(fold))\npredictions = pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],2),\n    "method":np.tile(methods,len(held_rows)),"estimate_h":estimate.ravel(),"confidence":confidence.ravel(),\n    "heldout_fold":fold,"heldout_run":np.repeat(run[heldout],2),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    periods=periods,mass=mass,estimate=estimate,confidence=confidence,methods=methods,\n    group_period_mass=population_probability,group_prior=population_prior,\n    group_names=held_groups,group_index=held_group,source_waveform=source_waveform,\n    background_waveform=background_waveform,coefficient_variance=np.exp(variance_result.x),\n    concentration=strength,training_trace_id=trace_id[train],training_groups=training_groups,**extra_source_outputs)\ndump({"model":"empirical_bayes_joint_source_period_populations","configuration":hierarchy_settings,\n    "coefficient_variance":np.exp(variance_result.x),"concentration":strength,\n    "variance_optimization":variance_result,"concentration_optimization":concentration_result,\n    "population_optimization":population_result,"training_trace_id":trace_id[train],\n    "training_groups":training_groups,"training_source_labels":training_usable.sum(axis=0),\n    "heldout_optical_read":False,"target":"optically_separated_target_luminescence_period",\n    "input":"all_unfiltered_cells_from_the_same_experiment"},stem.with_suffix(".joblib"))\nprint("HIERARCHY_POPULATION","iterations",population_result.nit,"status",str(population_result.message),\n    "source_modes",periods[population_probability.argmax(axis=2)].tolist(),flush=True)\nexec(compile(structural_source_readout_stage[\n    structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
