structural_spectral_source_fit_stage = '\nfrom scipy.optimize import minimize\nfrom joblib import dump\nimport torch\nfrom torch import nn\nexec(compile(structural_source_data_stage,__file__,"exec"))\nspectral_settings = application["structural_spectral_source"]\ntorch.set_num_threads(CONFIG["threads"])\ntorch.set_num_interop_threads(CONFIG["threads"])\ntorch.manual_seed(settings["seed"])\nrng = np.random.default_rng(settings["seed"])\nexec(compile(structural_period_flow_fit_stage[\n    structural_period_flow_fit_stage.index("background_raw ="):\n    structural_period_flow_fit_stage.index("layout_count,layout_index")],__file__,"exec"))\nfrequency = np.fft.rfftfreq(length,d=float(time[1]-time[0]))[1:]\nraw_fourier = np.fft.rfft(mixed,axis=-1,norm="ortho")[:,1:]\nsource_fourier = np.fft.rfft(source_unit,axis=-1,norm="ortho")[:,:,1:].transpose(0,2,1)\nraw_spectrum = np.einsum("n,nf->f",row_weight,np.abs(raw_fourier[train])**2)\nsource_spectrum = np.einsum("n,nfr->fr",row_weight,np.abs(source_fourier)**2)\nassert (raw_spectrum>0.).all() and (source_spectrum>0.).all()\ntraining_groups,training_group_index = np.unique(run[train],return_inverse=True)\ngroup_n = len(training_groups)\ngroup_count = np.bincount(training_group_index)\nwidth = spectral_settings["width"]\nencoder = nn.Sequential(nn.Linear(6,width),nn.Tanh(),nn.Linear(width,width+2))\ndecoder = nn.Sequential(nn.Linear(width+5,width),nn.Tanh(),nn.Linear(width,2*5))\nspectral_model = nn.ModuleList([encoder,decoder]).double()\nnn.init.zeros_(decoder[-1].weight)\nnn.init.zeros_(decoder[-1].bias)\nwith torch.no_grad():\n    decoder[-1].bias.reshape(2,5)[:,3] = np.log(.5)\n    decoder[-1].bias.reshape(2,5)[:,4] = np.sqrt(.5)\nencoder_names = tuple(dict(encoder.named_parameters()))\nencoder_shapes = tuple(map(torch.Tensor.size,encoder.parameters()))\nencoder_sizes = tuple(map(torch.Tensor.numel,encoder.parameters()))\ndecoder_names = tuple(dict(decoder.named_parameters()))\ndecoder_shapes = tuple(map(torch.Tensor.size,decoder.parameters()))\ndecoder_sizes = tuple(map(torch.Tensor.numel,decoder.parameters()))\nencoder_size = int(np.sum(encoder_sizes))\ninitial = nn.utils.parameters_to_vector(spectral_model.parameters()).detach().numpy().copy()\nunpack_encoder = lambda vector: dict(zip(encoder_names,map(torch.reshape,\n    torch.split(vector[:encoder_size],encoder_sizes),encoder_shapes)))\nunpack_decoder = lambda vector: dict(zip(decoder_names,map(torch.reshape,\n    torch.split(vector[encoder_size:],decoder_sizes),decoder_shapes)))\nraw_scale_tensor = torch.as_tensor(raw_spectrum,dtype=torch.float64)\nsource_scale_tensor = torch.as_tensor(source_spectrum,dtype=torch.float64)\ntensor_x = torch.as_tensor(raw_fourier[train],dtype=torch.complex128)\ntensor_y = torch.as_tensor(source_fourier,dtype=torch.complex128)\ntensor_groups = torch.as_tensor(training_group_index,dtype=torch.long)\ntensor_count = torch.as_tensor(group_count,dtype=torch.float64)\n# DC is zero after the common affine projection. A possible Nyquist coefficient\n# has one real degree of freedom; every other retained coefficient is complex.\nreal_frequency = (length%2==0)&(np.arange(1,len(frequency)+1)==length//2)\nfrequency_weight = torch.as_tensor(np.where(real_frequency,.5,1.),dtype=torch.float64)\nnoise_real_scale = np.where(real_frequency,1.,1./np.sqrt(2.))\nnoise_imag_scale = np.where(real_frequency,0.,1./np.sqrt(2.))\n# The gating variables are invariant to a common phase rotation or conjugation.\n# Both source fields use every cell in the same experiment, without orthogonality.\ninvariant_features = lambda inputs,groups,number: (\n    counts:=torch.bincount(groups,minlength=number).to(inputs.real.dtype),\n    mean:=inputs.new_zeros((number,len(frequency))).index_add(0,groups,inputs)/counts[:,None],\n    power:=inputs.real.new_zeros((number,len(frequency))).index_add(0,groups,inputs.abs().square())/counts[:,None],\n    mean:=mean[groups],\n    torch.stack([\n        torch.log1p(inputs.abs().square()/raw_scale_tensor),\n        torch.log1p(power[groups]/raw_scale_tensor),\n        torch.log1p(mean.abs().square()/raw_scale_tensor),\n        (inputs*mean.conj()).real/torch.sqrt(\n            (inputs.abs().square()+raw_scale_tensor)*(mean.abs().square()+raw_scale_tensor)),\n        torch.log(source_scale_tensor[:,0]/raw_scale_tensor).expand_as(inputs.real),\n        torch.log(source_scale_tensor[:,1]/raw_scale_tensor).expand_as(inputs.real)],dim=-1))[-1]\nconditional_source = lambda vector,inputs,groups,number: (\n    invariant:=invariant_features(inputs,groups,number),\n    encoded:=torch.func.functional_call(encoder,unpack_encoder(vector),(invariant,)),\n    logits:=encoded[:,:,width:],\n    index:=groups[:,None,None].expand_as(logits),\n    maximum:=logits.new_full((number,len(frequency),2),-torch.inf).scatter_reduce(\n        0,index,logits,reduce="amax",include_self=True),\n    attention:=(logits-maximum[groups]).exp(),\n    attention:=attention/attention.new_zeros((number,len(frequency),2)).index_add(0,groups,attention)[groups],\n    fields:=inputs.new_zeros((number,len(frequency),2)).index_add(\n        0,groups,attention*inputs[:,:,None])[groups],\n    field_power:=fields.abs().square(),\n    cross:=(inputs[:,:,None]*fields.conj()).real/torch.sqrt(\n        (inputs.abs().square()+raw_scale_tensor)[:,:,None]*(field_power+raw_scale_tensor[None,:,None])),\n    field_cross:=(fields[:,:,0]*fields[:,:,1].conj()).real/torch.sqrt(\n        (field_power[:,:,0]+raw_scale_tensor)*(field_power[:,:,1]+raw_scale_tensor)),\n    decoder_input:=torch.cat([encoded[:,:,:width],\n        torch.log1p(field_power/raw_scale_tensor[None,:,None]),cross,field_cross[:,:,None]],dim=-1),\n    output:=torch.func.functional_call(decoder,unpack_decoder(vector),(decoder_input,)).reshape(\n        len(inputs),len(frequency),2,5),\n    basis:=torch.cat([inputs[:,:,None],fields],dim=-1),\n    mean:=torch.einsum("nfrk,nfk->nfr",output[:,:,:,:3].to(inputs.dtype),basis)\n        *torch.sqrt(source_scale_tensor/raw_scale_tensor[:,None]),\n    log_private:=output[:,:,:,3],\n    loading:=output[:,:,:,4],\n    (mean,log_private,loading))[-1]\ngroup_gaussian_loss = lambda mean,log_private,loading: (\n    error:=(tensor_y-mean)/torch.sqrt(source_scale_tensor),\n    precision:=torch.exp(-log_private),\n    group_logdet:=log_private.new_zeros((group_n,len(frequency),2)).index_add(0,tensor_groups,log_private),\n    group_energy:=log_private.new_zeros((group_n,len(frequency),2)).index_add(\n        0,tensor_groups,error.abs().square()*precision),\n    group_snr:=log_private.new_zeros((group_n,len(frequency),2)).index_add(\n        0,tensor_groups,loading.square()*precision),\n    group_projection:=error.new_zeros((group_n,len(frequency),2)).index_add(\n        0,tensor_groups,error*loading*precision),\n    group_loss:=group_logdet+torch.log1p(group_snr)+group_energy\n        -group_projection.abs().square()/(1.+group_snr),\n    ((group_loss/tensor_count[:,None,None])*frequency_weight[None,:,None]).mean())[-1]\nobjective = lambda vector: group_gaussian_loss(*conditional_source(vector,tensor_x,tensor_groups,group_n)) \\\n    +settings["weight_decay"]*vector.square().mean()\nautograd_objective = torch.func.grad_and_value(objective)\nto_scipy = lambda gradient,value: (value.detach().item(),gradient.detach().numpy())\nscipy_objective = lambda vector: to_scipy(*autograd_objective(torch.as_tensor(vector,dtype=torch.float64)))\ninitial_loss,initial_gradient = scipy_objective(initial)\nassert np.isfinite(initial_loss) and np.isfinite(initial_gradient).all()\nloss_history = [[0,initial_loss]]\nprint("SPECTRAL_SOURCE_TRAIN",fold,"natural_records",int(train.sum()),"experiments",group_n,\n    "frequencies",len(frequency),"parameters",len(initial),"initial_loss",initial_loss,\n    "seed",settings["seed"],flush=True)\nresult = minimize(scipy_objective,initial,jac=True,method="L-BFGS-B",\n    callback=lambda intermediate_result:(loss_history.append([len(loss_history),float(intermediate_result.fun)]),\n        len(loss_history)%50==0 and print("SPECTRAL_SOURCE_PROGRESS",fold,len(loss_history)-1,\n            intermediate_result.fun,flush=True)),\n    options={"maxiter":spectral_settings["maxiter"],"ftol":spectral_settings["ftol"],\n        "gtol":settings["gtol"],"maxls":settings["maxls"]})\nstem = spectral_settings["stem"].with_name(spectral_settings["stem"].name+\n    {True:"_native",False:"_common"}[native]+"_fold"+str(fold))\ndump({"parameters":result.x,"encoder_names":encoder_names,"encoder_shapes":encoder_shapes,\n    "decoder_names":decoder_names,"decoder_shapes":decoder_shapes,"training_trace_id":trace_id[train],\n    "configuration":spectral_settings,"optimization":result,"training_loss_history":np.asarray(loss_history),\n    "training_row_weight":row_weight,"training_groups":training_groups,\n    "raw_spectrum":raw_spectrum,"source_spectrum":source_spectrum,"frequency":frequency,\n    "model":"same_frequency_population_conditional_complex_gaussian_sources",\n    "target":"unit_RMS_optically_separated_target_and_background_luminescence",\n    "input":"all_unfiltered_cells_from_the_same_experiment","seed":settings["seed"],\n    "heldout_optical_read":False},stem.with_suffix(".joblib"))\nprint("SPECTRAL_SOURCE_OPTIMIZED","loss",result.fun,"iterations",result.nit,\n    "status",str(result.message),flush=True)\nheld_groups,held_group_index = np.unique(run[heldout],return_inverse=True)\nparameters = torch.as_tensor(result.x,dtype=torch.float64)\nheld_mean,held_log_private,held_loading = conditional_source(parameters,\n    torch.as_tensor(raw_fourier[heldout],dtype=torch.complex128),\n    torch.as_tensor(held_group_index,dtype=torch.long),len(held_groups))\nheld_mean = held_mean.detach().numpy()\nheld_private = np.exp(held_log_private.detach().numpy())*source_spectrum\nheld_loading = held_loading.detach().numpy()*np.sqrt(source_spectrum)\nparticle_n = spectral_settings["posterior_particles"]\nprivate_noise = rng.standard_normal((int(heldout.sum()),particle_n,len(frequency),2))*noise_real_scale[None,None,:,None]\nprivate_noise = private_noise+1j*rng.standard_normal(private_noise.shape)*noise_imag_scale[None,None,:,None]\nshared_noise = rng.standard_normal((len(held_groups),particle_n,len(frequency),2))*noise_real_scale[None,None,:,None]\nshared_noise = shared_noise+1j*rng.standard_normal(shared_noise.shape)*noise_imag_scale[None,None,:,None]\nsample_fourier = held_mean[:,None]+np.sqrt(held_private[:,None])*private_noise \\\n    +held_loading[:,None]*shared_noise[held_group_index]\nsource_pair_samples = np.fft.irfft(np.pad(sample_fourier,((0,0),(0,0),(1,0),(0,0))),\n    n=length,axis=2,norm="ortho").transpose(0,1,3,2)*mask[heldout,None,None]\nsource_pair_samples -= np.einsum("nti,nqri->nqrt",base[heldout],\n    np.einsum("nti,nqrt->nqri",base[heldout],source_pair_samples))\nprior_fourier = np.sqrt(source_spectrum)[None,None]*private_noise\nprior_pair = np.fft.irfft(np.pad(prior_fourier,((0,0),(0,0),(1,0),(0,0))),\n    n=length,axis=2,norm="ortho").transpose(0,1,3,2)*mask[heldout,None,None]\nprior_pair -= np.einsum("nti,nqri->nqrt",base[heldout],\n    np.einsum("nti,nqrt->nqri",base[heldout],prior_pair))\nassert np.isfinite(source_pair_samples).all() and (held_private>0.).all()\nsource_samples = source_pair_samples[:,:,0]\nprior_samples = prior_pair[:,:,0]\n# Integrate each source law through the same proper H1 likelihood with uniform\n# period measure. No selected particle, learned temperature or period-only head.\nreadout_code = structural_source_readout_stage.split("prior_labels =",1)[0].replace(\n    "waves = np.stack([prediction,mixed[heldout]],axis=1)",\n    "waves = np.concatenate([source_samples,prior_samples],axis=1)").replace(\n    "np.repeat(held_mask,2,axis=0)","np.repeat(held_mask,2*particle_n,axis=0)").replace(\n    "np.repeat(held_count,2)","np.repeat(held_count,2*particle_n)")\nexec(compile(readout_code,__file__,"exec"))\nparticle_logmass = log_evidence.reshape(int(heldout.sum()),2,particle_n,len(periods))+np.log(grid_weight)[None,None,None]\nparticle_mass = np.exp(particle_logmass-logsumexp(particle_logmass,axis=-1)[...,None])\nmass = particle_mass.mean(axis=2)\nprior_layout,prior_layout_index = np.unique(count[heldout],return_inverse=True)\nprior_membership = (prior_layout[:,None]==count[heldout][None]).astype(float)\npooled_prior_mass = prior_membership@mass[:,1]/prior_membership.sum(axis=1)[:,None]\nmass[:,1] = pooled_prior_mass[prior_layout_index]\nwindow = (np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nscore = mass@window.T\nselected = score.argmax(axis=2)\nestimate = periods[selected]\nconfidence = np.take_along_axis(score,selected[...,None],axis=2)[...,0]\nmethods = np.array([spectral_settings["method"],"spectral_training_prior_window"])\npredictions = pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],2),\n    "method":np.tile(methods,int(heldout.sum())),"estimate_h":estimate.ravel(),\n    "confidence":confidence.ravel(),"heldout_fold":fold,"heldout_run":np.repeat(run[heldout],2),\n    "method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    source_samples=source_samples,background_samples=source_pair_samples[:,:,1],\n    prior_samples=prior_samples,background_prior_samples=prior_pair[:,:,1],\n    fourier_mean=held_mean,fourier_private_variance=held_private,fourier_shared_loading=held_loading,\n    periods=periods,mass=mass,particle_mass=particle_mass,estimate=estimate,confidence=confidence,methods=methods,\n    training_trace_id=trace_id[train],training_groups=training_groups,\n    training_loss_history=np.asarray(loss_history),training_source_energy=source_energy)\nprint("SPECTRAL_SOURCE_INFERENCE","source_rms_quantiles",\n    np.quantile(np.sqrt(np.sum(source_pair_samples**2,axis=3)/count[heldout,None,None]),\n        [.1,.5,.9],axis=(0,1)).tolist(),flush=True)\nevaluation_code = structural_source_readout_stage[structural_source_readout_stage.index("# Join held-out reference"):]\nexec(compile(evaluation_code,__file__,"exec"))\nraise SystemExit(0)\n'
