structural_dynamics_source_fit_stage = '\nfrom scipy.optimize import minimize\nfrom scipy.special import logsumexp,gammaln,digamma,roots_jacobi\nfrom joblib import dump\nimport torch\nexec(compile(structural_source_data_stage,__file__,"exec"))\ndynamics_settings = application["structural_dynamics_source"]\nhierarchy_settings = application["structural_hierarchy"]\ntorch.set_num_threads(CONFIG["threads"])\ntorch.set_num_interop_threads(CONFIG["threads"])\n# The same training-only role labels and period priors are used by the existing\n# joint-source comparison. Every unqualified optical waveform remains in the fit.\nexec(compile(structural_hierarchy_fit_stage[\n    structural_hierarchy_fit_stage.index("train_rows,held_rows ="):\n    structural_hierarchy_fit_stage.index("# Project the same full candidate grid")],__file__,"exec"))\nexec(compile(structural_period_flow_fit_stage[\n    structural_period_flow_fit_stage.index("background_raw ="):\n    structural_period_flow_fit_stage.index("layout_count,layout_index")],__file__,"exec"))\nlayout_count,layout_first,layout_index = np.unique(count,return_index=True,return_inverse=True)\nlayout_mask,layout_base = mask[layout_first],base[layout_first]\nprojection = np.eye(length)[None]*layout_mask[:,:,None]-np.einsum("lti,lsi->lts",layout_base,layout_base)\npadding = np.einsum("lti,lsi->lts",layout_base,layout_base)+np.eye(length)[None]*(~layout_mask)[:,:,None]\ndimension = count-2\nlag = np.abs(time[:,None]-time[None])\ntensor_projection = torch.as_tensor(projection,dtype=torch.float64)\ntensor_padding = torch.as_tensor(padding,dtype=torch.float64)\ntensor_layout_dimension = torch.as_tensor(layout_count-2,dtype=torch.float64)\ntensor_lag = torch.as_tensor(lag,dtype=torch.float64)\ntensor_periods = torch.as_tensor(periods,dtype=torch.float64)\ntensor_source = torch.as_tensor(source_unit,dtype=torch.float64)\ntensor_source_weight = torch.as_tensor(row_weight,dtype=torch.float64)\ntensor_anchor = torch.as_tensor(log_anchor,dtype=torch.float64)\ntensor_layout_index = torch.as_tensor(layout_index[train],dtype=torch.long)\ntensor_rows = torch.arange(int(train.sum()))\ntensor_dimension = torch.as_tensor(dimension[train],dtype=torch.float64)\n# A damped two-dimensional rotating state has covariance\n# exp(-|dt|/(cycles*period))*cos(2*pi*dt/period). The OU component represents\n# source fluctuations not explained by a persistent oscillation.\ndynamic_kernel = lambda vector: (\n    parameters:=vector.reshape(2,3),\n    cycles:=parameters[:,0].exp(),\n    noise_fraction:=parameters[:,1].sigmoid(),\n    correlation_h:=parameters[:,2].exp(),\n    oscillation:=torch.exp(-tensor_lag[None,None]/(cycles[:,None,None,None]\n        *tensor_periods[None,:,None,None]))*torch.cos(\n            2.*torch.pi*tensor_lag[None,None]/tensor_periods[None,:,None,None]),\n    remainder:=torch.exp(-tensor_lag[None,None]/correlation_h[:,None,None,None]),\n    kernel:=(1.-noise_fraction[:,None,None,None])*oscillation+noise_fraction[:,None,None,None]*remainder,\n    kernel:=tensor_projection[:,None,None]@kernel[None]@tensor_projection[:,None,None],\n    trace:=kernel.diagonal(dim1=-2,dim2=-1).sum(dim=-1),\n    kernel*(tensor_layout_dimension[:,None,None]/trace)[...,None,None]+tensor_padding[:,None,None])[-1]\noptical_source_objective = lambda vector: (\n    covariance:=dynamic_kernel(vector),\n    cholesky:=torch.linalg.cholesky(covariance),\n    inverse:=torch.cholesky_inverse(cholesky),\n    quadratic:=torch.einsum("nrt,lrptu,nru->lnrp",tensor_source,inverse,tensor_source)[\n        tensor_layout_index,tensor_rows],\n    determinant:=2.*torch.log(cholesky.diagonal(dim1=-2,dim2=-1)).sum(dim=-1),\n    evidence:=-.5*determinant[tensor_layout_index]\n        -.5*tensor_dimension[:,None,None]*torch.log(quadratic),\n    -(tensor_source_weight[:,None]*torch.logsumexp(evidence+tensor_anchor,dim=-1)).sum()/2.)[-1]\noptical_gradient = torch.func.grad_and_value(optical_source_objective)\nto_scipy = lambda gradient,value:(value.detach().item(),gradient.detach().numpy())\noptical_objective = lambda vector:to_scipy(*optical_gradient(torch.as_tensor(vector,dtype=torch.float64)))\ninitial = np.tile([0.,0.,np.log(float(time[1]-time[0]))],2)\nparameter_bounds = np.log(np.finfo(float).eps**np.array([.25,-.25]))\ninitial_loss,initial_gradient = optical_objective(initial)\nassert np.isfinite(initial_loss) and np.isfinite(initial_gradient).all()\nprint("DYNAMICS_SOURCE_TRAIN",fold,"natural_records",int(train.sum()),"groups",len(training_groups),\n    "qualified_roles",training_usable.sum(axis=0).tolist(),"initial_loss",initial_loss,flush=True)\nloss_history = [[0,initial_loss]]\nsource_result = minimize(optical_objective,initial,jac=True,method="L-BFGS-B",\n    bounds=np.tile(parameter_bounds,(len(initial),1)),\n    callback=lambda intermediate_result:(loss_history.append([len(loss_history),float(intermediate_result.fun)]),\n        len(loss_history)%10==0 and print("DYNAMICS_SOURCE_PROGRESS",fold,len(loss_history)-1,\n            intermediate_result.fun,flush=True)),\n    options={"maxiter":dynamics_settings["maxiter"],"ftol":dynamics_settings["ftol"],\n        "gtol":dynamics_settings["gtol"],"maxls":settings["maxls"]})\nsource_parameters = source_result.x.reshape(2,3)\nsource_kernel = dynamic_kernel(torch.as_tensor(source_result.x,dtype=torch.float64)).detach().numpy()\nprint("DYNAMICS_SOURCE_OPTIMIZED","cycles",np.exp(source_parameters[:,0]).tolist(),\n    "OU_fraction",(1./(1.+np.exp(-source_parameters[:,1]))).tolist(),\n    "OU_correlation_h",np.exp(source_parameters[:,2]).tolist(),"loss",source_result.fun,\n    "iterations",source_result.nit,"status",str(source_result.message),flush=True)\n# Learn the observation relation from the real paired sources. Their remainder\n# is retained as a stochastic measurement process; no exact optical sum is imposed.\noptical_pair = source_pair.transpose(0,2,1)\noptical_gain = np.linalg.solve(np.einsum("nti,ntj->nij",optical_pair,optical_pair),\n    np.einsum("nti,nt->ni",optical_pair,mixed[train])[...,None])[...,0]\nobservation_remainder = (mixed[train]-np.einsum("ntr,nr->nt",optical_pair,optical_gain))*mask[train]\nremainder_energy = np.sum(observation_remainder**2,axis=1)/count[train]\nassert (remainder_energy>0.).all()\nremainder_unit = observation_remainder/np.sqrt(remainder_energy)[:,None]\neffective_source_energy = optical_gain**2*source_energy\nfraction = effective_source_energy[:,0]/effective_source_energy.sum(axis=1)\nassert ((fraction>0.)&(fraction<1.)).all()\nsignal_fraction = np.sum(row_weight*effective_source_energy.sum(axis=1)\n    /(effective_source_energy.sum(axis=1)+remainder_energy))\nfraction_statistics = np.sum(row_weight[:,None]*np.column_stack([np.log(fraction),np.log1p(-fraction)]),axis=0)\nmixing_objective = lambda vector:(\n    shape:=np.exp(vector),\n    value:=-np.sum((shape-1.)*fraction_statistics)+np.sum(gammaln(shape))-gammaln(shape.sum()),\n    gradient:=shape*(-fraction_statistics+digamma(shape)-digamma(shape.sum())),\n    (float(value),gradient))[-1]\nmixing_result = minimize(mixing_objective,np.zeros(2),jac=True,method="L-BFGS-B",\n    bounds=np.tile(parameter_bounds,(2,1)),options={"maxiter":dynamics_settings["maxiter"],\n        "ftol":dynamics_settings["ftol"],"gtol":dynamics_settings["gtol"]})\nmixing_shape = np.exp(mixing_result.x)\nnodes,node_weight = roots_jacobi(dynamics_settings["quadrature_order"],mixing_shape[1]-1.,mixing_shape[0]-1.)\nmixing_fraction,mixing_weight = (nodes+1.)/2.,node_weight/node_weight.sum()\nassert np.allclose(np.sum(mixing_weight*mixing_fraction),mixing_shape[0]/mixing_shape.sum())\nremainder_autocovariance = np.fft.irfft(\n    np.abs(np.fft.rfft(remainder_unit,n=2*length,axis=1))**2,n=2*length,axis=1)[:,:length]/count[train,None]\nlayout_weight = (layout_count[:,None]==count[train][None])*row_weight[None]\nlayout_weight /= layout_weight.sum(axis=1)[:,None]\nlag_index = np.abs(np.arange(length)[:,None]-np.arange(length)[None])\nremainder_covariance = (layout_weight@remainder_autocovariance)[:,lag_index]\nnoise_covariance = projection@remainder_covariance@projection\nnoise_covariance *= ((layout_count-2)/np.trace(noise_covariance,axis1=1,axis2=2))[:,None,None]\nnoise_covariance += padding\nassert (np.linalg.eigvalsh(noise_covariance)>0.).all()\nprint("DYNAMICS_OBSERVATION","mixing_beta",mixing_shape.tolist(),"signal_fraction",signal_fraction,\n    "source_fraction_quantiles",np.quantile(fraction,[.1,.5,.9]).tolist(),\n    "remainder_rms_quantiles",np.quantile(np.sqrt(remainder_energy),[.1,.5,.9]).tolist(),flush=True)\n# Dense finite-window covariance retains the within-trajectory coupling that a\n# product of independent Fourier coefficients omits. Vmap chunks only memory.\nheld_layout,held_layout_index = np.unique(layout_index[heldout],return_inverse=True)\ncase_index = np.stack(np.meshgrid(held_layout,np.arange(period_n),np.arange(period_n),\n    np.arange(len(mixing_fraction)),indexing="ij"),axis=-1).reshape(-1,4)\ntensor_case = torch.as_tensor(case_index,dtype=torch.long)\ntensor_kernel = torch.as_tensor(source_kernel.reshape(-1,length,length),dtype=torch.float64)\ntensor_noise = torch.as_tensor(noise_covariance,dtype=torch.float64)\ntensor_mixing = torch.as_tensor(mixing_fraction,dtype=torch.float64)\ntensor_held = torch.as_tensor(mixed[heldout].T.copy(),dtype=torch.float64)\ntensor_held_dimension = torch.as_tensor(dimension[heldout],dtype=torch.float64)\ncase_evidence = lambda case:(\n    target_kernel:=torch.index_select(tensor_kernel,0,(case[0]*2*period_n+case[1]).reshape(1))[0],\n    background_kernel:=torch.index_select(tensor_kernel,0,((case[0]*2+1)*period_n+case[2]).reshape(1))[0],\n    noise:=torch.index_select(tensor_noise,0,case[0].reshape(1))[0],\n    proportion:=torch.index_select(tensor_mixing,0,case[3].reshape(1))[0],\n    covariance:=signal_fraction*(proportion*target_kernel+(1.-proportion)*background_kernel)\n        +(1.-signal_fraction)*noise,\n    cholesky:=torch.linalg.cholesky(covariance),\n    inverse_y:=torch.cholesky_solve(tensor_held,cholesky),\n    quadratic:=(tensor_held*inverse_y).sum(dim=0),\n    determinant:=2.*torch.log(cholesky.diagonal()).sum(),\n    -.5*determinant-.5*tensor_held_dimension*torch.log(quadratic))[-1]\nprint("DYNAMICS_SOURCE_INFERENCE","covariance_cases",len(case_index),"heldout_records",int(heldout.sum()),\n    "quadrature_nodes",len(mixing_fraction),flush=True)\ncase_log_evidence = torch.vmap(case_evidence,chunk_size=dynamics_settings["inference_chunk_size"])(\n    tensor_case).detach().numpy()\ncase_log_evidence = case_log_evidence.reshape(len(held_layout),period_n,period_n,\n    len(mixing_fraction),int(heldout.sum()))\ncase_log_evidence = case_log_evidence[held_layout_index,:,:,:,np.arange(int(heldout.sum()))]\nheld_evidence = logsumexp(case_log_evidence+np.log(mixing_weight)[None,None,None],axis=3)\nassert held_evidence.shape==(int(heldout.sum()),period_n,period_n)\ndel case_log_evidence\n# The existing empirical-Bayes population update uses only the unfiltered\n# held-out records. Its source-label priors and concentration use training runs.\nexec(compile(structural_hierarchy_fit_stage[\n    structural_hierarchy_fit_stage.index("# Learn how strongly cell-level period distributions"):\n    structural_hierarchy_fit_stage.index("held_evidence,held_gradient,held_coefficient =")],__file__,"exec"))\nexec(compile(structural_hierarchy_fit_stage[\n    structural_hierarchy_fit_stage.index("population_shape ="):\n    structural_hierarchy_fit_stage.index("methods = np.array")],__file__,"exec"))\nmethods = np.array(dynamics_settings["methods"])\nstem = dynamics_settings["stem"].with_name(dynamics_settings["stem"].name+\n    {True:"_native",False:"_common"}[native]+"_fold"+str(fold))\npredictions = pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],len(methods)),\n    "method":np.tile(methods,int(heldout.sum())),"estimate_h":estimate.ravel(),\n    "confidence":confidence.ravel(),"heldout_fold":fold,\n    "heldout_run":np.repeat(run[heldout],len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    periods=periods,mass=mass,joint_mass=joint_mass,estimate=estimate,confidence=confidence,methods=methods,\n    group_period_mass=population_probability,group_prior=population_prior,\n    group_names=held_groups,group_index=held_group,source_parameters=source_parameters,\n    source_kernel=source_kernel,noise_covariance=noise_covariance,\n    mixing_shape=mixing_shape,mixing_fraction=mixing_fraction,mixing_weight=mixing_weight,\n    signal_fraction=signal_fraction,concentration=strength,training_trace_id=trace_id[train],\n    training_groups=training_groups,training_loss_history=np.asarray(loss_history),\n    training_observation_remainder_energy=remainder_energy,\n    training_effective_source_energy=effective_source_energy)\ndump({"model":"named_damped_oscillator_source_period_inference","configuration":dynamics_settings,\n    "source_optimization":source_result,"mixing_optimization":mixing_result,\n    "concentration_optimization":concentration_result,"population_optimization":population_result,\n    "source_parameters":source_parameters,"mixing_shape":mixing_shape,"signal_fraction":signal_fraction,\n    "training_trace_id":trace_id[train],"training_groups":training_groups,\n    "training_source_labels":training_usable.sum(axis=0),"heldout_optical_read":False,\n    "target":"optically_separated_target_luminescence_period",\n    "input":"all_unfiltered_cells_from_the_same_experiment"},stem.with_suffix(".joblib"))\nprint("DYNAMICS_POPULATION","iterations",population_result.nit,"status",str(population_result.message),\n    "source_modes",periods[population_probability.argmax(axis=2)].tolist(),flush=True)\nexec(compile(structural_source_readout_stage[\n    structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
