structural_population_state_fit_stage = '\nfrom scipy.optimize import minimize\nfrom scipy.special import logsumexp\nfrom joblib import dump\nimport torch\nexec(compile(structural_source_data_stage,__file__,"exec"))\nstate_settings = application["structural_population_state"]\nassert not native\ntorch.set_num_threads(CONFIG["threads"])\ntorch.set_num_interop_threads(CONFIG["threads"])\n# Reuse the completed source-dynamics fit on exactly these training records.\n# No held-out optical measurements enter the population likelihood or priors.\nexec(compile(structural_hierarchy_fit_stage[\n    structural_hierarchy_fit_stage.index("train_rows,held_rows ="):\n    structural_hierarchy_fit_stage.index("# Project the same full candidate grid")],__file__,"exec"))\ndynamics_stem = application["structural_dynamics_source"]["stem"].with_name(\n    application["structural_dynamics_source"]["stem"].name+"_common_fold"+str(fold))\ndynamics_bank = np.load(dynamics_stem.with_suffix(".npz"))\nassert np.array_equal(dynamics_bank["training_trace_id"],trace_id[train])\nassert np.array_equal(dynamics_bank["time"],time)\nassert np.unique(count).size==1\nlength = len(time)\ndimension = length-2\nprojection_basis = np.linalg.qr(base[0],mode="complete")[0][:,2:]\nassert np.allclose(projection_basis.T@base[0],0.)\nnoise_covariance = projection_basis.T@dynamics_bank["noise_covariance"][0]@projection_basis\nnoise_precision = np.linalg.inv(noise_covariance)\nsource_parameters = dynamics_bank["source_parameters"]\nsource_cycles = np.exp(source_parameters[:,0])\nsource_ou_fraction = 1./(1.+np.exp(-source_parameters[:,1]))\nsource_ou_h = np.exp(source_parameters[:,2])\nmixing_shape = dynamics_bank["mixing_shape"]\nsignal_fraction = float(dynamics_bank["signal_fraction"])\nloading_variance = signal_fraction*np.array([mixing_shape[0],mixing_shape[1]])/mixing_shape.sum()/2.\nheld_groups,held_group_index = np.unique(run[heldout],return_inverse=True)\nheld_n = np.bincount(held_group_index)\ngroup_n = len(held_groups)\nheld_total = int(heldout.sum())\nslot = pd.Series(held_group_index).groupby(held_group_index,sort=False).cumcount().to_numpy()\ngroup_capacity = int(held_n.max())\npacked_index = np.full((group_n,group_capacity),held_total,dtype=int)\npacked_index[held_group_index,slot] = np.arange(held_total)\npacked_mask = packed_index<held_total\nheld_y = mixed[heldout]@projection_basis\npacked_y = np.pad(held_y,((0,1),(0,0)))[packed_index]\n# All raw spatial modes stay in the likelihood. SVD provides only an initial\n# loading orientation; both named source loadings remain free during fitting.\nleft,singular,right = np.linalg.svd(packed_y,full_matrices=False)\ninitial_loading = (left[:,:,:4]*singular[:,None,:4]/np.sqrt(dimension))[:,:,[2,3,0,1]]\ninitial_loading = initial_loading[held_group_index,slot]\ninitial_noise = np.clip(1.-signal_fraction,*state_settings["noise_variance_bounds"])\nwindow = (np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\ninitial_period = periods[(prior[heldout]@window.T).argmax(axis=-1)]\ninitial_period = initial_period[np.unique(held_group_index,return_index=True)[1]]\ninitial = np.concatenate([initial_loading.ravel(),np.full(held_total,np.log(initial_noise)),\n    initial_period.ravel()])\nloading_size = held_total*4\nnoise_end = loading_size+held_total\ntensor_y = torch.as_tensor(packed_y,dtype=torch.float64)\ntensor_mask = torch.as_tensor(packed_mask,dtype=torch.float64)\ntensor_index = torch.as_tensor(packed_index,dtype=torch.long)\ntensor_n = torch.as_tensor(held_n,dtype=torch.float64)\ntensor_basis = torch.as_tensor(projection_basis,dtype=torch.float64)\ntensor_precision = torch.as_tensor(noise_precision,dtype=torch.float64)\ntensor_noise_logdet = torch.as_tensor(np.linalg.slogdet(noise_covariance)[1],dtype=torch.float64)\ntensor_lag = torch.as_tensor(time[:,None]-time[None],dtype=torch.float64)\ntensor_cycles = torch.as_tensor(source_cycles,dtype=torch.float64)\ntensor_ou_fraction = torch.as_tensor(source_ou_fraction,dtype=torch.float64)\ntensor_ou_h = torch.as_tensor(source_ou_h,dtype=torch.float64)\ntensor_loading_variance = torch.as_tensor(np.repeat(loading_variance,2),dtype=torch.float64)\ntensor_labels = torch.as_tensor(filled_period.T,dtype=torch.float64)\nperiod_weight = source_weight.T/source_weight.sum(axis=0)[:,None]\ntensor_period_logweight = torch.as_tensor(np.where(period_weight>0.,\n    np.log(np.maximum(period_weight,np.finfo(float).tiny)),-np.inf),dtype=torch.float64)\nrole_identity = torch.eye(2,dtype=torch.float64)\n# Each source has a two-dimensional damped rotating state plus the OU source\n# fluctuations already learned from real optical training trajectories.\nstate_covariance = lambda source_period: (\n    damping:=torch.exp(-tensor_lag.abs()[None,None]/\n        (tensor_cycles[None,:,None,None]*source_period[:,:,None,None])),\n    phase:=2.*torch.pi*tensor_lag[None,None]/source_period[:,:,None,None],\n    ou:=torch.exp(-tensor_lag.abs()[None,None]/tensor_ou_h[None,:,None,None]),\n    cosine:=(1.-tensor_ou_fraction[None,:,None,None])*damping*torch.cos(phase)\n        +tensor_ou_fraction[None,:,None,None]*ou,\n    sine:=(1.-tensor_ou_fraction[None,:,None,None])*damping*torch.sin(phase),\n    cosine:=tensor_basis.T@cosine@tensor_basis,\n    sine:=tensor_basis.T@sine@tensor_basis,\n    scale:=dimension/cosine.diagonal(dim1=-2,dim2=-1).sum(dim=-1),\n    cosine:=cosine*scale[:,:,None,None],\n    sine:=sine*scale[:,:,None,None],\n    role_covariance:=torch.cat([torch.cat([cosine,-sine],dim=-1),\n        torch.cat([sine,cosine],dim=-1)],dim=-2),\n    torch.einsum("grij,rs->grisj",role_covariance,role_identity).reshape(group_n,4*dimension,4*dimension))[-1]\n# Exact Gaussian marginal likelihood of all cells and all recorded time points.\n# The Woodbury system is indexed by latent coordinate then projected time.\npopulation_state = lambda vector: (\n    loading:=vector[:loading_size].reshape(held_total,4),\n    lognoise:=vector[loading_size:noise_end],\n    source_period:=vector[noise_end:].reshape(group_n,2),\n    loading:=torch.cat([loading,torch.zeros((1,4),dtype=torch.float64)],dim=0)[tensor_index],\n    lognoise:=torch.cat([lognoise,torch.zeros(1,dtype=torch.float64)])[tensor_index],\n    weight:=tensor_mask*torch.exp(-lognoise),\n    covariance:=state_covariance(source_period),\n    prior_cholesky:=torch.linalg.cholesky(covariance),\n    prior_precision:=torch.cholesky_inverse(prior_cholesky),\n    spatial_gram:=torch.einsum("gnc,gn,gnk->gck",loading,weight,loading),\n    precision:=prior_precision+torch.einsum("gck,tu->gctku",\n        spatial_gram,tensor_precision).reshape(group_n,4*dimension,4*dimension),\n    cholesky:=torch.linalg.cholesky(precision),\n    rhs:=torch.einsum("gnc,gn,gnt,tu->gcu",loading,weight,tensor_y,tensor_precision).reshape(group_n,-1),\n    posterior_mean:=torch.cholesky_solve(rhs[:,:,None],cholesky)[:,:,0],\n    quadratic:=torch.einsum("gnt,tu,gnu,gn->g",tensor_y,tensor_precision,tensor_y,weight)\n        -(rhs*posterior_mean).sum(dim=-1),\n    determinant:=dimension*(lognoise*tensor_mask).sum(dim=1)+tensor_n*tensor_noise_logdet\n        +2.*torch.log(prior_cholesky.diagonal(dim1=-2,dim2=-1)).sum(dim=-1)\n        +2.*torch.log(cholesky.diagonal(dim1=-2,dim2=-1)).sum(dim=-1),\n    loading_penalty:=.5*(loading.square()/tensor_loading_variance[None,None]).sum(dim=(1,2)),\n    period_penalty:=-torch.logsumexp(\n        -torch.abs(source_period[:,:,None]-tensor_labels[None])/application["risk_tolerance_h"]\n        +tensor_period_logweight[None],dim=-1).sum(dim=1),\n    loss:=((.5*(quadratic+determinant)+loading_penalty+period_penalty)/(tensor_n*dimension)).mean(),\n    (loss,posterior_mean,cholesky,loading,lognoise,source_period,covariance,quadratic,determinant))[-1]\npopulation_objective = lambda vector:population_state(vector)[0]\npopulation_gradient = torch.func.grad_and_value(population_objective)\nto_scipy = lambda gradient,value:(value.detach().item(),gradient.detach().numpy())\nscipy_objective = lambda vector:to_scipy(*population_gradient(torch.as_tensor(vector,dtype=torch.float64)))\nparameter_bounds = np.concatenate([\n    np.tile([-np.inf,np.inf],(loading_size,1)),\n    np.tile(np.log(state_settings["noise_variance_bounds"]),(held_total,1)),\n    np.tile(application["period_bounds_h"],(group_n*2,1))])\ninitial_loss,initial_gradient = scipy_objective(initial)\nassert np.isfinite(initial_loss) and np.isfinite(initial_gradient).all()\nloss_history = [[0,initial_loss]]\nprint("POPULATION_STATE_FIT",fold,"natural_training_records",int(train.sum()),\n    "heldout_records",held_total,"heldout_groups",held_n.tolist(),"parameters",len(initial),\n    "initial_period",initial_period.tolist(),"initial_loss",initial_loss,flush=True)\nresult = minimize(scipy_objective,initial,jac=True,method="L-BFGS-B",bounds=parameter_bounds,\n    callback=lambda intermediate_result:(loss_history.append([len(loss_history),float(intermediate_result.fun)]),\n        len(loss_history)%25==0 and print("POPULATION_STATE_PROGRESS",fold,len(loss_history)-1,\n            intermediate_result.fun,flush=True)),\n    options={"maxiter":state_settings["maxiter"],"ftol":state_settings["ftol"],\n        "gtol":settings["gtol"],"maxls":settings["maxls"]})\nstate = population_state(torch.as_tensor(result.x,dtype=torch.float64))\nlatent_mean = state[1].detach().numpy()\nlatent_precision_cholesky = state[2].detach().numpy()\nloading = state[3].detach().numpy()[held_group_index,slot]\nnoise_variance = np.exp(state[4].detach().numpy()[held_group_index,slot])\npopulation_period = state[5].detach().numpy()\nstem = state_settings["stem"].with_name(state_settings["stem"].name+"_common_fold"+str(fold))\ndump({"model":"joint_population_named_rotating_state_sources","configuration":state_settings,\n    "optimization":result,"source_parameters":source_parameters,"loading_variance":loading_variance,\n    "training_trace_id":trace_id[train],"training_groups":training_groups,\n    "training_source_labels":training_usable.sum(axis=0),"heldout_optical_read":False,\n    "loading":loading,"noise_variance":noise_variance,"population_period":population_period,\n    "latent_mean":latent_mean,"latent_precision_cholesky":latent_precision_cholesky,\n    "target":"optically_separated_target_luminescence_period",\n    "input":"all_unfiltered_cells_from_the_same_experiment",\n    "uncertainty":"latent_source_conditional_on_MAP_loadings_period_and_noise"},stem.with_suffix(".joblib"))\nprint("POPULATION_STATE_OPTIMIZED","iterations",result.nit,"status",str(result.message),\n    "loss",result.fun,"population_period",population_period.tolist(),\n    "noise_variance_quantiles",np.quantile(noise_variance,[.1,.5,.9]).tolist(),flush=True)\nparticle_n = state_settings["posterior_particles"]\nrng = np.random.default_rng(settings["seed"])\nlatent_noise = rng.standard_normal((group_n,4*dimension,particle_n))\nlatent_samples = latent_mean[:,:,None]+np.linalg.solve(\n    latent_precision_cholesky.transpose(0,2,1),latent_noise)\nlatent_samples = latent_samples.reshape(group_n,2,2,dimension,particle_n)\nsource_pair_samples = np.einsum("nrc,nrcdq,td->nqrt",loading.reshape(held_total,2,2),\n    latent_samples[held_group_index],projection_basis,optimize=True)\nsource_pair_mean = np.einsum("nrc,nrcd,td->nrt",loading.reshape(held_total,2,2),\n    latent_mean.reshape(group_n,2,2,dimension)[held_group_index],projection_basis,optimize=True)\nassert np.isfinite(source_pair_samples).all()\nsource_samples = source_pair_samples[:,:,0]\nbackground_samples = source_pair_samples[:,:,1]\n# Read out a distribution for each cell\'s source trajectory, preserving the\n# existing target luminescence estimand rather than scoring a shared group period.\nreadout_code = structural_source_readout_stage.split("prior_labels =",1)[0].replace(\n    "waves = np.stack([prediction,mixed[heldout]],axis=1)",\n    "waves = np.concatenate([source_samples,background_samples],axis=1)").replace(\n    "np.repeat(held_mask,2,axis=0)","np.repeat(held_mask,2*particle_n,axis=0)").replace(\n    "np.repeat(held_count,2)","np.repeat(held_count,2*particle_n)")\nexec(compile(readout_code,__file__,"exec"))\nparticle_logmass = log_evidence.reshape(held_total,2,particle_n,len(periods))+np.log(grid_weight)[None,None,None]\nparticle_mass = np.exp(particle_logmass-logsumexp(particle_logmass,axis=-1)[...,None])\nrole_mass = particle_mass.mean(axis=2)\nwindow = (np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score = role_mass@window.T\nrole_selected = role_score.argmax(axis=2)\nrole_estimate = periods[role_selected]\nrole_confidence = np.take_along_axis(role_score,role_selected[...,None],axis=2)[...,0]\nmass,estimate,confidence = role_mass[:,:1],role_estimate[:,:1],role_confidence[:,:1]\nmethods = np.array([state_settings["method"]])\npredictions = pd.DataFrame({"trace_id":trace_id[heldout],"method":methods[0],\n    "estimate_h":estimate[:,0],"confidence":confidence[:,0],"heldout_fold":fold,\n    "heldout_run":run[heldout],"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    source_samples=source_samples,background_samples=background_samples,source_pair_mean=source_pair_mean,\n    source_parameters=source_parameters,noise_covariance=noise_covariance,noise_variance=noise_variance,\n    loading=loading,loading_variance=loading_variance,population_period=population_period,\n    latent_mean=latent_mean,latent_precision_cholesky=latent_precision_cholesky,\n    projection_basis=projection_basis,group_names=held_groups,group_index=held_group_index,\n    periods=periods,mass=mass,role_mass=role_mass,role_estimate=role_estimate,\n    role_confidence=role_confidence,estimate=estimate,confidence=confidence,methods=methods,\n    training_trace_id=trace_id[train],training_groups=training_groups,\n    training_loss_history=np.asarray(loss_history))\nexec(compile(structural_source_readout_stage[\n    structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'

