structural_phase_source_training_stage = '\nfrom scipy.optimize import minimize\nfrom scipy.special import logsumexp\nfrom joblib import dump\nimport torch\nexec(compile(structural_source_data_stage,__file__,"exec"))\nphase_settings = application["structural_phase_source"]\nassert not native\ntorch.set_num_threads(CONFIG["threads"])\ntorch.set_num_interop_threads(CONFIG["threads"])\nexec(compile(structural_hierarchy_fit_stage[\n    structural_hierarchy_fit_stage.index("train_rows,held_rows ="):\n    structural_hierarchy_fit_stage.index("# Project the same full candidate grid")],__file__,"exec"))\nexec(compile(structural_period_flow_fit_stage[\n    structural_period_flow_fit_stage.index("background_raw ="):\n    structural_period_flow_fit_stage.index("layout_count,layout_index")],__file__,"exec"))\nassert np.unique(count).size==1\ndimension = length-2\nharmonic_index = np.array([1.,2.])\nangle = 2.*np.pi*time[None,:,None]/periods[:,None,None]*harmonic_index[None,None]\nharmonic = np.sqrt(2.)*np.stack([np.cos(angle),np.sin(angle)],axis=-1).reshape(period_n,length,4)\nharmonic -= np.einsum("ti,pij->ptj",base[0],np.einsum("ti,ptj->pij",base[0],harmonic))\nsource_gram = np.einsum("pti,ptj->pij",harmonic,harmonic)\nsource_rhs = np.einsum("pti,nrt->nrpi",harmonic,source_unit)\nsource_rss = np.sum(source_unit**2,axis=-1)\nsource_evidence = lambda vector: (\n    log_variance:=vector.reshape(2,2),\n    coefficient_precision:=np.repeat(np.exp(-log_variance),2,axis=1),\n    matrix:=source_gram[None]+np.eye(4)[None,None]*coefficient_precision[:,None,None],\n    inverse:=np.linalg.inv(matrix),\n    coefficient:=np.einsum("rpij,nrpj->nrpi",inverse,source_rhs,optimize=True),\n    residual:=source_rss[...,None]-np.sum(source_rhs*coefficient,axis=-1),\n    determinant:=np.linalg.slogdet(matrix)[1]+2.*log_variance.sum(axis=1)[:,None],\n    evidence:=-.5*determinant[None]-.5*dimension*np.log(residual),\n    inverse_trace:=np.diagonal(inverse,axis1=-2,axis2=-1).reshape(2,period_n,2,2).sum(axis=-1),\n    coefficient_energy:=np.sum(coefficient.reshape(len(train_rows),2,period_n,2,2)**2,axis=-1),\n    derivative:=-.5*(2.-inverse_trace*np.exp(-log_variance)[:,None])[None]\n        +dimension*coefficient_energy*np.exp(-log_variance)[None,:,None]/(2.*residual[...,None]),\n    (evidence,derivative,coefficient,residual,inverse))[-1]\nsource_objective = lambda vector: (\n    state:=source_evidence(vector),\n    joint:=state[0]+log_anchor,\n    normalizer:=logsumexp(joint,axis=-1),\n    posterior:=np.exp(joint-normalizer[...,None]),\n    (-np.sum(row_weight[:,None]*normalizer)/2.,\n        (-np.einsum("n,nrp,nrph->rh",row_weight,posterior,state[1],optimize=True)/2.).ravel()))[-1]\nparameter_bounds = np.log(np.finfo(float).eps**np.array([.25,-.25]))\ninitial_source = np.zeros(4)\ninitial_loss,initial_gradient = source_objective(initial_source)\nassert np.isfinite(initial_loss) and np.isfinite(initial_gradient).all()\nprint("PHASE_SOURCE_TRAIN",fold,"records",len(train_rows),"source_labels",training_usable.sum(axis=0).tolist(),\n    "initial_loss",initial_loss,flush=True)\nsource_result = minimize(source_objective,initial_source,jac=True,method="L-BFGS-B",\n    bounds=np.tile(parameter_bounds,(4,1)),options={"maxiter":phase_settings["source_maxiter"],\n        "ftol":phase_settings["ftol"],"gtol":phase_settings["gtol"]})\nsource_variance = np.exp(source_result.x.reshape(2,2))\nsource_state = source_evidence(source_result.x)\nsource_logposterior = source_state[0]+log_anchor\nsource_logposterior -= logsumexp(source_logposterior,axis=-1)[...,None]\nsource_posterior = np.exp(source_logposterior)\nprint("PHASE_SOURCE_GAUSSIAN_PRIOR",source_variance.tolist(),"iterations",source_result.nit,\n    "status",str(source_result.message),"loss",source_result.fun,flush=True)\n# Fit nonlinear phase coupling from the exact Gaussian source posterior.\n# z2 = c*g(z1) + sqrt(1-|c|^2)*epsilon, g(z)=z^2/|z|.\n# z1, epsilon are standard circular Gaussians. Both harmonic marginals\n# and every second-order moment stay exactly equal to the uncoupled model.\nparticle_n = phase_settings["posterior_particles"]\nrng = np.random.default_rng(settings["seed"])\nsource_row_n = len(train_rows)*2\nsource_cdf = source_posterior.reshape(source_row_n,period_n).cumsum(axis=1)\nsource_selected = np.searchsorted((source_cdf+np.arange(source_row_n)[:,None]).ravel(),\n    (rng.random((source_row_n,particle_n))+np.arange(source_row_n)[:,None]).ravel()).reshape(\n        len(train_rows),2,particle_n)-np.arange(source_row_n).reshape(len(train_rows),2,1)*period_n\nassert ((source_selected>=0)&(source_selected<period_n)).all()\nsource_row = np.arange(len(train_rows))[:,None,None]\nsource_role = np.arange(2)[None,:,None]\nsource_selected_mean = source_state[2][source_row,source_role,source_selected]\nsource_selected_residual = source_state[3][source_row,source_role,source_selected]\nsource_selected_cholesky = np.linalg.cholesky(source_state[4])[source_role,source_selected]\nsource_inverse_sigma = np.sqrt(2.*rng.gamma(dimension/2.,size=source_selected.shape)/source_selected_residual)\nsource_normal = rng.standard_normal((*source_selected.shape,4))\nsource_standard = source_selected_mean*source_inverse_sigma[...,None] \\\n    +np.einsum("nrqij,nrqj->nrqi",source_selected_cholesky,source_normal)\nsource_standard /= np.sqrt(np.repeat(source_variance,2,axis=1))[None,:,None]\nsource_complex = source_standard.reshape(len(train_rows),2,particle_n,2,2)*np.array([1.,-1.])\nsource_z1,source_z2 = source_complex[:,:,:,0],source_complex[:,:,:,1]\nsource_g1 = np.stack([source_z1[...,0]**2-source_z1[...,1]**2,\n    2.*source_z1[...,0]*source_z1[...,1]],axis=-1)/np.linalg.norm(source_z1,axis=-1)[...,None]\ntensor_g1 = torch.as_tensor(source_g1,dtype=torch.float64)\ntensor_z2 = torch.as_tensor(source_z2,dtype=torch.float64)\ntensor_row_weight = torch.as_tensor(row_weight,dtype=torch.float64)\ncoupling_logratio = lambda vector,g1,z2: (\n    raw:=vector.reshape(2,2),\n    coupling:=raw/torch.sqrt(1.+(raw**2).sum(dim=-1,keepdim=True)),\n    remaining:=1.-(coupling**2).sum(dim=-1),\n    fitted:=torch.stack([coupling[None,:,None,0]*g1[...,0]-coupling[None,:,None,1]*g1[...,1],\n        coupling[None,:,None,1]*g1[...,0]+coupling[None,:,None,0]*g1[...,1]],dim=-1),\n    -torch.log(remaining)[None,:,None]-.5*((z2-fitted)**2).sum(dim=-1)/remaining[None,:,None]\n        +.5*(z2**2).sum(dim=-1))[-1]\ncoupling_objective = lambda vector: (\n    ratio:=coupling_logratio(vector,tensor_g1,tensor_z2),\n    evidence:=torch.logsumexp(ratio,dim=-1)-np.log(particle_n),\n    -(tensor_row_weight[:,None]*evidence).sum()/2.\n        +settings["weight_decay"]*(vector**2).mean())[-1]\ncoupling_gradient = torch.func.grad_and_value(coupling_objective)\nto_scipy = lambda gradient,value:(value.detach().item(),gradient.detach().numpy())\ncoupling_scipy = lambda vector:to_scipy(*coupling_gradient(torch.as_tensor(vector,dtype=torch.float64)))\ncoupling_initial = np.zeros(4)\ncoupling_initial_loss,coupling_initial_gradient = coupling_scipy(coupling_initial)\nassert np.allclose(coupling_logratio(torch.zeros(4,dtype=torch.float64),tensor_g1,tensor_z2).numpy(),0.)\n\ngradient_index = int(np.argmax(np.abs(coupling_initial_gradient)))\ngradient_step = np.zeros(4);gradient_step[gradient_index] = 1.e-5\ngradient_central = (coupling_scipy(gradient_step)[0]-coupling_scipy(-gradient_step)[0])/2.e-5\nassert np.isclose(gradient_central,coupling_initial_gradient[gradient_index],rtol=1.e-4,atol=1.e-6)\nprint("PHASE_COUPLING_GRADIENT_CHECK",coupling_initial_gradient[gradient_index],gradient_central,flush=True)\n\ncoupling_result = minimize(coupling_scipy,coupling_initial,jac=True,method="L-BFGS-B",\n    options={"maxiter":phase_settings["source_maxiter"],"ftol":phase_settings["ftol"],\n        "gtol":phase_settings["gtol"],"maxls":settings["maxls"]})\ncoupling_raw = coupling_result.x.reshape(2,2)\ncoupling = coupling_raw/np.sqrt(1.+np.sum(coupling_raw**2,axis=1))[:,None]\nsource_ratio = coupling_logratio(torch.as_tensor(coupling_result.x,dtype=torch.float64),\n    tensor_g1,tensor_z2).numpy()\nsource_ratio_weight = np.exp(source_ratio-logsumexp(source_ratio,axis=-1)[...,None])\nsource_ess = 1./np.sum(source_ratio_weight**2,axis=-1)\nprint("PHASE_SOURCE_COUPLING","complex",coupling.tolist(),"magnitude",np.linalg.norm(coupling,axis=1).tolist(),\n    "loss",coupling_result.fun,"iterations",coupling_result.nit,"status",str(coupling_result.message),\n    "source_importance_ess",np.quantile(source_ess,[.1,.5,.9],axis=0).tolist(),flush=True)\n# The observation remainder uses all complete training source waveforms,\n# with two fitted gains per record. It is an empirical remainder covariance,\n# including optical reconstruction errors, not known instrument noise.\noptical_pair = np.stack([target,background],axis=-1)\noptical_gain = np.linalg.solve(np.einsum("nti,ntj->nij",optical_pair,optical_pair),\n    np.einsum("nti,nt->ni",optical_pair,mixed[train])[...,None])[...,0]\nobservation_remainder = mixed[train]-np.einsum("ntr,nr->nt",optical_pair,optical_gain)\nremainder_energy = np.mean(observation_remainder**2,axis=1)\nremainder_unit = observation_remainder/np.sqrt(remainder_energy)[:,None]\nremainder_autocovariance = np.fft.irfft(np.abs(np.fft.rfft(\n    remainder_unit,n=2*length,axis=1))**2,n=2*length,axis=1)[:,:length]/length\nlag = np.abs(np.arange(length)[:,None]-np.arange(length)[None])\nprojection = np.eye(length)-base[0]@base[0].T\nnoise_covariance = projection@(row_weight@remainder_autocovariance)[lag]@projection\nnoise_covariance *= dimension/np.trace(noise_covariance)\nnoise_covariance += base[0]@base[0].T\nnoise_logdet = np.linalg.slogdet(noise_covariance)[1]\nnoise_inverse = np.linalg.inv(noise_covariance)\nassert np.linalg.eigvalsh(noise_covariance).min()>0.\nharmonic_metric = np.einsum("ts,psi->pti",noise_inverse,harmonic,optimize=True)\ngram = np.einsum("pti,qtj->pqij",harmonic,harmonic_metric,optimize=True)\ngrid_index = np.arange(period_n)\nsingle_gram = gram[grid_index,grid_index]\npair_shape = (period_n,period_n,4,4)\njoint_gram = np.concatenate([\n    np.concatenate([np.broadcast_to(single_gram[:,None],pair_shape),gram],axis=-1),\n    np.concatenate([gram.swapaxes(-1,-2),np.broadcast_to(single_gram[None],pair_shape)],axis=-1)],axis=-2)\nrhs = np.einsum("nt,pti->npi",mixed,harmonic_metric,optimize=True)\npair_rhs = np.concatenate([\n    np.broadcast_to(rhs[:,:,None],(len(mixed),period_n,period_n,4)),\n    np.broadcast_to(rhs[:,None],(len(mixed),period_n,period_n,4))],axis=-1)\nbase_rss = np.einsum("nt,ts,ns->n",mixed,noise_inverse,mixed,optimize=True)\ntemplate_variance = np.repeat(source_variance,2,axis=1)\nmixed_evidence = lambda vector,rows: (\n    variance:=np.exp(vector)[:,None]*template_variance,\n    precision:=1./variance,\n    matrix:=joint_gram+np.diag(precision.ravel()),\n    inverse:=np.linalg.inv(matrix),\n    coefficient:=np.einsum("pqij,npqj->npqi",inverse,pair_rhs[rows],optimize=True),\n    residual:=base_rss[rows,None,None]-np.sum(pair_rhs[rows]*coefficient,axis=-1),\n    determinant:=np.linalg.slogdet(matrix)[1]+np.log(variance).sum(),\n    evidence:=-.5*(determinant[None]+noise_logdet)-dimension/2.*np.log(residual),\n    trace:=np.sum(np.diagonal(inverse,axis1=-2,axis2=-1).reshape(period_n,period_n,2,4)*precision[None,None],axis=-1),\n    energy:=np.sum(coefficient.reshape(len(rows),period_n,period_n,2,4)**2*precision[None,None,None],axis=-1),\n    derivative:=-.5*(4.-trace)[None]+dimension*energy/(2.*residual[...,None]),\n    (evidence,derivative,coefficient,residual,inverse))[-1]\nmixed_objective = lambda vector: (\n    state:=mixed_evidence(vector,train_rows),\n    joint:=state[0]+log_anchor[:,0,:,None]+log_anchor[:,1,None,:],\n    normalizer:=logsumexp(joint,axis=(1,2)),\n    posterior:=np.exp(joint-normalizer[:,None,None]),\n    (-np.sum(row_weight*normalizer),\n        -np.einsum("n,npq,npqr->r",row_weight,posterior,state[1],optimize=True)))[-1]\ninitial_mixed = np.zeros(2)\nmixed_initial_loss,mixed_initial_gradient = mixed_objective(initial_mixed)\nassert np.isfinite(mixed_initial_loss) and np.isfinite(mixed_initial_gradient).all()\n\ngradient_index = int(np.argmax(np.abs(mixed_initial_gradient)))\ngradient_step = np.zeros(2);gradient_step[gradient_index] = 1.e-5\ngradient_central = (mixed_objective(gradient_step)[0]-mixed_objective(-gradient_step)[0])/2.e-5\nassert np.isclose(gradient_central,mixed_initial_gradient[gradient_index],rtol=1.e-4,atol=1.e-6)\ncheck_state = mixed_evidence(initial_mixed,train_rows[:1])\ncheck_pair = np.unravel_index(check_state[0][0].argmax(),(period_n,period_n))\ncheck_design = np.concatenate([harmonic[check_pair[0]],harmonic[check_pair[1]]],axis=1)\ncheck_variance = template_variance.ravel()\ncheck_covariance = noise_covariance+(check_design*check_variance[None])@check_design.T\ncheck_inverse_y = np.linalg.solve(check_covariance,mixed[train_rows[0]])\ncheck_dense = -.5*np.linalg.slogdet(check_covariance)[1] \\\n    -.5*dimension*np.log(mixed[train_rows[0]]@check_inverse_y)\ncheck_fast = check_state[0][0,check_pair[0],check_pair[1]]\ncheck_mean = check_variance*(check_design.T@check_inverse_y)\nassert np.isclose(check_dense,check_fast,rtol=1.e-9,atol=1.e-9)\nassert np.allclose(check_mean,check_state[2][0,check_pair[0],check_pair[1]],rtol=1.e-9,atol=1.e-9)\nprint("PHASE_MIXTURE_DENSE_GRADIENT_CHECK","gradient",mixed_initial_gradient[gradient_index],\n    "central",gradient_central,"dense",check_dense,"lowrank",check_fast,flush=True)\n\nmixed_history = [[0,mixed_initial_loss]]\nprint("PHASE_MIXTURE_TRAIN","initial_loss",mixed_initial_loss,flush=True)\nmixed_result = minimize(mixed_objective,initial_mixed,jac=True,method="L-BFGS-B",\n    bounds=np.tile(parameter_bounds,(2,1)),\n    callback=lambda intermediate_result:(mixed_history.append([len(mixed_history),float(intermediate_result.fun)]),\n        len(mixed_history)%10==0 and print("PHASE_MIXTURE_PROGRESS",len(mixed_history)-1,\n            intermediate_result.fun,flush=True)),\n    options={"maxiter":phase_settings["mixture_maxiter"],"ftol":phase_settings["ftol"],\n        "gtol":phase_settings["gtol"]})\nprint("PHASE_MIXTURE_VARIANCE",np.exp(mixed_result.x).tolist(),"iterations",mixed_result.nit,\n    "status",str(mixed_result.message),"loss",mixed_result.fun,flush=True)\n'

structural_phase_source_inference_stage = '\nstem = phase_settings["stem"].with_name(phase_settings["stem"].name+"_common_fold"+str(fold))\ndump({"model":"phase_coupled_two_source_harmonic_inverse","configuration":phase_settings,\n    "source_variance":source_variance,"coupling":coupling,"coupling_parameters":coupling_result.x,\n    "mixture_scale":np.exp(mixed_result.x),"noise_covariance":noise_covariance,\n    "source_optimization":source_result,"coupling_optimization":coupling_result,\n    "mixture_optimization":mixed_result,"training_trace_id":trace_id[train],\n    "training_groups":training_groups,"training_source_labels":training_usable.sum(axis=0),\n    "training_shape_importance_ess":source_ess,"heldout_optical_read":False,"seed":settings["seed"],\n    "target":"optically_separated_target_luminescence_period",\n    "uncertainty":"conditional_period_distribution_with_fixed_source_hyperparameters_and_importance_integration"},\n    stem.with_suffix(".joblib"))\nheld_state = mixed_evidence(mixed_result.x,held_rows)\njoint_logmass = held_state[0]+np.log(prior[heldout,0,:,None])+np.log(prior[heldout,1,None,:])\njoint_logmass -= logsumexp(joint_logmass,axis=(1,2))[:,None,None]\nbase_joint_mass = np.exp(joint_logmass)\nbase_target_logmass = logsumexp(joint_logmass,axis=2)\nconditional_background = np.exp(joint_logmass-base_target_logmass[:,:,None])\nheld_total = len(held_rows)\nconditional_row_n = held_total*period_n\nconditional_cdf = conditional_background.reshape(conditional_row_n,period_n).cumsum(axis=1)\nselected_background = np.searchsorted(\n    (conditional_cdf+np.arange(conditional_row_n)[:,None]).ravel(),\n    (rng.random((conditional_row_n,particle_n))+np.arange(conditional_row_n)[:,None]).ravel()\n    ).reshape(held_total,period_n,particle_n)-np.arange(conditional_row_n).reshape(held_total,period_n,1)*period_n\nassert ((selected_background>=0)&(selected_background<period_n)).all()\nposterior_normal = rng.standard_normal((held_total,period_n,particle_n,8))\nposterior_gamma = rng.gamma(dimension/2.,size=(held_total,period_n,particle_n))\ncoefficient_variance = (np.exp(mixed_result.x)[:,None]*template_variance).ravel()\ntensor_variance_scale = torch.as_tensor(np.sqrt(coefficient_variance),dtype=torch.float64)\ntensor_coupling = torch.as_tensor(coupling_result.x,dtype=torch.float64)\ntensor_selected_background = torch.as_tensor(selected_background.transpose(1,0,2),dtype=torch.int64)\ntensor_posterior_normal = torch.as_tensor(posterior_normal.transpose(1,0,2,3),dtype=torch.float64)\ntensor_posterior_gamma = torch.as_tensor(posterior_gamma.transpose(1,0,2),dtype=torch.float64)\ntensor_held_mean = torch.as_tensor(held_state[2].transpose(1,0,2,3),dtype=torch.float64)\ntensor_held_residual = torch.as_tensor(held_state[3].transpose(1,0,2),dtype=torch.float64)\ntensor_held_cholesky = torch.as_tensor(np.linalg.cholesky(held_state[4]),dtype=torch.float64)\n# Every target period is retained. Only nuisance background period and\n# coefficient uncertainty are integrated by fixed-seed conditional sampling.\nintegrate_target_period = lambda mean,residual,cholesky,selected,normal,gamma: (\n    selected_mean:=torch.gather(mean,1,selected[...,None].expand(-1,-1,8)),\n    selected_residual:=torch.gather(residual,1,selected),\n    inverse_sigma:=torch.sqrt(2.*gamma/selected_residual),\n    coefficient_noise:=torch.einsum("nqij,nqj->nqi",cholesky[selected],normal),\n    standard:=(selected_mean*inverse_sigma[...,None]+coefficient_noise)/tensor_variance_scale,\n    complex_coefficient:=standard.reshape(held_total,particle_n,2,2,2).permute(0,2,1,3,4)\n        *torch.tensor([1.,-1.],dtype=torch.float64),\n    z1:=complex_coefficient[:,:,:,0],\n    z2:=complex_coefficient[:,:,:,1],\n    g1:=torch.stack([z1[...,0]**2-z1[...,1]**2,2.*z1[...,0]*z1[...,1]],dim=-1)\n        /torch.linalg.vector_norm(z1,dim=-1,keepdim=True),\n    ratio:=coupling_logratio(tensor_coupling,g1,z2).sum(dim=1),\n    logcorrection:=torch.logsumexp(ratio,dim=-1)-np.log(particle_n),\n    weight:=torch.softmax(ratio,dim=-1),\n    physical_coefficient:=selected_mean+coefficient_noise/inverse_sigma[...,None],\n    background_mass:=torch.zeros((held_total,period_n),dtype=torch.float64).scatter_add(1,selected,weight),\n    target_coefficient:=(weight[...,None]*physical_coefficient[...,:4]).sum(dim=1),\n    background_coefficient:=torch.zeros((held_total,period_n,4),dtype=torch.float64).scatter_add(\n        1,selected[...,None].expand(-1,-1,4),weight[...,None]*physical_coefficient[...,4:]),\n    ess:=1./(weight**2).sum(dim=-1),\n    relative_se:=torch.sqrt((particle_n/ess-1.)/(particle_n-1.)),\n    (logcorrection,background_mass,target_coefficient,background_coefficient,ess,relative_se))[-1]\nintegrated = torch.vmap(integrate_target_period,chunk_size=phase_settings["integration_chunk_size"])(\n    tensor_held_mean,tensor_held_residual,tensor_held_cholesky,tensor_selected_background,\n    tensor_posterior_normal,tensor_posterior_gamma)\nlogcorrection = integrated[0].numpy().T\nconditional_background_mass = integrated[1].numpy().transpose(1,0,2)\nconditional_target_coefficient = integrated[2].numpy().transpose(1,0,2)\nconditional_background_coefficient = integrated[3].numpy().transpose(1,0,2,3)\nimportance_ess = integrated[4].numpy().T\nimportance_relative_se = integrated[5].numpy().T\ntarget_logmass = base_target_logmass+logcorrection\ntarget_logmass -= logsumexp(target_logmass,axis=1)[:,None]\ncoupled_target_mass = np.exp(target_logmass)\ncoupled_joint_mass = coupled_target_mass[:,:,None]*conditional_background_mass\nassert np.allclose(coupled_joint_mass.sum(axis=(1,2)),1.)\nrole_mass = np.stack([\n    np.stack([coupled_joint_mass.sum(axis=2),coupled_joint_mass.sum(axis=1)],axis=1),\n    np.stack([base_joint_mass.sum(axis=2),base_joint_mass.sum(axis=1)],axis=1),\n    prior[heldout]],axis=1)\nwindow = (np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score = role_mass@window.T\nrole_selected = role_score.argmax(axis=-1)\nrole_estimate = periods[role_selected]\nrole_confidence = np.take_along_axis(role_score,role_selected[...,None],axis=-1)[...,0]\nmass,estimate,confidence = role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\ntarget_coefficient = coupled_target_mass[:,:,None]*conditional_target_coefficient\nbackground_coefficient = np.einsum("np,npqi->nqi",coupled_target_mass,conditional_background_coefficient)\nsource_waveform = np.einsum("pti,npi->nt",harmonic,target_coefficient)\nbackground_waveform = np.einsum("qti,nqi->nt",harmonic,background_coefficient)\nbase_target_coefficient = np.einsum("npq,npqi->npi",base_joint_mass,held_state[2][...,:4])\nbase_background_coefficient = np.einsum("npq,npqi->nqi",base_joint_mass,held_state[2][...,4:])\nbase_source_waveform = np.einsum("pti,npi->nt",harmonic,base_target_coefficient)\nbase_background_waveform = np.einsum("qti,nqi->nt",harmonic,base_background_coefficient)\nmethods = np.array(phase_settings["methods"])\npredictions = pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],len(methods)),\n    "method":np.tile(methods,held_total),"estimate_h":estimate.ravel(),"confidence":confidence.ravel(),\n    "heldout_fold":fold,"heldout_run":np.repeat(run[heldout],len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    periods=periods,mass=mass,estimate=estimate,confidence=confidence,methods=methods,\n    role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,\n    coupled_joint_mass=coupled_joint_mass,base_joint_mass=base_joint_mass,\n    source_pair_mean=np.stack([source_waveform,background_waveform],axis=1),\n    base_source_pair_mean=np.stack([base_source_waveform,base_background_waveform],axis=1),\n    importance_logcorrection=logcorrection,importance_ess=importance_ess,\n    importance_relative_se=importance_relative_se,source_variance=source_variance,\n    mixture_scale=np.exp(mixed_result.x),coupling=coupling,\n    training_trace_id=trace_id[train],training_groups=training_groups)\nprint("PHASE_POSTERIOR_INTEGRATED","weighted_ess_quantiles",\n    np.quantile(np.sum(coupled_target_mass*importance_ess,axis=1),[0,.1,.5,.9,1]).tolist(),\n    "weighted_relative_se_quantiles",\n    np.quantile(np.sqrt(np.sum(coupled_target_mass**2*importance_relative_se**2,axis=1)),\n        [0,.1,.5,.9,1]).tolist(),flush=True)\nexec(compile(structural_source_readout_stage[\n    structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
structural_phase_source_fit_stage = structural_phase_source_training_stage+structural_phase_source_inference_stage
if args.stage=="structural-phase-source-fit":
    exec(compile(structural_phase_source_fit_stage,__file__,"exec"))

structural_phase_population_stage = '\nfrom scipy.special import logsumexp,ndtri,gammaincinv\nfrom scipy.stats import qmc\nfrom joblib import load,dump\nimport torch\nexec(compile(structural_source_data_stage.split("\\noptical =",1)[0],__file__,"exec"))\npopulation_settings = application["structural_phase_population"]\nassert not native\ntorch.set_num_threads(CONFIG["threads"])\ntorch.set_num_interop_threads(CONFIG["threads"])\nexec(compile(structural_hierarchy_fit_stage[\n    structural_hierarchy_fit_stage.index("train_rows,held_rows ="):\n    structural_hierarchy_fit_stage.index("# Project the same full candidate grid")],__file__,"exec"))\nlength=len(time)\ndimension=length-2\nsource_stem=application["structural_phase_source"]["stem"]\nsource_stem=source_stem.with_name(source_stem.name+"_common_fold"+str(fold))\nbundle=load(source_stem.with_suffix(".joblib"))\nassert np.array_equal(bundle["training_trace_id"],trace_id[train])\nsource_variance=bundle["source_variance"]\ntemplate_variance=np.repeat(source_variance,2,axis=1)\nnoise_covariance=bundle["noise_covariance"]\nnoise_inverse=np.linalg.inv(noise_covariance)\nnoise_logdet=np.linalg.slogdet(noise_covariance)[1]\nmixture_log_scale=np.log(bundle["mixture_scale"])\nangle=2.*np.pi*time[None,:,None]/periods[:,None,None]*np.array([1.,2.])[None,None]\nharmonic=np.sqrt(2.)*np.stack([np.cos(angle),np.sin(angle)],axis=-1).reshape(period_n,length,4)\nharmonic-=np.einsum("ti,pij->ptj",base[0],np.einsum("ti,ptj->pij",base[0],harmonic))\nexec(compile(structural_phase_source_training_stage[\n    structural_phase_source_training_stage.index("harmonic_metric ="):\n    structural_phase_source_training_stage.index("initial_mixed =")],__file__,"exec"))\nexec(compile(structural_phase_source_training_stage[\n    structural_phase_source_training_stage.index("coupling_logratio ="):\n    structural_phase_source_training_stage.index("coupling_objective =")],__file__,"exec"))\nheld_state=mixed_evidence(mixture_log_scale,held_rows)\nheld_total=len(held_rows)\nparticle_n=population_settings["posterior_particles"]\nsobol=qmc.Sobol(d=9*held_total,scramble=True,seed=settings["seed"])\nuniform=sobol.random_base2(int(np.log2(particle_n))).reshape(particle_n,held_total,9).transpose(1,0,2)\nassert particle_n==2**int(np.log2(particle_n)) and ((uniform>0.)&(uniform<1.)).all()\ntensor_normal=torch.as_tensor(ndtri(uniform[:,:,:8]),dtype=torch.float64)\ntensor_gamma=torch.as_tensor(gammaincinv(dimension/2.,uniform[:,:,8]),dtype=torch.float64)\ntensor_variance=torch.as_tensor(np.sqrt((bundle["mixture_scale"][:,None]*template_variance).ravel()),dtype=torch.float64)\ntensor_coupling=torch.as_tensor(bundle["coupling_parameters"],dtype=torch.float64)\ntensor_mean=torch.as_tensor(held_state[2].transpose(1,0,2,3),dtype=torch.float64)\ntensor_residual=torch.as_tensor(held_state[3].transpose(1,0,2),dtype=torch.float64)\ntensor_cholesky=torch.as_tensor(np.linalg.cholesky(held_state[4]),dtype=torch.float64)\n# All 73x73 period pairs receive a positive evidence correction; no sampled\n# background-period histogram is reused as a likelihood for population pooling.\nintegrate_period_pairs=lambda mean,residual,cholesky: (\n    inverse_sigma:=torch.sqrt(2.*tensor_gamma[:,None]/residual[:,:,None]),\n    coefficient_noise:=torch.einsum("bij,nqj->nbqi",cholesky,tensor_normal),\n    standard:=(mean[:,:,None]*inverse_sigma[...,None]+coefficient_noise)/tensor_variance,\n    complex_coefficient:=standard.reshape(held_total*period_n,particle_n,2,2,2).permute(0,2,1,3,4)\n        *torch.tensor([1.,-1.],dtype=torch.float64),\n    z1:=complex_coefficient[:,:,:,0],\n    z2:=complex_coefficient[:,:,:,1],\n    g1:=torch.stack([z1[...,0]**2-z1[...,1]**2,2.*z1[...,0]*z1[...,1]],dim=-1)\n        /torch.linalg.vector_norm(z1,dim=-1,keepdim=True),\n    ratio:=coupling_logratio(tensor_coupling,g1,z2).sum(dim=1).reshape(held_total,period_n,particle_n),\n    logcorrection:=torch.logsumexp(ratio,dim=-1)-np.log(particle_n),\n    weight:=torch.softmax(ratio,dim=-1),\n    coefficient:=(weight[...,None]*(mean[:,:,None]+coefficient_noise/inverse_sigma[...,None])).sum(dim=2),\n    ess:=1./(weight**2).sum(dim=-1),\n    relative_se:=torch.sqrt(torch.clamp((particle_n/ess-1.)/(particle_n-1.),min=0.)),\n    (logcorrection,coefficient,ess,relative_se))[-1]\nprint("PHASE_POPULATION_FULL_PAIR_INTEGRATION","records",held_total,"period_pairs",period_n**2,\n    "particles",particle_n,"seed",settings["seed"],flush=True)\nintegrated=torch.vmap(integrate_period_pairs,chunk_size=population_settings["integration_chunk_size"])(\n    tensor_mean,tensor_residual,tensor_cholesky)\nlogcorrection=integrated[0].numpy().transpose(1,0,2)\ncoupled_coefficient=integrated[1].numpy().transpose(1,0,2,3)\nimportance_ess=integrated[2].numpy().transpose(1,0,2)\nimportance_relative_se=integrated[3].numpy().transpose(1,0,2)\nassert logcorrection.shape==held_state[0].shape and np.isfinite(logcorrection).all()\nweighted_period=filled_period*training_usable\ntraining_group_mean=(training_membership@weighted_period)/np.maximum(source_group_n,1.)\nwithin_ss=np.sum(training_usable*(filled_period-training_group_mean[training_group])**2,axis=0)\nwithin_df=training_usable.sum(axis=0)-(source_group_n>0).sum(axis=0)\nwithin_variance=within_ss/within_df\nassert (within_variance>0.).all()\ntransition_log=-.5*(periods[None,:,None]-periods[None,None,:])**2/within_variance[:,None,None] \\\n    +np.log(grid_weight)[None,None]\ntransition_log-=logsumexp(transition_log,axis=-1)[...,None]\ntransition=np.exp(transition_log)\ngroup_mean_prior=np.einsum("grp,gr->rp",np.exp(-np.abs(\n    periods[None,None]-training_group_mean[...,None])/application["risk_tolerance_h"]),\n    source_group_n>0)*grid_weight[None]\ngroup_mean_prior/=group_mean_prior.sum(axis=1)[:,None]\nindividual_prior=np.einsum("ru,rup->rp",group_mean_prior,transition)\nheld_groups,held_group=np.unique(run[heldout],return_inverse=True)\nheld_membership=(np.arange(len(held_groups))[:,None]==held_group[None]).astype(float)\nevidence=np.stack([held_state[0]+logcorrection,held_state[0]],axis=1)\nlikelihood=np.exp(evidence-evidence.max(axis=(2,3),keepdims=True))\ngroup_mean_likelihood=np.einsum("up,nmpq,vq->nmuv",transition[0],likelihood,transition[1],optimize=True)\nassert (group_mean_likelihood>0.).all()\ngroup_logmass=np.einsum("gn,nmuv->gmuv",held_membership,np.log(group_mean_likelihood),optimize=True) \\\n    +np.log(group_mean_prior[0])[None,None,:,None]+np.log(group_mean_prior[1])[None,None,None,:]\ngroup_logmass-=logsumexp(group_logmass,axis=(2,3),keepdims=True)\ngroup_mass=np.exp(group_logmass)\n# Divide out the current cell\'s integrated likelihood before conditioning its\n# local period. This exact finite-grid hierarchy does not count a cell twice.\nother_logmass=group_logmass[held_group]-np.log(group_mean_likelihood)\nother_logmass-=other_logmass.max(axis=(2,3),keepdims=True)\nborrowed_prior=np.einsum("up,nmuv,vq->nmpq",transition[0],np.exp(other_logmass),transition[1],optimize=True)\npopulation_joint_mass=likelihood*borrowed_prior\npopulation_joint_mass/=population_joint_mass.sum(axis=(2,3),keepdims=True)\nindividual_logmass=evidence+np.log(individual_prior[0])[None,None,:,None] \\\n    +np.log(individual_prior[1])[None,None,None,:]\nindividual_logmass-=logsumexp(individual_logmass,axis=(2,3),keepdims=True)\nindividual_joint_mass=np.exp(individual_logmass)\n\nsingleton_global=group_mean_likelihood[0]*group_mean_prior[0][None,:,None]*group_mean_prior[1][None,None,:]\nsingleton_other=singleton_global/group_mean_likelihood[0]\nsingleton_local=likelihood[0]*np.einsum("up,muv,vq->mpq",transition[0],singleton_other,transition[1],optimize=True)\nsingleton_local/=singleton_local.sum(axis=(1,2),keepdims=True)\nassert np.allclose(singleton_local,individual_joint_mass[0],rtol=1.e-10,atol=1.e-12)\nprint("PHASE_POPULATION_SINGLE_CELL_IDENTITY",np.max(np.abs(singleton_local-individual_joint_mass[0])),flush=True)\n\nprior_joint=np.broadcast_to(individual_prior[0,:,None]*individual_prior[1,None,:],\n    (held_total,period_n,period_n))\njoint_mass=np.stack([population_joint_mass[:,0],individual_joint_mass[:,0],\n    population_joint_mass[:,1],individual_joint_mass[:,1],prior_joint],axis=1)\nassert np.allclose(joint_mass.sum(axis=(2,3)),1.)\nrole_mass=np.stack([joint_mass.sum(axis=3),joint_mass.sum(axis=2)],axis=2)\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nrole_selected=role_score.argmax(axis=-1)\nrole_estimate=periods[role_selected]\nrole_confidence=np.take_along_axis(role_score,role_selected[...,None],axis=-1)[...,0]\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\ncoefficient_bank=np.stack([coupled_coefficient,coupled_coefficient,held_state[2],held_state[2]],axis=1)\ntarget_coefficient=np.einsum("nmpq,nmpqi->nmpi",joint_mass[:,:4],coefficient_bank[...,:4],optimize=True)\nbackground_coefficient=np.einsum("nmpq,nmpqi->nmqi",joint_mass[:,:4],coefficient_bank[...,4:],optimize=True)\nsource_waveform=np.einsum("pti,nmpi->nmt",harmonic,target_coefficient,optimize=True)\nbackground_waveform=np.einsum("qti,nmqi->nmt",harmonic,background_coefficient,optimize=True)\nmethods=np.array(population_settings["methods"])\nstem=population_settings["stem"].with_name(population_settings["stem"].name+"_common_fold"+str(fold))\npredictions=pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],len(methods)),\n    "method":np.tile(methods,held_total),"estimate_h":estimate.ravel(),"confidence":confidence.ravel(),\n    "heldout_fold":fold,"heldout_run":np.repeat(run[heldout],len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    periods=periods,mass=mass,estimate=estimate,confidence=confidence,methods=methods,\n    role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,joint_mass=joint_mass,\n    source_pair_mean=np.stack([source_waveform,background_waveform],axis=2),\n    base_logevidence=held_state[0],phase_logevidence=held_state[0]+logcorrection,\n    phase_coefficient=coupled_coefficient,base_coefficient=held_state[2],\n    group_mass=group_mass,group_names=held_groups,group_index=held_group,\n    group_mean_prior=group_mean_prior,individual_prior=individual_prior,transition=transition,\n    within_period_variance=within_variance,importance_ess=importance_ess,\n    importance_relative_se=importance_relative_se,training_trace_id=trace_id[train],training_groups=training_groups)\ndump({"model":"fully_marginal_hierarchical_phase_coupled_source_periods","configuration":population_settings,\n    "source_model_path":str(source_stem.with_suffix(".joblib")),"source_variance":source_variance,\n    "coupling":bundle["coupling"],"mixture_scale":bundle["mixture_scale"],\n    "within_period_variance":within_variance,"group_mean_prior":group_mean_prior,\n    "training_trace_id":trace_id[train],"training_groups":training_groups,\n    "heldout_optical_read":False,"seed":settings["seed"],\n    "target":"optically_separated_target_luminescence_period"},stem.with_suffix(".joblib"))\nprint("PHASE_POPULATION_PERIOD_SD",np.sqrt(within_variance).tolist(),\n    "group_modes",periods[np.stack([group_mass.sum(axis=3).argmax(axis=2),\n        group_mass.sum(axis=2).argmax(axis=2)],axis=-1)].tolist(),flush=True)\nprint("PHASE_POPULATION_INTEGRATION_ESS",\n    np.quantile(np.sum(population_joint_mass[:,0]*importance_ess,axis=(1,2)),[0,.1,.5,.9,1]).tolist(),\n    "relative_se",np.quantile(np.sqrt(np.sum(population_joint_mass[:,0]**2*\n        importance_relative_se**2,axis=(1,2))),[0,.1,.5,.9,1]).tolist(),flush=True)\nexec(compile(structural_source_readout_stage[\n    structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
if args.stage=="structural-phase-population-fit":
    exec(compile(structural_phase_population_stage,__file__,"exec"))

structural_calibrated_phase_training_stage = '\nfrom scipy.special import logsumexp,ndtri,gammaincinv\nfrom scipy.stats import qmc\nfrom joblib import load,dump\nimport torch\nexec(compile(structural_phase_source_training_stage[\n    :structural_phase_source_training_stage.index("source_objective =")],__file__,"exec"))\ncalibrated_settings=application["structural_calibrated_phase"]\nsource_stem=application["structural_phase_source"]["stem"]\nsource_stem=source_stem.with_name(source_stem.name+"_common_fold"+str(fold))\nbundle=load(source_stem.with_suffix(".joblib"))\nassert np.array_equal(bundle["training_trace_id"],trace_id[train])\nsource_variance=bundle["source_variance"]\nsource_state=source_evidence(np.log(source_variance).ravel())\nsource_logposterior=source_state[0]+log_anchor\nsource_logposterior-=logsumexp(source_logposterior,axis=-1)[...,None]\nsource_posterior=np.exp(source_logposterior)\n# Optical trajectories stay in the observed mixture\'s scale. Unknown reference\n# periods are integrated; no record is discarded or declared non-rhythmic.\noptical_pair=np.stack([target,background],axis=-1)\noptical_gain=np.linalg.solve(np.einsum("nti,ntj->nij",optical_pair,optical_pair),\n    np.einsum("nti,nt->ni",optical_pair,mixed[train])[...,None])[...,0]\ncalibration_scale=optical_gain*np.sqrt(source_energy)\ntemplate_variance=np.repeat(source_variance/(2.*source_variance.sum(axis=1))[:,None],2,axis=1)\nsource_sigma2=source_state[3]/(dimension-2.)\nsource_mean=source_state[2]\nsource_second=source_mean**2+source_sigma2[...,None]*np.diagonal(\n    source_state[4],axis1=-2,axis2=-1)[None]\nsource_scale_second=np.sum(source_second/template_variance[None,:,None],axis=-1)/4.\nperiodic_scale=calibration_scale**2*np.sum(source_posterior*source_scale_second,axis=-1)\nsource_wave_mean=np.einsum("pti,nrpi->nrpt",harmonic,source_mean,optimize=True)\nsource_marginal_mean=np.einsum("nrp,nrpt->nrt",source_posterior,source_wave_mean,\n    optimize=True)*calibration_scale[...,None]\nharmonic_frequency=np.fft.rfft(harmonic,n=2*length,axis=1)\nsource_frequency=np.fft.rfft(source_wave_mean,n=2*length,axis=-1)\nsource_frequency_variance=np.einsum("pfi,rpij,pfj->rpf",harmonic_frequency.conj(),\n    source_state[4],harmonic_frequency,optimize=True).real\nsource_expected_power=np.einsum("nrp,nrpf->nrf",source_posterior,\n    np.abs(source_frequency)**2+source_sigma2[...,None]*source_frequency_variance[None],\n    optimize=True)*calibration_scale[...,None]**2\nsource_mean_frequency=np.fft.rfft(source_marginal_mean,n=2*length,axis=-1)\nremainder_mean=mixed[train]-source_marginal_mean.sum(axis=1)\nremainder_spectrum=np.abs(np.fft.rfft(remainder_mean,n=2*length,axis=-1))**2 \\\n    +np.sum(source_expected_power-np.abs(source_mean_frequency)**2,axis=1)\nassert remainder_spectrum.min()>-1.e-8\nremainder_autocovariance=np.fft.irfft(remainder_spectrum,n=2*length,axis=-1)[:,:length]/length\nremainder_energy=remainder_autocovariance[:,0]\nsource_gram_trace=np.einsum("pij,rpji->rp",source_gram,source_state[4])\ndirect_source_energy=np.einsum("nrp,nrp->nr",source_posterior,\n    np.mean(source_wave_mean**2,axis=-1)+source_sigma2*source_gram_trace[None]/length,\n    optimize=True)*calibration_scale**2\ndirect_remainder_energy=np.mean(remainder_mean**2,axis=1)+np.sum(\n    direct_source_energy-np.mean(source_marginal_mean**2,axis=-1),axis=1)\nassert np.allclose(remainder_energy,direct_remainder_energy,rtol=1.e-9,atol=1.e-9)\nassert (remainder_energy>0.).all() and (periodic_scale>0.).all()\nlag=np.abs(np.arange(length)[:,None]-np.arange(length)[None])\nprojection=np.eye(length)-base[0]@base[0].T\nnoise_covariance=projection@(row_weight@(remainder_autocovariance/remainder_energy[:,None]))[lag]@projection\nnoise_covariance*=dimension/np.trace(noise_covariance)\nnoise_covariance+=base[0]@base[0].T\nnoise_inverse=np.linalg.inv(noise_covariance)\nnoise_logdet=np.linalg.slogdet(noise_covariance)[1]\nassert np.linalg.eigvalsh(noise_covariance).min()>0.\namplitude_logscale=np.log(periodic_scale/remainder_energy[:,None])\namplitude_mean=row_weight@amplitude_logscale\ncentered_logscale=amplitude_logscale-amplitude_mean\namplitude_covariance=np.einsum("n,ni,nj->ij",row_weight,centered_logscale,centered_logscale)\nassert np.linalg.eigvalsh(amplitude_covariance).min()>0.\nquadrature_x,quadrature_w=np.polynomial.hermite.hermgauss(\n    calibrated_settings["amplitude_quadrature_order"])\nquadrature_standard=np.stack(np.meshgrid(quadrature_x,quadrature_x,indexing="ij"),\n    axis=-1).reshape(-1,2)*np.sqrt(2.)\nquadrature_weight=(quadrature_w[:,None]*quadrature_w[None]).ravel()/np.pi\namplitude_nodes=np.exp(amplitude_mean+quadrature_standard@np.linalg.cholesky(amplitude_covariance).T)\namplitude_n=len(amplitude_nodes)\ngain_sign=(optical_gain<0.).astype(int)\ngain_sign_index=gain_sign[:,0]*2+gain_sign[:,1]\nsign_prior=np.bincount(gain_sign_index,weights=row_weight,minlength=4).reshape(2,2)\nsign_logprior=np.log(np.maximum(sign_prior,np.finfo(float).tiny))\nsign_logprior[sign_prior==0.]=-np.inf\nassert np.isclose(quadrature_weight.sum(),1.) and np.isclose(sign_prior.sum(),1.)\nprint("CALIBRATED_PHASE_TRAIN","records",len(train_rows),"amplitude_log_mean",amplitude_mean.tolist(),\n    "amplitude_log_covariance",amplitude_covariance.tolist(),"sign_prior",sign_prior.tolist(),\n    "remainder_energy",np.quantile(remainder_energy,[.1,.5,.9]).tolist(),flush=True)\nprint("CALIBRATED_PHASE_POWER","observed_periodic_fraction_quantiles",\n    np.quantile(periodic_scale[:,0]/periodic_scale.sum(axis=1),[.1,.5,.9]).tolist(),\n    "quadrature_prior_mean_fraction",float(quadrature_weight@(amplitude_nodes[:,0]/amplitude_nodes.sum(axis=1))),\n    "quadrature_nodes",amplitude_n,flush=True)\nstem=calibrated_settings["stem"].with_name(\n    calibrated_settings["stem"].name+"_common_fold"+str(fold))\ndump({"source_variance":source_variance,"template_variance":template_variance,\n    "amplitude_log_mean":amplitude_mean,"amplitude_log_covariance":amplitude_covariance,\n    "amplitude_nodes":amplitude_nodes,"amplitude_weight":quadrature_weight,\n    "sign_prior":sign_prior,"noise_covariance":noise_covariance,\n    "coupling_parameters":bundle["coupling_parameters"],"training_trace_id":trace_id[train],\n    "training_groups":training_groups,"settings":dict(calibrated_settings)},stem.with_suffix(".joblib"))\nharmonic_metric=np.einsum("ts,psi->pti",noise_inverse,harmonic,optimize=True)\ngram=np.einsum("pti,qtj->pqij",harmonic,harmonic_metric,optimize=True)\ngrid_index=np.arange(period_n)\nsingle_gram=gram[grid_index,grid_index]\npair_shape=(period_n,period_n,4,4)\njoint_gram=np.concatenate([\n    np.concatenate([np.broadcast_to(single_gram[:,None],pair_shape),gram],axis=-1),\n    np.concatenate([gram.swapaxes(-1,-2),np.broadcast_to(single_gram[None],pair_shape)],axis=-1)],axis=-2)\nrhs=np.einsum("nt,pti->npi",mixed[heldout],harmonic_metric,optimize=True)\nheld_total=len(held_rows)\npair_rhs=np.concatenate([\n    np.broadcast_to(rhs[:,:,None],(held_total,period_n,period_n,4)),\n    np.broadcast_to(rhs[:,None],(held_total,period_n,period_n,4))],axis=-1)\nbase_rss=np.einsum("nt,ts,ns->n",mixed[heldout],noise_inverse,mixed[heldout],optimize=True)\ncoefficient_scale=np.sqrt(amplitude_nodes[:,:,None]*template_variance[None]).reshape(amplitude_n,8)\ntensor_scale=torch.as_tensor(coefficient_scale,dtype=torch.float64)\ntensor_gram=torch.as_tensor(joint_gram,dtype=torch.float64)\ntensor_rhs=torch.as_tensor(pair_rhs,dtype=torch.float64)\ntensor_rss=torch.as_tensor(base_rss,dtype=torch.float64)\nevaluate_amplitude=lambda scale: (\n    matrix:=torch.eye(8,dtype=torch.float64)+tensor_gram*scale[None,None,:,None]*scale[None,None,None,:],\n    cholesky:=torch.linalg.cholesky(matrix),\n    inverse:=torch.cholesky_inverse(cholesky),\n    scaled_rhs:=tensor_rhs*scale,\n    mean:=torch.einsum("pqij,npqj->npqi",inverse,scaled_rhs),\n    residual:=tensor_rss[:,None,None]-(scaled_rhs*mean).sum(dim=-1),\n    logdet:=2.*torch.log(torch.diagonal(cholesky,dim1=-2,dim2=-1)).sum(dim=-1),\n    evidence:=-.5*(noise_logdet+logdet[None])-dimension/2.*torch.log(residual),\n    (evidence,inverse))[-1]\nprint("CALIBRATED_PHASE_BASE_INTEGRATION","records",held_total,"amplitude_nodes",amplitude_n,\n    "period_pairs",period_n**2,flush=True)\namplitude_state=torch.vmap(evaluate_amplitude,chunk_size=calibrated_settings["integration_chunk_size"])(tensor_scale)\nbase_evidence=amplitude_state[0].numpy()\nassert np.isfinite(base_evidence).all()\ncheck_a=amplitude_n//2\ncheck_pair=np.unravel_index(base_evidence[check_a,0].argmax(),(period_n,period_n))\ncheck_harmonic=np.concatenate([harmonic[check_pair[0]],harmonic[check_pair[1]]],axis=1)\ncheck_design=check_harmonic*coefficient_scale[check_a][None]\ncheck_covariance=noise_covariance+check_design@check_design.T\ncheck_dense=-.5*np.linalg.slogdet(check_covariance)[1] \\\n    -.5*dimension*np.log(mixed[held_rows[0]]@np.linalg.solve(check_covariance,mixed[held_rows[0]]))\ncheck_fast=base_evidence[check_a,0,check_pair[0],check_pair[1]]\nassert np.isclose(check_dense,check_fast,rtol=1.e-9,atol=1.e-9)\nprint("CALIBRATED_PHASE_DENSE_CHECK",check_dense,check_fast,\n    "remainder_energy_error",np.max(np.abs(remainder_energy-direct_remainder_energy)),flush=True)\nbase_marginal_evidence=logsumexp(base_evidence+np.log(quadrature_weight)[:,None,None,None],axis=0)\njoint_logmass=base_marginal_evidence+np.log(prior[heldout,0,:,None])+np.log(prior[heldout,1,None,:])\njoint_logmass-=logsumexp(joint_logmass,axis=(1,2))[:,None,None]\nbase_joint_mass=np.exp(joint_logmass)\nbase_target_logmass=logsumexp(joint_logmass,axis=2)\n'

structural_calibrated_phase_inference_stage = '\nparticle_n=calibrated_settings["posterior_particles"]\nsobol=qmc.Sobol(d=10*held_total,scramble=True,seed=settings["seed"])\nuniform=sobol.random_base2(int(np.log2(particle_n))).reshape(particle_n,held_total,10).transpose(1,0,2)\nassert particle_n==2**int(np.log2(particle_n)) and ((uniform>0.)&(uniform<1.)).all()\ntensor_uniform=torch.as_tensor(uniform[:,:,0].copy(),dtype=torch.float64)\ntensor_normal=torch.as_tensor(ndtri(uniform[:,:,1:9]),dtype=torch.float64)\ntensor_gamma=torch.as_tensor(gammaincinv(dimension/2.,uniform[:,:,9]),dtype=torch.float64)\ntensor_quadrature_logweight=torch.as_tensor(np.log(quadrature_weight),dtype=torch.float64)\ntensor_background_logprior=torch.as_tensor(np.log(prior[heldout,1]),dtype=torch.float64)\ncoupling_raw=bundle["coupling_parameters"].reshape(2,2)\ncoupling=coupling_raw/np.sqrt(1.+np.sum(coupling_raw**2,axis=1))[:,None]\ntensor_coupling=torch.as_tensor(coupling,dtype=torch.float64)\ntensor_remaining=1.-(tensor_coupling**2).sum(dim=1)\ntensor_sign_prior=torch.as_tensor(sign_logprior,dtype=torch.float64)\ntensor_sign=torch.tensor([1.,-1.],dtype=torch.float64)\n# All target periods are retained. The amplitude/background grid is summed\n# exactly for the Gaussian control, then supplies the conditional proposal for\n# the unchanged nonlinear source phase prior. Gain polarity is marginalized.\nintegrate_calibrated_period=lambda evidence,inverse,rhs: (\n    nuisance_logmass:=evidence+tensor_quadrature_logweight[None,:,None]\n        +tensor_background_logprior[:,None],\n    nuisance_weight:=torch.softmax(nuisance_logmass.reshape(held_total,-1),dim=1),\n    selected:=torch.searchsorted(nuisance_weight.cumsum(dim=1).contiguous(),tensor_uniform),\n    selected_amplitude:=selected//period_n,\n    selected_background:=selected%period_n,\n    selected_inverse:=inverse.reshape(-1,8,8)[selected],\n    selected_scale:=tensor_scale[selected_amplitude],\n    selected_rhs:=torch.gather(rhs,1,selected_background[...,None].expand(-1,-1,8))*selected_scale,\n    selected_mean:=torch.einsum("nqij,nqj->nqi",selected_inverse,selected_rhs),\n    selected_residual:=tensor_rss[:,None]-(selected_rhs*selected_mean).sum(dim=-1),\n    inverse_sigma:=torch.sqrt(2.*tensor_gamma/selected_residual),\n    coefficient_noise:=torch.einsum("nqij,nqj->nqi",torch.linalg.cholesky(selected_inverse),tensor_normal),\n    standard:=selected_mean*inverse_sigma[...,None]+coefficient_noise,\n    complex_coefficient:=standard.reshape(held_total,particle_n,2,2,2).permute(0,2,1,3,4)*tensor_sign,\n    z1:=complex_coefficient[:,:,:,0],\n    z2:=complex_coefficient[:,:,:,1],\n    g1:=torch.stack([z1[...,0]**2-z1[...,1]**2,2.*z1[...,0]*z1[...,1]],dim=-1)\n        /torch.linalg.vector_norm(z1,dim=-1,keepdim=True),\n    fitted:=torch.stack([\n        tensor_coupling[None,:,None,0]*g1[...,0]-tensor_coupling[None,:,None,1]*g1[...,1],\n        tensor_coupling[None,:,None,1]*g1[...,0]+tensor_coupling[None,:,None,0]*g1[...,1]],dim=-1),\n    role_ratio:=-torch.log(tensor_remaining)[None,:,None,None]\n        -.5*((z2[:,:,:,None]-fitted[:,:,:,None]*tensor_sign[None,None,None,:,None])**2).sum(dim=-1)\n            /tensor_remaining[None,:,None,None]+.5*(z2**2).sum(dim=-1)[...,None],\n    ratio:=torch.logsumexp(role_ratio[:,0,:,:,None]+role_ratio[:,1,:,None,:]\n        +tensor_sign_prior[None,None],dim=(-2,-1)),\n    logcorrection:=torch.logsumexp(ratio,dim=-1)-np.log(particle_n),\n    weight:=torch.softmax(ratio,dim=-1),\n    coefficient:=selected_scale*(selected_mean+coefficient_noise/inverse_sigma[...,None]),\n    background_mass:=torch.zeros((held_total,period_n),dtype=torch.float64).scatter_add(\n        1,selected_background,weight),\n    target_coefficient:=(weight[...,None]*coefficient[...,:4]).sum(dim=1),\n    background_coefficient:=torch.zeros((held_total,period_n,4),dtype=torch.float64).scatter_add(\n        1,selected_background[...,None].expand(-1,-1,4),weight[...,None]*coefficient[...,4:]),\n    amplitude_mass:=torch.zeros((held_total,amplitude_n),dtype=torch.float64).scatter_add(\n        1,selected_amplitude,weight),\n    physical_inverse:=inverse*tensor_scale[:,None,:,None]*tensor_scale[:,None,None,:],\n    coefficient_grid:=torch.einsum("aqij,nqj->naqi",physical_inverse,rhs),\n    grid_weight:=nuisance_weight.reshape(held_total,amplitude_n,period_n),\n    base_target_coefficient:=(grid_weight[...,None]*coefficient_grid[...,:4]).sum(dim=(1,2)),\n    base_background_coefficient:=(grid_weight[...,None]*coefficient_grid[...,4:]).sum(dim=1),\n    base_amplitude_mass:=grid_weight.sum(dim=2),\n    ess:=1./(weight**2).sum(dim=-1),\n    relative_se:=torch.sqrt(torch.clamp((particle_n/ess-1.)/(particle_n-1.),min=0.)),\n    (logcorrection,background_mass,target_coefficient,background_coefficient,amplitude_mass,\n        base_target_coefficient,base_background_coefficient,base_amplitude_mass,ess,relative_se))[-1]\nprint("CALIBRATED_PHASE_NONLINEAR_INTEGRATION","particles",particle_n,"seed",settings["seed"],flush=True)\nintegrated=torch.vmap(integrate_calibrated_period,chunk_size=calibrated_settings["integration_chunk_size"])(\n    amplitude_state[0].permute(2,1,0,3),amplitude_state[1].permute(1,0,2,3,4),\n    tensor_rhs.permute(1,0,2,3))\nlogcorrection=integrated[0].numpy().T\nconditional_background_mass=integrated[1].numpy().transpose(1,0,2)\nconditional_target_coefficient=integrated[2].numpy().transpose(1,0,2)\nconditional_background_coefficient=integrated[3].numpy().transpose(1,0,2,3)\nconditional_amplitude_mass=integrated[4].numpy().transpose(1,0,2)\nbase_conditional_target_coefficient=integrated[5].numpy().transpose(1,0,2)\nbase_conditional_background_coefficient=integrated[6].numpy().transpose(1,0,2,3)\nbase_conditional_amplitude_mass=integrated[7].numpy().transpose(1,0,2)\nimportance_ess=integrated[8].numpy().T\nimportance_relative_se=integrated[9].numpy().T\ntarget_logmass=base_target_logmass+logcorrection\ntarget_logmass-=logsumexp(target_logmass,axis=1)[:,None]\ncoupled_target_mass=np.exp(target_logmass)\ncoupled_joint_mass=coupled_target_mass[:,:,None]*conditional_background_mass\nassert np.allclose(coupled_joint_mass.sum(axis=(1,2)),1.)\nrole_mass=np.stack([\n    np.stack([coupled_joint_mass.sum(axis=2),coupled_joint_mass.sum(axis=1)],axis=1),\n    np.stack([base_joint_mass.sum(axis=2),base_joint_mass.sum(axis=1)],axis=1),\n    prior[heldout]],axis=1)\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nrole_selected=role_score.argmax(axis=-1)\nrole_estimate=periods[role_selected]\nrole_confidence=np.take_along_axis(role_score,role_selected[...,None],axis=-1)[...,0]\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\ntarget_coefficient=coupled_target_mass[:,:,None]*conditional_target_coefficient\nbackground_coefficient=np.einsum("np,npqi->nqi",coupled_target_mass,conditional_background_coefficient)\nsource_waveform=np.einsum("pti,npi->nt",harmonic,target_coefficient)\nbackground_waveform=np.einsum("qti,nqi->nt",harmonic,background_coefficient)\nbase_target_mass=np.exp(base_target_logmass)\nbase_target_coefficient=base_target_mass[:,:,None]*base_conditional_target_coefficient\nbase_background_coefficient=np.einsum("np,npqi->nqi",base_target_mass,base_conditional_background_coefficient)\nbase_source_waveform=np.einsum("pti,npi->nt",harmonic,base_target_coefficient)\nbase_background_waveform=np.einsum("qti,nqi->nt",harmonic,base_background_coefficient)\namplitude_mass=np.einsum("np,npa->na",coupled_target_mass,conditional_amplitude_mass)\nbase_amplitude_mass=np.einsum("np,npa->na",base_target_mass,base_conditional_amplitude_mass)\nmethods=np.array(calibrated_settings["methods"])\npredictions=pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],len(methods)),\n    "method":np.tile(methods,held_total),"estimate_h":estimate.ravel(),"confidence":confidence.ravel(),\n    "heldout_fold":fold,"heldout_run":np.repeat(run[heldout],len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    periods=periods,mass=mass,estimate=estimate,confidence=confidence,methods=methods,\n    role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,\n    coupled_joint_mass=coupled_joint_mass,base_joint_mass=base_joint_mass,\n    source_pair_mean=np.stack([source_waveform,background_waveform],axis=1),\n    base_source_pair_mean=np.stack([base_source_waveform,base_background_waveform],axis=1),\n    importance_logcorrection=logcorrection,importance_ess=importance_ess,\n    importance_relative_se=importance_relative_se,amplitude_mass=amplitude_mass,\n    base_amplitude_mass=base_amplitude_mass,amplitude_nodes=amplitude_nodes,\n    amplitude_weight=quadrature_weight,noise_covariance=noise_covariance,\n    base_marginal_evidence=base_marginal_evidence,source_variance=source_variance,\n    coupling=coupling,sign_prior=sign_prior,training_trace_id=trace_id[train],training_groups=training_groups)\nprint("CALIBRATED_PHASE_POSTERIOR","weighted_ess_quantiles",\n    np.quantile(np.sum(coupled_target_mass*importance_ess,axis=1),[0,.1,.5,.9,1]).tolist(),\n    "weighted_relative_se_proxy",\n    np.quantile(np.sqrt(np.sum(coupled_target_mass**2*importance_relative_se**2,axis=1)),\n        [0,.1,.5,.9,1]).tolist(),flush=True)\nexec(compile(structural_source_readout_stage[\n    structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
structural_calibrated_phase_stage = structural_calibrated_phase_training_stage+structural_calibrated_phase_inference_stage
if args.stage=="structural-calibrated-phase-fit":
    exec(compile(structural_calibrated_phase_stage,__file__,"exec"))

structural_observed_calibration_update_stage = '\nraw_mean=signal.mean(axis=1)\nraw_cv=raw_rms/raw_mean\nraw_noise_fraction=np.mean(np.diff(mixed,n=2,axis=1)**2,axis=1)/6.\nassert (raw_cv>0.).all() and (raw_noise_fraction>0.).all()\nobserved_scale=np.column_stack([np.log(raw_cv),np.log(raw_noise_fraction)])\nscale_location=row_weight@observed_scale[train]\nscale_sd=np.sqrt(row_weight@(observed_scale[train]-scale_location)**2)\ncalibration_design=np.column_stack([np.ones(len(mixed)),(observed_scale-scale_location)/scale_sd])\ncalibration_coefficient=np.linalg.solve(\n    np.einsum("n,ni,nj->ij",row_weight,calibration_design[train],calibration_design[train],optimize=True),\n    np.einsum("n,ni,nr->ir",row_weight,calibration_design[train],amplitude_logscale,optimize=True))\nconditional_amplitude_mean=calibration_design@calibration_coefficient\ncalibration_residual=amplitude_logscale-conditional_amplitude_mean[train]\nconditional_amplitude_covariance=np.einsum("n,ni,nj->ij",row_weight,\n    calibration_residual,calibration_residual)\nconditional_inverse=np.linalg.inv(conditional_amplitude_covariance)\nnode_centered=np.log(amplitude_nodes)-amplitude_mean\nnode_logdensity=-.5*np.einsum("ai,ij,aj->a",node_centered,\n    np.linalg.inv(amplitude_covariance),node_centered,optimize=True) \\\n    -.5*np.linalg.slogdet(amplitude_covariance)[1]\nconditional_centered=np.log(amplitude_nodes)[None]-conditional_amplitude_mean[:,None]\nconditional_logdensity=-.5*np.einsum("nai,ij,naj->na",conditional_centered,\n    conditional_inverse,conditional_centered,optimize=True) \\\n    -.5*np.linalg.slogdet(conditional_amplitude_covariance)[1]\nconditional_logweight=np.log(quadrature_weight)[None]+conditional_logdensity-node_logdensity[None]\nconditional_logweight-=logsumexp(conditional_logweight,axis=1)[:,None]\nconditional_weight=np.exp(conditional_logweight)\nquadrature_conditional_mean=conditional_weight@np.log(amplitude_nodes)\nquadrature_centered=np.log(amplitude_nodes)[None]-quadrature_conditional_mean[:,None]\nquadrature_conditional_covariance=np.einsum("na,nai,naj->nij",conditional_weight,\n    quadrature_centered,quadrature_centered,optimize=True)\nprint("OBSERVED_CALIBRATION","coefficient",calibration_coefficient.tolist(),\n    "residual_covariance",conditional_amplitude_covariance.tolist(),\n    "quadrature_standardized_mean_error",\n    np.max(np.abs(quadrature_conditional_mean-conditional_amplitude_mean)\n        /np.sqrt(np.diag(conditional_amplitude_covariance))[None]),\n    "quadrature_covariance_relative_error",\n    np.max(np.abs(quadrature_conditional_covariance-conditional_amplitude_covariance[None]))\n        /np.max(np.abs(conditional_amplitude_covariance)),\n    "weight_ess",np.quantile(1./np.sum(conditional_weight[heldout]**2,axis=1),[.1,.5,.9]).tolist(),flush=True)\n'
structural_observed_calibration_stage = '\nfrom scipy.special import logsumexp,ndtri,gammaincinv\nfrom scipy.stats import qmc\nfrom joblib import load,dump\nimport torch\nexec(compile(structural_phase_source_training_stage[\n    :structural_phase_source_training_stage.index("source_objective =")],__file__,"exec"))\ncalibrated_settings=application["structural_observed_calibration"]\nsource_stem=application["structural_phase_source"]["stem"]\nsource_stem=source_stem.with_name(source_stem.name+"_common_fold"+str(fold))\nbundle=load(source_stem.with_suffix(".joblib"))\nassert np.array_equal(bundle["training_trace_id"],trace_id[train])\nsource_variance=bundle["source_variance"]\nsource_state=source_evidence(np.log(source_variance).ravel())\nsource_logposterior=source_state[0]+log_anchor\nsource_logposterior-=logsumexp(source_logposterior,axis=-1)[...,None]\nsource_posterior=np.exp(source_logposterior)\n# Optical trajectories stay in the observed mixture\'s scale. Unknown reference\n# periods are integrated; no record is discarded or declared non-rhythmic.\noptical_pair=np.stack([target,background],axis=-1)\noptical_gain=np.linalg.solve(np.einsum("nti,ntj->nij",optical_pair,optical_pair),\n    np.einsum("nti,nt->ni",optical_pair,mixed[train])[...,None])[...,0]\ncalibration_scale=optical_gain*np.sqrt(source_energy)\ntemplate_variance=np.repeat(source_variance/(2.*source_variance.sum(axis=1))[:,None],2,axis=1)\nsource_sigma2=source_state[3]/(dimension-2.)\nsource_mean=source_state[2]\nsource_second=source_mean**2+source_sigma2[...,None]*np.diagonal(\n    source_state[4],axis1=-2,axis2=-1)[None]\nsource_scale_second=np.sum(source_second/template_variance[None,:,None],axis=-1)/4.\nperiodic_scale=calibration_scale**2*np.sum(source_posterior*source_scale_second,axis=-1)\nsource_wave_mean=np.einsum("pti,nrpi->nrpt",harmonic,source_mean,optimize=True)\nsource_marginal_mean=np.einsum("nrp,nrpt->nrt",source_posterior,source_wave_mean,\n    optimize=True)*calibration_scale[...,None]\nharmonic_frequency=np.fft.rfft(harmonic,n=2*length,axis=1)\nsource_frequency=np.fft.rfft(source_wave_mean,n=2*length,axis=-1)\nsource_frequency_variance=np.einsum("pfi,rpij,pfj->rpf",harmonic_frequency.conj(),\n    source_state[4],harmonic_frequency,optimize=True).real\nsource_expected_power=np.einsum("nrp,nrpf->nrf",source_posterior,\n    np.abs(source_frequency)**2+source_sigma2[...,None]*source_frequency_variance[None],\n    optimize=True)*calibration_scale[...,None]**2\nsource_mean_frequency=np.fft.rfft(source_marginal_mean,n=2*length,axis=-1)\nremainder_mean=mixed[train]-source_marginal_mean.sum(axis=1)\nremainder_spectrum=np.abs(np.fft.rfft(remainder_mean,n=2*length,axis=-1))**2 \\\n    +np.sum(source_expected_power-np.abs(source_mean_frequency)**2,axis=1)\nassert remainder_spectrum.min()>-1.e-8\nremainder_autocovariance=np.fft.irfft(remainder_spectrum,n=2*length,axis=-1)[:,:length]/length\nremainder_energy=remainder_autocovariance[:,0]\nsource_gram_trace=np.einsum("pij,rpji->rp",source_gram,source_state[4])\ndirect_source_energy=np.einsum("nrp,nrp->nr",source_posterior,\n    np.mean(source_wave_mean**2,axis=-1)+source_sigma2*source_gram_trace[None]/length,\n    optimize=True)*calibration_scale**2\ndirect_remainder_energy=np.mean(remainder_mean**2,axis=1)+np.sum(\n    direct_source_energy-np.mean(source_marginal_mean**2,axis=-1),axis=1)\nassert np.allclose(remainder_energy,direct_remainder_energy,rtol=1.e-9,atol=1.e-9)\nassert (remainder_energy>0.).all() and (periodic_scale>0.).all()\nlag=np.abs(np.arange(length)[:,None]-np.arange(length)[None])\nprojection=np.eye(length)-base[0]@base[0].T\nnoise_covariance=projection@(row_weight@(remainder_autocovariance/remainder_energy[:,None]))[lag]@projection\nnoise_covariance*=dimension/np.trace(noise_covariance)\nnoise_covariance+=base[0]@base[0].T\nnoise_inverse=np.linalg.inv(noise_covariance)\nnoise_logdet=np.linalg.slogdet(noise_covariance)[1]\nassert np.linalg.eigvalsh(noise_covariance).min()>0.\namplitude_logscale=np.log(periodic_scale/remainder_energy[:,None])\namplitude_mean=row_weight@amplitude_logscale\ncentered_logscale=amplitude_logscale-amplitude_mean\namplitude_covariance=np.einsum("n,ni,nj->ij",row_weight,centered_logscale,centered_logscale)\nassert np.linalg.eigvalsh(amplitude_covariance).min()>0.\nquadrature_x,quadrature_w=np.polynomial.hermite.hermgauss(\n    calibrated_settings["amplitude_quadrature_order"])\nquadrature_standard=np.stack(np.meshgrid(quadrature_x,quadrature_x,indexing="ij"),\n    axis=-1).reshape(-1,2)*np.sqrt(2.)\nquadrature_weight=(quadrature_w[:,None]*quadrature_w[None]).ravel()/np.pi\namplitude_nodes=np.exp(amplitude_mean+quadrature_standard@np.linalg.cholesky(amplitude_covariance).T)\namplitude_n=len(amplitude_nodes)\ngain_sign=(optical_gain<0.).astype(int)\ngain_sign_index=gain_sign[:,0]*2+gain_sign[:,1]\nsign_prior=np.bincount(gain_sign_index,weights=row_weight,minlength=4).reshape(2,2)\nsign_logprior=np.log(np.maximum(sign_prior,np.finfo(float).tiny))\nsign_logprior[sign_prior==0.]=-np.inf\nassert np.isclose(quadrature_weight.sum(),1.) and np.isclose(sign_prior.sum(),1.)\nexec(compile(structural_observed_calibration_update_stage,__file__,"exec"))\nprint("CALIBRATED_PHASE_TRAIN","records",len(train_rows),"amplitude_log_mean",amplitude_mean.tolist(),\n    "amplitude_log_covariance",amplitude_covariance.tolist(),"sign_prior",sign_prior.tolist(),\n    "remainder_energy",np.quantile(remainder_energy,[.1,.5,.9]).tolist(),flush=True)\nprint("CALIBRATED_PHASE_POWER","observed_periodic_fraction_quantiles",\n    np.quantile(periodic_scale[:,0]/periodic_scale.sum(axis=1),[.1,.5,.9]).tolist(),\n    "quadrature_prior_mean_fraction",float(quadrature_weight@(amplitude_nodes[:,0]/amplitude_nodes.sum(axis=1))),\n    "quadrature_nodes",amplitude_n,flush=True)\nstem=calibrated_settings["stem"].with_name(\n    calibrated_settings["stem"].name+"_common_fold"+str(fold))\ndump({"source_variance":source_variance,"template_variance":template_variance,\n    "amplitude_log_mean":amplitude_mean,"amplitude_log_covariance":amplitude_covariance,\n    "calibration_feature_location":scale_location,"calibration_feature_sd":scale_sd,\n    "calibration_coefficient":calibration_coefficient,\n    "conditional_amplitude_covariance":conditional_amplitude_covariance,\n    "amplitude_nodes":amplitude_nodes,"amplitude_weight":quadrature_weight,\n    "sign_prior":sign_prior,"noise_covariance":noise_covariance,\n    "coupling_parameters":bundle["coupling_parameters"],"training_trace_id":trace_id[train],\n    "training_groups":training_groups,"settings":dict(calibrated_settings)},stem.with_suffix(".joblib"))\nharmonic_metric=np.einsum("ts,psi->pti",noise_inverse,harmonic,optimize=True)\ngram=np.einsum("pti,qtj->pqij",harmonic,harmonic_metric,optimize=True)\ngrid_index=np.arange(period_n)\nsingle_gram=gram[grid_index,grid_index]\npair_shape=(period_n,period_n,4,4)\njoint_gram=np.concatenate([\n    np.concatenate([np.broadcast_to(single_gram[:,None],pair_shape),gram],axis=-1),\n    np.concatenate([gram.swapaxes(-1,-2),np.broadcast_to(single_gram[None],pair_shape)],axis=-1)],axis=-2)\nrhs=np.einsum("nt,pti->npi",mixed[heldout],harmonic_metric,optimize=True)\nheld_total=len(held_rows)\npair_rhs=np.concatenate([\n    np.broadcast_to(rhs[:,:,None],(held_total,period_n,period_n,4)),\n    np.broadcast_to(rhs[:,None],(held_total,period_n,period_n,4))],axis=-1)\nbase_rss=np.einsum("nt,ts,ns->n",mixed[heldout],noise_inverse,mixed[heldout],optimize=True)\ncoefficient_scale=np.sqrt(amplitude_nodes[:,:,None]*template_variance[None]).reshape(amplitude_n,8)\ntensor_scale=torch.as_tensor(coefficient_scale,dtype=torch.float64)\ntensor_gram=torch.as_tensor(joint_gram,dtype=torch.float64)\ntensor_rhs=torch.as_tensor(pair_rhs,dtype=torch.float64)\ntensor_rss=torch.as_tensor(base_rss,dtype=torch.float64)\nevaluate_amplitude=lambda scale: (\n    matrix:=torch.eye(8,dtype=torch.float64)+tensor_gram*scale[None,None,:,None]*scale[None,None,None,:],\n    cholesky:=torch.linalg.cholesky(matrix),\n    inverse:=torch.cholesky_inverse(cholesky),\n    scaled_rhs:=tensor_rhs*scale,\n    mean:=torch.einsum("pqij,npqj->npqi",inverse,scaled_rhs),\n    residual:=tensor_rss[:,None,None]-(scaled_rhs*mean).sum(dim=-1),\n    logdet:=2.*torch.log(torch.diagonal(cholesky,dim1=-2,dim2=-1)).sum(dim=-1),\n    evidence:=-.5*(noise_logdet+logdet[None])-dimension/2.*torch.log(residual),\n    (evidence,inverse))[-1]\nprint("CALIBRATED_PHASE_BASE_INTEGRATION","records",held_total,"amplitude_nodes",amplitude_n,\n    "period_pairs",period_n**2,flush=True)\namplitude_state=torch.vmap(evaluate_amplitude,chunk_size=calibrated_settings["integration_chunk_size"])(tensor_scale)\nbase_evidence=amplitude_state[0].numpy()\nassert np.isfinite(base_evidence).all()\ncheck_a=amplitude_n//2\ncheck_pair=np.unravel_index(base_evidence[check_a,0].argmax(),(period_n,period_n))\ncheck_harmonic=np.concatenate([harmonic[check_pair[0]],harmonic[check_pair[1]]],axis=1)\ncheck_design=check_harmonic*coefficient_scale[check_a][None]\ncheck_covariance=noise_covariance+check_design@check_design.T\ncheck_dense=-.5*np.linalg.slogdet(check_covariance)[1] \\\n    -.5*dimension*np.log(mixed[held_rows[0]]@np.linalg.solve(check_covariance,mixed[held_rows[0]]))\ncheck_fast=base_evidence[check_a,0,check_pair[0],check_pair[1]]\nassert np.isclose(check_dense,check_fast,rtol=1.e-9,atol=1.e-9)\nprint("CALIBRATED_PHASE_DENSE_CHECK",check_dense,check_fast,\n    "remainder_energy_error",np.max(np.abs(remainder_energy-direct_remainder_energy)),flush=True)\nbase_marginal_evidence=logsumexp(base_evidence+conditional_logweight[heldout].T[:,:,None,None],axis=0)\njoint_logmass=base_marginal_evidence+np.log(prior[heldout,0,:,None])+np.log(prior[heldout,1,None,:])\njoint_logmass-=logsumexp(joint_logmass,axis=(1,2))[:,None,None]\nbase_joint_mass=np.exp(joint_logmass)\nbase_target_logmass=logsumexp(joint_logmass,axis=2)\n\nparticle_n=calibrated_settings["posterior_particles"]\nsobol=qmc.Sobol(d=10*held_total,scramble=True,seed=settings["seed"])\nuniform=sobol.random_base2(int(np.log2(particle_n))).reshape(particle_n,held_total,10).transpose(1,0,2)\nassert particle_n==2**int(np.log2(particle_n)) and ((uniform>0.)&(uniform<1.)).all()\ntensor_uniform=torch.as_tensor(uniform[:,:,0].copy(),dtype=torch.float64)\ntensor_normal=torch.as_tensor(ndtri(uniform[:,:,1:9]),dtype=torch.float64)\ntensor_gamma=torch.as_tensor(gammaincinv(dimension/2.,uniform[:,:,9]),dtype=torch.float64)\ntensor_quadrature_logweight=torch.as_tensor(conditional_logweight[heldout],dtype=torch.float64)\ntensor_background_logprior=torch.as_tensor(np.log(prior[heldout,1]),dtype=torch.float64)\ncoupling_raw=bundle["coupling_parameters"].reshape(2,2)\ncoupling=coupling_raw/np.sqrt(1.+np.sum(coupling_raw**2,axis=1))[:,None]\ntensor_coupling=torch.as_tensor(coupling,dtype=torch.float64)\ntensor_remaining=1.-(tensor_coupling**2).sum(dim=1)\ntensor_sign_prior=torch.as_tensor(sign_logprior,dtype=torch.float64)\ntensor_sign=torch.tensor([1.,-1.],dtype=torch.float64)\n# All target periods are retained. The amplitude/background grid is summed\n# exactly for the Gaussian control, then supplies the conditional proposal for\n# the unchanged nonlinear source phase prior. Gain polarity is marginalized.\nintegrate_calibrated_period=lambda evidence,inverse,rhs: (\n    nuisance_logmass:=evidence+tensor_quadrature_logweight[:,:,None]\n        +tensor_background_logprior[:,None],\n    nuisance_weight:=torch.softmax(nuisance_logmass.reshape(held_total,-1),dim=1),\n    selected:=torch.searchsorted(nuisance_weight.cumsum(dim=1).contiguous(),tensor_uniform),\n    selected_amplitude:=selected//period_n,\n    selected_background:=selected%period_n,\n    selected_inverse:=inverse.reshape(-1,8,8)[selected],\n    selected_scale:=tensor_scale[selected_amplitude],\n    selected_rhs:=torch.gather(rhs,1,selected_background[...,None].expand(-1,-1,8))*selected_scale,\n    selected_mean:=torch.einsum("nqij,nqj->nqi",selected_inverse,selected_rhs),\n    selected_residual:=tensor_rss[:,None]-(selected_rhs*selected_mean).sum(dim=-1),\n    inverse_sigma:=torch.sqrt(2.*tensor_gamma/selected_residual),\n    coefficient_noise:=torch.einsum("nqij,nqj->nqi",torch.linalg.cholesky(selected_inverse),tensor_normal),\n    standard:=selected_mean*inverse_sigma[...,None]+coefficient_noise,\n    complex_coefficient:=standard.reshape(held_total,particle_n,2,2,2).permute(0,2,1,3,4)*tensor_sign,\n    z1:=complex_coefficient[:,:,:,0],\n    z2:=complex_coefficient[:,:,:,1],\n    g1:=torch.stack([z1[...,0]**2-z1[...,1]**2,2.*z1[...,0]*z1[...,1]],dim=-1)\n        /torch.linalg.vector_norm(z1,dim=-1,keepdim=True),\n    fitted:=torch.stack([\n        tensor_coupling[None,:,None,0]*g1[...,0]-tensor_coupling[None,:,None,1]*g1[...,1],\n        tensor_coupling[None,:,None,1]*g1[...,0]+tensor_coupling[None,:,None,0]*g1[...,1]],dim=-1),\n    role_ratio:=-torch.log(tensor_remaining)[None,:,None,None]\n        -.5*((z2[:,:,:,None]-fitted[:,:,:,None]*tensor_sign[None,None,None,:,None])**2).sum(dim=-1)\n            /tensor_remaining[None,:,None,None]+.5*(z2**2).sum(dim=-1)[...,None],\n    ratio:=torch.logsumexp(role_ratio[:,0,:,:,None]+role_ratio[:,1,:,None,:]\n        +tensor_sign_prior[None,None],dim=(-2,-1)),\n    logcorrection:=torch.logsumexp(ratio,dim=-1)-np.log(particle_n),\n    weight:=torch.softmax(ratio,dim=-1),\n    coefficient:=selected_scale*(selected_mean+coefficient_noise/inverse_sigma[...,None]),\n    background_mass:=torch.zeros((held_total,period_n),dtype=torch.float64).scatter_add(\n        1,selected_background,weight),\n    target_coefficient:=(weight[...,None]*coefficient[...,:4]).sum(dim=1),\n    background_coefficient:=torch.zeros((held_total,period_n,4),dtype=torch.float64).scatter_add(\n        1,selected_background[...,None].expand(-1,-1,4),weight[...,None]*coefficient[...,4:]),\n    amplitude_mass:=torch.zeros((held_total,amplitude_n),dtype=torch.float64).scatter_add(\n        1,selected_amplitude,weight),\n    physical_inverse:=inverse*tensor_scale[:,None,:,None]*tensor_scale[:,None,None,:],\n    coefficient_grid:=torch.einsum("aqij,nqj->naqi",physical_inverse,rhs),\n    grid_weight:=nuisance_weight.reshape(held_total,amplitude_n,period_n),\n    base_target_coefficient:=(grid_weight[...,None]*coefficient_grid[...,:4]).sum(dim=(1,2)),\n    base_background_coefficient:=(grid_weight[...,None]*coefficient_grid[...,4:]).sum(dim=1),\n    base_amplitude_mass:=grid_weight.sum(dim=2),\n    ess:=1./(weight**2).sum(dim=-1),\n    relative_se:=torch.sqrt(torch.clamp((particle_n/ess-1.)/(particle_n-1.),min=0.)),\n    (logcorrection,background_mass,target_coefficient,background_coefficient,amplitude_mass,\n        base_target_coefficient,base_background_coefficient,base_amplitude_mass,ess,relative_se))[-1]\nprint("CALIBRATED_PHASE_NONLINEAR_INTEGRATION","particles",particle_n,"seed",settings["seed"],flush=True)\nintegrated=torch.vmap(integrate_calibrated_period,chunk_size=calibrated_settings["integration_chunk_size"])(\n    amplitude_state[0].permute(2,1,0,3),amplitude_state[1].permute(1,0,2,3,4),\n    tensor_rhs.permute(1,0,2,3))\nlogcorrection=integrated[0].numpy().T\nconditional_background_mass=integrated[1].numpy().transpose(1,0,2)\nconditional_target_coefficient=integrated[2].numpy().transpose(1,0,2)\nconditional_background_coefficient=integrated[3].numpy().transpose(1,0,2,3)\nconditional_amplitude_mass=integrated[4].numpy().transpose(1,0,2)\nbase_conditional_target_coefficient=integrated[5].numpy().transpose(1,0,2)\nbase_conditional_background_coefficient=integrated[6].numpy().transpose(1,0,2,3)\nbase_conditional_amplitude_mass=integrated[7].numpy().transpose(1,0,2)\nimportance_ess=integrated[8].numpy().T\nimportance_relative_se=integrated[9].numpy().T\ntarget_logmass=base_target_logmass+logcorrection\ntarget_logmass-=logsumexp(target_logmass,axis=1)[:,None]\ncoupled_target_mass=np.exp(target_logmass)\ncoupled_joint_mass=coupled_target_mass[:,:,None]*conditional_background_mass\nassert np.allclose(coupled_joint_mass.sum(axis=(1,2)),1.)\nrole_mass=np.stack([\n    np.stack([coupled_joint_mass.sum(axis=2),coupled_joint_mass.sum(axis=1)],axis=1),\n    np.stack([base_joint_mass.sum(axis=2),base_joint_mass.sum(axis=1)],axis=1),\n    prior[heldout]],axis=1)\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nrole_selected=role_score.argmax(axis=-1)\nrole_estimate=periods[role_selected]\nrole_confidence=np.take_along_axis(role_score,role_selected[...,None],axis=-1)[...,0]\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\ntarget_coefficient=coupled_target_mass[:,:,None]*conditional_target_coefficient\nbackground_coefficient=np.einsum("np,npqi->nqi",coupled_target_mass,conditional_background_coefficient)\nsource_waveform=np.einsum("pti,npi->nt",harmonic,target_coefficient)\nbackground_waveform=np.einsum("qti,nqi->nt",harmonic,background_coefficient)\nbase_target_mass=np.exp(base_target_logmass)\nbase_target_coefficient=base_target_mass[:,:,None]*base_conditional_target_coefficient\nbase_background_coefficient=np.einsum("np,npqi->nqi",base_target_mass,base_conditional_background_coefficient)\nbase_source_waveform=np.einsum("pti,npi->nt",harmonic,base_target_coefficient)\nbase_background_waveform=np.einsum("qti,nqi->nt",harmonic,base_background_coefficient)\namplitude_mass=np.einsum("np,npa->na",coupled_target_mass,conditional_amplitude_mass)\nbase_amplitude_mass=np.einsum("np,npa->na",base_target_mass,base_conditional_amplitude_mass)\nmethods=np.array(calibrated_settings["methods"])\npredictions=pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],len(methods)),\n    "method":np.tile(methods,held_total),"estimate_h":estimate.ravel(),"confidence":confidence.ravel(),\n    "heldout_fold":fold,"heldout_run":np.repeat(run[heldout],len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    periods=periods,mass=mass,estimate=estimate,confidence=confidence,methods=methods,\n    role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,\n    coupled_joint_mass=coupled_joint_mass,base_joint_mass=base_joint_mass,\n    source_pair_mean=np.stack([source_waveform,background_waveform],axis=1),\n    base_source_pair_mean=np.stack([base_source_waveform,base_background_waveform],axis=1),\n    importance_logcorrection=logcorrection,importance_ess=importance_ess,\n    importance_relative_se=importance_relative_se,amplitude_mass=amplitude_mass,\n    base_amplitude_mass=base_amplitude_mass,amplitude_nodes=amplitude_nodes,\n    amplitude_weight=quadrature_weight,conditional_amplitude_weight=conditional_weight[heldout],\n    noise_covariance=noise_covariance,\n    base_marginal_evidence=base_marginal_evidence,source_variance=source_variance,\n    coupling=coupling,sign_prior=sign_prior,training_trace_id=trace_id[train],training_groups=training_groups)\nprint("CALIBRATED_PHASE_POSTERIOR","weighted_ess_quantiles",\n    np.quantile(np.sum(coupled_target_mass*importance_ess,axis=1),[0,.1,.5,.9,1]).tolist(),\n    "weighted_relative_se_proxy",\n    np.quantile(np.sqrt(np.sum(coupled_target_mass**2*importance_relative_se**2,axis=1)),\n        [0,.1,.5,.9,1]).tolist(),flush=True)\nexec(compile(structural_source_readout_stage[\n    structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
