structural_diffusion_source_setup_stage = '\nfrom scipy.optimize import minimize\nfrom scipy.integrate import solve_ivp\nfrom scipy.special import logsumexp,ndtri\nfrom scipy.stats import qmc\nfrom joblib import load,dump\nimport torch\nfrom torch import nn\nexec(compile(structural_source_data_stage,__file__,"exec"))\ndiffusion_settings=application["structural_diffusion_source"]\nassert not native\ntorch.set_num_threads(CONFIG["threads"])\ntorch.set_num_interop_threads(CONFIG["threads"])\ntorch.manual_seed(settings["seed"])\nrng=np.random.default_rng(settings["seed"])\nexec(compile(structural_period_flow_fit_stage[\n    structural_period_flow_fit_stage.index("background_raw ="):\n    structural_period_flow_fit_stage.index("layout_count,layout_index")],__file__,"exec"))\ntrain_rows,held_rows=np.flatnonzero(train),np.flatnonzero(heldout)\ntraining_groups=np.unique(run[train])\nassert np.unique(count).size==1\ndimension=length-2\noptical_pair=np.stack([target,background],axis=-1)\noptical_gain=np.linalg.solve(np.einsum("nti,ntj->nij",optical_pair,optical_pair),\n    np.einsum("nti,nt->ni",optical_pair,mixed[train])[...,None])[...,0]\noptical_amplitude=optical_gain*np.sqrt(source_energy)\nobservation_remainder=mixed[train]-np.einsum("ntr,nr->nt",optical_pair,optical_gain)\nremainder_energy=np.mean(observation_remainder**2,axis=1)\nremainder_unit=observation_remainder/np.sqrt(remainder_energy)[:,None]\nremainder_autocovariance=np.fft.irfft(np.abs(np.fft.rfft(\n    remainder_unit,n=2*length,axis=1))**2,n=2*length,axis=1)[:,:length]/length\nlag=np.abs(np.arange(length)[:,None]-np.arange(length)[None])\naffine_complement=np.linalg.qr(base[0],mode="complete")[0][:,2:]\nnoise_covariance=affine_complement.T@(row_weight@remainder_autocovariance)[lag]@affine_complement\nnoise_covariance*=dimension/np.trace(noise_covariance)\nnoise_eigenvalue,noise_eigenvector=np.linalg.eigh(noise_covariance)\nassert noise_eigenvalue.min()>0.\ncoordinate_basis=affine_complement@noise_eigenvector\nsource_coordinate=source_unit@coordinate_basis\nsource_autocovariance=np.fft.irfft(np.abs(np.fft.rfft(\n    source_unit,n=2*length,axis=-1))**2,n=2*length,axis=-1)[...,:length]/length\nstationary_covariance=(np.einsum("n,nrt->rt",row_weight,source_autocovariance))[:,lag]\nsource_covariance=np.einsum("ti,rts,sj->rij",coordinate_basis,\n    stationary_covariance,coordinate_basis,optimize=True)\nsource_covariance*=length/np.trace(source_covariance,axis1=-2,axis2=-1)[:,None,None]\nsource_eigenvalue,source_eigenvector=np.linalg.eigh(source_covariance)\nassert source_eigenvalue.min()>0.\ncalibration_log=np.column_stack([np.log(np.abs(optical_amplitude)),np.log(remainder_energy)])\ncalibration_mean=row_weight@calibration_log\ncalibration_centered=calibration_log-calibration_mean\ncalibration_covariance=np.einsum("n,ni,nj->ij",row_weight,calibration_centered,calibration_centered)\ncalibration_eigenvalue,calibration_eigenvector=np.linalg.eigh(calibration_covariance)\nassert calibration_eigenvalue.min()>0.\ngain_sign=(optical_gain<0.).astype(int)\ngain_sign_index=gain_sign[:,0]*2+gain_sign[:,1]\nsign_prior=np.bincount(gain_sign_index,weights=row_weight,minlength=4)\nactive_sign=np.flatnonzero(sign_prior>0.)\nsign_values=1.-2.*np.stack([active_sign//2,active_sign%2],axis=1)\nsign_logprior=np.log(sign_prior[active_sign])\n# Source identity is the optical role; the neural prior never receives a mixed\n# trace or a reference period. The physical observation is used only at inversion.\ndata_sd=np.sqrt(length/dimension)\nsigma_bounds=data_sd*np.asarray(diffusion_settings["source_noise_relative_bounds"])\nquadrature_x,quadrature_weight=np.polynomial.legendre.leggauss(diffusion_settings["training_particles"])\nquadrature_weight/=quadrature_weight.sum()\nlog_sigma=np.log(sigma_bounds).mean()+np.diff(np.log(sigma_bounds))[0]*quadrature_x/2.\nsigma=np.exp(log_sigma)\ntraining_noise=rng.standard_normal((len(train_rows),2,len(sigma),dimension))\ntraining_coordinate=source_coordinate[:,:,None]+sigma[None,None,:,None]*training_noise\ntraining_eigencoordinate=np.einsum("nrqd,rde->nrqe",training_coordinate,source_eigenvector,optimize=True)\ngaussian_gain=source_eigenvalue[:,None]/(source_eigenvalue[:,None]+sigma[None,:,None]**2)\ngaussian_coordinate=np.einsum("nrqe,rde->nrqd",\n    training_eigencoordinate*gaussian_gain[None],source_eigenvector,optimize=True)\ntraining_wave=training_coordinate@coordinate_basis.T\ngaussian_wave=gaussian_coordinate@coordinate_basis.T\ninput_scale=1./np.sqrt(sigma**2+data_sd**2)\noutput_scale=sigma*data_sd/np.sqrt(sigma**2+data_sd**2)\nrole_code=np.array([1.,-1.])[None,:,None,None]\ntraining_input=np.stack([\n    training_wave*input_scale[None,None,:,None],\n    np.broadcast_to(role_code,training_wave.shape),\n    np.broadcast_to((log_sigma-np.log(data_sd))[None,None,:,None]/4.,training_wave.shape)],axis=-2).reshape(\n        -1,3,length)\ntraining_output=((source_unit[:,:,None]-gaussian_wave)/output_scale[None,None,:,None]).reshape(-1,length)\ntraining_weight=np.broadcast_to(row_weight[:,None,None]*quadrature_weight[None,None]/2.,\n    (len(train_rows),2,len(sigma))).reshape(-1,1)/length\ntensor_training_input=torch.as_tensor(training_input,dtype=torch.float32)\ntensor_training_output=torch.as_tensor(training_output,dtype=torch.float32)\ntensor_training_weight=torch.as_tensor(training_weight,dtype=torch.float32)\ntensor_affine=torch.as_tensor(base[0].copy(),dtype=torch.float32)\ntensor_coordinate_basis=torch.as_tensor(coordinate_basis,dtype=torch.float32)\nwidth=diffusion_settings["width"]\nkernel=settings["kernel_size"]\ndilation=diffusion_settings["dilations"]\ndenoiser_model=nn.Sequential(\n    nn.Conv1d(3,width,kernel,padding=(kernel//2)*dilation[0],dilation=dilation[0],padding_mode="replicate"),\n    nn.Tanh(),\n    nn.Conv1d(width,width,kernel,padding=(kernel//2)*dilation[1],dilation=dilation[1],padding_mode="replicate"),\n    nn.Tanh(),\n    nn.Conv1d(width,width,kernel,padding=(kernel//2)*dilation[2],dilation=dilation[2],padding_mode="replicate"),\n    nn.Tanh(),\n    nn.Conv1d(width,width,kernel,padding=(kernel//2)*dilation[3],dilation=dilation[3],padding_mode="replicate"),\n    nn.Tanh(),nn.Conv1d(width,1,1))\nnn.init.zeros_(denoiser_model[-1].weight)\nnn.init.zeros_(denoiser_model[-1].bias)\nparameter_names=tuple(dict(denoiser_model.named_parameters()))\nparameter_shapes=tuple(map(torch.Tensor.size,denoiser_model.parameters()))\nparameter_sizes=tuple(map(torch.Tensor.numel,denoiser_model.parameters()))\ninitial=nn.utils.parameters_to_vector(denoiser_model.parameters()).detach().numpy().astype(np.float64)\nunpack=lambda vector:dict(zip(parameter_names,\n    map(torch.reshape,torch.split(vector,parameter_sizes),parameter_shapes)))\ndenoiser_residual=lambda vector,inputs: (\n    value:=torch.func.functional_call(denoiser_model,unpack(vector),(inputs,))[:,0],\n    value-(value@tensor_affine)@tensor_affine.T)[-1]\nobjective=lambda vector: ((denoiser_residual(vector,tensor_training_input)-tensor_training_output).square()\n    *tensor_training_weight).sum()+settings["weight_decay"]*vector.square().mean()\nautograd_objective=torch.func.grad_and_value(objective)\nto_scipy=lambda gradient,value:(value.detach().item(),gradient.detach().numpy().astype(np.float64))\nscipy_objective=lambda vector:to_scipy(*autograd_objective(torch.as_tensor(vector,dtype=torch.float32)))\nstem=diffusion_settings["stem"].with_name(\n    diffusion_settings["stem"].name+"_common_fold"+str(fold))\n'
structural_diffusion_source_train_stage = '\ninitial_loss,initial_gradient=scipy_objective(initial)\nassert np.isfinite(initial_loss) and np.isfinite(initial_gradient).all()\nloss_history=[[0,initial_loss]]\nprint("DIFFUSION_SOURCE_TRAIN","records",len(train_rows),"roles",2,\n    "noise_pairs",len(training_input),"parameters",len(initial),"initial_loss",initial_loss,\n    "seed",settings["seed"],flush=True)\nresult=minimize(scipy_objective,initial,jac=True,method="L-BFGS-B",\n    callback=lambda intermediate_result:(loss_history.append([len(loss_history),float(intermediate_result.fun)]),\n        len(loss_history)%50==0 and print("DIFFUSION_SOURCE_PROGRESS",len(loss_history)-1,\n            intermediate_result.fun,flush=True)),\n    options={"maxiter":diffusion_settings["maxiter"],"ftol":diffusion_settings["ftol"],\n        "gtol":settings["gtol"],"maxls":settings["maxls"]})\nparameters=torch.as_tensor(result.x,dtype=torch.float32)\ntraining_error=(denoiser_residual(parameters,tensor_training_input)-tensor_training_output).square()\nrole_loss=(training_error*tensor_training_weight).reshape(len(train_rows),2,len(sigma),length).sum(\n    dim=(0,2,3))*2.\nbaseline_role_loss=(tensor_training_output.square()*tensor_training_weight).reshape(\n    len(train_rows),2,len(sigma),length).sum(dim=(0,2,3))*2.\ndump({"parameters":result.x,"parameter_names":parameter_names,"parameter_shapes":parameter_shapes,\n    "optimization":result,"training_loss_history":np.asarray(loss_history),\n    "source_covariance":source_covariance,"coordinate_basis":coordinate_basis,\n    "noise_eigenvalue":noise_eigenvalue,"calibration_mean":calibration_mean,\n    "calibration_covariance":calibration_covariance,"sign_prior":sign_prior,\n    "training_trace_id":trace_id[train],"training_groups":training_groups,\n    "settings":dict(diffusion_settings),"neural_role_loss":role_loss.detach().numpy(),\n    "gaussian_role_loss":baseline_role_loss.numpy(),"seed":settings["seed"],\n    "heldout_optical_read":False,\n    "target":"optically_separated_target_luminescence_waveform"},stem.with_suffix(".joblib"))\nprint("DIFFUSION_SOURCE_OPTIMIZED","loss",result.fun,"iterations",result.nit,\n    "status",str(result.message),"neural_role_loss",role_loss.detach().numpy().tolist(),\n    "gaussian_role_loss",baseline_role_loss.numpy().tolist(),flush=True)\nraise SystemExit(0)\n'
if args.stage=="structural-diffusion-source-fit":
    exec(compile(structural_diffusion_source_setup_stage+structural_diffusion_source_train_stage,__file__,"exec"))

structural_diffusion_inverse_core_stage = '\ntensor_source_eigenvalue=torch.as_tensor(source_eigenvalue,dtype=torch.float32)\ntensor_source_eigenvector=torch.as_tensor(source_eigenvector,dtype=torch.float32)\ntensor_calibration_mean=torch.as_tensor(calibration_mean,dtype=torch.float32)\ntensor_calibration_eigenvalue=torch.as_tensor(calibration_eigenvalue,dtype=torch.float32)\ntensor_calibration_eigenvector=torch.as_tensor(calibration_eigenvector,dtype=torch.float32)\ntensor_noise_eigenvalue=torch.as_tensor(noise_eigenvalue,dtype=torch.float32)\ntensor_sign_values=torch.as_tensor(sign_values,dtype=torch.float32)\ntensor_sign_logprior=torch.as_tensor(sign_logprior,dtype=torch.float32)\ntensor_role_code=torch.tensor([1.,-1.],dtype=torch.float32)\nstate_dimension=2*dimension+3\nneural_coordinate_residual=lambda coordinate,sigma: (\n    wave:=coordinate@tensor_coordinate_basis.T,\n    network_input:=torch.stack([\n        wave/np.sqrt(sigma**2+data_sd**2),\n        torch.ones_like(wave)*tensor_role_code[None,:,None],\n        torch.ones_like(wave)*np.log(sigma/data_sd)/4.],dim=2).reshape(-1,3,length),\n    correction:=denoiser_residual(parameters,network_input).reshape(-1,2,length)@tensor_coordinate_basis,\n    correction*(sigma*data_sd/np.sqrt(sigma**2+data_sd**2)))[-1]\ncoordinate_residual={0:lambda coordinate,sigma:torch.zeros_like(coordinate),\n    1:neural_coordinate_residual}\ndenoising_moments=lambda state,sigma,model_index: (\n    coordinate:=state[:,:2*dimension].reshape(-1,2,dimension),\n    source_ratio:=tensor_source_eigenvalue/(tensor_source_eigenvalue+sigma**2),\n    source_eigencoordinate:=torch.einsum("nrd,rde->nre",coordinate,tensor_source_eigenvector),\n    source_mean:=torch.einsum("nre,rde->nrd",source_eigencoordinate*source_ratio[None],\n        tensor_source_eigenvector)+coordinate_residual[model_index](coordinate,sigma),\n    source_variance:=torch.einsum("rie,re,rje->rij",tensor_source_eigenvector,\n        sigma**2*source_ratio,tensor_source_eigenvector),\n    calibration_ratio:=tensor_calibration_eigenvalue/(tensor_calibration_eigenvalue+sigma**2),\n    calibration_mean_denoised:=tensor_calibration_mean\n        +(((state[:,2*dimension:]-tensor_calibration_mean)@tensor_calibration_eigenvector)\n            *calibration_ratio)@tensor_calibration_eigenvector.T,\n    calibration_variance:=(tensor_calibration_eigenvector*(sigma**2*calibration_ratio)[None])\n        @tensor_calibration_eigenvector.T,\n    denoised:=torch.cat([source_mean.reshape(-1,2*dimension),calibration_mean_denoised],dim=1),\n    (denoised,source_mean,source_variance,calibration_mean_denoised,calibration_variance))[-1]\n# The observation likelihood integrates the current Gaussian approximation\n# to denoising uncertainty, lognormal gains/noise, and gain polarity. The\n# nonlinear prior uses the GP conditional covariance as a moment approximation;\n# this is approximate posterior transport, not an exact posterior sampler.\ninverse_likelihood=lambda state,sigma,model_index,observation: (\n    moments:=denoising_moments(state,sigma,model_index),\n    source_mean:=moments[1],\n    source_variance:=moments[2],\n    calibration_location:=moments[3],\n    calibration_variance:=moments[4],\n    calibration_diagonal:=torch.diagonal(calibration_variance),\n    amplitude_mean:=torch.exp(calibration_location[:,:2]+.5*calibration_diagonal[None,:2]),\n    amplitude_second:=torch.exp(2.*calibration_location[:,:2]+2.*calibration_diagonal[None,:2]),\n    amplitude_covariance:=amplitude_mean[:,:,None]*amplitude_mean[:,None,:]\n        *torch.expm1(calibration_variance[None,:2,:2]),\n    observation_noise:=torch.exp(calibration_location[:,2]+.5*calibration_diagonal[2]),\n    base_covariance:=torch.diag_embed(observation_noise[:,None]*tensor_noise_eigenvalue[None])\n        +torch.einsum("nr,rij->nij",amplitude_second,source_variance),\n    signed_source_mean:=source_mean[:,None]*tensor_sign_values[None,:,:,None],\n    observation_mean:=(signed_source_mean*amplitude_mean[:,None,:,None]).sum(dim=2),\n    covariance:=base_covariance[:,None]+torch.einsum("nsri,nrt,nstj->nsij",\n        signed_source_mean,amplitude_covariance,signed_source_mean),\n    cholesky:=torch.linalg.cholesky(covariance),\n    residual:=observation[:,None]-observation_mean,\n    quadratic:=(residual*torch.cholesky_solve(residual[...,None],cholesky)[...,0]).sum(dim=-1),\n    logdet:=2.*torch.log(torch.diagonal(cholesky,dim1=-2,dim2=-1)).sum(dim=-1),\n    log_likelihood:=torch.logsumexp(-.5*(quadratic+logdet)+tensor_sign_logprior[None],dim=1),\n    (log_likelihood.sum(),moments[0]))[-1]\ninverse_gradient=torch.func.grad_and_value(inverse_likelihood,argnums=0,has_aux=True)\ninverse_velocity=lambda log_sigma,vector,model_index: (\n    sigma:=np.exp(float(log_sigma)),\n    state:=torch.as_tensor(vector.reshape(-1,state_dimension),dtype=torch.float32),\n    evaluated:=inverse_gradient(state,sigma,model_index,tensor_observation),\n    gradient:=evaluated[0],\n    denoised:=evaluated[1][1],\n    (state-denoised-sigma**2*gradient).detach().numpy().astype(np.float64).ravel())[-1]\nprior_velocity=lambda log_sigma,vector: (\n    sigma:=np.exp(float(log_sigma)),\n    state:=torch.as_tensor(vector.reshape(-1,state_dimension),dtype=torch.float32),\n    denoised:=denoising_moments(state,sigma,1)[0],\n    (state-denoised).detach().numpy().astype(np.float64).ravel())[-1]\n'

structural_diffusion_source_predict_stage = '\nfrom scipy.optimize import minimize\nfrom scipy.integrate import solve_ivp\nfrom scipy.special import logsumexp,ndtri\nfrom scipy.stats import qmc\nfrom joblib import load,dump\nimport torch\nfrom torch import nn\nexec(compile(structural_source_data_stage,__file__,"exec"))\ndiffusion_settings=application["structural_diffusion_source"]\nassert not native\ntorch.set_num_threads(CONFIG["threads"])\ntorch.set_num_interop_threads(CONFIG["threads"])\ntorch.manual_seed(settings["seed"])\nrng=np.random.default_rng(settings["seed"])\nexec(compile(structural_period_flow_fit_stage[\n    structural_period_flow_fit_stage.index("background_raw ="):\n    structural_period_flow_fit_stage.index("layout_count,layout_index")],__file__,"exec"))\ntrain_rows,held_rows=np.flatnonzero(train),np.flatnonzero(heldout)\ntraining_groups=np.unique(run[train])\nassert np.unique(count).size==1\ndimension=length-2\noptical_pair=np.stack([target,background],axis=-1)\noptical_gain=np.linalg.solve(np.einsum("nti,ntj->nij",optical_pair,optical_pair),\n    np.einsum("nti,nt->ni",optical_pair,mixed[train])[...,None])[...,0]\noptical_amplitude=optical_gain*np.sqrt(source_energy)\nobservation_remainder=mixed[train]-np.einsum("ntr,nr->nt",optical_pair,optical_gain)\nremainder_energy=np.mean(observation_remainder**2,axis=1)\nremainder_unit=observation_remainder/np.sqrt(remainder_energy)[:,None]\nremainder_autocovariance=np.fft.irfft(np.abs(np.fft.rfft(\n    remainder_unit,n=2*length,axis=1))**2,n=2*length,axis=1)[:,:length]/length\nlag=np.abs(np.arange(length)[:,None]-np.arange(length)[None])\naffine_complement=np.linalg.qr(base[0],mode="complete")[0][:,2:]\nnoise_covariance=affine_complement.T@(row_weight@remainder_autocovariance)[lag]@affine_complement\nnoise_covariance*=dimension/np.trace(noise_covariance)\nnoise_eigenvalue,noise_eigenvector=np.linalg.eigh(noise_covariance)\nassert noise_eigenvalue.min()>0.\ncoordinate_basis=affine_complement@noise_eigenvector\nsource_coordinate=source_unit@coordinate_basis\nsource_autocovariance=np.fft.irfft(np.abs(np.fft.rfft(\n    source_unit,n=2*length,axis=-1))**2,n=2*length,axis=-1)[...,:length]/length\nstationary_covariance=(np.einsum("n,nrt->rt",row_weight,source_autocovariance))[:,lag]\nsource_covariance=np.einsum("ti,rts,sj->rij",coordinate_basis,\n    stationary_covariance,coordinate_basis,optimize=True)\nsource_covariance*=length/np.trace(source_covariance,axis1=-2,axis2=-1)[:,None,None]\nsource_eigenvalue,source_eigenvector=np.linalg.eigh(source_covariance)\nassert source_eigenvalue.min()>0.\ncalibration_log=np.column_stack([np.log(np.abs(optical_amplitude)),np.log(remainder_energy)])\ncalibration_mean=row_weight@calibration_log\ncalibration_centered=calibration_log-calibration_mean\ncalibration_covariance=np.einsum("n,ni,nj->ij",row_weight,calibration_centered,calibration_centered)\ncalibration_eigenvalue,calibration_eigenvector=np.linalg.eigh(calibration_covariance)\nassert calibration_eigenvalue.min()>0.\ngain_sign=(optical_gain<0.).astype(int)\ngain_sign_index=gain_sign[:,0]*2+gain_sign[:,1]\nsign_prior=np.bincount(gain_sign_index,weights=row_weight,minlength=4)\nactive_sign=np.flatnonzero(sign_prior>0.)\nsign_values=1.-2.*np.stack([active_sign//2,active_sign%2],axis=1)\nsign_logprior=np.log(sign_prior[active_sign])\n# Source identity is the optical role; the neural prior never receives a mixed\n# trace or a reference period. The physical observation is used only at inversion.\ndata_sd=np.sqrt(length/dimension)\nsigma_bounds=data_sd*np.asarray(diffusion_settings["source_noise_relative_bounds"])\n\ntensor_affine=torch.as_tensor(base[0].copy(),dtype=torch.float32)\ntensor_coordinate_basis=torch.as_tensor(coordinate_basis,dtype=torch.float32)\nwidth=diffusion_settings["width"]\nkernel=settings["kernel_size"]\ndilation=diffusion_settings["dilations"]\ndenoiser_model=nn.Sequential(\n    nn.Conv1d(3,width,kernel,padding=(kernel//2)*dilation[0],dilation=dilation[0],padding_mode="replicate"),\n    nn.Tanh(),\n    nn.Conv1d(width,width,kernel,padding=(kernel//2)*dilation[1],dilation=dilation[1],padding_mode="replicate"),\n    nn.Tanh(),\n    nn.Conv1d(width,width,kernel,padding=(kernel//2)*dilation[2],dilation=dilation[2],padding_mode="replicate"),\n    nn.Tanh(),\n    nn.Conv1d(width,width,kernel,padding=(kernel//2)*dilation[3],dilation=dilation[3],padding_mode="replicate"),\n    nn.Tanh(),nn.Conv1d(width,1,1))\nnn.init.zeros_(denoiser_model[-1].weight)\nnn.init.zeros_(denoiser_model[-1].bias)\nparameter_names=tuple(dict(denoiser_model.named_parameters()))\nparameter_shapes=tuple(map(torch.Tensor.size,denoiser_model.parameters()))\nparameter_sizes=tuple(map(torch.Tensor.numel,denoiser_model.parameters()))\ninitial=nn.utils.parameters_to_vector(denoiser_model.parameters()).detach().numpy().astype(np.float64)\nunpack=lambda vector:dict(zip(parameter_names,\n    map(torch.reshape,torch.split(vector,parameter_sizes),parameter_shapes)))\ndenoiser_residual=lambda vector,inputs: (\n    value:=torch.func.functional_call(denoiser_model,unpack(vector),(inputs,))[:,0],\n    value-(value@tensor_affine)@tensor_affine.T)[-1]\nstem=diffusion_settings["stem"].with_name(\n    diffusion_settings["stem"].name+"_common_fold"+str(fold))\n\nbundle=load(stem.with_suffix(".joblib"))\nassert np.array_equal(bundle["training_trace_id"],trace_id[train])\nparameters=torch.as_tensor(bundle["parameters"],dtype=torch.float32)\nexec(compile(structural_diffusion_inverse_core_stage,__file__,"exec"))\nparticle_n=diffusion_settings["posterior_particles"]\nsobol=qmc.Sobol(d=state_dimension,scramble=True,seed=settings["seed"])\nnormal=ndtri(sobol.random_base2(int(np.log2(particle_n))))\nassert particle_n==2**int(np.log2(particle_n))\nsource_normal=normal[:,:2*dimension].reshape(particle_n,2,dimension)\ncalibration_normal=normal[:,2*dimension:]\nsource_initial=np.einsum("qre,rde->qrd",source_normal*np.sqrt(\n    source_eigenvalue[None]+sigma_bounds[1]**2),source_eigenvector,optimize=True)\ncalibration_initial=calibration_mean+(calibration_normal*np.sqrt(\n    calibration_eigenvalue+sigma_bounds[1]**2))@calibration_eigenvector.T\nprior_initial=np.column_stack([source_initial.reshape(particle_n,-1),calibration_initial])\n# Moment-matched conditioning at the starting noise level uses only each mixed\n# trace. Both neural and Gaussian inversions receive exactly the same particles.\nprior_amplitude_mean=np.exp(calibration_mean[:2]+.5*np.diag(calibration_covariance)[:2])\nprior_amplitude_second=np.exp(2.*calibration_mean[:2]+2.*np.diag(calibration_covariance)[:2])\nprior_noise_mean=np.exp(calibration_mean[2]+.5*calibration_covariance[2,2])\nmean_sign=(sign_prior[active_sign,None]*sign_values).sum(axis=0)\ninitial_observation_covariance=np.diag(prior_noise_mean*noise_eigenvalue) \\\n    +np.einsum("r,rij->ij",prior_amplitude_second,source_covariance)\ninitial_cross=(source_covariance*(prior_amplitude_mean*mean_sign)[:,None,None]).reshape(\n    2*dimension,dimension)\nsource_block=np.zeros((2*dimension,2*dimension))\nsource_block[:dimension,:dimension]=source_covariance[0]\nsource_block[dimension:,dimension:]=source_covariance[1]\ninitial_source_covariance=source_block+sigma_bounds[1]**2*np.eye(2*dimension) \\\n    -initial_cross@np.linalg.solve(initial_observation_covariance,initial_cross.T)\ninitial_source_factor=np.linalg.cholesky(initial_source_covariance)\nheld_coordinate=mixed[heldout]@coordinate_basis\ninitial_source_mean=held_coordinate@np.linalg.solve(initial_observation_covariance,initial_cross.T)\nposterior_initial=np.concatenate([\n    initial_source_mean[:,None]+normal[None,:,:2*dimension]@initial_source_factor.T,\n    np.broadcast_to(calibration_initial[None],(len(held_rows),particle_n,3))],axis=-1)\ntensor_observation=torch.as_tensor(np.repeat(held_coordinate,particle_n,axis=0),dtype=torch.float32)\ncheck_state=np.column_stack([initial_source_mean[:1],calibration_mean[None]])\ncheck_tensor=torch.as_tensor(check_state,dtype=torch.float32)\ncheck_observation=torch.as_tensor(held_coordinate[:1],dtype=torch.float32)\ncheck_evaluation=inverse_gradient(check_tensor,data_sd,1,check_observation)\ncheck_gradient=check_evaluation[0].detach().numpy()\ncheck_index=int(np.argmax(np.abs(check_gradient)))\ncheck_step=np.zeros_like(check_state);check_step.ravel()[check_index]=1.e-3\ncheck_upper=inverse_likelihood(torch.as_tensor(check_state+check_step,dtype=torch.float32),\n    data_sd,1,check_observation)[0].detach().item()\ncheck_lower=inverse_likelihood(torch.as_tensor(check_state-check_step,dtype=torch.float32),\n    data_sd,1,check_observation)[0].detach().item()\ncheck_central=(check_upper-check_lower)/2.e-3\nassert np.isfinite(check_gradient).all() and np.isclose(\n    check_central,check_gradient.ravel()[check_index],rtol=5.e-3,atol=5.e-3)\nprint("DIFFUSION_INVERSE_GRADIENT",check_gradient.ravel()[check_index],check_central,\n    "initial_noise_bounds",sigma_bounds.tolist(),flush=True)\nprint("DIFFUSION_INVERSE_NEURAL","records",len(held_rows),"particles",particle_n,flush=True)\nneural_solution=solve_ivp(lambda t,z:inverse_velocity(t,z,1),\n    tuple(np.log(sigma_bounds[::-1])),posterior_initial.ravel(),method="RK45",t_eval=[np.log(sigma_bounds[0])],\n    rtol=diffusion_settings["ode_rtol"],atol=diffusion_settings["ode_atol"])\nassert neural_solution.success\nneural_state=torch.as_tensor(neural_solution.y[:,-1].reshape(-1,state_dimension),dtype=torch.float32)\nneural_endpoint=denoising_moments(neural_state,sigma_bounds[0],1)[0].detach().numpy().astype(np.float64)\nneural_source=neural_endpoint[:,:2*dimension].reshape(len(held_rows),particle_n,2,dimension)@coordinate_basis.T\nneural_calibration=neural_endpoint[:,2*dimension:].reshape(len(held_rows),particle_n,3)\nprint("DIFFUSION_INVERSE_NEURAL_DONE","nfev",neural_solution.nfev,\n    "source_rms",np.quantile(np.sqrt(np.mean(neural_source**2,axis=-1)),[.1,.5,.9],axis=(0,1)).tolist(),\n    flush=True)\nprint("DIFFUSION_INVERSE_GAUSSIAN","records",len(held_rows),"particles",particle_n,flush=True)\ngaussian_solution=solve_ivp(lambda t,z:inverse_velocity(t,z,0),\n    tuple(np.log(sigma_bounds[::-1])),posterior_initial.ravel(),method="RK45",t_eval=[np.log(sigma_bounds[0])],\n    rtol=diffusion_settings["ode_rtol"],atol=diffusion_settings["ode_atol"])\nassert gaussian_solution.success\ngaussian_state=torch.as_tensor(gaussian_solution.y[:,-1].reshape(-1,state_dimension),dtype=torch.float32)\ngaussian_endpoint=denoising_moments(gaussian_state,sigma_bounds[0],0)[0].detach().numpy().astype(np.float64)\ngaussian_source=gaussian_endpoint[:,:2*dimension].reshape(len(held_rows),particle_n,2,dimension)@coordinate_basis.T\ngaussian_calibration=gaussian_endpoint[:,2*dimension:].reshape(len(held_rows),particle_n,3)\nprint("DIFFUSION_INVERSE_GAUSSIAN_DONE","nfev",gaussian_solution.nfev,flush=True)\nprior_solution=solve_ivp(prior_velocity,tuple(np.log(sigma_bounds[::-1])),prior_initial.ravel(),\n    method="RK45",t_eval=[np.log(sigma_bounds[0])],\n    rtol=diffusion_settings["ode_rtol"],atol=diffusion_settings["ode_atol"])\nassert prior_solution.success\nprior_state=torch.as_tensor(prior_solution.y[:,-1].reshape(-1,state_dimension),dtype=torch.float32)\nprior_endpoint=denoising_moments(prior_state,sigma_bounds[0],1)[0].detach().numpy().astype(np.float64)\nneural_prior_source=prior_endpoint[:,:2*dimension].reshape(particle_n,2,dimension)@coordinate_basis.T\ngaussian_prior_coordinate=np.einsum("qre,rde->qrd",source_normal*(\n    source_eigenvalue/np.sqrt(source_eigenvalue+sigma_bounds[0]**2))[None],\n    source_eigenvector,optimize=True)\ngaussian_prior_source=gaussian_prior_coordinate@coordinate_basis.T\nsource_samples=np.stack([neural_source,gaussian_source,\n    np.broadcast_to(neural_prior_source[None],neural_source.shape),\n    np.broadcast_to(gaussian_prior_source[None],neural_source.shape)],axis=1).transpose(0,1,3,2,4)\nassert np.isfinite(source_samples).all()\n# Marginalize period mass over every generated source trajectory.\nreadout_code=structural_source_readout_stage.split("prior_labels =",1)[0].replace(\n    "waves = np.stack([prediction,mixed[heldout]],axis=1)",\n    "waves = source_samples.reshape(len(held_rows),8*particle_n,length)").replace(\n    "np.repeat(held_mask,2,axis=0)","np.repeat(held_mask,8*particle_n,axis=0)").replace(\n    "np.repeat(held_count,2)","np.repeat(held_count,8*particle_n)")\nexec(compile(readout_code,__file__,"exec"))\nparticle_logmass=log_evidence.reshape(len(held_rows),4,2,particle_n,len(periods)) \\\n    +np.log(grid_weight)[None,None,None,None]\nparticle_mass=np.exp(particle_logmass-logsumexp(particle_logmass,axis=-1)[...,None])\nrole_mass=particle_mass.mean(axis=3)\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nrole_selected=role_score.argmax(axis=-1)\nrole_estimate=periods[role_selected]\nrole_confidence=np.take_along_axis(role_score,role_selected[...,None],axis=-1)[...,0]\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\nmethods=np.array(diffusion_settings["methods"])\npredictions=pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],len(methods)),\n    "method":np.tile(methods,len(held_rows)),"estimate_h":estimate.ravel(),"confidence":confidence.ravel(),\n    "heldout_fold":fold,"heldout_run":np.repeat(run[heldout],len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    source_samples=source_samples,source_pair_mean=source_samples.mean(axis=3),\n    periods=periods,mass=mass,estimate=estimate,confidence=confidence,methods=methods,\n    particle_mass=particle_mass,role_mass=role_mass,role_estimate=role_estimate,\n    role_confidence=role_confidence,neural_calibration=neural_calibration,\n    gaussian_calibration=gaussian_calibration,training_trace_id=trace_id[train],\n    training_groups=training_groups,ode_nfev=np.array([\n        neural_solution.nfev,gaussian_solution.nfev,prior_solution.nfev]))\nprint("DIFFUSION_SOURCE_INFERENCE_DONE","prior_nfev",prior_solution.nfev,flush=True)\nexec(compile(structural_source_readout_stage[\n    structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
