structural_diffusion_integral_predict_stage = '\nfrom scipy.special import logsumexp,ndtr,ndtri\nexec(compile(structural_diffusion_source_setup_stage,__file__,"exec"))\nbundle=load(stem.with_suffix(".joblib"))\nassert np.array_equal(bundle["training_trace_id"],trace_id[train])\nassert np.allclose(source_covariance,bundle["source_covariance"],rtol=1.e-12,atol=1.e-12)\nintegral_settings=application["structural_diffusion_integral"]\nstem=integral_settings["stem"].with_name(integral_settings["stem"].name+"_common_fold"+str(fold))\nintegration_power=integral_settings["integration_power"]\ncalibration_uniform=qmc.Sobol(d=3,scramble=True,seed=settings["seed"]).random_base2(integration_power)\ncalibration_grid=calibration_mean+(ndtri(calibration_uniform)*np.sqrt(calibration_eigenvalue))@calibration_eigenvector.T\namplitude_grid=np.exp(calibration_grid[:,:2])\nnoise_grid=np.exp(calibration_grid[:,2])\nobservation_covariance=np.einsum("qr,rij->qij",amplitude_grid**2,source_covariance,\n    optimize=True)+noise_grid[:,None,None]*np.diag(noise_eigenvalue)[None]\nobservation_factor=np.linalg.cholesky(observation_covariance)\nheld_coordinate=mixed[heldout]@coordinate_basis\nwhitened_observation=np.linalg.solve(observation_factor,held_coordinate.T[None])\nlog_likelihood=-.5*np.sum(whitened_observation**2,axis=1).T \\\n    -np.log(np.diagonal(observation_factor,axis1=-2,axis2=-1)).sum(axis=-1)[None]\nnode_logmass=log_likelihood-logsumexp(log_likelihood,axis=1)[:,None]\nnode_mass=np.exp(node_logmass)\nhalf=len(calibration_grid)//2\nhalf_mass=np.exp(log_likelihood[:,:half]-logsumexp(log_likelihood[:,:half],axis=1)[:,None])\nlog_evidence_change=(logsumexp(log_likelihood,axis=1)-np.log(len(calibration_grid))) \\\n    -(logsumexp(log_likelihood[:,:half],axis=1)-np.log(half))\ncalibration_mean_full=node_mass@calibration_grid\ncalibration_mean_half=half_mass@calibration_grid[:half]\nprint("GAUSSIAN_INTEGRAL",len(held_rows),"nodes",len(calibration_grid),\n    "posterior_node_ess",np.quantile(1./np.sum(node_mass**2,axis=1),[0,.1,.5,.9,1]).tolist(),\n    "half_to_full_logevidence_abs",np.quantile(np.abs(log_evidence_change),[0,.5,.9,1]).tolist(),\n    "half_to_full_logcalibration_mean_abs",np.max(np.abs(\n        calibration_mean_full-calibration_mean_half),axis=0).tolist(),flush=True)\ninverse_observation=np.linalg.solve(observation_factor.swapaxes(-1,-2),whitened_observation)\nmean_sign=(sign_prior[active_sign,None]*sign_values).sum(axis=0)\nintegrated_precision_y=np.einsum("nqr,qdn->nrd",\n    node_mass[:,:,None]*amplitude_grid[None],inverse_observation,optimize=True)\nposterior_source_mean=np.einsum("rij,nrj->nri",source_covariance,\n    integrated_precision_y,optimize=True)*mean_sign[None,:,None]\nposterior_source_mean=posterior_source_mean@coordinate_basis.T\n\nparticle_n=integral_settings["posterior_particles"]\nnormal=ndtri(qmc.Sobol(d=3*dimension+3,scramble=True,seed=settings["seed"]).random_base2(\n    int(np.log2(particle_n))))\nselection_uniform=ndtr(normal[:,2*dimension])\nselected_node=np.sum(np.cumsum(node_mass,axis=1)[:,None,:]<selection_uniform[None,:,None],axis=-1)\nunique_node,node_map=np.unique(selected_node,return_inverse=True)\nselected_amplitude=amplitude_grid[selected_node]\nsource_normal=normal[:,:2*dimension].reshape(particle_n,2,dimension)\nprior_coordinate=np.einsum("qre,rde->qrd",source_normal*np.sqrt(source_eigenvalue)[None],\n    source_eigenvector,optimize=True)\nprior_noise=normal[:,2*dimension+3:]*np.sqrt(noise_eigenvalue)[None]\npseudo_observation=np.einsum("nqr,qrd->nqd",selected_amplitude,prior_coordinate,optimize=True) \\\n    +np.sqrt(noise_grid[selected_node])[...,None]*prior_noise[None]\npseudo_residual=held_coordinate[:,None]-pseudo_observation\nunique_covariance=np.einsum("qr,rij->qij",amplitude_grid[unique_node]**2,source_covariance,\n    optimize=True)+noise_grid[unique_node,None,None]*np.diag(noise_eigenvalue)[None]\nunique_factor=np.linalg.cholesky(unique_covariance)\nunique_inverse=np.linalg.solve(unique_factor.swapaxes(-1,-2),\n    np.linalg.solve(unique_factor,np.eye(dimension)[None]))\nprecision_residual=np.einsum("nqde,nqe->nqd",\n    unique_inverse[node_map].reshape(len(held_rows),particle_n,dimension,dimension),\n    pseudo_residual,optimize=True)\nsource_coordinate_sample=prior_coordinate[None]+selected_amplitude[...,None]*np.einsum(\n    "rij,nqj->nqri",source_covariance,precision_residual,optimize=True)\n# Conditional Gaussian simulation uses independent joint source and observation\n# noise coordinates in one Sobol vector, preserving the source cross-covariance.\nsource_block=np.zeros((2*dimension,2*dimension))\nsource_block[:dimension,:dimension]=source_covariance[0]\nsource_block[dimension:,dimension:]=source_covariance[1]\ncheck_operator=np.concatenate(amplitude_grid[unique_node[0],:,None,None]*np.eye(dimension)[None],axis=1)\ncheck_gain=source_block@check_operator.T@unique_inverse[0]\ncheck_residual=np.eye(2*dimension)-check_gain@check_operator\ncheck_covariance=check_residual@source_block@check_residual.T \\\n    +noise_grid[unique_node[0]]*(check_gain*noise_eigenvalue[None])@check_gain.T\ncheck_direct_covariance=source_block-check_gain@check_operator@source_block\nassert np.allclose(check_covariance,check_direct_covariance,rtol=1.e-10,atol=1.e-10)\nprint("GAUSSIAN_CONDITIONAL_COVARIANCE_IDENTITY",\n    np.max(np.abs(check_covariance-check_direct_covariance)),flush=True)\nsign_node=np.searchsorted(np.cumsum(sign_prior[active_sign]),ndtr(normal[:,2*dimension+1]))\nsource_coordinate_sample*=sign_values[sign_node][None,:,:,None]\nsource_samples=(source_coordinate_sample@coordinate_basis.T).transpose(0,2,1,3)\nassert np.isfinite(source_samples).all()\nreadout_code=structural_source_readout_stage.split("prior_labels =",1)[0].replace(\n    "waves = np.stack([prediction,mixed[heldout]],axis=1)",\n    "waves = source_samples.reshape(len(held_rows),2*particle_n,length)").replace(\n    "np.repeat(held_mask,2,axis=0)","np.repeat(held_mask,2*particle_n,axis=0)").replace(\n    "np.repeat(held_count,2)","np.repeat(held_count,2*particle_n)")\nexec(compile(readout_code,__file__,"exec"))\nparticle_logmass=log_evidence.reshape(len(held_rows),2,particle_n,len(periods)) \\\n    +np.log(grid_weight)[None,None,None]\nparticle_mass=np.exp(particle_logmass-logsumexp(particle_logmass,axis=-1)[...,None])\nrole_mass=particle_mass.mean(axis=2)\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nrole_selected=role_score.argmax(axis=-1)\nrole_estimate=periods[role_selected]\nrole_confidence=np.take_along_axis(role_score,role_selected[...,None],axis=-1)[...,0]\n\nprefix_role_mass=np.stack([particle_mass[:,:,:particle_n//4].mean(axis=2),\n    particle_mass[:,:,:particle_n//2].mean(axis=2),role_mass],axis=1)\nprefix_role_score=prefix_role_mass@window.T\nprefix_role_estimate=periods[prefix_role_score.argmax(axis=-1)]\nprint("GAUSSIAN_PERIOD_PARTICLE_CONVERGENCE","particle_counts",\n    [particle_n//4,particle_n//2,particle_n],\n    "target_period_shift_128_to_512",np.quantile(np.abs(\n        prefix_role_estimate[:,0,0]-prefix_role_estimate[:,2,0]),[0,.5,.9,1]).tolist(),\n    "target_period_shift_256_to_512",np.quantile(np.abs(\n        prefix_role_estimate[:,1,0]-prefix_role_estimate[:,2,0]),[0,.5,.9,1]).tolist(),\n    "target_mass_L1_256_to_512",np.quantile(np.sum(np.abs(\n        prefix_role_mass[:,1,0]-prefix_role_mass[:,2,0]),axis=-1),[0,.5,.9,1]).tolist(),flush=True)\n\nmass,estimate,confidence=role_mass[:,:1],role_estimate[:,:1],role_confidence[:,:1]\nmethods=np.array(integral_settings["methods"])\npredictions=pd.DataFrame({"trace_id":trace_id[heldout],"method":methods[0],\n    "estimate_h":estimate[:,0],"confidence":confidence[:,0],\n    "heldout_fold":fold,"heldout_run":run[heldout],"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    source_samples=source_samples[:,None],source_pair_mean=source_samples.mean(axis=2)[:,None],\n    posterior_source_mean=posterior_source_mean,periods=periods,mass=mass,estimate=estimate,confidence=confidence,\n    methods=methods,particle_mass=particle_mass[:,None],role_mass=role_mass[:,None],\n    role_estimate=role_estimate[:,None],role_confidence=role_confidence[:,None],\n    calibration_grid=calibration_grid,node_mass=node_mass,selected_node=selected_node,\n    training_trace_id=trace_id[train],training_groups=training_groups,seed=settings["seed"],\n    log_evidence_change=log_evidence_change,\n    calibration_mean_full=calibration_mean_full,calibration_mean_half=calibration_mean_half,\n    prefix_role_estimate=prefix_role_estimate,posterior_particles=particle_n)\nprint("GAUSSIAN_INTEGRAL_PREDICTED",flush=True)\nexec(compile(structural_source_readout_stage[\n    structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
