structural_joint_diffusion_setup_stage = '\nfrom scipy.optimize import minimize\nfrom scipy.integrate import solve_ivp\nfrom scipy.special import logsumexp,ndtri\nfrom scipy.stats import qmc\nfrom joblib import load,dump\nfrom time import perf_counter\nimport torch\nfrom torch import nn\nexec(compile(structural_source_data_stage,__file__,"exec"))\njoint_settings=application["structural_joint_diffusion"]\nassert not native\ntorch.set_num_threads(CONFIG["threads"])\ntorch.set_num_interop_threads(CONFIG["threads"])\ntorch.manual_seed(settings["seed"])\nrng=np.random.default_rng(settings["seed"])\nexec(compile(structural_period_flow_fit_stage[\n    structural_period_flow_fit_stage.index("background_raw ="):\n    structural_period_flow_fit_stage.index("layout_count,layout_index")],__file__,"exec"))\ntrain_rows,held_rows=np.flatnonzero(train),np.flatnonzero(heldout)\ntraining_groups=np.unique(run[train])\nassert np.unique(count).size==1\ndimension=length-2\ncoordinate_basis=np.linalg.qr(base[0],mode="complete")[0][:,2:]\njoint_wave=np.concatenate([mixed[train,None],source_unit],axis=1)\njoint_coordinate=(joint_wave@coordinate_basis).reshape(len(train_rows),3*dimension)\njoint_mean=row_weight@joint_coordinate\njoint_centered=joint_coordinate-joint_mean\nempirical_covariance=np.einsum("n,ni,nj->ij",row_weight,joint_centered,joint_centered,optimize=True)\ncoordinate_n=3*dimension\ncovariance_norm=np.sum(empirical_covariance**2)\ncovariance_scale=np.trace(empirical_covariance)/coordinate_n\nsample_norm=np.sum(joint_centered**2,axis=1)\ncovariance_variance=np.sum(row_weight**2*(sample_norm**2\n    -2.*np.einsum("ni,ij,nj->n",joint_centered,empirical_covariance,joint_centered,optimize=True)\n    +covariance_norm))\ncovariance_distance=np.sum((empirical_covariance-covariance_scale*np.eye(coordinate_n))**2)\nshrinkage=np.minimum(np.maximum(covariance_variance/covariance_distance,0.),1.)\njoint_covariance=(1.-shrinkage)*empirical_covariance+shrinkage*covariance_scale*np.eye(coordinate_n)\nassert np.linalg.eigvalsh(joint_covariance).min()>0.\n# All records and all optical roles remain in the law. The four masks encode\n# joint generation and each single observed view, not additional observations.\nunknown=np.concatenate([np.ones((1,3)),1.-np.eye(3)],axis=0)\nunknown_coordinate=np.repeat(unknown,dimension,axis=1)\nblock_index=np.arange(coordinate_n).reshape(3,dimension)\nobserved_covariance=joint_covariance[block_index[:,:,None],block_index[:,None,:]]\ncross_covariance=joint_covariance[:,block_index].transpose(1,0,2)\ncondition_gain=np.linalg.solve(observed_covariance,cross_covariance.swapaxes(-1,-2)).swapaxes(-1,-2)\nconditional_covariance=joint_covariance[None]-condition_gain@cross_covariance.swapaxes(-1,-2)\nconditional_covariance=np.concatenate([joint_covariance[None],conditional_covariance],axis=0)\nconditional_covariance*=unknown_coordinate[:,:,None]*unknown_coordinate[:,None,:]\nconditional_covariance=(conditional_covariance+conditional_covariance.swapaxes(-1,-2))/2.\nconditional_mean=joint_mean[None,None]+np.einsum("pij,npj->npi",condition_gain,\n    joint_centered.reshape(len(train_rows),3,dimension),optimize=True)\nconditional_mean=np.concatenate([\n    np.broadcast_to(joint_mean,(len(train_rows),1,coordinate_n)),conditional_mean],axis=1)\nconditional_eigenvalue,conditional_eigenvector=np.linalg.eigh(conditional_covariance)\nassert conditional_eigenvalue.min()>-1.e-10\nconditional_eigenvalue=np.maximum(conditional_eigenvalue,0.)\nquadrature_x,quadrature_weight=np.polynomial.legendre.leggauss(joint_settings["training_particles"])\nquadrature_weight/=quadrature_weight.sum()\nphi=(quadrature_x+1.)*np.pi/4.\nalpha,beta=np.cos(phi),np.sin(phi)\ntraining_noise=rng.standard_normal((len(train_rows),len(phi),coordinate_n))\nnoisy_coordinate=joint_coordinate[:,None,None]*(1.-unknown_coordinate[None,:,None]\n    +alpha[None,None,:,None]*unknown_coordinate[None,:,None]) \\\n    +beta[None,None,:,None]*training_noise[:,None]*unknown_coordinate[None,:,None]\nvelocity_target=(alpha[None,None,:,None]*training_noise[:,None]\n    -beta[None,None,:,None]*joint_coordinate[:,None,None])*unknown_coordinate[None,:,None]\ncentered_noisy=(noisy_coordinate-alpha[None,None,:,None]*conditional_mean[:,:,None]) \\\n    *unknown_coordinate[None,:,None]\nvelocity_ratio=alpha[None,:,None]*beta[None,:,None]*(1.-conditional_eigenvalue[:,None]) \\\n    /(alpha[None,:,None]**2*conditional_eigenvalue[:,None]+beta[None,:,None]**2)\ngaussian_velocity=-beta[None,None,:,None]*conditional_mean[:,:,None] \\\n    +np.einsum("npqe,pej->npqj",\n        np.einsum("npqj,pje->npqe",centered_noisy,conditional_eigenvector,optimize=True)\n        *velocity_ratio[None],conditional_eigenvector.swapaxes(-1,-2),optimize=True)\ngaussian_velocity*=unknown_coordinate[None,:,None]\nnoisy_wave=noisy_coordinate.reshape(len(train_rows),len(unknown),len(phi),3,dimension)@coordinate_basis.T\ntraining_timestep=np.broadcast_to(\n    phi[None,None,:,None,None]/(np.pi/2.)*unknown[None,:,None,:,None],noisy_wave.shape)\ntraining_input=np.concatenate([noisy_wave,training_timestep],axis=-2).reshape(-1,6,length)\ntraining_output=((velocity_target-gaussian_velocity).reshape(\n    len(train_rows),len(unknown),len(phi),3,dimension)@coordinate_basis.T).reshape(-1,3,length)\ntraining_weight=(row_weight[:,None,None,None,None]\n    *quadrature_weight[None,None,:,None,None]*unknown[None,:,None,:,None]\n    /(len(unknown)*unknown.sum(axis=1)[None,:,None,None,None]*length))\ntraining_weight=np.broadcast_to(training_weight,(*noisy_wave.shape[:-1],1)).reshape(-1,3,1)\ntraining_beta=np.broadcast_to(beta[None,None,:,None,None],(*noisy_wave.shape[:-2],1,1)).reshape(-1,1,1)\ntensor_training_input=torch.as_tensor(training_input,dtype=torch.float32)\ntensor_training_output=torch.as_tensor(training_output,dtype=torch.float64)\ntensor_training_weight=torch.as_tensor(training_weight.copy(),dtype=torch.float64)\ntensor_training_beta=torch.as_tensor(training_beta.copy(),dtype=torch.float32)\ntensor_affine=torch.as_tensor(base[0].copy(),dtype=torch.float32)\ntensor_coordinate_basis=torch.as_tensor(coordinate_basis,dtype=torch.float32)\nwidth=joint_settings["width"]\nkernel=settings["kernel_size"]\ndilation=joint_settings["dilations"]\njoint_model=nn.Sequential(\n    nn.Conv1d(6,width,kernel,padding=(kernel//2)*dilation[0],dilation=dilation[0],padding_mode="replicate"),\n    nn.Tanh(),\n    nn.Conv1d(width,width,kernel,padding=(kernel//2)*dilation[1],dilation=dilation[1],padding_mode="replicate"),\n    nn.Tanh(),\n    nn.Conv1d(width,width,kernel,padding=(kernel//2)*dilation[2],dilation=dilation[2],padding_mode="replicate"),\n    nn.Tanh(),\n    nn.Conv1d(width,width,kernel,padding=(kernel//2)*dilation[3],dilation=dilation[3],padding_mode="replicate"),\n    nn.Tanh(),nn.Conv1d(width,3,1))\nnn.init.zeros_(joint_model[-1].weight)\nnn.init.zeros_(joint_model[-1].bias)\nparameter_names=tuple(dict(joint_model.named_parameters()))\nparameter_shapes=tuple(map(torch.Tensor.size,joint_model.parameters()))\nparameter_sizes=tuple(map(torch.Tensor.numel,joint_model.parameters()))\ninitial=nn.utils.parameters_to_vector(joint_model.parameters()).detach().numpy().astype(np.float64)\nunpack=lambda vector:dict(zip(parameter_names,\n    map(torch.reshape,torch.split(vector,parameter_sizes),parameter_shapes)))\njoint_residual=lambda vector,inputs: (\n    value:=torch.func.functional_call(joint_model,unpack(vector),(inputs,)),\n    value-(value@tensor_affine)@tensor_affine.T)[-1]\nobjective=lambda vector: (((joint_residual(vector,tensor_training_input)*tensor_training_beta).double()\n    -tensor_training_output).square()*tensor_training_weight).sum() \\\n    +settings["weight_decay"]*vector.double().square().mean()\nautograd_objective=torch.func.grad_and_value(objective)\nto_scipy=lambda gradient,value:(value.detach().item(),gradient.detach().numpy().astype(np.float64))\nscipy_objective=lambda vector:to_scipy(*autograd_objective(torch.as_tensor(vector,dtype=torch.float32)))\nstem=joint_settings["stem"].with_name(joint_settings["stem"].name+"_common_fold"+str(fold))\n'

structural_joint_diffusion_train_stage = '\ninitial_loss,initial_gradient=scipy_objective(initial)\nassert np.isfinite(initial_loss) and np.isfinite(initial_gradient).all()\nloss_history=[[0,initial_loss]]\nprint("JOINT_DIFFUSION_TRAIN","records",len(train_rows),"views",3,\n    "conditional_patterns",len(unknown),"noise_pairs",len(training_input),"parameters",len(initial),\n    "initial_loss",initial_loss,"covariance_shrinkage",shrinkage,"seed",settings["seed"],flush=True)\nresult=minimize(scipy_objective,initial,jac=True,method="L-BFGS-B",\n    callback=lambda intermediate_result:(loss_history.append([len(loss_history),float(intermediate_result.fun)]),\n        len(loss_history)%50==0 and print("JOINT_DIFFUSION_PROGRESS",len(loss_history)-1,\n            intermediate_result.fun,flush=True)),\n    options={"maxiter":joint_settings["maxiter"],"ftol":joint_settings["ftol"],\n        "gtol":settings["gtol"],"maxls":settings["maxls"]})\nparameters=torch.as_tensor(result.x,dtype=torch.float32)\ntraining_error=(joint_residual(parameters,tensor_training_input)*tensor_training_beta\n    -tensor_training_output).square()\npattern_role_loss=(training_error*tensor_training_weight).reshape(\n    len(train_rows),len(unknown),len(phi),3,length).sum(dim=(0,2,4))*len(unknown)*unknown.sum(axis=1)[:,None]\nbaseline_pattern_role_loss=(tensor_training_output.square()*tensor_training_weight).reshape(\n    len(train_rows),len(unknown),len(phi),3,length).sum(dim=(0,2,4))*len(unknown)*unknown.sum(axis=1)[:,None]\ndump({"parameters":result.x,"parameter_names":parameter_names,"parameter_shapes":parameter_shapes,\n    "optimization":result,"training_loss_history":np.asarray(loss_history),\n    "joint_mean":joint_mean,"joint_covariance":joint_covariance,"shrinkage":shrinkage,\n    "coordinate_basis":coordinate_basis,"condition_gain":condition_gain,\n    "conditional_covariance":conditional_covariance,"unknown_patterns":unknown,\n    "training_trace_id":trace_id[train],"training_groups":training_groups,\n    "settings":dict(joint_settings),"neural_pattern_role_loss":pattern_role_loss.detach().numpy(),\n    "gaussian_pattern_role_loss":baseline_pattern_role_loss.numpy(),"seed":settings["seed"],\n    "heldout_optical_read":False,"target":"optically_separated_target_luminescence_waveform"},\n    stem.with_suffix(".joblib"))\nprint("JOINT_DIFFUSION_OPTIMIZED","loss",result.fun,"iterations",result.nit,"status",str(result.message),\n    "neural_pattern_role_loss",pattern_role_loss.detach().numpy().tolist(),\n    "gaussian_pattern_role_loss",baseline_pattern_role_loss.numpy().tolist(),flush=True)\nraise SystemExit(0)\n'
exec(compile({True:structural_joint_diffusion_setup_stage+structural_joint_diffusion_train_stage,False:""}[args.stage=="structural-joint-diffusion-fit"],__file__,"exec"))

structural_joint_diffusion_predict_stage = '\nexec(compile(structural_joint_diffusion_setup_stage,__file__,"exec"))\nbundle=load(stem.with_suffix(".joblib"))\nassert np.array_equal(bundle["training_trace_id"],trace_id[train])\nassert np.allclose(bundle["joint_covariance"],joint_covariance,rtol=1.e-12,atol=1.e-12)\nparameters=torch.as_tensor(bundle["parameters"],dtype=torch.float32)\nparticle_n=joint_settings["posterior_particles"]\nprior_n=joint_settings["prior_particles"]\nnormal=ndtri(qmc.Sobol(d=coordinate_n,scramble=True,seed=settings["seed"]).random_base2(\n    int(np.log2(prior_n))))\nheld_coordinate=mixed[heldout]@coordinate_basis\nsource_mean=joint_mean[dimension:][None]+(held_coordinate-joint_mean[:dimension]) \\\n    @condition_gain[0,dimension:,:].T\nsource_covariance=conditional_covariance[1,dimension:,dimension:]\nsource_eigenvalue,source_eigenvector=np.linalg.eigh(source_covariance)\nassert source_eigenvalue.min()>0.\ngaussian_endpoint=source_mean[:,None]+((normal[:particle_n,:2*dimension]@source_eigenvector)\n    *np.sqrt(source_eigenvalue)[None])@source_eigenvector.T\ntensor_source_mean=torch.as_tensor(np.repeat(source_mean,particle_n,axis=0),dtype=torch.float32)\ntensor_source_eigenvalue=torch.as_tensor(source_eigenvalue,dtype=torch.float32)\ntensor_source_eigenvector=torch.as_tensor(source_eigenvector,dtype=torch.float32)\ntensor_observed_wave=torch.as_tensor(np.repeat(mixed[heldout],particle_n,axis=0)[:,None],dtype=torch.float32)\ninitial_source=np.broadcast_to(normal[None,:particle_n,:2*dimension],\n    (len(held_rows),particle_n,2*dimension)).copy()\nposterior_velocity_tensor=lambda state,angle: (\n    alpha:=np.cos(float(angle)),beta:=np.sin(float(angle)),\n    ratio:=alpha*beta*(1.-tensor_source_eigenvalue)/(alpha**2*tensor_source_eigenvalue+beta**2),\n    gaussian:=-beta*tensor_source_mean+(((state-alpha*tensor_source_mean)@tensor_source_eigenvector)\n        *ratio[None])@tensor_source_eigenvector.T,\n    waves:=torch.cat([tensor_observed_wave,state.reshape(-1,2,dimension)@tensor_coordinate_basis.T],dim=1),\n    timestep:=torch.ones_like(waves)*torch.tensor(\n        [0.,angle/(np.pi/2.),angle/(np.pi/2.)],dtype=torch.float32)[None,:,None],\n    residual:=joint_residual(parameters,torch.cat([waves,timestep],dim=1))[:,1:]@tensor_coordinate_basis,\n    gaussian+beta*residual.reshape(-1,2*dimension))[-1]\nprogress={"calls":0,"started":perf_counter()}\nposterior_velocity=lambda angle,vector: (\n    progress.__setitem__("calls",progress["calls"]+1),\n    value:=posterior_velocity_tensor(\n        torch.as_tensor(vector.reshape(-1,2*dimension),dtype=torch.float32),angle),\n    progress["calls"]%joint_settings["progress_every"]==0 and print(\n        "JOINT_DIFFUSION_POSTERIOR_PROGRESS",progress["calls"],"angle",angle,\n        "elapsed_s",round(perf_counter()-progress["started"],1),flush=True),\n    value.detach().numpy().astype(np.float64).ravel())[-1]\nprint("JOINT_DIFFUSION_POSTERIOR_START","records",len(held_rows),"particles",particle_n,flush=True)\nsolution=solve_ivp(posterior_velocity,(np.pi/2.,0.),initial_source.ravel(),method="RK45",\n    t_eval=[0.],rtol=joint_settings["ode_rtol"],atol=joint_settings["ode_atol"])\nassert solution.success\nneural_endpoint=solution.y[:,-1].reshape(len(held_rows),particle_n,2,dimension)\ngaussian_endpoint=gaussian_endpoint.reshape(len(held_rows),particle_n,2,dimension)\nposterior_source_samples=np.stack([\n    (neural_endpoint@coordinate_basis.T).transpose(0,2,1,3),\n    (gaussian_endpoint@coordinate_basis.T).transpose(0,2,1,3)],axis=1)\nprint("JOINT_DIFFUSION_POSTERIOR_DONE","nfev",solution.nfev,"source_rms",\n    np.quantile(np.sqrt(np.mean(posterior_source_samples**2,axis=-1)),[.1,.5,.9],axis=(0,3)).tolist(),\n    flush=True)\njoint_eigenvalue,joint_eigenvector=np.linalg.eigh(joint_covariance)\ntensor_joint_mean=torch.as_tensor(joint_mean,dtype=torch.float32)\ntensor_joint_eigenvalue=torch.as_tensor(joint_eigenvalue,dtype=torch.float32)\ntensor_joint_eigenvector=torch.as_tensor(joint_eigenvector,dtype=torch.float32)\nprior_velocity_tensor=lambda state,angle: (\n    alpha:=np.cos(float(angle)),beta:=np.sin(float(angle)),\n    ratio:=alpha*beta*(1.-tensor_joint_eigenvalue)/(alpha**2*tensor_joint_eigenvalue+beta**2),\n    gaussian:=-beta*tensor_joint_mean[None]+(((state-alpha*tensor_joint_mean[None])@tensor_joint_eigenvector)\n        *ratio[None])@tensor_joint_eigenvector.T,\n    waves:=state.reshape(-1,3,dimension)@tensor_coordinate_basis.T,\n    timestep:=torch.ones_like(waves)*(angle/(np.pi/2.)),\n    residual:=joint_residual(parameters,torch.cat([waves,timestep],dim=1))@tensor_coordinate_basis,\n    gaussian+beta*residual.reshape(-1,coordinate_n))[-1]\nprior_velocity=lambda angle,vector:prior_velocity_tensor(\n    torch.as_tensor(vector.reshape(-1,coordinate_n),dtype=torch.float32),angle).detach().numpy().astype(\n        np.float64).ravel()\nprior_solution=solve_ivp(prior_velocity,(np.pi/2.,0.),normal.ravel(),method="RK45",t_eval=[0.],\n    rtol=joint_settings["ode_rtol"],atol=joint_settings["ode_atol"])\nassert prior_solution.success\nneural_prior=prior_solution.y[:,-1].reshape(prior_n,3,dimension)[:,1:]@coordinate_basis.T\ngaussian_prior=(joint_mean[None]+((normal@joint_eigenvector)*np.sqrt(joint_eigenvalue)[None])@joint_eigenvector.T).reshape(\n    prior_n,3,dimension)[:,1:]@coordinate_basis.T\nprior_source_samples=np.stack([neural_prior.transpose(1,0,2),gaussian_prior.transpose(1,0,2)])\nassert np.isfinite(posterior_source_samples).all() and np.isfinite(prior_source_samples).all()\nreadout_waves=np.concatenate([\n    posterior_source_samples.reshape(-1,length),prior_source_samples.reshape(-1,length)],axis=0)\nreadout_code=structural_source_readout_stage.split("prior_labels =",1)[0].replace(\n    "waves = np.stack([prediction,mixed[heldout]],axis=1)","waves = readout_waves").replace(\n    "np.repeat(held_mask,2,axis=0)","np.broadcast_to(held_mask[0],(len(readout_waves),length))").replace(\n    "np.repeat(held_count,2)","np.full(len(readout_waves),held_count[0])")\nexec(compile(readout_code,__file__,"exec"))\nlogmass=log_evidence+np.log(grid_weight)[None]\nparticle_mass=np.exp(logmass-logsumexp(logmass,axis=-1)[:,None])\nposterior_size=len(held_rows)*2*2*particle_n\nposterior_particle_mass=particle_mass[:posterior_size].reshape(\n    len(held_rows),2,2,particle_n,len(periods))\nprior_particle_mass=particle_mass[posterior_size:].reshape(2,2,prior_n,len(periods))\nposterior_role_mass=posterior_particle_mass.mean(axis=3)\nprior_role_mass=prior_particle_mass.mean(axis=2)\nrole_mass=np.concatenate([posterior_role_mass,np.broadcast_to(prior_role_mass[None],\n    (len(held_rows),2,2,len(periods)))],axis=1)\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nrole_selected=role_score.argmax(axis=-1)\nrole_estimate=periods[role_selected]\nrole_confidence=np.take_along_axis(role_score,role_selected[...,None],axis=-1)[...,0]\nprefix_role_mass=posterior_particle_mass[:,:,:,:particle_n//2].mean(axis=3)\nprefix_role_estimate=periods[(prefix_role_mass@window.T).argmax(axis=-1)]\nprint("JOINT_DIFFUSION_PARTICLE_CONVERGENCE","half_to_full_period_shift",\n    np.quantile(np.abs(prefix_role_estimate[:,:,0]-role_estimate[:,:2,0]),[0,.5,.9,1],axis=0).tolist(),\n    "half_to_full_mass_L1",np.quantile(np.sum(np.abs(\n        prefix_role_mass[:,:,0]-role_mass[:,:2,0]),axis=-1),[0,.5,.9,1],axis=0).tolist(),flush=True)\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\nmethods=np.array(joint_settings["methods"])\npredictions=pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],len(methods)),\n    "method":np.tile(methods,len(held_rows)),"estimate_h":estimate.ravel(),"confidence":confidence.ravel(),\n    "heldout_fold":fold,"heldout_run":np.repeat(run[heldout],len(methods)),"method_status":"ok"})\nsource_pair_mean=np.concatenate([posterior_source_samples.mean(axis=3),np.broadcast_to(\n    prior_source_samples.mean(axis=2)[None],(len(held_rows),2,2,length))],axis=1)\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    posterior_source_samples=posterior_source_samples,prior_source_samples=prior_source_samples,\n    source_pair_mean=source_pair_mean,periods=periods,mass=mass,estimate=estimate,confidence=confidence,\n    methods=methods,role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,\n    posterior_particle_mass=posterior_particle_mass,prior_particle_mass=prior_particle_mass,\n    posterior_particles=particle_n,prior_particles=prior_n,training_trace_id=trace_id[train],\n    training_groups=training_groups,seed=settings["seed"],prefix_role_estimate=prefix_role_estimate,\n    posterior_ode_nfev=solution.nfev,prior_ode_nfev=prior_solution.nfev,\n    conditional_source_mean=source_mean,conditional_source_covariance=source_covariance,\n    interpretation="conditional_distribution_of_optically_observed_sources_given_No")\nexec(compile(structural_source_readout_stage[\n    structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
exec(compile({True:structural_joint_diffusion_predict_stage,False:""}[args.stage=="structural-joint-diffusion-predict"],__file__,"exec"))

structural_energy_source_setup_stage = '\nfrom scipy.special import softmax\nexec(compile(structural_diffusion_source_setup_stage.split("data_sd=",1)[0],__file__,"exec"))\nenergy_settings=application["structural_energy_source"]\ngaussian_stem=diffusion_settings["stem"].with_name(\n    diffusion_settings["stem"].name+"_common_fold"+str(fold))\ngaussian_bundle=load(gaussian_stem.with_suffix(".joblib"))\nassert np.array_equal(gaussian_bundle["training_trace_id"],trace_id[train])\nassert np.allclose(source_covariance,gaussian_bundle["source_covariance"],rtol=1.e-12,atol=1.e-12)\nnoise_n=2**energy_settings["noise_power"]\nnoise_normal=ndtri(qmc.Sobol(d=2*dimension,scramble=True,seed=settings["seed"]).random_base2(\n    energy_settings["noise_power"]+1)).reshape(2*noise_n,2,dimension)\nnoise_coordinate=np.einsum("qre,rde->qrd",\n    noise_normal*np.sqrt(source_eigenvalue)[None],source_eigenvector,optimize=True)\nnoise_wave=noise_coordinate@coordinate_basis.T\nnoise_unit=noise_wave/np.sqrt(np.mean(noise_wave**2,axis=-1,keepdims=True))\nenergy_wave=np.concatenate([source_unit,noise_unit[:noise_n]],axis=0)\nrole_code=np.array([1.,-1.])[None,:,None]\ntraining_input=np.stack([energy_wave,np.broadcast_to(role_code,energy_wave.shape)],axis=-2).reshape(\n    -1,2,length)\ntensor_training_input=torch.as_tensor(training_input,dtype=torch.float32)\ntensor_row_weight=torch.as_tensor(row_weight,dtype=torch.float64)\nnoise_magnitude=np.sqrt(1./np.sum(row_weight**2))\nlog_noise_magnitude=float(np.log(noise_magnitude))\nwidth=energy_settings["width"]\nkernel=settings["kernel_size"]\ndilation=energy_settings["dilations"]\nenergy_model=nn.Sequential(\n    nn.Conv1d(2,width,kernel,padding=(kernel//2)*dilation[0],dilation=dilation[0],padding_mode="replicate"),\n    nn.Tanh(),\n    nn.Conv1d(width,width,kernel,padding=(kernel//2)*dilation[1],dilation=dilation[1],padding_mode="replicate"),\n    nn.Tanh(),\n    nn.Conv1d(width,width,kernel,padding=(kernel//2)*dilation[2],dilation=dilation[2],padding_mode="replicate"),\n    nn.Tanh(),\n    nn.Conv1d(width,width,kernel,padding=(kernel//2)*dilation[3],dilation=dilation[3],padding_mode="replicate"),\n    nn.Tanh(),nn.Conv1d(width,1,1),nn.AdaptiveAvgPool1d(1),nn.Flatten())\nnn.init.zeros_(energy_model[-3].weight)\nnn.init.zeros_(energy_model[-3].bias)\nparameter_names=tuple(dict(energy_model.named_parameters()))\nparameter_shapes=tuple(map(torch.Tensor.size,energy_model.parameters()))\nparameter_sizes=tuple(map(torch.Tensor.numel,energy_model.parameters()))\ninitial=nn.utils.parameters_to_vector(energy_model.parameters()).detach().numpy().astype(np.float64)\nunpack=lambda vector:dict(zip(parameter_names,\n    map(torch.reshape,torch.split(vector,parameter_sizes),parameter_shapes)))\nenergy_logratio=lambda vector,inputs:torch.func.functional_call(\n    energy_model,unpack(vector),(inputs,))[:,0].to(torch.float64)\nobjective=lambda vector:(\n    score:=energy_logratio(vector,tensor_training_input).reshape(-1,2),\n    (torch.nn.functional.softplus(log_noise_magnitude-score[:len(train_rows)])\n        *tensor_row_weight[:,None]).sum()/2.\n    +noise_magnitude*torch.nn.functional.softplus(\n        score[len(train_rows):]-log_noise_magnitude).mean()\n    +settings["weight_decay"]*vector.to(torch.float64).square().mean())[-1]\nautograd_objective=torch.func.grad_and_value(objective)\nto_scipy=lambda gradient,value:(value.detach().item(),gradient.detach().numpy().astype(np.float64))\nscipy_objective=lambda vector:to_scipy(*autograd_objective(torch.as_tensor(vector,dtype=torch.float32)))\nstem=energy_settings["stem"].with_name(energy_settings["stem"].name+"_common_fold"+str(fold))\n'

structural_energy_source_train_stage = '\ninitial_loss,initial_gradient=scipy_objective(initial)\nassert np.isfinite(initial_loss) and np.isfinite(initial_gradient).all()\nloss_history=[[0,initial_loss]]\nprint("ENERGY_SOURCE_TRAIN","records",len(train_rows),"groups",len(training_groups),\n    "noise_per_role",noise_n,"parameters",len(initial),"noise_magnitude",noise_magnitude,\n    "initial_loss",initial_loss,"seed",settings["seed"],flush=True)\nresult=minimize(scipy_objective,initial,jac=True,method="L-BFGS-B",\n    callback=lambda intermediate_result:(loss_history.append([len(loss_history),float(intermediate_result.fun)]),\n        len(loss_history)%50==0 and print("ENERGY_SOURCE_PROGRESS",len(loss_history)-1,\n            intermediate_result.fun,flush=True)),\n    options={"maxiter":energy_settings["maxiter"],"ftol":energy_settings["ftol"],\n        "gtol":settings["gtol"],"maxls":settings["maxls"]})\nparameters=torch.as_tensor(result.x,dtype=torch.float32)\ntraining_score=energy_logratio(parameters,tensor_training_input).detach().numpy().reshape(-1,2)\ncheck_input=np.stack([noise_unit[noise_n:],np.broadcast_to(role_code,noise_unit[noise_n:].shape)],\n    axis=-2).reshape(-1,2,length)\ncheck_score=energy_logratio(parameters,torch.as_tensor(check_input,dtype=torch.float32)).detach().numpy().reshape(-1,2)\ntraining_log_normalizer=logsumexp(training_score[len(train_rows):],axis=0)-np.log(noise_n)\ncheck_log_normalizer=logsumexp(check_score,axis=0)-np.log(noise_n)\npositive_role_loss=np.sum(row_weight[:,None]*np.logaddexp(\n    0.,log_noise_magnitude-training_score[:len(train_rows)]),axis=0)\nnegative_role_loss=noise_magnitude*np.mean(np.logaddexp(\n    0.,training_score[len(train_rows):]-log_noise_magnitude),axis=0)\ncheck_negative_role_loss=noise_magnitude*np.mean(np.logaddexp(\n    0.,check_score-log_noise_magnitude),axis=0)\ndump({"parameters":result.x,"parameter_names":parameter_names,"parameter_shapes":parameter_shapes,\n    "optimization":result,"training_loss_history":np.asarray(loss_history),\n    "source_covariance":source_covariance,"coordinate_basis":coordinate_basis,\n    "training_trace_id":trace_id[train],"training_groups":training_groups,\n    "settings":dict(energy_settings),"seed":settings["seed"],\n    "noise_magnitude":noise_magnitude,"noise_samples_per_role":noise_n,\n    "training_log_normalizer":training_log_normalizer,"check_log_normalizer":check_log_normalizer,\n    "training_role_loss":positive_role_loss+negative_role_loss,\n    "check_negative_role_loss":check_negative_role_loss,\n    "heldout_optical_read":False,"target":"optically_separated_target_luminescence_waveform"},\n    stem.with_suffix(".joblib"))\nprint("ENERGY_SOURCE_OPTIMIZED","loss",result.fun,"iterations",result.nit,\n    "status",str(result.message),"training_role_loss",(positive_role_loss+negative_role_loss).tolist(),\n    "noise_log_normalizer_train",training_log_normalizer.tolist(),\n    "noise_log_normalizer_check",check_log_normalizer.tolist(),\n    "negative_role_loss",negative_role_loss.tolist(),\n    "check_negative_role_loss",check_negative_role_loss.tolist(),flush=True)\nraise SystemExit(0)\n'

structural_energy_source_predict_stage = '\nexec(compile(structural_energy_source_setup_stage,__file__,"exec"))\nbundle=load(stem.with_suffix(".joblib"))\nassert np.array_equal(bundle["training_trace_id"],trace_id[train])\nparameters=torch.as_tensor(bundle["parameters"],dtype=torch.float32)\nintegral_settings=application["structural_diffusion_integral"]\nproposal_stem=integral_settings["stem"].with_name(integral_settings["stem"].name+"_common_fold"+str(fold))\nproposal=np.load(proposal_stem.with_suffix(".npz"))\nassert np.array_equal(proposal["trace_id"],trace_id[heldout])\nsource_samples=proposal["source_samples"][:,0]\nparticle_n=source_samples.shape[2]\nparticle_mass=proposal["particle_mass"][:,0]\nperiods=proposal["periods"]\nsource_sample_unit=source_samples/np.sqrt(np.mean(source_samples**2,axis=-1,keepdims=True))\nposterior_input=np.stack([source_sample_unit,\n    np.broadcast_to(np.array([1.,-1.])[None,:,None,None],source_sample_unit.shape)],\n    axis=-2).reshape(-1,2,length)\nposterior_logratio=energy_logratio(parameters,torch.as_tensor(\n    posterior_input,dtype=torch.float32)).detach().numpy().reshape(len(held_rows),2,particle_n)\npair_logratio=posterior_logratio.sum(axis=1)\nparticle_weight=softmax(pair_logratio,axis=1)\nposterior_role_mass=np.einsum("nq,nrqp->nrp",particle_weight,particle_mass,optimize=True)\nposterior_source_mean=np.einsum("nq,nrqt->nrt",particle_weight,source_samples,optimize=True)\nassert np.allclose(particle_mass.mean(axis=2),proposal["role_mass"][:,0],rtol=1.e-12,atol=1.e-12)\nprefix_half_weight=softmax(pair_logratio[:,:particle_n//2],axis=1)\nprefix_quarter_weight=softmax(pair_logratio[:,:particle_n//4],axis=1)\nprefix_role_mass=np.stack([\n    np.einsum("nq,nrqp->nrp",prefix_quarter_weight,particle_mass[:,:,:particle_n//4],optimize=True),\n    np.einsum("nq,nrqp->nrp",prefix_half_weight,particle_mass[:,:,:particle_n//2],optimize=True),\n    posterior_role_mass],axis=1)\nposterior_ess=1./np.sum(particle_weight**2,axis=1)\nprior_wave=noise_wave[noise_n:]\nprior_unit=noise_unit[noise_n:]\nprior_input=np.stack([prior_unit,np.broadcast_to(role_code,prior_unit.shape)],axis=-2).reshape(-1,2,length)\nprior_logratio=energy_logratio(parameters,torch.as_tensor(\n    prior_input,dtype=torch.float32)).detach().numpy().reshape(noise_n,2)\nprior_weight=softmax(prior_logratio,axis=0)\nprior_readout=structural_source_readout_stage.split("prior_labels =",1)[0].replace(\n    "waves = np.stack([prediction,mixed[heldout]],axis=1)",\n    "waves = prior_wave.transpose(1,0,2).reshape(1,2*noise_n,length)").replace(\n    "held_mask = mask[heldout]","held_mask = np.ones((1,length),dtype=bool)").replace(\n    "held_count = count[heldout]","held_count = np.array([length])").replace(\n    "np.repeat(held_mask,2,axis=0)","np.repeat(held_mask,2*noise_n,axis=0)").replace(\n    "np.repeat(held_count,2)","np.repeat(held_count,2*noise_n)")\nexec(compile(prior_readout,__file__,"exec"))\nprior_particle_mass=softmax(log_evidence.reshape(2,noise_n,len(periods))\n    +np.log(grid_weight)[None,None],axis=-1)\nenergy_prior_mass=np.einsum("qr,rqp->rp",prior_weight,prior_particle_mass,optimize=True)\ngaussian_prior_mass=prior_particle_mass.mean(axis=1)\nenergy_prior_mean=np.einsum("qr,qrt->rt",prior_weight,prior_wave,optimize=True)\ngaussian_prior_mean=prior_wave.mean(axis=0)\nrole_mass=np.stack([posterior_role_mass,np.broadcast_to(energy_prior_mass,posterior_role_mass.shape),\n    np.broadcast_to(gaussian_prior_mass,posterior_role_mass.shape)],axis=1)\nsource_pair_mean=np.stack([posterior_source_mean,\n    np.broadcast_to(energy_prior_mean,posterior_source_mean.shape),\n    np.broadcast_to(gaussian_prior_mean,posterior_source_mean.shape)],axis=1)\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nrole_selected=role_score.argmax(axis=-1)\nrole_estimate=periods[role_selected]\nrole_confidence=np.take_along_axis(role_score,role_selected[...,None],axis=-1)[...,0]\nprefix_role_estimate=periods[(prefix_role_mass@window.T).argmax(axis=-1)]\nprior_half_weight=softmax(prior_logratio[:noise_n//2],axis=0)\nprior_half_mass=np.einsum("qr,rqp->rp",prior_half_weight,\n    prior_particle_mass[:,:noise_n//2],optimize=True)\nprint("ENERGY_IMPORTANCE","posterior_ess",np.quantile(posterior_ess,[0,.1,.5,.9,1]).tolist(),\n    "posterior_max_weight",np.quantile(particle_weight.max(axis=1),[0,.5,.9,1]).tolist(),\n    "prior_role_ess",(1./np.sum(prior_weight**2,axis=0)).tolist(),\n    "prior_half_to_full_period_shift",(periods[(prior_half_mass@window.T).argmax(axis=-1)]\n        -role_estimate[0,1]).tolist(),\n    "prior_half_to_full_mass_L1",np.sum(np.abs(prior_half_mass-energy_prior_mass),axis=-1).tolist(),\n    "posterior_half_to_full_target_period_shift",np.quantile(np.abs(\n        prefix_role_estimate[:,1,0]-prefix_role_estimate[:,2,0]),[0,.5,.9,1]).tolist(),\n    "posterior_half_to_full_target_mass_L1",np.quantile(np.sum(np.abs(\n        prefix_role_mass[:,1,0]-prefix_role_mass[:,2,0]),axis=-1),[0,.5,.9,1]).tolist(),flush=True)\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\nmethods=np.asarray(energy_settings["methods"])\npredictions=pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],len(methods)),\n    "method":np.tile(methods,len(held_rows)),"estimate_h":estimate.ravel(),"confidence":confidence.ravel(),\n    "heldout_fold":fold,"heldout_run":np.repeat(run[heldout],len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    source_pair_mean=source_pair_mean,periods=periods,mass=mass,estimate=estimate,confidence=confidence,\n    methods=methods,role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,\n    proposal_stem=str(proposal_stem),posterior_particle_weights=particle_weight,\n    posterior_source_logratio=posterior_logratio,posterior_ess=posterior_ess,\n    prior_wave=prior_wave,prior_source_logratio=prior_logratio,prior_particle_weights=prior_weight,\n    prior_particle_mass=prior_particle_mass,\n    training_trace_id=trace_id[train],training_groups=training_groups,seed=settings["seed"],\n    prefix_role_estimate=prefix_role_estimate,posterior_particles=particle_n)\nprint("ENERGY_SOURCE_PREDICTED",flush=True)\nexec(compile(structural_source_readout_stage[\n    structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'

exec(compile({True:structural_energy_source_setup_stage+structural_energy_source_train_stage,False:""}[args.stage=="structural-energy-source-fit"],__file__,"exec"))
exec(compile({True:structural_energy_source_predict_stage,False:""}[args.stage=="structural-energy-source-predict"],__file__,"exec"))

structural_bridge_energy_setup_stage = '\nexec(compile(structural_energy_source_setup_stage.split("energy_wave=",1)[0].replace(\n    \'application["structural_energy_source"]\',\'application["structural_bridge_energy"]\'),__file__,"exec"))\nbridge_count=energy_settings["training_particles"]\nwaymark_angle=np.linspace(0.,np.pi/2.,bridge_count+1)\nwaymark_wave=np.cos(waymark_angle[:-1,None,None,None])*source_unit[None] \\\n    +np.sin(waymark_angle[:-1,None,None,None])*noise_unit[None,:len(train_rows)]\nwaymark_wave/=np.sqrt(np.mean(waymark_wave**2,axis=-1,keepdims=True))\nrole_code=np.array([1.,-1.])[None,:,None]\nenergy_wave=np.concatenate([waymark_wave.reshape(-1,2,length),noise_unit[:noise_n]],axis=0)\ntraining_input=np.stack([energy_wave,np.broadcast_to(role_code,energy_wave.shape)],axis=-2).reshape(\n    -1,2,length)\ntensor_training_input=torch.as_tensor(training_input,dtype=torch.float32)\ntensor_row_weight=torch.as_tensor(row_weight,dtype=torch.float64)\nnoise_magnitude=np.sqrt(1./np.sum(row_weight**2))\nlog_noise_magnitude=float(np.log(noise_magnitude))\nwaymark_rows=bridge_count*len(train_rows)*2\nstage_index=torch.arange(bridge_count)\nwidth=energy_settings["width"]\nkernel=settings["kernel_size"]\ndilation=energy_settings["dilations"]\nenergy_model=nn.Sequential(\n    nn.Conv1d(2,width,kernel,padding=(kernel//2)*dilation[0],dilation=dilation[0],padding_mode="replicate"),\n    nn.Tanh(),\n    nn.Conv1d(width,width,kernel,padding=(kernel//2)*dilation[1],dilation=dilation[1],padding_mode="replicate"),\n    nn.Tanh(),\n    nn.Conv1d(width,width,kernel,padding=(kernel//2)*dilation[2],dilation=dilation[2],padding_mode="replicate"),\n    nn.Tanh(),\n    nn.Conv1d(width,width,kernel,padding=(kernel//2)*dilation[3],dilation=dilation[3],padding_mode="replicate"),\n    nn.Tanh(),nn.Conv1d(width,bridge_count,1),nn.AdaptiveAvgPool1d(1),nn.Flatten())\nnn.init.zeros_(energy_model[-3].weight)\nnn.init.zeros_(energy_model[-3].bias)\nparameter_names=tuple(dict(energy_model.named_parameters()))\nparameter_shapes=tuple(map(torch.Tensor.size,energy_model.parameters()))\nparameter_sizes=tuple(map(torch.Tensor.numel,energy_model.parameters()))\ninitial=nn.utils.parameters_to_vector(energy_model.parameters()).detach().numpy().astype(np.float64)\nunpack=lambda vector:dict(zip(parameter_names,\n    map(torch.reshape,torch.split(vector,parameter_sizes),parameter_shapes)))\n\nbridge_logratio=lambda vector,inputs:torch.func.functional_call(\n    energy_model,unpack(vector),(inputs,)).to(torch.float64)\nenergy_logratio=lambda vector,inputs:bridge_logratio(vector,inputs).sum(dim=-1)\nobjective=lambda vector:(\n    score:=bridge_logratio(vector,tensor_training_input),\n    waymark_score:=score[:waymark_rows].reshape(bridge_count,len(train_rows),2,bridge_count),\n    positive:=waymark_score[stage_index,:,:,stage_index],\n    negative:=waymark_score[stage_index[1:],:,:,stage_index[:-1]],\n    final_negative:=score[waymark_rows:,-1].reshape(noise_n,2),\n    ((torch.nn.functional.softplus(log_noise_magnitude-positive)*tensor_row_weight[None,:,None]).sum()\n        +noise_magnitude*(torch.nn.functional.softplus(negative-log_noise_magnitude)\n            *tensor_row_weight[None,:,None]).sum()\n        +noise_magnitude*torch.nn.functional.softplus(\n            final_negative-log_noise_magnitude).mean(dim=0).sum())/(2.*bridge_count)\n    +settings["weight_decay"]*vector.to(torch.float64).square().mean())[-1]\nautograd_objective=torch.func.grad_and_value(objective)\nto_scipy=lambda gradient,value:(value.detach().item(),gradient.detach().numpy().astype(np.float64))\nscipy_objective=lambda vector:to_scipy(*autograd_objective(torch.as_tensor(vector,dtype=torch.float32)))\nstem=energy_settings["stem"].with_name(energy_settings["stem"].name+"_common_fold"+str(fold))\n'

structural_bridge_energy_train_stage = '\ninitial_loss,initial_gradient=scipy_objective(initial)\nassert np.isfinite(initial_loss) and np.isfinite(initial_gradient).all()\nloss_history=[[0,initial_loss]]\nprint("BRIDGE_ENERGY_TRAIN","records",len(train_rows),"groups",len(training_groups),\n    "bridges",bridge_count,"noise_per_role",noise_n,"parameters",len(initial),\n    "noise_magnitude",noise_magnitude,"initial_loss",initial_loss,"seed",settings["seed"],flush=True)\nresult=minimize(scipy_objective,initial,jac=True,method="L-BFGS-B",\n    callback=lambda intermediate_result:(loss_history.append([len(loss_history),float(intermediate_result.fun)]),\n        len(loss_history)%50==0 and print("BRIDGE_ENERGY_PROGRESS",len(loss_history)-1,\n            intermediate_result.fun,flush=True)),\n    options={"maxiter":energy_settings["maxiter"],"ftol":energy_settings["ftol"],\n        "gtol":settings["gtol"],"maxls":settings["maxls"]})\nparameters=torch.as_tensor(result.x,dtype=torch.float32)\ntraining_score=bridge_logratio(parameters,tensor_training_input).detach().numpy()\ntraining_waymark_score=training_score[:waymark_rows].reshape(bridge_count,len(train_rows),2,bridge_count)\npositive_score=training_waymark_score[np.arange(bridge_count),:,:,np.arange(bridge_count)]\nnegative_score=training_waymark_score[np.arange(1,bridge_count),:,:,np.arange(bridge_count-1)]\ntraining_noise_score=training_score[waymark_rows:].reshape(noise_n,2,bridge_count)\npositive_loss=np.einsum("n,knr->kr",row_weight,np.logaddexp(0.,log_noise_magnitude-positive_score))\nnegative_loss=noise_magnitude*np.concatenate([\n    np.einsum("n,knr->kr",row_weight,np.logaddexp(0.,negative_score-log_noise_magnitude)),\n    np.mean(np.logaddexp(0.,training_noise_score[:,:,-1]-log_noise_magnitude),axis=0)[None]],axis=0)\ncheck_waymark_wave=np.cos(waymark_angle[:-1,None,None,None])*source_unit[None] \\\n    +np.sin(waymark_angle[:-1,None,None,None])*noise_unit[None,noise_n:noise_n+len(train_rows)]\ncheck_waymark_wave/=np.sqrt(np.mean(check_waymark_wave**2,axis=-1,keepdims=True))\ncheck_wave=np.concatenate([check_waymark_wave.reshape(-1,2,length),noise_unit[noise_n:]],axis=0)\ncheck_input=np.stack([check_wave,np.broadcast_to(role_code,check_wave.shape)],axis=-2).reshape(-1,2,length)\ncheck_score=bridge_logratio(parameters,torch.as_tensor(check_input,dtype=torch.float32)).detach().numpy()\ncheck_waymark_score=check_score[:waymark_rows].reshape(bridge_count,len(train_rows),2,bridge_count)\ncheck_positive_score=check_waymark_score[np.arange(bridge_count),:,:,np.arange(bridge_count)]\ncheck_negative_score=check_waymark_score[np.arange(1,bridge_count),:,:,np.arange(bridge_count-1)]\ncheck_noise_score=check_score[waymark_rows:].reshape(noise_n,2,bridge_count)\ncheck_positive_loss=np.einsum("n,knr->kr",row_weight,np.logaddexp(\n    0.,log_noise_magnitude-check_positive_score))\ncheck_negative_loss=noise_magnitude*np.concatenate([\n    np.einsum("n,knr->kr",row_weight,np.logaddexp(0.,check_negative_score-log_noise_magnitude)),\n    np.mean(np.logaddexp(0.,check_noise_score[:,:,-1]-log_noise_magnitude),axis=0)[None]],axis=0)\ntraining_log_normalizer=logsumexp(training_noise_score.sum(axis=-1),axis=0)-np.log(noise_n)\ncheck_log_normalizer=logsumexp(check_noise_score.sum(axis=-1),axis=0)-np.log(noise_n)\ndump({"parameters":result.x,"parameter_names":parameter_names,"parameter_shapes":parameter_shapes,\n    "optimization":result,"training_loss_history":np.asarray(loss_history),\n    "source_covariance":source_covariance,"coordinate_basis":coordinate_basis,\n    "training_trace_id":trace_id[train],"training_groups":training_groups,\n    "settings":dict(energy_settings),"seed":settings["seed"],"waymark_angles":waymark_angle,\n    "noise_magnitude":noise_magnitude,"noise_samples_per_role":noise_n,\n    "training_log_normalizer":training_log_normalizer,"check_log_normalizer":check_log_normalizer,\n    "training_bridge_role_loss":positive_loss+negative_loss,\n    "check_bridge_role_loss":check_positive_loss+check_negative_loss,\n    "heldout_optical_read":False,"target":"optically_separated_target_luminescence_waveform"},\n    stem.with_suffix(".joblib"))\nprint("BRIDGE_ENERGY_OPTIMIZED","loss",result.fun,"iterations",result.nit,\n    "status",str(result.message),"training_bridge_role_loss",(positive_loss+negative_loss).tolist(),\n    "check_bridge_role_loss",(check_positive_loss+check_negative_loss).tolist(),\n    "noise_log_normalizer_train",training_log_normalizer.tolist(),\n    "noise_log_normalizer_check",check_log_normalizer.tolist(),flush=True)\nraise SystemExit(0)\n'

structural_bridge_energy_predict_stage = structural_energy_source_predict_stage.replace("structural_energy_source_setup_stage","structural_bridge_energy_setup_stage")
exec(compile({True:structural_bridge_energy_setup_stage+structural_bridge_energy_train_stage,False:""}[args.stage=="structural-bridge-energy-fit"],__file__,"exec"))
exec(compile({True:structural_bridge_energy_predict_stage,False:""}[args.stage=="structural-bridge-energy-predict"],__file__,"exec"))

structural_sphere_flow_setup_stage = '\nfrom scipy.special import softmax\nexec(compile(structural_diffusion_source_setup_stage.split("data_sd=",1)[0],__file__,"exec"))\nflow_settings=application["structural_sphere_flow"]\nassert flow_settings["layers"]==4\nwhite_linear=source_eigenvector/np.sqrt(source_eigenvalue)[:,None,:]\nwhite_coordinate=np.einsum("nrd,rde->nre",source_coordinate,white_linear,optimize=True)\nunit_coordinate=white_coordinate/np.linalg.norm(white_coordinate,axis=-1,keepdims=True)\nangular_second_moment=np.einsum("n,nri,nrj->rij",row_weight,unit_coordinate,unit_coordinate,optimize=True)\n_,flow_rotation=np.linalg.eigh(angular_second_moment)\nwhite_rotation=white_linear@flow_rotation\ncoordinate_from_white=np.linalg.inv(white_rotation)\nrotated_unit=np.einsum("nrd,rde->nre",unit_coordinate,flow_rotation,optimize=True)\ntensor_unit=torch.as_tensor(rotated_unit,dtype=torch.float64)\ntensor_row_weight=torch.as_tensor(row_weight,dtype=torch.float64)\ntensor_white_rotation=torch.as_tensor(white_rotation,dtype=torch.float64)\nsphere_step=lambda x,pars:(\n    scale:=pars[...,0,:]-pars[...,0,:].mean(dim=-1,keepdim=True),\n    raw_offset:=pars[...,1,:],\n    squared_offset:=raw_offset.square().sum(dim=-1,keepdim=True),\n    offset:=raw_offset/torch.sqrt(1.+squared_offset),\n    scaled:=x*torch.exp(scale),\n    norm:=torch.linalg.vector_norm(scaled,dim=-1,keepdim=True),\n    linear_unit:=scaled/norm,\n    displacement:=linear_unit-offset,\n    squared_distance:=displacement.square().sum(dim=-1,keepdim=True),\n    transformed:=displacement/((1.+squared_offset)*squared_distance)-offset,\n    logjac:=scale.sum(dim=-1)-dimension*torch.log(norm[...,0])\n        +(dimension-1)*(-torch.log1p(squared_offset[...,0])-torch.log(squared_distance[...,0])),\n    (transformed,logjac))[-1]\nsphere_inverse_step=lambda z,pars:(\n    scale:=pars[...,0,:]-pars[...,0,:].mean(dim=-1,keepdim=True),\n    raw_offset:=pars[...,1,:],\n    squared_offset:=raw_offset.square().sum(dim=-1,keepdim=True),\n    offset:=raw_offset/torch.sqrt(1.+squared_offset),\n    displacement:=z+offset,\n    mapped:=displacement/((1.+squared_offset)*displacement.square().sum(dim=-1,keepdim=True))+offset,\n    scaled:=mapped*torch.exp(-scale),\n    scaled/torch.linalg.vector_norm(scaled,dim=-1,keepdim=True))[-1]\nsphere_forward=lambda vector,x:(\n    pars:=vector.reshape(flow_settings["layers"],2,2,dimension),\n    first:=sphere_step(x,pars[0]),\n    second:=sphere_step(first[0],pars[1]),\n    third:=sphere_step(second[0],pars[2]),\n    fourth:=sphere_step(third[0],pars[3]),\n    (fourth[0],first[1]+second[1]+third[1]+fourth[1]))[-1]\nsphere_inverse=lambda vector,z:(\n    pars:=vector.reshape(flow_settings["layers"],2,2,dimension),\n    third:=sphere_inverse_step(z,pars[3]),\n    second:=sphere_inverse_step(third,pars[2]),\n    first:=sphere_inverse_step(second,pars[1]),\n    sphere_inverse_step(first,pars[0]))[-1]\nsource_logratio=lambda vector,coordinates:(\n    white:=torch.einsum("...rd,rde->...re",coordinates,tensor_white_rotation),\n    unit:=white/torch.linalg.vector_norm(white,dim=-1,keepdim=True),\n    sphere_forward(vector,unit)[1])[-1]\nobjective=lambda vector:(\n    -(sphere_forward(vector,tensor_unit)[1]*tensor_row_weight[:,None]).sum()/2.\n    +settings["weight_decay"]*vector.square().mean())\nautograd_objective=torch.func.grad_and_value(objective)\nto_scipy=lambda gradient,value:(value.detach().item(),gradient.detach().numpy())\nscipy_objective=lambda vector:to_scipy(*autograd_objective(torch.as_tensor(vector,dtype=torch.float64)))\ninitial=np.zeros(flow_settings["layers"]*2*2*dimension,dtype=np.float64)\nstem=flow_settings["stem"].with_name(flow_settings["stem"].name+"_common_fold"+str(fold))\n'

structural_sphere_flow_train_stage = '\ninitial_loss,initial_gradient=scipy_objective(initial)\nassert np.isfinite(initial_loss) and np.isfinite(initial_gradient).all()\nloss_history=[[0,initial_loss]]\nprint("SPHERE_FLOW_TRAIN","records",len(train_rows),"groups",len(training_groups),\n    "dimension",dimension,"layers",flow_settings["layers"],"parameters",len(initial),\n    "initial_loss",initial_loss,flush=True)\nresult=minimize(scipy_objective,initial,jac=True,method="L-BFGS-B",\n    callback=lambda intermediate_result:(loss_history.append([len(loss_history),float(intermediate_result.fun)]),\n        len(loss_history)%50==0 and print("SPHERE_FLOW_PROGRESS",len(loss_history)-1,\n            intermediate_result.fun,flush=True)),\n    options={"maxiter":flow_settings["maxiter"],"ftol":flow_settings["ftol"],\n        "gtol":settings["gtol"],"maxls":settings["maxls"]})\nparameters=torch.as_tensor(result.x,dtype=torch.float64)\ntraining_logratio=sphere_forward(parameters,tensor_unit)[1].detach().numpy()\nnoise_n=2**flow_settings["noise_power"]\nnormal=ndtri(qmc.Sobol(d=2*dimension,scramble=True,seed=settings["seed"]).random_base2(\n    flow_settings["noise_power"]+1)).reshape(2*noise_n,2,dimension)\nradius=np.linalg.norm(normal,axis=-1,keepdims=True)\nbase_unit=normal/radius\ntensor_base_unit=torch.as_tensor(base_unit,dtype=torch.float64)\ngenerated_unit=sphere_inverse(parameters,tensor_base_unit)\nrecovered_base=sphere_forward(parameters,generated_unit)[0]\nrecovered_training=sphere_inverse(parameters,sphere_forward(parameters,tensor_unit)[0])\ninverse_error=max(torch.max(torch.abs(recovered_base-tensor_base_unit)).item(),\n    torch.max(torch.abs(recovered_training-tensor_unit)).item())\nassert inverse_error<1.e-8\nassert torch.max(torch.abs(generated_unit.square().sum(dim=-1)-1.))<1.e-10\nprior_coordinate=np.einsum("qrd,rde->qre",\n    generated_unit.detach().numpy()*radius,coordinate_from_white,optimize=True)\nproposal_mean=prior_coordinate[:noise_n].mean(axis=0)\nproposal_centered=prior_coordinate[:noise_n]-proposal_mean[None]\nproposal_covariance=np.einsum("qri,qrj->rij",proposal_centered,proposal_centered,optimize=True)/noise_n\nproposal_eigenvalue,proposal_eigenvector=np.linalg.eigh(proposal_covariance)\nassert proposal_eigenvalue.min()>0.\ncheck_mean=prior_coordinate[noise_n:].mean(axis=0)\ncheck_centered=prior_coordinate[noise_n:]-check_mean[None]\ncheck_covariance=np.einsum("qri,qrj->rij",check_centered,check_centered,optimize=True)/noise_n\nprint("SPHERE_FLOW_GENERATOR","inverse_error",inverse_error,\n    "source_mean_RMS",np.sqrt(np.mean((proposal_mean@coordinate_basis.T)**2,axis=-1)).tolist(),\n    "source_total_RMS",np.sqrt(np.mean((prior_coordinate[:noise_n]@coordinate_basis.T)**2,axis=(0,2))).tolist(),\n    "independent_bank_mean_RMS_difference",np.sqrt(np.mean(\n        ((proposal_mean-check_mean)@coordinate_basis.T)**2,axis=-1)).tolist(),\n    "independent_bank_covariance_relative_difference",(np.linalg.norm(\n        proposal_covariance-check_covariance,axis=(-2,-1))/np.linalg.norm(\n        proposal_covariance,axis=(-2,-1))).tolist(),flush=True)\ndump({"parameters":result.x,"optimization":result,"training_loss_history":np.asarray(loss_history),\n    "source_covariance":source_covariance,"coordinate_basis":coordinate_basis,\n    "flow_rotation":flow_rotation,"white_rotation":white_rotation,\n    "proposal_mean":proposal_mean,"proposal_covariance":proposal_covariance,\n    "proposal_eigenvalue":proposal_eigenvalue,"proposal_eigenvector":proposal_eigenvector,\n    "prior_coordinate":prior_coordinate[:noise_n],"prior_base_normal":normal[:noise_n],\n    "training_trace_id":trace_id[train],"training_groups":training_groups,\n    "settings":dict(flow_settings),"seed":settings["seed"],\n    "training_role_log_density_gain":np.einsum("n,nr->r",row_weight,training_logratio),\n    "inverse_error":inverse_error,"heldout_optical_read":False,\n    "target":"optically_separated_target_luminescence_waveform"},\n    stem.with_suffix(".joblib"))\nprint("SPHERE_FLOW_OPTIMIZED","loss",result.fun,"iterations",result.nit,"status",str(result.message),\n    "training_role_log_density_gain",np.einsum("n,nr->r",row_weight,training_logratio).tolist(),\n    "max_gradient",np.max(np.abs(result.jac)),flush=True)\nraise SystemExit(0)\n'

exec(compile({True:structural_sphere_flow_setup_stage+structural_sphere_flow_train_stage,False:""}[args.stage=="structural-sphere-flow-fit"],__file__,"exec"))

structural_sphere_flow_predict_stage = '\nfrom scipy.special import logsumexp,ndtr,ndtri,softmax\nexec(compile(structural_sphere_flow_setup_stage,__file__,"exec"))\nbundle=load(stem.with_suffix(".joblib"))\nassert np.array_equal(bundle["training_trace_id"],trace_id[train])\nassert np.allclose(bundle["white_rotation"],white_rotation,rtol=1.e-11,atol=1.e-11)\nparameters=torch.as_tensor(bundle["parameters"],dtype=torch.float64)\nproposal_mean=bundle["proposal_mean"]\nproposal_covariance=bundle["proposal_covariance"]\nproposal_eigenvalue=bundle["proposal_eigenvalue"]\nproposal_eigenvector=bundle["proposal_eigenvector"]\nintegral_settings=application["structural_diffusion_integral"]\nintegration_power=integral_settings["integration_power"]\ncalibration_uniform=qmc.Sobol(d=3,scramble=True,seed=settings["seed"]).random_base2(integration_power)\nbase_calibration_grid=calibration_mean+(ndtri(calibration_uniform)*np.sqrt(\n    calibration_eigenvalue))@calibration_eigenvector.T\nsign_n=len(active_sign)\ncalibration_grid=np.repeat(base_calibration_grid,sign_n,axis=0)\ngrid_sign=np.tile(sign_values,(len(base_calibration_grid),1))\namplitude_grid=np.exp(calibration_grid[:,:2])*grid_sign\nnoise_grid=np.exp(calibration_grid[:,2])\ngrid_logprior=np.tile(sign_logprior,len(base_calibration_grid))\nobservation_mean=amplitude_grid@proposal_mean\nobservation_covariance=np.einsum("qr,rij->qij",amplitude_grid**2,proposal_covariance,\n    optimize=True)+noise_grid[:,None,None]*np.diag(noise_eigenvalue)[None]\nobservation_factor=np.linalg.cholesky(observation_covariance)\nheld_coordinate=mixed[heldout]@coordinate_basis\ncentered_observation=held_coordinate[:,None,:]-observation_mean[None]\nwhitened_observation=np.linalg.solve(observation_factor,centered_observation.transpose(1,2,0))\nlog_likelihood=-.5*np.sum(whitened_observation**2,axis=1).T \\\n    -np.log(np.diagonal(observation_factor,axis1=-2,axis2=-1)).sum(axis=-1)[None]\nlog_node=log_likelihood+grid_logprior[None]\nnode_mass=softmax(log_node,axis=1)\nhalf=len(calibration_grid)//2\nhalf_mass=softmax(log_node[:,:half],axis=1)\nlog_evidence_change=(logsumexp(log_node,axis=1)-np.log(len(base_calibration_grid))) \\\n    -(logsumexp(log_node[:,:half],axis=1)-np.log(len(base_calibration_grid)//2))\ncalibration_mean_full=node_mass@calibration_grid\ncalibration_mean_half=half_mass@calibration_grid[:half]\nprint("SPHERE_GAUSSIAN_INTEGRAL","records",len(held_rows),"calibration_nodes",len(base_calibration_grid),\n    "signs",sign_n,"posterior_node_ess",np.quantile(1./np.sum(node_mass**2,axis=1),[0,.1,.5,.9,1]).tolist(),\n    "half_to_full_logevidence_abs",np.quantile(np.abs(log_evidence_change),[0,.5,.9,1]).tolist(),\n    "half_to_full_logcalibration_mean_abs",np.max(np.abs(\n        calibration_mean_full-calibration_mean_half),axis=0).tolist(),flush=True)\ninverse_observation=np.linalg.solve(observation_factor.swapaxes(-1,-2),whitened_observation)\nintegrated_precision_y=np.einsum("nqr,qdn->nrd",\n    node_mass[:,:,None]*amplitude_grid[None],inverse_observation,optimize=True)\ngaussian_source_mean=proposal_mean[None]+np.einsum("rij,nrj->nri",\n    proposal_covariance,integrated_precision_y,optimize=True)\ngaussian_source_mean=gaussian_source_mean@coordinate_basis.T\n\nparticle_n=integral_settings["posterior_particles"]\nnormal=ndtri(qmc.Sobol(d=3*dimension+3,scramble=True,seed=settings["seed"]).random_base2(\n    int(np.log2(particle_n))))\nselection_uniform=ndtr(normal[:,2*dimension])\nselected_node=np.sum(np.cumsum(node_mass,axis=1)[:,None,:]<selection_uniform[None,:,None],axis=-1)\nunique_node,node_map=np.unique(selected_node,return_inverse=True)\nselected_amplitude=amplitude_grid[selected_node]\nsource_normal=normal[:,:2*dimension].reshape(particle_n,2,dimension)\nprior_gaussian_coordinate=proposal_mean[None]+np.einsum("qre,rde->qrd",\n    source_normal*np.sqrt(proposal_eigenvalue)[None],proposal_eigenvector,optimize=True)\nprior_noise=normal[:,2*dimension+3:]*np.sqrt(noise_eigenvalue)[None]\npseudo_observation=np.einsum("nqr,qrd->nqd",selected_amplitude,prior_gaussian_coordinate,optimize=True) \\\n    +np.sqrt(noise_grid[selected_node])[...,None]*prior_noise[None]\npseudo_residual=held_coordinate[:,None]-pseudo_observation\nunique_covariance=observation_covariance[unique_node]\nunique_factor=np.linalg.cholesky(unique_covariance)\nunique_inverse=np.linalg.solve(unique_factor.swapaxes(-1,-2),\n    np.linalg.solve(unique_factor,np.eye(dimension)[None]))\nprecision_residual=np.einsum("nqde,nqe->nqd",\n    unique_inverse[node_map].reshape(len(held_rows),particle_n,dimension,dimension),\n    pseudo_residual,optimize=True)\nsource_coordinate_sample=prior_gaussian_coordinate[None]+selected_amplitude[...,None]*np.einsum(\n    "rij,nqj->nqri",proposal_covariance,precision_residual,optimize=True)\nsource_block=np.zeros((2*dimension,2*dimension))\nsource_block[:dimension,:dimension]=proposal_covariance[0]\nsource_block[dimension:,dimension:]=proposal_covariance[1]\ncheck_operator=np.concatenate(amplitude_grid[unique_node[0],:,None,None]*np.eye(dimension)[None],axis=1)\ncheck_gain=source_block@check_operator.T@unique_inverse[0]\ncheck_residual=np.eye(2*dimension)-check_gain@check_operator\ncheck_covariance=check_residual@source_block@check_residual.T \\\n    +noise_grid[unique_node[0]]*(check_gain*noise_eigenvalue[None])@check_gain.T\ncheck_direct_covariance=source_block-check_gain@check_operator@source_block\nassert np.allclose(check_covariance,check_direct_covariance,rtol=1.e-10,atol=1.e-10)\nfrom scipy.stats import multivariate_normal\ncheck_likelihood=multivariate_normal.logpdf(held_coordinate[0],mean=observation_mean[0],\n    cov=observation_covariance[0])+.5*dimension*np.log(2.*np.pi)\nassert np.allclose(check_likelihood,log_likelihood[0,0],rtol=1.e-10,atol=1.e-10)\nsource_samples=(source_coordinate_sample@coordinate_basis.T).transpose(0,2,1,3)\nassert np.isfinite(source_samples).all()\nposterior_angular_logratio=source_logratio(parameters,torch.as_tensor(\n    source_coordinate_sample,dtype=torch.float64)).detach().numpy()\nposterior_GP_white=np.einsum("nqrd,rde->nqre",source_coordinate_sample,white_linear,optimize=True)\nposterior_proposal_white=np.einsum("nqrd,rde->nqre",\n    source_coordinate_sample-proposal_mean[None,None],proposal_eigenvector,optimize=True) \\\n    /np.sqrt(proposal_eigenvalue)[None,None]\nposterior_role_logratio=posterior_angular_logratio \\\n    -.5*np.sum(posterior_GP_white**2-posterior_proposal_white**2,axis=-1) \\\n    +.5*np.log(proposal_eigenvalue/source_eigenvalue).sum(axis=-1)[None,None]\npair_logratio=posterior_role_logratio.sum(axis=-1)\nparticle_weight=softmax(pair_logratio,axis=1)\nposterior_ess=1./np.sum(particle_weight**2,axis=1)\n\nreadout_code=structural_source_readout_stage.split("prior_labels =",1)[0].replace(\n    "waves = np.stack([prediction,mixed[heldout]],axis=1)",\n    "waves = source_samples.reshape(len(held_rows),2*particle_n,length)").replace(\n    "np.repeat(held_mask,2,axis=0)","np.repeat(held_mask,2*particle_n,axis=0)").replace(\n    "np.repeat(held_count,2)","np.repeat(held_count,2*particle_n)")\nexec(compile(readout_code,__file__,"exec"))\nparticle_mass=softmax(log_evidence.reshape(len(held_rows),2,particle_n,len(periods))\n    +np.log(grid_weight)[None,None,None],axis=-1)\nposterior_role_mass=np.einsum("nq,nrqp->nrp",particle_weight,particle_mass,optimize=True)\ngaussian_role_mass=particle_mass.mean(axis=2)\nposterior_source_mean=np.einsum("nq,nrqt->nrt",particle_weight,source_samples,optimize=True)\nquarter_weight=softmax(pair_logratio[:,:particle_n//4],axis=1)\nhalf_weight=softmax(pair_logratio[:,:particle_n//2],axis=1)\nflow_prefix_mass=np.stack([\n    np.einsum("nq,nrqp->nrp",quarter_weight,particle_mass[:,:,:particle_n//4],optimize=True),\n    np.einsum("nq,nrqp->nrp",half_weight,particle_mass[:,:,:particle_n//2],optimize=True),\n    posterior_role_mass],axis=1)\ngaussian_prefix_mass=np.stack([particle_mass[:,:,:particle_n//4].mean(axis=2),\n    particle_mass[:,:,:particle_n//2].mean(axis=2),gaussian_role_mass],axis=1)\nprefix_role_mass=np.stack([flow_prefix_mass,gaussian_prefix_mass],axis=2)\n\nprior_flow_coordinate=bundle["prior_coordinate"]\nprior_base_normal=bundle["prior_base_normal"]\nnoise_n=len(prior_base_normal)\nprior_gaussian_coordinate=proposal_mean[None]+np.einsum("qre,rde->qrd",\n    prior_base_normal*np.sqrt(proposal_eigenvalue)[None],proposal_eigenvector,optimize=True)\nprior_wave=np.stack([prior_flow_coordinate,prior_gaussian_coordinate],axis=1)@coordinate_basis.T\nprior_readout=structural_source_readout_stage.split("prior_labels =",1)[0].replace(\n    "waves = np.stack([prediction,mixed[heldout]],axis=1)",\n    "waves = prior_wave.transpose(1,2,0,3).reshape(1,4*noise_n,length)").replace(\n    "held_mask = mask[heldout]","held_mask = np.ones((1,length),dtype=bool)").replace(\n    "held_count = count[heldout]","held_count = np.array([length])").replace(\n    "np.repeat(held_mask,2,axis=0)","np.repeat(held_mask,4*noise_n,axis=0)").replace(\n    "np.repeat(held_count,2)","np.repeat(held_count,4*noise_n)")\nexec(compile(prior_readout,__file__,"exec"))\nprior_particle_mass=softmax(log_evidence.reshape(2,2,noise_n,len(periods))\n    +np.log(grid_weight)[None,None,None],axis=-1)\nprior_role_mass=prior_particle_mass.mean(axis=2)\nrole_mass=np.stack([posterior_role_mass,gaussian_role_mass,\n    np.broadcast_to(prior_role_mass[0],posterior_role_mass.shape),\n    np.broadcast_to(prior_role_mass[1],posterior_role_mass.shape)],axis=1)\nprior_source_mean=prior_wave.mean(axis=0)\nsource_pair_mean=np.stack([posterior_source_mean,gaussian_source_mean,\n    np.broadcast_to(prior_source_mean[0],posterior_source_mean.shape),\n    np.broadcast_to(prior_source_mean[1],posterior_source_mean.shape)],axis=1)\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nrole_selected=role_score.argmax(axis=-1)\nrole_estimate=periods[role_selected]\nrole_confidence=np.take_along_axis(role_score,role_selected[...,None],axis=-1)[...,0]\nprefix_role_estimate=periods[(prefix_role_mass@window.T).argmax(axis=-1)]\nprior_half_mass=prior_particle_mass[:,:,:noise_n//2].mean(axis=2)\nprior_half_estimate=periods[(prior_half_mass@window.T).argmax(axis=-1)]\nprint("SPHERE_FLOW_IMPORTANCE",\n    "posterior_ess",np.quantile(posterior_ess,[0,.1,.5,.9,1]).tolist(),\n    "posterior_max_weight",np.quantile(particle_weight.max(axis=1),[0,.5,.9,1]).tolist(),\n    "posterior_half_to_full_target_period_shift",np.quantile(np.abs(\n        prefix_role_estimate[:,1,:,0]-prefix_role_estimate[:,2,:,0]),[0,.5,.9,1],axis=0).tolist(),\n    "posterior_half_to_full_target_mass_L1",np.quantile(np.sum(np.abs(\n        prefix_role_mass[:,1,:,0]-prefix_role_mass[:,2,:,0]),axis=-1),[0,.5,.9,1],axis=0).tolist(),\n    "prior_half_to_full_period_shift",(prior_half_estimate-role_estimate[0,2:]).tolist(),\n    "prior_half_to_full_mass_L1",np.sum(np.abs(prior_half_mass-prior_role_mass),axis=-1).tolist(),flush=True)\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\nmethods=np.asarray(flow_settings["methods"])\npredictions=pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],len(methods)),\n    "method":np.tile(methods,len(held_rows)),"estimate_h":estimate.ravel(),"confidence":confidence.ravel(),\n    "heldout_fold":fold,"heldout_run":np.repeat(run[heldout],len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    source_samples=source_samples,source_pair_mean=source_pair_mean,\n    periods=periods,mass=mass,estimate=estimate,confidence=confidence,methods=methods,\n    role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,\n    particle_mass=particle_mass,posterior_particle_weights=particle_weight,posterior_ess=posterior_ess,\n    posterior_source_logratio=posterior_role_logratio,\n    calibration_grid=calibration_grid,node_mass=node_mass,selected_node=selected_node,grid_sign=grid_sign,\n    prior_wave=prior_wave,prior_particle_mass=prior_particle_mass,\n    training_trace_id=trace_id[train],training_groups=training_groups,seed=settings["seed"],\n    prefix_role_estimate=prefix_role_estimate,posterior_particles=particle_n,\n    log_evidence_change=log_evidence_change,calibration_mean_full=calibration_mean_full,\n    calibration_mean_half=calibration_mean_half)\nprint("SPHERE_FLOW_PREDICTED",flush=True)\nexec(compile(structural_source_readout_stage[\n    structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
exec(compile({True:structural_sphere_flow_predict_stage,False:""}[args.stage=="structural-sphere-flow-predict"],__file__,"exec"))

structural_moving_sphere_flow_setup_stage = '\nfrom numpy.lib.stride_tricks import sliding_window_view\nexec(compile(structural_sphere_flow_setup_stage,__file__,"exec"))\nflow_settings=application["structural_moving_sphere_flow"]\nrecord_weight=row_weight.copy()\nfull_optical=pd.read_parquet(application["paths"]["lemna_dual_observations"],\n    columns=["trace_id","time_h","published_target_y","green","red"],\n    filters=[("trace_id","in",trace_id[train].tolist())])\nfull_optical=full_optical.assign(background=full_optical.green*application["background_templates"]["optical_coefficients"][0]\n    +full_optical.red*application["background_templates"]["optical_coefficients"][1])\nfull_target=full_optical.pivot(index="trace_id",columns="time_h",values="published_target_y").reindex(trace_id[train])\nfull_background=full_optical.pivot(index="trace_id",columns="time_h",values="background").reindex(trace_id[train])\nfull_pair=np.stack([full_target.to_numpy(),full_background.to_numpy()],axis=1)\nfull_time=full_target.columns.to_numpy(dtype=float)\nnp.testing.assert_allclose(np.diff(full_time),np.diff(time)[0],atol=1.e-12)\nwindows=sliding_window_view(full_pair,length,axis=-1).transpose(0,2,1,3)\nvalid_window=np.isfinite(windows).all(axis=(-2,-1))\nwindow_record,window_start=np.nonzero(valid_window)\nwindow_count=valid_window.sum(axis=1)\nassert (window_count>0).all()\nwindow_pair=windows[valid_window]\nwindow_pair-=(window_pair@base[0])@base[0].T\nwindow_unit=window_pair/np.sqrt(np.mean(window_pair**2,axis=-1,keepdims=True))\nwindow_weight=record_weight[window_record]/window_count[window_record]\nnp.testing.assert_allclose(np.bincount(window_record,weights=window_weight),record_weight,atol=1.e-15)\nnp.testing.assert_allclose(window_unit[full_time[window_start]==optical_time[0]],source_unit,atol=1.e-10)\nsource_unit=window_unit\nrow_weight=window_weight\nsource_coordinate=source_unit@coordinate_basis\nwhite_coordinate=np.einsum("nrd,rde->nre",source_coordinate,white_linear,optimize=True)\nunit_coordinate=white_coordinate/np.linalg.norm(white_coordinate,axis=-1,keepdims=True)\nangular_second_moment=np.einsum("n,nri,nrj->rij",row_weight,unit_coordinate,unit_coordinate,optimize=True)\n_,flow_rotation=np.linalg.eigh(angular_second_moment)\nwhite_rotation=white_linear@flow_rotation\ncoordinate_from_white=np.linalg.inv(white_rotation)\nrotated_unit=np.einsum("nrd,rde->nre",unit_coordinate,flow_rotation,optimize=True)\ntensor_unit=torch.as_tensor(rotated_unit,dtype=torch.float64)\ntensor_row_weight=torch.as_tensor(row_weight,dtype=torch.float64)\ntensor_white_rotation=torch.as_tensor(white_rotation,dtype=torch.float64)\nstem=flow_settings["stem"].with_name(flow_settings["stem"].name+"_common_fold"+str(fold))\nprint("MOVING_SOURCE_WINDOWS","records",len(train_rows),"groups",len(training_groups),\n    "windows",len(window_record),"per_record",np.unique(window_count,return_counts=True),\n    "original_weight_error",np.max(np.abs(np.bincount(window_record,weights=window_weight)-record_weight)),\n    "window_h",float(time[-1]-time[0]),flush=True)\n'
structural_moving_sphere_flow_train_stage = structural_sphere_flow_train_stage.replace('"training_trace_id":trace_id[train],','"training_window_record":window_record,"training_window_start_h":full_time[window_start],\n    "training_window_weight":window_weight,"training_record_weight":record_weight,\n    "training_trace_id":trace_id[train],')
structural_moving_sphere_flow_predict_stage = structural_sphere_flow_predict_stage.replace('structural_sphere_flow_setup_stage','structural_moving_sphere_flow_setup_stage')
exec(compile({True:structural_moving_sphere_flow_setup_stage+structural_moving_sphere_flow_train_stage,False:""}[args.stage=="structural-moving-sphere-flow-fit"],__file__,"exec"))
exec(compile({True:structural_moving_sphere_flow_predict_stage,False:""}[args.stage=="structural-moving-sphere-flow-predict"],__file__,"exec"))

structural_origin_source_setup_stage = '\nfrom scipy.special import logsumexp,softmax,ndtri,ndtr\nexec(compile(structural_diffusion_source_setup_stage.split("data_sd=",1)[0],__file__,"exec"))\nfrom numpy.lib.stride_tricks import sliding_window_view\nexec(compile(structural_moving_sphere_flow_setup_stage[\n    structural_moving_sphere_flow_setup_stage.index("record_weight=row_weight.copy()"):\n    structural_moving_sphere_flow_setup_stage.index("white_coordinate=")],__file__,"exec"))\norigin_settings=application["structural_origin_source"]\nstem=origin_settings["stem"].with_name(origin_settings["stem"].name+"_common_fold"+str(fold))\norigin_time=full_time[:len(full_time)-length+1]\norigin_prior=np.bincount(window_start,weights=window_weight,minlength=len(origin_time))\norigin_mean=np.zeros((len(origin_time),2,dimension))\nnp.add.at(origin_mean,window_start,window_weight[:,None,None]*source_coordinate)\norigin_mean/=origin_prior[:,None,None]\ncentered_pair=(source_coordinate-origin_mean[window_start]).reshape(len(window_start),2*dimension)\npaired_covariance=(centered_pair.T*window_weight)@centered_pair\npaired_eigenvalue,paired_eigenvector=np.linalg.eigh(paired_covariance)\nassert paired_eigenvalue.min()>0.\npaired_blocks=paired_covariance.reshape(2,dimension,2,dimension)\nnp.testing.assert_allclose(origin_prior.sum(),1.,atol=1.e-12)\nprint("ORIGIN_SOURCE_FIT","records",len(train_rows),"experiments",len(training_groups),\n    "real_windows",len(window_start),"origin_states",len(origin_time),\n    "paired_covariance_eigenvalue_range",[float(paired_eigenvalue.min()),float(paired_eigenvalue.max())],\n    "source_mean_RMS_range",np.stack([\n        np.sqrt(np.mean((origin_mean@coordinate_basis.T)**2,axis=-1)).min(axis=0),\n        np.sqrt(np.mean((origin_mean@coordinate_basis.T)**2,axis=-1)).max(axis=0)]).tolist(),flush=True)\n'
structural_origin_source_fit_stage = '\ndump({"origin_time":origin_time,"origin_prior":origin_prior,"origin_mean":origin_mean,\n    "paired_covariance":paired_covariance,"paired_eigenvalue":paired_eigenvalue,\n    "paired_eigenvector":paired_eigenvector,"coordinate_basis":coordinate_basis,\n    "noise_eigenvalue":noise_eigenvalue,"calibration_mean":calibration_mean,\n    "calibration_covariance":calibration_covariance,"sign_prior":sign_prior,\n    "training_trace_id":trace_id[train],"training_groups":training_groups,\n    "training_window_record":window_record,"training_window_start_h":full_time[window_start],\n    "training_window_weight":window_weight,"training_record_weight":record_weight,\n    "settings":dict(origin_settings),"seed":settings["seed"],"heldout_optical_read":False,\n    "target":"optically_separated_target_luminescence_waveform"},stem.with_suffix(".joblib"))\nprint("ORIGIN_SOURCE_SAVED",flush=True)\nraise SystemExit(0)\n'
exec(compile({True:structural_origin_source_setup_stage+structural_origin_source_fit_stage,False:""}[args.stage=="structural-origin-source-fit"],__file__,"exec"))

structural_origin_source_predict_stage = '\nfrom scipy.special import logsumexp,softmax,ndtri,ndtr\nfrom scipy.stats import multivariate_normal\nexec(compile(structural_diffusion_source_setup_stage.split("data_sd=",1)[0],__file__,"exec"))\norigin_settings=application["structural_origin_source"]\nstem=origin_settings["stem"].with_name(origin_settings["stem"].name+"_common_fold"+str(fold))\nbundle=load(stem.with_suffix(".joblib"))\nassert np.array_equal(bundle["training_trace_id"],trace_id[train])\nnp.testing.assert_allclose(bundle["coordinate_basis"],coordinate_basis,rtol=1.e-11,atol=1.e-11)\norigin_time=bundle["origin_time"]\norigin_prior=bundle["origin_prior"]\norigin_mean=bundle["origin_mean"]\npaired_covariance=bundle["paired_covariance"]\npaired_eigenvalue=bundle["paired_eigenvalue"]\npaired_eigenvector=bundle["paired_eigenvector"]\npaired_blocks=paired_covariance.reshape(2,dimension,2,dimension)\nintegration_power=origin_settings["integration_power"]\ncalibration_uniform=qmc.Sobol(d=3,scramble=True,seed=settings["seed"]).random_base2(integration_power)\nbase_calibration_grid=calibration_mean+(ndtri(calibration_uniform)*np.sqrt(\n    calibration_eigenvalue))@calibration_eigenvector.T\nsign_n=len(active_sign)\ncalibration_grid=np.repeat(base_calibration_grid,sign_n,axis=0)\ngrid_sign=np.tile(sign_values,(len(base_calibration_grid),1))\namplitude_grid=np.exp(calibration_grid[:,:2])*grid_sign\nnoise_grid=np.exp(calibration_grid[:,2])\ngrid_logprior=np.tile(sign_logprior,len(base_calibration_grid))\nobservation_covariance=np.einsum("qr,qs,risj->qij",amplitude_grid,amplitude_grid,\n    paired_blocks,optimize=True)+noise_grid[:,None,None]*np.diag(noise_eigenvalue)[None]\nobservation_factor=np.linalg.cholesky(observation_covariance)\nheld_coordinate=mixed[heldout]@coordinate_basis\nwhitened_y=np.linalg.solve(observation_factor,held_coordinate.T[None])\nbase_log_node=-.5*np.einsum("qdn,qdn->nq",whitened_y,whitened_y,optimize=True)     -np.log(np.diagonal(observation_factor,axis1=-2,axis2=-1)).sum(axis=-1)[None]     -.5*dimension*np.log(2.*np.pi)+grid_logprior[None]\ndel whitened_y\ntensor_amplitude=torch.as_tensor(amplitude_grid,dtype=torch.float64)\ntensor_factor=torch.as_tensor(observation_factor,dtype=torch.float64)\ntensor_y=torch.as_tensor(held_coordinate,dtype=torch.float64)\ntensor_base_node=torch.as_tensor(base_log_node,dtype=torch.float64)\norigin_log_node=lambda mean:(\n    observation_mean:=tensor_amplitude@mean,\n    precision_mean:=torch.cholesky_solve(observation_mean[...,None],tensor_factor)[...,0],\n    tensor_base_node+tensor_y@precision_mean.T\n        -.5*(observation_mean*precision_mean).sum(dim=-1)[None])[-1]\nfirst_log_node=origin_log_node(torch.as_tensor(origin_mean[0],dtype=torch.float64)).numpy()\ncheck_logpdf=multivariate_normal.logpdf(held_coordinate[0],\n    mean=amplitude_grid[0]@origin_mean[0],cov=observation_covariance[0])\nnp.testing.assert_allclose(first_log_node[0,0]-grid_logprior[0],check_logpdf,atol=1.e-9)\nprint("ORIGIN_GAUSSIAN_LIKELIHOOD_CHECK","absolute_error",\n    float(abs(first_log_node[0,0]-grid_logprior[0]-check_logpdf)),flush=True)\ndel first_log_node\nlog_node=torch.vmap(origin_log_node,chunk_size=1)(\n    torch.as_tensor(origin_mean,dtype=torch.float64)).numpy()\nlog_normalizer=logsumexp(log_node,axis=-1)\nlog_evidence=log_normalizer.T-np.log(len(base_calibration_grid))\nhalf=len(calibration_grid)//2\nhalf_log_evidence=logsumexp(log_node[:,:,:half],axis=-1).T-np.log(len(base_calibration_grid)//2)\nexternal_group_names,external_group_index=np.unique(run[heldout],return_inverse=True)\ngroup_membership=(external_group_names[:,None]==run[heldout][None]).astype(float)\nshared_origin_mass=softmax(group_membership@log_evidence+np.log(origin_prior)[None],axis=1)\nindividual_origin_mass=softmax(log_evidence+np.log(origin_prior)[None],axis=1)\nhalf_shared_origin_mass=softmax(group_membership@half_log_evidence+np.log(origin_prior)[None],axis=1)\nhalf_individual_origin_mass=softmax(half_log_evidence+np.log(origin_prior)[None],axis=1)\nposterior_origin_mass=np.stack([shared_origin_mass[external_group_index],individual_origin_mass],axis=1)\nnode_probability=np.exp(log_node-log_normalizer[:,:,None])\nconditional_calibration_ess=1./np.sum(node_probability**2,axis=-1)\ndel log_node\nprint("ORIGIN_INTEGRAL","records",len(held_rows),"experiments",len(external_group_names),\n    "origin_states",len(origin_time),"calibration_nodes",len(base_calibration_grid),"signs",sign_n,\n    "half_to_full_log_evidence_abs",np.quantile(np.abs(log_evidence-half_log_evidence),[0,.5,.9,1]).tolist(),\n    "half_to_full_shared_origin_L1",np.sum(np.abs(shared_origin_mass-half_shared_origin_mass),axis=1).tolist(),\n    "half_to_full_individual_origin_L1",np.quantile(np.sum(np.abs(\n        individual_origin_mass-half_individual_origin_mass),axis=1),[0,.5,.9,1]).tolist(),flush=True)\nprint("ORIGIN_GROUP_POSTERIOR","experiments",external_group_names.tolist(),\n    "mode_start_h",origin_time[shared_origin_mass.argmax(axis=1)].tolist(),\n    "effective_states",(1./np.sum(shared_origin_mass**2,axis=1)).tolist(),\n    "mean_calibration_ess",np.quantile(np.einsum("nmj,jn->nm",\n        posterior_origin_mass,conditional_calibration_ess,optimize=True),[0,.5,.9,1],axis=0).tolist(),flush=True)\nparticle_n=origin_settings["posterior_particles"]\nuniform=qmc.Sobol(d=3*dimension+2,scramble=True,seed=settings["seed"]).random_base2(int(np.log2(particle_n)))\nnormal=ndtri(uniform[:,:3*dimension])\norigin_uniform=uniform[:,-2]\ncalibration_select_uniform=uniform[:,-1]\nselected_origin=np.sum(np.cumsum(posterior_origin_mass,axis=-1)[:,:,None,:]\n    <origin_uniform[None,None,:,None],axis=-1)\nnp.cumsum(node_probability,axis=-1,out=node_probability)\ncalibration_selection=torch.searchsorted(\n    torch.as_tensor(node_probability.reshape(-1,len(calibration_grid)),dtype=torch.float64),\n    torch.as_tensor(np.broadcast_to(calibration_select_uniform,\n        (len(origin_time)*len(held_rows),particle_n)).copy(),dtype=torch.float64),right=False).numpy()\ncalibration_selection=calibration_selection.reshape(len(origin_time),len(held_rows),particle_n)\nselected_node=calibration_selection[selected_origin,np.arange(len(held_rows))[:,None,None],\n    np.arange(particle_n)[None,None,:]]\ndel node_probability,calibration_selection\nselected_amplitude=amplitude_grid[selected_node]\nprior_centered=(normal[:,:2*dimension]*np.sqrt(paired_eigenvalue))@paired_eigenvector.T\nprior_coordinate=origin_mean[selected_origin]+prior_centered.reshape(particle_n,2,dimension)[None,None]\nprior_noise=normal[:,2*dimension:]*np.sqrt(noise_eigenvalue)[None]\npseudo_observation=np.einsum("nmqr,nmqrd->nmqd",selected_amplitude,prior_coordinate,optimize=True)     +np.sqrt(noise_grid[selected_node])[...,None]*prior_noise[None,None]\npseudo_residual=held_coordinate[:,None,None]-pseudo_observation\nunique_node,node_map=np.unique(selected_node,return_inverse=True)\nunique_factor=torch.as_tensor(observation_factor[unique_node],dtype=torch.float64)\nunique_inverse=torch.cholesky_inverse(unique_factor)\ncheck_node=int(selected_node[0,0,0])\ncheck_operator=np.concatenate(amplitude_grid[check_node,:,None,None]*np.eye(dimension)[None],axis=1)\ncheck_inverse=np.linalg.inv(observation_covariance[check_node])\ncheck_gain=paired_covariance@check_operator.T@check_inverse\ncheck_residual=np.eye(2*dimension)-check_gain@check_operator\ncheck_conditional=paired_covariance-check_gain@check_operator@paired_covariance\ncheck_matheron=check_residual@paired_covariance@check_residual.T     +noise_grid[check_node]*(check_gain*noise_eigenvalue)@check_gain.T\nnp.testing.assert_allclose(check_conditional,check_matheron,rtol=1.e-8,atol=1.e-9)\ndel observation_covariance,observation_factor,tensor_factor,unique_factor\nprecision_residual=torch.vmap(lambda indices,residual:torch.einsum(\n    "mqij,mqj->mqi",unique_inverse[indices],residual),chunk_size=1)(\n    torch.as_tensor(node_map.reshape(selected_node.shape),dtype=torch.long),\n    torch.as_tensor(pseudo_residual,dtype=torch.float64)).numpy()\nnp.testing.assert_allclose(precision_residual[0,0,0],\n    check_inverse@pseudo_residual[0,0,0],rtol=1.e-9,atol=1.e-9)\nsource_coordinate_sample=prior_coordinate+np.einsum("risj,nmqj,nmqs->nmqri",\n    paired_blocks,precision_residual,selected_amplitude,optimize=True)\nsource_samples=np.einsum("nmqrd,td->nmrqt",source_coordinate_sample,coordinate_basis,optimize=True)\nposterior_source_mean=source_samples.mean(axis=3)\ndel unique_inverse,prior_coordinate,pseudo_observation,pseudo_residual,precision_residual,source_coordinate_sample\nprint("ORIGIN_SOURCE_SAMPLES","shape",source_samples.shape,\n    "Matheron_covariance_error",float(np.max(np.abs(check_conditional-check_matheron))),flush=True)\nsource_readout=structural_source_readout_stage.split("prior_labels =",1)[0].replace(\n    "waves = np.stack([prediction,mixed[heldout]],axis=1)",\n    "waves = source_samples.reshape(len(held_rows),4*particle_n,length)").replace(\n    "np.repeat(held_mask,2,axis=0)","np.repeat(held_mask,4*particle_n,axis=0)").replace(\n    "np.repeat(held_count,2)","np.repeat(held_count,4*particle_n)")\nexec(compile(source_readout,__file__,"exec"))\nparticle_mass=softmax(log_evidence.reshape(len(held_rows),2,2,particle_n,len(periods))\n    +np.log(grid_weight)[None,None,None,None],axis=-1)\nposterior_role_mass=particle_mass.mean(axis=3)\nprefix_role_mass=np.stack([particle_mass[:,:,:,:particle_n//4].mean(axis=3),\n    particle_mass[:,:,:,:particle_n//2].mean(axis=3),posterior_role_mass],axis=1)\nprior_uniform=qmc.Sobol(d=2*dimension+1,scramble=True,seed=settings["seed"]).random_base2(\n    origin_settings["prior_power"])\nprior_origin=np.searchsorted(np.cumsum(origin_prior),prior_uniform[:,-1],side="left")\nprior_normal=ndtri(prior_uniform[:,:2*dimension])\nprior_centered=(prior_normal*np.sqrt(paired_eigenvalue))@paired_eigenvector.T\nprior_source_coordinate=origin_mean[prior_origin]+prior_centered.reshape(-1,2,dimension)\nprior_wave=prior_source_coordinate@coordinate_basis.T\nprior_n=len(prior_uniform)\nprior_readout=structural_source_readout_stage.split("prior_labels =",1)[0].replace(\n    "waves = np.stack([prediction,mixed[heldout]],axis=1)",\n    "waves = prior_wave.transpose(1,0,2).reshape(1,2*prior_n,length)").replace(\n    "held_mask = mask[heldout]","held_mask = np.ones((1,length),dtype=bool)").replace(\n    "held_count = count[heldout]","held_count = np.array([length])").replace(\n    "np.repeat(held_mask,2,axis=0)","np.repeat(held_mask,2*prior_n,axis=0)").replace(\n    "np.repeat(held_count,2)","np.repeat(held_count,2*prior_n)")\nexec(compile(prior_readout,__file__,"exec"))\nprior_particle_mass=softmax(log_evidence.reshape(2,prior_n,len(periods))\n    +np.log(grid_weight)[None,None],axis=-1)\nprior_role_mass=prior_particle_mass.mean(axis=1)\nrole_mass=np.concatenate([posterior_role_mass,\n    np.broadcast_to(prior_role_mass,(len(held_rows),1,2,len(periods)))],axis=1)\nsource_pair_mean=np.concatenate([posterior_source_mean,\n    np.broadcast_to(prior_wave.mean(axis=0),(len(held_rows),1,2,length))],axis=1)\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nrole_selected=role_score.argmax(axis=-1)\nrole_estimate=periods[role_selected]\nrole_confidence=np.take_along_axis(role_score,role_selected[...,None],axis=-1)[...,0]\nprefix_role_estimate=periods[(prefix_role_mass@window.T).argmax(axis=-1)]\nprior_half_mass=prior_particle_mass[:,:prior_n//2].mean(axis=1)\nprior_half_estimate=periods[(prior_half_mass@window.T).argmax(axis=-1)]\nprint("ORIGIN_PERIOD_INTEGRATION",\n    "half_to_full_target_period_shift",np.quantile(np.abs(\n        prefix_role_estimate[:,1,:,0]-prefix_role_estimate[:,2,:,0]),[0,.5,.9,1],axis=0).tolist(),\n    "half_to_full_target_mass_L1",np.quantile(np.sum(np.abs(\n        prefix_role_mass[:,1,:,0]-prefix_role_mass[:,2,:,0]),axis=-1),[0,.5,.9,1],axis=0).tolist(),\n    "prior_half_to_full_period_shift",(prior_half_estimate-role_estimate[0,-1]).tolist(),\n    "prior_half_to_full_mass_L1",np.sum(np.abs(prior_half_mass-prior_role_mass),axis=-1).tolist(),flush=True)\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\nmethods=np.asarray(origin_settings["methods"])\npredictions=pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],len(methods)),\n    "method":np.tile(methods,len(held_rows)),"estimate_h":estimate.ravel(),"confidence":confidence.ravel(),\n    "heldout_fold":fold,"heldout_run":np.repeat(run[heldout],len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    source_samples=source_samples,source_pair_mean=source_pair_mean,\n    periods=periods,mass=mass,estimate=estimate,confidence=confidence,methods=methods,\n    role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,\n    particle_mass=particle_mass,calibration_grid=calibration_grid,selected_node=selected_node,\n    selected_origin=selected_origin,origin_time=origin_time,origin_prior=origin_prior,\n    posterior_origin_mass=posterior_origin_mass,shared_origin_mass=shared_origin_mass,\n    individual_origin_mass=individual_origin_mass,half_shared_origin_mass=half_shared_origin_mass,\n    half_individual_origin_mass=half_individual_origin_mass,\n    group_names=external_group_names,group_index=external_group_index,\n    conditional_calibration_ess=conditional_calibration_ess,\n    prior_wave=prior_wave,prior_particle_mass=prior_particle_mass,\n    prefix_role_estimate=prefix_role_estimate,posterior_particles=particle_n,\n    training_trace_id=trace_id[train],training_groups=training_groups,seed=settings["seed"])\nprint("ORIGIN_SOURCE_PREDICTED",flush=True)\nexec(compile(structural_source_readout_stage[\n    structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
exec(compile({True:structural_origin_source_predict_stage,False:""}[args.stage=="structural-origin-source-predict"],__file__,"exec"))

