structural_cohort_source_setup_stage = '\nfrom scipy.special import logsumexp,softmax,ndtri,ndtr\nexec(compile(structural_diffusion_source_setup_stage.split("data_sd=",1)[0],__file__,"exec"))\nfrom numpy.lib.stride_tricks import sliding_window_view\nexec(compile(structural_moving_sphere_flow_setup_stage[\n    structural_moving_sphere_flow_setup_stage.index("record_weight=row_weight.copy()"):\n    structural_moving_sphere_flow_setup_stage.index("white_coordinate=")],__file__,"exec"))\ncohort_settings=application["structural_cohort_source"]\nstem=cohort_settings["stem"].with_name(cohort_settings["stem"].name+"_common_fold"+str(fold))\npaired_dimension=2*dimension\ntraining_group_index=np.unique(run[train],return_inverse=True)[1]\nstart_count=len(full_time)-length+1\nraw_group_id=training_group_index[window_record]*start_count+window_start\ngroup_code,group_index=np.unique(raw_group_id,return_inverse=True)\ngroup_n=np.bincount(group_index)\ngroup_weight=np.bincount(group_index,weights=window_weight)\nnp.testing.assert_allclose(window_weight,group_weight[group_index]/group_n[group_index],atol=1.e-15)\npaired_coordinate=source_coordinate.reshape(len(window_record),paired_dimension)\ngroup_mean=np.zeros((len(group_n),paired_dimension))\nnp.add.at(group_mean,group_index,paired_coordinate)\ngroup_mean/=group_n[:,None]\nprivate_residual=paired_coordinate-group_mean[group_index]\nwithin_covariance=(private_residual.T*window_weight)@private_residual\ngroup_sizes,size_index=np.unique(group_n,return_inverse=True)\nsize_weight=np.bincount(size_index,weights=group_weight)\nsize_first=np.zeros((len(group_sizes),paired_dimension))\nsize_second=np.zeros((len(group_sizes),paired_dimension,paired_dimension))\nnp.add.at(size_first,size_index,group_weight[:,None]*group_mean)\nnp.add.at(size_second,size_index,group_weight[:,None,None]*group_mean[:,:,None]*group_mean[:,None,:])\ninitial_mean=group_weight@group_mean\ncentered_mean=group_mean-initial_mean\nwithin_coefficient=np.sum(size_weight*(1.-1./group_sizes))\ninitial_private=within_covariance/within_coefficient\ninitial_shared=(centered_mean.T*group_weight)@centered_mean\ninitial_covariance=np.stack([initial_shared,initial_private])\ninitial_factor=np.linalg.cholesky(initial_covariance)\ntri_row,tri_column=np.tril_indices(paired_dimension)\nis_diagonal=tri_row==tri_column\npacked_factor=initial_factor[:,tri_row,tri_column].copy()\npacked_factor[:,is_diagonal]=np.log(packed_factor[:,is_diagonal])\ninitial=np.r_[initial_mean,packed_factor.ravel()]\ntensor_role=torch.arange(2)[:,None]\ntensor_row=torch.as_tensor(tri_row)[None]\ntensor_column=torch.as_tensor(tri_column)[None]\ntensor_diagonal=torch.as_tensor(is_diagonal)[None]\ntensor_n=torch.as_tensor(group_sizes,dtype=torch.float64)\ntensor_weight=torch.as_tensor(size_weight,dtype=torch.float64)\ntensor_first=torch.as_tensor(size_first,dtype=torch.float64)\ntensor_second=torch.as_tensor(size_second,dtype=torch.float64)\ntensor_within=torch.as_tensor(within_covariance,dtype=torch.float64)\nunpack_cohort=lambda vector:(\n    raw:=vector[paired_dimension:].reshape(2,-1),\n    values:=torch.where(tensor_diagonal,raw.exp(),raw),\n    factor:=torch.zeros((2,paired_dimension,paired_dimension),dtype=vector.dtype).index_put(\n        (tensor_role,tensor_row,tensor_column),values),\n    (vector[:paired_dimension],factor,factor@factor.transpose(-2,-1)))[-1]\ncohort_objective=lambda vector:(\n    decoded:=unpack_cohort(vector),\n    mean:=decoded[0],factor:=decoded[1],covariance:=decoded[2],\n    count_factor:=torch.linalg.cholesky(covariance[1][None]+tensor_n[:,None,None]*covariance[0][None]),\n    centered_second:=tensor_second-tensor_first[:,:,None]*mean[None,None,:]\n        -mean[None,:,None]*tensor_first[:,None,:]+tensor_weight[:,None,None]*mean[None,:,None]*mean[None,None,:],\n    .5/paired_dimension*(within_coefficient*2.*torch.diagonal(factor[1]).log().sum()\n        +torch.cholesky_solve(tensor_within,factor[1]).diagonal().sum()\n        +((tensor_weight/tensor_n)*2.*torch.diagonal(count_factor,dim1=-2,dim2=-1).log().sum(dim=-1)).sum()\n        +torch.cholesky_solve(centered_second,count_factor).diagonal(dim1=-2,dim2=-1).sum()))[-1]\nautograd_objective=torch.func.grad_and_value(cohort_objective)\nto_scipy=lambda gradient,value:(value.detach().item(),gradient.detach().numpy())\nscipy_objective=lambda vector:to_scipy(*autograd_objective(torch.as_tensor(vector,dtype=torch.float64)))\nprint("COHORT_SOURCE_SETUP","records",len(train_rows),"experiments",len(training_groups),\n    "real_windows",len(window_record),"cohort_windows",len(group_n),"cohort_sizes",group_sizes.tolist(),\n    "parameters",len(initial),"initial_covariance_min_eigenvalues",np.linalg.eigvalsh(initial_covariance)[:,0].tolist(),flush=True)\n'
structural_cohort_source_fit_stage = '\ninitial_loss,initial_gradient=scipy_objective(initial)\nassert np.isfinite(initial_loss) and np.isfinite(initial_gradient).all()\nloss_history=[[0,initial_loss]]\nprint("COHORT_SOURCE_TRAIN","initial_loss",initial_loss,flush=True)\nresult=minimize(scipy_objective,initial,jac=True,method="L-BFGS-B",\n    callback=lambda intermediate_result:(loss_history.append([len(loss_history),float(intermediate_result.fun)]),\n        len(loss_history)%50==0 and print("COHORT_SOURCE_PROGRESS",len(loss_history)-1,\n            intermediate_result.fun,flush=True)),\n    options={"maxiter":cohort_settings["maxiter"],"ftol":cohort_settings["ftol"],\n        "gtol":settings["gtol"],"maxls":settings["maxls"]})\nfitted=unpack_cohort(torch.as_tensor(result.x,dtype=torch.float64))\ncohort_mean=fitted[0].detach().numpy()\ncohort_factor=fitted[1].detach().numpy()\ncohort_covariance=fitted[2].detach().numpy()\ndump({"cohort_mean":cohort_mean,"cohort_covariance":cohort_covariance,"cohort_factor":cohort_factor,\n    "coordinate_basis":coordinate_basis,"noise_eigenvalue":noise_eigenvalue,\n    "calibration_mean":calibration_mean,"calibration_covariance":calibration_covariance,\n    "sign_prior":sign_prior,"training_trace_id":trace_id[train],"training_groups":training_groups,\n    "training_window_record":window_record,"training_window_start_h":full_time[window_start],\n    "training_window_weight":window_weight,"training_record_weight":record_weight,\n    "training_cohort_group_code":group_code,"training_cohort_size":group_n,"training_cohort_weight":group_weight,\n    "optimization":result,"training_loss_history":np.asarray(loss_history),\n    "settings":dict(cohort_settings),"seed":settings["seed"],"heldout_optical_read":False,\n    "target":"optically_separated_target_luminescence_waveform"},stem.with_suffix(".joblib"))\nprint("COHORT_SOURCE_OPTIMIZED","loss",result.fun,"iterations",result.nit,"status",str(result.message),\n    "max_gradient",np.max(np.abs(result.jac)),"covariance_min_eigenvalues",\n    np.linalg.eigvalsh(cohort_covariance)[:,0].tolist(),\n    "shared_private_role_trace",np.stack([np.trace(cohort_covariance[:,:dimension,:dimension],axis1=-2,axis2=-1),\n        np.trace(cohort_covariance[:,dimension:,dimension:],axis1=-2,axis2=-1)],axis=-1).tolist(),flush=True)\nraise SystemExit(0)\n'
exec(compile({True:structural_cohort_source_setup_stage+structural_cohort_source_fit_stage,False:""}[args.stage=="structural-cohort-source-fit"],__file__,"exec"))

structural_cohort_source_predict_stage = '\nfrom scipy.special import logsumexp,softmax,ndtri,ndtr\nfrom scipy.optimize import root\nfrom scipy.stats import multivariate_normal\nimport time as system_time\nexec(compile(structural_diffusion_source_setup_stage.split("data_sd=",1)[0],__file__,"exec"))\ncohort_settings=application["structural_cohort_source"]\nstem=cohort_settings["stem"].with_name(cohort_settings["stem"].name+"_common_fold"+str(fold))\nbundle=load(stem.with_suffix(".joblib"))\nassert np.array_equal(bundle["training_trace_id"],trace_id[train])\nnp.testing.assert_allclose(bundle["coordinate_basis"],coordinate_basis,rtol=1.e-11,atol=1.e-11)\npaired_dimension=2*dimension\ncohort_mean=bundle["cohort_mean"]\nshared_covariance,private_covariance=bundle["cohort_covariance"]\nshared_factor,private_factor=bundle["cohort_factor"]\nmarginal_covariance=shared_covariance+private_covariance\nmarginal_factor=np.linalg.cholesky(marginal_covariance)\nshared_inverse=np.linalg.inv(shared_covariance)\nshared_logdet=np.linalg.slogdet(shared_covariance)[1]\nprior_information=shared_inverse@cohort_mean\nprivate_blocks=private_covariance.reshape(2,dimension,2,dimension)\nshared_blocks=shared_covariance.reshape(2,dimension,2,dimension)\nmarginal_blocks=marginal_covariance.reshape(2,dimension,2,dimension)\nsource_mean_pair=cohort_mean.reshape(2,dimension)\nheld_coordinate=mixed[heldout]@coordinate_basis\nexternal_group_names,external_group_index=np.unique(run[heldout],return_inverse=True)\ngroup_membership=(external_group_names[:,None]==run[heldout][None]).astype(float)\nexternal_n=group_membership.sum(axis=1).astype(int)\ngroup_n=len(external_group_names)\ngroup_max_n=int(external_n.max())\ngroup_row_order=np.argsort(external_group_index,kind="stable")\nlocal_index=np.empty(len(held_rows),dtype=int)\nlocal_index[group_row_order]=np.arange(len(held_rows))-np.repeat(np.r_[0,np.cumsum(external_n)[:-1]],external_n)\npadded_y=np.zeros((group_n,group_max_n,dimension))\npadded_y[external_group_index,local_index]=held_coordinate\nintegration_power=cohort_settings["integration_power"]\ncalibration_uniform=qmc.Sobol(d=3,scramble=True,seed=settings["seed"]).random_base2(integration_power)\nbase_calibration_grid=calibration_mean+(ndtri(calibration_uniform)*np.sqrt(\n    calibration_eigenvalue))@calibration_eigenvector.T\nsign_n=len(active_sign)\ncalibration_grid=np.repeat(base_calibration_grid,sign_n,axis=0)\ngrid_sign=np.tile(sign_values,(len(base_calibration_grid),1))\namplitude_grid=np.exp(calibration_grid[:,:2])*grid_sign\nnoise_grid=np.exp(calibration_grid[:,2])\ngrid_logprior=np.tile(sign_logprior,len(base_calibration_grid))-np.log(len(base_calibration_grid))\ntensor_y=torch.as_tensor(held_coordinate,dtype=torch.float64)\nobservation_covariance=np.einsum("qr,qs,risj->qij",amplitude_grid,amplitude_grid,\n    marginal_blocks,optimize=True)+noise_grid[:,None,None]*np.diag(noise_eigenvalue)[None]\nobservation_factor=np.linalg.cholesky(observation_covariance)\nobservation_inverse=torch.cholesky_inverse(torch.as_tensor(observation_factor)).numpy()\nobservation_mean=amplitude_grid@source_mean_pair\nobservation_precision_mean=np.einsum("qij,qj->qi",observation_inverse,observation_mean,optimize=True)\ntensor_inverse=torch.as_tensor(observation_inverse)\nindependent_log_node=torch.vmap(lambda y:\n    -.5*torch.einsum("i,qij,j->q",y,tensor_inverse,y),chunk_size=1)(tensor_y).numpy()\nindependent_log_node+=held_coordinate@observation_precision_mean.T\nindependent_log_node-=.5*np.sum(observation_mean*observation_precision_mean,axis=-1)[None]\nindependent_log_node-=np.log(np.diagonal(observation_factor,axis1=-2,axis2=-1)).sum(axis=-1)[None]\nindependent_log_node+=grid_logprior[None]-.5*dimension*np.log(2.*np.pi)\ncheck_pdf=multivariate_normal.logpdf(held_coordinate[0],\n    mean=observation_mean[0],cov=observation_covariance[0])\nnp.testing.assert_allclose(independent_log_node[0,0]-grid_logprior[0],check_pdf,atol=1.e-9)\nindependent_node_probability=softmax(independent_log_node,axis=-1)\nindependent_ess=1./np.sum(independent_node_probability**2,axis=-1)\nhalf=len(calibration_grid)//2\nindependent_half_log_error=logsumexp(independent_log_node[:,:half],axis=-1)+np.log(2.)     -logsumexp(independent_log_node,axis=-1)\ndel independent_log_node,observation_inverse,observation_factor,observation_covariance,tensor_inverse\nobservation_covariance=np.einsum("qr,qs,risj->qij",amplitude_grid,amplitude_grid,\n    private_blocks,optimize=True)+noise_grid[:,None,None]*np.diag(noise_eigenvalue)[None]\nobservation_factor=np.linalg.cholesky(observation_covariance)\nobservation_logdet=2.*np.log(np.diagonal(observation_factor,axis1=-2,axis2=-1)).sum(axis=-1)\nobservation_inverse=torch.cholesky_inverse(torch.as_tensor(observation_factor)).numpy()\ntensor_inverse=torch.as_tensor(observation_inverse)\nbase_log_node=torch.vmap(lambda y:\n    -.5*torch.einsum("i,qij,j->q",y,tensor_inverse,y),chunk_size=1)(tensor_y).numpy()\nbase_log_node+=grid_logprior[None]-.5*observation_logdet[None]-.5*dimension*np.log(2.*np.pi)\ndel tensor_inverse,observation_covariance,observation_factor\ninverse_flat=observation_inverse.reshape(len(calibration_grid),-1)\namplitude_products=np.stack([amplitude_grid[:,0]**2,\n    amplitude_grid[:,0]*amplitude_grid[:,1],amplitude_grid[:,1]**2])\nmean_amplitude=np.exp(calibration_mean[:2]+.5*np.diag(calibration_covariance)[:2])     *(np.exp(sign_logprior)@sign_values)\nmean_amplitude_product=np.exp(calibration_mean[:2,None]+calibration_mean[None,:2]\n    +.5*(np.diag(calibration_covariance)[:2,None]+np.diag(calibration_covariance)[None,:2])\n    +calibration_covariance[:2,:2])*((sign_values.T*np.exp(sign_logprior))@sign_values)\nmean_noise=np.exp(calibration_mean[2]+.5*calibration_covariance[2,2])\nexpected_y=mean_amplitude@source_mean_pair\nmarginal_y_covariance=np.einsum("rs,risj->ij",mean_amplitude_product,\n    marginal_blocks+source_mean_pair[:,:,None,None]*source_mean_pair[None,None,:,:],optimize=True)     -np.outer(expected_y,expected_y)+mean_noise*np.diag(noise_eigenvalue)\nshared_y_covariance=np.einsum("r,s,risj->ij",mean_amplitude,mean_amplitude,shared_blocks,optimize=True)\ngroup_y_covariance=shared_y_covariance[None]+(\n    marginal_y_covariance-shared_y_covariance)[None]/external_n[:,None,None]\nsource_y_covariance=np.einsum("risj,s->rij",shared_blocks,mean_amplitude,optimize=True).reshape(paired_dimension,dimension)\ninitial_gain=np.linalg.solve(group_y_covariance,source_y_covariance.T[None]).transpose(0,2,1)\ngroup_y=group_membership@held_coordinate/external_n[:,None]\ninitial_mean=cohort_mean[None]+np.einsum("gij,gj->gi",initial_gain,group_y-expected_y[None],optimize=True)\ninitial_variance=shared_covariance[None]-initial_gain@source_y_covariance.T\ninitial_variance=(initial_variance+initial_variance.transpose(0,2,1))/2.\nassert np.linalg.eigvalsh(initial_variance).min()>0.\ninitial=np.r_[initial_mean.ravel(),initial_variance.ravel()]\nmean_size=group_n*paired_dimension\ncohort_variational_nodes=lambda vector:(\n    mean:=vector[:mean_size].reshape(group_n,2,dimension),\n    variance:=vector[mean_size:].reshape(group_n,2,dimension,2,dimension),\n    mean_wave:=np.einsum("qr,grd->gqd",amplitude_grid,mean,optimize=True),\n    precision_mean:=np.einsum("qij,gqj->gqi",observation_inverse,mean_wave,optimize=True),\n    cross_term:=np.matmul(padded_y,precision_mean.transpose(0,2,1)),\n    variance_blocks:=np.stack([variance[:,0,:,0,:],\n        variance[:,0,:,1,:]+variance[:,1,:,0,:],variance[:,1,:,1,:]],axis=1),\n    variance_term:=(variance_blocks.reshape(group_n*3,-1)@inverse_flat.T).reshape(\n        group_n,3,-1)*amplitude_products[None],\n    node:=base_log_node+cross_term[external_group_index,local_index]\n        -.5*np.sum(mean_wave*precision_mean,axis=-1)[external_group_index]\n        -.5*variance_term.sum(axis=1)[external_group_index],\n    node)[-1]\ncohort_variational_update=lambda node:(\n    probability:=softmax(node,axis=-1),\n    group_probability:=group_membership@probability,\n    precision_blocks:=((group_probability[:,None]*amplitude_products[None]).reshape(\n        group_n*3,-1)@inverse_flat).reshape(group_n,3,dimension,dimension),\n    precision:=shared_inverse[None]+np.concatenate([\n        np.concatenate([precision_blocks[:,0],precision_blocks[:,1]],axis=-1),\n        np.concatenate([precision_blocks[:,1],precision_blocks[:,2]],axis=-1)],axis=-2),\n    variance:=np.linalg.inv(precision),\n    variance:=(variance+variance.transpose(0,2,1))/2.,\n    weighted_y:=np.einsum("gn,nq,ni->gqi",group_membership,probability,held_coordinate,optimize=True),\n    precision_y:=np.einsum("qij,gqj->gqi",observation_inverse,weighted_y,optimize=True),\n    information:=prior_information[None]+np.einsum("qr,gqi->gri",\n        amplitude_grid,precision_y,optimize=True).reshape(group_n,paired_dimension),\n    mean:=np.einsum("gij,gj->gi",variance,information,optimize=True),\n    np.r_[mean.ravel(),variance.ravel()])[-1]\ncohort_variational_elbo=lambda vector,node:(\n    mean:=vector[:mean_size].reshape(group_n,paired_dimension),\n    variance:=vector[mean_size:].reshape(group_n,paired_dimension,paired_dimension),\n    centered:=mean-cohort_mean[None],\n    kl:=.5*(np.einsum("ij,gji->g",shared_inverse,variance,optimize=True)\n        +np.einsum("gi,ij,gj->g",centered,shared_inverse,centered,optimize=True)\n        -paired_dimension+shared_logdet-np.linalg.slogdet(variance)[1]),\n    logsumexp(node,axis=-1).sum()-kl.sum())[-1]\nvariational_history=[]\nstarted=system_time.perf_counter()\ncohort_fixed_point=lambda vector:(\n    node:=cohort_variational_nodes(vector),\n    updated:=cohort_variational_update(node),\n    elbo:=cohort_variational_elbo(vector,node),\n    variational_history.append([len(variational_history),elbo,\n        float(np.max(np.abs(updated-vector))),system_time.perf_counter()-started]),\n    (len(variational_history)==1 or len(variational_history)%25==0)\n        and print("COHORT_VARIATIONAL_PROGRESS",variational_history[-1],flush=True),\n    updated-vector)[-1]\nprint("COHORT_PREDICT","records",len(held_rows),"experiments",group_n,\n    "calibration_nodes",len(calibration_grid),"independent_calibration_ess",\n    np.quantile(independent_ess,[0,.1,.5,.9,1]).tolist(),\n    "independent_half_log_error",np.quantile(np.abs(independent_half_log_error),[0,.5,.9,1]).tolist(),flush=True)\ncheck_variational_node=cohort_variational_nodes(initial)\ncheck_operator=np.concatenate(amplitude_grid[0,:,None,None]*np.eye(dimension)[None],axis=1)\ncheck_covariance=check_operator@private_covariance@check_operator.T+noise_grid[0]*np.diag(noise_eigenvalue)\ncheck_variational_expected=multivariate_normal.logpdf(held_coordinate[0],\n    mean=check_operator@initial_mean[external_group_index[0]],cov=check_covariance) \\\n    -.5*np.trace(observation_inverse[0]@check_operator@initial_variance[external_group_index[0]]@check_operator.T) \\\n    +grid_logprior[0]\nnp.testing.assert_allclose(check_variational_node[0,0],check_variational_expected,atol=1.e-9)\nprint("COHORT_VARIATIONAL_LIKELIHOOD_CHECK","absolute_error",\n    float(abs(check_variational_node[0,0]-check_variational_expected)),flush=True)\ndel check_variational_node\nvariational_result=root(cohort_fixed_point,initial,method="linearmixing",\n    options={"jac_options":{"alpha":1.},"line_search":None,\n        "maxiter":cohort_settings["maxiter"],"fatol":settings["gtol"]})\nvariational_mean=variational_result.x[:mean_size].reshape(group_n,paired_dimension)\nvariational_covariance=variational_result.x[mean_size:].reshape(group_n,paired_dimension,paired_dimension)\nvariational_factor=np.linalg.cholesky(variational_covariance)\nvariational_node=cohort_variational_nodes(variational_result.x)\nvariational_node_probability=softmax(variational_node,axis=-1)\nvariational_ess=1./np.sum(variational_node_probability**2,axis=-1)\nvariational_half_log_error=logsumexp(variational_node[:,:half],axis=-1)+np.log(2.)     -logsumexp(variational_node,axis=-1)\nhistory_array=np.asarray(variational_history)\nassert np.diff(history_array[:,1]).min()>-1.e-7\nprint("COHORT_VARIATIONAL_FINISHED","success",bool(variational_result.success),\n    "status",str(variational_result.message),"iterations",len(variational_history),\n    "final_elbo",history_array[-1,1],"max_fixed_point_error",history_array[-1,2],\n    "calibration_ess",np.quantile(variational_ess,[0,.1,.5,.9,1]).tolist(),\n    "half_log_error",np.quantile(np.abs(variational_half_log_error),[0,.5,.9,1]).tolist(),flush=True)\nparticle_n=cohort_settings["posterior_particles"]\nsample_dimension=paired_dimension+group_max_n*(3*dimension+1)\nuniform=qmc.Sobol(d=sample_dimension,scramble=True,seed=settings["seed"]).random_base2(\n    int(np.ceil(np.log2(group_n*particle_n))))[:group_n*particle_n].reshape(\n        group_n,particle_n,sample_dimension)\nshared_normal=ndtri(uniform[:,:,:paired_dimension])\nrecord_uniform=uniform[:,:,paired_dimension:].reshape(group_n,particle_n,group_max_n,3*dimension+1)\nrecord_uniform=record_uniform[external_group_index,:,local_index]\nrecord_normal=ndtri(record_uniform[:,:,:3*dimension])\nnode_uniform=record_uniform[:,:,-1]\nnode_probability=np.stack([variational_node_probability,independent_node_probability],axis=1)\nnode_ess=1./np.sum(node_probability**2,axis=-1)\nnode_cumulative=np.cumsum(node_probability,axis=-1)\nselected_node=torch.searchsorted(torch.as_tensor(node_cumulative.reshape(-1,len(calibration_grid))),\n    torch.as_tensor(np.broadcast_to(node_uniform[:,None],(len(held_rows),2,particle_n)).copy().reshape(-1,particle_n)),\n    right=False).numpy().reshape(len(held_rows),2,particle_n)\ndel node_cumulative,node_probability,record_uniform,uniform,variational_node\nselected_amplitude=amplitude_grid[selected_node]\nshared_sample=variational_mean[:,None]+np.einsum("gqd,gid->gqi",shared_normal,variational_factor,optimize=True)\nprivate_sample=record_normal[:,:,:paired_dimension]@private_factor.T\nmarginal_sample=cohort_mean[None,None]+record_normal[:,:,:paired_dimension]@marginal_factor.T\nprior_coordinate=np.stack([shared_sample[external_group_index]+private_sample,marginal_sample],axis=1).reshape(\n    len(held_rows),2,particle_n,2,dimension)\nprior_noise=record_normal[:,:,paired_dimension:]*np.sqrt(noise_eigenvalue)[None,None]\npseudo_observation=np.einsum("nmqr,nmqrd->nmqd",selected_amplitude,prior_coordinate,optimize=True)     +np.sqrt(noise_grid[selected_node])[...,None]*prior_noise[:,None]\npseudo_residual=held_coordinate[:,None,None]-pseudo_observation\nunique_main,node_map=np.unique(selected_node[:,0],return_inverse=True)\nmain_inverse=observation_inverse[unique_main]\ndel observation_inverse,inverse_flat\nmain_precision_residual=torch.vmap(lambda index,residual:torch.einsum(\n    "qij,qj->qi",torch.as_tensor(main_inverse)[index],residual),chunk_size=1)(\n        torch.as_tensor(node_map.reshape(selected_node[:,0].shape)),\n        torch.as_tensor(pseudo_residual[:,0])).numpy()\nunique_individual,individual_map=np.unique(selected_node[:,1],return_inverse=True)\nindividual_covariance=np.einsum("qr,qs,risj->qij",amplitude_grid[unique_individual],amplitude_grid[unique_individual],\n    marginal_blocks,optimize=True)+noise_grid[unique_individual,None,None]*np.diag(noise_eigenvalue)[None]\nindividual_inverse=np.linalg.inv(individual_covariance)\nindividual_precision_residual=torch.vmap(lambda index,residual:torch.einsum(\n    "qij,qj->qi",torch.as_tensor(individual_inverse)[index],residual),chunk_size=1)(\n        torch.as_tensor(individual_map.reshape(selected_node[:,1].shape)),\n        torch.as_tensor(pseudo_residual[:,1])).numpy()\ncorrection=np.stack([np.einsum("risj,nqj,nqs->nqri",private_blocks,\n    main_precision_residual,selected_amplitude[:,0],optimize=True),\n    np.einsum("risj,nqj,nqs->nqri",marginal_blocks,\n    individual_precision_residual,selected_amplitude[:,1],optimize=True)],axis=1)\nsource_coordinate_sample=prior_coordinate+correction\nsource_samples=np.einsum("nmqrd,td->nmrqt",source_coordinate_sample,coordinate_basis,optimize=True)\nposterior_source_mean=source_samples.mean(axis=3)\ncheck_node=int(selected_node[0,0,0])\ncheck_operator=np.concatenate(amplitude_grid[check_node,:,None,None]*np.eye(dimension)[None],axis=1)\ncheck_inverse=main_inverse[np.searchsorted(unique_main,check_node)]\ncheck_gain=private_covariance@check_operator.T@check_inverse\ncheck_residual=np.eye(paired_dimension)-check_gain@check_operator\ncheck_conditional=private_covariance-check_gain@check_operator@private_covariance\ncheck_matheron=check_residual@private_covariance@check_residual.T     +noise_grid[check_node]*(check_gain*noise_eigenvalue)@check_gain.T\nnp.testing.assert_allclose(check_conditional,check_matheron,rtol=1.e-8,atol=1.e-9)\nprint("COHORT_SOURCE_SAMPLES","shape",source_samples.shape,\n    "Matheron_covariance_error",float(np.max(np.abs(check_conditional-check_matheron))),flush=True)\ndel main_inverse,individual_inverse,individual_covariance,prior_coordinate,pseudo_observation,pseudo_residual\ndel main_precision_residual,individual_precision_residual,correction,source_coordinate_sample\nsource_readout=structural_source_readout_stage.split("prior_labels =",1)[0].replace(\n    "waves = np.stack([prediction,mixed[heldout]],axis=1)",\n    "waves = source_samples.reshape(len(held_rows),4*particle_n,length)").replace(\n    "np.repeat(held_mask,2,axis=0)","np.repeat(held_mask,4*particle_n,axis=0)").replace(\n    "np.repeat(held_count,2)","np.repeat(held_count,4*particle_n)")\nexec(compile(source_readout,__file__,"exec"))\nparticle_mass=softmax(log_evidence.reshape(len(held_rows),2,2,particle_n,len(periods))\n    +np.log(grid_weight)[None,None,None,None],axis=-1)\nposterior_role_mass=particle_mass.mean(axis=3)\nprefix_role_mass=np.stack([particle_mass[:,:,:,:particle_n//4].mean(axis=3),\n    particle_mass[:,:,:,:particle_n//2].mean(axis=3),posterior_role_mass],axis=1)\nprior_uniform=qmc.Sobol(d=paired_dimension,scramble=True,seed=settings["seed"]).random_base2(\n    cohort_settings["prior_power"])\nprior_source_coordinate=(cohort_mean[None]+ndtri(prior_uniform)@marginal_factor.T).reshape(-1,2,dimension)\nprior_wave=prior_source_coordinate@coordinate_basis.T\nprior_n=len(prior_uniform)\nprior_readout=structural_source_readout_stage.split("prior_labels =",1)[0].replace(\n    "waves = np.stack([prediction,mixed[heldout]],axis=1)",\n    "waves = prior_wave.transpose(1,0,2).reshape(1,2*prior_n,length)").replace(\n    "held_mask = mask[heldout]","held_mask = np.ones((1,length),dtype=bool)").replace(\n    "held_count = count[heldout]","held_count = np.array([length])").replace(\n    "np.repeat(held_mask,2,axis=0)","np.repeat(held_mask,2*prior_n,axis=0)").replace(\n    "np.repeat(held_count,2)","np.repeat(held_count,2*prior_n)")\nexec(compile(prior_readout,__file__,"exec"))\nprior_particle_mass=softmax(log_evidence.reshape(2,prior_n,len(periods))\n    +np.log(grid_weight)[None,None],axis=-1)\nprior_role_mass=prior_particle_mass.mean(axis=1)\nrole_mass=np.concatenate([posterior_role_mass,\n    np.broadcast_to(prior_role_mass,(len(held_rows),1,2,len(periods)))],axis=1)\nsource_pair_mean=np.concatenate([posterior_source_mean,\n    np.broadcast_to(prior_wave.mean(axis=0),(len(held_rows),1,2,length))],axis=1)\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nrole_selected=role_score.argmax(axis=-1)\nrole_estimate=periods[role_selected]\nrole_confidence=np.take_along_axis(role_score,role_selected[...,None],axis=-1)[...,0]\nprefix_role_estimate=periods[(prefix_role_mass@window.T).argmax(axis=-1)]\nprior_half_mass=prior_particle_mass[:,:prior_n//2].mean(axis=1)\nprior_half_estimate=periods[(prior_half_mass@window.T).argmax(axis=-1)]\nprint("COHORT_PERIOD_INTEGRATION",\n    "half_to_full_target_period_shift",np.quantile(np.abs(\n        prefix_role_estimate[:,1,:,0]-prefix_role_estimate[:,2,:,0]),[0,.5,.9,1],axis=0).tolist(),\n    "half_to_full_target_mass_L1",np.quantile(np.sum(np.abs(\n        prefix_role_mass[:,1,:,0]-prefix_role_mass[:,2,:,0]),axis=-1),[0,.5,.9,1],axis=0).tolist(),\n    "prior_half_to_full_period_shift",(prior_half_estimate-role_estimate[0,-1]).tolist(),flush=True)\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\nmethods=np.asarray(cohort_settings["methods"])\npredictions=pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],len(methods)),\n    "method":np.tile(methods,len(held_rows)),"estimate_h":estimate.ravel(),"confidence":confidence.ravel(),\n    "heldout_fold":fold,"heldout_run":np.repeat(run[heldout],len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    source_samples=source_samples,source_pair_mean=source_pair_mean,shared_sample=shared_sample,\n    periods=periods,mass=mass,estimate=estimate,confidence=confidence,methods=methods,\n    role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,\n    particle_mass=particle_mass,calibration_grid=calibration_grid,selected_node=selected_node,\n    variational_mean=variational_mean,variational_covariance=variational_covariance,\n    variational_history=history_array,variational_success=variational_result.success,\n    variational_status=str(variational_result.message),node_ess=node_ess,\n    variational_half_log_error=variational_half_log_error,\n    independent_half_log_error=independent_half_log_error,\n    group_names=external_group_names,group_index=external_group_index,\n    prior_wave=prior_wave,prior_particle_mass=prior_particle_mass,\n    prefix_role_estimate=prefix_role_estimate,posterior_particles=particle_n,\n    training_trace_id=trace_id[train],training_groups=training_groups,seed=settings["seed"])\nprint("COHORT_SOURCE_PREDICTED",flush=True)\nexec(compile(structural_source_readout_stage[\n    structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
exec(compile({True:structural_cohort_source_predict_stage,False:""}[args.stage=="structural-cohort-source-predict"],__file__,"exec"))

structural_gated_cohort_fit_stage = '\nexec(compile(structural_cohort_source_setup_stage,__file__,"exec"))\nbundle=load(stem.with_suffix(".joblib"))\nshared_covariance,private_covariance=bundle["cohort_covariance"]\ncohort_mean=bundle["cohort_mean"]\nshared_inverse=np.linalg.inv(shared_covariance)\nprivate_inverse=np.linalg.inv(private_covariance)\ntarget_on_background=np.linalg.solve(shared_covariance[dimension:,dimension:],\n    shared_covariance[dimension:,:dimension]).T\ntarget_innovation=shared_covariance[:dimension,:dimension] \\\n    -target_on_background@shared_covariance[dimension:,:dimension]\ngated_operator=np.zeros((paired_dimension,paired_dimension))\ngated_operator[:dimension,dimension:]=target_on_background\ngated_operator[dimension:,dimension:]=np.eye(dimension)\ninnovation_covariance=np.zeros((paired_dimension,paired_dimension))\ninnovation_covariance[:dimension,:dimension]=target_innovation\nnp.testing.assert_allclose(gated_operator@shared_covariance@gated_operator.T+innovation_covariance,\n    shared_covariance,rtol=1.e-9,atol=1.e-10)\nloo_variance=np.linalg.inv(shared_inverse[None]+(group_sizes-1)[:,None,None]*private_inverse[None])\nloo_gain=loo_variance@private_inverse\nrow_size_index=size_index[group_index]\nother_centered=group_n[group_index,None]*group_mean[group_index]-paired_coordinate \\\n    -(group_n[group_index,None]-1)*cohort_mean\nloo_mean=cohort_mean+np.einsum("nij,nj->ni",loo_gain[row_size_index],other_centered,optimize=True)\ngated_loo_mean=cohort_mean+(loo_mean-cohort_mean)@gated_operator.T\npredictive_covariance=np.stack([private_covariance[None]+innovation_covariance[None] \\\n    +gated_operator[None]@loo_variance@gated_operator.T[None],\n    private_covariance[None]+loo_variance],axis=0)\npredictive_factor=np.linalg.cholesky(predictive_covariance)\npredictive_inverse_factor=np.linalg.inv(predictive_factor)\nresidual=np.stack([paired_coordinate-gated_loo_mean,paired_coordinate-loo_mean],axis=1)\ntensor_factor_inverse=torch.as_tensor(predictive_inverse_factor)\nwhitened=torch.vmap(lambda i,x:torch.einsum("rij,rj->ri",torch.index_select(tensor_factor_inverse,1,i.reshape(1))[:,0],x),chunk_size=256)(\n    torch.as_tensor(row_size_index),torch.as_tensor(residual)).numpy()\nlog_predictive=-.5*np.sum(whitened**2,axis=-1) \\\n    -np.log(np.diagonal(predictive_factor,axis1=-2,axis2=-1)).sum(axis=-1)[:,row_size_index].T \\\n    -.5*paired_dimension*np.log(2.*np.pi)\nfrom scipy.optimize import minimize_scalar\ngate_objective=lambda probability:-np.sum(window_weight*np.logaddexp(\n    np.log(probability)+log_predictive[:,1],np.log1p(-probability)+log_predictive[:,0]))\ngate_result=minimize_scalar(gate_objective,bounds=(0.,1.),method="bounded",\n    options={"xatol":cohort_settings["ftol"]})\ngate_log_prior=np.log([1.-gate_result.x,gate_result.x])\ngate_posterior=softmax(log_predictive+gate_log_prior[None],axis=-1)\nprint("COHORT_TARGET_GATE_TRAINING","records",len(train_rows),"real_windows",len(window_record),\n    "shared_probability",gate_result.x,"predictive_NLL",gate_result.fun,\n    "always_shared_NLL",-np.sum(window_weight*log_predictive[:,1]),\n    "always_private_NLL",-np.sum(window_weight*log_predictive[:,0]),\n    "state_log_predictive_shared_minus_private_quantile",np.quantile(\n        log_predictive[:,1]-log_predictive[:,0],[0,.1,.5,.9,1]).tolist(),\n    "weighted_mean_shared_posterior",np.sum(window_weight*gate_posterior[:,1]),\n    "innovation_min_eigenvalue",np.linalg.eigvalsh(target_innovation)[0],\n    "shared_target_trace",np.trace(shared_covariance[:dimension,:dimension]),\n    "target_innovation_trace",np.trace(target_innovation),flush=True)\nrun_gate=np.bincount(training_group_index[window_record],weights=window_weight*gate_posterior[:,1]) \\\n    /np.bincount(training_group_index[window_record],weights=window_weight)\nprint("COHORT_TARGET_GATE_BY_TRAIN_RUN",pd.DataFrame({"run":training_groups,"mean_shared_posterior":run_gate}).to_string(index=False),flush=True)\n\ngated_settings=application["structural_gated_cohort_source"]\ngated_stem=gated_settings["stem"].with_name(gated_settings["stem"].name+"_common_fold"+str(fold))\noperators=np.stack([gated_operator,np.eye(paired_dimension)])\noffset=cohort_mean[None]-np.einsum("hij,j->hi",operators,cohort_mean)\nconditional_covariance=np.stack([private_covariance+innovation_covariance,private_covariance])\nmarginal_covariance=operators@shared_covariance[None]@operators.transpose(0,2,1)+conditional_covariance\nnp.testing.assert_allclose(marginal_covariance[0],marginal_covariance[1],rtol=1.e-9,atol=1.e-10)\ndump({"parent_model":str(stem.with_suffix(".joblib")),"operators":operators,"offset":offset,\n    "conditional_covariance":conditional_covariance,"gate_log_prior":gate_log_prior,\n    "gate_optimization":gate_result,"training_gate_by_run":run_gate,"training_groups":training_groups,\n    "training_trace_id":trace_id[train],"training_mean_log_predictive":window_weight@log_predictive,\n    "training_window_record":window_record,"training_window_start_h":full_time[window_start],\n    "settings":dict(gated_settings),"seed":settings["seed"],"heldout_optical_read":False},\n    gated_stem.with_suffix(".joblib"))\nprint("GATED_COHORT_FITTED","marginal_covariance_error",\n    float(np.max(np.abs(marginal_covariance[0]-marginal_covariance[1]))),flush=True)\nraise SystemExit(0)\n'
exec(compile({True:structural_gated_cohort_fit_stage,False:""}[args.stage=="structural-gated-cohort-fit"],__file__,"exec"))

structural_gated_cohort_predict_stage = '\nfrom scipy.special import logsumexp,softmax,ndtri,ndtr\nfrom scipy.optimize import root\nfrom scipy.stats import multivariate_normal\nimport time as system_time\nexec(compile(structural_diffusion_source_setup_stage.split("data_sd=",1)[0],__file__,"exec"))\ngated_settings=application["structural_gated_cohort_source"]\nstem=gated_settings["stem"].with_name(gated_settings["stem"].name+"_common_fold"+str(fold))\ngate_bundle=load(stem.with_suffix(".joblib"))\nbundle=load(gate_bundle["parent_model"])\nassert np.array_equal(bundle["training_trace_id"],trace_id[train])\nassert np.array_equal(gate_bundle["training_trace_id"],trace_id[train])\nnp.testing.assert_allclose(bundle["coordinate_basis"],coordinate_basis,rtol=1.e-11,atol=1.e-11)\npaired_dimension=2*dimension\ncohort_mean=bundle["cohort_mean"]\nshared_covariance,private_covariance=bundle["cohort_covariance"]\nshared_inverse=np.linalg.inv(shared_covariance)\nshared_logdet=np.linalg.slogdet(shared_covariance)[1]\nprior_information=shared_inverse@cohort_mean\noperators=gate_bundle["operators"]\noffset=gate_bundle["offset"]\nconditional_covariance=gate_bundle["conditional_covariance"]\nconditional_factor=np.linalg.cholesky(conditional_covariance)\nconditional_blocks=conditional_covariance.reshape(2,2,dimension,2,dimension)\ngate_log_prior=gate_bundle["gate_log_prior"]\nmarginal_covariance=shared_covariance+private_covariance\nmarginal_blocks=marginal_covariance.reshape(2,dimension,2,dimension)\nsource_mean_pair=cohort_mean.reshape(2,dimension)\nheld_coordinate=mixed[heldout]@coordinate_basis\nexternal_group_names,external_group_index=np.unique(run[heldout],return_inverse=True)\ngroup_membership=(external_group_names[:,None]==run[heldout][None]).astype(float)\nexternal_n=group_membership.sum(axis=1).astype(int)\ngroup_n=len(external_group_names)\ngroup_max_n=int(external_n.max())\ngroup_row_order=np.argsort(external_group_index,kind="stable")\nlocal_index=np.empty(len(held_rows),dtype=int)\nlocal_index[group_row_order]=np.arange(len(held_rows))-np.repeat(np.r_[0,np.cumsum(external_n)[:-1]],external_n)\npadded_y=np.zeros((group_n,group_max_n,dimension))\npadded_y[external_group_index,local_index]=held_coordinate\nintegration_power=gated_settings["integration_power"]\ncalibration_uniform=qmc.Sobol(d=3,scramble=True,seed=settings["seed"]).random_base2(integration_power)\nbase_calibration_grid=calibration_mean+(ndtri(calibration_uniform)*np.sqrt(\n    calibration_eigenvalue))@calibration_eigenvector.T\nsign_n=len(active_sign)\ncalibration_grid=np.repeat(base_calibration_grid,sign_n,axis=0)\ngrid_sign=np.tile(sign_values,(len(base_calibration_grid),1))\namplitude_grid=np.exp(calibration_grid[:,:2])*grid_sign\nnoise_grid=np.exp(calibration_grid[:,2])\ngrid_logprior=np.tile(sign_logprior,len(base_calibration_grid))-np.log(len(base_calibration_grid))\nnode_n=len(calibration_grid)\nhalf=node_n//2\nobservation_covariance=np.einsum("qr,qs,hrisj->hqij",amplitude_grid,amplitude_grid,\n    conditional_blocks,optimize=True)+noise_grid[None,:,None,None]*np.diag(noise_eigenvalue)[None,None]\nobservation_factor=np.linalg.cholesky(observation_covariance)\nobservation_logdet=2.*np.log(np.diagonal(observation_factor,axis1=-2,axis2=-1)).sum(axis=-1)\nobservation_inverse=torch.cholesky_inverse(torch.as_tensor(observation_factor)).numpy()\ntensor_inverse=torch.as_tensor(observation_inverse)\ntensor_y=torch.as_tensor(held_coordinate)\nbase_log_node=torch.vmap(lambda y:\n    -.5*torch.einsum("i,hqij,j->hq",y,tensor_inverse,y),chunk_size=1)(tensor_y).numpy()\nbase_log_node+=grid_logprior[None,None]+gate_log_prior[None,:,None]     -.5*observation_logdet[None]-.5*dimension*np.log(2.*np.pi)\ndel tensor_inverse,observation_covariance,observation_factor\ninverse_flat=observation_inverse.reshape(2,node_n,-1)\namplitude_products=np.stack([amplitude_grid[:,0]**2,\n    amplitude_grid[:,0]*amplitude_grid[:,1],amplitude_grid[:,1]**2])\nobservation_offset=np.einsum("qr,hrd->hqd",amplitude_grid,offset.reshape(2,2,dimension),optimize=True)\nmean_amplitude=np.exp(calibration_mean[:2]+.5*np.diag(calibration_covariance)[:2])     *(np.exp(sign_logprior)@sign_values)\nmean_amplitude_product=np.exp(calibration_mean[:2,None]+calibration_mean[None,:2]\n    +.5*(np.diag(calibration_covariance)[:2,None]+np.diag(calibration_covariance)[None,:2])\n    +calibration_covariance[:2,:2])*((sign_values.T*np.exp(sign_logprior))@sign_values)\nmean_noise=np.exp(calibration_mean[2]+.5*calibration_covariance[2,2])\nexpected_y=mean_amplitude@source_mean_pair\nmarginal_y_covariance=np.einsum("rs,risj->ij",mean_amplitude_product,\n    marginal_blocks+source_mean_pair[:,:,None,None]*source_mean_pair[None,None,:,:],optimize=True)     -np.outer(expected_y,expected_y)+mean_noise*np.diag(noise_eigenvalue)\naverage_operator=np.einsum("h,hij->ij",np.exp(gate_log_prior),operators,optimize=True)\nmean_observation_operator=np.concatenate(mean_amplitude[:,None,None]*np.eye(dimension)[None],axis=1)\nsource_y_covariance=shared_covariance@average_operator.T@mean_observation_operator.T\nshared_y_covariance=mean_observation_operator@average_operator@source_y_covariance\ngroup_y_covariance=shared_y_covariance[None]+(\n    marginal_y_covariance-shared_y_covariance)[None]/external_n[:,None,None]\ninitial_gain=np.linalg.solve(group_y_covariance,source_y_covariance.T[None]).transpose(0,2,1)\ngroup_y=group_membership@held_coordinate/external_n[:,None]\ninitial_mean=cohort_mean[None]+np.einsum("gij,gj->gi",initial_gain,group_y-expected_y[None],optimize=True)\ninitial_variance=shared_covariance[None]-initial_gain@source_y_covariance.T\ninitial_variance=(initial_variance+initial_variance.transpose(0,2,1))/2.\nassert np.linalg.eigvalsh(initial_variance).min()>0.\ninitial=np.r_[initial_mean.ravel(),initial_variance.ravel()]\nmean_size=group_n*paired_dimension\ngated_variational_nodes=lambda vector:(\n    mean:=vector[:mean_size].reshape(group_n,paired_dimension),\n    variance:=vector[mean_size:].reshape(group_n,paired_dimension,paired_dimension),\n    mapped_mean:=(np.einsum("hij,gj->hgi",operators,mean,optimize=True)+offset[:,None]).reshape(\n        2,group_n,2,dimension),\n    mapped_variance:=(operators[:,None]@variance[None]@operators.transpose(0,2,1)[:,None]).reshape(\n        2,group_n,2,dimension,2,dimension),\n    mean_wave:=np.einsum("qr,hgrd->hgqd",amplitude_grid,mapped_mean,optimize=True),\n    precision_mean:=np.einsum("hqij,hgqj->hgqi",observation_inverse,mean_wave,optimize=True),\n    cross_term:=np.matmul(padded_y[None],precision_mean.transpose(0,1,3,2)),\n    variance_blocks:=np.stack([mapped_variance[:,:,0,:,0,:],\n        mapped_variance[:,:,0,:,1,:]+mapped_variance[:,:,1,:,0,:],\n        mapped_variance[:,:,1,:,1,:]],axis=2),\n    variance_term:=np.matmul(variance_blocks.reshape(2,group_n*3,-1),\n        inverse_flat.transpose(0,2,1)).reshape(2,group_n,3,-1)*amplitude_products[None,None],\n    node:=base_log_node+cross_term[:,external_group_index,local_index].transpose(1,0,2)\n        -.5*np.sum(mean_wave*precision_mean,axis=-1)[:,external_group_index].transpose(1,0,2)\n        -.5*variance_term.sum(axis=2)[:,external_group_index].transpose(1,0,2),\n    node)[-1]\ngated_variational_update=lambda node:(\n    probability:=softmax(node.reshape(len(held_rows),-1),axis=-1).reshape(len(held_rows),2,node_n),\n    group_probability:=np.einsum("gn,nhq->hgq",group_membership,probability,optimize=True),\n    precision_blocks:=np.matmul((group_probability[:,:,None]*amplitude_products[None,None]).reshape(\n        2,group_n*3,-1),inverse_flat).reshape(2,group_n,3,dimension,dimension),\n    source_precision:=np.concatenate([\n        np.concatenate([precision_blocks[:,:,0],precision_blocks[:,:,1]],axis=-1),\n        np.concatenate([precision_blocks[:,:,1],precision_blocks[:,:,2]],axis=-1)],axis=-2),\n    precision:=shared_inverse[None]+np.sum(\n        operators.transpose(0,2,1)[:,None]@source_precision@operators[:,None],axis=0),\n    variance:=np.linalg.inv(precision),\n    variance:=(variance+variance.transpose(0,2,1))/2.,\n    weighted_y:=np.einsum("gn,nhq,ni->hgqi",group_membership,probability,held_coordinate,optimize=True)\n        -group_probability[:,:,:,None]*observation_offset[:,None],\n    precision_y:=np.einsum("hqij,hgqj->hgqi",observation_inverse,weighted_y,optimize=True),\n    source_information:=np.einsum("qr,hgqi->hgri",amplitude_grid,precision_y,optimize=True).reshape(\n        2,group_n,paired_dimension),\n    information:=prior_information[None]+np.einsum("hji,hgj->gi",\n        operators,source_information,optimize=True),\n    mean:=np.einsum("gij,gj->gi",variance,information,optimize=True),\n    np.r_[mean.ravel(),variance.ravel()])[-1]\ngated_variational_elbo=lambda vector,node:(\n    mean:=vector[:mean_size].reshape(group_n,paired_dimension),\n    variance:=vector[mean_size:].reshape(group_n,paired_dimension,paired_dimension),\n    centered:=mean-cohort_mean[None],\n    kl:=.5*(np.einsum("ij,gji->g",shared_inverse,variance,optimize=True)\n        +np.einsum("gi,ij,gj->g",centered,shared_inverse,centered,optimize=True)\n        -paired_dimension+shared_logdet-np.linalg.slogdet(variance)[1]),\n    logsumexp(node.reshape(len(held_rows),-1),axis=-1).sum()-kl.sum())[-1]\nvariational_history=[]\nstarted=system_time.perf_counter()\ngated_fixed_point=lambda vector:(\n    node:=gated_variational_nodes(vector),\n    updated:=gated_variational_update(node),\n    elbo:=gated_variational_elbo(vector,node),\n    variational_history.append([len(variational_history),elbo,\n        float(np.max(np.abs(updated-vector))),system_time.perf_counter()-started]),\n    (len(variational_history)==1 or len(variational_history)%25==0)\n        and print("GATED_COHORT_PROGRESS",variational_history[-1],flush=True),\n    updated-vector)[-1]\nprint("GATED_COHORT_PREDICT","records",len(held_rows),"experiments",group_n,\n    "calibration_nodes_per_state",node_n,"shared_prior_probability",np.exp(gate_log_prior[1]),flush=True)\ncheck_node=gated_variational_nodes(initial)\ncheck_calibration=np.concatenate(amplitude_grid[0,:,None,None]*np.eye(dimension)[None],axis=1)\ncheck_operator=check_calibration@operators[0]\ncheck_covariance=check_calibration@conditional_covariance[0]@check_calibration.T     +noise_grid[0]*np.diag(noise_eigenvalue)\ncheck_expected=multivariate_normal.logpdf(held_coordinate[0],\n    mean=check_operator@initial_mean[external_group_index[0]]+check_calibration@offset[0],\n    cov=check_covariance)     -.5*np.trace(observation_inverse[0,0]@check_operator@initial_variance[external_group_index[0]]@check_operator.T)     +grid_logprior[0]+gate_log_prior[0]\nnp.testing.assert_allclose(check_node[0,0,0],check_expected,atol=1.e-9)\nprint("GATED_COHORT_LIKELIHOOD_CHECK","absolute_error",float(abs(check_node[0,0,0]-check_expected)),flush=True)\ndel check_node\nvariational_result=root(gated_fixed_point,initial,method="linearmixing",\n    options={"jac_options":{"alpha":1.},"line_search":None,\n        "maxiter":gated_settings["maxiter"],"fatol":settings["gtol"]})\nvariational_mean=variational_result.x[:mean_size].reshape(group_n,paired_dimension)\nvariational_covariance=variational_result.x[mean_size:].reshape(group_n,paired_dimension,paired_dimension)\nvariational_factor=np.linalg.cholesky(variational_covariance)\nvariational_node=gated_variational_nodes(variational_result.x)\nnode_probability=softmax(variational_node.reshape(len(held_rows),-1),axis=-1)\ngate_probability=node_probability.reshape(len(held_rows),2,node_n).sum(axis=-1)\nnode_ess=1./np.sum(node_probability**2,axis=-1)\nhalf_log_error=logsumexp(variational_node[:,:,:half].reshape(len(held_rows),-1),axis=-1)+np.log(2.)     -logsumexp(variational_node.reshape(len(held_rows),-1),axis=-1)\nhistory_array=np.asarray(variational_history)\nassert np.diff(history_array[:,1]).min()>-1.e-7\nprint("GATED_COHORT_FINISHED","success",bool(variational_result.success),\n    "status",str(variational_result.message),"iterations",len(variational_history),\n    "final_elbo",history_array[-1,1],"max_fixed_point_error",history_array[-1,2],\n    "node_ess",np.quantile(node_ess,[0,.1,.5,.9,1]).tolist(),\n    "half_log_error",np.quantile(np.abs(half_log_error),[0,.5,.9,1]).tolist(),\n    "shared_probability_quantiles",np.quantile(gate_probability[:,1],[0,.1,.5,.9,1]).tolist(),\n    "group_shared_probability",(group_membership@gate_probability[:,1]/external_n).tolist(),flush=True)\nparticle_n=gated_settings["posterior_particles"]\nsample_dimension=paired_dimension+group_max_n*(3*dimension+1)\nuniform=qmc.Sobol(d=sample_dimension,scramble=True,seed=settings["seed"]).random_base2(\n    int(np.ceil(np.log2(group_n*particle_n))))[:group_n*particle_n].reshape(\n        group_n,particle_n,sample_dimension)\nshared_normal=ndtri(uniform[:,:,:paired_dimension])\nrecord_uniform=uniform[:,:,paired_dimension:].reshape(group_n,particle_n,group_max_n,3*dimension+1)\nrecord_uniform=record_uniform[external_group_index,:,local_index]\nrecord_normal=ndtri(record_uniform[:,:,:3*dimension])\nnode_uniform=record_uniform[:,:,-1]\nnp.cumsum(node_probability,axis=-1,out=node_probability)\nselected_flat=torch.searchsorted(torch.as_tensor(node_probability),torch.as_tensor(node_uniform.copy()),\n    right=False).numpy()\nselected_state=selected_flat//node_n\nselected_node=selected_flat%node_n\ndel node_probability,record_uniform,uniform,variational_node\nselected_amplitude=amplitude_grid[selected_node]\nshared_sample=variational_mean[:,None]+np.einsum("gqd,gid->gqi",shared_normal,variational_factor,optimize=True)\ntensor_operators=torch.as_tensor(operators)\nmapped_shared=torch.vmap(lambda state,value:torch.einsum("qij,qj->qi",tensor_operators[state],value),\n    chunk_size=1)(torch.as_tensor(selected_state),\n        torch.as_tensor(shared_sample[external_group_index])).numpy()\nconditional_normal=np.einsum("nqj,hij->nhqi",record_normal[:,:,:paired_dimension],\n    conditional_factor,optimize=True)\nprivate_sample=conditional_normal[np.arange(len(held_rows))[:,None],selected_state,np.arange(particle_n)[None]]\nprior_coordinate=(offset[selected_state]+mapped_shared+private_sample).reshape(\n    len(held_rows),particle_n,2,dimension)\nprior_noise=record_normal[:,:,paired_dimension:]*np.sqrt(noise_eigenvalue)[None,None]\npseudo_observation=np.einsum("nqr,nqrd->nqd",selected_amplitude,prior_coordinate,optimize=True)     +np.sqrt(noise_grid[selected_node])[...,None]*prior_noise\npseudo_residual=held_coordinate[:,None]-pseudo_observation\nunique_node,node_map=np.unique(selected_flat,return_inverse=True)\nselected_inverse=observation_inverse.reshape(2*node_n,dimension,dimension)[unique_node]\ndel observation_inverse,inverse_flat,mapped_shared,conditional_normal,private_sample\ntensor_selected_inverse=torch.as_tensor(selected_inverse)\nprecision_residual=torch.vmap(lambda index,residual:torch.einsum(\n    "qij,qj->qi",tensor_selected_inverse[index],residual),chunk_size=1)(\n        torch.as_tensor(node_map.reshape(selected_flat.shape)),torch.as_tensor(pseudo_residual)).numpy()\nstate_correction=np.einsum("hrisj,nqj,nqs->nhqri",conditional_blocks,\n    precision_residual,selected_amplitude,optimize=True)\ncorrection=state_correction[np.arange(len(held_rows))[:,None],selected_state,np.arange(particle_n)[None]]\nsource_coordinate_sample=prior_coordinate+correction\nsource_samples=np.einsum("nqrd,td->nrqt",source_coordinate_sample,coordinate_basis,optimize=True)[:,None]\nsource_pair_mean=source_samples.mean(axis=3)\ncheck_state=int(selected_state[0,0])\ncheck_node_index=int(selected_node[0,0])\ncheck_calibration=np.concatenate(amplitude_grid[check_node_index,:,None,None]*np.eye(dimension)[None],axis=1)\ncheck_inverse=selected_inverse[np.searchsorted(unique_node,selected_flat[0,0])]\ncheck_source_covariance=conditional_covariance[check_state]\ncheck_gain=check_source_covariance@check_calibration.T@check_inverse\ncheck_residual=np.eye(paired_dimension)-check_gain@check_calibration\ncheck_conditional=check_source_covariance-check_gain@check_calibration@check_source_covariance\ncheck_matheron=check_residual@check_source_covariance@check_residual.T     +noise_grid[check_node_index]*(check_gain*noise_eigenvalue)@check_gain.T\nnp.testing.assert_allclose(check_conditional,check_matheron,rtol=1.e-8,atol=1.e-9)\nprint("GATED_COHORT_SAMPLES","shape",source_samples.shape,\n    "Matheron_covariance_error",float(np.max(np.abs(check_conditional-check_matheron))),flush=True)\ndel selected_inverse,tensor_selected_inverse,prior_coordinate,pseudo_observation,pseudo_residual\ndel precision_residual,correction,state_correction,source_coordinate_sample\nsource_readout=structural_source_readout_stage.split("prior_labels =",1)[0].replace(\n    "waves = np.stack([prediction,mixed[heldout]],axis=1)",\n    "waves = source_samples.reshape(len(held_rows),2*particle_n,length)").replace(\n    "np.repeat(held_mask,2,axis=0)","np.repeat(held_mask,2*particle_n,axis=0)").replace(\n    "np.repeat(held_count,2)","np.repeat(held_count,2*particle_n)")\nexec(compile(source_readout,__file__,"exec"))\nparticle_mass=softmax(log_evidence.reshape(len(held_rows),1,2,particle_n,len(periods))\n    +np.log(grid_weight)[None,None,None,None],axis=-1)\nrole_mass=particle_mass.mean(axis=3)\nprefix_role_mass=np.stack([particle_mass[:,:,:,:particle_n//4].mean(axis=3),\n    particle_mass[:,:,:,:particle_n//2].mean(axis=3),role_mass],axis=1)\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nrole_selected=role_score.argmax(axis=-1)\nrole_estimate=periods[role_selected]\nrole_confidence=np.take_along_axis(role_score,role_selected[...,None],axis=-1)[...,0]\nprefix_role_estimate=periods[(prefix_role_mass@window.T).argmax(axis=-1)]\nprint("GATED_COHORT_PERIOD_INTEGRATION",\n    "half_to_full_target_period_shift",np.quantile(np.abs(\n        prefix_role_estimate[:,1,:,0]-prefix_role_estimate[:,2,:,0]),[0,.5,.9,1],axis=0).tolist(),\n    "half_to_full_target_mass_L1",np.quantile(np.sum(np.abs(\n        prefix_role_mass[:,1,:,0]-prefix_role_mass[:,2,:,0]),axis=-1),[0,.5,.9,1],axis=0).tolist(),flush=True)\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\nmethods=np.asarray(gated_settings["methods"])\npredictions=pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],len(methods)),\n    "method":np.tile(methods,len(held_rows)),"estimate_h":estimate.ravel(),"confidence":confidence.ravel(),\n    "heldout_fold":fold,"heldout_run":np.repeat(run[heldout],len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    source_samples=source_samples,source_pair_mean=source_pair_mean,shared_sample=shared_sample,\n    periods=periods,mass=mass,estimate=estimate,confidence=confidence,methods=methods,\n    role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,\n    particle_mass=particle_mass,calibration_grid=calibration_grid,selected_node=selected_node,\n    selected_state=selected_state,gate_probability=gate_probability,gate_log_prior=gate_log_prior,\n    variational_mean=variational_mean,variational_covariance=variational_covariance,\n    variational_history=history_array,variational_success=variational_result.success,\n    variational_status=str(variational_result.message),node_ess=node_ess,half_log_error=half_log_error,\n    group_names=external_group_names,group_index=external_group_index,\n    prefix_role_estimate=prefix_role_estimate,posterior_particles=particle_n,\n    training_trace_id=trace_id[train],training_groups=training_groups,seed=settings["seed"])\nprint("GATED_COHORT_PREDICTED",flush=True)\nexec(compile(structural_source_readout_stage[\n    structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
exec(compile({True:structural_gated_cohort_predict_stage,False:""}[args.stage=="structural-gated-cohort-predict"],__file__,"exec"))

structural_stationary_cohort_fit_stage = '\nexec(compile(structural_diffusion_source_setup_stage.split("data_sd=",1)[0],__file__,"exec"))\ncohort_settings=application["structural_stationary_cohort_source"]\nparent_stem=application["structural_cohort_source"]["stem"]\nparent_stem=parent_stem.with_name(parent_stem.name+"_common_fold"+str(fold))\nbundle=load(parent_stem.with_suffix(".joblib"))\nassert np.array_equal(bundle["training_trace_id"],trace_id[train])\n\nshared_covariance,private_covariance=bundle["cohort_covariance"]\ncohort_mean=bundle["cohort_mean"]\nold_basis=bundle["coordinate_basis"]\nold_length=len(old_basis)\nold_dimension=old_basis.shape[1]\nraw_operator=np.kron(np.eye(2),old_basis)\ncomponent_covariance=np.stack([shared_covariance+np.outer(cohort_mean,cohort_mean),private_covariance])\nraw_covariance=(raw_operator[None]@component_covariance@raw_operator.T[None]).reshape(\n    2,2,old_length,2,old_length).transpose(0,1,3,2,4)\nlag_index=np.arange(old_length)[:,None]-np.arange(old_length)[None]+old_length-1\nstationary_kernel=np.zeros((2,2,2,2*old_length-1))\nnp.add.at(stationary_kernel,\n    (np.arange(2)[:,None,None,None,None],np.arange(2)[None,:,None,None,None],\n     np.arange(2)[None,None,:,None,None],lag_index[None,None,None]),\n    raw_covariance/old_length)\nnp.testing.assert_allclose(stationary_kernel,stationary_kernel.transpose(0,2,1,3)[...,::-1],atol=1.e-12)\nnew_lag=np.arange(length)[:,None]-np.arange(length)[None]\nlag_padding=max(length-old_length,0)\npadded_kernel=np.pad(stationary_kernel,((0,0),(0,0),(0,0),(lag_padding,lag_padding)))\nraw_new_covariance=padded_kernel[:,:,:,new_lag+max(length,old_length)-1].transpose(\n    0,1,3,2,4).reshape(2,2*length,2*length)\nnew_operator=np.kron(np.eye(2),coordinate_basis)\nlifted_covariance=new_operator.T[None]@raw_new_covariance@new_operator[None]\ntotal_covariance=lifted_covariance.sum(axis=0)\nrole_scale=np.sqrt(length/np.array([np.trace(total_covariance[:dimension,:dimension]),\n    np.trace(total_covariance[dimension:,dimension:])]))\ncoordinate_scale=np.repeat(role_scale,dimension)\nlifted_covariance*=coordinate_scale[None,:,None]*coordinate_scale[None,None,:]\nlifted_mean=np.zeros(2*dimension)\nlifted_factor=np.linalg.cholesky(lifted_covariance)\n\nstem=cohort_settings["stem"].with_name(cohort_settings["stem"].name+"_common_fold"+str(fold))\ndump({**bundle,"parent_model":str(parent_stem.with_suffix(".joblib")),\n    "cohort_mean":lifted_mean,"cohort_covariance":lifted_covariance,"cohort_factor":lifted_factor,\n    "stationary_kernel":stationary_kernel,"stationary_kernel_lag_h":np.arange(\n        -old_length+1,old_length)*np.diff(time)[0],"coordinate_basis":coordinate_basis,\n    "role_scale":role_scale,"settings":dict(cohort_settings)},stem.with_suffix(".joblib"))\nprint("STATIONARY_COHORT_FITTED","length",length,"dimension",dimension,\n    "shared_private_role_trace",np.stack([np.trace(lifted_covariance[:,:dimension,:dimension],axis1=-2,axis2=-1),\n        np.trace(lifted_covariance[:,dimension:,dimension:],axis1=-2,axis2=-1)],axis=-1).tolist(),\n    "minimum_eigenvalues",np.linalg.eigvalsh(lifted_covariance)[:,0].tolist(),flush=True)\nraise SystemExit(0)\n'

structural_stationary_cohort_predict_stage = '\nfrom scipy.special import logsumexp,softmax,ndtri,ndtr\nfrom scipy.optimize import root\nfrom scipy.stats import multivariate_normal\nimport time as system_time\nexec(compile(structural_diffusion_source_setup_stage.split("data_sd=",1)[0],__file__,"exec"))\ncohort_settings=application["structural_stationary_cohort_source"]\nstem=cohort_settings["stem"].with_name(cohort_settings["stem"].name+"_common_fold"+str(fold))\nbundle=load(stem.with_suffix(".joblib"))\nassert np.array_equal(bundle["training_trace_id"],trace_id[train])\nnp.testing.assert_allclose(bundle["coordinate_basis"],coordinate_basis,rtol=1.e-11,atol=1.e-11)\npaired_dimension=2*dimension\ncohort_mean=bundle["cohort_mean"]\nshared_covariance,private_covariance=bundle["cohort_covariance"]\nshared_factor,private_factor=bundle["cohort_factor"]\nmarginal_covariance=shared_covariance+private_covariance\nmarginal_factor=np.linalg.cholesky(marginal_covariance)\nshared_inverse=np.linalg.inv(shared_covariance)\nshared_logdet=np.linalg.slogdet(shared_covariance)[1]\nprior_information=shared_inverse@cohort_mean\nprivate_blocks=private_covariance.reshape(2,dimension,2,dimension)\nshared_blocks=shared_covariance.reshape(2,dimension,2,dimension)\nmarginal_blocks=marginal_covariance.reshape(2,dimension,2,dimension)\nsource_mean_pair=cohort_mean.reshape(2,dimension)\nheld_coordinate=mixed[heldout]@coordinate_basis\nexternal_group_names,external_group_index=np.unique(run[heldout],return_inverse=True)\ngroup_membership=(external_group_names[:,None]==run[heldout][None]).astype(float)\nexternal_n=group_membership.sum(axis=1).astype(int)\ngroup_n=len(external_group_names)\ngroup_max_n=int(external_n.max())\ngroup_row_order=np.argsort(external_group_index,kind="stable")\nlocal_index=np.empty(len(held_rows),dtype=int)\nlocal_index[group_row_order]=np.arange(len(held_rows))-np.repeat(np.r_[0,np.cumsum(external_n)[:-1]],external_n)\npadded_y=np.zeros((group_n,group_max_n,dimension))\npadded_y[external_group_index,local_index]=held_coordinate\nintegration_power=cohort_settings["integration_power"]\ncalibration_uniform=qmc.Sobol(d=3,scramble=True,seed=settings["seed"]).random_base2(integration_power)\nbase_calibration_grid=calibration_mean+(ndtri(calibration_uniform)*np.sqrt(\n    calibration_eigenvalue))@calibration_eigenvector.T\nsign_n=len(active_sign)\ncalibration_grid=np.repeat(base_calibration_grid,sign_n,axis=0)\ngrid_sign=np.tile(sign_values,(len(base_calibration_grid),1))\namplitude_grid=np.exp(calibration_grid[:,:2])*grid_sign\nnoise_grid=np.exp(calibration_grid[:,2])\ngrid_logprior=np.tile(sign_logprior,len(base_calibration_grid))-np.log(len(base_calibration_grid))\ntensor_y=torch.as_tensor(held_coordinate,dtype=torch.float64)\nobservation_covariance=np.einsum("qr,qs,risj->qij",amplitude_grid,amplitude_grid,\n    marginal_blocks,optimize=True)+noise_grid[:,None,None]*np.diag(noise_eigenvalue)[None]\nobservation_factor=np.linalg.cholesky(observation_covariance)\nobservation_inverse=torch.cholesky_inverse(torch.as_tensor(observation_factor)).numpy()\nobservation_mean=amplitude_grid@source_mean_pair\nobservation_precision_mean=np.einsum("qij,qj->qi",observation_inverse,observation_mean,optimize=True)\ntensor_inverse=torch.as_tensor(observation_inverse)\nindependent_log_node=torch.vmap(lambda y:\n    -.5*torch.einsum("i,qij,j->q",y,tensor_inverse,y),chunk_size=1)(tensor_y).numpy()\nindependent_log_node+=held_coordinate@observation_precision_mean.T\nindependent_log_node-=.5*np.sum(observation_mean*observation_precision_mean,axis=-1)[None]\nindependent_log_node-=np.log(np.diagonal(observation_factor,axis1=-2,axis2=-1)).sum(axis=-1)[None]\nindependent_log_node+=grid_logprior[None]-.5*dimension*np.log(2.*np.pi)\ncheck_pdf=multivariate_normal.logpdf(held_coordinate[0],\n    mean=observation_mean[0],cov=observation_covariance[0])\nnp.testing.assert_allclose(independent_log_node[0,0]-grid_logprior[0],check_pdf,atol=1.e-9)\nindependent_node_probability=softmax(independent_log_node,axis=-1)\nindependent_ess=1./np.sum(independent_node_probability**2,axis=-1)\nhalf=len(calibration_grid)//2\nindependent_half_log_error=logsumexp(independent_log_node[:,:half],axis=-1)+np.log(2.)     -logsumexp(independent_log_node,axis=-1)\ndel independent_log_node,observation_inverse,observation_factor,observation_covariance,tensor_inverse\nobservation_covariance=np.einsum("qr,qs,risj->qij",amplitude_grid,amplitude_grid,\n    private_blocks,optimize=True)+noise_grid[:,None,None]*np.diag(noise_eigenvalue)[None]\nobservation_factor=np.linalg.cholesky(observation_covariance)\nobservation_logdet=2.*np.log(np.diagonal(observation_factor,axis1=-2,axis2=-1)).sum(axis=-1)\nobservation_inverse=torch.cholesky_inverse(torch.as_tensor(observation_factor)).numpy()\ntensor_inverse=torch.as_tensor(observation_inverse)\nbase_log_node=torch.vmap(lambda y:\n    -.5*torch.einsum("i,qij,j->q",y,tensor_inverse,y),chunk_size=1)(tensor_y).numpy()\nbase_log_node+=grid_logprior[None]-.5*observation_logdet[None]-.5*dimension*np.log(2.*np.pi)\ndel tensor_inverse,observation_covariance,observation_factor\ninverse_flat=observation_inverse.reshape(len(calibration_grid),-1)\namplitude_products=np.stack([amplitude_grid[:,0]**2,\n    amplitude_grid[:,0]*amplitude_grid[:,1],amplitude_grid[:,1]**2])\nmean_amplitude=np.exp(calibration_mean[:2]+.5*np.diag(calibration_covariance)[:2])     *(np.exp(sign_logprior)@sign_values)\nmean_amplitude_product=np.exp(calibration_mean[:2,None]+calibration_mean[None,:2]\n    +.5*(np.diag(calibration_covariance)[:2,None]+np.diag(calibration_covariance)[None,:2])\n    +calibration_covariance[:2,:2])*((sign_values.T*np.exp(sign_logprior))@sign_values)\nmean_noise=np.exp(calibration_mean[2]+.5*calibration_covariance[2,2])\nexpected_y=mean_amplitude@source_mean_pair\nmarginal_y_covariance=np.einsum("rs,risj->ij",mean_amplitude_product,\n    marginal_blocks+source_mean_pair[:,:,None,None]*source_mean_pair[None,None,:,:],optimize=True)     -np.outer(expected_y,expected_y)+mean_noise*np.diag(noise_eigenvalue)\nshared_y_covariance=np.einsum("r,s,risj->ij",mean_amplitude,mean_amplitude,shared_blocks,optimize=True)\ngroup_y_covariance=shared_y_covariance[None]+(\n    marginal_y_covariance-shared_y_covariance)[None]/external_n[:,None,None]\nsource_y_covariance=np.einsum("risj,s->rij",shared_blocks,mean_amplitude,optimize=True).reshape(paired_dimension,dimension)\ninitial_gain=np.linalg.solve(group_y_covariance,source_y_covariance.T[None]).transpose(0,2,1)\ngroup_y=group_membership@held_coordinate/external_n[:,None]\ninitial_mean=cohort_mean[None]+np.einsum("gij,gj->gi",initial_gain,group_y-expected_y[None],optimize=True)\ninitial_variance=shared_covariance[None]-initial_gain@source_y_covariance.T\ninitial_variance=(initial_variance+initial_variance.transpose(0,2,1))/2.\nassert np.linalg.eigvalsh(initial_variance).min()>0.\ninitial=np.r_[initial_mean.ravel(),initial_variance.ravel()]\nmean_size=group_n*paired_dimension\ncohort_variational_nodes=lambda vector:(\n    mean:=vector[:mean_size].reshape(group_n,2,dimension),\n    variance:=vector[mean_size:].reshape(group_n,2,dimension,2,dimension),\n    mean_wave:=np.einsum("qr,grd->gqd",amplitude_grid,mean,optimize=True),\n    precision_mean:=np.einsum("qij,gqj->gqi",observation_inverse,mean_wave,optimize=True),\n    cross_term:=np.matmul(padded_y,precision_mean.transpose(0,2,1)),\n    variance_blocks:=np.stack([variance[:,0,:,0,:],\n        variance[:,0,:,1,:]+variance[:,1,:,0,:],variance[:,1,:,1,:]],axis=1),\n    variance_term:=(variance_blocks.reshape(group_n*3,-1)@inverse_flat.T).reshape(\n        group_n,3,-1)*amplitude_products[None],\n    node:=base_log_node+cross_term[external_group_index,local_index]\n        -.5*np.sum(mean_wave*precision_mean,axis=-1)[external_group_index]\n        -.5*variance_term.sum(axis=1)[external_group_index],\n    node)[-1]\ncohort_variational_update=lambda node:(\n    probability:=softmax(node,axis=-1),\n    group_probability:=group_membership@probability,\n    precision_blocks:=((group_probability[:,None]*amplitude_products[None]).reshape(\n        group_n*3,-1)@inverse_flat).reshape(group_n,3,dimension,dimension),\n    precision:=shared_inverse[None]+np.concatenate([\n        np.concatenate([precision_blocks[:,0],precision_blocks[:,1]],axis=-1),\n        np.concatenate([precision_blocks[:,1],precision_blocks[:,2]],axis=-1)],axis=-2),\n    variance:=np.linalg.inv(precision),\n    variance:=(variance+variance.transpose(0,2,1))/2.,\n    weighted_y:=np.einsum("gn,nq,ni->gqi",group_membership,probability,held_coordinate,optimize=True),\n    precision_y:=np.einsum("qij,gqj->gqi",observation_inverse,weighted_y,optimize=True),\n    information:=prior_information[None]+np.einsum("qr,gqi->gri",\n        amplitude_grid,precision_y,optimize=True).reshape(group_n,paired_dimension),\n    mean:=np.einsum("gij,gj->gi",variance,information,optimize=True),\n    np.r_[mean.ravel(),variance.ravel()])[-1]\ncohort_variational_elbo=lambda vector,node:(\n    mean:=vector[:mean_size].reshape(group_n,paired_dimension),\n    variance:=vector[mean_size:].reshape(group_n,paired_dimension,paired_dimension),\n    centered:=mean-cohort_mean[None],\n    kl:=.5*(np.einsum("ij,gji->g",shared_inverse,variance,optimize=True)\n        +np.einsum("gi,ij,gj->g",centered,shared_inverse,centered,optimize=True)\n        -paired_dimension+shared_logdet-np.linalg.slogdet(variance)[1]),\n    logsumexp(node,axis=-1).sum()-kl.sum())[-1]\nvariational_history=[]\nstarted=system_time.perf_counter()\ncohort_fixed_point=lambda vector:(\n    node:=cohort_variational_nodes(vector),\n    updated:=cohort_variational_update(node),\n    elbo:=cohort_variational_elbo(vector,node),\n    variational_history.append([len(variational_history),elbo,\n        float(np.max(np.abs(updated-vector))),system_time.perf_counter()-started]),\n    (len(variational_history)==1 or len(variational_history)%25==0)\n        and print("STATIONARY_COHORT_VARIATIONAL_PROGRESS",variational_history[-1],flush=True),\n    updated-vector)[-1]\nprint("STATIONARY_COHORT_PREDICT","records",len(held_rows),"experiments",group_n,\n    "calibration_nodes",len(calibration_grid),"independent_calibration_ess",\n    np.quantile(independent_ess,[0,.1,.5,.9,1]).tolist(),\n    "independent_half_log_error",np.quantile(np.abs(independent_half_log_error),[0,.5,.9,1]).tolist(),flush=True)\ncheck_variational_node=cohort_variational_nodes(initial)\ncheck_operator=np.concatenate(amplitude_grid[0,:,None,None]*np.eye(dimension)[None],axis=1)\ncheck_covariance=check_operator@private_covariance@check_operator.T+noise_grid[0]*np.diag(noise_eigenvalue)\ncheck_variational_expected=multivariate_normal.logpdf(held_coordinate[0],\n    mean=check_operator@initial_mean[external_group_index[0]],cov=check_covariance) \\\n    -.5*np.trace(observation_inverse[0]@check_operator@initial_variance[external_group_index[0]]@check_operator.T) \\\n    +grid_logprior[0]\nnp.testing.assert_allclose(check_variational_node[0,0],check_variational_expected,atol=1.e-9)\nprint("STATIONARY_COHORT_VARIATIONAL_LIKELIHOOD_CHECK","absolute_error",\n    float(abs(check_variational_node[0,0]-check_variational_expected)),flush=True)\ndel check_variational_node\nvariational_result=root(cohort_fixed_point,initial,method="linearmixing",\n    options={"jac_options":{"alpha":1.},"line_search":None,\n        "maxiter":cohort_settings["maxiter"],"fatol":settings["gtol"]})\nvariational_mean=variational_result.x[:mean_size].reshape(group_n,paired_dimension)\nvariational_covariance=variational_result.x[mean_size:].reshape(group_n,paired_dimension,paired_dimension)\nvariational_factor=np.linalg.cholesky(variational_covariance)\nvariational_node=cohort_variational_nodes(variational_result.x)\nvariational_node_probability=softmax(variational_node,axis=-1)\nvariational_ess=1./np.sum(variational_node_probability**2,axis=-1)\nvariational_half_log_error=logsumexp(variational_node[:,:half],axis=-1)+np.log(2.)     -logsumexp(variational_node,axis=-1)\nhistory_array=np.asarray(variational_history)\nassert np.diff(history_array[:,1]).min()>-1.e-7\nprint("STATIONARY_COHORT_VARIATIONAL_FINISHED","success",bool(variational_result.success),\n    "status",str(variational_result.message),"iterations",len(variational_history),\n    "final_elbo",history_array[-1,1],"max_fixed_point_error",history_array[-1,2],\n    "calibration_ess",np.quantile(variational_ess,[0,.1,.5,.9,1]).tolist(),\n    "half_log_error",np.quantile(np.abs(variational_half_log_error),[0,.5,.9,1]).tolist(),flush=True)\nparticle_n=cohort_settings["posterior_particles"]\nsample_dimension=paired_dimension+group_max_n*(3*dimension+1)\nuniform=qmc.Sobol(d=sample_dimension,scramble=True,seed=settings["seed"]).random_base2(\n    int(np.ceil(np.log2(group_n*particle_n))))[:group_n*particle_n].reshape(\n        group_n,particle_n,sample_dimension)\nshared_normal=ndtri(uniform[:,:,:paired_dimension])\nrecord_uniform=uniform[:,:,paired_dimension:].reshape(group_n,particle_n,group_max_n,3*dimension+1)\nrecord_uniform=record_uniform[external_group_index,:,local_index]\nrecord_normal=ndtri(record_uniform[:,:,:3*dimension])\nnode_uniform=record_uniform[:,:,-1]\nnode_probability=np.stack([variational_node_probability,independent_node_probability],axis=1)\nnode_ess=1./np.sum(node_probability**2,axis=-1)\nnode_cumulative=np.cumsum(node_probability,axis=-1)\nselected_node=torch.searchsorted(torch.as_tensor(node_cumulative.reshape(-1,len(calibration_grid))),\n    torch.as_tensor(np.broadcast_to(node_uniform[:,None],(len(held_rows),2,particle_n)).copy().reshape(-1,particle_n)),\n    right=False).numpy().reshape(len(held_rows),2,particle_n)\ndel node_cumulative,node_probability,record_uniform,uniform,variational_node\nselected_amplitude=amplitude_grid[selected_node]\nshared_sample=variational_mean[:,None]+np.einsum("gqd,gid->gqi",shared_normal,variational_factor,optimize=True)\nprivate_sample=record_normal[:,:,:paired_dimension]@private_factor.T\nmarginal_sample=cohort_mean[None,None]+record_normal[:,:,:paired_dimension]@marginal_factor.T\nprior_coordinate=np.stack([shared_sample[external_group_index]+private_sample,marginal_sample],axis=1).reshape(\n    len(held_rows),2,particle_n,2,dimension)\nprior_noise=record_normal[:,:,paired_dimension:]*np.sqrt(noise_eigenvalue)[None,None]\npseudo_observation=np.einsum("nmqr,nmqrd->nmqd",selected_amplitude,prior_coordinate,optimize=True)     +np.sqrt(noise_grid[selected_node])[...,None]*prior_noise[:,None]\npseudo_residual=held_coordinate[:,None,None]-pseudo_observation\nunique_main,node_map=np.unique(selected_node[:,0],return_inverse=True)\nmain_inverse=observation_inverse[unique_main]\ndel observation_inverse,inverse_flat\nmain_precision_residual=torch.vmap(lambda index,residual:torch.einsum(\n    "qij,qj->qi",torch.as_tensor(main_inverse)[index],residual),chunk_size=1)(\n        torch.as_tensor(node_map.reshape(selected_node[:,0].shape)),\n        torch.as_tensor(pseudo_residual[:,0])).numpy()\nunique_individual,individual_map=np.unique(selected_node[:,1],return_inverse=True)\nindividual_covariance=np.einsum("qr,qs,risj->qij",amplitude_grid[unique_individual],amplitude_grid[unique_individual],\n    marginal_blocks,optimize=True)+noise_grid[unique_individual,None,None]*np.diag(noise_eigenvalue)[None]\nindividual_inverse=np.linalg.inv(individual_covariance)\nindividual_precision_residual=torch.vmap(lambda index,residual:torch.einsum(\n    "qij,qj->qi",torch.as_tensor(individual_inverse)[index],residual),chunk_size=1)(\n        torch.as_tensor(individual_map.reshape(selected_node[:,1].shape)),\n        torch.as_tensor(pseudo_residual[:,1])).numpy()\ncorrection=np.stack([np.einsum("risj,nqj,nqs->nqri",private_blocks,\n    main_precision_residual,selected_amplitude[:,0],optimize=True),\n    np.einsum("risj,nqj,nqs->nqri",marginal_blocks,\n    individual_precision_residual,selected_amplitude[:,1],optimize=True)],axis=1)\nsource_coordinate_sample=prior_coordinate+correction\nsource_samples=np.einsum("nmqrd,td->nmrqt",source_coordinate_sample,coordinate_basis,optimize=True)\nposterior_source_mean=source_samples.mean(axis=3)\ncheck_node=int(selected_node[0,0,0])\ncheck_operator=np.concatenate(amplitude_grid[check_node,:,None,None]*np.eye(dimension)[None],axis=1)\ncheck_inverse=main_inverse[np.searchsorted(unique_main,check_node)]\ncheck_gain=private_covariance@check_operator.T@check_inverse\ncheck_residual=np.eye(paired_dimension)-check_gain@check_operator\ncheck_conditional=private_covariance-check_gain@check_operator@private_covariance\ncheck_matheron=check_residual@private_covariance@check_residual.T     +noise_grid[check_node]*(check_gain*noise_eigenvalue)@check_gain.T\nnp.testing.assert_allclose(check_conditional,check_matheron,rtol=1.e-8,atol=1.e-9)\nprint("STATIONARY_COHORT_SOURCE_SAMPLES","shape",source_samples.shape,\n    "Matheron_covariance_error",float(np.max(np.abs(check_conditional-check_matheron))),flush=True)\ndel main_inverse,individual_inverse,individual_covariance,prior_coordinate,pseudo_observation,pseudo_residual\ndel main_precision_residual,individual_precision_residual,correction,source_coordinate_sample\nsource_readout=structural_source_readout_stage.split("prior_labels =",1)[0].replace(\n    "waves = np.stack([prediction,mixed[heldout]],axis=1)",\n    "waves = source_samples.reshape(len(held_rows),4*particle_n,length)").replace(\n    "np.repeat(held_mask,2,axis=0)","np.repeat(held_mask,4*particle_n,axis=0)").replace(\n    "np.repeat(held_count,2)","np.repeat(held_count,4*particle_n)")\nexec(compile(source_readout,__file__,"exec"))\nparticle_mass=softmax(log_evidence.reshape(len(held_rows),2,2,particle_n,len(periods))\n    +np.log(grid_weight)[None,None,None,None],axis=-1)\nposterior_role_mass=particle_mass.mean(axis=3)\nprefix_role_mass=np.stack([particle_mass[:,:,:,:particle_n//4].mean(axis=3),\n    particle_mass[:,:,:,:particle_n//2].mean(axis=3),posterior_role_mass],axis=1)\nprior_uniform=qmc.Sobol(d=paired_dimension,scramble=True,seed=settings["seed"]).random_base2(\n    cohort_settings["prior_power"])\nprior_source_coordinate=(cohort_mean[None]+ndtri(prior_uniform)@marginal_factor.T).reshape(-1,2,dimension)\nprior_wave=prior_source_coordinate@coordinate_basis.T\nprior_n=len(prior_uniform)\nprior_readout=structural_source_readout_stage.split("prior_labels =",1)[0].replace(\n    "waves = np.stack([prediction,mixed[heldout]],axis=1)",\n    "waves = prior_wave.transpose(1,0,2).reshape(1,2*prior_n,length)").replace(\n    "held_mask = mask[heldout]","held_mask = np.ones((1,length),dtype=bool)").replace(\n    "held_count = count[heldout]","held_count = np.array([length])").replace(\n    "np.repeat(held_mask,2,axis=0)","np.repeat(held_mask,2*prior_n,axis=0)").replace(\n    "np.repeat(held_count,2)","np.repeat(held_count,2*prior_n)")\nexec(compile(prior_readout,__file__,"exec"))\nprior_particle_mass=softmax(log_evidence.reshape(2,prior_n,len(periods))\n    +np.log(grid_weight)[None,None],axis=-1)\nprior_role_mass=prior_particle_mass.mean(axis=1)\nrole_mass=np.concatenate([posterior_role_mass,\n    np.broadcast_to(prior_role_mass,(len(held_rows),1,2,len(periods)))],axis=1)\nsource_pair_mean=np.concatenate([posterior_source_mean,\n    np.broadcast_to(prior_wave.mean(axis=0),(len(held_rows),1,2,length))],axis=1)\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nrole_selected=role_score.argmax(axis=-1)\nrole_estimate=periods[role_selected]\nrole_confidence=np.take_along_axis(role_score,role_selected[...,None],axis=-1)[...,0]\nprefix_role_estimate=periods[(prefix_role_mass@window.T).argmax(axis=-1)]\nprior_half_mass=prior_particle_mass[:,:prior_n//2].mean(axis=1)\nprior_half_estimate=periods[(prior_half_mass@window.T).argmax(axis=-1)]\nprint("STATIONARY_COHORT_PERIOD_INTEGRATION",\n    "half_to_full_target_period_shift",np.quantile(np.abs(\n        prefix_role_estimate[:,1,:,0]-prefix_role_estimate[:,2,:,0]),[0,.5,.9,1],axis=0).tolist(),\n    "half_to_full_target_mass_L1",np.quantile(np.sum(np.abs(\n        prefix_role_mass[:,1,:,0]-prefix_role_mass[:,2,:,0]),axis=-1),[0,.5,.9,1],axis=0).tolist(),\n    "prior_half_to_full_period_shift",(prior_half_estimate-role_estimate[0,-1]).tolist(),flush=True)\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\nmethods=np.asarray(cohort_settings["methods"])\npredictions=pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],len(methods)),\n    "method":np.tile(methods,len(held_rows)),"estimate_h":estimate.ravel(),"confidence":confidence.ravel(),\n    "heldout_fold":fold,"heldout_run":np.repeat(run[heldout],len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    source_samples=source_samples,source_pair_mean=source_pair_mean,shared_sample=shared_sample,\n    periods=periods,mass=mass,estimate=estimate,confidence=confidence,methods=methods,\n    role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,\n    particle_mass=particle_mass,calibration_grid=calibration_grid,selected_node=selected_node,\n    variational_mean=variational_mean,variational_covariance=variational_covariance,\n    variational_history=history_array,variational_success=variational_result.success,\n    variational_status=str(variational_result.message),node_ess=node_ess,\n    variational_half_log_error=variational_half_log_error,\n    independent_half_log_error=independent_half_log_error,\n    group_names=external_group_names,group_index=external_group_index,\n    prior_wave=prior_wave,prior_particle_mass=prior_particle_mass,\n    prefix_role_estimate=prefix_role_estimate,posterior_particles=particle_n,\n    training_trace_id=trace_id[train],training_groups=training_groups,seed=settings["seed"])\nprint("STATIONARY_COHORT_SOURCE_PREDICTED",flush=True)\nexec(compile(structural_source_readout_stage[\n    structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
