exec(compile({True:structural_cohort_native_predict_stage,False:""}[args.stage=="structural-cohort-native-predict"],__file__,"exec"))

structural_cohort_oracle_alignment_stage = '\nfrom joblib import load\nfold=args.heldout_run\ncohort_settings=application["structural_cohort_source"]\nstem=cohort_settings["stem"].with_name(cohort_settings["stem"].name+"_native_fold"+str(fold))\nbank=np.load(stem.with_suffix(".npz"))\nparent=load(cohort_settings["stem"].with_name(\n    cohort_settings["stem"].name+"_common_fold"+str(fold)).with_suffix(".joblib"))\nids=bank["trace_id"]\nrecord_n=len(ids)\npositions=bank["window_index"]\nwindow_n,length=positions.shape\ncoordinate_basis=parent["coordinate_basis"]\ndimension=coordinate_basis.shape[1]\npaired_dimension=2*dimension\ntime=bank["window_time"]\ncentered_time=time-time.mean()\nbase=np.stack([np.ones(length)/np.sqrt(length),centered_time/np.linalg.norm(centered_time)],axis=-1)\noptical=pd.read_parquet(application["paths"]["lemna_dual_observations"],\n    columns=["trace_id","time_h","published_target_y","green","red"],filters=[("trace_id","in",ids.tolist())])\noptical["background"]=optical.green*application["background_templates"]["optical_coefficients"][0]     +optical.red*application["background_templates"]["optical_coefficients"][1]\ntarget=optical.pivot(index="trace_id",columns="time_h",values="published_target_y").reindex(ids).to_numpy()[:,positions]\nbackground=optical.pivot(index="trace_id",columns="time_h",values="background").reindex(ids).to_numpy()[:,positions]\ntrue_source=np.stack([target,background],axis=2).reshape(record_n*window_n,2,length)\ntrue_source-=(true_source@base)@base.T\ntrue_unit=true_source/np.sqrt(np.mean(true_source**2,axis=-1))[...,None]\ntrue_coordinate=(true_unit@coordinate_basis).reshape(record_n,window_n,paired_dimension)\ntrue_group_mean=true_coordinate.mean(axis=0)\ntrue_deviation=true_coordinate-true_group_mean[None]\ntrue_private=np.einsum("ngi,ngj->gij",true_deviation,true_deviation)/(record_n-1)\nshared_covariance,private_covariance=parent["cohort_covariance"]\nshared_inverse=np.linalg.inv(shared_covariance)\nprivate=np.stack([np.broadcast_to(private_covariance,true_private.shape),true_private])\nraw=bank["raw_waveform"][:,positions].reshape(record_n*window_n,length)\nraw-=(raw@base)@base.T\nraw/=np.sqrt(np.mean(raw**2,axis=-1))[:,None]\ngain=np.linalg.solve(np.einsum("nrt,nst->nrs",true_unit,true_unit),\n    np.einsum("nrt,nt->nr",true_unit,raw)[...,None])[...,0]\nnoise_variance=np.mean((raw-np.einsum("nr,nrt->nt",gain,true_unit))**2,axis=-1)\noperator=(gain[:,:,None,None]*np.eye(dimension)[None,None]).transpose(0,2,1,3).reshape(\n    len(raw),dimension,paired_dimension)\nnp.testing.assert_allclose(operator[0]@true_coordinate.reshape(-1,paired_dimension)[0],\n    (np.einsum("r,rt->t",gain[0],true_unit[0])@coordinate_basis),atol=1.e-12)\ngroup_index=np.tile(np.arange(window_n),record_n)\nmembership=(np.arange(window_n)[:,None]==group_index[None]).astype(float)\ny=raw@coordinate_basis\nprivate_rows=private[:,group_index]\nobservation_covariance=operator[None]@private_rows@operator.transpose(0,2,1)[None]     +noise_variance[None,:,None,None]*np.diag(parent["noise_eigenvalue"])[None,None]\nobservation_inverse=np.linalg.inv(observation_covariance)\ninformation_operator=operator.transpose(0,2,1)[None]@observation_inverse\nprecision_increment=information_operator@operator[None]\nprecision=shared_inverse[None,None]+np.einsum("gn,mnij->mgij",membership,precision_increment)\ninformation=(shared_inverse@parent["cohort_mean"])[None,None]     +np.einsum("gn,mnij,nj->mgi",membership,information_operator,y)\nshared_posterior_covariance=np.linalg.inv(precision)\nshared_mean=np.einsum("mgij,mgj->mgi",shared_posterior_covariance,information)\nsource_gain=private_rows@information_operator\nremainder=y[None]-np.einsum("nij,mnj->mni",operator,shared_mean[:,group_index])\nsource_mean=shared_mean[:,group_index]+np.einsum("mnij,mnj->mni",source_gain,remainder)\nsource_wave=source_mean.reshape(2,len(raw),2,dimension)@coordinate_basis.T\nwave=np.concatenate([bank["window_source_pair_mean"][:,0][None],source_wave])\nrms=np.sqrt(np.mean(wave**2,axis=-1))\ncross=np.einsum("mnrt,nst->mnrs",wave,true_unit)/(length*rms[:,:,:,None])\nmethods=np.array(["variational_unknown_calibration","oracle_calibration_global_private",\n    "oracle_calibration_and_private_covariance"])\ntable=pd.DataFrame({"method":np.repeat(methods,len(raw)),"trace_id":np.tile(np.repeat(ids,window_n),len(methods)),\n    "window_start_h":np.tile(np.tile(bank["time"][positions[:,0]],record_n),len(methods)),\n    "target_true_target_correlation":cross[:,:,0,0].ravel(),\n    "target_true_background_correlation":cross[:,:,0,1].ravel(),\n    "background_true_background_correlation":cross[:,:,1,1].ravel(),\n    "target_posterior_mean_rms":rms[:,:,0].ravel(),"background_posterior_mean_rms":rms[:,:,1].ravel(),\n    "diagnostic_scope":"optical_truth_oracle_for_failure_localization_only"})\ntable.to_csv(str(stem)+"_source_alignment_diagnostic.csv",index=False,encoding="utf-8",lineterminator="\\n")\nprint("COHORT_ORACLE_ALIGNMENT",table.groupby(["method","window_start_h"])[[\n    "target_true_target_correlation","target_true_background_correlation",\n    "background_true_background_correlation","target_posterior_mean_rms",\n    "background_posterior_mean_rms"]].median().to_string(),flush=True)\nraise SystemExit(0)\n'
exec(compile({True:structural_cohort_oracle_alignment_stage,False:""}[args.stage=="structural-cohort-oracle-diagnose"],__file__,"exec"))

structural_unit_cohort_setup_stage = '\nfrom scipy.optimize import minimize\nfrom scipy.special import softmax\nfrom joblib import load,dump\nimport time as system_time\nnative_query=args.heldout_run<application["lemna_expected_runs"]\nparent_prefix={True:structural_cohort_native_predict_stage.split("paired_dimension=2*dimension",1)[0],\n    False:structural_cohort_source_predict_stage.split("paired_dimension=2*dimension",1)[0]}[native_query]\nexec(compile(parent_prefix,__file__,"exec"))\nunit_settings=application["structural_unit_cohort_source"]\nparent_stem=stem\nparent_prior_stem=application["structural_cohort_source"]["stem"]\nparent_prior_stem=parent_prior_stem.with_name(parent_prior_stem.name+"_common_fold"+str(fold))\nparent_bank=np.load(parent_stem.with_suffix(".npz"))\nparent_ids=parent_bank[{True:"window_trace_id",False:"trace_id"}[native_query]]\nassert np.array_equal(parent_ids,trace_id[heldout])\nparent_samples=parent_bank[{True:"window_source_samples",False:"source_samples"}[native_query]]\nstem=unit_settings["stem"].with_name(unit_settings["stem"].name+\n    {True:"_native_fold",False:"_common_fold"}[native_query]+str(fold))\ncohort_settings=unit_settings\npaired_dimension=2*dimension\nmethod_n=len(unit_settings["methods"])\nrecord_n=len(held_rows)\nparticle_n=unit_settings["posterior_particles"]\ngroup_names,group_index=np.unique(run[heldout],return_inverse=True)\ngroup_n=len(group_names)\ngroup_count=np.bincount(group_index)\ngroup_max_n=int(group_count.max())\ngroup_order=np.argsort(group_index,kind="stable")\nlocal_index=np.empty(record_n,dtype=int)\nlocal_index[group_order]=np.arange(record_n)-np.repeat(np.r_[0,np.cumsum(group_count)[:-1]],group_count)\nnp.testing.assert_array_equal(group_index,parent_bank["group_index"])\ncohort_mean=bundle["cohort_mean"]\nshared_covariance,private_covariance=bundle["cohort_covariance"]\nshared_factor,private_factor=bundle["cohort_factor"]\nmarginal_covariance=shared_covariance+private_covariance\nmarginal_factor=np.linalg.cholesky(marginal_covariance)\nprivate_factors=np.stack([private_factor,marginal_factor])\nprivate_inverse=np.linalg.inv(private_factors)\nshared_inverse_factor=np.linalg.inv(shared_factor)\ncalibration_factor=np.linalg.cholesky(calibration_covariance)\ncalibration_inverse_factor=np.linalg.inv(calibration_factor)\nparent_coordinate=(parent_samples.transpose(1,0,3,2,4)@coordinate_basis).reshape(\n    method_n,record_n,parent_samples.shape[3],paired_dimension)\nparent_private=parent_coordinate.copy()\nparent_private[0]-=parent_bank["shared_sample"][group_index]\nparent_private[1]-=cohort_mean[None,None]\nwhite_private=np.einsum("mij,mnqj->mnqi",private_inverse,parent_private,optimize=True)\ninitial_private_mean=white_private.mean(axis=2)\ninitial_private_log_sd=np.log(white_private.std(axis=2))\ninitial_shared_mean=(parent_bank["variational_mean"]-cohort_mean[None])@shared_inverse_factor.T\ninitial_shared_covariance=shared_inverse_factor[None]@parent_bank["variational_covariance"]@shared_inverse_factor.T[None]\ninitial_shared_covariance=(initial_shared_covariance+initial_shared_covariance.transpose(0,2,1))/2.\ninitial_shared_factor=np.linalg.cholesky(initial_shared_covariance)\nparent_log_calibration=parent_bank["calibration_grid"][parent_bank["selected_node"]].transpose(1,0,2,3).copy()\nparent_rms=np.sqrt(np.mean(parent_samples**2,axis=-1)).transpose(1,0,3,2)\nparent_log_calibration[:,:,:,:2]+=np.log(parent_rms)\nwhite_calibration=(parent_log_calibration-calibration_mean)@calibration_inverse_factor.T\ninitial_calibration_mean=white_calibration.mean(axis=2)\ncalibration_centered_sample=white_calibration-initial_calibration_mean[:,:,None]\nparent_particle_n=parent_samples.shape[3]\n# One prior moment regularizes only the finite-sample initialization.\ninitial_calibration_covariance=(np.einsum("mnqi,mnqj->mnij",\n    calibration_centered_sample,calibration_centered_sample)+np.eye(3)[None,None])/(parent_particle_n+1.)\ninitial_calibration_factor=np.linalg.cholesky(initial_calibration_covariance)\nsign_n=len(active_sign)\nparent_sign=parent_bank["selected_node"].transpose(1,0,2)%sign_n\ninitial_sign_probability=((parent_sign[...,None]==np.arange(sign_n)).sum(axis=2)\n    +np.exp(sign_logprior)[None,None])/(parent_particle_n+1.)\ninitial_sign_free=np.log(initial_sign_probability[:,:,:-1]/initial_sign_probability[:,:,-1:])\nshared_row,shared_column=np.tril_indices(paired_dimension)\nshared_diagonal=shared_row==shared_column\ninitial_shared_packed=initial_shared_factor[:,shared_row,shared_column].copy()\ninitial_shared_packed[:,shared_diagonal]=np.log(initial_shared_packed[:,shared_diagonal])\ncalibration_row,calibration_column=np.tril_indices(3)\ncalibration_diagonal=calibration_row==calibration_column\ninitial_calibration_packed=initial_calibration_factor[:,:,calibration_row,calibration_column].copy()\ninitial_calibration_packed[:,:,calibration_diagonal]=np.log(initial_calibration_packed[:,:,calibration_diagonal])\nparameter_sizes=np.array([initial_shared_mean.size,initial_shared_packed.size,\n    initial_private_mean.size,initial_private_log_sd.size,initial_calibration_mean.size,\n    initial_calibration_packed.size,initial_sign_free.size])\nparameter_edges=np.r_[0,np.cumsum(parameter_sizes)]\ninitial=np.r_[initial_shared_mean.ravel(),initial_shared_packed.ravel(),\n    initial_private_mean.ravel(),initial_private_log_sd.ravel(),initial_calibration_mean.ravel(),\n    initial_calibration_packed.ravel(),initial_sign_free.ravel()]\nsample_dimension=paired_dimension+group_max_n*(paired_dimension+3)\nsampler=qmc.Sobol(d=sample_dimension,scramble=True,seed=settings["seed"])\nuniform=sampler.random_base2(int(np.ceil(np.log2(group_n*2*particle_n))))[\n    :group_n*2*particle_n].reshape(group_n,2*particle_n,sample_dimension)\nuniform[uniform==0.]=np.ldexp(.5,-sampler.bits)\nshared_normal=ndtri(uniform[:,:,:paired_dimension])\nrecord_uniform=uniform[:,:,paired_dimension:].reshape(\n    group_n,2*particle_n,group_max_n,paired_dimension+3)\nrecord_normal=ndtri(record_uniform[group_index,:,local_index])\nprivate_normal=record_normal[:,:,:paired_dimension]\ncalibration_normal=record_normal[:,:,paired_dimension:]\ndel uniform,record_uniform,record_normal,parent_coordinate,parent_private,white_private\ntensor_shared_normal=torch.as_tensor(shared_normal,dtype=torch.float64)\ntensor_private_normal=torch.as_tensor(private_normal,dtype=torch.float64)\ntensor_calibration_normal=torch.as_tensor(calibration_normal,dtype=torch.float64)\ntensor_group_index=torch.as_tensor(group_index)\ntensor_shared_factor=torch.as_tensor(shared_factor,dtype=torch.float64)\ntensor_private_factors=torch.as_tensor(private_factors,dtype=torch.float64)\ntensor_calibration_factor=torch.as_tensor(calibration_factor,dtype=torch.float64)\ntensor_cohort_mean=torch.as_tensor(cohort_mean,dtype=torch.float64)\ntensor_calibration_mean=torch.as_tensor(calibration_mean,dtype=torch.float64)\ntensor_sign_values=torch.as_tensor(sign_values,dtype=torch.float64)\ntensor_sign_logprior=torch.as_tensor(sign_logprior,dtype=torch.float64)\ntensor_noise_scale=torch.sqrt(torch.as_tensor(noise_eigenvalue,dtype=torch.float64))\ntensor_y=torch.as_tensor(mixed[heldout]@coordinate_basis,dtype=torch.float64)/tensor_noise_scale[None]\ntensor_y_energy=(tensor_y**2).sum(dim=-1)\ntensor_shared_group=torch.arange(group_n)[:,None]\ntensor_shared_row=torch.as_tensor(shared_row)[None]\ntensor_shared_column=torch.as_tensor(shared_column)[None]\ntensor_shared_diagonal=torch.as_tensor(shared_diagonal)[None]\ntensor_cal_method=torch.arange(method_n)[:,None,None]\ntensor_cal_record=torch.arange(record_n)[None,:,None]\ntensor_cal_row=torch.as_tensor(calibration_row)[None,None]\ntensor_cal_column=torch.as_tensor(calibration_column)[None,None]\ntensor_cal_diagonal=torch.as_tensor(calibration_diagonal)[None,None]\ntensor_shared_indicator=torch.as_tensor([1.,0.],dtype=torch.float64)[:,None,None,None]\nunit_decode=lambda vector:(\n    bm:=vector[parameter_edges[0]:parameter_edges[1]].reshape(group_n,paired_dimension),\n    bp:=vector[parameter_edges[1]:parameter_edges[2]].reshape(group_n,-1),\n    bv:=torch.where(tensor_shared_diagonal,bp.exp(),bp),\n    bf:=torch.zeros((group_n,paired_dimension,paired_dimension),dtype=vector.dtype).index_put(\n        (tensor_shared_group,tensor_shared_row,tensor_shared_column),bv),\n    em:=vector[parameter_edges[2]:parameter_edges[3]].reshape(method_n,record_n,paired_dimension),\n    es:=vector[parameter_edges[3]:parameter_edges[4]].reshape(method_n,record_n,paired_dimension),\n    cm:=vector[parameter_edges[4]:parameter_edges[5]].reshape(method_n,record_n,3),\n    cp:=vector[parameter_edges[5]:parameter_edges[6]].reshape(method_n,record_n,-1),\n    cv:=torch.where(tensor_cal_diagonal,cp.exp(),cp),\n    cf:=torch.zeros((method_n,record_n,3,3),dtype=vector.dtype).index_put(\n        (tensor_cal_method,tensor_cal_record,tensor_cal_row,tensor_cal_column),cv),\n    sf:=vector[parameter_edges[6]:parameter_edges[7]].reshape(method_n,record_n,sign_n-1),\n    sl:=torch.log_softmax(torch.cat([sf,torch.zeros((method_n,record_n,1),dtype=vector.dtype)],dim=-1),dim=-1),\n    (bm,bf,em,es,cm,cf,sl))[-1]\nunit_terms=lambda vector,shared_epsilon,private_epsilon,calibration_epsilon:(\n    decoded:=unit_decode(vector),\n    bm:=decoded[0],bf:=decoded[1],em:=decoded[2],es:=decoded[3],\n    cm:=decoded[4],cf:=decoded[5],sl:=decoded[6],\n    shared_white:=bm[:,None]+torch.einsum("gqj,gij->gqi",shared_epsilon,bf),\n    shared_coordinate:=tensor_cohort_mean[None,None]+shared_white@tensor_shared_factor.T,\n    private_white:=em[:,:,None]+private_epsilon[None]*es.exp()[:,:,None],\n    private_coordinate:=torch.einsum("mnqj,mij->mnqi",private_white,tensor_private_factors),\n    coordinate:=tensor_cohort_mean[None,None,None]+private_coordinate+\n        tensor_shared_indicator*(shared_coordinate[tensor_group_index][None]-tensor_cohort_mean[None,None,None]),\n    paired_coordinate:=coordinate.reshape(method_n,record_n,-1,2,dimension),\n    source_rms:=torch.sqrt((paired_coordinate**2).sum(dim=-1)/length),\n    source_unit:=paired_coordinate/source_rms[...,None],\n    calibration_white:=cm[:,:,None]+torch.einsum("nqj,mnij->mnqi",calibration_epsilon,cf),\n    calibration:=tensor_calibration_mean[None,None,None]+calibration_white@tensor_calibration_factor.T,\n    amplitude:=calibration[:,:,:,:2].exp(),\n    sign_probability:=sl.exp(),\n    sign_mean:=sign_probability@tensor_sign_values,\n    sign_cross:=sign_probability@(tensor_sign_values[:,0]*tensor_sign_values[:,1]),\n    source_white:=source_unit/tensor_noise_scale[None,None,None,None],\n    observation_mean:=torch.einsum("mnqr,mnr,mnqrd->mnqd",amplitude,sign_mean,source_white),\n    observation_energy:=torch.sum(amplitude**2*torch.sum(source_white**2,dim=-1),dim=-1)\n        +2.*amplitude[:,:,:,0]*amplitude[:,:,:,1]*sign_cross[:,:,None]\n        *torch.sum(source_white[:,:,:,0]*source_white[:,:,:,1],dim=-1),\n    residual_energy:=tensor_y_energy[None,:,None]-2.*torch.einsum(\n        "nd,mnqd->mnq",tensor_y,observation_mean)+observation_energy,\n    likelihood:=.5*(dimension*(np.log(2.*np.pi)+calibration[:,:,:,2])\n        +np.log(noise_eigenvalue).sum()+(-calibration[:,:,:,2]).exp()*residual_energy),\n    kb:=.5*((bf**2).sum(dim=(-2,-1))+(bm**2).sum(dim=-1)-paired_dimension\n        -2.*torch.diagonal(bf,dim1=-2,dim2=-1).log().sum(dim=-1)),\n    ke:=.5*((2.*es).exp()+em**2-1.-2.*es).sum(dim=-1),\n    kc:=.5*((cf**2).sum(dim=(-2,-1))+(cm**2).sum(dim=-1)-3.\n        -2.*torch.diagonal(cf,dim1=-2,dim2=-1).log().sum(dim=-1)),\n    ks:=(sign_probability*(sl-tensor_sign_logprior[None,None])).sum(dim=-1),\n    (likelihood.mean(dim=-1),kb,ke,kc,ks,source_unit,calibration,sign_probability,shared_coordinate))[-1]\nunit_objective=lambda vector:(\n    values:=unit_terms(vector,tensor_shared_normal[:,:particle_n],\n        tensor_private_normal[:,:particle_n],tensor_calibration_normal[:,:particle_n]),\n    (values[0].sum()+values[1].sum()+values[2].sum()+values[3].sum()+values[4].sum())\n        /(method_n*record_n*dimension))[-1]\nunit_autograd=torch.func.grad_and_value(unit_objective)\nunit_to_scipy=lambda gradient,value:(value.detach().item(),gradient.detach().numpy())\nunit_scipy_objective=lambda vector:unit_to_scipy(*unit_autograd(torch.as_tensor(vector,dtype=torch.float64)))\nprint("UNIT_COHORT_SETUP","fold",fold,"native",native_query,"window_records",record_n,\n    "cohorts",group_n,"parameters",len(initial),"integration_particles",particle_n,flush=True)\n'

structural_unit_cohort_fit_stage = '\ninitial_loss,initial_gradient=unit_scipy_objective(initial)\nassert np.isfinite(initial_loss) and np.isfinite(initial_gradient).all()\nloss_history=[[0,initial_loss,0.]]\nstarted=system_time.perf_counter()\nprint("UNIT_COHORT_OPTIMIZE","initial_loss",initial_loss,"max_gradient",\n    float(np.max(np.abs(initial_gradient))),flush=True)\nunit_result=minimize(unit_scipy_objective,initial,jac=True,method="L-BFGS-B",\n    callback=lambda intermediate_result:(loss_history.append(\n        [len(loss_history),float(intermediate_result.fun),system_time.perf_counter()-started]),\n        len(loss_history)%25==0 and print("UNIT_COHORT_PROGRESS",loss_history[-1],flush=True)),\n    options={"maxiter":unit_settings["maxiter"],"ftol":unit_settings["ftol"],\n        "gtol":settings["gtol"],"maxls":settings["maxls"]})\nwith torch.no_grad():\n    training_terms=unit_terms(torch.as_tensor(unit_result.x,dtype=torch.float64),\n        tensor_shared_normal[:,:particle_n],tensor_private_normal[:,:particle_n],\n        tensor_calibration_normal[:,:particle_n])\n    validation_terms=unit_terms(torch.as_tensor(unit_result.x,dtype=torch.float64),\n        tensor_shared_normal[:,particle_n:],tensor_private_normal[:,particle_n:],\n        tensor_calibration_normal[:,particle_n:])\ntraining_loss=(training_terms[0].sum()+training_terms[1].sum()+training_terms[2].sum()\n    +training_terms[3].sum()+training_terms[4].sum()).item()/(method_n*record_n*dimension)\nvalidation_loss=(validation_terms[0].sum()+validation_terms[1].sum()+validation_terms[2].sum()\n    +validation_terms[3].sum()+validation_terms[4].sum()).item()/(method_n*record_n*dimension)\nprint("UNIT_COHORT_OPTIMIZED","success",bool(unit_result.success),"iterations",unit_result.nit,\n    "status",str(unit_result.message),"max_gradient",float(np.max(np.abs(unit_result.jac))),\n    "training_loss",training_loss,"validation_loss",validation_loss,\n    "integration_gap",validation_loss-training_loss,flush=True)\nsource_samples=(validation_terms[5].numpy()@coordinate_basis.T).transpose(1,0,3,2,4)\nnp.testing.assert_allclose(np.mean(source_samples**2,axis=-1),1.,rtol=1.e-10,atol=1.e-10)\nposterior_source_mean=source_samples.mean(axis=3)\nposterior_calibration=validation_terms[6].numpy().transpose(1,0,2,3)\nposterior_sign_probability=validation_terms[7].numpy().transpose(1,0,2)\nshared_sample=validation_terms[8].numpy()\nprint("UNIT_COHORT_SOURCE_SAMPLES","shape",source_samples.shape,"maximum_RMS_error",\n    float(np.max(np.abs(np.sqrt(np.mean(source_samples**2,axis=-1))-1.))),flush=True)\ndump({"variational_parameters":unit_result.x,"parameter_sizes":parameter_sizes,\n    "parent_prior":str(parent_prior_stem.with_suffix(".joblib")),\n    "parent_prediction":str(parent_stem.with_suffix(".npz")),\n    "native":native_query,"heldout_fold":fold,"training_trace_id":trace_id[train],\n    "training_groups":training_groups,"seed":settings["seed"],"settings":dict(unit_settings),\n    "optimization_success":bool(unit_result.success),"optimization_status":str(unit_result.message),\n    "max_gradient":float(np.max(np.abs(unit_result.jac))),"loss_history":loss_history,\n    "training_loss":training_loss,"validation_loss":validation_loss,"heldout_optical_read":False},\n    stem.with_suffix(".joblib"))\ndel training_terms,validation_terms\nsource_readout=structural_source_readout_stage.split("prior_labels =",1)[0].replace(\n    "waves = np.stack([prediction,mixed[heldout]],axis=1)",\n    "waves = source_samples.reshape(len(held_rows),method_n*2*particle_n,length)").replace(\n    "np.repeat(held_mask,2,axis=0)","np.repeat(held_mask,method_n*2*particle_n,axis=0)").replace(\n    "np.repeat(held_count,2)","np.repeat(held_count,method_n*2*particle_n)")\nexec(compile(source_readout,__file__,"exec"))\nparticle_mass=softmax(log_evidence.reshape(record_n,method_n,2,particle_n,len(periods))\n    +np.log(grid_weight)[None,None,None,None],axis=-1)\nwindow_role_mass=particle_mass.mean(axis=3)\nwindow_prefix_role_mass=np.stack([particle_mass[:,:,:,:particle_n//4].mean(axis=3),\n    particle_mass[:,:,:,:particle_n//2].mean(axis=3),window_role_mass],axis=1)\nrole_mass=window_role_mass.copy()\nprefix_role_mass=window_prefix_role_mass.copy()\nprediction_ids=trace_id[heldout]\nprediction_runs=run[heldout]\nprediction_time=time\nprediction_mask=mask[heldout]\nsource_window_index=np.arange(length)[None]\nnative_aggregate_code="""\nrole_mass=role_mass.reshape(len(native_id),native_window_n,method_n,2,len(periods)).mean(axis=1)\nprefix_role_mass=prefix_role_mass.reshape(len(native_id),native_window_n,\n    3,method_n,2,len(periods)).mean(axis=1)\nprediction_ids=native_id\nprediction_runs=native_run\nprediction_time=native_time\nprediction_mask=np.ones(native_signal.shape,dtype=bool)\nsource_window_index=native_window_index\n"""\nexec(compile({True:native_aggregate_code,False:""}[native_query],__file__,"exec"))\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nrole_estimate=periods[role_score.argmax(axis=-1)]\nrole_confidence=role_score.max(axis=-1)\nprefix_role_estimate=periods[(prefix_role_mass@window.T).argmax(axis=-1)]\nprint("UNIT_COHORT_PERIOD_INTEGRATION","half_to_full_target_period_shift",\n    np.quantile(np.abs(prefix_role_estimate[:,1,:,0]-prefix_role_estimate[:,2,:,0]),\n        [0,.5,.9,1],axis=0).tolist(),flush=True)\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\nmethods=np.asarray(unit_settings["methods"])\npredictions=pd.DataFrame({"trace_id":np.repeat(prediction_ids,len(methods)),\n    "method":np.tile(methods,len(prediction_ids)),"estimate_h":estimate.ravel(),"confidence":confidence.ravel(),\n    "heldout_fold":fold,"heldout_run":np.repeat(prediction_runs,len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=prediction_ids,time=prediction_time,mask=prediction_mask,\n    window_trace_id=trace_id[heldout],source_window_time=time,source_window_index=source_window_index,\n    source_samples=source_samples,source_pair_mean=posterior_source_mean,shared_sample=shared_sample,\n    periods=periods,mass=mass,estimate=estimate,confidence=confidence,methods=methods,\n    role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,\n    particle_mass=particle_mass,window_role_mass=window_role_mass,\n    posterior_calibration=posterior_calibration,posterior_sign_probability=posterior_sign_probability,\n    prefix_role_estimate=prefix_role_estimate,posterior_particles=particle_n,\n    group_names=group_names,group_index=group_index,training_trace_id=trace_id[train],\n    training_groups=training_groups,seed=settings["seed"],optimization_success=unit_result.success,\n    optimization_status=str(unit_result.message),training_loss=training_loss,validation_loss=validation_loss,\n    max_gradient=np.max(np.abs(unit_result.jac)))\nprint("UNIT_COHORT_SOURCE_PREDICTED",flush=True)\nexec(compile(structural_source_readout_stage[\n    structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
exec(compile({True:structural_unit_cohort_setup_stage+structural_unit_cohort_fit_stage,False:""}[args.stage=="structural-unit-cohort-fit"],__file__,"exec"))



structural_contribution_cohort_training_transform="\nfull_no=full_optical.pivot(index=\"trace_id\",columns=\"time_h\",values=\"no\").reindex(\n    index=trace_id[train],columns=full_time).to_numpy()\nwindow_no=sliding_window_view(full_no,length,axis=-1)[valid_window]\nwindow_no-=(window_no@base[0])@base[0].T\nwindow_no/=np.sqrt(np.mean(window_no**2,axis=-1))[:,None]\nwindow_amplitude=np.linalg.solve(\n    np.einsum(\"nrt,nst->nrs\",window_unit,window_unit),\n    np.einsum(\"nrt,nt->nr\",window_unit,window_no)[...,None])[...,0]\nwindow_contribution=window_unit*window_amplitude[...,None]\nwindow_remainder=window_no-window_contribution.sum(axis=1)\nnp.testing.assert_allclose(np.einsum(\"nrt,nt->nr\",window_unit,window_remainder),0.,atol=1.e-10)\nsource_coordinate=window_contribution@coordinate_basis\nprint(\"CONTRIBUTION_TRAINING\",\"records\",len(train_rows),\"windows\",len(window_record),\n    \"amplitude_quantiles\",np.quantile(window_amplitude,[0,.5,1],axis=0).tolist(),\n    \"noise_RMS_quantiles\",np.quantile(np.sqrt(np.mean(window_remainder**2,axis=1)),[0,.5,1]).tolist(),flush=True)\n"
structural_contribution_cohort_calibration="\ncalibration_mean=bundle[\"calibration_mean\"].copy()\ncalibration_mean[:2]=0.\ncalibration_covariance=np.zeros((3,3))\ncalibration_covariance[2,2]=bundle[\"calibration_covariance\"][2,2]\ncalibration_eigenvalue,calibration_eigenvector=np.linalg.eigh(calibration_covariance)\nactive_sign=np.array([0],dtype=int)\nsign_values=np.ones((1,2))\nsign_logprior=np.zeros(1)\nsign_prior=np.array([1.,0.,0.,0.])\n"
structural_contribution_cohort_setup_stage="\nstructural_source_data_stage=structural_source_data_stage.replace(\n    'native = fold<application[\"lemna_expected_runs\"]','native = False',1)\nstructural_moving_sphere_flow_setup_stage=structural_moving_sphere_flow_setup_stage.replace(\n    'columns=[\"trace_id\",\"time_h\",\"published_target_y\",\"green\",\"red\"]',\n    'columns=[\"trace_id\",\"time_h\",\"published_target_y\",\"green\",\"red\",\"no\"]',1)\nsource_setup=structural_cohort_source_setup_stage.replace(\n    'application[\"structural_cohort_source\"]','application[\"structural_contribution_cohort_source\"]')\nsource_setup=source_setup.replace(\"paired_coordinate=source_coordinate.reshape(\",\n    structural_contribution_cohort_training_transform+\"\\npaired_coordinate=source_coordinate.reshape(\",1)\nexec(compile(source_setup,__file__,\"exec\"))\n"

