structural_literal_source_fit_stage = "\nfrom scipy.special import digamma,softmax\nfrom scipy.optimize import root_scalar\nfrom numpy.lib.stride_tricks import sliding_window_view\nstructural_source_data_stage=structural_source_data_stage.replace(\n    'native = fold<application[\"lemna_expected_runs\"]','native = False',1)\nstructural_diffusion_source_setup_stage=structural_diffusion_source_setup_stage.replace(\n    'torch.manual_seed(settings[\"seed\"])','').replace('rng=np.random.default_rng(settings[\"seed\"])','')\nexec(compile(structural_diffusion_source_setup_stage.split(\"data_sd=\",1)[0],__file__,\"exec\"))\nmoving_setup=structural_moving_sphere_flow_setup_stage[\n    structural_moving_sphere_flow_setup_stage.index(\"record_weight=row_weight.copy()\"):\n    structural_moving_sphere_flow_setup_stage.index(\"white_coordinate=\")]\nmoving_setup=moving_setup.replace(\n    'columns=[\"trace_id\",\"time_h\",\"published_target_y\",\"green\",\"red\"]',\n    'columns=[\"trace_id\",\"time_h\",\"published_target_y\",\"green\",\"red\",\"no\"]',1)\nexec(compile(moving_setup,__file__,\"exec\"))\ncohort_settings=application[\"structural_literal_source\"]\nstem=cohort_settings[\"stem\"].with_name(cohort_settings[\"stem\"].name+\"_common_fold\"+str(fold))\ntraining_group_index=np.unique(run[train],return_inverse=True)[1]\nstart_count=len(full_time)-length+1\ngroup_code,group_index=np.unique(\n    training_group_index[window_record]*start_count+window_start,return_inverse=True)\ngroup_n=np.bincount(group_index)\ngroup_weight=np.bincount(group_index,weights=window_weight)\nnp.testing.assert_allclose(window_weight,group_weight[group_index]/group_n[group_index],atol=1.e-15)\ngroup_order=np.argsort(group_index,kind=\"stable\")\nlocal_index=np.empty(len(group_index),dtype=int)\nlocal_index[group_order]=np.arange(len(group_index))-np.repeat(\n    np.r_[0,np.cumsum(group_n)[:-1]],group_n)\nfull_no=full_optical.pivot(index=\"trace_id\",columns=\"time_h\",values=\"no\").reindex(\n    index=trace_id[train],columns=full_time).to_numpy()\nwindow_no=sliding_window_view(full_no,length,axis=-1)[valid_window]\nwindow_no-=(window_no@base[0])@base[0].T\nwindow_no/=np.sqrt(np.mean(window_no**2,axis=-1))[:,None]\nnp.testing.assert_allclose(window_no[full_time[window_start]==optical_time[0]],mixed[train],atol=1.e-10)\nnoise_root=np.sqrt(noise_eigenvalue)\nwhite_source=source_coordinate/noise_root[None,None]\nwhite_no=(window_no@coordinate_basis)/noise_root[None]\ngain=np.linalg.solve(white_source@white_source.transpose(0,2,1),\n    np.einsum(\"nrd,nd->nr\",white_source,white_no)[...,None])[...,0]\nremainder=white_no-np.einsum(\"nr,nrd->nd\",gain,white_source)\nnoise_variance=np.mean(remainder**2,axis=-1)\nassert noise_variance.min()>0.\nnp.testing.assert_allclose(np.einsum(\"nrd,nd->nr\",white_source,remainder),0.,atol=1.e-9)\ninverse_noise_mean=window_weight@(1./noise_variance)\ngain_mean=(window_weight/noise_variance)@gain/inverse_noise_mean\ngain_residual=gain-gain_mean\ngain_covariance=(gain_residual.T*(window_weight/noise_variance))@gain_residual\ngain_precision=np.linalg.inv(gain_covariance)\nshape_statistic=np.log(inverse_noise_mean)+window_weight@np.log(noise_variance)\nshape_result=root_scalar(lambda value:np.log(value)-digamma(value)-shape_statistic,\n    bracket=[np.finfo(float).eps,1./np.finfo(float).eps],method=\"brentq\")\nassert shape_result.converged\nnoise_shape=shape_result.root\nnoise_rate=noise_shape/inverse_noise_mean\nsource_readout=structural_source_readout_stage.split(\"prior_labels =\",1)[0]\nsource_readout=source_readout.replace(\n    \"waves = np.stack([prediction,mixed[heldout]],axis=1)\",\"waves = source_unit.copy()\")\nsource_readout=source_readout.replace(\n    \"held_mask = mask[heldout]\",\"held_mask = np.ones((len(source_unit),length),dtype=bool)\")\nsource_readout=source_readout.replace(\n    \"held_count = count[heldout]\",\"held_count = np.full(len(source_unit),length,dtype=int)\")\nexec(compile(source_readout,__file__,\"exec\"))\nsource_period_mass=softmax(log_evidence.reshape(len(source_unit),2,len(periods))\n    +np.log(grid_weight)[None,None],axis=-1)\nprior_role_mass=np.einsum(\"n,nrp->rp\",window_weight,source_period_mass,optimize=True)\nnp.testing.assert_allclose(prior_role_mass.sum(axis=-1),1.,atol=1.e-12)\nnp.testing.assert_allclose(source_unit@coordinate_basis,source_coordinate,atol=1.e-12)\ndump({\"source_wave\":source_unit,\"source_period_mass\":source_period_mass,\n    \"source_group_index\":group_index,\"source_local_index\":local_index,\n    \"source_record\":window_record,\"source_start\":window_start,\"source_weight\":window_weight,\n    \"group_n\":group_n,\"group_weight\":group_weight,\"group_run\":training_groups[group_code//start_count],\n    \"group_start_h\":full_time[group_code%start_count],\"gain_mean\":gain_mean,\n    \"gain_covariance\":gain_covariance,\"gain_precision\":gain_precision,\n    \"noise_shape\":noise_shape,\"noise_rate\":noise_rate,\"noise_eigenvalue\":noise_eigenvalue,\n    \"coordinate_basis\":coordinate_basis,\"periods\":periods,\"prior_role_mass\":prior_role_mass,\n    \"training_trace_id\":trace_id[train],\"training_groups\":training_groups,\n    \"settings\":dict(cohort_settings)},stem.with_suffix(\".joblib\"))\nwindow=(np.abs(periods[:,None]-periods[None])<=application[\"risk_tolerance_h\"]).astype(float)\nprint(\"LITERAL_SOURCE_TRAINED\",\"fold\",fold,\"records\",len(train_rows),\n    \"real_windows\",len(source_unit),\"cohort_windows\",len(group_n),\"all_within_cohort_pairs\",int(group_n@group_n),\n    \"gain_mean\",gain_mean.tolist(),\"gain_covariance_eigenvalues\",np.linalg.eigvalsh(gain_covariance).tolist(),\n    \"noise_shape_rate\",[float(noise_shape),float(noise_rate)],\n    \"real_source_prior_periods\",periods[(prior_role_mass@window.T).argmax(axis=-1)].tolist(),flush=True)\nraise SystemExit(0)\n"
structural_literal_source_predict_stage = "\nfrom scipy.special import gammaln,softmax,logsumexp\nfrom scipy.stats import multivariate_t\nstructural_diffusion_source_setup_stage=structural_diffusion_source_setup_stage.replace(\n    'torch.manual_seed(settings[\"seed\"])','').replace('rng=np.random.default_rng(settings[\"seed\"])','')\nnative_query=args.heldout_run<application[\"lemna_expected_runs\"]\npreparation={True:structural_cohort_native_predict_stage,\n    False:structural_cohort_source_predict_stage}[native_query].split(\"paired_dimension=2*dimension\",1)[0]\npreparation=preparation.replace('application[\"structural_cohort_source\"]',\n    'application[\"structural_literal_source\"]')\nexec(compile(preparation,__file__,\"exec\"))\nsource_wave=bundle[\"source_wave\"]\nsource_mass=bundle[\"source_period_mass\"]\nsource_group=bundle[\"source_group_index\"]\nsource_local=bundle[\"source_local_index\"]\ntemplate_n=len(bundle[\"group_n\"])\ntemplate_max_n=int(bundle[\"group_n\"].max())\npadded_wave=np.zeros((template_n,template_max_n,2,length))\npadded_mass=np.zeros((template_n,template_max_n,2,len(bundle[\"periods\"])))\npadded_wave[source_group,source_local]=source_wave\npadded_mass[source_group,source_local]=source_mass\npadded_coordinate=padded_wave@coordinate_basis\nnoise_root=np.sqrt(noise_eigenvalue)\nwhite_source=padded_coordinate/noise_root[None,None,None]\nvalid_source=np.arange(template_max_n)[None]<bundle[\"group_n\"][:,None]\nvalid_pair=valid_source[:,:,None]&valid_source[:,None,:]\nprior_precision=bundle[\"gain_precision\"]\nprior_mean=bundle[\"gain_mean\"]\nprior_natural=prior_precision@prior_mean\nprior_quadratic=prior_mean@prior_natural\nnoise_shape,noise_rate=bundle[\"noise_shape\"],bundle[\"noise_rate\"]\nleft_precision=prior_precision[0,0]+np.sum(white_source[:,:,0]**2,axis=-1)\nright_precision=prior_precision[1,1]+np.sum(white_source[:,:,1]**2,axis=-1)\ncross_precision=prior_precision[0,1]+np.matmul(\n    white_source[:,:,0],white_source[:,:,1].transpose(0,2,1))\ndeterminant=left_precision[:,:,None]*right_precision[:,None,:]-cross_precision**2\nassert determinant.min()>0.\nconstant=gammaln(noise_shape+dimension/2.)-gammaln(noise_shape)+noise_shape*np.log(noise_rate)\nconstant-=dimension/2.*np.log(2.*np.pi)+.5*np.linalg.slogdet(bundle[\"gain_covariance\"])[1]\nconstant-=.5*np.log(noise_eigenvalue).sum()\npair_constant=constant-.5*np.log(determinant)\nheld_coordinate=mixed[heldout]@coordinate_basis\nwhite_held=held_coordinate/noise_root[None]\nexternal_group_names,external_group_index=np.unique(run[heldout],return_inverse=True)\ngroup_membership=(external_group_names[:,None]==run[heldout][None]).astype(float)\ntensor_source=torch.as_tensor(white_source)\ntensor_left=torch.as_tensor(left_precision[:,:,None])\ntensor_right=torch.as_tensor(right_precision[:,None,:])\ntensor_cross=torch.as_tensor(cross_precision)\ntensor_determinant=torch.as_tensor(determinant)\ntensor_natural=torch.as_tensor(prior_natural)\ntensor_constant=torch.as_tensor(pair_constant)\ntensor_valid=torch.as_tensor(valid_pair)\ntensor_log_n=torch.as_tensor(np.log(bundle[\"group_n\"]))\nliteral_record=lambda observed:(\n    projection:=torch.einsum(\"kmrd,d->kmr\",tensor_source,observed)+tensor_natural,\n    left:=projection[:,:,0,None],right:=projection[:,None,:,1],\n    quadratic:=observed.square().sum()+prior_quadratic\n        -(tensor_right*left.square()-2.*tensor_cross*left*right+tensor_left*right.square())/tensor_determinant,\n    pair_log:=tensor_constant-(noise_shape+dimension/2.)*torch.log(noise_rate+quadratic/2.),\n    pair_log:=pair_log.masked_fill(~tensor_valid,-torch.inf),\n    diagonal:=torch.diagonal(pair_log,dim1=-2,dim2=-1),\n    all_normalizer:=torch.logsumexp(pair_log.flatten(1),dim=-1),\n    paired_normalizer:=torch.logsumexp(diagonal,dim=-1),\n    factorial_marginal:=torch.stack([\n        torch.exp(torch.logsumexp(pair_log,dim=-1)-all_normalizer[:,None]),\n        torch.exp(torch.logsumexp(pair_log,dim=-2)-all_normalizer[:,None])]),\n    paired_marginal:=torch.exp(diagonal-paired_normalizer[:,None]),\n    (torch.stack([all_normalizer-2.*tensor_log_n,paired_normalizer-tensor_log_n]),\n        torch.stack([factorial_marginal,torch.stack([paired_marginal,paired_marginal])]),\n        quadratic.min()))[-1]\ncheck_source=padded_coordinate[0,[0,1],[0,1]]\ncheck_projection=white_source[0,[0,1],[0,1]]@white_held[0]+prior_natural\ncheck_quadratic=white_held[0]@white_held[0]+prior_quadratic-(\n    right_precision[0,1]*check_projection[0]**2\n    -2.*cross_precision[0,0,1]*check_projection[0]*check_projection[1]\n    +left_precision[0,0]*check_projection[1]**2)/determinant[0,0,1]\ncheck_analytic=pair_constant[0,0,1]-(noise_shape+dimension/2.)*np.log(noise_rate+check_quadratic/2.)\ncheck_dense=multivariate_t.logpdf(held_coordinate[0],loc=check_source.T@prior_mean,\n    shape=(noise_rate/noise_shape)*(np.diag(noise_eigenvalue)\n        +check_source.T@bundle[\"gain_covariance\"]@check_source),df=2.*noise_shape)\nnp.testing.assert_allclose(check_analytic,check_dense,atol=1.e-8,rtol=1.e-10)\nprint(\"LITERAL_SOURCE_INTEGRATION_START\",\"records\",len(held_rows),\"templates\",template_n,\n    \"all_pairs\",int(bundle[\"group_n\"]@bundle[\"group_n\"]),\n    \"analytic_dense_logpdf_difference\",float(check_analytic-check_dense),flush=True)\nrecord_log,conditional_source_probability,minimum_quadratic=torch.vmap(\n    literal_record,chunk_size=1)(torch.as_tensor(white_held))\nrecord_log=record_log.numpy()\nassert minimum_quadratic.min().item()>0.\nnp.testing.assert_allclose(conditional_source_probability.sum(dim=-1).numpy(),1.,atol=1.e-12)\ngroup_log=np.einsum(\"gn,nfk->gfk\",group_membership,record_log)+np.log(bundle[\"group_weight\"])[None,None]\ngroup_probability=softmax(group_log,axis=-1)\nindependent_probability=softmax(record_log+np.log(bundle[\"group_weight\"])[None,None],axis=-1)\ncontext_probability=np.stack([group_probability[external_group_index],independent_probability],axis=2)\nsource_features=np.concatenate([padded_mass,padded_wave],axis=-1).transpose(2,0,1,3).reshape(\n    2,template_n*template_max_n,-1)\ntensor_features=torch.as_tensor(np.ascontiguousarray(source_features))\nposterior_features=torch.vmap(lambda context,conditional:torch.matmul(\n    (context[:,:,None,:,None]*conditional[:,None]).reshape(\n        4,2,template_n*template_max_n).permute(1,0,2),tensor_features).permute(1,0,2),\n    chunk_size=1)(torch.as_tensor(context_probability),conditional_source_probability).numpy()\ndel conditional_source_probability\nperiods=bundle[\"periods\"]\nprior_role_mass=bundle[\"prior_role_mass\"]\nrole_mass=np.concatenate([posterior_features[:,:,:,:len(periods)],\n    np.broadcast_to(prior_role_mass,(len(held_rows),1,2,len(periods)))],axis=1)\nsource_pair_mean=posterior_features[:,:,:,len(periods):]\nnp.testing.assert_allclose(role_mass.sum(axis=-1),1.,atol=1.e-12)\nwindow=(np.abs(periods[:,None]-periods[None])<=application[\"risk_tolerance_h\"]).astype(float)\nrole_score=role_mass@window.T\nrole_estimate=periods[role_score.argmax(axis=-1)]\nrole_confidence=role_score.max(axis=-1)\nwindow_role_mass=role_mass.copy()\nwindow_role_estimate=role_estimate.copy()\nwindow_role_confidence=role_confidence.copy()\nprediction_ids=trace_id[heldout]\nprediction_runs=run[heldout]\nprediction_time=time\nprediction_mask=mask[heldout]\nprediction_raw=mixed[heldout]\nsource_window_index=np.arange(length)[None]\nnative_aggregation=\"\"\"\nrole_mass=role_mass.reshape(len(native_id),native_window_n,len(cohort_settings[\"methods\"]),\n    2,len(periods)).mean(axis=1)\nrole_score=role_mass@window.T\nrole_estimate=periods[role_score.argmax(axis=-1)]\nrole_confidence=role_score.max(axis=-1)\nprediction_ids=native_id\nprediction_runs=native_run\nprediction_time=native_time\nprediction_mask=np.ones(native_signal.shape,dtype=bool)\nprediction_raw=native_signal\nsource_window_index=native_window_index\n\"\"\"\nexec(compile({True:native_aggregation,False:\"\"}[native_query],__file__,\"exec\"))\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\nmethods=np.asarray(cohort_settings[\"methods\"])\npredictions=pd.DataFrame({\"trace_id\":np.repeat(prediction_ids,len(methods)),\n    \"method\":np.tile(methods,len(prediction_ids)),\"estimate_h\":estimate.ravel(),\n    \"confidence\":confidence.ravel(),\"heldout_fold\":fold,\n    \"heldout_run\":np.repeat(prediction_runs,len(methods)),\"method_status\":\"ok\"})\npredictions.to_csv(stem.with_suffix(\".csv\"),index=False,encoding=\"utf-8\",lineterminator=\"\\n\")\nnp.savez_compressed(stem.with_suffix(\".npz\"),trace_id=prediction_ids,time=prediction_time,\n    mask=prediction_mask,raw_waveform=prediction_raw,window_trace_id=trace_id[heldout],\n    source_window_time=time,source_window_index=source_window_index,\n    source_pair_mean=source_pair_mean,periods=periods,mass=mass,estimate=estimate,confidence=confidence,\n    methods=methods,role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,\n    window_role_mass=window_role_mass,window_role_estimate=window_role_estimate,\n    window_role_confidence=window_role_confidence,group_template_probability=group_probability,\n    independent_template_probability=independent_probability,group_log_evidence=logsumexp(group_log,axis=-1),\n    group_names=external_group_names,group_index=external_group_index,\n    template_run=bundle[\"group_run\"],template_start_h=bundle[\"group_start_h\"],\n    prior_role_mass=prior_role_mass,gain_mean=prior_mean,gain_covariance=bundle[\"gain_covariance\"],\n    noise_shape=noise_shape,noise_rate=noise_rate,training_trace_id=trace_id[train],\n    training_groups=training_groups,source_model=\"literal_real_optical_waveforms\",\n    source_mean_definition=\"posterior_mean_unit_waveform_without_mixing_gain\",\n    full_record_integration=\"equal_density_average_over_minimal_complete_covering_windows\")\nprint(\"LITERAL_SOURCE_PREDICTED\",\"fold\",fold,\"records\",len(prediction_ids),\n    \"cohort_template_ESS\",(1./np.sum(group_probability**2,axis=-1)).tolist(),flush=True)\nexec(compile(structural_source_readout_stage[\n    structural_source_readout_stage.index(\"# Join held-out reference\"):],__file__,\"exec\"))\nraise SystemExit(0)\n"
