structural_observed_empirical_fit_stage = "\nfrom joblib import load,dump\nfrom scipy.special import ive,hyp0f1,gammaln,roots_jacobi,logsumexp\nfrom scipy.optimize import root_scalar\nfrom numpy.lib.stride_tricks import sliding_window_view\ncohort_settings=application[\"structural_observed_empirical_source\"]\nfold=args.heldout_run\nparent_stem=cohort_settings[\"source_parent\"].with_name(\n    cohort_settings[\"source_parent\"].name+\"_common_fold\"+str(fold))\nparent=load(parent_stem.with_suffix(\".joblib\"))\ntraining_id=parent[\"training_trace_id\"]\ncoordinate_basis=parent[\"coordinate_basis\"]\nlength,dimension=coordinate_basis.shape\nobserved=pd.read_parquet(application[\"paths\"][\"lemna_dual_observations\"],\n    columns=[\"trace_id\",\"time_h\",\"no\"],filters=[(\"trace_id\",\"in\",training_id.tolist())]).pivot(\n        index=\"trace_id\",columns=\"time_h\",values=\"no\").reindex(training_id)\nwindow_no=sliding_window_view(observed.to_numpy(),length,axis=-1)[\n    parent[\"source_record\"],parent[\"source_start\"]]\nobserved_coordinate=window_no@coordinate_basis\nobserved_unit=observed_coordinate/np.linalg.norm(observed_coordinate,axis=-1,keepdims=True)\ngroup_sum=np.zeros((len(parent[\"group_n\"]),dimension))\nnp.add.at(group_sum,parent[\"source_group_index\"],observed_unit)\npair_cosine=(np.sum(group_sum**2,axis=-1)-parent[\"group_n\"])/(\n    parent[\"group_n\"]*(parent[\"group_n\"]-1.))\nmean_pair_cosine=parent[\"group_weight\"]@pair_cosine\nassert 0.<mean_pair_cosine<1.\nresultant=np.sqrt(mean_pair_cosine)\norder=dimension/2.-1.\nmean_cosine=lambda value:ive(order+1.,value)/ive(order,value)\ninitial=resultant*(dimension-resultant**2)/(1.-resultant**2)\nconcentration_result=root_scalar(lambda value:mean_cosine(value)-resultant,\n    fprime=lambda value:1.-mean_cosine(value)**2-(dimension-1.)*mean_cosine(value)/value,\n    x0=initial,method=\"newton\")\nassert concentration_result.converged and concentration_result.root>0.\nconcentration=concentration_result.root\nlog_uniform=gammaln(dimension/2.)-np.log(2.)-dimension/2.*np.log(np.pi)\nlog_hyp=np.log(hyp0f1(dimension/2.,concentration**2/4.))\nlog_constant=log_uniform-2.*log_hyp\nnodes,weights=roots_jacobi(128,(dimension-3.)/2.,(dimension-3.)/2.)\nlog_kernel=log_constant+np.log(hyp0f1(\n    dimension/2.,concentration**2*(1.+nodes)/2.))\nlog_sphere_area=np.log(2.)+(dimension-1.)/2.*np.log(np.pi)-gammaln((dimension-1.)/2.)\nlog_quadrature=log_kernel+np.log(weights)+log_sphere_area\nnp.testing.assert_allclose(logsumexp(log_quadrature),0.,atol=1.e-10)\nnp.testing.assert_allclose(np.exp(log_quadrature)@nodes,mean_pair_cosine,atol=1.e-10)\nstem=cohort_settings[\"stem\"].with_name(cohort_settings[\"stem\"].name+\"_common_fold\"+str(fold))\ndump({\"observed_unit\":observed_unit,\"concentration\":concentration,\n    \"mean_pair_cosine\":mean_pair_cosine,\"kernel_log_constant\":log_constant,\n    \"source_bundle\":str(parent_stem.with_suffix(\".joblib\")),\"training_trace_id\":training_id,\n    \"training_groups\":parent[\"training_groups\"],\"coordinate_basis\":coordinate_basis,\n    \"noise_eigenvalue\":parent[\"noise_eigenvalue\"],\"settings\":dict(cohort_settings)},\n    stem.with_suffix(\".joblib\"))\nprint(\"OBSERVED_EMPIRICAL_TRAINED\",\"fold\",fold,\"records\",len(training_id),\n    \"all_real_windows\",len(observed_unit),\"concentration\",float(concentration),\n    \"cohort_pair_cosine\",float(mean_pair_cosine),\n    \"predictive_kernel_log_normalization\",float(logsumexp(log_quadrature)),flush=True)\nraise SystemExit(0)\n"
structural_observed_empirical_predict_stage = "\nfrom scipy.special import hyp0f1,softmax,logsumexp\nstructural_diffusion_source_setup_stage=structural_diffusion_source_setup_stage.replace(\n    'torch.manual_seed(settings[\"seed\"])','').replace('rng=np.random.default_rng(settings[\"seed\"])','')\nnative_query=args.heldout_run<application[\"lemna_expected_runs\"]\npreparation={True:structural_cohort_native_predict_stage,\n    False:structural_cohort_source_predict_stage}[native_query].split(\"paired_dimension=2*dimension\",1)[0]\npreparation=preparation.replace('application[\"structural_cohort_source\"]',\n    'application[\"structural_observed_empirical_source\"]')\nexec(compile(preparation,__file__,\"exec\"))\nsource_bundle=load(bundle[\"source_bundle\"])\nsource_group=source_bundle[\"source_group_index\"]\nsource_local=source_bundle[\"source_local_index\"]\ntemplate_n=len(source_bundle[\"group_n\"])\ntemplate_max_n=int(source_bundle[\"group_n\"].max())\nperiods=source_bundle[\"periods\"]\npadded_observed=np.zeros((template_n,template_max_n,dimension))\npadded_mass=np.zeros((template_n,template_max_n,2,len(periods)))\npadded_wave=np.zeros((template_n,template_max_n,2,length))\npadded_observed[source_group,source_local]=bundle[\"observed_unit\"]\npadded_mass[source_group,source_local]=source_bundle[\"source_period_mass\"]\npadded_wave[source_group,source_local]=source_bundle[\"source_wave\"]\nvalid_source=np.arange(template_max_n)[None]<source_bundle[\"group_n\"][:,None]\nheld_coordinate=mixed[heldout]@coordinate_basis\nheld_unit=held_coordinate/np.linalg.norm(held_coordinate,axis=-1,keepdims=True)\ncosine=np.einsum(\"nd,kmd->nkm\",held_unit,padded_observed,optimize=True)\nnp.testing.assert_array_less(np.abs(cosine),1.+1.e-12)\nconcentration=bundle[\"concentration\"]\nlog_kernel=bundle[\"kernel_log_constant\"]+np.log(hyp0f1(dimension/2.,\n    concentration**2*(1.+np.clip(cosine,-1.,1.))/2.))\nlog_kernel=np.where(valid_source[None],log_kernel,-np.inf)\nassert np.isfinite(log_kernel[:,valid_source]).all()\nrecord_normalizer=logsumexp(log_kernel,axis=-1)\nrecord_log=record_normalizer-np.log(source_bundle[\"group_n\"])[None]\nconditional_source_probability=np.exp(log_kernel-record_normalizer[:,:,None])\ndel cosine,log_kernel\nnp.testing.assert_allclose(conditional_source_probability.sum(axis=-1),1.,atol=1.e-12)\nexternal_group_names,external_group_index=np.unique(run[heldout],return_inverse=True)\ngroup_membership=(external_group_names[:,None]==run[heldout][None]).astype(float)\ngroup_log=group_membership@record_log+np.log(source_bundle[\"group_weight\"])[None]\ngroup_probability=softmax(group_log,axis=-1)\nindependent_probability=softmax(record_log+np.log(source_bundle[\"group_weight\"])[None],axis=-1)\ncontext_probability=np.stack([group_probability[external_group_index],independent_probability],axis=1)\nsource_features=np.concatenate([padded_mass,padded_wave],axis=-1)\ntensor_features=torch.as_tensor(np.ascontiguousarray(\n    source_features.transpose(2,0,1,3).reshape(2,template_n*template_max_n,-1)))\npaired_features=torch.vmap(lambda context,conditional:torch.matmul(\n    (context[:,:,None]*conditional[None]).reshape(2,-1)[None],tensor_features).transpose(0,1),\n    chunk_size=1)(torch.as_tensor(context_probability),\n        torch.as_tensor(conditional_source_probability)).numpy()\ngroup_source_features=source_features.sum(axis=1)/source_bundle[\"group_n\"][:,None,None]\nunpaired_features=np.einsum(\"nck,krf->ncrf\",context_probability,group_source_features,optimize=True)\nposterior_features=np.concatenate([paired_features,unpaired_features],axis=1)\nprior_role_mass=source_bundle[\"prior_role_mass\"]\nrole_mass=np.concatenate([posterior_features[:,:,:,:len(periods)],\n    np.broadcast_to(prior_role_mass,(len(held_rows),1,2,len(periods)))],axis=1)\nsource_pair_mean=posterior_features[:,:,:,len(periods):]\nnp.testing.assert_allclose(role_mass.sum(axis=-1),1.,atol=1.e-12)\nwindow=(np.abs(periods[:,None]-periods[None])<=application[\"risk_tolerance_h\"]).astype(float)\nrole_score=role_mass@window.T\nrole_estimate=periods[role_score.argmax(axis=-1)]\nrole_confidence=role_score.max(axis=-1)\nwindow_role_mass=role_mass.copy()\nwindow_role_estimate=role_estimate.copy()\nwindow_role_confidence=role_confidence.copy()\nprediction_ids=trace_id[heldout]\nprediction_runs=run[heldout]\nprediction_time=time\nprediction_mask=mask[heldout]\nprediction_raw=mixed[heldout]\nsource_window_index=np.arange(length)[None]\nnative_aggregation=\"\"\"\nrole_mass=role_mass.reshape(len(native_id),native_window_n,len(cohort_settings[\"methods\"]),\n    2,len(periods)).mean(axis=1)\nrole_score=role_mass@window.T\nrole_estimate=periods[role_score.argmax(axis=-1)]\nrole_confidence=role_score.max(axis=-1)\nprediction_ids=native_id\nprediction_runs=native_run\nprediction_time=native_time\nprediction_mask=np.ones(native_signal.shape,dtype=bool)\nprediction_raw=native_signal\nsource_window_index=native_window_index\n\"\"\"\nexec(compile({True:native_aggregation,False:\"\"}[native_query],__file__,\"exec\"))\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\nmethods=np.asarray(cohort_settings[\"methods\"])\npredictions=pd.DataFrame({\"trace_id\":np.repeat(prediction_ids,len(methods)),\n    \"method\":np.tile(methods,len(prediction_ids)),\"estimate_h\":estimate.ravel(),\n    \"confidence\":confidence.ravel(),\"heldout_fold\":fold,\n    \"heldout_run\":np.repeat(prediction_runs,len(methods)),\"method_status\":\"ok\"})\npredictions.to_csv(stem.with_suffix(\".csv\"),index=False,encoding=\"utf-8\",lineterminator=\"\\n\")\nnp.savez_compressed(stem.with_suffix(\".npz\"),trace_id=prediction_ids,time=prediction_time,\n    mask=prediction_mask,raw_waveform=prediction_raw,window_trace_id=trace_id[heldout],\n    source_window_time=time,source_window_index=source_window_index,\n    source_pair_mean=source_pair_mean,periods=periods,mass=mass,estimate=estimate,confidence=confidence,\n    methods=methods,role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,\n    window_role_mass=window_role_mass,window_role_estimate=window_role_estimate,\n    window_role_confidence=window_role_confidence,group_template_probability=group_probability,\n    independent_template_probability=independent_probability,group_log_evidence=logsumexp(group_log,axis=-1),\n    group_names=external_group_names,group_index=external_group_index,\n    template_run=source_bundle[\"group_run\"],template_start_h=source_bundle[\"group_start_h\"],\n    prior_role_mass=prior_role_mass,concentration=concentration,\n    training_trace_id=trace_id[train],training_groups=training_groups,\n    source_mean_definition=\"posterior_mean_real_unit_source_waveform\",\n    full_record_integration=\"equal_density_average_over_minimal_complete_covering_windows\")\nprint(\"OBSERVED_EMPIRICAL_PREDICTED\",\"fold\",fold,\"records\",len(prediction_ids),\n    \"cohort_template_ESS\",(1./np.sum(group_probability**2,axis=-1)).tolist(),flush=True)\nexec(compile(structural_source_readout_stage[\n    structural_source_readout_stage.index(\"# Join held-out reference\"):],__file__,\"exec\"))\nraise SystemExit(0)\n"
