structural_harmonic_external_stage = "\nfrom scipy.special import softmax\napp=application\nsettings=app[\"structural_harmonic_innovation\"]\nbundle=np.load(settings[\"stem\"].with_suffix(\".npz\"))\nstem=settings[\"external_stem\"]\nexternal=pd.read_parquet(app[\"conditional_source_external\"][\"raw\"],\n    columns=[\"trace_id\",\"run\",\"time_h\",\"no\"])\nidentity=external[[\"trace_id\",\"run\"]].drop_duplicates().sort_values(\"trace_id\")\nids=identity.trace_id.to_numpy(dtype=str)\nruns=identity.run.to_numpy(dtype=str)\ntime=np.arange(app[\"conditional_source_external\"][\"window_h\"][0],\n    app[\"conditional_source_external\"][\"window_h\"][1]+1.)\nraw=external.pivot(index=\"trace_id\",columns=\"time_h\",values=\"no\").reindex(\n    index=ids,columns=time).to_numpy()\nlength=len(time)\ntime=time-time[0]\nbase=np.stack([np.ones(length)/np.sqrt(length),\n    (time-time.mean())/np.linalg.norm(time-time.mean())],axis=-1)\nwindow_no=raw-(raw@base)@base.T\nwindow_no/=np.sqrt(np.mean(window_no**2,axis=-1))[:,None]\ngroup_names,group_index=np.unique(runs,return_inverse=True)\ngroup_n=np.bincount(group_index)\nsource_sum=np.zeros((len(group_n),length))\nnp.add.at(source_sum,group_index,window_no)\npeer=(source_sum[group_index]-window_no)/(group_n[group_index,None]-1.)\npeer/=np.sqrt(np.mean(peer**2,axis=-1))[:,None]\ninput_wave=np.stack([window_no,peer],axis=-1)\ninput_fft=np.fft.rfft(input_wave,axis=1,norm=\"ortho\")\nfrequencies=bundle[\"frequencies\"]\nband=bundle[\"band\"]\nlinear_spectrum=np.zeros_like(input_fft)\nlinear_spectrum[:,frequencies]=np.einsum(\"nfi,fir->nfr\",\n    input_fft[:,frequencies],bundle[\"linear_coefficient\"][-1],optimize=True)\nquadratic=(input_fft[:,2*band,:,None]*input_fft[:,band,None,:].conj()).reshape(len(ids),len(band),-1)\ndesign=np.concatenate([input_fft[:,band],quadratic],axis=-1)\nquadratic_spectrum=linear_spectrum.copy()\nquadratic_spectrum[:,band]=np.einsum(\"nfi,fir->nfr\",design,bundle[\"quadratic_coefficient\"][-1],optimize=True)\nlinear_wave=np.fft.irfft(linear_spectrum,axis=1,n=length,norm=\"ortho\").transpose(0,2,1)\nquadratic_wave=np.fft.irfft(quadratic_spectrum,axis=1,n=length,norm=\"ortho\").transpose(0,2,1)\nsource_pairs=np.stack([linear_wave,quadratic_wave,np.repeat(window_no[:,None],2,axis=1)],axis=1)\nsource_pairs-=(source_pairs@base)@base.T\nmethod_names=bundle[\"methods\"][:3]\nsource_readout=structural_source_readout_stage.split(\"prior_labels =\",1)[0]\nsource_readout=source_readout.replace(\"waves = np.stack([prediction,mixed[heldout]],axis=1)\",\n    \"waves = source_pairs.reshape(-1,2,length)\")\nsource_readout=source_readout.replace(\"held_mask = mask[heldout]\",\n    \"held_mask = np.ones((len(ids)*len(method_names),length),dtype=bool)\")\nsource_readout=source_readout.replace(\"held_count = count[heldout]\",\n    \"held_count = np.full(len(ids)*len(method_names),length,dtype=int)\")\nexec(compile(source_readout,__file__,\"exec\"))\nperiod_mass=softmax(log_evidence.reshape(len(ids),len(method_names),2,len(periods))\n    +np.log(grid_weight)[None,None,None],axis=-1)\nperiod_window=(np.abs(periods[:,None]-periods[None])<=app[\"risk_tolerance_h\"]).astype(float)\nperiod_score=period_mass@period_window.T\nestimate=periods[period_score.argmax(axis=-1)]\nconfidence=period_score.max(axis=-1)\nnp.savez_compressed(stem.with_suffix(\".npz\"),trace_id=ids,run=runs,time=time,raw_waveform=raw,\n    input_unit_waveform=window_no,peer_waveform=peer,source_pairs=source_pairs,\n    periods=periods,methods=method_names,mass=period_mass,estimate=estimate,confidence=confidence,\n    training_trace_id=bundle[\"trace_id\"],training_groups=bundle[\"groups\"],\n    linear_coefficient=bundle[\"linear_coefficient\"][-1],\n    quadratic_coefficient=bundle[\"quadratic_coefficient\"][-1],\n    band=band,frequencies=frequencies,\n    readout_definition=\"proper_H1_period_score_on_conditional_mean_not_source_posterior\")\npredictions=pd.DataFrame({\"trace_id\":np.repeat(ids,len(method_names)),\n    \"method\":np.tile(method_names,len(ids)),\"estimate_h\":estimate[:,:,0].ravel(),\n    \"confidence\":confidence[:,:,0].ravel(),\"heldout_fold\":app[\"lemna_expected_runs\"],\n    \"heldout_run\":np.repeat(runs,len(method_names)),\"method_status\":\"ok\"})\npredictions.to_csv(stem.with_suffix(\".csv\"),index=False,encoding=\"utf-8\",lineterminator=\"\\n\")\nreference=pd.read_csv(app[\"conditional_source_external\"][\"reference\"],encoding=\"utf-8\",\n    float_precision=\"round_trip\").set_index(\"trace_id\").reindex(ids).rename(\n        columns={\"target_period_h\":\"reference_period_h\",\"reference_status\":\"reference_state\"})\ncells=predictions.join(reference[[\"reference_period_h\",\"reference_usable\",\"reference_state\"]],on=\"trace_id\")\ncells[\"absolute_difference_h\"]=(cells.estimate_h-cells.reference_period_h).abs().where(cells.reference_usable)\ncells[\"bad2h\"]=cells.absolute_difference_h.gt(app[\"risk_tolerance_h\"]).astype(float).where(cells.reference_usable)\ncells.to_csv(str(stem)+\"_cells.csv\",index=False,encoding=\"utf-8\",lineterminator=\"\\n\")\nprint(\"HARMONIC_SOURCE_COMMON_EXTERNAL\",cells.groupby(\"method\").agg(n=(\"trace_id\",\"size\"),\n    qualified=(\"reference_usable\",\"sum\"),bad2h=(\"bad2h\",\"sum\"),mae_h=(\"absolute_difference_h\",\"mean\")).to_string(),flush=True)\nprint(\"HARMONIC_SOURCE_COMMON_EXTERNAL_BY_RUN\",cells.groupby([\"heldout_run\",\"method\"]).agg(\n    qualified=(\"reference_usable\",\"sum\"),bad2h=(\"bad2h\",\"sum\"),\n    mae_h=(\"absolute_difference_h\",\"mean\")).unstack(\"method\").to_string(),flush=True)\noptical=pd.read_parquet(app[\"conditional_source_external\"][\"raw\"],\n    columns=[\"trace_id\",\"time_h\",\"published_target_y\",\"published_background_y\"])\noptical_time=time+app[\"conditional_source_external\"][\"window_h\"][0]\ntruth_source=np.stack([optical.pivot(index=\"trace_id\",columns=\"time_h\",values=\"published_target_y\").reindex(\n    index=ids,columns=optical_time).to_numpy(),optical.pivot(index=\"trace_id\",columns=\"time_h\",\n    values=\"published_background_y\").reindex(index=ids,columns=optical_time).to_numpy()],axis=1)\ntruth_source-=(truth_source@base)@base.T\ntruth_source/=np.sqrt(np.mean(truth_source**2,axis=-1))[:,:,None]\nsource_norm=source_pairs/np.linalg.norm(source_pairs,axis=-1,keepdims=True)\ntruth_norm=truth_source/np.linalg.norm(truth_source,axis=-1,keepdims=True)\ncorrelation=np.einsum(\"nmrt,nst->nmrs\",source_norm,truth_norm,optimize=True)\nmse=np.mean((source_pairs-truth_source[:,None])**2,axis=-1)\nprint(\"HARMONIC_SOURCE_EXTERNAL_CORRELATION_MEDIAN\",np.median(correlation,axis=0).tolist(),\n    \"SOURCE_MSE\",mse.mean(axis=0).tolist(),flush=True)\nraise SystemExit(0)\n"
exec(compile({True:structural_harmonic_external_stage,False:""}[
    args.stage=="structural-harmonic-external"],__file__,"exec"))


structural_remixed_moment_stage = '\nfrom scipy.special import softmax\nexec(compile(structural_harmonic_innovation_stage.split("moment_fit=",1)[0],__file__,"exec"))\nsettings=app["structural_remixed_moment"]\nstem=settings["stem"]\ngain=np.linalg.solve(source@source.transpose(0,2,1),\n    np.einsum("nrt,nt->nr",source,window_no)[...,None])[...,0]\nremainder=window_no-np.einsum("nr,nrt->nt",gain,source)\nnp.testing.assert_allclose(np.einsum("nrt,nt->nr",source,remainder),0.,atol=1.e-10)\nbackground_gain=gain[:,1]\ntarget_fft=source_fft[:,:,0]*gain[:,:1]\nresidual_fft=input_fft[:,:,0]-background_gain[:,None]*source_fft[:,:,1]\nbackground_fft=source_fft[:,:,1]\nrow_weight=parent["source_weight"]*group_n\neligible=fold_weights>0.\nloo_eligible=eligible[:,None,:]&~np.eye(group_n,dtype=bool)[None]\nloo_weights=loo_eligible/loo_eligible.sum(axis=-1,keepdims=True)\nnp.testing.assert_allclose(loo_weights.sum(axis=-1),1.,atol=1.e-12)\nexpand_moments="""\nbasis_n=donor_basis.shape[-1]\nvariable_n=anchor_coeff.shape[-2]\nflat=anchor_coeff.reshape(len(source),len(selected_frequency),-1)\nanchor_moment=np.zeros((group_n,len(selected_frequency),flat.shape[-1],flat.shape[-1]),dtype=complex)\nnp.add.at(anchor_moment,group_index,\n    flat.conj()[..., :,None]*flat[...,None,:]*row_weight[:,None,None,None])\ndonor_moment=np.zeros((group_n,len(selected_frequency),basis_n,basis_n),dtype=complex)\nnp.add.at(donor_moment,group_index,\n    donor_basis.conj()[...,:,None]*donor_basis[...,None,:]*row_weight[:,None,None,None])\nanchor_moment=anchor_moment.reshape(group_n,len(selected_frequency),variable_n,basis_n,variable_n,basis_n)\nremixed_moment=np.einsum("gfakbl,hfkl->ghfab",anchor_moment,donor_moment,optimize=True)\nobserved_moment=np.zeros((group_n,len(selected_frequency),variable_n,variable_n),dtype=complex)\nnp.add.at(observed_moment,group_index,\n    original_joint.conj()[...,:,None]*original_joint[...,None,:]*row_weight[:,None,None,None])\npair_moment=np.stack([np.broadcast_to(observed_moment[:,None],remixed_moment.shape),remixed_moment])\nnp.testing.assert_allclose(pair_moment,pair_moment.conj().swapaxes(-1,-2),atol=1.e-10)\nfull_moment=np.einsum("kg,kh,mghfij->kmfij",fold_weights,fold_weights,pair_moment,optimize=True)\nleave_moment=np.einsum("krg,krh,mghfij->krmfij",loo_weights,loo_weights,pair_moment,optimize=True)\nscale=np.sqrt(np.diagonal(full_moment,axis1=-2,axis2=-1).real)\nstandard=full_moment/scale[..., :,None]/scale[...,None,:]\nleave_scale=np.sqrt(np.diagonal(leave_moment,axis1=-2,axis2=-1).real)\nleave_standard=leave_moment/leave_scale[..., :,None]/leave_scale[...,None,:]\nnp.testing.assert_allclose(np.diagonal(leave_standard,axis1=-2,axis2=-1).real,1.,atol=1.e-12)\nleave_mean=np.einsum("kr,krmfij->kmfij",fold_weights,leave_standard,optimize=True)\nleave_delta=leave_standard-leave_mean[:,None]\nbeta=(fold_n-1.)[:,None,None]*np.einsum("kr,krmf->kmf",fold_weights,\n    np.sum(np.abs(leave_delta)**2,axis=(-1,-2)),optimize=True)\ndelta=np.sum(np.abs(standard-np.eye(variable_n))**2,axis=(-1,-2))\nshrinkage=np.minimum(beta/delta,1.)\nshrunk=(1.-shrinkage[...,None,None])*standard+shrinkage[...,None,None]*np.eye(variable_n)\ncoefficient=np.linalg.solve(shrunk[...,:-1,:-1],shrunk[...,:-1,-1:])\ncoefficient*=scale[...,None,-1:]/scale[...,:-1,None]\nassert np.isfinite(coefficient).all()\ndel flat,anchor_moment,donor_moment,leave_moment,leave_standard,leave_delta\n"""\nselected_frequency=frequencies\nu=residual_fft[:,selected_frequency]\nb=np.broadcast_to(background_gain[:,None],u.shape)\nz=target_fft[:,selected_frequency]\nzero=np.zeros_like(u)\nanchor_coeff=np.stack([np.stack([u,b],axis=-1),np.stack([z,zero],axis=-1)],axis=-2)\ndonor_basis=np.stack([np.ones_like(u),background_fft[:,selected_frequency]],axis=-1)\noriginal_joint=np.stack([input_fft[:,selected_frequency,0],z],axis=-1)\nexec(compile(expand_moments,__file__,"exec"))\nlinear_coefficient=coefficient.copy()\nlinear_shrinkage=shrinkage.copy()\nlinear_pair_moment=pair_moment.copy()\nselected_frequency=band\nu=residual_fft[:,band]\nv=residual_fft[:,2*band]\nb=np.broadcast_to(background_gain[:,None],u.shape)\nz=target_fft[:,band]\nzero=np.zeros_like(u)\nanchor_coeff=np.stack([\n    np.stack([u,b,zero,zero,zero],axis=-1),\n    np.stack([v*u.conj(),zero,b*v,b*u.conj(),b**2],axis=-1),\n    np.stack([z,zero,zero,zero,zero],axis=-1)],axis=-2)\ndonor_basis=np.stack([np.ones_like(u),background_fft[:,band],background_fft[:,band].conj(),\n    background_fft[:,2*band],background_fft[:,2*band]*background_fft[:,band].conj()],axis=-1)\noriginal_joint=np.stack([input_fft[:,band,0],\n    input_fft[:,2*band,0]*input_fft[:,band,0].conj(),z],axis=-1)\nliteral_replaced=window_no-background_gain[:,None]*source[:,1]+background_gain[:,None]*source[0,1]\nliteral_fft=np.fft.rfft(literal_replaced,axis=-1,norm="ortho")\nliteral_joint=np.stack([literal_fft[:,band],literal_fft[:,2*band]*literal_fft[:,band].conj(),z],axis=-1)\nexpanded_joint=np.einsum("nfak,fk->nfa",anchor_coeff,donor_basis[0],optimize=True)\nnp.testing.assert_allclose(literal_joint,expanded_joint,rtol=1.e-11,atol=1.e-11)\ndel literal_replaced,literal_fft,literal_joint,expanded_joint\nexec(compile(expand_moments,__file__,"exec"))\nquadratic_coefficient=coefficient.copy()\nquadratic_shrinkage=shrinkage.copy()\nquadratic_pair_moment=pair_moment.copy()\nnp.savez_compressed(stem.with_suffix(".npz"),linear_coefficient=linear_coefficient,\n    quadratic_coefficient=quadratic_coefficient,linear_shrinkage=linear_shrinkage,\n    quadratic_shrinkage=quadratic_shrinkage,linear_pair_moment=linear_pair_moment,\n    quadratic_pair_moment=quadratic_pair_moment,fold_weights=fold_weights,loo_weights=loo_weights,\n    groups=groups,training_trace_id=ids,source_window_record=parent["source_record"],\n    source_window_start=parent["source_start"],window_gain=gain,\n    frequencies=frequencies,band=band,all_window_pairs=len(source)**2)\nprint("REMIXED_MOMENT_FIT","real_records",len(ids),"all_windows",len(source),\n    "analytically_integrated_pairs",len(source)**2,"held_experiments",group_n,\n    "original_quadratic_shrinkage",np.quantile(quadratic_shrinkage[:,0],[0,.5,1]).tolist(),\n    "remixed_quadratic_shrinkage",np.quantile(quadratic_shrinkage[:,1],[0,.5,1]).tolist(),flush=True)\ncommon=parent["group_start_h"][source_group]==app["conditional_source_external"]["window_h"][0]\nnp.testing.assert_array_equal(parent["source_record"][common],np.arange(len(ids)))\nnative_id=ids.copy()\nnative_run=source_run[common]\nnative_fold=group_index[common]\nnative_unit=window_no[common]\nexternal=pd.read_parquet(app["conditional_source_external"]["raw"],columns=["trace_id","run","time_h","no"])\nidentity=external[["trace_id","run"]].drop_duplicates().sort_values("trace_id")\nexternal_ids=identity.trace_id.to_numpy(dtype=str)\nexternal_runs=identity.run.to_numpy(dtype=str)\nexternal_raw=external.pivot(index="trace_id",columns="time_h",values="no").reindex(\n    index=external_ids,columns=time+app["conditional_source_external"]["window_h"][0]).to_numpy()\nexternal_unit=external_raw-(external_raw@base)@base.T\nexternal_unit/=np.sqrt(np.mean(external_unit**2,axis=-1))[:,None]\nquery=np.concatenate([native_unit,external_unit],axis=0)\nids=np.r_[native_id,external_ids]\nruns=np.r_[native_run,external_runs]\ncohort=np.repeat(["native_common_loro","external_common"],[len(native_id),len(external_ids)])\nquery_fold=np.r_[native_fold,np.full(len(external_ids),group_n,dtype=int)]\nquery_fft=np.fft.rfft(query,axis=-1,norm="ortho")\nlinear_spectrum=np.zeros((len(query),2,query_fft.shape[-1]),dtype=complex)\nlinear_spectrum[:,:,frequencies]=np.einsum("nf,nmf->nmf",query_fft[:,frequencies],\n    linear_coefficient[query_fold,...,0,0],optimize=True)\nquadratic_design=np.stack([query_fft[:,band],query_fft[:,2*band]*query_fft[:,band].conj()],axis=-1)\nquadratic_spectrum=linear_spectrum.copy()\nquadratic_spectrum[:,:,band]=np.einsum("nfi,nmfi->nmf",\n    quadratic_design,quadratic_coefficient[query_fold,...,0],optimize=True)\nprediction=np.fft.irfft(np.concatenate([linear_spectrum,quadratic_spectrum],axis=1),\n    n=length,axis=-1,norm="ortho")\nprediction-=(prediction@base)@base.T\nmethods=np.asarray(settings["methods"])\nreadout=structural_source_readout_stage.split("prior_labels =",1)[0]\nreadout=readout.replace("waves = np.stack([prediction,mixed[heldout]],axis=1)","waves = prediction.copy()")\nreadout=readout.replace("held_mask = mask[heldout]","held_mask = np.ones((len(ids),length),dtype=bool)")\nreadout=readout.replace("held_count = count[heldout]","held_count = np.full(len(ids),length,dtype=int)")\nreadout=readout.replace("np.repeat(held_mask,2,axis=0)","np.repeat(held_mask,len(methods),axis=0)")\nreadout=readout.replace("np.repeat(held_count,2)","np.repeat(held_count,len(methods))")\nexec(compile(readout,__file__,"exec"))\nmass=softmax(log_evidence.reshape(len(ids),len(methods),len(periods))+np.log(grid_weight)[None,None],axis=-1)\nperiod_window=(np.abs(periods[:,None]-periods[None])<=app["risk_tolerance_h"]).astype(float)\nscore=mass@period_window.T\nestimate=periods[score.argmax(axis=-1)]\nconfidence=score.max(axis=-1)\nnp.savez_compressed(stem.with_name(stem.name+"_predictions").with_suffix(".npz"),trace_id=ids,run=runs,\n    cohort=cohort,heldout_fold=query_fold,time=time,raw_unit_waveform=query,\n    source_waveform=prediction,periods=periods,methods=methods,mass=mass,estimate=estimate,\n    confidence=confidence,training_trace_id=native_id,training_groups=groups,\n    readout_definition="proper_H1_score_on_predicted_target_contribution_not_source_posterior")\npredictions=pd.DataFrame({"trace_id":np.repeat(ids,len(methods)),"cohort":np.repeat(cohort,len(methods)),\n    "method":np.tile(methods,len(ids)),"estimate_h":estimate.ravel(),"confidence":confidence.ravel(),\n    "heldout_fold":np.repeat(query_fold,len(methods)),"heldout_run":np.repeat(runs,len(methods)),"method_status":"ok"})\npredictions.loc[predictions.cohort.eq("native_common_loro")].to_csv(\n    settings["native_stem"].with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\npredictions.loc[predictions.cohort.eq("external_common")].to_csv(\n    settings["external_stem"].with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnative_ref=pd.read_csv(app["paths"]["lemna_reference"],encoding="utf-8",float_precision="round_trip").set_index("trace_id")\nexternal_ref=pd.read_csv(app["conditional_source_external"]["reference"],encoding="utf-8",\n    float_precision="round_trip").set_index("trace_id").rename(\n        columns={"target_period_h":"reference_period_h","reference_status":"reference_state"})\nreference=pd.concat([native_ref[["reference_period_h","reference_usable","reference_state"]],\n    external_ref[["reference_period_h","reference_usable","reference_state"]]]).reindex(ids)\ncells=predictions.join(reference,on="trace_id")\ncells["absolute_difference_h"]=(cells.estimate_h-cells.reference_period_h).abs().where(cells.reference_usable)\ncells["bad2h"]=cells.absolute_difference_h.gt(app["risk_tolerance_h"]).astype(float).where(cells.reference_usable)\ncells.to_csv(str(stem)+"_cells.csv",index=False,encoding="utf-8",lineterminator="\\n")\nprint("REMIXED_MOMENT_PERIOD",cells.groupby(["cohort","method"]).agg(n=("trace_id","size"),\n    qualified=("reference_usable","sum"),bad2h=("bad2h","sum"),mae_h=("absolute_difference_h","mean")).to_string(),flush=True)\nprint("REMIXED_MOMENT_NATIVE_BY_RUN",cells.loc[cells.cohort.eq("native_common_loro")].groupby(\n    ["heldout_run","method"]).agg(bad2h=("bad2h","sum"),\n    mae_h=("absolute_difference_h","mean")).unstack("method").to_string(),flush=True)\nprint("REMIXED_MOMENT_EXTERNAL_BY_RUN",cells.loc[cells.cohort.eq("external_common")].groupby(\n    ["heldout_run","method"]).agg(bad2h=("bad2h","sum"),\n    mae_h=("absolute_difference_h","mean")).unstack("method").to_string(),flush=True)\nraise SystemExit(0)\n'
exec(compile({True:structural_remixed_moment_stage,False:""}[
    args.stage=="structural-remixed-moment"],__file__,"exec"))

structural_period_state_setup_stage = '\nfrom scipy.optimize import minimize\nfrom scipy.special import logsumexp,expit\nfrom joblib import load,dump\nimport torch\nexec(compile(structural_phase_source_training_stage[\n    :structural_phase_source_training_stage.index("source_objective =")],__file__,"exec"))\nstate_settings=application["structural_period_state"]\nassert fold==application["lemna_expected_runs"] and not native\nparent_stem=application["structural_dynamics_source"]["stem"].with_name(\n    application["structural_dynamics_source"]["stem"].name+"_common_fold"+str(fold))\nparent=np.load(parent_stem.with_suffix(".npz"))\nassert np.array_equal(parent["training_trace_id"],trace_id[train])\nassert np.array_equal(parent["trace_id"],trace_id[heldout]) and np.array_equal(parent["periods"],periods)\nactive_kernel=parent["source_kernel"][0]\nprojection=np.eye(length)-base[0]@base[0].T\npadding=base[0]@base[0].T\nlag=np.abs(time[:,None]-time[None])\nstem=state_settings["stem"].with_name(state_settings["stem"].name+"_common_fold"+str(fold))\n'
structural_period_state_fit_stage = '\nexec(compile(structural_period_state_setup_stage,__file__,"exec"))\n# The active kernels are reused unchanged. All real optical sources contribute\n# to the state fit; an unavailable published period is never a negative label.\nactive_inverse=np.linalg.inv(active_kernel)\nactive_quadratic=np.einsum("nrt,rptu,nru->nrp",source_unit,active_inverse,source_unit,optimize=True)\nactive_evidence=-.5*np.linalg.slogdet(active_kernel)[1][None]-.5*dimension*np.log(active_quadratic)\nactive_loglikelihood=logsumexp(active_evidence+np.log(prior[train]),axis=-1)\ntensor_projection=torch.as_tensor(projection,dtype=torch.float64)\ntensor_padding=torch.as_tensor(padding,dtype=torch.float64)\ntensor_lag=torch.as_tensor(lag,dtype=torch.float64)\ntensor_source=torch.as_tensor(source_unit,dtype=torch.float64)\ntensor_weight=torch.as_tensor(row_weight,dtype=torch.float64)\ntensor_active=torch.as_tensor(active_loglikelihood,dtype=torch.float64)\nnull_kernel_model=lambda vector:(\n    correlation_h:=vector[:2].exp(),\n    covariance:=torch.exp(-tensor_lag[None]/correlation_h[:,None,None]),\n    covariance:=tensor_projection@covariance@tensor_projection,\n    covariance*(dimension/covariance.diagonal(dim1=-2,dim2=-1).sum(dim=-1))[:,None,None]\n        +tensor_padding)[-1]\nstate_likelihood=lambda vector:(\n    covariance:=null_kernel_model(vector),\n    cholesky:=torch.linalg.cholesky(covariance),\n    inverse:=torch.cholesky_inverse(cholesky),\n    quadratic:=torch.einsum("nrt,rtu,nru->nr",tensor_source,inverse,tensor_source),\n    determinant:=2.*torch.log(cholesky.diagonal(dim1=-2,dim2=-1)).sum(dim=-1),\n    null_evidence:=-.5*determinant[None]-.5*dimension*torch.log(quadratic),\n    active_logprob:=-torch.nn.functional.softplus(-vector[2:]),\n    null_logprob:=-torch.nn.functional.softplus(vector[2:]),\n    torch.stack([tensor_active+active_logprob[None],null_evidence+null_logprob[None]],dim=-1))[-1]\nstate_objective=lambda vector:-(tensor_weight[:,None]*torch.logsumexp(state_likelihood(vector),dim=-1)).sum()/2.\nstate_gradient=torch.func.grad_and_value(state_objective)\nto_scipy=lambda gradient,value:(value.detach().item(),gradient.detach().numpy())\nstate_scipy=lambda vector:to_scipy(*state_gradient(torch.as_tensor(vector,dtype=torch.float64)))\ninitial=np.r_[parent["source_parameters"][:,2],np.zeros(2)]\ninitial_loss,initial_gradient=state_scipy(initial)\nstep=np.zeros_like(initial)\ngradient_index=int(np.abs(initial_gradient).argmax())\nstep[gradient_index]=1.e-5\ncentral=(state_scipy(initial+step)[0]-state_scipy(initial-step)[0])/2.e-5\nassert np.isclose(central,initial_gradient[gradient_index],rtol=1.e-4,atol=1.e-6)\nprint("PERIOD_STATE_SOURCE_TRAIN","records",len(train_rows),"groups",len(training_groups),\n    "initial_loss",initial_loss,"gradient_check",initial_gradient[gradient_index],central,flush=True)\nnumeric_bounds=np.log(np.finfo(float).eps**np.array([.25,-.25]))\nresult=minimize(state_scipy,initial,jac=True,method="L-BFGS-B",\n    bounds=np.tile(numeric_bounds,(len(initial),1)),\n    options={"maxiter":state_settings["maxiter"],"ftol":state_settings["ftol"],\n        "gtol":state_settings["gtol"],"maxls":settings["maxls"]})\nparameters=torch.as_tensor(result.x,dtype=torch.float64)\nnull_kernel=null_kernel_model(parameters).detach().numpy()\nactive_probability=expit(result.x[2:])\ntraining_state=torch.softmax(state_likelihood(parameters),dim=-1).detach().numpy()\nassert np.allclose(training_state.sum(axis=-1),1.) and np.linalg.eigvalsh(null_kernel).min()>0.\ndump({"parameters":result.x,"optimization":result,"null_kernel":null_kernel,\n    "active_probability":active_probability,"training_state":training_state,\n    "training_trace_id":trace_id[train],"training_groups":training_groups,\n    "configuration":state_settings,"parent_stem":str(parent_stem),\n    "state_label":"OU_fluctuation_without_resolved_period_not_biological_absence",\n    "heldout_optical_read":False},stem.with_suffix(".joblib"))\nprint("PERIOD_STATE_SOURCE_FIT","correlation_h",np.exp(result.x[:2]).tolist(),\n    "active_probability",active_probability.tolist(),"iterations",result.nit,"loss",result.fun,\n    "status",str(result.message),"training_active_quantiles",\n    np.quantile(training_state[:,:,0],[0,.1,.5,.9,1.],axis=0).tolist(),flush=True)\nraise SystemExit(0)\n'
exec(compile({True:structural_period_state_fit_stage,False:""}[args.stage=="structural-period-state-fit"],__file__,"exec"))
structural_period_state_predict_stage = '\nexec(compile(structural_period_state_setup_stage,__file__,"exec"))\nbundle=load(stem.with_suffix(".joblib"))\nassert np.array_equal(bundle["training_trace_id"],trace_id[train])\nnull_kernel=bundle["null_kernel"]\nactive_probability=bundle["active_probability"]\nstate_n=period_n+1\nstate_kernel=np.concatenate([active_kernel,null_kernel[:,None]],axis=1)\n# Existing nonzero posterior entries retain the complete active-active\n# likelihood up to a per-record normalizer. One unchanged anchor likelihood\n# restores that normalizer, avoiding a repeated fit or full healthy inference.\nold_joint=parent["joint_mass"][:,1]\nassert (old_joint>0.).all()\nold_relative_evidence=np.log(old_joint)-np.log(prior[heldout,0,:,None])-np.log(prior[heldout,1,None,:])\nanchor=prior[heldout].mean(axis=0).argmax(axis=1)\npairs=np.concatenate([\n    np.column_stack([np.arange(period_n),np.full(period_n,period_n)]),\n    np.column_stack([np.full(period_n,period_n),np.arange(period_n)]),\n    np.full((1,2),period_n),anchor[None]],axis=0)\namplitude_n=len(parent["mixing_fraction"])\ncases=np.stack(np.meshgrid(np.arange(len(pairs)),np.arange(amplitude_n),indexing="ij"),axis=-1).reshape(-1,2)\ntensor_pairs=torch.as_tensor(pairs,dtype=torch.long)\ntensor_kernel=torch.as_tensor(state_kernel.reshape(2*state_n,length,length),dtype=torch.float64)\ntensor_noise=torch.as_tensor(parent["noise_covariance"][0],dtype=torch.float64)\ntensor_mixing=torch.as_tensor(parent["mixing_fraction"],dtype=torch.float64)\ntensor_held=torch.as_tensor(mixed[heldout].T.copy(),dtype=torch.float64)\nsignal_fraction=float(parent["signal_fraction"])\ncase_evidence=lambda case:(\n    pair:=torch.index_select(tensor_pairs,0,case[:1])[0],\n    target_kernel:=torch.index_select(tensor_kernel,0,pair[:1])[0],\n    background_kernel:=torch.index_select(tensor_kernel,0,pair[1:]+state_n)[0],\n    fraction:=torch.index_select(tensor_mixing,0,case[1:])[0],\n    covariance:=signal_fraction*(fraction*target_kernel+(1.-fraction)*background_kernel)\n        +(1.-signal_fraction)*tensor_noise,\n    cholesky:=torch.linalg.cholesky(covariance),\n    inverse_y:=torch.cholesky_solve(tensor_held,cholesky),\n    quadratic:=(tensor_held*inverse_y).sum(dim=0),\n    determinant:=2.*torch.log(cholesky.diagonal()).sum(),\n    -.5*determinant-.5*dimension*torch.log(quadratic))[-1]\nprint("PERIOD_STATE_INFERENCE","all_records",int(heldout.sum()),"new_covariance_cases",len(cases),\n    "active_active_cases_reused",period_n**2*amplitude_n,flush=True)\ncase_result=torch.vmap(case_evidence,chunk_size=state_settings["inference_chunk_size"])(\n    torch.as_tensor(cases,dtype=torch.long)).detach().numpy()\nnew_evidence=logsumexp(case_result.reshape(len(pairs),amplitude_n,len(held_rows))\n    +np.log(parent["mixing_weight"])[None,:,None],axis=1).T\nheld_evidence=np.empty((len(held_rows),state_n,state_n))\nnormalizer=new_evidence[:,-1]-old_relative_evidence[:,anchor[0],anchor[1]]\nheld_evidence[:,:period_n,:period_n]=old_relative_evidence+normalizer[:,None,None]\nheld_evidence[:,:period_n,-1]=new_evidence[:,:period_n]\nheld_evidence[:,-1,:period_n]=new_evidence[:,period_n:2*period_n]\nheld_evidence[:,-1,-1]=new_evidence[:,2*period_n]\nstate_prior=np.concatenate([prior[heldout]*active_probability[None,:,None],\n    np.broadcast_to(1.-active_probability,(len(held_rows),2))[:,:,None]],axis=-1)\njoint_logmass=held_evidence+np.log(state_prior[:,0,:,None])+np.log(state_prior[:,1,None,:])\njoint_logmass-=logsumexp(joint_logmass,axis=(1,2))[:,None,None]\nstate_joint=np.exp(joint_logmass)\nforced_logmass=held_evidence[:,:period_n,:period_n]+np.log(prior[heldout,0,:,None])+np.log(prior[heldout,1,None,:])\nforced_logmass-=logsumexp(forced_logmass,axis=(1,2))[:,None,None]\nforced_joint=np.exp(forced_logmass)\nassert np.allclose(forced_joint,old_joint,rtol=1.e-10,atol=1.e-12)\nstate_role_mass=np.stack([state_joint.sum(axis=2),state_joint.sum(axis=1)],axis=1)\nforced_role_mass=np.stack([forced_joint.sum(axis=2),forced_joint.sum(axis=1)],axis=1)\nrole_mass=np.stack([state_role_mass[:,:,:period_n],forced_role_mass,prior[heldout]],axis=1)\nunresolved_mass=np.zeros((len(held_rows),3,2))\nunresolved_mass[:,0]=state_role_mass[:,:,-1]\nassert np.allclose(role_mass.sum(axis=-1)+unresolved_mass,1.)\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nrole_selected=role_score.argmax(axis=-1)\nrole_estimate=periods[role_selected]\nrole_confidence=np.take_along_axis(role_score,role_selected[...,None],axis=-1)[...,0]\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\nmethods=np.array(state_settings["methods"])\npredictions=pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],len(methods)),\n    "method":np.tile(methods,len(held_rows)),"estimate_h":estimate.ravel(),"confidence":confidence.ravel(),\n    "heldout_fold":fold,"heldout_run":np.repeat(run[heldout],len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,\n    mask=mask[heldout],periods=periods,methods=methods,mass=mass,estimate=estimate,confidence=confidence,\n    role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,\n    unresolved_mass=unresolved_mass,joint_mass=state_joint,held_evidence=held_evidence,\n    state_prior=state_prior,source_kernel=state_kernel,noise_covariance=parent["noise_covariance"],\n    training_trace_id=trace_id[train],training_groups=training_groups,\n    active_probability=active_probability,null_parameters=bundle["parameters"][:2],\n    confidence_definition="joint_probability_of_resolved_target_period_within_tolerance")\nprint("PERIOD_STATE_REUSE_CHECK","maximum_forced_control_difference",np.max(np.abs(forced_joint-old_joint)),\n    "posterior_unresolved_quantiles",np.quantile(unresolved_mass[:,0],[0,.1,.5,.9,1.],axis=0).tolist(),flush=True)\nexec(compile(structural_source_readout_stage[\n    structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
exec(compile({True:structural_period_state_predict_stage,False:""}[args.stage=="structural-period-state-predict"],__file__,"exec"))

structural_crossed_period_feature_stage = '\n# Joint harmonic coefficients remove the arbitrary common phase while retaining\n# the relative second-harmonic phase and the two harmonic powers.\nphase_operator=(harmonic@np.linalg.inv(source_gram)).transpose(1,0,2).reshape(length,-1)\nphase_features=lambda waves,operator:(\n    coefficient:=(waves@operator).reshape(len(waves),period_n,4),\n    first:=coefficient[:,:,0]-1j*coefficient[:,:,1],\n    second:=coefficient[:,:,2]-1j*coefficient[:,:,3],\n    first_power:=np.abs(first)**2,\n    second_power:=np.abs(second)**2,\n    coupling:=second*np.conj(first)**2/(first_power+second_power)**1.5,\n    np.stack([first_power,second_power,coupling.real,coupling.imag],axis=-1).reshape(len(waves),-1))[-1]\nobserved_features=phase_features(training_mixture,phase_operator)\nphase_mean=np.einsum("n,nf->f",row_weight,observed_features)\nphase_sd=np.sqrt(np.einsum("n,nf->f",row_weight,(observed_features-phase_mean)**2))\nassert np.isfinite(observed_features).all() and np.all(phase_sd>0.)\nperiod_input_transform=lambda waves:(phase_features(waves,phase_operator)-phase_mean)/phase_sd\n# Changing only the coordinate origin must leave these features unchanged.\nshifted_angle=2.*np.pi*(time-time.mean())[None,:,None]/periods[:,None,None]*harmonic_index[None,None]\nshifted_harmonic=np.sqrt(2.)*np.stack([np.cos(shifted_angle),np.sin(shifted_angle)],axis=-1).reshape(period_n,length,4)\nshifted_harmonic-=np.einsum("ti,pij->ptj",base[0],np.einsum("ti,ptj->pij",base[0],shifted_harmonic))\nshifted_gram=np.einsum("pti,ptj->pij",shifted_harmonic,shifted_harmonic)\nshifted_operator=(shifted_harmonic@np.linalg.inv(shifted_gram)).transpose(1,0,2).reshape(length,-1)\nshifted_features=phase_features(training_mixture,shifted_operator)\nassert np.allclose(shifted_features,observed_features,rtol=1.e-10,atol=1.e-12)\ninput_state={"mode":"phase_invariant","operator":phase_operator,"mean":phase_mean,"sd":phase_sd}\nprint("PHASE_INPUT",len(train_rows),observed_features.shape[1],\n    "origin_shift_max_error",float(np.max(np.abs(shifted_features-observed_features))),flush=True)\n'
structural_crossed_period_all_window_stage = '\nfrom numpy.lib.stride_tricks import sliding_window_view\n# Reuse every complete observed window from the existing training records.\n# Window replication changes neither a record\'s total weight nor the held-out split.\nwindow_code=structural_moving_sphere_flow_setup_stage[\n    structural_moving_sphere_flow_setup_stage.index("record_weight=row_weight.copy()"):\n    structural_moving_sphere_flow_setup_stage.index("source_coordinate=source_unit@coordinate_basis")]\nwindow_code=window_code.replace(\n    \'columns=["trace_id","time_h","published_target_y","green","red"]\',\n    \'columns=["trace_id","time_h","published_target_y","green","red","no"]\',1)\nwindow_scope=dict(globals())\nexec(compile(window_code,__file__,"exec"),window_scope)\nfull_no=window_scope["full_optical"].pivot(index="trace_id",columns="time_h",values="no").reindex(\n    index=trace_id[train],columns=window_scope["full_time"]).to_numpy(dtype=float)\ntraining_mixture=sliding_window_view(full_no,length,axis=-1)[window_scope["valid_window"]]\ntraining_mixture-=(training_mixture@base[0])@base[0].T\ntraining_mixture/=np.sqrt(np.mean(training_mixture**2,axis=-1))[:,None]\ntraining_window_record=window_scope["window_record"]\ntraining_window_start=window_scope["full_time"][window_scope["window_start"]]\ncommon_window=training_window_start==optical_time[0]\nassert np.allclose(training_mixture[common_window],mixed[train],atol=1.e-10)\nsource_unit=window_scope["source_unit"]\nrow_weight=window_scope["window_weight"]\ntrain_rows=train_rows[training_window_record]\nassert np.isfinite(training_mixture).all()\nassert np.array_equal(np.unique(training_window_record),np.arange(int(train.sum())))\nassert input_mode=="phase_invariant"\ncrossed_settings["stem"]=crossed_settings["all_window_stem"]\ncrossed_settings["methods"]=crossed_settings["all_window_methods"]\ncrossed_settings["training"]="all_actual_training_windows_with_record_and_experiment_weight_preserved"\nprint("ALL_OBSERVED_PERIOD_WINDOWS","records",int(train.sum()),"windows",len(training_mixture),\n    "experiments",len(training_groups),"weight_total",float(row_weight.sum()),flush=True)\n'
structural_crossed_period_hybrid_setup_stage = '\nassert args.period_training_window=="all_observed" and input_mode=="phase_invariant"\nhybrid_rows=np.flatnonzero(training_window_start==optical_time[0])\nassert np.array_equal(training_window_record[hybrid_rows],np.arange(int(train.sum())))\nhybrid_weight=np.bincount(training_window_record,weights=row_weight)\nassert np.isclose(hybrid_weight.sum(),1.)\ncommon_source_prior=np.einsum("n,nrp->rp",hybrid_weight,source_mass[hybrid_rows])\nsource_prior=crossed_settings["natural_weight"]*source_prior+(1.-crossed_settings["natural_weight"])*common_source_prior\nassert np.allclose(source_prior.sum(axis=-1),1.)\ncrossed_settings["stem"]=crossed_settings["hybrid_stem"]\ncrossed_settings["methods"]=crossed_settings["hybrid_methods"]\ncrossed_settings["training"]="all_actual_windows_plus_complete_common_window_background_replacements"\n'
structural_crossed_period_hybrid_training_stage = '\n# The natural term uses every actual training window. The replacement term uses\n# the complete original common-window Cartesian product, with every record kept.\nhybrid_n=len(hybrid_rows)\nhybrid_source=source_unit[hybrid_rows]\nhybrid_gain=gain[hybrid_rows]\nhybrid_anchor=anchor_remainder[hybrid_rows]\ncounterfactual=hybrid_anchor[:,None]+hybrid_gain[:,1,None,None]*hybrid_source[None,:,1]\ncounterfactual/=np.sqrt(np.mean(counterfactual**2,axis=-1))[...,None]\nassert np.allclose(counterfactual[np.arange(hybrid_n),np.arange(hybrid_n)],mixed[train],rtol=1.e-10,atol=1.e-12)\npair_weight=hybrid_weight[:,None]*hybrid_weight[None]\nassert np.allclose(pair_weight.sum(axis=0),hybrid_weight) and np.allclose(pair_weight.sum(axis=1),hybrid_weight)\ntensor_crossed=torch.as_tensor(period_input_transform(counterfactual.reshape(-1,length)),dtype=torch.float64)\ntensor_pair_weight=torch.as_tensor(pair_weight,dtype=torch.float64)\ntensor_crossed_mass=torch.as_tensor(source_mass[hybrid_rows],dtype=torch.float64)\ncrossed_objective=lambda vector:(\n    logmass:=torch.log_softmax(forward(vector,tensor_crossed).reshape(hybrid_n,hybrid_n,2,period_n),dim=-1),\n    target_loss:=-(logmass[:,:,0]*tensor_crossed_mass[:,None,0]).sum(dim=-1),\n    background_loss:=-(logmass[:,:,1]*tensor_crossed_mass[None,:,1]).sum(dim=-1),\n    (tensor_pair_weight*(target_loss+background_loss)).sum()/2.)[-1]\ndata_objective=lambda vector:crossed_settings["natural_weight"]*natural_objective(vector) \\\n    +(1.-crossed_settings["natural_weight"])*crossed_objective(vector)\npair_n=hybrid_n**2\n'
structural_crossed_period_peer_feature_stage = '\n# Every peer mean uses the other observed records at the same experimental time\n# window. No target or background optical values enter these context features.\nperiod_peer_wave=lambda waves,groups:(\n    group_index:=pd.factorize(groups,sort=True)[0],\n    group_count:=np.bincount(group_index),\n    group_sum:=np.zeros((len(group_count),waves.shape[-1])),\n    np.add.at(group_sum,group_index,waves),\n    peer:=(group_sum[group_index]-waves)/(group_count[group_index,None]-1.),\n    peer/np.sqrt(np.mean(peer**2,axis=-1))[:,None])[-1]\ntraining_peer_groups=pd.MultiIndex.from_arrays([\n    run[train][training_window_record],training_window_start])\ntraining_peer=period_peer_wave(training_mixture,training_peer_groups)\nassert np.isfinite(training_peer).all()\npaired_phase_features=lambda waves,peers,operator:(\n    coefficient:=(np.stack([waves,peers],axis=1)@operator).reshape(len(waves),2,period_n,4),\n    first:=coefficient[...,0]-1j*coefficient[...,1],\n    second:=coefficient[...,2]-1j*coefficient[...,3],\n    first_power:=np.abs(first)**2,\n    second_power:=np.abs(second)**2,\n    total_power:=first_power+second_power,\n    coupling:=second*np.conj(first)**2/total_power**1.5,\n    individual:=np.stack([first_power,second_power,coupling.real,coupling.imag],axis=-1)\n        .transpose(0,2,1,3).reshape(len(waves),period_n,8),\n    cross:=np.stack([first[:,0]*np.conj(first[:,1]),second[:,0]*np.conj(second[:,1])],axis=-1)\n        /np.sqrt(total_power[:,0]*total_power[:,1])[...,None],\n    np.concatenate([individual,np.stack([cross.real,cross.imag],axis=-1).reshape(len(waves),period_n,4)],axis=-1))[-1]\nshared_features=paired_phase_features(training_mixture,training_peer,phase_operator)\nshifted_paired=paired_phase_features(training_mixture,training_peer,shifted_operator)\nassert np.allclose(shared_features,shifted_paired,rtol=1.e-10,atol=1.e-12)\nprint("SHARED_PEER_INPUT","records",int(train.sum()),"windows",len(training_mixture),\n    "features_per_period",shared_features.shape[-1],\n    "origin_shift_max_error",float(np.max(np.abs(shared_features-shifted_paired))),flush=True)\n'
structural_crossed_period_shared_feature_stage = '\n# The score function is shared across candidate periods. The empirical prior\n# retains the absolute-period information for each named optical source.\nassert args.period_input=="phase_invariant" and args.period_training_window=="all_observed"\nassert args.remixing_objective=="observed"\nshared_features=observed_features.reshape(len(train_rows),period_n,-1)\nexec(compile({"individual":"","peer":structural_crossed_period_peer_feature_stage}[args.period_context],__file__,"exec"))\nshared_mean=np.einsum("n,npf->f",row_weight,shared_features)/period_n\nshared_sd=np.sqrt(np.einsum("n,npf->f",row_weight,(shared_features-shared_mean)**2)/period_n)\nassert np.all(shared_sd>0.) and np.isfinite(shared_sd).all()\nperiod_input_transform={\n    "individual":lambda waves:(phase_features(waves,phase_operator).reshape(len(waves),period_n,-1)-shared_mean)/shared_sd,\n    "peer":lambda pair:(paired_phase_features(pair[0],pair[1],phase_operator)-shared_mean)/shared_sd}[args.period_context]\ninput_state={"mode":"phase_invariant","layout":"candidate_shared","context":args.period_context,\n    "operator":phase_operator,"mean":shared_mean,"sd":shared_sd}\ncrossed_settings["stem"]=crossed_settings[{"individual":"shared_stem","peer":"peer_shared_stem"}[args.period_context]]\ncrossed_settings["methods"]=crossed_settings[{"individual":"shared_methods","peer":"peer_shared_methods"}[args.period_context]]\ncrossed_settings["representation"]="same_evidence_function_at_each_candidate_period_with_fixed_empirical_prior"\n'
structural_crossed_period_setup_stage = '\nfrom scipy.optimize import minimize\nfrom scipy.special import softmax\nfrom joblib import load,dump\nimport torch\nfrom torch import nn\n# The existing common-window input loader is used for either held-out native\n# experiments or the external cohort. Optical reads remain limited to train.\ncommon_prefix=structural_phase_source_training_stage[\n    :structural_phase_source_training_stage.index("source_objective =")]\ncommon_prefix=common_prefix.replace(\'exec(compile(structural_source_data_stage,__file__,"exec"))\',\n    \'exec(compile(structural_source_data_stage.replace(\'\n    \'\\\'native = fold<application["lemna_expected_runs"]\\\',\\\'native = False\\\'),__file__,"exec"))\')\nexec(compile(common_prefix,__file__,"exec"))\ncrossed_settings=dict(application["structural_crossed_period"])\ninput_mode=args.period_input\ncrossed_settings["stem"]={"raw":crossed_settings["stem"],"phase_invariant":crossed_settings["invariant_stem"]}[input_mode]\ncrossed_settings["methods"]={"raw":crossed_settings["methods"],"phase_invariant":crossed_settings["invariant_methods"]}[input_mode]\ncrossed_settings["period_input"]=input_mode\nnative_evaluation=fold<application["lemna_expected_runs"]\nassert np.all(count==length) and not np.intersect1d(trace_id[train],trace_id[heldout]).size\ntraining_mixture=mixed[train]\ntraining_window_record=np.arange(len(train_rows))\ntraining_window_start=np.full(len(train_rows),optical_time[0])\ncrossed_settings["period_training_window"]=args.period_training_window\nexec(compile({"common":"","all_observed":structural_crossed_period_all_window_stage}[\n    args.period_training_window],__file__,"exec"))\n\nteacher_code=structural_source_readout_stage.split("prior_labels =",1)[0]\nteacher_code=teacher_code.replace("waves = np.stack([prediction,mixed[heldout]],axis=1)","waves = source_unit")\nteacher_code=teacher_code.replace("held_mask = mask[heldout]","held_mask = np.ones((len(train_rows),length),dtype=bool)")\nteacher_code=teacher_code.replace("held_count = count[heldout]","held_count = np.full(len(train_rows),length,dtype=int)")\nteacher_scope=dict(globals())\nexec(compile(teacher_code,__file__,"exec"),teacher_scope)\nassert np.array_equal(teacher_scope["periods"],periods)\nsource_mass=softmax(teacher_scope["log_evidence"].reshape(len(train_rows),2,period_n)\n    +np.log(teacher_scope["grid_weight"])[None,None],axis=-1)\nsource_prior=np.einsum("n,nrp->rp",row_weight,source_mass)\nassert np.allclose(source_mass.sum(axis=-1),1.) and np.allclose(source_prior.sum(axis=-1),1.)\nexec(compile({"observed":"","crossed":"","hybrid":structural_crossed_period_hybrid_setup_stage}[\n    args.remixing_objective],__file__,"exec"))\ntrain_n=len(train_rows)\noptical_pair=source_unit.transpose(0,2,1)\ngain=np.linalg.solve(np.einsum("nti,ntj->nij",optical_pair,optical_pair),\n    np.einsum("nti,nt->ni",optical_pair,training_mixture)[...,None])[...,0]\nanchor_remainder=training_mixture-gain[:,1,None]*source_unit[:,1]\nexec(compile({"raw":\'period_input_transform=lambda waves:waves\\ninput_state={"mode":"raw"}\',\n    "phase_invariant":structural_crossed_period_feature_stage}[input_mode],__file__,"exec"))\ncrossed_settings["period_head"]=args.period_head\ncrossed_settings["period_context"]=args.period_context\nassert args.period_context=="individual" or args.period_head=="shared"\nexec(compile({"global":"","shared":structural_crossed_period_shared_feature_stage}[args.period_head],__file__,"exec"))\ntraining_input={"individual":lambda:training_mixture,"peer":lambda:(training_mixture,training_peer)}[args.period_context]()\nobserved_inputs=period_input_transform(training_input)\ninput_n=observed_inputs.shape[-1]\ntensor_observed=torch.as_tensor(observed_inputs,dtype=torch.float64)\ntensor_source_mass=torch.as_tensor(source_mass,dtype=torch.float64)\ntensor_weight=torch.as_tensor(row_weight,dtype=torch.float64)\ntorch.manual_seed(crossed_settings["seed"])\nwidth=crossed_settings["width"]\noutput_n={"global":2*period_n,"shared":2}[args.period_head]\nnetwork=nn.Sequential(nn.Linear(input_n,width),nn.Tanh(),\n    nn.Linear(width,width),nn.Tanh(),nn.Linear(width,output_n)).double()\nnn.init.zeros_(network[-1].weight)\ninitial_bias={"global":np.log(source_prior).ravel(),"shared":np.zeros(2)}[args.period_head]\nnetwork[-1].bias.data.copy_(torch.as_tensor(initial_bias,dtype=torch.float64))\nparameter_names=tuple(dict(network.named_parameters()))\nparameter_shapes=tuple(map(torch.Tensor.size,network.parameters()))\nparameter_sizes=tuple(map(torch.Tensor.numel,network.parameters()))\ninitial=nn.utils.parameters_to_vector(network.parameters()).detach().numpy()\nunpack=lambda vector:dict(zip(parameter_names,map(torch.reshape,torch.split(vector,parameter_sizes),parameter_shapes)))\ntensor_log_prior=torch.as_tensor(np.log(source_prior),dtype=torch.float64)\nforward={"global":lambda vector,inputs:torch.func.functional_call(network,unpack(vector),(inputs,)).reshape(-1,2,period_n),\n    "shared":lambda vector,inputs:torch.func.functional_call(network,unpack(vector),(inputs,)).transpose(-1,-2)+tensor_log_prior}[args.period_head]\nnatural_objective=lambda vector:-(tensor_weight[:,None,None]*tensor_source_mass\n    *torch.log_softmax(forward(vector,tensor_observed),dim=-1)).sum()/2.\nstem=crossed_settings["stem"].with_name(crossed_settings["stem"].name+"_common_fold"+str(fold))\n'
structural_crossed_period_training_stage = '\n# The complete Cartesian product removes the observed target-background pairing.\n# Each target retains its measured gain and original measurement remainder.\ncounterfactual=anchor_remainder[:,None]+gain[:,1,None,None]*source_unit[None,:,1]\ncounterfactual/=np.sqrt(np.mean(counterfactual**2,axis=-1))[...,None]\nassert np.allclose(counterfactual[np.arange(train_n),np.arange(train_n)],training_mixture,rtol=1.e-10,atol=1.e-12)\npair_weight=row_weight[:,None]*row_weight[None]\nassert np.allclose(pair_weight.sum(axis=0),row_weight) and np.allclose(pair_weight.sum(axis=1),row_weight)\ntensor_crossed=torch.as_tensor(period_input_transform(counterfactual.reshape(-1,length)),dtype=torch.float64)\ntensor_pair_weight=torch.as_tensor(pair_weight,dtype=torch.float64)\ncrossed_objective=lambda vector:(\n    logmass:=torch.log_softmax(forward(vector,tensor_crossed).reshape(train_n,train_n,2,period_n),dim=-1),\n    target_loss:=-(logmass[:,:,0]*tensor_source_mass[:,None,0]).sum(dim=-1),\n    background_loss:=-(logmass[:,:,1]*tensor_source_mass[None,:,1]).sum(dim=-1),\n    (tensor_pair_weight*(target_loss+background_loss)).sum()/2.)[-1]\ndata_objective=lambda vector:crossed_settings["natural_weight"]*natural_objective(vector) \\\n    +(1.-crossed_settings["natural_weight"])*crossed_objective(vector)\npair_n=train_n**2\n'
structural_crossed_period_fit_stage = '\nexec(compile(structural_crossed_period_setup_stage,__file__,"exec"))\ntraining_mode=args.remixing_objective\nassert args.period_training_window=="common" or training_mode in ("observed","hybrid")\nexec(compile({"observed":"data_objective=natural_objective\\npair_n=0",\n    "crossed":structural_crossed_period_training_stage,\n    "hybrid":structural_crossed_period_hybrid_training_stage}[training_mode],__file__,"exec"))\nobjective=lambda vector:data_objective(vector)+crossed_settings["weight_decay"]*vector.square().mean()\nautograd_objective=torch.func.grad_and_value(objective)\nto_scipy=lambda gradient,value:(value.detach().item(),gradient.detach().numpy())\nscipy_objective=lambda vector:to_scipy(*autograd_objective(torch.from_numpy(vector)))\ninitial_loss,initial_gradient=scipy_objective(initial)\nexpected_initial=-np.sum(source_prior*np.log(source_prior))/2. \\\n    +crossed_settings["weight_decay"]*np.mean(initial**2)\nassert np.isclose(initial_loss,expected_initial,rtol=1.e-10,atol=1.e-12) and np.isfinite(initial_gradient).all()\nloss_history=[[0,initial_loss]]\nprint("CROSSED_PERIOD_TRAIN","fold",fold,"mode",training_mode,"input",input_mode,"actual_cells",int(train.sum()),"training_windows",train_n,\n    "experiments",len(training_groups),"counterfactual_pairs",pair_n,"parameters",len(initial),\n    "initial_loss",initial_loss,"prior_entropy_check",expected_initial,"seed",crossed_settings["seed"],flush=True)\nresult=minimize(scipy_objective,initial,jac=True,method="L-BFGS-B",\n    callback=lambda intermediate_result:(loss_history.append([len(loss_history),float(intermediate_result.fun)]),\n        len(loss_history)%25==0 and print("CROSSED_PERIOD_PROGRESS",fold,training_mode,\n            len(loss_history)-1,float(intermediate_result.fun),flush=True)),\n    options={"maxiter":crossed_settings["maxiter"],"ftol":crossed_settings["ftol"],\n        "gtol":crossed_settings["gtol"],"maxls":crossed_settings["maxls"]})\nparameters=torch.as_tensor(result.x,dtype=torch.float64)\nnatural_loss=float(natural_objective(parameters).detach())\nassert np.isfinite(result.fun) and np.isfinite(result.x).all()\ndump({"parameters":result.x,"parameter_names":parameter_names,"parameter_shapes":parameter_shapes,\n    "optimization":result,"loss_history":np.asarray(loss_history),"source_prior":source_prior,\n    "training_trace_id":trace_id[train],"training_window_record":training_window_record,\n    "training_window_start_h":training_window_start,"training_groups":training_groups,"training_weight":row_weight,\n    "source_period_mass":source_mass,"configuration":crossed_settings,"training_mode":training_mode,\n    "input_state":input_state,"counterfactual_pair_count":pair_n,"natural_training_crossentropy":natural_loss,\n    "mix_formula":"No_i-b_i*B_i+b_i*B_j; target_period=i; background_period=j",\n    "heldout_optical_read":False,"seed":crossed_settings["seed"]},\n    stem.with_name(stem.name+"_"+training_mode).with_suffix(".joblib"))\nprint("CROSSED_PERIOD_FIT","fold",fold,"mode",training_mode,"iterations",result.nit,\n    "loss",result.fun,"natural_crossentropy",natural_loss,"status",str(result.message),flush=True)\nraise SystemExit(0)\n'
exec(compile({True:structural_crossed_period_fit_stage,False:""}[args.stage=="structural-crossed-period-fit"],__file__,"exec"))
structural_crossed_period_predict_stage = '\nexec(compile(structural_crossed_period_setup_stage,__file__,"exec"))\nprediction_modes={"common":("observed","crossed"),"all_observed":("observed",)}[args.period_training_window]\nprediction_modes={"observed":prediction_modes,"crossed":prediction_modes,"hybrid":("hybrid",)}[args.remixing_objective]\nmodel_bundles=tuple(map(lambda mode:load(stem.with_name(stem.name+"_"+mode).with_suffix(".joblib")),prediction_modes))\nassert all(map(lambda bundle:np.array_equal(bundle["training_trace_id"],trace_id[train]),model_bundles))\nassert all(map(lambda bundle:np.allclose(bundle["source_prior"],source_prior),model_bundles))\nmodel_parameters=torch.as_tensor(np.stack(tuple(map(lambda bundle:bundle["parameters"],model_bundles))),dtype=torch.float64)\nquery_input={"individual":lambda:mixed[heldout],\n    "peer":lambda:(mixed[heldout],period_peer_wave(mixed[heldout],run[heldout]))}[args.period_context]()\ntensor_held=torch.as_tensor(period_input_transform(query_input),dtype=torch.float64)\nmodel_mass=torch.vmap(lambda vector:torch.softmax(forward(vector,tensor_held),dim=-1))(\n    model_parameters).detach().numpy().transpose(1,0,2,3)\nrole_mass=np.concatenate([model_mass,np.broadcast_to(source_prior,(len(held_rows),1,2,period_n))],axis=1)\nassert np.allclose(role_mass.sum(axis=-1),1.) and np.isfinite(role_mass).all()\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nrole_selected=role_score.argmax(axis=-1)\nrole_estimate=periods[role_selected]\nrole_confidence=np.take_along_axis(role_score,role_selected[...,None],axis=-1)[...,0]\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\nmethods=np.array(crossed_settings["methods"])\npredictions=pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],len(methods)),\n    "method":np.tile(methods,len(held_rows)),"estimate_h":estimate.ravel(),"confidence":confidence.ravel(),\n    "heldout_fold":fold,"heldout_run":np.repeat(run[heldout],len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,\n    mask=mask[heldout],periods=periods,methods=methods,mass=mass,estimate=estimate,confidence=confidence,\n    role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,\n    source_prior=source_prior,raw_waveform=mixed[heldout],period_input=input_mode,period_training_window=args.period_training_window,period_context=args.period_context,\n    training_trace_id=trace_id[train],training_groups=training_groups,\n    evaluation_layout="existing_common_24_96h_window",\n    confidence_definition="learned_conditional_optical_source_period_window_mass")\nnative=native_evaluation\nexec(compile(structural_source_readout_stage[\n    structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
exec(compile({True:structural_crossed_period_predict_stage,False:""}[args.stage=="structural-crossed-period-predict"],__file__,"exec"))


structural_residual_transport_stage = '\nfrom joblib import dump\nfrom scipy.special import softmax\ncommon_prefix=structural_phase_source_training_stage[:structural_phase_source_training_stage.index("source_objective =")]\ncommon_prefix=common_prefix.replace(\'exec(compile(structural_source_data_stage,__file__,"exec"))\',\n    \'exec(compile(structural_source_data_stage.replace(\\\'native = fold<application["lemna_expected_runs"]\\\',\\\'native = False\\\'),__file__,"exec"))\')\nexec(compile(common_prefix,__file__,"exec"))\nnative_evaluation=fold<application["lemna_expected_runs"]\nresidual_settings=application["structural_residual_transport"]\nstem=residual_settings["stem"].with_name(residual_settings["stem"].name+"_common_fold"+str(fold))\nassert np.all(count==length) and not np.intersect1d(trace_id[train],trace_id[heldout]).size\npeer=peer_mean/np.sqrt(np.mean(peer_mean**2,axis=-1))[:,None]\npredictor=np.concatenate([mixed,peer],axis=-1)\ntraining_x=predictor[train]\ntraining_y=source_unit.reshape(len(train_rows),-1)\ntraining_groups,group_index,group_n=np.unique(run[train],return_inverse=True,return_counts=True)\ngroup_membership=(np.arange(len(training_groups))[:,None]==group_index[None]).astype(float)\ngroup_weight=group_membership/group_n[:,None]\ngroup_mean_x=group_weight@training_x\ngroup_mean_y=group_weight@training_y\ngroup_second=np.einsum("gn,ni,nj->gij",group_weight,training_x,training_x,optimize=True)\ngroup_cross=np.einsum("gn,ni,nj->gij",group_weight,training_x,training_y,optimize=True)\n# Fit the full training law and exclude each training experiment for residuals.\n# The covariance regularizer reuses leave-experiment-out correlation shrinkage.\neligible=np.vstack([~np.eye(len(training_groups),dtype=bool),np.ones(len(training_groups),dtype=bool)])\nmodel_group_n=eligible.sum(axis=-1)\nmodel_weight=eligible/model_group_n[:,None]\nmean_x=model_weight@group_mean_x\nmean_y=model_weight@group_mean_y\nempirical=np.einsum("mg,gij->mij",model_weight,group_second)-mean_x[:,:,None]*mean_x[:,None,:]\ncross=np.einsum("mg,gij->mij",model_weight,group_cross)-mean_x[:,:,None]*mean_y[:,None,:]\nscale_x=np.sqrt(np.diagonal(empirical,axis1=-2,axis2=-1))\ncorrelation=empirical/(scale_x[:,:,None]*scale_x[:,None,:])\ninner_eligible=eligible[:,None,:]&(~np.eye(len(training_groups),dtype=bool))[None]\ninner_weight=inner_eligible/inner_eligible.sum(axis=-1,keepdims=True)\ninner_mean=np.einsum("mkg,gi->mki",inner_weight,group_mean_x)\ninner_cov=np.einsum("mkg,gij->mkij",inner_weight,group_second)-inner_mean[:,:,:,None]*inner_mean[:,:,None,:]\ninner_scale=np.sqrt(np.diagonal(inner_cov,axis1=-2,axis2=-1))\ninner_correlation=inner_cov/(inner_scale[:,:,:,None]*inner_scale[:,:,None,:])\ninner_mean_correlation=np.einsum("mk,mkij->mij",model_weight,inner_correlation)\nbeta=(model_group_n-1.)*np.einsum("mk,mkij->m",model_weight,\n    (inner_correlation-inner_mean_correlation[:,None])**2)\nidentity=np.eye(training_x.shape[-1])\ndelta=np.sum((correlation-identity)**2,axis=(-2,-1))\nshrinkage=np.minimum(beta/delta,1.)\nshrunk=(1.-shrinkage[:,None,None])*correlation+shrinkage[:,None,None]*identity\ncoefficient=np.linalg.solve(shrunk,(1.-shrinkage[:,None,None])*cross/scale_x[:,:,None])\nassert np.isfinite(coefficient).all() and np.allclose(np.diagonal(inner_correlation,axis1=-2,axis2=-1),1.)\ncrossfit_mean=mean_y[group_index]+np.einsum("ni,nij->nj",\n    (training_x-mean_x[group_index])/scale_x[group_index],coefficient[group_index])\nresidual=(training_y-crossfit_mean).reshape(len(train_rows),2,length)\nassert np.allclose(row_weight,group_weight.mean(axis=0))\ndump({"coefficient":coefficient[-1],"mean_x":mean_x[-1],"mean_y":mean_y[-1],\n    "scale_x":scale_x[-1],"crossfit_residual":residual,"residual_weight":row_weight,\n    "crossfit_mean":crossfit_mean.reshape(len(train_rows),2,length),"shrinkage":shrinkage,\n    "training_trace_id":trace_id[train],"training_groups":training_groups,\n    "target":"two_optically_named_unit_RMS_source_waveforms",\n    "residual_law":"empirical_leave_experiment_out_residuals_assumed_transportable",\n    "regularization":"leave_experiment_out_correlation_jackknife_shrinkage",\n    "literature":residual_settings["literature"]},stem.with_suffix(".joblib"))\nmean_prediction=(mean_y[-1]+((predictor[heldout]-mean_x[-1])/scale_x[-1])@coefficient[-1]).reshape(len(held_rows),2,length)\ntransported=mean_prediction[:,None]+residual[None]\n# Integrate the existing H1 readout over every empirical residual atom.\n# This is a predictive distribution approximation, not an exact source posterior.\nreadout_waves=np.concatenate([transported.reshape(-1,2,length),mean_prediction,source_unit],axis=0)\nreadout_scope=dict(globals())\nreadout_scope.update(readout_waves=readout_waves)\nreadout=structural_source_readout_stage.split("prior_labels =",1)[0]\nreadout=readout.replace("waves = np.stack([prediction,mixed[heldout]],axis=1)","waves = readout_waves.copy()")\nreadout=readout.replace("held_mask = mask[heldout]","held_mask = np.ones((len(readout_waves),length),dtype=bool)")\nreadout=readout.replace("held_count = count[heldout]","held_count = np.full(len(readout_waves),length,dtype=int)")\nexec(compile(readout,__file__,"exec"),readout_scope)\nassert np.array_equal(periods,readout_scope["periods"])\nall_mass=softmax(readout_scope["log_evidence"].reshape(len(readout_waves),2,period_n)\n    +np.log(readout_scope["grid_weight"])[None,None],axis=-1)\nsample_n=len(held_rows)*len(train_rows)\ntransport_mass=np.einsum("n,qnrp->qrp",row_weight,all_mass[:sample_n].reshape(len(held_rows),len(train_rows),2,period_n))\nmean_mass=all_mass[sample_n:sample_n+len(held_rows)]\nsource_prior=np.einsum("n,nrp->rp",row_weight,all_mass[sample_n+len(held_rows):])\nrole_mass=np.stack([transport_mass,mean_mass,np.broadcast_to(source_prior,transport_mass.shape)],axis=1)\nassert np.isfinite(role_mass).all() and np.allclose(role_mass.sum(axis=-1),1.)\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nrole_selected=role_score.argmax(axis=-1)\nrole_estimate=periods[role_selected]\nrole_confidence=np.take_along_axis(role_score,role_selected[...,None],axis=-1)[...,0]\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\nmethods=np.array(residual_settings["methods"])\npredictions=pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],len(methods)),\n    "method":np.tile(methods,len(held_rows)),"estimate_h":estimate.ravel(),"confidence":confidence.ravel(),\n    "heldout_fold":fold,"heldout_run":np.repeat(run[heldout],len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,\n    mask=mask[heldout],periods=periods,methods=methods,mass=mass,estimate=estimate,confidence=confidence,\n    role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,\n    source_prior=source_prior,source_pair_mean=mean_prediction+np.einsum("n,nrt->rt",row_weight,residual)[None],\n    regression_source_mean=mean_prediction,raw_waveform=mixed[heldout],\n    training_trace_id=trace_id[train],training_groups=training_groups,\n    evaluation_layout="existing_common_24_96h_window",\n    confidence_definition="empirical_residual_transport_optical_source_period_window_mass")\nprint("RESIDUAL_TRANSPORT","fold",fold,"training_records",len(train_rows),"held_records",len(held_rows),\n    "all_residual_atoms",len(residual),"shrinkage_quantiles",np.quantile(shrinkage,[0.,.5,1.]).tolist(),flush=True)\nnative=native_evaluation\nexec(compile(structural_source_readout_stage[structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
exec(compile({True:structural_residual_transport_stage,False:""}[args.stage=="structural-residual-transport"],__file__,"exec"))


structural_multicell_period_stage = '\nfrom scipy.optimize import minimize\nfrom scipy.special import softmax\nfrom joblib import dump\nimport torch\nfrom torch import nn\ncommon_prefix=structural_phase_source_training_stage[:structural_phase_source_training_stage.index("source_objective =")]\ncommon_prefix=common_prefix.replace(\'exec(compile(structural_source_data_stage,__file__,"exec"))\',\n    \'exec(compile(structural_source_data_stage.replace(\\\'native = fold<application["lemna_expected_runs"]\\\',\\\'native = False\\\'),__file__,"exec"))\')\nexec(compile(common_prefix,__file__,"exec"))\nnative_evaluation=fold<application["lemna_expected_runs"]\nmulticell_settings=application["structural_multicell_period"]\nfit_settings=application["structural_crossed_period"]\nstem=multicell_settings["stem"].with_name(multicell_settings["stem"].name+"_common_fold"+str(fold))\nassert np.all(count==length) and not np.intersect1d(trace_id[train],trace_id[heldout]).size\ntraining_mixture=mixed[train]\nexec(compile(structural_crossed_period_feature_stage,__file__,"exec"))\nraw_features=phase_features(mixed,phase_operator).reshape(len(mixed),period_n,4)\ngroups,group_index,group_n=np.unique(run,return_inverse=True,return_counts=True)\ngroup_weight=(np.arange(len(groups))[:,None]==group_index[None])/group_n[:,None]\nempirical=np.einsum("gn,nt,nu->gtu",group_weight,mixed,mixed,optimize=True)\nnorm_covariance=np.sum(empirical**2,axis=(-2,-1))\nbeta=(length**2-norm_covariance)/(length*group_n)\ndelta=(norm_covariance-length)/length\nshrinkage=np.minimum(beta/delta,1.)\ncovariance=(1.-shrinkage[:,None,None])*empirical+shrinkage[:,None,None]*np.eye(length)\neigenvalue,eigenvector=np.linalg.eigh(covariance)\nassert np.all(eigenvalue>0.) and np.all((shrinkage>0.)&(shrinkage<1.))\ninverse_root=(eigenvector/np.sqrt(eigenvalue)[:,None])@eigenvector.transpose(0,2,1)\nwhite_wave=np.einsum("nt,ntu->nu",mixed,inverse_root[group_index],optimize=True)\nwhite_wave/=np.sqrt(np.mean(white_wave**2,axis=-1))[:,None]\nwhite_features=phase_features(white_wave,phase_operator).reshape(len(mixed),period_n,4)\n# Population Capon variance retains every covariance direction. Its two\n# harmonic blocks are compared with the corresponding ordinary population power.\noperator=phase_operator.reshape(length,period_n,4).transpose(1,0,2)\nordinary=np.einsum("pti,gtu,pui->gpi",operator,empirical,operator,optimize=True)\nprecision=inverse_root@inverse_root\ncapon_gram=np.einsum("pti,gtu,puj->gpij",harmonic,precision,harmonic,optimize=True)\ncapon_variance=np.diagonal(np.linalg.inv(capon_gram),axis1=-2,axis2=-1)\npopulation_features=np.log(np.concatenate([\n    ordinary.reshape(len(groups),period_n,2,2).sum(axis=-1),\n    capon_variance.reshape(len(groups),period_n,2,2).sum(axis=-1)],axis=-1))\nassert np.isfinite(population_features).all()\n# AMUSE-style one-step temporal ordering is used only as a representation.\n# All modes are retained, with squared lag correlation as a continuous weight.\n# The source-role score below is supervised; no mode is assigned a role by rank.\ngroup_order=np.argsort(group_index,kind="stable")\nlocal_index=np.empty(len(mixed),dtype=int)\nlocal_index[group_order]=np.arange(len(mixed))-np.repeat(np.r_[0,np.cumsum(group_n)[:-1]],group_n)\nmax_n=int(group_n.max())\ngroup_wave=np.zeros((len(groups),max_n,length))\ngroup_wave[group_index,local_index]=mixed\nspatial_covariance=group_wave@group_wave.transpose(0,2,1)/length\nspatial_covariance=(1.-shrinkage[:,None,None])*spatial_covariance+shrinkage[:,None,None]*np.eye(max_n)\nspatial_value,spatial_vector=np.linalg.eigh(spatial_covariance)\nspatial_inverse_root=(spatial_vector/np.sqrt(spatial_value)[:,None])@spatial_vector.transpose(0,2,1)\nlag_cross=group_wave[:,:,:-1]@group_wave[:,:,1:].transpose(0,2,1)/(length-1.)\nlag_covariance=(1.-shrinkage[:,None,None])*(lag_cross+lag_cross.transpose(0,2,1))/2.\nlag_white=spatial_inverse_root@lag_covariance@spatial_inverse_root\nlag_value,lag_vector=np.linalg.eigh(lag_white)\nmode_wave=lag_vector.transpose(0,2,1)@spatial_inverse_root@group_wave\nmode_rms=np.sqrt(np.mean(mode_wave**2,axis=-1))\nmode_unit=np.divide(mode_wave,mode_rms[...,None],out=np.zeros_like(mode_wave),where=mode_rms[...,None]>0.)\nmode_coefficient=(mode_unit@phase_operator).reshape(len(groups),max_n,period_n,4)\nmode_first=mode_coefficient[...,0]-1j*mode_coefficient[...,1]\nmode_second=mode_coefficient[...,2]-1j*mode_coefficient[...,3]\nmode_power=np.stack([np.abs(mode_first)**2,np.abs(mode_second)**2],axis=-1)\nmode_denominator=mode_power.sum(axis=-1)**1.5\nmode_coupling=np.divide(mode_second*np.conj(mode_first)**2,mode_denominator,\n    out=np.zeros_like(mode_first),where=mode_denominator>0.)\nmode_features=np.concatenate([mode_power,np.stack([mode_coupling.real**2,mode_coupling.imag**2],axis=-1)],axis=-1)\nmode_weight=lag_value**2\nmode_weight/=mode_weight.sum(axis=-1,keepdims=True)\ndynamic_features=np.einsum("gk,gkpf->gpf",mode_weight,mode_features)\nfeature_bank=np.stack([\n    np.concatenate([raw_features,raw_features],axis=-1),\n    np.concatenate([raw_features,white_features],axis=-1),\n    np.concatenate([raw_features,population_features[group_index]],axis=-1),\n    np.concatenate([raw_features,dynamic_features[group_index]],axis=-1)])\nfeature_mean=np.einsum("n,mnpf->mf",row_weight,feature_bank[:,train])/period_n\nfeature_sd=np.sqrt(np.einsum("n,mnpf->mf",row_weight,\n    (feature_bank[:,train]-feature_mean[:,None,None])**2)/period_n)\nfeatures=(feature_bank-feature_mean[:,None,None])/feature_sd[:,None,None]\nassert np.isfinite(features).all() and np.all(feature_sd>0.)\nteacher=structural_source_readout_stage.split("prior_labels =",1)[0]\nteacher=teacher.replace("waves = np.stack([prediction,mixed[heldout]],axis=1)","waves = source_unit")\nteacher=teacher.replace("held_mask = mask[heldout]","held_mask = np.ones((len(train_rows),length),dtype=bool)")\nteacher=teacher.replace("held_count = count[heldout]","held_count = np.full(len(train_rows),length,dtype=int)")\nteacher_scope=dict(globals())\nexec(compile(teacher,__file__,"exec"),teacher_scope)\nsource_mass=softmax(teacher_scope["log_evidence"].reshape(len(train_rows),2,period_n)\n    +np.log(teacher_scope["grid_weight"])[None,None],axis=-1)\nsource_prior=np.einsum("n,nrp->rp",row_weight,source_mass)\nmodel_n=len(feature_bank)\ninput_n=features.shape[-1]\ntorch.manual_seed(fit_settings["seed"])\nwidth=fit_settings["width"]\nnetwork=nn.Sequential(nn.Linear(input_n,width),nn.Tanh(),nn.Linear(width,width),nn.Tanh(),nn.Linear(width,2)).double()\nnn.init.zeros_(network[-1].weight)\nnn.init.zeros_(network[-1].bias)\nparameter_names=tuple(dict(network.named_parameters()))\nparameter_shapes=tuple(map(torch.Tensor.size,network.parameters()))\nparameter_sizes=tuple(map(torch.Tensor.numel,network.parameters()))\none_initial=nn.utils.parameters_to_vector(network.parameters()).detach().numpy()\ninitial=np.broadcast_to(one_initial,(model_n,len(one_initial))).copy().ravel()\nunpack=lambda vector:dict(zip(parameter_names,map(torch.reshape,torch.split(vector,parameter_sizes),parameter_shapes)))\nsingle_forward=lambda vector,inputs:torch.func.functional_call(network,unpack(vector),(inputs,))\ntensor_prior=torch.as_tensor(np.log(source_prior),dtype=torch.float64)\nforward=lambda vector,inputs:torch.vmap(single_forward)(vector.reshape(model_n,-1),inputs).transpose(-1,-2)+tensor_prior\ntensor_inputs=torch.as_tensor(features[:,train],dtype=torch.float64)\ntensor_mass=torch.as_tensor(source_mass,dtype=torch.float64)\ntensor_weight=torch.as_tensor(row_weight,dtype=torch.float64)\ndata_losses=lambda vector:-(tensor_weight[None,:,None,None]*tensor_mass[None]\n    *torch.log_softmax(forward(vector,tensor_inputs),dim=-1)).sum(dim=(1,2,3))/2.\nobjective=lambda vector:data_losses(vector).mean()+fit_settings["weight_decay"]*vector.square().mean()\nautograd_objective=torch.func.grad_and_value(objective)\nto_scipy=lambda gradient,value:(value.detach().item(),gradient.detach().numpy())\nscipy_objective=lambda vector:to_scipy(*autograd_objective(torch.from_numpy(vector)))\ninitial_loss,initial_gradient=scipy_objective(initial)\nexpected_initial=-np.sum(source_prior*np.log(source_prior))/2.+fit_settings["weight_decay"]*np.mean(initial**2)\nassert np.isclose(initial_loss,expected_initial,rtol=1.e-10) and np.isfinite(initial_gradient).all()\nloss_history=[[0,initial_loss]]\nprint("MULTICELL_PERIOD_SETUP","fold",fold,"training_records",len(train_rows),"held_records",len(held_rows),\n    "experiments",len(training_groups),"representations",multicell_settings["representations"],\n    "parameters_each",len(one_initial),"all_temporal_modes",max_n,\n    "shrinkage_quantiles",np.quantile(shrinkage,[0.,.5,1.]).tolist(),flush=True)\nresult=minimize(scipy_objective,initial,jac=True,method="L-BFGS-B",\n    callback=lambda intermediate_result:(loss_history.append([len(loss_history),float(intermediate_result.fun)]),\n        len(loss_history)%25==0 and print("MULTICELL_PERIOD_PROGRESS",fold,len(loss_history)-1,float(intermediate_result.fun),flush=True)),\n    options={"maxiter":fit_settings["maxiter"],"ftol":fit_settings["ftol"],"gtol":fit_settings["gtol"],"maxls":fit_settings["maxls"]})\nparameters=torch.as_tensor(result.x,dtype=torch.float64)\nassert np.isfinite(result.x).all() and np.isfinite(result.fun)\ntraining_losses=data_losses(parameters).detach().numpy()\ndump({"parameters":result.x.reshape(model_n,-1),"parameter_names":parameter_names,"parameter_shapes":parameter_shapes,\n    "feature_mean":feature_mean,"feature_sd":feature_sd,"source_prior":source_prior,"source_period_mass":source_mass,\n    "training_trace_id":trace_id[train],"training_groups":training_groups,"training_weight":row_weight,\n    "configuration":multicell_settings,"fit_configuration":fit_settings,"optimization":result,\n    "loss_history":np.asarray(loss_history),"natural_training_crossentropy":training_losses,\n    "heldout_optical_read":False,"evaluation_layout":"existing_common_24_96h_window"},stem.with_suffix(".joblib"))\nlogit=forward(parameters,torch.as_tensor(features[:,heldout],dtype=torch.float64)).detach().numpy()\npredicted_mass=softmax(logit,axis=-1).transpose(1,0,2,3)\nrole_mass=np.concatenate([predicted_mass,np.broadcast_to(source_prior,(len(held_rows),1,2,period_n))],axis=1)\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nselected=role_score.argmax(axis=-1)\nrole_estimate=periods[selected]\nrole_confidence=np.take_along_axis(role_score,selected[...,None],axis=-1)[...,0]\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\nmethods=np.array(multicell_settings["methods"])\nassert np.isfinite(role_mass).all() and np.allclose(role_mass.sum(axis=-1),1.)\npredictions=pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],len(methods)),"method":np.tile(methods,len(held_rows)),\n    "estimate_h":estimate.ravel(),"confidence":confidence.ravel(),"heldout_fold":fold,\n    "heldout_run":np.repeat(run[heldout],len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    periods=periods,methods=methods,mass=mass,estimate=estimate,confidence=confidence,\n    role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,\n    source_prior=source_prior,training_trace_id=trace_id[train],training_groups=training_groups,\n    query_features=feature_bank[:,heldout],group_names=groups,group_shrinkage=shrinkage,\n    confidence_definition="supervised_source_period_mass_not_coverage_calibrated")\nprint("MULTICELL_PERIOD_FIT",fold,"iterations",result.nit,"training_crossentropy",training_losses.tolist(),\n    "status",str(result.message),flush=True)\nnative=native_evaluation\nexec(compile(structural_source_readout_stage[structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
exec(compile({True:structural_multicell_period_stage,False:""}[args.stage=="structural-multicell-period"],__file__,"exec"))


structural_window_context_stage = '\nfrom scipy.optimize import minimize\nfrom scipy.special import softmax\nfrom numpy.lib.stride_tricks import sliding_window_view\nfrom joblib import dump\nimport torch\nfrom torch import nn\ncommon_prefix=structural_phase_source_training_stage[:structural_phase_source_training_stage.index("source_objective =")]\ncommon_prefix=common_prefix.replace(\'exec(compile(structural_source_data_stage,__file__,"exec"))\',\n    \'exec(compile(structural_source_data_stage.replace(\\\'native = fold<application["lemna_expected_runs"]\\\',\\\'native = False\\\'),__file__,"exec"))\')\nexec(compile(common_prefix,__file__,"exec"))\nnative_evaluation=fold<application["lemna_expected_runs"]\ncontext_settings=application["structural_window_context"]\nfit_settings=application["structural_crossed_period"]\nstem=context_settings["stem"].with_name(context_settings["stem"].name+"_common_fold"+str(fold))\nassert np.all(count==length) and not np.intersect1d(trace_id[train],trace_id[heldout]).size\ntraining_mixture=mixed[train]\nexec(compile(structural_crossed_period_feature_stage,__file__,"exec"))\ncommon_features=phase_features(mixed,phase_operator).reshape(len(mixed),period_n,4)\nnative_no=pd.read_parquet(application["paths"]["lemna_dual_observations"],columns=["trace_id","time_h","no"])\nexternal_no=pd.read_parquet(application["conditional_source_external"]["raw"],columns=["trace_id","time_h","no"])\nfull_signal=pd.concat([native_no,external_no],ignore_index=True).pivot(\n    index="trace_id",columns="time_h",values="no").reindex(trace_id)\nfull_time=full_signal.columns.to_numpy(dtype=float)\nassert np.all(np.diff(full_time)==np.diff(time)[0])\nwindow_view=sliding_window_view(full_signal.to_numpy(dtype=float),length,axis=-1)\nvalid_window=np.isfinite(window_view).all(axis=-1)\nwindow_record,window_start=np.nonzero(valid_window)\nwindow_wave=window_view[valid_window].copy()\nwindow_wave-=(window_wave@base[0])@base[0].T\nwindow_wave/=np.sqrt(np.mean(window_wave**2,axis=-1))[:,None]\nwindow_features=phase_features(window_wave,phase_operator).reshape(len(window_wave),period_n,4)\ncommon_index=int(np.flatnonzero(full_time==optical_time[0])[0])\ncommon=window_start==common_index\nassert np.array_equal(window_record[common],np.arange(len(mixed)))\nassert np.allclose(window_wave[common],mixed,atol=1.e-10)\nassert np.allclose(window_features[common],common_features,rtol=1.e-10,atol=1.e-12)\nwindow_n=valid_window.shape[-1]\nprofile=np.zeros((len(mixed),period_n,window_n,4))\nprofile[window_record,:,window_start]=window_features\nrecord_window_count=valid_window.sum(axis=-1)\ntraining_record_weight=np.zeros(len(mixed))\ntraining_record_weight[train]=row_weight\nwindow_weight=training_record_weight[window_record]/record_window_count[window_record]\nfeature_mean=np.einsum("n,npf->f",window_weight,window_features)/period_n\nfeature_sd=np.sqrt(np.einsum("n,npf->f",window_weight,(window_features-feature_mean)**2)/period_n)\nprofile=(profile-feature_mean)/feature_sd\nlocal=(common_features-feature_mean)/feature_sd\nassert np.isfinite(profile).all() and np.isfinite(local).all() and np.all(feature_sd>0.)\nrelative_time=(full_time[:window_n]-optical_time[0])/(time[-1]-time[0])\nposition=np.stack([relative_time,relative_time**2],axis=-1)\nteacher=structural_source_readout_stage.split("prior_labels =",1)[0]\nteacher=teacher.replace("waves = np.stack([prediction,mixed[heldout]],axis=1)","waves = source_unit")\nteacher=teacher.replace("held_mask = mask[heldout]","held_mask = np.ones((len(train_rows),length),dtype=bool)")\nteacher=teacher.replace("held_count = count[heldout]","held_count = np.full(len(train_rows),length,dtype=int)")\nteacher_scope=dict(globals())\nexec(compile(teacher,__file__,"exec"),teacher_scope)\nsource_mass=softmax(teacher_scope["log_evidence"].reshape(len(train_rows),2,period_n)\n    +np.log(teacher_scope["grid_weight"])[None,None],axis=-1)\nsource_prior=np.einsum("n,nrp->rp",row_weight,source_mass)\ntorch.manual_seed(fit_settings["seed"])\nwidth=fit_settings["width"]\nnetwork=nn.Sequential(nn.Linear(12,width),nn.Tanh(),nn.Linear(width,width),nn.Tanh(),nn.Linear(width,2)).double()\nnn.init.zeros_(network[-1].weight)\nnn.init.zeros_(network[-1].bias)\nparameter_names=tuple(dict(network.named_parameters()))\nparameter_shapes=tuple(map(torch.Tensor.size,network.parameters()))\nparameter_sizes=tuple(map(torch.Tensor.numel,network.parameters()))\nreadout_initial=nn.utils.parameters_to_vector(network.parameters()).detach().numpy()\nattention_size=2*(2*4+2)\none_initial=np.r_[np.zeros(attention_size),readout_initial]\nmodel_n=len(context_settings["representations"])\ninitial=np.broadcast_to(one_initial,(model_n,len(one_initial))).copy().ravel()\nunpack=lambda vector:dict(zip(parameter_names,map(torch.reshape,torch.split(vector,parameter_sizes),parameter_shapes)))\ntensor_prior=torch.as_tensor(np.log(source_prior),dtype=torch.float64)\ntensor_position=torch.as_tensor(position,dtype=torch.float64)\ntensor_modes=torch.arange(model_n)\n# Each attention query uses its local mixture, all observed windows, and their\n# physical offsets. Absolute period is not provided to the shared score head.\n# Local and uniform-context controls use the same readout architecture.\nsingle_forward=lambda vector,mode,local_x,profile_x,valid:(\n    attention:=vector[:attention_size].reshape(2,-1)*(mode==2),\n    query:=attention[None,None,:,:4]+local_x[:,:,None]*attention[None,None,:,4:8],\n    scores:=torch.einsum("npwf,nprf->npwr",profile_x,query)\n        +torch.einsum("wf,rf->wr",tensor_position,attention[:,8:])[None,None],\n    weights:=torch.softmax(scores.masked_fill(~valid[:,None,:,None],-torch.inf),dim=2),\n    pooled:=torch.einsum("npwr,npwf->nprf",weights,profile_x),\n    pooled:=torch.where(mode==0,local_x[:,:,None].expand_as(pooled),pooled),\n    inputs:=torch.cat([local_x,pooled.flatten(-2)],dim=-1),\n    torch.func.functional_call(network,unpack(vector[attention_size:]),(inputs,)).transpose(-1,-2)+tensor_prior)[-1]\nforward=lambda vector,local_x,profile_x,valid:torch.vmap(single_forward,in_dims=(0,0,None,None,None))(\n    vector.reshape(model_n,-1),tensor_modes,local_x,profile_x,valid)\ntensor_local=torch.as_tensor(local[train],dtype=torch.float64)\ntensor_profile=torch.as_tensor(profile[train],dtype=torch.float64)\ntensor_valid=torch.as_tensor(valid_window[train])\ntensor_mass=torch.as_tensor(source_mass,dtype=torch.float64)\ntensor_weight=torch.as_tensor(row_weight,dtype=torch.float64)\ndata_losses=lambda vector:-(tensor_weight[None,:,None,None]*tensor_mass[None]\n    *torch.log_softmax(forward(vector,tensor_local,tensor_profile,tensor_valid),dim=-1)).sum(dim=(1,2,3))/2.\nobjective=lambda vector:data_losses(vector).mean()+fit_settings["weight_decay"]*vector.square().mean()\nautograd_objective=torch.func.grad_and_value(objective)\nto_scipy=lambda gradient,value:(value.detach().item(),gradient.detach().numpy())\nscipy_objective=lambda vector:to_scipy(*autograd_objective(torch.from_numpy(vector)))\ninitial_loss,initial_gradient=scipy_objective(initial)\nexpected_initial=-np.sum(source_prior*np.log(source_prior))/2.+fit_settings["weight_decay"]*np.mean(initial**2)\nassert np.isclose(initial_loss,expected_initial,rtol=1.e-10) and np.isfinite(initial_gradient).all()\nloss_history=[[0,initial_loss]]\nprint("WINDOW_CONTEXT_SETUP","fold",fold,"records",len(train_rows),"held_records",len(held_rows),\n    "training_context_windows",int(valid_window[train].sum()),"held_context_windows",int(valid_window[heldout].sum()),\n    "context_points_minmax",np.quantile(np.sum(np.isfinite(full_signal.to_numpy()),axis=1)[heldout],[0.,1.]).astype(int).tolist(),\n    "period_label_window_h",application["conditional_source_external"]["window_h"],\n    "representations",context_settings["representations"],"parameters_each",len(one_initial),flush=True)\nresult=minimize(scipy_objective,initial,jac=True,method="L-BFGS-B",\n    callback=lambda intermediate_result:(loss_history.append([len(loss_history),float(intermediate_result.fun)]),\n        len(loss_history)%25==0 and print("WINDOW_CONTEXT_PROGRESS",fold,len(loss_history)-1,float(intermediate_result.fun),flush=True)),\n    options={"maxiter":fit_settings["maxiter"],"ftol":fit_settings["ftol"],"gtol":fit_settings["gtol"],"maxls":fit_settings["maxls"]})\nparameters=torch.as_tensor(result.x,dtype=torch.float64)\nassert np.isfinite(result.fun) and np.isfinite(result.x).all()\ntraining_losses=data_losses(parameters).detach().numpy()\ndump({"parameters":result.x.reshape(model_n,-1),"parameter_names":parameter_names,"parameter_shapes":parameter_shapes,\n    "attention_size":attention_size,"feature_mean":feature_mean,"feature_sd":feature_sd,\n    "phase_operator":phase_operator,"source_prior":source_prior,"source_period_mass":source_mass,\n    "training_trace_id":trace_id[train],"training_groups":training_groups,"training_weight":row_weight,\n    "configuration":context_settings,"fit_configuration":fit_settings,"optimization":result,\n    "loss_history":np.asarray(loss_history),"natural_training_crossentropy":training_losses,\n    "heldout_optical_read":False,"training_context_window_count":record_window_count[train]},stem.with_suffix(".joblib"))\nlogit=forward(parameters,torch.as_tensor(local[heldout],dtype=torch.float64),\n    torch.as_tensor(profile[heldout],dtype=torch.float64),torch.as_tensor(valid_window[heldout])).detach().numpy()\npredicted_mass=softmax(logit,axis=-1).transpose(1,0,2,3)\nrole_mass=np.concatenate([predicted_mass,np.broadcast_to(source_prior,(len(held_rows),1,2,period_n))],axis=1)\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nselected=role_score.argmax(axis=-1)\nrole_estimate=periods[selected]\nrole_confidence=np.take_along_axis(role_score,selected[...,None],axis=-1)[...,0]\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\nmethods=np.array(context_settings["methods"])\nassert np.isfinite(role_mass).all() and np.allclose(role_mass.sum(axis=-1),1.)\npredictions=pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],len(methods)),"method":np.tile(methods,len(held_rows)),\n    "estimate_h":estimate.ravel(),"confidence":confidence.ravel(),"heldout_fold":fold,\n    "heldout_run":np.repeat(run[heldout],len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    periods=periods,methods=methods,mass=mass,estimate=estimate,confidence=confidence,\n    role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,\n    source_prior=source_prior,training_trace_id=trace_id[train],training_groups=training_groups,\n    full_context_time=full_time,context_window_start=full_time[:window_n],\n    query_valid_context_window=valid_window[heldout],query_local_features=common_features[heldout],\n    observation_context="all_actual_No_observations_for_mean_and_attention_controls",\n    target_interval_h=application["conditional_source_external"]["window_h"],\n    confidence_definition="supervised_local_source_period_mass_not_coverage_calibrated")\nprint("WINDOW_CONTEXT_FIT",fold,"iterations",result.nit,"training_crossentropy",training_losses.tolist(),\n    "status",str(result.message),flush=True)\nnative=native_evaluation\nexec(compile(structural_source_readout_stage[structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
