structural_global_factorial_stage = '\nfrom scipy.special import gammaln,softmax\nfrom scipy.stats import multivariate_t\nfrom joblib import load\nimport torch\ncommon_prefix=structural_phase_source_training_stage[:structural_phase_source_training_stage.index("source_objective =")]\ncommon_prefix=common_prefix.replace(\'exec(compile(structural_source_data_stage,__file__,"exec"))\',\n    \'exec(compile(structural_source_data_stage.replace(\\\'native = fold<application["lemna_expected_runs"]\\\',\\\'native = False\\\'),__file__,"exec"))\')\nexec(compile(common_prefix,__file__,"exec"))\nnative_evaluation=fold<application["lemna_expected_runs"]\nfactorial_settings=application["structural_global_factorial"]\nstem=factorial_settings["stem"].with_name(factorial_settings["stem"].name+"_common_fold"+str(fold))\nparent_stem=application["structural_literal_source"]["stem"]\nparent_stem=parent_stem.with_name(parent_stem.name+"_common_fold"+str(fold))\nbundle=load(parent_stem.with_suffix(".joblib"))\nassert np.array_equal(bundle["training_trace_id"],trace_id[train])\nsource_start_h=bundle["group_start_h"][bundle["source_group_index"]]\ncommon=source_start_h==application["conditional_source_external"]["window_h"][0]\nassert np.array_equal(bundle["source_record"][common],np.arange(len(train_rows)))\nsource_wave=bundle["source_wave"][common]\nsource_mass=bundle["source_period_mass"][common]\nnp.testing.assert_allclose(source_wave,source_unit,rtol=1.e-10,atol=1.e-10)\nnp.testing.assert_allclose(bundle["periods"],periods,rtol=0.,atol=0.)\nsource_n=len(source_wave)\nsource_groups,source_group,source_counts=np.unique(run[train],return_inverse=True,return_counts=True)\nsource_weight=1./(len(source_groups)*source_counts[source_group])\nnp.testing.assert_allclose(source_weight,row_weight,atol=1.e-15)\nsource_prior=np.einsum("n,nrp->rp",source_weight,source_mass)\nglobal_joint=source_weight[:,None]*source_weight[None]\nwithin_joint=global_joint*len(source_groups)*(source_group[:,None]==source_group[None])\npaired_joint=np.diag(source_weight)\njoint_prior=np.stack([global_joint,within_joint,paired_joint])\nnp.testing.assert_allclose(joint_prior.sum(axis=-1),np.broadcast_to(source_weight,(3,source_n)),atol=1.e-14)\nnp.testing.assert_allclose(joint_prior.sum(axis=-2),np.broadcast_to(source_weight,(3,source_n)),atol=1.e-14)\nlog_prior=np.where(joint_prior>0.,np.log(np.where(joint_prior>0.,joint_prior,1.)),-np.inf)\n\ncoordinate_basis=bundle["coordinate_basis"]\nnoise_eigenvalue=bundle["noise_eigenvalue"]\nsource_coordinate=source_wave@coordinate_basis\nwhite_source=source_coordinate/np.sqrt(noise_eigenvalue)[None,None]\nheld_coordinate=mixed[heldout]@coordinate_basis\nwhite_held=held_coordinate/np.sqrt(noise_eigenvalue)[None]\nprior_precision=bundle["gain_precision"]\nprior_mean=bundle["gain_mean"]\nprior_natural=prior_precision@prior_mean\nprior_quadratic=prior_mean@prior_natural\nnoise_shape,noise_rate=bundle["noise_shape"],bundle["noise_rate"]\nleft_precision=prior_precision[0,0]+np.sum(white_source[:,0]**2,axis=-1)\nright_precision=prior_precision[1,1]+np.sum(white_source[:,1]**2,axis=-1)\ncross_precision=prior_precision[0,1]+white_source[:,0]@white_source[:,1].T\ndeterminant=left_precision[:,None]*right_precision[None]-cross_precision**2\nassert determinant.min()>0.\nconstant=gammaln(noise_shape+dimension/2.)-gammaln(noise_shape)+noise_shape*np.log(noise_rate)\nconstant-=dimension/2.*np.log(2.*np.pi)+.5*np.linalg.slogdet(bundle["gain_covariance"])[1]\nconstant-=.5*np.log(noise_eigenvalue).sum()\npair_constant=constant-.5*np.log(determinant)\ntensor_source=torch.as_tensor(white_source)\ntensor_left=torch.as_tensor(left_precision[:,None])\ntensor_right=torch.as_tensor(right_precision[None])\ntensor_cross=torch.as_tensor(cross_precision)\ntensor_determinant=torch.as_tensor(determinant)\ntensor_natural=torch.as_tensor(prior_natural)\ntensor_constant=torch.as_tensor(pair_constant)\ntensor_prior=torch.as_tensor(log_prior)\nsource_features=np.concatenate([source_mass,source_wave],axis=-1).transpose(1,0,2)\ntensor_features=torch.as_tensor(np.ascontiguousarray(source_features))\nglobal_record=lambda observed:(\n    projection:=torch.einsum("nrd,d->nr",tensor_source,observed)+tensor_natural,\n    left:=projection[:,0,None],right:=projection[None,:,1],\n    quadratic:=observed.square().sum()+prior_quadratic\n        -(tensor_right*left.square()-2.*tensor_cross*left*right+tensor_left*right.square())/tensor_determinant,\n    log_likelihood:=tensor_constant-(noise_shape+dimension/2.)*torch.log(noise_rate+quadratic/2.),\n    log_joint:=log_likelihood[None]+tensor_prior,\n    log_normalizer:=torch.logsumexp(log_joint.flatten(1),dim=-1),\n    probability:=torch.exp(log_joint-log_normalizer[:,None,None]),\n    source_probability:=torch.stack([probability.sum(dim=-1),probability.sum(dim=-2)],dim=1),\n    features:=torch.einsum("mrn,rnf->mrf",source_probability,tensor_features),\n    posterior_gain_left:=(tensor_right*left-tensor_cross*right)/tensor_determinant,\n    posterior_gain_right:=(tensor_left*right-tensor_cross*left)/tensor_determinant,\n    mean_gain:=torch.stack([(probability*posterior_gain_left[None]).sum(dim=(-2,-1)),\n        (probability*posterior_gain_right[None]).sum(dim=(-2,-1))],dim=-1),\n    (features,source_probability,log_normalizer,mean_gain,quadratic.min()))[-1]\n# A cross-run source pair checks indexing and the analytic two-amplitude integral.\ncheck_pair=np.array([0,np.flatnonzero(source_group!=source_group[0])[0]])\ncheck_source=source_coordinate[check_pair,np.arange(2)]\ncheck_projection=white_source[check_pair,np.arange(2)]@white_held[0]+prior_natural\ncheck_cross=cross_precision[tuple(check_pair)]\ncheck_determinant=determinant[tuple(check_pair)]\ncheck_quadratic=white_held[0]@white_held[0]+prior_quadratic-(\n    right_precision[check_pair[1]]*check_projection[0]**2\n    -2.*check_cross*check_projection[0]*check_projection[1]\n    +left_precision[check_pair[0]]*check_projection[1]**2)/check_determinant\ncheck_analytic=pair_constant[tuple(check_pair)]-(noise_shape+dimension/2.)*np.log(noise_rate+check_quadratic/2.)\ncheck_dense=multivariate_t.logpdf(held_coordinate[0],loc=check_source.T@prior_mean,\n    shape=(noise_rate/noise_shape)*(np.diag(noise_eigenvalue)\n        +check_source.T@bundle["gain_covariance"]@check_source),df=2.*noise_shape)\nnp.testing.assert_allclose(check_analytic,check_dense,atol=1.e-8,rtol=1.e-10)\nprint("GLOBAL_FACTORIAL_SETUP","fold",fold,"source_records",source_n,\n    "held_records",len(held_rows),"source_runs",len(source_groups),\n    "prior_pairs",(joint_prior>0.).sum(axis=(-2,-1)).tolist(),\n    "analytic_dense_difference",float(check_analytic-check_dense),flush=True)\nfeatures,source_probability,log_evidence,mean_gain,minimum_quadratic=torch.vmap(\n    global_record,chunk_size=1)(torch.as_tensor(white_held))\nassert minimum_quadratic.min().item()>0.\nnp.testing.assert_allclose(source_probability.sum(dim=-1).numpy(),1.,atol=1.e-12)\nfeatures=features.numpy()\nrole_mass=np.concatenate([features[:,:,:,:period_n],\n    np.broadcast_to(source_prior,(len(held_rows),1,2,period_n))],axis=1)\nsource_pair_mean=features[:,:,:,period_n:]\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nrole_estimate=periods[role_score.argmax(axis=-1)]\nrole_confidence=role_score.max(axis=-1)\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\nmethods=np.array(factorial_settings["methods"])\nassert np.isfinite(role_mass).all() and np.allclose(role_mass.sum(axis=-1),1.)\npredictions=pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],len(methods)),\n    "method":np.tile(methods,len(held_rows)),"estimate_h":estimate.ravel(),\n    "confidence":confidence.ravel(),"heldout_fold":fold,\n    "heldout_run":np.repeat(run[heldout],len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    raw_waveform=mixed[heldout],periods=periods,methods=methods,mass=mass,estimate=estimate,confidence=confidence,\n    role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,source_prior=source_prior,\n    source_pair_mean=source_pair_mean,source_probability=source_probability.numpy(),log_evidence=log_evidence.numpy(),\n    mean_mixing_gain=mean_gain.numpy(),training_trace_id=trace_id[train],training_groups=training_groups,\n    source_group_index=source_group,source_weight=source_weight,source_period_mass=source_mass,\n    gain_mean=prior_mean,gain_covariance=bundle["gain_covariance"],noise_shape=noise_shape,noise_rate=noise_rate,\n    source_support="all_training_records_at_the_common_interval",\n    nuisance_calibration="unchanged_parent_literal_source_all_window_NIG",\n    source_mean_definition="posterior_mean_unit_waveform_without_mixing_gain",\n    confidence_definition="finite_real_source_posterior_mass_not_coverage_calibrated")\nprint("GLOBAL_FACTORIAL_PREDICTED","fold",fold,"records",len(held_rows),\n    "minimum_quadratic",float(minimum_quadratic.min()),\n    "posterior_source_ESS_median",np.median(1./source_probability.square().sum(dim=-1).numpy(),axis=0).tolist(),flush=True)\nnative=native_evaluation\nexec(compile(structural_source_readout_stage[structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
