structural_pair_competition_stage = '\nfrom scipy.special import gammaln,softmax\nfrom scipy.stats import multivariate_t\nfrom joblib import load\nimport torch\ncommon_prefix=structural_phase_source_training_stage[:structural_phase_source_training_stage.index("source_objective =")]\ncommon_prefix=common_prefix.replace(\'exec(compile(structural_source_data_stage,__file__,"exec"))\',\n    \'exec(compile(structural_source_data_stage.replace(\\\'native = fold<application["lemna_expected_runs"]\\\',\\\'native = False\\\'),__file__,"exec"))\')\nexec(compile(common_prefix,__file__,"exec"))\nnative_evaluation=fold<application["lemna_expected_runs"]\n\nfrom scipy.optimize import minimize\nfrom joblib import dump\ncompetition_settings=application["structural_pair_competition"]\nfit_settings=application["structural_crossed_period"]\nstem=competition_settings["stem"].with_name(competition_settings["stem"].name+"_common_fold"+str(fold))\nparent_stem=application["structural_literal_source"]["stem"]\nparent_stem=parent_stem.with_name(parent_stem.name+"_common_fold"+str(fold))\nbundle=load(parent_stem.with_suffix(".joblib"))\nassert np.array_equal(bundle["training_trace_id"],trace_id[train])\nsource_start_h=bundle["group_start_h"][bundle["source_group_index"]]\ncommon=source_start_h==application["conditional_source_external"]["window_h"][0]\nassert np.array_equal(bundle["source_record"][common],np.arange(len(train_rows)))\nsource_mass=bundle["source_period_mass"][common]\nnp.testing.assert_allclose(bundle["source_wave"][common],source_unit,atol=1.e-10,rtol=1.e-10)\nsource_prior=np.einsum("n,nrp->rp",row_weight,source_mass,optimize=True)\ncoordinate_basis=bundle["coordinate_basis"]\nnoise_root=np.sqrt(bundle["noise_eigenvalue"])\nwhite_source=(source_unit@coordinate_basis)/noise_root[None,None]\nwhite_mixed=(mixed@coordinate_basis)/noise_root[None]\nwhite_harmonic=np.einsum("ti,ptj->pij",coordinate_basis,harmonic)/noise_root[None,:,None]\ngram=np.einsum("pdi,pdj->pij",white_harmonic,white_harmonic)\npure_operator=np.einsum("pdi,pij->pdj",white_harmonic,np.linalg.inv(gram))\nsource_coefficient=np.einsum("nrd,pdk->nrpk",white_source,pure_operator,optimize=True)\ngain=np.linalg.solve(white_source@white_source.transpose(0,2,1),\n    np.einsum("nrd,nd->nr",white_source,white_mixed[train])[...,None])[...,0]\nremainder=white_mixed[train]-np.einsum("nr,nrd->nd",gain,white_source)\nnoise_variance=np.mean(remainder**2,axis=-1)\nsource_harmonic_power=np.sum(source_coefficient.reshape(len(train_rows),2,period_n,2,2)**2,axis=-1)/2.\ncoefficient_variance=np.einsum("n,nr,nrp,nrph->rh",row_weight,gain**2/noise_variance[:,None],\n    source_mass,source_harmonic_power,optimize=True)\nassert np.isfinite(coefficient_variance).all() and coefficient_variance.min()>0.\nprior_precision=np.diag(1./np.repeat(coefficient_variance.ravel(),2))\npair_harmonic=np.concatenate([\n    np.broadcast_to(white_harmonic[:,None],(period_n,period_n,dimension,4)),\n    np.broadcast_to(white_harmonic[None],(period_n,period_n,dimension,4))],axis=-1)\npair_gram=np.einsum("pqdi,pqdj->pqij",pair_harmonic,pair_harmonic)\nrole_blocks=np.repeat(np.arange(2),4)\nindependent_gram=pair_gram*(role_blocks[:,None]==role_blocks[None])\nprecision=np.stack([independent_gram,pair_gram])+prior_precision[None,None,None]\ninverse=np.linalg.inv(precision)\noperators=np.einsum("pqdi,mpqij->mpqdj",pair_harmonic,inverse,optimize=True)\ncoefficient=np.einsum("nd,mpqdk->mnpqk",white_mixed,operators,optimize=True).reshape(\n    2,len(mixed),period_n,period_n,2,4)\nphase_features=lambda values:(\n    first:=values[...,0]-1j*values[...,1],\n    second:=values[...,2]-1j*values[...,3],\n    first_power:=np.abs(first)**2,\n    second_power:=np.abs(second)**2,\n    coupling:=second*np.conj(first)**2/(first_power+second_power)**1.5,\n    np.stack([first_power,second_power,coupling.real,coupling.imag],axis=-1))[-1]\nfeatures=phase_features(coefficient).reshape(2,len(mixed),period_n**2,8)\nassert np.isfinite(features).all()\nfeature_mean=np.einsum("n,mnkf->mf",row_weight,features[:,train])/(period_n**2)\nfeature_sd=np.sqrt(np.einsum("n,mnkf->mf",row_weight,\n    (features[:,train]-feature_mean[:,None,None])**2)/(period_n**2))\nassert feature_sd.min()>0.\nstandardized=(features-feature_mean[:,None,None])/feature_sd[:,None,None]\n# The independent representation has no cross-frequency contribution.\nnp.testing.assert_allclose(coefficient[0,:,:,0,0],coefficient[0,:,:,period_n-1,0],atol=1.e-11,rtol=1.e-11)\nnp.testing.assert_allclose(coefficient[0,:,0,:,1],coefficient[0,:,period_n-1,:,1],atol=1.e-11,rtol=1.e-11)\nshifted_angle=2.*np.pi*(time-time.mean())[None,:,None]/periods[:,None,None]*harmonic_index[None,None]\nshifted_harmonic=np.sqrt(2.)*np.stack([np.cos(shifted_angle),np.sin(shifted_angle)],axis=-1).reshape(period_n,length,4)\nshifted_harmonic-=np.einsum("ti,pij->ptj",base[0],np.einsum("ti,ptj->pij",base[0],shifted_harmonic))\nshifted_white=np.einsum("ti,ptj->pij",coordinate_basis,shifted_harmonic)/noise_root[None,:,None]\nshifted_pair=np.concatenate([\n    np.broadcast_to(shifted_white[:,None],(period_n,period_n,dimension,4)),\n    np.broadcast_to(shifted_white[None],(period_n,period_n,dimension,4))],axis=-1)\nshifted_gram=np.einsum("pqdi,pqdj->pqij",shifted_pair,shifted_pair)\nshifted_precision=np.stack([shifted_gram*(role_blocks[:,None]==role_blocks[None]),shifted_gram])+prior_precision[None,None,None]\nshifted_inverse=np.linalg.inv(shifted_precision)\nshifted_coefficient=np.einsum("d,pqdi,mpqij->mpqj",white_mixed[train][0],shifted_pair,shifted_inverse,optimize=True).reshape(\n    2,period_n,period_n,2,4)\nshifted_features=phase_features(shifted_coefficient).reshape(2,period_n**2,8)\nnp.testing.assert_allclose(shifted_features,features[:,train_rows[0]],atol=1.e-10,rtol=1.e-10)\n\njoint_teacher=(source_mass[:,0,:,None]*source_mass[:,1,None,:]).reshape(len(train_rows),-1)\njoint_prior=(source_prior[0,:,None]*source_prior[1,None,:]).ravel()\ntensor_features=torch.as_tensor(np.ascontiguousarray(standardized[:,train]))\ntensor_teacher=torch.as_tensor(joint_teacher)\ntensor_weight=torch.as_tensor(row_weight)\ntensor_prior=torch.as_tensor(np.log(joint_prior))\nforward=lambda vector,values:torch.einsum("mnkf,mf->mnk",values,vector.reshape(2,8))+tensor_prior\ndata_losses=lambda vector:-(tensor_weight[None,:,None]*tensor_teacher[None]\n    *torch.log_softmax(forward(vector,tensor_features),dim=-1)).sum(dim=(1,2))/2.\nobjective=lambda vector:data_losses(vector).mean()+fit_settings["weight_decay"]*vector.square().mean()\nautograd_objective=torch.func.grad_and_value(objective)\nto_scipy=lambda gradient,value:(value.detach().item(),gradient.detach().numpy())\nscipy_objective=lambda vector:to_scipy(*autograd_objective(torch.from_numpy(vector)))\ninitial=np.zeros(16)\ninitial_loss,initial_gradient=scipy_objective(initial)\nexpected_initial=-np.sum(source_prior*np.log(source_prior))/2.\nassert np.isclose(initial_loss,expected_initial,rtol=1.e-10) and np.isfinite(initial_gradient).all()\nloss_history=[[0,initial_loss]]\nprint("PAIR_COMPETITION_SETUP","fold",fold,"training_records",len(train_rows),"held_records",len(held_rows),\n    "all_period_pairs",period_n**2,"parameters_each",8,\n    "coefficient_variance",coefficient_variance.tolist(),\n    "origin_invariance_error",float(np.max(np.abs(shifted_features-features[:,train_rows[0]]))),flush=True)\nresult=minimize(scipy_objective,initial,jac=True,method="L-BFGS-B",\n    callback=lambda intermediate_result:(loss_history.append([len(loss_history),float(intermediate_result.fun)]),\n        len(loss_history)%25==0 and print("PAIR_COMPETITION_PROGRESS",fold,len(loss_history)-1,float(intermediate_result.fun),flush=True)),\n    options={"maxiter":fit_settings["maxiter"],"ftol":fit_settings["ftol"],"gtol":fit_settings["gtol"],"maxls":fit_settings["maxls"]})\nparameters=torch.as_tensor(result.x)\nassert np.isfinite(result.x).all() and np.isfinite(result.fun)\ntraining_losses=data_losses(parameters).detach().numpy()\ndump({"parameters":result.x.reshape(2,8),"feature_mean":feature_mean,"feature_sd":feature_sd,\n    "coefficient_variance":coefficient_variance,"operators":operators,"coordinate_basis":coordinate_basis,\n    "noise_eigenvalue":bundle["noise_eigenvalue"],"source_prior":source_prior,"source_period_mass":source_mass,\n    "training_trace_id":trace_id[train],"training_groups":training_groups,"training_weight":row_weight,\n    "optimization":result,"loss_history":np.asarray(loss_history),"training_crossentropy":training_losses,\n    "configuration":competition_settings,"fit_configuration":fit_settings,"heldout_optical_read":False},stem.with_suffix(".joblib"))\nlogit=forward(parameters,torch.as_tensor(np.ascontiguousarray(standardized[:,heldout]))).detach().numpy()\njoint_mass=softmax(logit,axis=-1).transpose(1,0,2).reshape(len(held_rows),2,period_n,period_n)\nrole_mass=np.concatenate([np.stack([joint_mass.sum(axis=-1),joint_mass.sum(axis=-2)],axis=2),\n    np.broadcast_to(source_prior,(len(held_rows),1,2,period_n))],axis=1)\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nrole_estimate=periods[role_score.argmax(axis=-1)]\nrole_confidence=role_score.max(axis=-1)\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\nmethods=np.array(competition_settings["methods"])\nassert np.isfinite(role_mass).all() and np.allclose(role_mass.sum(axis=-1),1.)\npredictions=pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],len(methods)),\n    "method":np.tile(methods,len(held_rows)),"estimate_h":estimate.ravel(),\n    "confidence":confidence.ravel(),"heldout_fold":fold,\n    "heldout_run":np.repeat(run[heldout],len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    periods=periods,methods=methods,mass=mass,estimate=estimate,confidence=confidence,\n    role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,joint_mass=joint_mass,\n    source_prior=source_prior,training_trace_id=trace_id[train],training_groups=training_groups,\n    coefficient_variance=coefficient_variance,source_period_mass=source_mass,\n    confidence_definition="supervised_named_source_joint_period_mass_not_coverage_calibrated")\nprint("PAIR_COMPETITION_FIT","fold",fold,"iterations",result.nit,\n    "training_crossentropy",training_losses.tolist(),"weights",result.x.reshape(2,8).tolist(),\n    "status",str(result.message),flush=True)\nnative=native_evaluation\nexec(compile(structural_source_readout_stage[structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
