structural_asymmetric_source_stage = '\nfrom scipy.special import gammaln,softmax\nfrom scipy.stats import multivariate_t\nfrom joblib import load\nimport torch\ncommon_prefix=structural_phase_source_training_stage[:structural_phase_source_training_stage.index("source_objective =")]\ncommon_prefix=common_prefix.replace(\'exec(compile(structural_source_data_stage,__file__,"exec"))\',\n    \'exec(compile(structural_source_data_stage.replace(\\\'native = fold<application["lemna_expected_runs"]\\\',\\\'native = False\\\'),__file__,"exec"))\')\nexec(compile(common_prefix,__file__,"exec"))\nnative_evaluation=fold<application["lemna_expected_runs"]\n\nasymmetric_settings=application["structural_asymmetric_source"]\nstem=asymmetric_settings["stem"].with_name(asymmetric_settings["stem"].name+"_common_fold"+str(fold))\nparent_stem=application["structural_literal_source"]["stem"]\nparent_stem=parent_stem.with_name(parent_stem.name+"_common_fold"+str(fold))\nbundle=load(parent_stem.with_suffix(".joblib"))\nvariance_stem=application["structural_pair_competition"]["stem"]\nvariance_stem=variance_stem.with_name(variance_stem.name+"_common_fold"+str(fold))\nvariance_bundle=load(variance_stem.with_suffix(".joblib"))\nassert np.array_equal(bundle["training_trace_id"],trace_id[train])\nassert np.array_equal(variance_bundle["training_trace_id"],trace_id[train])\nsource_start_h=bundle["group_start_h"][bundle["source_group_index"]]\ncommon=source_start_h==application["conditional_source_external"]["window_h"][0]\nassert np.array_equal(bundle["source_record"][common],np.arange(len(train_rows)))\nsource_wave=bundle["source_wave"][common]\nsource_mass=bundle["source_period_mass"][common]\nnp.testing.assert_allclose(source_wave,source_unit,atol=1.e-10,rtol=1.e-10)\nsource_prior=np.einsum("n,nrp->rp",row_weight,source_mass,optimize=True)\ncoordinate_basis=bundle["coordinate_basis"]\nnoise_root=np.sqrt(bundle["noise_eigenvalue"])\nwhite_held=(mixed[heldout]@coordinate_basis)/noise_root[None]\nwhite_source=(source_wave@coordinate_basis)/noise_root[None,None]\nwhite_harmonic=np.einsum("ti,ptj->pij",coordinate_basis,harmonic)/noise_root[None,:,None]\ncoefficient_variance=variance_bundle["coefficient_variance"]\ncoefficient_diagonal=np.repeat(coefficient_variance,2,axis=1)\nharmonic_gram=np.einsum("pdi,pdj->pij",white_harmonic,white_harmonic)\nharmonic_precision=harmonic_gram[None]+np.eye(4)[None,None]/coefficient_diagonal[:,None,None]\nharmonic_inverse=np.linalg.inv(harmonic_precision)\nharmonic_operator=np.einsum("pdi,mpij->mpdj",white_harmonic,harmonic_inverse,optimize=True)\nfree_inverse=np.eye(dimension)[None,None]-np.einsum("mpdi,pei->mpde",harmonic_operator,white_harmonic,optimize=True)\nfree_logdet=np.linalg.slogdet(harmonic_precision)[1]+np.log(coefficient_diagonal).sum(axis=-1)[:,None]\nempirical_role=np.array([1,0])\nempirical_white=white_source[:,empirical_role].transpose(1,0,2)\nempirical_wave=source_wave[:,empirical_role].transpose(1,0,2)\nempirical_mass=source_mass[:,empirical_role].transpose(1,0,2)\nempirical_mean=bundle["gain_mean"][empirical_role]\nempirical_variance=np.diag(bundle["gain_covariance"])[empirical_role]\ntransformed_source=np.einsum("mpde,mse->mpsd",free_inverse,empirical_white,optimize=True)\nsource_quadratic=np.einsum("msd,mpsd->mps",empirical_white,transformed_source,optimize=True)\ndenominator=1.+empirical_variance[:,None,None]*source_quadratic\ntemplate_to_coefficient=np.einsum("mpdi,msd->mpsi",harmonic_operator,empirical_white,optimize=True)\nnoise_shape,noise_rate=bundle["noise_shape"],bundle["noise_rate"]\nconstant=gammaln(noise_shape+dimension/2.)-gammaln(noise_shape)+noise_shape*np.log(noise_rate)\nconstant-=dimension/2.*np.log(2.*np.pi)\nlogdet=free_logdet[:,:,None]+np.log(denominator)\nprior=np.log(source_prior)[:,:,None]+np.log(row_weight)[None,None]\ntensor_inverse=torch.as_tensor(free_inverse)\ntensor_source=torch.as_tensor(transformed_source)\ntensor_source_quadratic=torch.as_tensor(source_quadratic)\ntensor_denominator=torch.as_tensor(denominator)\ntensor_logdet=torch.as_tensor(logdet)\ntensor_prior=torch.as_tensor(prior)\ntensor_mean=torch.as_tensor(empirical_mean[:,None,None])\ntensor_variance=torch.as_tensor(empirical_variance[:,None,None])\ntensor_empirical_mass=torch.as_tensor(np.ascontiguousarray(empirical_mass))\ntensor_empirical_wave=torch.as_tensor(np.ascontiguousarray(empirical_wave))\ntensor_harmonic=torch.as_tensor(harmonic)\ntensor_operator=torch.as_tensor(harmonic_operator)\ntensor_template_coefficient=torch.as_tensor(template_to_coefficient)\nasymmetric_record=lambda observed:(\n    observed_quadratic:=torch.einsum("d,mpde,e->mp",observed,tensor_inverse,observed),\n    cross:=torch.einsum("mpsd,d->mps",tensor_source,observed),\n    quadratic:=observed_quadratic[:,:,None]-2.*tensor_mean*cross+tensor_mean.square()*tensor_source_quadratic\n        -tensor_variance*(cross-tensor_mean*tensor_source_quadratic).square()/tensor_denominator,\n    log_likelihood:=constant-.5*tensor_logdet-(noise_shape+dimension/2.)*torch.log(noise_rate+quadratic/2.),\n    log_joint:=log_likelihood+tensor_prior,\n    log_normalizer:=torch.logsumexp(log_joint.flatten(1),dim=-1),\n    probability:=torch.exp(log_joint-log_normalizer[:,None,None]),\n    gaussian_mass:=probability.sum(dim=-1),\n    source_probability:=probability.sum(dim=-2),\n    real_mass:=torch.einsum("ms,msp->mp",source_probability,tensor_empirical_mass),\n    masses:=torch.stack([torch.stack([gaussian_mass[0],real_mass[0]]),\n        torch.stack([real_mass[1],gaussian_mass[1]])]),\n    mean_gain:=(tensor_mean+tensor_variance*cross)/tensor_denominator,\n    base_coefficient:=torch.einsum("mpdi,d->mpi",tensor_operator,observed),\n    coefficient:=base_coefficient[:,:,None]-tensor_template_coefficient*mean_gain[:,:,:,None],\n    weighted_coefficient:=torch.einsum("mps,mpsi->mpi",probability,coefficient),\n    gaussian_wave:=torch.einsum("mpi,pti->mt",weighted_coefficient,tensor_harmonic),\n    real_wave:=torch.einsum("mps,mps,mst->mt",probability,mean_gain,tensor_empirical_wave),\n    waves:=torch.stack([torch.stack([gaussian_wave[0],real_wave[0]]),\n        torch.stack([real_wave[1],gaussian_wave[1]])]),\n    (masses,waves,source_probability,log_normalizer,quadratic.min()))[-1]\ncheck_covariance=np.eye(dimension)+(white_harmonic[0]*coefficient_diagonal[0][None])@white_harmonic[0].T\ncheck_covariance+=empirical_variance[0]*np.outer(empirical_white[0,0],empirical_white[0,0])\ncheck_observation=white_held[0]\ncheck_cross=transformed_source[0,0,0]@check_observation\ncheck_quadratic=check_observation@free_inverse[0,0]@check_observation-2.*empirical_mean[0]*check_cross\ncheck_quadratic+=empirical_mean[0]**2*source_quadratic[0,0,0]\ncheck_quadratic-=empirical_variance[0]*(check_cross-empirical_mean[0]*source_quadratic[0,0,0])**2/denominator[0,0,0]\ncheck_analytic=constant-.5*logdet[0,0,0]-(noise_shape+dimension/2.)*np.log(noise_rate+check_quadratic/2.)\ncheck_dense=multivariate_t.logpdf(check_observation,loc=empirical_mean[0]*empirical_white[0,0],\n    shape=(noise_rate/noise_shape)*check_covariance,df=2.*noise_shape)\nnp.testing.assert_allclose(check_analytic,check_dense,atol=1.e-8,rtol=1.e-10)\nprint("ASYMMETRIC_SOURCE_SETUP","fold",fold,"training_records",len(train_rows),"held_records",len(held_rows),\n    "source_period_pairs",len(train_rows)*period_n,"analytic_dense_difference",float(check_analytic-check_dense),flush=True)\nasymmetric_mass,asymmetric_wave,source_probability,asymmetric_log_evidence,minimum_quadratic=torch.vmap(\n    asymmetric_record,chunk_size=1)(torch.as_tensor(white_held))\nassert minimum_quadratic.min().item()>0.\nnp.testing.assert_allclose(source_probability.sum(dim=-1).numpy(),1.,atol=1.e-12)\n\npair_harmonic=np.concatenate([\n    np.broadcast_to(white_harmonic[:,None],(period_n,period_n,dimension,4)),\n    np.broadcast_to(white_harmonic[None],(period_n,period_n,dimension,4))],axis=-1)\npair_gram=np.einsum("pqdi,pqdj->pqij",pair_harmonic,pair_harmonic)\npair_precision=pair_gram+np.diag(1./coefficient_diagonal.ravel())[None,None]\npair_inverse=np.linalg.inv(pair_precision)\npair_logdet=np.linalg.slogdet(pair_precision)[1]+np.log(coefficient_diagonal).sum()\npair_rhs=np.einsum("nd,pqdi->npqi",white_held,pair_harmonic,optimize=True)\npair_coefficient=np.einsum("npqi,pqij->npqj",pair_rhs,pair_inverse,optimize=True)\npair_quadratic=np.sum(white_held**2,axis=-1)[:,None,None]-np.sum(pair_rhs*pair_coefficient,axis=-1)\nassert pair_quadratic.min()>0.\ngaussian_log=constant-.5*pair_logdet[None]-(noise_shape+dimension/2.)*np.log(noise_rate+pair_quadratic/2.)\ngaussian_log+=np.log(source_prior[0])[None,:,None]+np.log(source_prior[1])[None,None,:]\ngaussian_joint_mass=softmax(gaussian_log.reshape(len(held_rows),-1),axis=-1).reshape(len(held_rows),period_n,period_n)\ngaussian_mass=np.stack([gaussian_joint_mass.sum(axis=-1),gaussian_joint_mass.sum(axis=-2)],axis=1)\ngaussian_target_coefficient=np.einsum("npq,npqi->npi",gaussian_joint_mass,pair_coefficient[:,:,:,:4],optimize=True)\ngaussian_background_coefficient=np.einsum("npq,npqi->nqi",gaussian_joint_mass,pair_coefficient[:,:,:,4:],optimize=True)\ngaussian_wave=np.stack([np.einsum("npi,pti->nt",gaussian_target_coefficient,harmonic,optimize=True),\n    np.einsum("npi,pti->nt",gaussian_background_coefficient,harmonic,optimize=True)],axis=1)\nrole_mass=np.concatenate([asymmetric_mass.numpy(),gaussian_mass[:,None],\n    np.broadcast_to(source_prior,(len(held_rows),1,2,period_n))],axis=1)\nsource_pair_mean=np.concatenate([asymmetric_wave.numpy(),gaussian_wave[:,None]],axis=1)\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nrole_estimate=periods[role_score.argmax(axis=-1)]\nrole_confidence=role_score.max(axis=-1)\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\nmethods=np.array(asymmetric_settings["methods"])\nassert np.isfinite(role_mass).all() and np.allclose(role_mass.sum(axis=-1),1.)\npredictions=pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],len(methods)),\n    "method":np.tile(methods,len(held_rows)),"estimate_h":estimate.ravel(),\n    "confidence":confidence.ravel(),"heldout_fold":fold,\n    "heldout_run":np.repeat(run[heldout],len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    raw_waveform=mixed[heldout],periods=periods,methods=methods,mass=mass,estimate=estimate,confidence=confidence,\n    role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,source_prior=source_prior,\n    source_pair_mean=source_pair_mean,source_probability=source_probability.numpy(),\n    asymmetric_log_evidence=asymmetric_log_evidence.numpy(),gaussian_joint_mass=gaussian_joint_mass,\n    training_trace_id=trace_id[train],training_groups=training_groups,training_weight=row_weight,\n    source_period_mass=source_mass,coefficient_variance=coefficient_variance,\n    gain_mean=bundle["gain_mean"],gain_covariance=bundle["gain_covariance"],noise_shape=noise_shape,noise_rate=noise_rate,\n    source_mean_definition="posterior_mean_contribution_waveforms_for_first_three_methods",\n    period_mass_definition="latent_period_for_harmonic_role_and_optical_period_mark_for_empirical_role",\n    confidence_definition="model_period_probability_not_coverage_calibrated")\nprint("ASYMMETRIC_SOURCE_PREDICTED","fold",fold,"records",len(held_rows),\n    "minimum_quadratic",float(minimum_quadratic.min()),\n    "empirical_template_ESS_median",np.median(1./source_probability.square().sum(dim=-1).numpy(),axis=0).tolist(),flush=True)\nnative=native_evaluation\nexec(compile(structural_source_readout_stage[structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
