structural_candidate_interaction_stage = '\nexec(compile(structural_pair_competition_stage[:structural_pair_competition_stage.index("coordinate_basis=")]\n    .replace(\'application["structural_pair_competition"]\',\'application["structural_candidate_interaction"]\'),__file__,"exec"))\nexec(compile(structural_crossed_period_feature_stage[:structural_crossed_period_feature_stage.index("observed_features=")],__file__,"exec"))\nfeatures=phase_features(mixed,phase_operator).reshape(len(mixed),period_n,4)\nfeature_mean=np.einsum("n,npf->f",row_weight,features[train])/period_n\nfeature_sd=np.sqrt(np.einsum("n,npf->f",row_weight,(features[train]-feature_mean)**2)/period_n)\nstandardized=(features-feature_mean)/feature_sd\nquadratic_left,quadratic_right=np.triu_indices(4)\nquadratic=standardized[:,:,quadratic_left]*standardized[:,:,quadratic_right]\nquadratic_mean=np.einsum("n,npf->f",row_weight,quadratic[train])/period_n\nquadratic_sd=np.sqrt(np.einsum("n,npf->f",row_weight,(quadratic[train]-quadratic_mean)**2)/period_n)\nlocal_features=np.concatenate([standardized,(quadratic-quadratic_mean)/quadratic_sd],axis=-1)\nwithin_record_mean=standardized[train].mean(axis=1)\nwithin_record_second=(standardized[train]**2).mean(axis=1)\ncross_mean=np.einsum("n,nf,ng->fg",row_weight,within_record_mean,within_record_mean)\ncross_sd=np.sqrt(np.einsum("n,nf,ng->fg",row_weight,within_record_second,within_record_second)-cross_mean**2)\nassert np.isfinite(local_features).all() and cross_sd.min()>0. and quadratic_sd.min()>0.\njoint_teacher=source_mass[:,0,:,None]*source_mass[:,1,None,:]\njoint_prior=source_prior[0,:,None]*source_prior[1,None,:]\ntensor_local=torch.as_tensor(np.ascontiguousarray(local_features[train]))\ntensor_raw=torch.as_tensor(np.ascontiguousarray(standardized[train]))\ntensor_teacher=torch.as_tensor(joint_teacher)\ntensor_weight=torch.as_tensor(row_weight)\ntensor_prior=torch.as_tensor(np.log(joint_prior))\ntensor_cross_sd=torch.as_tensor(cross_sd)\nparameter_count=8+2*len(quadratic_left)+4**2\nparameter_mask=torch.as_tensor(np.arange(parameter_count)[None,:]<np.array([8,28,44])[:,None])\n# A globally centered cross feature differs by a candidate-independent constant,\n# which cancels exactly in the joint softmax; its scale is retained.\nforward=lambda vector,local,raw:(\n    weights:=vector.reshape(3,parameter_count)*parameter_mask,\n    target_weights:=torch.cat([weights[:,:4],weights[:,8:18]],dim=1),\n    background_weights:=torch.cat([weights[:,4:8],weights[:,18:28]],dim=1),\n    target_score:=torch.einsum("npf,mf->mnp",local,target_weights),\n    background_score:=torch.einsum("nqf,mf->mnq",local,background_weights),\n    cross_score:=torch.einsum("npf,mfg,nqg->mnpq",raw,weights[:,28:].reshape(3,4,4)/tensor_cross_sd,raw),\n    target_score[:,:,:,None]+background_score[:,:,None,:]+cross_score+tensor_prior)[-1]\ndata_losses=lambda vector:-(tensor_weight[None,:,None,None]*tensor_teacher[None]\n    *torch.log_softmax(forward(vector,tensor_local,tensor_raw).flatten(-2),dim=-1).reshape(3,len(train_rows),period_n,period_n)\n    ).sum(dim=(1,2,3))/2.\nobjective=lambda vector:data_losses(vector).mean()+fit_settings["weight_decay"]*vector.square().mean()\nautograd_objective=torch.func.grad_and_value(objective)\nto_scipy=lambda gradient,value:(value.detach().item(),gradient.detach().numpy())\nscipy_objective=lambda vector:to_scipy(*autograd_objective(torch.from_numpy(vector)))\ninitial=np.zeros(3*parameter_count)\ninitial_loss,initial_gradient=scipy_objective(initial)\nexpected_initial=-np.sum(source_prior*np.log(source_prior))/2.\nassert np.isclose(initial_loss,expected_initial,rtol=1.e-10) and np.isfinite(initial_gradient).all()\nloss_history=[[0,initial_loss]]\nprint("CANDIDATE_INTERACTION_SETUP","fold",fold,"training_records",len(train_rows),"held_records",len(held_rows),\n    "all_period_pairs",period_n**2,"active_parameters",parameter_mask.sum(dim=1).tolist(),\n    "initial_crossentropy",initial_loss,flush=True)\nresult=minimize(scipy_objective,initial,jac=True,method="L-BFGS-B",\n    callback=lambda intermediate_result:(loss_history.append([len(loss_history),float(intermediate_result.fun)]),\n        len(loss_history)%25==0 and print("CANDIDATE_INTERACTION_PROGRESS",fold,len(loss_history)-1,float(intermediate_result.fun),flush=True)),\n    options={"maxiter":fit_settings["maxiter"],"ftol":fit_settings["ftol"],"gtol":fit_settings["gtol"],"maxls":fit_settings["maxls"]})\nparameters=torch.as_tensor(result.x)\nassert np.isfinite(result.x).all() and np.isfinite(result.fun)\ntraining_losses=data_losses(parameters).detach().numpy()\ndump({"parameters":result.x.reshape(3,parameter_count),"parameter_mask":parameter_mask.numpy(),\n    "feature_mean":feature_mean,"feature_sd":feature_sd,"quadratic_mean":quadratic_mean,"quadratic_sd":quadratic_sd,\n    "quadratic_left":quadratic_left,"quadratic_right":quadratic_right,"cross_mean":cross_mean,"cross_sd":cross_sd,\n    "phase_operator":phase_operator,"source_prior":source_prior,"source_period_mass":source_mass,\n    "training_trace_id":trace_id[train],"training_groups":training_groups,"training_weight":row_weight,\n    "optimization":result,"loss_history":np.asarray(loss_history),"training_crossentropy":training_losses,\n    "configuration":competition_settings,"fit_configuration":fit_settings,"heldout_optical_read":False},stem.with_suffix(".joblib"))\nlogit=forward(parameters,torch.as_tensor(np.ascontiguousarray(local_features[heldout])),\n    torch.as_tensor(np.ascontiguousarray(standardized[heldout]))).detach().numpy()\njoint_mass=softmax(logit.reshape(3,len(held_rows),-1),axis=-1).transpose(1,0,2).reshape(len(held_rows),3,period_n,period_n)\nrole_mass=np.concatenate([np.stack([joint_mass.sum(axis=-1),joint_mass.sum(axis=-2)],axis=2),\n    np.broadcast_to(source_prior,(len(held_rows),1,2,period_n))],axis=1)\nnp.testing.assert_allclose(joint_mass[:,:2],role_mass[:,:2,0,:,None]*role_mass[:,:2,1,None,:],rtol=1.e-10,atol=1.e-12)\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nrole_estimate=periods[role_score.argmax(axis=-1)]\nrole_confidence=role_score.max(axis=-1)\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\nmethods=np.array(competition_settings["methods"])\nassert np.isfinite(role_mass).all() and np.allclose(role_mass.sum(axis=-1),1.)\npredictions=pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],len(methods)),\n    "method":np.tile(methods,len(held_rows)),"estimate_h":estimate.ravel(),\n    "confidence":confidence.ravel(),"heldout_fold":fold,\n    "heldout_run":np.repeat(run[heldout],len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    periods=periods,methods=methods,mass=mass,estimate=estimate,confidence=confidence,\n    role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,joint_mass=joint_mass,\n    source_prior=source_prior,training_trace_id=trace_id[train],training_groups=training_groups,\n    source_period_mass=source_mass,confidence_definition="supervised_named_source_joint_period_mass_not_coverage_calibrated")\nprint("CANDIDATE_INTERACTION_FIT","fold",fold,"iterations",result.nit,\n    "training_crossentropy",training_losses.tolist(),"status",str(result.message),flush=True)\nnative=native_evaluation\nexec(compile(structural_source_readout_stage[structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
exec(compile({True:structural_candidate_interaction_stage,False:""}[args.stage=="structural-candidate-interaction"],__file__,"exec"))


structural_evidence_calibration_stage = '\nexec(compile(structural_global_factorial_stage[:structural_global_factorial_stage.index("global_record=")],__file__,"exec"))\nfrom scipy.optimize import minimize\nfrom joblib import dump\ncalibration_settings=application["structural_evidence_calibration"]\nfit_settings=application["structural_crossed_period"]\nstem=calibration_settings["stem"].with_name(calibration_settings["stem"].name+"_common_fold"+str(fold))\ntensor_group=torch.as_tensor(source_group)\ntensor_source_logweight=torch.as_tensor(np.log(source_weight))\ntensor_source_mass=torch.as_tensor(np.ascontiguousarray(source_mass.transpose(1,0,2)))\n# The template bank excludes every source from the query\'s training experiment.\n# Nuisance gain/noise estimates remain the fixed outer-training estimates.\nexcluded_record=lambda observed,query_group:(\n    projection:=torch.einsum("nrd,d->nr",tensor_source,observed)+tensor_natural,\n    left:=projection[:,0,None],right:=projection[None,:,1],\n    quadratic:=observed.square().sum()+prior_quadratic\n        -(tensor_right*left.square()-2.*tensor_cross*left*right+tensor_left*right.square())/tensor_determinant,\n    log_likelihood:=tensor_constant-(noise_shape+dimension/2.)*torch.log(noise_rate+quadratic/2.),\n    allowed:=tensor_group!=query_group,\n    log_weight:=torch.where(allowed,tensor_source_logweight,-torch.inf),\n    log_weight:=log_weight-torch.logsumexp(log_weight,dim=0),\n    log_joint:=log_likelihood+log_weight[:,None]+log_weight[None],\n    probability:=torch.softmax(log_joint.flatten(),dim=0).reshape(source_n,source_n),\n    source_probability:=torch.stack([probability.sum(dim=-1),probability.sum(dim=-2)]),\n    mass:=torch.einsum("rn,rnp->rp",source_probability,tensor_source_mass),\n    excluded_mass:=(source_probability*(~allowed)[None]).sum(),\n    (mass,excluded_mass,quadratic.min()))[-1]\nwhite_training=(mixed[train]@coordinate_basis)/np.sqrt(noise_eigenvalue)[None]\nprint("EVIDENCE_CALIBRATION_SETUP","fold",fold,"training_records",len(train_rows),\n    "training_experiments",len(source_groups),"held_records",len(held_rows),\n    "cross_experiment_source_bank",True,flush=True)\ntraining_mass,excluded_probability,minimum_quadratic=torch.vmap(excluded_record,chunk_size=1)(\n    torch.as_tensor(white_training),tensor_group)\nassert excluded_probability.max().item()==0. and minimum_quadratic.min().item()>0.\ntraining_mass=training_mass.numpy()\nexcluded_weight=source_weight[None]*(source_group[:,None]!=source_group[None])\nexcluded_weight/=excluded_weight.sum(axis=1)[:,None]\nexcluded_prior=np.einsum("ij,jrp->irp",excluded_weight,source_mass,optimize=True)\nparent_prediction=application["structural_global_factorial"]["stem"]\nparent_prediction=parent_prediction.with_name(parent_prediction.name+"_common_fold"+str(fold)).with_suffix(".npz")\nparent_prediction=np.load(parent_prediction,allow_pickle=False)\nassert np.array_equal(parent_prediction["trace_id"],trace_id[heldout])\nnp.testing.assert_allclose(parent_prediction["source_prior"],source_prior,atol=1.e-13)\nheld_mass=parent_prediction["role_mass"][:,0]\ncheck_mass=excluded_record(torch.as_tensor(white_held[0]),torch.tensor(len(source_groups)))[0].numpy()\nnp.testing.assert_allclose(check_mass,held_mass[0],atol=1.e-12,rtol=1.e-10)\ntrain_log_ratio=np.log(training_mass)-np.log(excluded_prior)\nheld_log_ratio=np.log(held_mass)-np.log(source_prior)[None]\nratio_mean=np.einsum("n,nrp->r",row_weight,train_log_ratio)/period_n\nratio_sd=np.sqrt(np.einsum("n,nrp->r",row_weight,(train_log_ratio-ratio_mean[None,:,None])**2)/period_n)\nassert ratio_sd.min()>0. and np.isfinite(train_log_ratio).all()\ntrain_log_ratio=(train_log_ratio-ratio_mean[None,:,None])/ratio_sd[None,:,None]\nheld_log_ratio=(held_log_ratio-ratio_mean[None,:,None])/ratio_sd[None,:,None]\nexec(compile(structural_crossed_period_feature_stage[:structural_crossed_period_feature_stage.index("observed_features=")],__file__,"exec"))\nfeatures=phase_features(mixed,phase_operator).reshape(len(mixed),period_n,4)\nfeature_mean=np.einsum("n,npf->f",row_weight,features[train])/period_n\nfeature_sd=np.sqrt(np.einsum("n,npf->f",row_weight,(features[train]-feature_mean)**2)/period_n)\nstandardized=(features-feature_mean)/feature_sd\ntensor_local=torch.as_tensor(np.ascontiguousarray(standardized[train]))\ntensor_ratio=torch.as_tensor(train_log_ratio)\ntensor_teacher=torch.as_tensor(source_mass)\ntensor_weight=torch.as_tensor(row_weight)\ntensor_prior=torch.as_tensor(np.log(source_prior))\nparameter_count=2*features.shape[-1]+2\nparameter_mask=torch.as_tensor(np.stack([np.arange(parameter_count)<8,np.arange(parameter_count)>=8,\n    np.ones(parameter_count,dtype=bool)]))\nforward=lambda vector,local,ratio:(\n    weights:=vector.reshape(3,parameter_count)*parameter_mask,\n    local_score:=torch.einsum("npf,mrf->mnrp",local,weights[:,:8].reshape(3,2,4)),\n    local_score+ratio[None]*weights[:,None,8:,None]+tensor_prior[None,None])[-1]\ndata_losses=lambda vector:-(tensor_weight[None,:,None,None]*tensor_teacher[None]\n    *torch.log_softmax(forward(vector,tensor_local,tensor_ratio),dim=-1)).sum(dim=(1,2,3))/2.\nobjective=lambda vector:data_losses(vector).mean()+fit_settings["weight_decay"]*vector.square().mean()\nautograd_objective=torch.func.grad_and_value(objective)\nto_scipy=lambda gradient,value:(value.detach().item(),gradient.detach().numpy())\nscipy_objective=lambda vector:to_scipy(*autograd_objective(torch.from_numpy(vector)))\ninitial=np.zeros(3*parameter_count)\ninitial_loss,initial_gradient=scipy_objective(initial)\nassert np.isclose(initial_loss,-np.sum(source_prior*np.log(source_prior))/2.,rtol=1.e-10)\nbounds=np.broadcast_to(np.array([-np.inf,np.inf]),(3,parameter_count,2)).copy()\nbounds[:,8:,0]=0.\nloss_history=[[0,initial_loss]]\nprint("EVIDENCE_CALIBRATION_TRAIN","fold",fold,"excluded_run_probability",float(excluded_probability.max()),\n    "active_parameters",parameter_mask.sum(dim=1).tolist(),"ratio_sd",ratio_sd.tolist(),flush=True)\nresult=minimize(scipy_objective,initial,jac=True,method="L-BFGS-B",bounds=bounds.reshape(-1,2),\n    callback=lambda intermediate_result:(loss_history.append([len(loss_history),float(intermediate_result.fun)]),\n        len(loss_history)%25==0 and print("EVIDENCE_CALIBRATION_PROGRESS",fold,len(loss_history)-1,float(intermediate_result.fun),flush=True)),\n    options={"maxiter":fit_settings["maxiter"],"ftol":fit_settings["ftol"],"gtol":fit_settings["gtol"],"maxls":fit_settings["maxls"]})\nparameters=torch.as_tensor(result.x)\ntraining_losses=data_losses(parameters).detach().numpy()\nassert np.isfinite(result.x).all() and np.isfinite(result.fun)\ndump({"parameters":result.x.reshape(3,parameter_count),"parameter_mask":parameter_mask.numpy(),\n    "feature_mean":feature_mean,"feature_sd":feature_sd,"phase_operator":phase_operator,\n    "ratio_mean":ratio_mean,"ratio_sd":ratio_sd,"training_excluded_run_role_mass":training_mass,\n    "training_excluded_run_prior":excluded_prior,"training_excluded_probability":excluded_probability.numpy(),\n    "source_prior":source_prior,"source_period_mass":source_mass,\n    "training_trace_id":trace_id[train],"training_groups":training_groups,"training_weight":row_weight,\n    "optimization":result,"loss_history":np.asarray(loss_history),"training_crossentropy":training_losses,\n    "configuration":calibration_settings,"fit_configuration":fit_settings,"heldout_optical_read":False,\n    "nuisance_estimation":"same_outer_training_NIG_estimates_for_all_inner_excluded_template_banks"},stem.with_suffix(".joblib"))\nlogit=forward(parameters,torch.as_tensor(np.ascontiguousarray(standardized[heldout])),\n    torch.as_tensor(held_log_ratio)).detach().numpy().transpose(1,0,2,3)\nrole_mass=np.concatenate([softmax(logit,axis=-1),\n    np.broadcast_to(source_prior,(len(held_rows),1,2,period_n))],axis=1)\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nrole_estimate=periods[role_score.argmax(axis=-1)]\nrole_confidence=role_score.max(axis=-1)\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\nmethods=np.array(calibration_settings["methods"])\nassert np.isfinite(role_mass).all() and np.allclose(role_mass.sum(axis=-1),1.)\npredictions=pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],len(methods)),\n    "method":np.tile(methods,len(held_rows)),"estimate_h":estimate.ravel(),\n    "confidence":confidence.ravel(),"heldout_fold":fold,\n    "heldout_run":np.repeat(run[heldout],len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    periods=periods,methods=methods,mass=mass,estimate=estimate,confidence=confidence,\n    role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,\n    source_prior=source_prior,training_trace_id=trace_id[train],training_groups=training_groups,\n    source_period_mass=source_mass,confidence_definition="supervised_named_source_period_mass_not_coverage_calibrated")\nprint("EVIDENCE_CALIBRATION_FIT","fold",fold,"iterations",result.nit,\n    "training_crossentropy",training_losses.tolist(),"generative_weights",result.x.reshape(3,parameter_count)[:,8:].tolist(),\n    "status",str(result.message),flush=True)\nnative=native_evaluation\nexec(compile(structural_source_readout_stage[structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
