structural_kernel_source_stage = '\nexec(compile(structural_pair_competition_stage[:structural_pair_competition_stage.index("coordinate_basis=")]\n    .replace(\'application["structural_pair_competition"]\',\'application["structural_kernel_source"]\'),__file__,"exec"))\nfrom scipy.spatial.distance import cdist\nkernel_settings=competition_settings\nexec(compile(structural_crossed_period_feature_stage[:structural_crossed_period_feature_stage.index("observed_features=")],__file__,"exec"))\nfeatures=phase_features(mixed,phase_operator).reshape(len(mixed),period_n,4)\nfeature_mean=np.einsum("n,npf->f",row_weight,features[train])/period_n\nfeature_sd=np.sqrt(np.einsum("n,npf->f",row_weight,(features[train]-feature_mean)**2)/period_n)\nstandardized=(features-feature_mean)/feature_sd\npower=standardized[:,:,:2].reshape(len(mixed),-1)\ncoupling=standardized[:,:,2:].reshape(len(mixed),-1)\ndistances=np.stack([cdist(mixed,mixed[train],metric="sqeuclidean")/length,\n    cdist(power,power[train],metric="sqeuclidean")/power.shape[1],\n    cdist(coupling,coupling[train],metric="sqeuclidean")/coupling.shape[1]],axis=-1)\nsame_run=run[train,None]==run[None,train]\nsource_logweight=np.log(row_weight)\ntraining_logweight=np.where(same_run,-np.inf,source_logweight[None])\nheld_logweight=np.broadcast_to(source_logweight,(len(held_rows),len(train_rows)))\ntensor_distance=torch.as_tensor(np.ascontiguousarray(distances[train]))\ntensor_teacher=torch.as_tensor(source_mass)\ntensor_weight=torch.as_tensor(row_weight)\ntensor_logweight=torch.as_tensor(training_logweight)\nmetric_mask=torch.as_tensor(np.array([[1.,0.,0.],[0.,1.,1.],[1.,1.,1.]]))[:,None]\nkernel_weights=lambda vector,distance,logweight:(\n    metric:=vector.reshape(3,2,3)*metric_mask,\n    torch.softmax(-.5*torch.einsum("njd,mrd->mnrj",distance,metric)+logweight[None,:,None],dim=-1))[-1]\nforward=lambda vector,distance,logweight:torch.einsum("mnrj,jrp->mnrp",\n    kernel_weights(vector,distance,logweight),tensor_teacher)\ndata_losses=lambda vector:-(tensor_weight[None,:,None,None]*tensor_teacher[None]\n    *torch.log(forward(vector,tensor_distance,tensor_logweight))).sum(dim=(1,2,3))/2.\nobjective=lambda vector:data_losses(vector).mean()+fit_settings["weight_decay"]*vector.square().mean()\nautograd_objective=torch.func.grad_and_value(objective)\nto_scipy=lambda gradient,value:(value.detach().item(),gradient.detach().numpy())\nscipy_objective=lambda vector:to_scipy(*autograd_objective(torch.from_numpy(vector)))\ninitial=np.broadcast_to(metric_mask.numpy(),(3,2,3)).ravel().copy()\ninitial_loss,initial_gradient=scipy_objective(initial)\nprior_loss,prior_gradient=scipy_objective(np.zeros_like(initial))\nassert np.isfinite(initial_gradient).all() and np.isfinite(prior_gradient).all()\nloss_history=[[0,initial_loss]]\nprint("KERNEL_SOURCE_SETUP","fold",fold,"training_records",len(train_rows),"held_records",len(held_rows),\n    "representation_dimensions",[length,power.shape[1],coupling.shape[1]],"excluded_experiment_pairs",int(same_run.sum()),\n    "initial_crossentropy",initial_loss,"excluded_prior_crossentropy",prior_loss,flush=True)\nresult=minimize(scipy_objective,initial,jac=True,method="L-BFGS-B",bounds=np.tile([0.,np.inf],(len(initial),1)),\n    callback=lambda intermediate_result:(loss_history.append([len(loss_history),float(intermediate_result.fun)]),\n        len(loss_history)%25==0 and print("KERNEL_SOURCE_PROGRESS",fold,len(loss_history)-1,float(intermediate_result.fun),flush=True)),\n    options={"maxiter":fit_settings["maxiter"],"ftol":fit_settings["ftol"],"gtol":fit_settings["gtol"],"maxls":fit_settings["maxls"]})\nparameters=torch.as_tensor(result.x)\ntraining_losses=data_losses(parameters).detach().numpy()\ntraining_kernel=kernel_weights(parameters,tensor_distance,tensor_logweight)\nexcluded_probability=(training_kernel*torch.as_tensor(same_run)[None,:,None]).sum(dim=-1)\nassert excluded_probability.max().item()==0.\nheld_kernel=kernel_weights(parameters,torch.as_tensor(np.ascontiguousarray(distances[heldout])),\n    torch.as_tensor(held_logweight))\npredicted_mass=torch.einsum("mnrj,jrp->mnrp",held_kernel,tensor_teacher).detach().numpy().transpose(1,0,2,3)\nrole_mass=np.concatenate([predicted_mass,np.broadcast_to(source_prior,(len(held_rows),1,2,period_n))],axis=1)\neffective_n=1./held_kernel.square().sum(dim=-1).detach().numpy().transpose(1,0,2)\ndump({"inverse_bandwidth_square":result.x.reshape(3,2,3),"metric_mask":metric_mask.numpy(),\n    "feature_mean":feature_mean,"feature_sd":feature_sd,"phase_operator":phase_operator,\n    "training_raw":mixed[train],"training_phase":standardized[train],\n    "source_prior":source_prior,"source_period_mass":source_mass,\n    "training_trace_id":trace_id[train],"training_groups":training_groups,"training_weight":row_weight,\n    "optimization":result,"loss_history":np.asarray(loss_history),"training_crossentropy":training_losses,\n    "excluded_prior_crossentropy":prior_loss,"configuration":kernel_settings,"fit_configuration":fit_settings,\n    "heldout_optical_read":False},stem.with_suffix(".joblib"))\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nrole_estimate=periods[role_score.argmax(axis=-1)]\nrole_confidence=role_score.max(axis=-1)\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\nmethods=np.array(kernel_settings["methods"])\nassert np.isfinite(role_mass).all() and np.allclose(role_mass.sum(axis=-1),1.)\npredictions=pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],len(methods)),\n    "method":np.tile(methods,len(held_rows)),"estimate_h":estimate.ravel(),\n    "confidence":confidence.ravel(),"heldout_fold":fold,\n    "heldout_run":np.repeat(run[heldout],len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    periods=periods,methods=methods,mass=mass,estimate=estimate,confidence=confidence,\n    role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,\n    source_prior=source_prior,training_trace_id=trace_id[train],training_groups=training_groups,\n    source_period_mass=source_mass,kernel_weight=held_kernel.detach().numpy().transpose(1,0,2,3),\n    effective_template_n=effective_n,confidence_definition="supervised_named_source_period_mass_not_coverage_calibrated")\nprint("KERNEL_SOURCE_FIT","fold",fold,"iterations",result.nit,\n    "training_crossentropy",training_losses.tolist(),"inverse_bandwidth_square",result.x.reshape(3,2,3).tolist(),\n    "held_effective_n_median",np.median(effective_n,axis=0).tolist(),\n    "status",str(result.message),flush=True)\nnative=native_evaluation\nexec(compile(structural_source_readout_stage[structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
exec(compile({True:structural_kernel_source_stage,False:""}[args.stage=="structural-kernel-source"],__file__,"exec"))


structural_teacher_horizon_stage = '\nexec(compile(structural_pair_competition_stage[:structural_pair_competition_stage.index("coordinate_basis=")]\n    .replace(\'application["structural_pair_competition"]\',\'application["structural_teacher_horizon"]\'),__file__,"exec"))\nhorizon_settings=competition_settings\n# Additional optical time points are used only for native training outcomes.\n# The prediction input remains the same common No interval for every model.\nfull_time=np.sort(optical.time_h.unique())\nfull_target=optical.pivot(index="trace_id",columns="time_h",values="published_target_y").reindex(\n    index=trace_id[train],columns=full_time).to_numpy()\nfull_background=(optical.assign(background=optical.green*application["background_templates"]["optical_coefficients"][0]\n    +optical.red*application["background_templates"]["optical_coefficients"][1])\n    .pivot(index="trace_id",columns="time_h",values="background")\n    .reindex(index=trace_id[train],columns=full_time).to_numpy())\nfull_raw=np.stack([full_target,full_background],axis=1)\nfull_mask=np.isfinite(full_target)\nfull_count=full_mask.sum(axis=1)\nassert np.array_equal(np.isfinite(full_raw),np.broadcast_to(full_mask[:,None],full_raw.shape))\nassert np.array_equal(full_mask,np.arange(len(full_time))[None]<full_count[:,None])\nfull_centered_time=np.where(full_mask,full_time[None]-(full_mask*full_time[None]).sum(axis=1)[:,None]/full_count[:,None],0.)\nfull_base=np.stack([full_mask/np.sqrt(full_count[:,None]),\n    full_centered_time/np.linalg.norm(full_centered_time,axis=1)[:,None]],axis=-1)\nfull_raw=np.where(full_mask[:,None],full_raw,0.)\nfull_optical=full_raw-np.einsum("nti,nri->nrt",full_base,np.einsum("nti,nrt->nri",full_base,full_raw))\nteacher_code=structural_source_readout_stage.split("prior_labels =",1)[0]\nteacher_code=teacher_code.replace("waves = np.stack([prediction,mixed[heldout]],axis=1)","waves = full_optical")\nteacher_code=teacher_code.replace("held_mask = mask[heldout]","held_mask = full_mask")\nteacher_code=teacher_code.replace("held_count = count[heldout]","held_count = full_count")\nteacher_scope={"np":np,"application":application,"time":full_time,\n    "full_optical":full_optical,"full_mask":full_mask,"full_count":full_count}\nexec(compile(teacher_code,__file__,"exec"),teacher_scope)\nnp.testing.assert_array_equal(periods,teacher_scope["periods"])\nfull_teacher=softmax(teacher_scope["log_evidence"].reshape(len(train_rows),2,period_n)\n    +np.log(teacher_scope["grid_weight"])[None,None],axis=-1)\nwindow_teacher=np.zeros_like(source_mass)\nnp.add.at(window_teacher,bundle["source_record"],bundle["source_period_mass"])\nwindow_teacher/=np.bincount(bundle["source_record"])[:,None,None]\nteacher_mass=np.stack([source_mass,full_teacher,window_teacher],axis=1)\nteacher_prior=np.einsum("n,nmrp->mrp",row_weight,teacher_mass,optimize=True)\nassert np.allclose(teacher_mass.sum(axis=-1),1.) and np.isfinite(teacher_mass).all()\nexec(compile(structural_crossed_period_feature_stage[:structural_crossed_period_feature_stage.index("observed_features=")],__file__,"exec"))\nfeatures=phase_features(mixed,phase_operator).reshape(len(mixed),period_n,4)\nfeature_mean=np.einsum("n,npf->f",row_weight,features[train])/period_n\nfeature_sd=np.sqrt(np.einsum("n,npf->f",row_weight,(features[train]-feature_mean)**2)/period_n)\nstandardized=(features-feature_mean)/feature_sd\ntensor_features=torch.as_tensor(np.ascontiguousarray(standardized[train]))\ntensor_teacher=torch.as_tensor(teacher_mass.transpose(1,0,2,3).copy())\ntensor_weight=torch.as_tensor(row_weight)\ntensor_prior=torch.as_tensor(np.log(teacher_prior))\nforward=lambda vector,values:torch.einsum("npf,mrf->mnrp",values,vector.reshape(3,2,4))+tensor_prior[:,None]\ndata_losses=lambda vector:-(tensor_weight[None,:,None,None]*tensor_teacher\n    *torch.log_softmax(forward(vector,tensor_features),dim=-1)).sum(dim=(1,2,3))/2.\nobjective=lambda vector:data_losses(vector).mean()+fit_settings["weight_decay"]*vector.square().mean()\nautograd_objective=torch.func.grad_and_value(objective)\nto_scipy=lambda gradient,value:(value.detach().item(),gradient.detach().numpy())\nscipy_objective=lambda vector:to_scipy(*autograd_objective(torch.from_numpy(vector)))\ninitial=np.zeros(3*2*4)\ninitial_loss,initial_gradient=scipy_objective(initial)\nassert np.isclose(initial_loss,-np.sum(teacher_prior*np.log(teacher_prior))/6.,rtol=1.e-10)\nassert np.isfinite(initial_gradient).all()\nloss_history=[[0,initial_loss]]\nprint("TEACHER_HORIZON_SETUP","fold",fold,"training_records",len(train_rows),"held_records",len(held_rows),\n    "common_input_length",length,"native_training_optical_lengths",np.unique(full_count).tolist(),\n    "teacher_entropy",np.einsum("n,nmrp->mr",row_weight,-teacher_mass*np.log(teacher_mass)).tolist(),flush=True)\nresult=minimize(scipy_objective,initial,jac=True,method="L-BFGS-B",\n    callback=lambda intermediate_result:(loss_history.append([len(loss_history),float(intermediate_result.fun)]),\n        len(loss_history)%25==0 and print("TEACHER_HORIZON_PROGRESS",fold,len(loss_history)-1,float(intermediate_result.fun),flush=True)),\n    options={"maxiter":fit_settings["maxiter"],"ftol":fit_settings["ftol"],"gtol":fit_settings["gtol"],"maxls":fit_settings["maxls"]})\nparameters=torch.as_tensor(result.x)\ntraining_losses=data_losses(parameters).detach().numpy()\nassert np.isfinite(result.x).all() and np.isfinite(result.fun)\ndump({"parameters":result.x.reshape(3,2,4),"feature_mean":feature_mean,"feature_sd":feature_sd,\n    "phase_operator":phase_operator,"teacher_period_mass":teacher_mass,"teacher_prior":teacher_prior,\n    "training_trace_id":trace_id[train],"training_groups":training_groups,"training_weight":row_weight,\n    "native_training_optical_count":full_count,"common_input_time":time,"full_training_optical_time":full_time,\n    "optimization":result,"loss_history":np.asarray(loss_history),"training_crossentropy":training_losses,\n    "configuration":horizon_settings,"fit_configuration":fit_settings,"heldout_optical_read":False},stem.with_suffix(".joblib"))\nlogit=forward(parameters,torch.as_tensor(np.ascontiguousarray(standardized[heldout]))).detach().numpy().transpose(1,0,2,3)\nrole_mass=np.concatenate([softmax(logit,axis=-1),np.broadcast_to(teacher_prior,(len(held_rows),3,2,period_n))],axis=1)\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nrole_estimate=periods[role_score.argmax(axis=-1)]\nrole_confidence=role_score.max(axis=-1)\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\nmethods=np.array(horizon_settings["methods"])\nassert np.isfinite(role_mass).all() and np.allclose(role_mass.sum(axis=-1),1.)\npredictions=pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],len(methods)),\n    "method":np.tile(methods,len(held_rows)),"estimate_h":estimate.ravel(),\n    "confidence":confidence.ravel(),"heldout_fold":fold,\n    "heldout_run":np.repeat(run[heldout],len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    periods=periods,methods=methods,mass=mass,estimate=estimate,confidence=confidence,\n    role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,\n    teacher_prior=teacher_prior,teacher_period_mass=teacher_mass,training_trace_id=trace_id[train],training_groups=training_groups,\n    confidence_definition="supervised_named_source_period_mass_teacher_horizon_specific_not_coverage_calibrated")\nprint("TEACHER_HORIZON_FIT","fold",fold,"iterations",result.nit,\n    "training_crossentropy",training_losses.tolist(),"weights",result.x.reshape(3,2,4).tolist(),\n    "status",str(result.message),flush=True)\nnative=native_evaluation\nexec(compile(structural_source_readout_stage[structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
exec(compile({True:structural_teacher_horizon_stage,False:""}[args.stage=="structural-teacher-horizon"],__file__,"exec"))


structural_calibrated_population_stage = '\nfrom scipy.special import softmax,logsumexp\nfold=args.heldout_run\nassert fold==application["lemna_expected_runs"]\npopulation_settings=application["structural_calibrated_population"]\nstem=population_settings["stem"].with_name(population_settings["stem"].name+"_common_fold"+str(fold))\nsource_stem=application["structural_calibrated_phase"]["stem"]\nsource_stem=source_stem.with_name(source_stem.name+"_common_fold"+str(fold))\nhierarchy_stem=application["structural_phase_population"]["stem"]\nhierarchy_stem=hierarchy_stem.with_name(hierarchy_stem.name+"_common_fold"+str(fold))\nsource=np.load(source_stem.with_suffix(".npz"),allow_pickle=False)\nhierarchy=np.load(hierarchy_stem.with_suffix(".npz"),allow_pickle=False)\nnp.testing.assert_array_equal(source["trace_id"],hierarchy["trace_id"])\nnp.testing.assert_array_equal(source["periods"],hierarchy["periods"])\nnp.testing.assert_array_equal(source["training_trace_id"],hierarchy["training_trace_id"])\ntrace_id=source["trace_id"]\nperiods=source["periods"]\nheldout=np.ones(len(trace_id),dtype=bool)\ngroup_index=hierarchy["group_index"]\ngroup_names=hierarchy["group_names"]\nrun=group_names[group_index]\ntransition=hierarchy["transition"]\ngroup_prior=hierarchy["group_mean_prior"]\nindividual_prior=hierarchy["individual_prior"]\nlog_likelihood=source["base_marginal_evidence"]\nlikelihood=np.exp(log_likelihood-log_likelihood.max(axis=(1,2),keepdims=True))\ngroup_mean_likelihood=np.einsum("up,npq,vq->nuv",transition[0],likelihood,transition[1],optimize=True)\nassert group_mean_likelihood.min()>0.\ngroup_logmass=np.broadcast_to(np.log(group_prior[0,:,None])+np.log(group_prior[1,None,:]),\n    (len(group_names),len(periods),len(periods))).copy()\nnp.add.at(group_logmass,group_index,np.log(group_mean_likelihood))\ngroup_logmass-=logsumexp(group_logmass,axis=(1,2),keepdims=True)\ngroup_mass=np.exp(group_logmass)\nother_logmass=group_logmass[group_index]-np.log(group_mean_likelihood)\nother_logmass-=logsumexp(other_logmass,axis=(1,2),keepdims=True)\nborrowed_prior=np.einsum("up,nuv,vq->npq",transition[0],np.exp(other_logmass),transition[1],optimize=True)\npopulation_joint=likelihood*borrowed_prior\npopulation_joint/=population_joint.sum(axis=(1,2),keepdims=True)\nindividual_logmass=log_likelihood+np.log(individual_prior[0,:,None])+np.log(individual_prior[1,None,:])\nindividual_joint=np.exp(individual_logmass-logsumexp(individual_logmass,axis=(1,2),keepdims=True))\nprior_joint=individual_prior[0,:,None]*individual_prior[1,None,:]\nsingleton_prior=transition[0].T@(group_prior[0,:,None]*group_prior[1,None,:])@transition[1]\nnp.testing.assert_allclose(singleton_prior,prior_joint,atol=1.e-13,rtol=1.e-10)\nsingleton_joint=likelihood*singleton_prior[None]\nsingleton_joint/=singleton_joint.sum(axis=(1,2),keepdims=True)\nnp.testing.assert_allclose(singleton_joint,individual_joint,atol=1.e-12,rtol=1.e-10)\njoint_mass=np.stack([population_joint,individual_joint,np.broadcast_to(prior_joint,population_joint.shape)],axis=1)\nrole_mass=np.stack([joint_mass.sum(axis=-1),joint_mass.sum(axis=-2)],axis=2)\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nrole_estimate=periods[role_score.argmax(axis=-1)]\nrole_confidence=role_score.max(axis=-1)\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\nmethods=np.array(population_settings["methods"])\nassert np.isfinite(role_mass).all() and np.allclose(role_mass.sum(axis=-1),1.)\npredictions=pd.DataFrame({"trace_id":np.repeat(trace_id,len(methods)),\n    "method":np.tile(methods,len(trace_id)),"estimate_h":estimate.ravel(),\n    "confidence":confidence.ravel(),"heldout_fold":fold,\n    "heldout_run":np.repeat(run,len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id,time=source["time"],mask=source["mask"],\n    periods=periods,methods=methods,mass=mass,estimate=estimate,confidence=confidence,\n    role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,joint_mass=joint_mass,\n    group_mass=group_mass,group_names=group_names,group_index=group_index,\n    group_mean_prior=group_prior,individual_prior=individual_prior,transition=transition,\n    base_marginal_evidence=log_likelihood,within_period_variance=hierarchy["within_period_variance"],\n    training_trace_id=source["training_trace_id"],training_groups=source["training_groups"],\n    parent_calibrated_observation=str(source_stem),parent_period_hierarchy=str(hierarchy_stem),\n    confidence_definition="normal_amplitude_calibrated_power_period_hierarchy_not_coverage_calibrated")\nprint("CALIBRATED_POPULATION_PREDICTED","records",len(trace_id),"within_period_sd",\n    np.sqrt(hierarchy["within_period_variance"]).tolist(),"group_modes",\n    periods[np.stack([group_mass.sum(axis=-1).argmax(axis=-1),group_mass.sum(axis=-2).argmax(axis=-1)],axis=-1)].tolist(),\n    "singleton_identity_error",float(np.max(np.abs(singleton_joint-individual_joint))),flush=True)\nnative=False\nexec(compile(structural_source_readout_stage[structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
exec(compile({True:structural_calibrated_population_stage,False:""}[args.stage=="structural-calibrated-population"],__file__,"exec"))


structural_cross_phase_stage = '\nexec(compile(structural_pair_competition_stage[:structural_pair_competition_stage.index("coordinate_basis=")]\n    .replace(\'application["structural_pair_competition"]\',\'application["structural_cross_phase"]\'),__file__,"exec"))\ncross_settings=competition_settings\nexec(compile(structural_crossed_period_feature_stage[:structural_crossed_period_feature_stage.index("observed_features=")],__file__,"exec"))\nfeatures=phase_features(mixed,phase_operator).reshape(len(mixed),period_n,4)\nfeature_mean=np.einsum("n,npf->f",row_weight,features[train])/period_n\nfeature_sd=np.sqrt(np.einsum("n,npf->f",row_weight,(features[train]-feature_mean)**2)/period_n)\nstandardized=(features-feature_mean)/feature_sd\nfrequency=1./periods\nsum_frequency=frequency[:,None]+frequency[None]\ndifference_frequency=frequency[:,None]-frequency[None]\nfundamental=mixed@np.exp(-2.j*np.pi*time[:,None]*frequency[None])/length\nsum_coefficient=(mixed@np.exp(-2.j*np.pi*time[:,None]*sum_frequency.ravel()[None])/length).reshape(\n    len(mixed),period_n,period_n)\ndifference_coefficient=(mixed@np.exp(-2.j*np.pi*time[:,None]*difference_frequency.ravel()[None])/length).reshape(\n    len(mixed),period_n,period_n)\npair_features=lambda first,addition,difference:(\n    first_power:=np.abs(first)**2,\n    addition_power:=np.abs(addition)**2,\n    difference_power:=np.abs(difference)**2,\n    sum_closure:=first[:,:,None]*first[:,None,:]*np.conj(addition)\n        /(first_power[:,:,None]+first_power[:,None,:]+addition_power)**1.5,\n    difference_closure:=first[:,:,None]*np.conj(first[:,None,:])*np.conj(difference)\n        /(first_power[:,:,None]+first_power[:,None,:]+difference_power)**1.5,\n    np.stack([addition_power,difference_power,sum_closure.real,sum_closure.imag,\n        difference_closure.real,difference_closure.imag],axis=-1))[-1]\npair_values=pair_features(fundamental,sum_coefficient,difference_coefficient)\nassert np.isfinite(pair_values).all()\nnp.testing.assert_allclose(pair_values[:,:,:,:5],pair_values.transpose(0,2,1,3)[:,:,:,:5],atol=1.e-12,rtol=1.e-10)\nnp.testing.assert_allclose(pair_values[:,:,:,5],-pair_values.transpose(0,2,1,3)[:,:,:,5],atol=1.e-12,rtol=1.e-10)\norigin_shift=time.mean()\nshifted_values=pair_features(fundamental*np.exp(2.j*np.pi*origin_shift*frequency)[None],\n    sum_coefficient*np.exp(2.j*np.pi*origin_shift*sum_frequency)[None],\n    difference_coefficient*np.exp(2.j*np.pi*origin_shift*difference_frequency)[None])\norigin_error=float(np.max(np.abs(pair_values-shifted_values)))\nnp.testing.assert_allclose(pair_values,shifted_values,atol=1.e-12,rtol=1.e-10)\ndel shifted_values,sum_coefficient,difference_coefficient\npair_mean=np.einsum("n,npqf->f",row_weight,pair_values[train])/(period_n**2)\npair_sd=np.sqrt(np.einsum("n,npqf->f",row_weight,(pair_values[train]-pair_mean)**2)/(period_n**2))\nassert pair_sd.min()>0.\nstandardized_pair=(pair_values-pair_mean)/pair_sd\ntensor_local=torch.as_tensor(np.ascontiguousarray(standardized[train]))\ntensor_pair=torch.as_tensor(np.ascontiguousarray(standardized_pair[train]))\njoint_teacher=source_mass[:,0,:,None]*source_mass[:,1,None,:]\ntensor_teacher=torch.as_tensor(joint_teacher)\ntensor_weight=torch.as_tensor(row_weight)\ntensor_prior=torch.as_tensor(np.log(source_prior[0,:,None]*source_prior[1,None,:]))\nparameter_count=2*features.shape[-1]+pair_values.shape[-1]\nparameter_mask=torch.as_tensor(np.arange(parameter_count)[None,:]<np.array([8,10,14])[:,None])\nforward=lambda vector,local,pair:(\n    weights:=vector.reshape(3,parameter_count)*parameter_mask,\n    target_score:=torch.einsum("npf,mf->mnp",local,weights[:,:4]),\n    background_score:=torch.einsum("nqf,mf->mnq",local,weights[:,4:8]),\n    pair_score:=torch.einsum("npqf,mf->mnpq",pair,weights[:,8:]),\n    target_score[:,:,:,None]+background_score[:,:,None,:]+pair_score+tensor_prior)[-1]\ndata_losses=lambda vector:-(tensor_weight[None,:,None,None]*tensor_teacher[None]\n    *torch.log_softmax(forward(vector,tensor_local,tensor_pair).flatten(-2),dim=-1).reshape(\n        3,len(train_rows),period_n,period_n)).sum(dim=(1,2,3))/2.\nobjective=lambda vector:data_losses(vector).mean()+fit_settings["weight_decay"]*vector.square().mean()\nautograd_objective=torch.func.grad_and_value(objective)\nto_scipy=lambda gradient,value:(value.detach().item(),gradient.detach().numpy())\nscipy_objective=lambda vector:to_scipy(*autograd_objective(torch.from_numpy(vector)))\ninitial=np.zeros(3*parameter_count)\ninitial_loss,initial_gradient=scipy_objective(initial)\nassert np.isclose(initial_loss,-np.sum(source_prior*np.log(source_prior))/2.,rtol=1.e-10)\nassert np.isfinite(initial_gradient).all()\nloss_history=[[0,initial_loss]]\nprint("CROSS_PHASE_SETUP","fold",fold,"training_records",len(train_rows),"held_records",len(held_rows),\n    "active_parameters",parameter_mask.sum(dim=1).tolist(),"origin_error",origin_error,flush=True)\nresult=minimize(scipy_objective,initial,jac=True,method="L-BFGS-B",\n    callback=lambda intermediate_result:(loss_history.append([len(loss_history),float(intermediate_result.fun)]),\n        len(loss_history)%25==0 and print("CROSS_PHASE_PROGRESS",fold,len(loss_history)-1,float(intermediate_result.fun),flush=True)),\n    options={"maxiter":fit_settings["maxiter"],"ftol":fit_settings["ftol"],"gtol":fit_settings["gtol"],"maxls":fit_settings["maxls"]})\nparameters=torch.as_tensor(result.x)\ntraining_losses=data_losses(parameters).detach().numpy()\nassert np.isfinite(result.x).all() and np.isfinite(result.fun)\ndump({"parameters":result.x.reshape(3,parameter_count),"parameter_mask":parameter_mask.numpy(),\n    "feature_mean":feature_mean,"feature_sd":feature_sd,"phase_operator":phase_operator,\n    "pair_mean":pair_mean,"pair_sd":pair_sd,"frequency":frequency,"sum_frequency":sum_frequency,\n    "difference_frequency":difference_frequency,"source_prior":source_prior,"source_period_mass":source_mass,\n    "training_trace_id":trace_id[train],"training_groups":training_groups,"training_weight":row_weight,\n    "optimization":result,"loss_history":np.asarray(loss_history),"training_crossentropy":training_losses,\n    "configuration":cross_settings,"fit_configuration":fit_settings,"heldout_optical_read":False},stem.with_suffix(".joblib"))\nlogit=forward(parameters,torch.as_tensor(np.ascontiguousarray(standardized[heldout])),\n    torch.as_tensor(np.ascontiguousarray(standardized_pair[heldout]))).detach().numpy()\njoint_mass=softmax(logit.reshape(3,len(held_rows),-1),axis=-1).transpose(1,0,2).reshape(len(held_rows),3,period_n,period_n)\nrole_mass=np.concatenate([np.stack([joint_mass.sum(axis=-1),joint_mass.sum(axis=-2)],axis=2),\n    np.broadcast_to(source_prior,(len(held_rows),1,2,period_n))],axis=1)\nnp.testing.assert_allclose(joint_mass[:,0],role_mass[:,0,0,:,None]*role_mass[:,0,1,None,:],rtol=1.e-10,atol=1.e-12)\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nrole_estimate=periods[role_score.argmax(axis=-1)]\nrole_confidence=role_score.max(axis=-1)\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\nmethods=np.array(cross_settings["methods"])\nassert np.isfinite(role_mass).all() and np.allclose(role_mass.sum(axis=-1),1.)\npredictions=pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],len(methods)),\n    "method":np.tile(methods,len(held_rows)),"estimate_h":estimate.ravel(),\n    "confidence":confidence.ravel(),"heldout_fold":fold,\n    "heldout_run":np.repeat(run[heldout],len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    periods=periods,methods=methods,mass=mass,estimate=estimate,confidence=confidence,\n    role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,joint_mass=joint_mass,\n    source_prior=source_prior,training_trace_id=trace_id[train],training_groups=training_groups,\n    source_period_mass=source_mass,confidence_definition="supervised_joint_period_mass_cross_frequency_phase_not_coverage_calibrated")\nprint("CROSS_PHASE_FIT","fold",fold,"iterations",result.nit,\n    "training_crossentropy",training_losses.tolist(),"extra_weights",result.x.reshape(3,parameter_count)[:,8:].tolist(),\n    "status",str(result.message),flush=True)\nnative=native_evaluation\nexec(compile(structural_source_readout_stage[structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
exec(compile({True:structural_cross_phase_stage,False:""}[args.stage=="structural-cross-phase"],__file__,"exec"))

structural_period_score_stage = '\nexec(compile(structural_pair_competition_stage.split("parent_stem=",1)[0]\n    .replace(\'application["structural_pair_competition"]\',\'application["structural_period_score"]\'),__file__,"exec"))\nscore_settings=competition_settings\nteacher_code=structural_crossed_period_setup_stage.split("teacher_code=",1)[1].split(\n    \'exec(compile({"observed"\',1)[0]\nexec(compile("teacher_code="+teacher_code,__file__,"exec"))\nexec(compile(structural_crossed_period_feature_stage.split("observed_features=",1)[0],__file__,"exec"))\nfeatures=phase_features(mixed,phase_operator).reshape(len(mixed),period_n,4)\nfeature_mean=np.einsum("n,npf->f",row_weight,features[train])/period_n\nfeature_sd=np.sqrt(np.einsum("n,npf->f",row_weight,(features[train]-feature_mean)**2)/period_n)\nstandardized=(features-feature_mean)/feature_sd\nfrequency=1./periods\nsum_frequency=frequency[:,None]+frequency[None]\ndifference_frequency=frequency[:,None]-frequency[None]\nsum_power=np.abs(mixed@np.exp(-2.j*np.pi*time[:,None]*sum_frequency.ravel()[None])/length)**2\ndifference_power=np.abs(mixed@np.exp(-2.j*np.pi*time[:,None]*difference_frequency.ravel()[None])/length)**2\npair_values=np.stack([sum_power,difference_power],axis=-1).reshape(len(mixed),period_n,period_n,2)\npair_mean=np.einsum("n,npqf->f",row_weight,pair_values[train])/(period_n**2)\npair_sd=np.sqrt(np.einsum("n,npqf->f",row_weight,(pair_values[train]-pair_mean)**2)/(period_n**2))\nstandardized_pair=(pair_values-pair_mean)/pair_sd\ntensor_local=torch.as_tensor(np.ascontiguousarray(standardized[train]))\ntensor_pair=torch.as_tensor(np.ascontiguousarray(standardized_pair[train]))\njoint_teacher=source_mass[:,0,:,None]*source_mass[:,1,None,:]\ntensor_teacher=torch.as_tensor(joint_teacher)\ntensor_weight=torch.as_tensor(row_weight)\ntensor_prior=torch.as_tensor(np.log(source_prior[0,:,None]*source_prior[1,None,:]))\n# Retain the previous 14-slot regularization denominator for the two retained heads.\nparameter_count=score_settings["regularization_slots"]\nparameter_mask=torch.as_tensor(np.arange(parameter_count)[None,:]<np.array([8,10])[:,None])\nforward=lambda vector,local,pair:(\n    weights:=vector.reshape(2,parameter_count)*parameter_mask,\n    target_score:=torch.einsum("npf,mf->mnp",local,weights[:,:4]),\n    background_score:=torch.einsum("nqf,mf->mnq",local,weights[:,4:8]),\n    pair_score:=torch.einsum("npqf,mf->mnpq",pair,weights[:,8:10]),\n    target_score[:,:,:,None]+background_score[:,:,None,:]+pair_score+tensor_prior)[-1]\ndata_losses=lambda vector:-(tensor_weight[None,:,None,None]*tensor_teacher[None]\n    *torch.log_softmax(forward(vector,tensor_local,tensor_pair).flatten(-2),dim=-1).reshape(\n        2,len(train_rows),period_n,period_n)).sum(dim=(1,2,3))/2.\nobjective=lambda vector:data_losses(vector).mean()+fit_settings["weight_decay"]*vector.square().mean()\nautograd_objective=torch.func.grad_and_value(objective)\nto_scipy=lambda gradient,value:(value.detach().item(),gradient.detach().numpy())\nscipy_objective=lambda vector:to_scipy(*autograd_objective(torch.from_numpy(vector)))\ninitial=np.zeros(2*parameter_count)\ninitial_loss,initial_gradient=scipy_objective(initial)\nassert np.isclose(initial_loss,-np.sum(source_prior*np.log(source_prior))/2.,rtol=1.e-10)\nassert np.isfinite(initial_gradient).all()\nloss_history=[[0,initial_loss]]\nprint("PERIOD_SCORE_SETUP","fold",fold,"training_records",len(train_rows),"held_records",len(held_rows),\n    "active_parameters",parameter_mask.sum(dim=1).tolist(),flush=True)\nscore_fit_code="""\nresult=minimize(scipy_objective,initial,jac=True,method="L-BFGS-B",\n    callback=lambda intermediate_result:(loss_history.append([len(loss_history),float(intermediate_result.fun)]),\n        len(loss_history)%25==0 and print("PERIOD_SCORE_PROGRESS",fold,len(loss_history)-1,float(intermediate_result.fun),flush=True)),\n    options={"maxiter":fit_settings["maxiter"],"ftol":fit_settings["ftol"],"gtol":fit_settings["gtol"],"maxls":fit_settings["maxls"]})\nparameters=torch.as_tensor(result.x)\nreused_fit=False\n"""\nscore_reuse_code="""\nprevious_stem=application["structural_cross_phase"]["stem"]\nprevious_stem=previous_stem.with_name(previous_stem.name+"_common_fold"+str(fold))\nprevious=load(previous_stem.with_suffix(".joblib"))\nassert np.array_equal(previous["training_trace_id"],trace_id[train])\nnp.testing.assert_allclose(previous["source_period_mass"],source_mass,atol=1.e-12,rtol=1.e-10)\nnp.testing.assert_allclose(previous["source_prior"],source_prior,atol=1.e-12,rtol=1.e-10)\nnp.testing.assert_allclose(previous["feature_mean"],feature_mean,atol=1.e-12,rtol=1.e-10)\nnp.testing.assert_allclose(previous["feature_sd"],feature_sd,atol=1.e-12,rtol=1.e-10)\nnp.testing.assert_allclose(previous["pair_mean"][:2],pair_mean,atol=1.e-12,rtol=1.e-10)\nnp.testing.assert_allclose(previous["pair_sd"][:2],pair_sd,atol=1.e-12,rtol=1.e-10)\nparameters=torch.as_tensor(previous["parameters"][:2].ravel())\nresult=previous["optimization"]\nloss_history=previous["loss_history"]\nreused_fit=True\n"""\nexec(compile({True:score_reuse_code,False:score_fit_code}[fold in score_settings["reuse_folds"]],__file__,"exec"))\ntraining_losses=data_losses(parameters).detach().numpy()\nassert np.isfinite(parameters.numpy()).all()\ndump({"parameters":parameters.numpy().reshape(2,parameter_count),"parameter_mask":parameter_mask.numpy(),\n    "feature_mean":feature_mean,"feature_sd":feature_sd,"phase_operator":phase_operator,\n    "pair_mean":pair_mean,"pair_sd":pair_sd,"frequency":frequency,"sum_frequency":sum_frequency,\n    "difference_frequency":difference_frequency,"source_prior":source_prior,"source_period_mass":source_mass,\n    "training_trace_id":trace_id[train],"training_groups":training_groups,"training_weight":row_weight,\n    "optimization":result,"loss_history":np.asarray(loss_history),"training_crossentropy":training_losses,\n    "reused_previous_fit":reused_fit,"configuration":score_settings,"fit_configuration":fit_settings,\n    "heldout_optical_read":False},stem.with_suffix(".joblib"))\nlogit=forward(parameters,torch.as_tensor(np.ascontiguousarray(standardized[heldout])),\n    torch.as_tensor(np.ascontiguousarray(standardized_pair[heldout]))).detach().numpy()\njoint_mass=softmax(logit.reshape(2,len(held_rows),-1),axis=-1).transpose(1,0,2).reshape(len(held_rows),2,period_n,period_n)\nrole_mass=np.concatenate([np.stack([joint_mass.sum(axis=-1),joint_mass.sum(axis=-2)],axis=2),\n    np.broadcast_to(source_prior,(len(held_rows),1,2,period_n))],axis=1)\nnp.testing.assert_allclose(joint_mass[:,0],role_mass[:,0,0,:,None]*role_mass[:,0,1,None,:],rtol=1.e-10,atol=1.e-12)\nscore_reuse_check="""\nprevious_predictions=np.load(previous_stem.with_suffix(".npz"),allow_pickle=False)\nnp.testing.assert_allclose(joint_mass,previous_predictions["joint_mass"][:,:2],atol=1.e-12,rtol=1.e-10)\nnp.testing.assert_allclose(role_mass,previous_predictions["role_mass"][:,[0,1,3]],atol=1.e-12,rtol=1.e-10)\nprint("PERIOD_SCORE_REUSE_CHECK","fold",fold,"maximum_mass_error",\n    float(np.max(np.abs(role_mass-previous_predictions["role_mass"][:,[0,1,3]]))),flush=True)\n"""\nexec(compile({True:score_reuse_check,False:""}[reused_fit],__file__,"exec"))\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nrole_estimate=periods[role_score.argmax(axis=-1)]\nrole_confidence=role_score.max(axis=-1)\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\nmethods=np.array(score_settings["methods"])\nassert np.isfinite(role_mass).all() and np.allclose(role_mass.sum(axis=-1),1.)\npredictions=pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],len(methods)),\n    "method":np.tile(methods,len(held_rows)),"estimate_h":estimate.ravel(),\n    "confidence":confidence.ravel(),"heldout_fold":fold,\n    "heldout_run":np.repeat(run[heldout],len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    periods=periods,methods=methods,mass=mass,estimate=estimate,confidence=confidence,\n    role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,joint_mass=joint_mass,\n    source_prior=source_prior,training_trace_id=trace_id[train],training_groups=training_groups,\n    source_period_mass=source_mass,confidence_definition="supervised_period_density_not_coverage_calibrated")\nprint("PERIOD_SCORE_FIT","fold",fold,"iterations",result.nit,"reused",reused_fit,\n    "training_crossentropy",training_losses.tolist(),"status",str(result.message),flush=True)\nnative=native_evaluation\nexec(compile(structural_source_readout_stage[structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
exec(compile({True:structural_period_score_stage,False:""}[args.stage=="structural-period-score"],__file__,"exec"))

structural_period_information_stage = '\nsetup_code=structural_period_score_stage.split(\'exec(compile(structural_crossed_period_feature_stage\',1)[0]\nsetup_code=setup_code.replace(\'application["structural_period_score"]\',\'application["structural_period_information"]\')\nexec(compile(setup_code,__file__,"exec"))\ninformation_settings=score_settings\ncommon_mass=source_mass.copy()\ncommon_prior=source_prior.copy()\ncommon_log_evidence=teacher_scope["log_evidence"].reshape(len(train_rows),2,period_n).copy()\nfull_scope=dict(globals())\nexec(compile(structural_source_data_stage.replace(\n    \'native = fold<application["lemna_expected_runs"]\',\'native = True\'),__file__,"exec"),full_scope)\nfull_scope["train_rows"]=np.flatnonzero(full_scope["train"])\nfull_scope["held_rows"]=np.flatnonzero(full_scope["heldout"])\nexec(compile(structural_period_flow_fit_stage[\n    structural_period_flow_fit_stage.index("background_raw ="):\n    structural_period_flow_fit_stage.index("layout_count,layout_index")],__file__,"exec"),full_scope)\nassert np.array_equal(trace_id[train],full_scope["trace_id"][full_scope["train"]])\nnp.testing.assert_allclose(row_weight,full_scope["row_weight"],atol=1.e-14,rtol=1.e-12)\nfull_teacher_code=structural_source_readout_stage.split("prior_labels =",1)[0]\nfull_teacher_code=full_teacher_code.replace("waves = np.stack([prediction,mixed[heldout]],axis=1)","waves = source_unit")\nfull_teacher_code=full_teacher_code.replace("held_mask = mask[heldout]","held_mask = mask[train]")\nfull_teacher_code=full_teacher_code.replace("held_count = count[heldout]","held_count = count[train]")\nfull_teacher_scope=dict(full_scope)\nexec(compile(full_teacher_code,__file__,"exec"),full_teacher_scope)\nfull_log_evidence=full_teacher_scope["log_evidence"].reshape(len(train_rows),2,period_n)\nfull_mass=softmax(full_log_evidence+np.log(grid_weight)[None,None],axis=-1)\nfull_prior=np.einsum("n,nrp->rp",row_weight,full_mass)\n# The first four features are the unchanged phase-invariant local representation.\n# The last four retain phase relative to the beginning of the observed time course.\ninformation_features=lambda values,times,masks,bases:(\n    layout:=np.unique(masks.sum(axis=1),return_index=True,return_inverse=True),\n    local_base:=bases[layout[1]],\n    angle:=2.*np.pi*(times-times[0])[None,:,None]/periods[:,None,None]*np.array([1.,2.])[None,None],\n    waves:=np.sqrt(2.)*np.stack([np.cos(angle),np.sin(angle)],axis=-1).reshape(period_n,len(times),4)[None]\n        *masks[layout[1],None,:,None],\n    waves:=waves-np.einsum("lti,lpij->lptj",local_base,np.einsum("lti,lptj->lpij",local_base,waves)),\n    gram:=np.einsum("lpti,lptj->lpij",waves,waves),\n    operator:=waves@np.linalg.inv(gram),\n    coefficient:=np.einsum("nt,lpti->lnpi",values,operator)[layout[2],np.arange(len(values))],\n    first:=coefficient[:,:,0]-1j*coefficient[:,:,1],\n    second:=coefficient[:,:,2]-1j*coefficient[:,:,3],\n    first_power:=np.abs(first)**2,\n    second_power:=np.abs(second)**2,\n    coupling:=second*np.conj(first)**2/(first_power+second_power)**1.5,\n    np.concatenate([np.stack([first_power,second_power,coupling.real,coupling.imag],axis=-1),coefficient],axis=-1))[-1]\ncommon_features=information_features(mixed,time,mask,base)\ncommon_shifted=information_features(mixed,time+time.mean(),mask,base)\nnp.testing.assert_allclose(common_features,common_shifted,atol=1.e-12,rtol=1.e-10)\nfull_native_features=information_features(full_scope["mixed"],full_scope["time"],full_scope["mask"],full_scope["base"])\nfull_order=pd.Index(trace_id).get_indexer(full_scope["trace_id"])\nassert (full_order>=0).all() and np.unique(full_order).size==len(full_order)\nfull_features=common_features.copy()\nfull_features[full_order]=full_native_features\nfull_input_count=count.copy()\nfull_input_count[full_order]=full_scope["count"]\ncommon_mean=np.einsum("n,npf->f",row_weight,common_features[train])/period_n\ncommon_sd=np.sqrt(np.einsum("n,npf->f",row_weight,(common_features[train]-common_mean)**2)/period_n)\nfull_mean=np.einsum("n,npf->f",row_weight,full_features[train])/period_n\nfull_sd=np.sqrt(np.einsum("n,npf->f",row_weight,(full_features[train]-full_mean)**2)/period_n)\ncommon_standardized=(common_features-common_mean)/common_sd\nfull_standardized=(full_features-full_mean)/full_sd\nassert np.isfinite(common_standardized).all() and np.isfinite(full_standardized).all()\ncontrol_stem=application[{True:"structural_cross_phase",False:"structural_period_score"}[\n    fold==application["lemna_expected_runs"]]]["stem"]\ncontrol_stem=control_stem.with_name(control_stem.name+"_common_fold"+str(fold))\ncontrol_bundle=load(control_stem.with_suffix(".joblib"))\nassert np.array_equal(control_bundle["training_trace_id"],trace_id[train])\nnp.testing.assert_allclose(common_prior,control_bundle["source_prior"],atol=1.e-12,rtol=1.e-10)\nnp.testing.assert_allclose(common_mass,control_bundle["source_period_mass"],atol=1.e-12,rtol=1.e-10)\nnp.testing.assert_allclose(common_mean[:4],control_bundle["feature_mean"],atol=1.e-12,rtol=1.e-10)\nnp.testing.assert_allclose(common_sd[:4],control_bundle["feature_sd"],atol=1.e-12,rtol=1.e-10)\nfixed_control=torch.as_tensor(np.pad(control_bundle["parameters"][0,:8].reshape(2,4),((0,0),(0,4))))\nmodel_features=np.stack([common_standardized,common_standardized,common_standardized,\n    full_standardized,full_standardized])\nmodel_teacher=np.stack([common_mass,common_mass,common_mass,common_mass,full_mass])\nmodel_prior=np.stack([common_prior,common_prior,common_prior,common_prior,full_prior])\ntensor_inputs=torch.as_tensor(np.ascontiguousarray(model_features[:,train]))\ntensor_teacher=torch.as_tensor(model_teacher)\ntensor_prior=torch.as_tensor(np.log(model_prior))\ntensor_weight=torch.as_tensor(row_weight)\ntensor_evidence=torch.as_tensor(common_log_evidence-common_log_evidence.max(axis=-1,keepdims=True))\nparameter_mask=torch.as_tensor(np.arange(8)[None,None,:]<np.array([4,8,4,4])[:,None,None])\nforward=lambda vector,inputs:(\n    weights:=torch.cat([fixed_control[None],vector.reshape(4,2,8)*parameter_mask],dim=0),\n    torch.einsum("mnpf,mrf->mnrp",inputs,weights)+tensor_prior[:,None])[-1]\ndata_losses=lambda vector:(\n    log_probability:=torch.log_softmax(forward(vector,tensor_inputs),dim=-1),\n    crossentropy:=-(tensor_weight[None,:,None,None]*tensor_teacher*log_probability).sum(dim=(1,2,3))/2.,\n    weak_evidence:=-(tensor_weight[:,None]*torch.logsumexp(log_probability[1]+tensor_evidence,dim=-1)).sum()/2.,\n    torch.stack([crossentropy[0],weak_evidence,crossentropy[2],crossentropy[3],crossentropy[4]]))[-1]\nobjective=lambda vector:data_losses(vector)[1:].mean()+fit_settings["weight_decay"]*vector.square().sum()/(\n    4*information_settings["regularization_slots"])\nautograd_objective=torch.func.grad_and_value(objective)\nto_scipy=lambda gradient,value:(value.detach().item(),gradient.detach().numpy())\nscipy_objective=lambda vector:to_scipy(*autograd_objective(torch.from_numpy(vector)))\ninitial=np.zeros(4*2*8)\ninitial_loss,initial_gradient=scipy_objective(initial)\nassert np.isfinite(initial_loss) and np.isfinite(initial_gradient).all()\nflat_evidence_loss=lambda vector:-(tensor_weight[:,None]*torch.logsumexp(\n    torch.log_softmax(forward(vector,tensor_inputs)[1],dim=-1),dim=-1)).sum()/2.\nflat_gradient=torch.func.grad(flat_evidence_loss)(torch.from_numpy(initial)).numpy()\nassert np.max(np.abs(flat_gradient))<1.e-12\nloss_history=[[0,initial_loss]]\nprint("PERIOD_INFORMATION_SETUP","fold",fold,"training_records",len(train_rows),"held_records",len(held_rows),\n    "full_training_counts",np.unique(full_input_count[train],return_counts=True),\n    "flat_evidence_gradient",float(np.max(np.abs(flat_gradient))),flush=True)\nresult=minimize(scipy_objective,initial,jac=True,method="L-BFGS-B",\n    callback=lambda intermediate_result:(loss_history.append([len(loss_history),float(intermediate_result.fun)]),\n        len(loss_history)%25==0 and print("PERIOD_INFORMATION_PROGRESS",fold,len(loss_history)-1,float(intermediate_result.fun),flush=True)),\n    options={"maxiter":fit_settings["maxiter"],"ftol":fit_settings["ftol"],"gtol":fit_settings["gtol"],"maxls":fit_settings["maxls"]})\nparameters=torch.as_tensor(result.x)\ntraining_losses=data_losses(parameters).detach().numpy()\nassert np.isfinite(result.x).all() and np.isfinite(result.fun)\ndump({"parameters":result.x.reshape(4,2,8),"parameter_mask":parameter_mask.numpy(),\n    "fixed_control_parameters":fixed_control.numpy(),"control_stem":str(control_stem),\n    "common_feature_mean":common_mean,"common_feature_sd":common_sd,\n    "full_feature_mean":full_mean,"full_feature_sd":full_sd,\n    "model_source_prior":model_prior,"source_period_mass":np.stack([common_mass,full_mass]),\n    "common_optical_log_evidence":common_log_evidence,"full_optical_log_evidence":full_log_evidence,\n    "training_trace_id":trace_id[train],"training_groups":training_groups,"training_weight":row_weight,\n    "training_input_counts":full_input_count[train],"full_native_time":full_scope["time"],\n    "optimization":result,"loss_history":np.asarray(loss_history),"training_objectives":training_losses,\n    "configuration":information_settings,"fit_configuration":fit_settings,"heldout_optical_read":False},stem.with_suffix(".joblib"))\nlogit=forward(parameters,torch.as_tensor(np.ascontiguousarray(model_features[:,heldout]))).detach().numpy()\ntrained_mass=softmax(logit,axis=-1).transpose(1,0,2,3)\ncontrol_prediction=np.load(control_stem.with_suffix(".npz"),allow_pickle=False)\nnp.testing.assert_allclose(trained_mass[:,0],control_prediction["role_mass"][:,0],atol=1.e-12,rtol=1.e-10)\nrole_mass=np.concatenate([trained_mass,np.broadcast_to(np.stack([common_prior,full_prior]),(\n    len(held_rows),2,2,period_n))],axis=1)\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nrole_estimate=periods[role_score.argmax(axis=-1)]\nrole_confidence=role_score.max(axis=-1)\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\nmethods=np.array(information_settings["methods"])\nassert np.isfinite(role_mass).all() and np.allclose(role_mass.sum(axis=-1),1.)\npredictions=pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],len(methods)),\n    "method":np.tile(methods,len(held_rows)),"estimate_h":estimate.ravel(),"confidence":confidence.ravel(),\n    "heldout_fold":fold,"heldout_run":np.repeat(run[heldout],len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    full_native_time=full_scope["time"],full_input_count=full_input_count[heldout],\n    periods=periods,methods=methods,mass=mass,estimate=estimate,confidence=confidence,\n    role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,\n    source_prior=common_prior,full_source_prior=full_prior,model_source_prior=model_prior,\n    training_trace_id=trace_id[train],training_groups=training_groups,\n    source_period_mass=np.stack([common_mass,full_mass]),\n    confidence_definition="supervised_period_density_not_coverage_calibrated")\nprint("PERIOD_INFORMATION_FIT","fold",fold,"iterations",result.nit,\n    "training_objectives",training_losses.tolist(),"status",str(result.message),flush=True)\nnative=native_evaluation\nexec(compile(structural_source_readout_stage[structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
exec(compile({True:structural_period_information_stage,False:""}[args.stage=="structural-period-information"],__file__,"exec"))

structural_source_assignment_stage = '\nfrom scipy.special import expit\nsetup_code=structural_period_score_stage.split(\'exec(compile(structural_crossed_period_feature_stage\',1)[0]\nsetup_code=setup_code.replace(\'application["structural_period_score"]\',\'application["structural_source_assignment"]\')\nexec(compile(setup_code,__file__,"exec"))\nassignment_settings=score_settings\nexec(compile(structural_crossed_period_feature_stage.split("observed_features=",1)[0],__file__,"exec"))\nfeatures=phase_features(mixed,phase_operator).reshape(len(mixed),period_n,4)\nfeature_mean=np.einsum("n,npf->f",row_weight,features[train])/period_n\nfeature_sd=np.sqrt(np.einsum("n,npf->f",row_weight,(features[train]-feature_mean)**2)/period_n)\nstandardized=(features-feature_mean)/feature_sd\nprior_odds=np.log(source_prior[0])-np.log(source_prior[1])\nprior_logit=prior_odds[:,None]-prior_odds[None]\ntensor_inputs=torch.as_tensor(np.ascontiguousarray(standardized[train]))\ntensor_prior=torch.as_tensor(prior_logit)\ntensor_prior_use=torch.as_tensor(np.array([1.,0.]))\ntensor_teacher=torch.as_tensor(source_mass[:,0,:,None]*source_mass[:,1,None,:])\ntensor_weight=torch.as_tensor(row_weight)\nforward=lambda vector,inputs:(\n    candidate:=torch.einsum("npf,mf->mnp",inputs,vector.reshape(2,4)),\n    candidate[:,:,:,None]-candidate[:,:,None,:]+tensor_prior_use[:,None,None,None]*tensor_prior)[-1]\ndata_losses=lambda vector:(tensor_weight[None,:,None,None]*tensor_teacher[None]\n    *torch.nn.functional.softplus(-forward(vector,tensor_inputs))).sum(dim=(1,2,3))\nobjective=lambda vector:data_losses(vector).mean()+fit_settings["weight_decay"]*vector.square().sum()/(\n    2*assignment_settings["regularization_slots"])\nautograd_objective=torch.func.grad_and_value(objective)\nto_scipy=lambda gradient,value:(value.detach().item(),gradient.detach().numpy())\nscipy_objective=lambda vector:to_scipy(*autograd_objective(torch.from_numpy(vector)))\ninitial=np.zeros(8)\ninitial_loss,initial_gradient=scipy_objective(initial)\nassert np.isfinite(initial_loss) and np.isfinite(initial_gradient).all()\nnp.testing.assert_allclose(data_losses(torch.from_numpy(initial)).detach().numpy()[1],np.log(2.),atol=1.e-12)\nloss_history=[[0,initial_loss]]\nprint("SOURCE_ASSIGNMENT_SETUP","fold",fold,"training_records",len(train_rows),"held_records",len(held_rows),\n    "initial_losses",data_losses(torch.from_numpy(initial)).detach().numpy().tolist(),flush=True)\nresult=minimize(scipy_objective,initial,jac=True,method="L-BFGS-B",\n    callback=lambda intermediate_result:(loss_history.append([len(loss_history),float(intermediate_result.fun)]),\n        len(loss_history)%25==0 and print("SOURCE_ASSIGNMENT_PROGRESS",fold,len(loss_history)-1,float(intermediate_result.fun),flush=True)),\n    options={"maxiter":fit_settings["maxiter"],"ftol":fit_settings["ftol"],"gtol":fit_settings["gtol"],"maxls":fit_settings["maxls"]})\nparameters=torch.as_tensor(result.x)\nassert np.isfinite(result.x).all() and np.isfinite(result.fun)\ntraining_losses=data_losses(parameters).detach().numpy()\ndump({"parameters":result.x.reshape(2,4),"feature_mean":feature_mean,"feature_sd":feature_sd,\n    "phase_operator":phase_operator,"prior_odds":prior_odds,"source_prior":source_prior,\n    "source_period_mass":source_mass,"training_trace_id":trace_id[train],"training_groups":training_groups,\n    "training_weight":row_weight,"optimization":result,"loss_history":np.asarray(loss_history),\n    "training_assignment_loss":training_losses,"configuration":assignment_settings,\n    "fit_configuration":fit_settings,"heldout_optical_read":False},stem.with_suffix(".joblib"))\nparent_stems=tuple(map(lambda key:application[key]["stem"],assignment_settings["parent_keys"]))\nparent_paths=tuple(map(lambda value:value.with_name(value.name+"_common_fold"+str(fold)).with_suffix(".npz"),parent_stems))\nparents=tuple(map(lambda path:np.load(path,allow_pickle=False),parent_paths))\nassert all(map(lambda parent:np.array_equal(parent["trace_id"],trace_id[heldout]),parents))\nassert all(map(lambda parent:np.array_equal(parent["periods"],periods),parents))\nassert all(map(lambda parent:np.array_equal(parent["training_trace_id"],trace_id[train]),parents))\nparent_mass=np.stack(tuple(map(lambda item:item[0]["role_mass"][:,item[1]],\n    zip(parents,assignment_settings["parent_indices"]))),axis=1)\nparent_joint=parent_mass[:,:,0,:,None]*parent_mass[:,:,1,None,:]\nunordered_mass=(parent_joint+parent_joint.swapaxes(-1,-2))/2.\nlearned_logit=forward(parameters,torch.as_tensor(np.ascontiguousarray(standardized[heldout]))).detach().numpy()\nnp.testing.assert_allclose(learned_logit,-learned_logit.swapaxes(-1,-2),atol=1.e-12,rtol=1.e-10)\nlearned_orientation=expit(learned_logit).transpose(1,0,2,3)\norientation=np.concatenate([np.broadcast_to(expit(prior_logit),(len(held_rows),1,period_n,period_n)),\n    learned_orientation],axis=1)\nnp.testing.assert_allclose(orientation+orientation.swapaxes(-1,-2),1.,atol=1.e-14,rtol=1.e-12)\nreassigned_joint=2.*unordered_mass[:,:,None]*orientation[:,None]\nnp.testing.assert_allclose(reassigned_joint.sum(axis=(-1,-2)),1.,atol=1.e-12,rtol=1.e-10)\nnp.testing.assert_allclose((reassigned_joint+reassigned_joint.swapaxes(-1,-2))/2.,\n    np.broadcast_to(unordered_mass[:,:,None],reassigned_joint.shape),atol=1.e-12,rtol=1.e-10)\njoint=np.concatenate([parent_joint[:,:,None],reassigned_joint],axis=2)\nrole_mass=np.stack([joint.sum(axis=-1),joint.sum(axis=-2)],axis=-2).reshape(len(held_rows),-1,2,period_n)\nnp.testing.assert_allclose(role_mass[:,::4],parent_mass,atol=1.e-12,rtol=1.e-10)\nmethods=np.char.add(np.char.add(np.array(assignment_settings["parent_names"])[:,None],"_"),\n    np.array(assignment_settings["assignment_names"])[None])\nmethods=np.char.add(methods,"_window").ravel()\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nrole_estimate=periods[role_score.argmax(axis=-1)]\nrole_confidence=role_score.max(axis=-1)\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\nassert np.isfinite(role_mass).all() and np.allclose(role_mass.sum(axis=-1),1.)\npredictions=pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],len(methods)),\n    "method":np.tile(methods,len(held_rows)),"estimate_h":estimate.ravel(),"confidence":confidence.ravel(),\n    "heldout_fold":fold,"heldout_run":np.repeat(run[heldout],len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    periods=periods,methods=methods,mass=mass,estimate=estimate,confidence=confidence,\n    role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,\n    source_prior=source_prior,training_trace_id=trace_id[train],training_groups=training_groups,\n    source_period_mass=source_mass,unordered_mass=unordered_mass,orientation_probability=orientation,\n    original_parent_role_mass=parent_mass,parent_names=np.array(assignment_settings["parent_names"]),\n    parent_paths=np.array(tuple(map(str,parent_paths))),\n    pair_law_definition="factorized_saved_marginals_then_symmetrized_not_original_parent_joint_dependencies",\n    confidence_definition="conditional_source_assignment_period_mass_not_coverage_calibrated")\nprint("SOURCE_ASSIGNMENT_FIT","fold",fold,"iterations",result.nit,"weights",result.x.reshape(2,4).tolist(),\n    "training_assignment_loss",training_losses.tolist(),"status",str(result.message),flush=True)\nnative=native_evaluation\nexec(compile(structural_source_readout_stage[structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
