structural_shape_identity_stage = '\nfrom scipy.special import softmax,logsumexp\nsetup_code=structural_period_score_stage.split(\'exec(compile(structural_crossed_period_feature_stage\',1)[0]\nexec(compile(setup_code,__file__,"exec"))\nshape_settings=application["structural_shape_identity"]\nassert fold==application["lemna_expected_runs"]\nnative_n=len(train_rows)\ncommon_base=base[0]\nexternal_optical=pd.read_parquet(application["conditional_source_external"]["raw"],\n    columns=["trace_id","time_h","published_target_y","published_background_y"],\n    filters=[("time_h",">=",application["conditional_source_external"]["window_h"][0]),\n        ("time_h","<=",application["conditional_source_external"]["window_h"][1])])\nexternal_target=external_optical.pivot(index="trace_id",columns="time_h",values="published_target_y").reindex(trace_id[heldout])\nexternal_background=external_optical.pivot(index="trace_id",columns="time_h",values="published_background_y").reindex(\n    index=trace_id[heldout],columns=external_target.columns)\nexternal_pair=np.stack([external_target.to_numpy(),external_background.to_numpy()],axis=1)\nexternal_pair-=(external_pair@common_base)@common_base.T\nexternal_pair/=np.sqrt(np.mean(external_pair**2,axis=-1))[...,None]\npure=np.concatenate([source_unit,external_pair])\nassert np.isfinite(pure).all()\nteacher_code=structural_source_readout_stage.split("prior_labels =",1)[0]\nteacher_code=teacher_code.replace("waves = np.stack([prediction,mixed[heldout]],axis=1)","waves = pure")\nteacher_code=teacher_code.replace("held_mask = mask[heldout]","held_mask = np.ones((len(pure),len(time)),dtype=bool)")\nteacher_code=teacher_code.replace("held_count = count[heldout]","held_count = np.full(len(pure),len(time),dtype=int)")\nteacher_scope=dict(globals())\nexec(compile(teacher_code,__file__,"exec"),teacher_scope)\nteacher=softmax(teacher_scope["log_evidence"].reshape(len(pure),2,period_n)+np.log(grid_weight)[None,None],axis=-1)\nnp.testing.assert_allclose(teacher[:native_n],source_mass,atol=1.e-12,rtol=1.e-10)\norders=np.arange(1,shape_settings["harmonics"]+1)\nangle=2.*np.pi*time[None,:,None]*orders[None,None]/periods[:,None,None]\nharmonic3=(np.sqrt(2.)/orders[None,None,:,None]*np.stack([np.cos(angle),np.sin(angle)],axis=-1)).reshape(period_n,length,-1)\nharmonic3-=np.einsum("ti,pij->ptj",common_base,np.einsum("ti,ptj->pij",common_base,harmonic3))\ngram3=np.einsum("pti,ptj->pij",harmonic3,harmonic3)+application["density"]["coefficient_precision"]*np.eye(2*len(orders))\noperator3=(harmonic3@np.linalg.inv(gram3)).transpose(1,0,2).reshape(length,-1)\ncoefficient=(pure@operator3).reshape(len(pure),2,period_n,len(orders),2)\ncomplex_coefficient=(coefficient[...,0]-1.j*coefficient[...,1])*np.sqrt(2.)/orders\ncanonical=lambda z:z*np.exp(-1.j*np.angle(z[...,:1])*orders)/np.sqrt(np.sum(np.abs(z)**2,axis=-1))[...,None]\naligned=canonical(complex_coefficient)\nshifted=complex_coefficient*np.exp(2.j*np.pi*orders[None,None,None]*float(time[1]-time[0])/periods[None,None,:,None])\nnp.testing.assert_allclose(canonical(shifted),aligned,atol=1.e-12,rtol=1.e-10)\nshape_candidates=np.concatenate([aligned[...,:1].real,aligned[...,1:].real,aligned[...,1:].imag],axis=-1)\nshape=np.sum(teacher[...,None]*shape_candidates,axis=-2)\nfeature_n=shape.shape[-1]\ngroups,group_index=np.unique(run[train],return_inverse=True)\nfolds=np.arange(len(groups)+1)\nbank_weight=(group_index[None]!=folds[:,None])*row_weight[None]\nbank_weight/=bank_weight.sum(axis=1)[:,None]\nnp.testing.assert_allclose(bank_weight.sum(axis=1),1.,atol=1.e-12)\nmeans=np.einsum("kn,nrf->krf",bank_weight,shape[:native_n])\nsecond=np.einsum("kn,nrf,nrg->krfg",bank_weight,shape[:native_n],shape[:native_n],optimize=True)\ncovariance=second-means[...,:,None]*means[...,None,:]\nassert np.linalg.eigvalsh(covariance).min()>0.\npooled_covariance=np.broadcast_to(covariance.mean(axis=1,keepdims=True),covariance.shape)\ncovariances=np.stack([pooled_covariance,covariance],axis=1)\nmodel_fold=np.r_[group_index,np.full(len(held_rows),len(groups),dtype=int)]\ndifference=shape[:,:,None]-means[model_fold][:,None]\ngaussian_logit=-.5*np.einsum("nrcf,nmcfg,nrcg->nmrc",difference,\n    np.linalg.inv(covariances[model_fold]),difference,optimize=True)\ngaussian_logit-=.5*np.linalg.slogdet(covariances[model_fold])[1][:,:,None]\ngaussian_probability=softmax(gaussian_logit,axis=-1)\ntraining_shape=shape[:native_n].reshape(-1,feature_n)\ntraining_distance=np.sum((training_shape[:,None,None]-shape[None,:native_n])**2,axis=-1)\ncross_run=np.repeat(group_index,2)[:,None]!=group_index[None]\nlog_bank=np.full(bank_weight.shape,-np.inf)\nnp.log(bank_weight,out=log_bank,where=bank_weight>0.)\ntensor_distance=torch.as_tensor(training_distance)\ntensor_mask=torch.as_tensor(np.where(cross_run,0.,-np.inf))\ntensor_log_bank=torch.as_tensor(log_bank)\ntensor_query_weight=torch.as_tensor(np.repeat(bank_weight,2,axis=1)/2.)\ntensor_label=torch.as_tensor(np.tile(np.arange(2),native_n),dtype=torch.long)\none_loss=lambda beta,log_weight,query_weight:(\n    logit:=torch.logsumexp(-beta*tensor_distance+log_weight[None,:,None]+tensor_mask[:,:,None],dim=1),\n    log_probability:=torch.log_softmax(logit,dim=-1),\n    -(query_weight*log_probability.gather(1,tensor_label[:,None])[:,0]).sum())[-1]\nlosses=lambda vector:torch.vmap(one_loss,chunk_size=1)(vector,tensor_log_bank,tensor_query_weight)\nobjective=lambda vector:losses(vector).mean()\nautograd_objective=torch.func.grad_and_value(objective)\nto_scipy=lambda gradient,value:(value.detach().item(),gradient.detach().numpy())\nscipy_objective=lambda vector:to_scipy(*autograd_objective(torch.from_numpy(vector)))\ninitial=np.ones(len(folds))\nnp.testing.assert_allclose(losses(torch.zeros(len(folds),dtype=torch.float64)).detach().numpy(),np.log(2.),atol=1.e-12)\nprint("SHAPE_IDENTITY_SETUP","native",native_n,"external",len(held_rows),"features",feature_n,\n    "outer_folds",len(groups),"minimum_covariance_eigenvalue",float(np.linalg.eigvalsh(covariance).min()),\n    "phase_origin_error",float(np.max(np.abs(canonical(shifted)-aligned))),flush=True)\nresult=minimize(scipy_objective,initial,jac=True,method="L-BFGS-B",bounds=np.tile([0.,np.inf],(len(folds),1)),\n    options={"maxiter":fit_settings["maxiter"],"ftol":fit_settings["ftol"],"gtol":fit_settings["gtol"],"maxls":fit_settings["maxls"]})\nassert np.isfinite(result.x).all() and np.isfinite(result.fun)\ndistance=np.sum((shape.reshape(-1,feature_n)[:,None,None]-shape[None,:native_n])**2,axis=-1)\nquery_fold=np.repeat(model_fold,2)\nkernel_logit=logsumexp(-result.x[query_fold,None,None]*distance+log_bank[query_fold,:,None],axis=1)\nkernel_probability=softmax(kernel_logit,axis=-1).reshape(len(shape),1,2,2)\nprobability=np.concatenate([gaussian_probability,kernel_probability],axis=1)\nnp.testing.assert_allclose(probability.sum(axis=-1),1.,atol=1.e-12)\nmethods=np.asarray(shape_settings["methods"])\nroles=np.array(["target","background"])\ncorrect=(probability.argmax(axis=-1)==np.arange(2)[None,None])\ntruth_probability=np.diagonal(probability,axis1=-2,axis2=-1)\nlog_loss=-np.log(truth_probability)\nnative_reference=pd.read_csv(application["paths"]["lemna_reference"],encoding="utf-8").set_index("trace_id").loc[trace_id[train]]\nnative_background_reference=pd.read_csv(application["source_density"]["background_reference"],encoding="utf-8").set_index("trace_id").loc[trace_id[train]]\nexternal_reference=pd.read_csv(application["conditional_source_external"]["reference"],encoding="utf-8").set_index("trace_id").loc[trace_id[heldout]]\nusable=np.concatenate([np.column_stack([native_reference.reference_usable.eq(True),native_background_reference.background_usable.eq(True)]),\n    np.column_stack([external_reference.target_reference_usable.eq(True),external_reference.background_reference_usable.eq(True)])])\ncohort=np.repeat(["native2023_LOEO","external2021"],[native_n,len(held_rows)])\ncells=pd.DataFrame({"trace_id":np.repeat(trace_id,len(methods)*2),"run":np.repeat(run,len(methods)*2),\n    "cohort":np.repeat(cohort,len(methods)*2),"method":np.tile(np.repeat(methods,2),len(shape)),\n    "role":np.tile(roles,len(shape)*len(methods)),"correct":correct.ravel(),"log_loss":log_loss.ravel(),\n    "period_reference_usable":np.broadcast_to(usable[:,None],correct.shape).ravel()})\nstem=shape_settings["stem"]\ncells.to_csv(str(stem)+"_cells.csv",index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id,run=run,cohort=cohort,methods=methods,roles=roles,\n    features=shape,source_period_mass=teacher,periods=periods,role_probability=probability,\n    native_training_trace_id=trace_id[train],groups=groups,fold_bank_weight=bank_weight,\n    covariance=covariances,means=means,kernel_inverse_bandwidth=result.x,model_fold=model_fold,\n    feature_definition="H3_phase_aligned_unit_harmonic_shape_averaged_over_optical_H1_period_mass",\n    usage="pure_optical_role_diagnostic_not_unfiltered_source_recovery")\nsummary=cells.groupby(["cohort","method","role"],sort=False).agg(n=("correct","size"),correct=("correct","sum"),accuracy=("correct","mean"),log_loss=("log_loss","mean"))\ngroup_summary=cells.groupby(["cohort","run","method","role"],sort=False).agg(accuracy=("correct","mean"),log_loss=("log_loss","mean"))\nrun_balanced=group_summary.groupby(["cohort","method","role"],sort=False).mean()\nqualified_summary=cells.loc[cells.period_reference_usable].groupby(["cohort","method","role"],sort=False).agg(\n    n=("correct","size"),correct=("correct","sum"),accuracy=("correct","mean"),log_loss=("log_loss","mean"))\ngroup_summary.to_csv(str(stem)+"_groups.csv",encoding="utf-8",lineterminator="\\n")\nprint("SHAPE_IDENTITY_FIT","iterations",result.nit,"status",str(result.message),\n    "inverse_bandwidth",result.x.tolist(),"inner_losses",losses(torch.as_tensor(result.x)).detach().numpy().tolist(),flush=True)\nprint("SHAPE_IDENTITY_ALL",summary.to_string(),flush=True)\nprint("SHAPE_IDENTITY_RUN_BALANCED",run_balanced.to_string(),flush=True)\nprint("SHAPE_IDENTITY_QUALIFIED",qualified_summary.to_string(),flush=True)\nraise SystemExit(0)\n'
exec(compile({True:structural_shape_identity_stage,False:""}[args.stage=="structural-shape-identity"],__file__,"exec"))

structural_clock_coupling_stage = '\nfrom scipy.special import softmax\nsetup_code=structural_period_score_stage.split("tensor_local=",1)[0]\nsetup_code=setup_code.replace(\'application["structural_period_score"]\',\'application["structural_clock_coupling"]\')\nexec(compile(setup_code,__file__,"exec"))\ncoupling_settings=score_settings\nparent_key={True:"structural_period_score",False:"structural_cross_phase"}[native_evaluation]\nparent_stem=application[parent_key]["stem"]\nparent_stem=parent_stem.with_name(parent_stem.name+"_common_fold"+str(fold))\nparent=load(parent_stem.with_suffix(".joblib"))\nparent_predictions=np.load(parent_stem.with_suffix(".npz"),allow_pickle=False)\nassert np.array_equal(parent["training_trace_id"],trace_id[train])\nassert np.array_equal(parent_predictions["trace_id"],trace_id[heldout])\nnp.testing.assert_allclose(parent["source_period_mass"],source_mass,atol=1.e-12,rtol=1.e-10)\nnp.testing.assert_allclose(parent["feature_mean"],feature_mean,atol=1.e-12,rtol=1.e-10)\nnp.testing.assert_allclose(parent["feature_sd"],feature_sd,atol=1.e-12,rtol=1.e-10)\nnp.testing.assert_allclose(parent["pair_mean"][:2],pair_mean,atol=1.e-12,rtol=1.e-10)\nnp.testing.assert_allclose(parent["pair_sd"][:2],pair_sd,atol=1.e-12,rtol=1.e-10)\nindependent_prior=source_prior[0,:,None]*source_prior[1,None,:]\npaired_prior=np.einsum("n,np,nq->pq",row_weight,source_mass[:,0],source_mass[:,1],optimize=True)\nnp.testing.assert_allclose(paired_prior.sum(axis=1),source_prior[0],atol=1.e-12)\nnp.testing.assert_allclose(paired_prior.sum(axis=0),source_prior[1],atol=1.e-12)\nnp.testing.assert_allclose(np.diff(periods),periods[1]-periods[0],atol=1.e-12)\ndifference_index=np.arange(period_n)[:,None]-np.arange(period_n)[None]+period_n-1\ndifference_mass=np.bincount(difference_index.ravel(),weights=paired_prior.ravel(),minlength=2*period_n-1)\ndifference_conditional=difference_mass[difference_index]\ndifference_conditional/=difference_conditional.sum(axis=0,keepdims=True)\ndifference_prior=difference_conditional*source_prior[1,None]\nprior_law=np.stack([independent_prior,paired_prior,difference_prior])\nnp.testing.assert_allclose(prior_law.sum(axis=(1,2)),1.,atol=1.e-12)\nnp.testing.assert_allclose(difference_prior.sum(axis=0),source_prior[1],atol=1.e-12)\nassert prior_law.min()>0.\ntensor_local=torch.as_tensor(np.ascontiguousarray(standardized[train]))\ntensor_pair=torch.as_tensor(np.ascontiguousarray(standardized_pair[train]))\njoint_teacher=source_mass[:,0,:,None]*source_mass[:,1,None,:]\ntensor_teacher=torch.as_tensor(joint_teacher)\ntensor_weight=torch.as_tensor(row_weight)\ntensor_prior=torch.as_tensor(np.log(prior_law[[1,2,1,2]]))\nparameter_count=coupling_settings["regularization_slots"]\nparameter_mask=torch.as_tensor(np.arange(parameter_count)[None,:]<np.array([8,8,10,10])[:,None])\nforward=lambda vector,local,pair:(\n    weights:=vector.reshape(4,parameter_count)*parameter_mask,\n    target_score:=torch.einsum("npf,mf->mnp",local,weights[:,:4]),\n    background_score:=torch.einsum("nqf,mf->mnq",local,weights[:,4:8]),\n    pair_score:=torch.einsum("npqf,mf->mnpq",pair,weights[:,8:10]),\n    target_score[:,:,:,None]+background_score[:,:,None,:]+pair_score+tensor_prior[:,None])[-1]\ndata_losses=lambda vector:-(tensor_weight[None,:,None,None]*tensor_teacher[None]\n    *torch.log_softmax(forward(vector,tensor_local,tensor_pair).flatten(-2),dim=-1).reshape(\n        4,len(train_rows),period_n,period_n)).sum(dim=(1,2,3))/2.\nobjective=lambda vector:data_losses(vector).mean()+fit_settings["weight_decay"]*vector.square().mean()\nautograd_objective=torch.func.grad_and_value(objective)\nto_scipy=lambda gradient,value:(value.detach().item(),gradient.detach().numpy())\nscipy_objective=lambda vector:to_scipy(*autograd_objective(torch.from_numpy(vector)))\ninitial=np.zeros(4*parameter_count)\ninitial_loss,initial_gradient=scipy_objective(initial)\nnp.testing.assert_allclose(data_losses(torch.as_tensor(initial)).detach().numpy(),\n    -np.einsum("pq,mpq->m",paired_prior,np.log(prior_law[[1,2,1,2]]))/2.,atol=1.e-12)\nassert np.isfinite(initial_gradient).all()\nloss_history=[[0,initial_loss]]\nprint("CLOCK_COUPLING_SETUP","fold",fold,"training_records",len(train_rows),"held_records",len(held_rows),\n    "paired_mutual_information",float(np.sum(paired_prior*np.log(paired_prior/independent_prior))),\n    "difference_prior_target_mean",float(difference_prior.sum(axis=1)@periods),\n    "independent_target_mean",float(source_prior[0]@periods),flush=True)\nresult=minimize(scipy_objective,initial,jac=True,method="L-BFGS-B",\n    callback=lambda intermediate_result:(loss_history.append([len(loss_history),float(intermediate_result.fun)]),\n        len(loss_history)%25==0 and print("CLOCK_COUPLING_PROGRESS",fold,len(loss_history)-1,float(intermediate_result.fun),flush=True)),\n    options={"maxiter":fit_settings["maxiter"],"ftol":fit_settings["ftol"],"gtol":fit_settings["gtol"],"maxls":fit_settings["maxls"]})\nparameters=torch.as_tensor(result.x)\nassert np.isfinite(result.x).all() and np.isfinite(result.fun)\ntraining_losses=data_losses(parameters).detach().numpy()\ndump({"parameters":result.x.reshape(4,parameter_count),"parameter_mask":parameter_mask.numpy(),\n    "feature_mean":feature_mean,"feature_sd":feature_sd,"phase_operator":phase_operator,\n    "pair_mean":pair_mean,"pair_sd":pair_sd,"source_prior":source_prior,"prior_law":prior_law,\n    "difference_mass":difference_mass,"source_period_mass":source_mass,"training_trace_id":trace_id[train],\n    "training_groups":training_groups,"training_weight":row_weight,"optimization":result,\n    "loss_history":np.asarray(loss_history),"training_crossentropy":training_losses,\n    "configuration":coupling_settings,"fit_configuration":fit_settings,"parent_path":str(parent_stem),\n    "heldout_optical_read":False},stem.with_suffix(".joblib"))\nlogit=forward(parameters,torch.as_tensor(np.ascontiguousarray(standardized[heldout])),\n    torch.as_tensor(np.ascontiguousarray(standardized_pair[heldout]))).detach().numpy()\nnew_joint=softmax(logit.reshape(4,len(held_rows),-1),axis=-1).transpose(1,0,2).reshape(len(held_rows),4,period_n,period_n)\njoint_mass=np.empty((len(held_rows),6,period_n,period_n))\njoint_mass[:,[0,3]]=parent_predictions["joint_mass"][:,:2]\njoint_mass[:,[1,2,4,5]]=new_joint\nlearned_mass=np.stack([joint_mass.sum(axis=-1),joint_mass.sum(axis=-2)],axis=-2)\nprior_role_mass=np.stack([prior_law.sum(axis=-1),prior_law.sum(axis=-2)],axis=1)\nrole_mass=np.concatenate([learned_mass,np.broadcast_to(prior_role_mass,(len(held_rows),3,2,period_n))],axis=1)\nnp.testing.assert_allclose(role_mass[:,[0,3]],parent_predictions["role_mass"][:,:2],atol=1.e-12,rtol=1.e-10)\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nrole_score=role_mass@window.T\nrole_estimate=periods[role_score.argmax(axis=-1)]\nrole_confidence=role_score.max(axis=-1)\nmass,estimate,confidence=role_mass[:,:,0],role_estimate[:,:,0],role_confidence[:,:,0]\nmethods=np.asarray(coupling_settings["methods"])\nassert np.isfinite(role_mass).all() and np.allclose(role_mass.sum(axis=-1),1.)\npredictions=pd.DataFrame({"trace_id":np.repeat(trace_id[heldout],len(methods)),\n    "method":np.tile(methods,len(held_rows)),"estimate_h":estimate.ravel(),"confidence":confidence.ravel(),\n    "heldout_fold":fold,"heldout_run":np.repeat(run[heldout],len(methods)),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id[heldout],time=time,mask=mask[heldout],\n    periods=periods,methods=methods,mass=mass,estimate=estimate,confidence=confidence,\n    role_mass=role_mass,role_estimate=role_estimate,role_confidence=role_confidence,joint_mass=joint_mass,\n    prior_law=prior_law,source_prior=source_prior,prior_role_mass=prior_role_mass,difference_mass=difference_mass,\n    source_period_mass=source_mass,training_trace_id=trace_id[train],training_groups=training_groups,\n    confidence_definition="coupled_period_model_probability_not_coverage_calibrated")\nprint("CLOCK_COUPLING_FIT","fold",fold,"iterations",result.nit,"status",str(result.message),\n    "training_crossentropy",training_losses.tolist(),flush=True)\nnative=native_evaluation\nexec(compile(structural_source_readout_stage[structural_source_readout_stage.index("# Join held-out reference"):],__file__,"exec"))\nraise SystemExit(0)\n'
exec(compile({True:structural_clock_coupling_stage,False:""}[args.stage=="structural-clock-coupling"],__file__,"exec"))

structural_observation_relation_stage = '\nfrom scipy.signal import savgol_filter\nmeasurement_settings=application["structural_observation_relation"]\nwindow_h=application["conditional_source_external"]["window_h"]\nnative=pd.read_parquet(application["paths"]["lemna_dual_observations"])\nnative["published_background_y"]=native.green*application["background_templates"]["optical_coefficients"][0]+native.red*application["background_templates"]["optical_coefficients"][1]\nexternal=pd.read_parquet(application["conditional_source_external"]["raw"])\nobservations=pd.concat([native.assign(cohort="native"),external.assign(cohort="external")],ignore_index=True)\nobservations=observations.loc[observations.time_h.between(*window_h)]\nrecord=observations[["trace_id","run","cohort"]].drop_duplicates().sort_values("trace_id").set_index("trace_id")\ntrace_id=record.index.to_numpy(dtype=str)\nno_table=observations.pivot(index="trace_id",columns="time_h",values="no").reindex(index=trace_id)\ntarget_table=observations.pivot(index="trace_id",columns="time_h",values="published_target_y").reindex(index=trace_id,columns=no_table.columns)\nbackground_table=observations.pivot(index="trace_id",columns="time_h",values="published_background_y").reindex(index=trace_id,columns=no_table.columns)\ntime=no_table.columns.to_numpy(dtype=float)\nmixture=no_table.to_numpy(dtype=float)\nsources=np.stack([target_table.to_numpy(dtype=float),background_table.to_numpy(dtype=float)],axis=-1)\nassert np.isfinite(mixture).all() and np.isfinite(sources).all()\nassert record.cohort.value_counts().to_dict()=={"native":application["conditional_source_external"]["expected_training_records"],"external":application["conditional_source_external"]["expected_external_records"]}\nstep=np.diff(time)\nnp.testing.assert_allclose(step,step[0],atol=1.e-12)\nrecord_n,length=mixture.shape\nraw=(sources-sources.mean(axis=1,keepdims=True))/sources.std(axis=1,keepdims=True)\nsmoothed=savgol_filter(raw,measurement_settings["smooth_window"],measurement_settings["polyorder"],axis=1,mode="interp")\nderivative=savgol_filter(raw,measurement_settings["smooth_window"],measurement_settings["polyorder"],deriv=1,delta=step[0],axis=1,mode="interp")\nnormalized_time=(time-time.mean())/(time[-1]-time[0])\nnull_sources=np.zeros_like(raw)\nnull_extras=np.zeros((record_n,length,3))\nbase=np.stack([np.ones(length),normalized_time],axis=-1)\ncore=np.stack([null_sources,raw,smoothed,smoothed,smoothed,smoothed])\nextras=np.stack([null_extras,null_extras,null_extras,\n    np.concatenate([derivative,np.zeros((record_n,length,1))],axis=-1),\n    np.concatenate([smoothed*normalized_time[None,:,None],np.zeros((record_n,length,1))],axis=-1),\n    np.stack([smoothed[:,:,0]**2,smoothed[:,:,0]*smoothed[:,:,1],smoothed[:,:,1]**2],axis=-1)])\ndesign=np.concatenate([np.broadcast_to(base,(len(core),record_n,length,2)),core,extras],axis=-1)\nfold_index=np.arange(length)*measurement_settings["cv_blocks"]//length\ntest_mask=fold_index[None]==np.arange(measurement_settings["cv_blocks"])[:,None]\ntrain_mask=~test_mask\nassert np.all(test_mask.sum(axis=0)==1)\ntrain_design=design[None]*train_mask[:,None,None,:,None]\ncv_coefficients=np.einsum("fmnkt,fnt->fmnk",np.linalg.pinv(train_design),\n    mixture[None]*train_mask[:,None],optimize=True)\ncv_prediction=np.einsum("fmnk,mntk->fmnt",cv_coefficients,design,optimize=True)\ncv_prediction=np.sum(cv_prediction*test_mask[:,None,None],axis=0)\nfull_coefficients=np.einsum("mnkt,nt->mnk",np.linalg.pinv(design),mixture,optimize=True)\nfull_prediction=np.einsum("mnk,mntk->mnt",full_coefficients,design,optimize=True)\ncv_residual=mixture[None]-cv_prediction\nfull_residual=mixture[None]-full_prediction\ncv_mse=np.mean(cv_residual**2,axis=-1).T\nfull_mse=np.mean(full_residual**2,axis=-1).T\nno_variance=np.var(mixture,axis=-1)\nassert np.all(no_variance>0.)\ncv_nmse=cv_mse/no_variance[:,None]\nfull_nmse=full_mse/no_variance[:,None]\nmethods=np.asarray(measurement_settings["methods"])\nimplied_lag_h=full_coefficients[3,:,4:6]/full_coefficients[3,:,2:4]\nsource_gain=full_coefficients[3,:,2:4]\nrecord_group=record.cohort.to_numpy(dtype=str)+"__"+record.run.to_numpy(dtype=str)\ngroup_names,group_index,group_n=np.unique(record_group,return_inverse=True,return_counts=True)\nrecord_weight=1./group_n[group_index]\ncells=pd.DataFrame({"trace_id":np.repeat(trace_id,len(methods)),\n    "run":np.repeat(record.run.to_numpy(dtype=str),len(methods)),\n    "cohort":np.repeat(record.cohort.to_numpy(dtype=str),len(methods)),\n    "method":np.tile(methods,record_n),"cv_nmse":cv_nmse.ravel(),"full_fit_nmse":full_nmse.ravel(),\n    "cv_nmse_delta_raw":(cv_nmse-cv_nmse[:,1,None]).ravel(),\n    "cv_nmse_delta_smoothed":(cv_nmse-cv_nmse[:,2,None]).ravel(),\n    "cv_better_than_raw":(cv_nmse<cv_nmse[:,1,None]).ravel(),\n    "cv_better_than_smoothed":(cv_nmse<cv_nmse[:,2,None]).ravel()})\ngroups=cells.groupby(["cohort","run","method"],as_index=False).agg(n=("trace_id","size"),\n    cv_nmse=("cv_nmse","mean"),full_fit_nmse=("full_fit_nmse","mean"),\n    cv_nmse_delta_raw=("cv_nmse_delta_raw","mean"),cv_nmse_delta_smoothed=("cv_nmse_delta_smoothed","mean"),\n    fraction_better_raw=("cv_better_than_raw","mean"),fraction_better_smoothed=("cv_better_than_smoothed","mean"))\nsummary=groups.groupby(["cohort","method"],as_index=False).agg(n=("n","sum"),runs=("run","size"),\n    cv_nmse=("cv_nmse","mean"),full_fit_nmse=("full_fit_nmse","mean"),\n    cv_nmse_delta_raw=("cv_nmse_delta_raw","mean"),cv_nmse_delta_smoothed=("cv_nmse_delta_smoothed","mean"),\n    fraction_better_raw=("fraction_better_raw","mean"),fraction_better_smoothed=("fraction_better_smoothed","mean"))\nstem=measurement_settings["stem"]\ncells.to_csv(stem.with_name(stem.name+"_cells.csv"),index=False,encoding="utf-8",lineterminator="\\n")\ngroups.to_csv(stem.with_name(stem.name+"_groups.csv"),index=False,encoding="utf-8",lineterminator="\\n")\nsummary.to_csv(stem.with_name(stem.name+"_summary.csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id,run=record.run.to_numpy(dtype=str),\n    cohort=record.cohort.to_numpy(dtype=str),time=time,methods=methods,fold_index=fold_index,\n    cv_coefficients=cv_coefficients,full_coefficients=full_coefficients,cv_prediction=cv_prediction,\n    full_prediction=full_prediction,cv_nmse=cv_nmse,full_nmse=full_nmse,mixture=mixture,sources=sources,\n    implied_lag_h=implied_lag_h,source_gain=source_gain,\n    evaluation="optical_oracle_observation_diagnostic_not_unfiltered_source_recovery",\n    derivative_note="unbounded_first_order_timing_approximation_lag_ratio_not_a_calibrated_delay_estimate",\n    normalization="squared_error_divided_by_same_record_observed_No_variance_equal_experiment_weight")\nprint("OBSERVATION_RELATION",summary.to_string(index=False),flush=True)\nprint("DERIVATIVE_DIAGNOSTIC","lag_h_quantile_10_50_90",np.quantile(implied_lag_h,[.1,.5,.9],axis=0).tolist(),\n    "absolute_lag_within_external_dark_interval_fraction",\n    (np.abs(implied_lag_h)<=measurement_settings["external_dark_interval_h"]).mean(axis=0).tolist(),\n    "negative_gain_fraction",(source_gain<0.).mean(axis=0).tolist(),flush=True)\nassert np.isfinite(cv_prediction).all() and np.isfinite(full_prediction).all()\nassert np.all(full_mse[:,3:]<=full_mse[:,2,None]+1.e-8*no_variance[:,None])\nraise SystemExit(0)\n'
exec(compile({True:structural_observation_relation_stage,False:""}[args.stage=="structural-observation-relation"],__file__,"exec"))

structural_background_annihilation_stage = '\nfrom scipy.special import softmax\nprobe_settings=application["structural_background_annihilation"]\nb=np.load(application["structural_observation_relation"]["stem"].with_suffix(".npz"),allow_pickle=False)\ntrace_id=b["trace_id"]\nrun=b["run"]\ncohort=b["cohort"]\ntime=b["time"]-b["time"][0]\nraw=b["mixture"]\nrecord_n,length=raw.shape\nbase=np.stack([np.ones(length)/np.sqrt(length),(time-time.mean())/np.linalg.norm(time-time.mean())],axis=-1)\nmixed=raw-(raw@base)@base.T\nmixed/=np.sqrt(np.mean(mixed**2,axis=1))[:,None]\ngroup_names,group_index,group_n=np.unique(cohort+"__"+run,return_inverse=True,return_counts=True)\nmembership=group_names[:,None]==(cohort+"__"+run)[None]\npeer=((membership.astype(float)@mixed)[group_index]-mixed)/(group_n[group_index,None]-1)\nreadout_code=structural_source_readout_stage.split("prior_labels =",1)[0]\nreadout_code=readout_code.replace("waves = np.stack([prediction,mixed[heldout]],axis=1)","waves = readout_waves")\nreadout_code=readout_code.replace("held_mask = mask[heldout]","held_mask = np.ones((record_n,length),dtype=bool)")\nreadout_code=readout_code.replace("held_count = count[heldout]","held_count = np.full(record_n,length,dtype=int)")\nreadout_scope=dict(globals())\nreadout_scope["readout_waves"]=np.stack([mixed,peer],axis=1)\nexec(compile(readout_code,__file__,"exec"),readout_scope)\nperiods=readout_scope["periods"]\ngrid_weight=readout_scope["grid_weight"]\nprecision=application["density"]["coefficient_precision"]\nperiod_n=len(periods)\nobserved_mass=softmax(readout_scope["log_evidence"].reshape(record_n,2,period_n)+np.log(grid_weight)[None,None],axis=-1)\nangle=2.*np.pi*time[None,:,None]/periods[:,None,None]*np.arange(1,probe_settings["harmonics"]+1)[None,None]\nharmonic=np.sqrt(2.)*np.stack([np.cos(angle),np.sin(angle)],axis=-1).reshape(period_n,length,-1)\ntarget_basis=harmonic[:,:,:2]\nshared_base=np.broadcast_to(base,(period_n,length,2))\nq1=np.linalg.qr(np.concatenate([shared_base,harmonic[:,:,:2]],axis=-1),mode="reduced")[0]\nq3=np.linalg.qr(np.concatenate([shared_base,harmonic],axis=-1),mode="reduced")[0]\nidentity=np.eye(length)\nproject1=identity-q1@q1.swapaxes(-2,-1)\nproject3=identity-q3@q3.swapaxes(-2,-1)\nnp.testing.assert_allclose(np.diff(time),time[1]-time[0],atol=1.e-12)\ndelay_position=np.arange(length)[None]+periods[:,None]/(time[1]-time[0])\nlower_index=np.floor(delay_position).astype(int)\nfraction=delay_position-lower_index\ncolumn=np.arange(length)[None,None]\ninterpolator=((1.-fraction)[...,None]*(column==lower_index[...,None])\n    +fraction[...,None]*(column==lower_index[...,None]+1))\ndifference=(interpolator-identity)*(delay_position<=length-1)[...,None]\ndifference_projection=np.linalg.pinv(difference)@difference\nlinear_projection=difference_projection@base[:,1]\nproject_difference=difference_projection-np.einsum("qt,qu->qtu",linear_projection,linear_projection)/(\n    np.einsum("t,qt->q",base[:,1],linear_projection)[:,None,None])\nprojection=np.stack([project1,project3,project_difference])\nnp.testing.assert_allclose(projection,projection.swapaxes(-2,-1),atol=1.e-10)\nnp.testing.assert_allclose(projection@projection,projection,atol=1.e-10)\nnp.testing.assert_allclose(projection@base,0.,atol=1.e-10)\ndimension=np.trace(projection,axis1=-2,axis2=-1)\nnp.testing.assert_allclose(dimension,np.rint(dimension),atol=1.e-9)\nprojected_target=np.einsum("mqtu,pui->mqpti",projection,target_basis,optimize=True)\ngram=np.einsum("pti,mqptj->mqpij",target_basis,projected_target,optimize=True)\ninverse=np.linalg.inv(gram+precision*np.eye(2))\nrhs=np.einsum("nt,mqpti->mqnpi",mixed,projected_target,optimize=True)\ncoefficient=np.einsum("mqpij,mqnpj->mqnpi",inverse,rhs,optimize=True)\nbase_rss=np.einsum("nt,mqtu,nu->mqn",mixed,projection,mixed,optimize=True)\nrss=base_rss[:,:,:,None]-np.sum(rhs*coefficient,axis=-1)\nassert rss.min()>0.\nlog_evidence=-.5*np.linalg.slogdet(gram+precision*np.eye(2))[1][:,:,None]-.5*dimension[:,:,None,None]*np.log(rss)\nconditional_mass=softmax(log_evidence+np.log(grid_weight)[None,None,None],axis=-1)\nself_mass=np.einsum("nq,mqnp->nmp",observed_mass[:,0],conditional_mass,optimize=True)\npeer_mass=np.einsum("nq,mqnp->nmp",observed_mass[:,1],conditional_mass,optimize=True)\nobserved_target_mass=np.concatenate([observed_mass[:,:1],self_mass,peer_mass],axis=1)\nmethods=np.asarray(probe_settings["methods"])\nwindow=(np.abs(periods[:,None]-periods[None])<=application["risk_tolerance_h"]).astype(float)\nscore=observed_target_mass@window.T\nestimate=periods[score.argmax(axis=-1)]\nconfidence=score.max(axis=-1)\nstem=probe_settings["stem"]\npredictions=pd.DataFrame({"trace_id":np.repeat(trace_id,len(methods)),"run":np.repeat(run,len(methods)),\n    "cohort":np.repeat(cohort,len(methods)),"method":np.tile(methods,record_n),\n    "estimate_h":estimate.ravel(),"confidence":confidence.ravel(),"method_status":"ok"})\npredictions.to_csv(stem.with_suffix(".csv"),index=False,encoding="utf-8",lineterminator="\\n")\nnp.savez_compressed(stem.with_suffix(".npz"),trace_id=trace_id,run=run,cohort=cohort,time=time,\n    periods=periods,methods=methods,mass=observed_target_mass,estimate=estimate,confidence=confidence,\n    nuisance_period_mass=observed_mass,projection=projection,dimension=dimension,\n    projected_target_gram=gram,\n    coefficient_precision=precision,query_optical_read=False,\n    interpretation="modular_period_readout_conditional_on_No_or_peer_nuisance_period_not_joint_posterior",\n    difference_model="piecewise_linear_one_period_delay_annihilator_with_exact_white_noise_covariance")\n# Optical channels are accessed only after the No-only predictions are saved.\nsource_waves=b["sources"].transpose(0,2,1).copy()\nsource_waves-=(source_waves@base)@base.T\nreadout_scope["readout_waves"]=source_waves\nexec(compile(readout_code,__file__,"exec"),readout_scope)\noptical_mass=softmax(readout_scope["log_evidence"].reshape(record_n,2,period_n)+np.log(grid_weight)[None,None],axis=-1)\noracle_mass=np.einsum("nq,mqnp->nmp",optical_mass[:,1],conditional_mass,optimize=True)\noracle_score=oracle_mass@window.T\noracle_estimate=periods[oracle_score.argmax(axis=-1)]\noracle_methods=np.asarray(probe_settings["oracle_methods"])\nnp.savez_compressed(stem.with_name(stem.name+"_oracle").with_suffix(".npz"),trace_id=trace_id,\n    methods=oracle_methods,periods=periods,optical_period_mass=optical_mass,\n    mass=oracle_mass,estimate=oracle_estimate,\n    interpretation="diagnostic_uses_held_optical_background_period_distribution_not_algorithm_performance")\nnative_reference=pd.read_csv(application["paths"]["lemna_reference"],encoding="utf-8").set_index("trace_id")\nnative_background=pd.read_csv(application["source_density"]["background_reference"],encoding="utf-8").set_index("trace_id")\nexternal_reference=pd.read_csv(application["conditional_source_external"]["reference"],encoding="utf-8").set_index("trace_id")\ntruth=pd.concat([native_reference.reference_period_h,external_reference.target_period_h]).reindex(trace_id).to_numpy()\nqualified=pd.concat([native_reference.reference_usable,external_reference.target_reference_usable]).reindex(trace_id).eq(True).to_numpy()\nnative_distinct=native_reference.reference_usable.eq(True)&native_background.background_usable.reindex(native_reference.index).eq(True)&((native_reference.reference_period_h-native_background.background_period_h.reindex(native_reference.index)).abs()>2*application["risk_tolerance_h"])\ndistinct=pd.concat([native_distinct,external_reference.distinct.eq(True)]).reindex(trace_id).eq(True).to_numpy()\nall_estimate=np.concatenate([estimate,oracle_estimate],axis=1)\nall_methods=np.r_[methods,oracle_methods]\nerror=np.abs(all_estimate-truth[:,None])\ncells=pd.DataFrame({"trace_id":np.repeat(trace_id,len(all_methods)),"cohort":np.repeat(cohort,len(all_methods)),\n    "run":np.repeat(run,len(all_methods)),"method":np.tile(all_methods,record_n),\n    "qualified":np.repeat(qualified,len(all_methods)),"distinct":np.repeat(distinct,len(all_methods)),\n    "estimate_h":all_estimate.ravel(),"error_h":error.ravel(),"bad2h":(error>application["risk_tolerance_h"]).ravel()})\ncells.to_csv(stem.with_name(stem.name+"_cells.csv"),index=False,encoding="utf-8",lineterminator="\\n")\nsummary=cells.loc[cells.qualified].groupby(["cohort","method"],as_index=False).agg(\n    n=("trace_id","size"),bad2h=("bad2h","sum"),mae_h=("error_h","mean"))\nsummary.to_csv(stem.with_name(stem.name+"_summary.csv"),index=False,encoding="utf-8",lineterminator="\\n")\nprint("BACKGROUND_ANNIHILATION_ALL",summary.to_string(index=False),flush=True)\nprint("BACKGROUND_ANNIHILATION_DISTINCT",cells.loc[cells.distinct].groupby(["cohort","method"]).agg(\n    n=("trace_id","size"),bad2h=("bad2h","sum"),mae_h=("error_h","mean")).to_string(),flush=True)\nselected=distinct&(cohort=="external")\nprint("BACKGROUND_ANNIHILATION_EXTERNAL_THREE",trace_id[selected].tolist(),"truth",truth[selected].tolist(),\n    "methods",all_methods.tolist(),"prediction",all_estimate[selected].tolist(),\n    "projection_dimension_range",np.stack([dimension.min(axis=1),dimension.max(axis=1)],axis=1).tolist(),flush=True)\nraise SystemExit(0)\n'
exec(compile({True:structural_background_annihilation_stage,False:""}[args.stage=="structural-background-annihilation"],__file__,"exec"))

