task_density_refine_stage = '\nimport torch\nfrom scipy.optimize import minimize\nsolver_config = {"maxiter":800,"ftol":1e-11,"gtol":1e-6,"maxls":30,"progress_every":25}\nbench = application["task_supervised"]\nconfig = application["task_transfer"]\noutput_path = Path(str(config["stem"])+"_period_density_refine.npz")\ndata = np.load(str(bench["stem"])+"_context.npz",allow_pickle=False)\ncache = np.load(str(config["stem"])+"_period_profile_context.npz",allow_pickle=False)\nparent = np.load(str(config["stem"])+"_period_density_ordered.npz",allow_pickle=False)\ntorch.set_num_threads(int(os.environ["PERIOD_THREADS"]))\nperiod = cache["period"]\nbase_features = cache["base_features"]\nleft,right = np.triu_indices(base_features.shape[-1])\noriginal = np.concatenate([base_features,base_features[:,:,left]*base_features[:,:,right]],axis=-1)\nslope = np.gradient(base_features,period,axis=1,edge_order=2)\nfeatures = np.stack([np.concatenate([original,slope],axis=-1),\n    np.concatenate([original,np.zeros_like(slope)],axis=-1)])\nn_outer = len(data["outer_protocol"])\ntrain = data["case_train"][:n_outer]\ntrain_n = train.sum(axis=1)\noriginal_weight = train/train_n[:,None]\nrun_labels = data["run_membership"]@data["qualified"].astype(float)\nbalanced_weight = train/run_labels[data["run_index"]][None]\nbalanced_weight /= balanced_weight.sum(axis=1)[:,None]\nweight = np.stack([original_weight,balanced_weight])\nslope_mean = original_weight@slope.mean(axis=1)\nslope_scale = np.sqrt(np.maximum(original_weight@np.mean(slope**2,axis=1)-slope_mean**2,0.))\nslope_scale = np.where(slope_scale>0.,slope_scale,1.)\nscale = np.concatenate([parent["feature_scale"],slope_scale],axis=-1)\ntarget_mean = weight@data["target"]\ntarget_sd = np.sqrt(weight@(data["target"]**2)-target_mean**2)\ngrid_step = float(period[1]-period[0])\nteacher = np.maximum(1.-abs(period[None]-data["target"][:,None])/grid_step,0.)\nteacher_cdf = np.cumsum(teacher,axis=-1)[:,:-1]\ncdf_constant = grid_step*np.sum(teacher_cdf*(1.-teacher_cdf),axis=-1)\ntensor_features = torch.as_tensor(features,dtype=torch.float64)\ntensor_scale = torch.as_tensor(scale,dtype=torch.float64)\ntensor_teacher = torch.as_tensor(teacher,dtype=torch.float64)\ntensor_cdf = torch.as_tensor(teacher_cdf,dtype=torch.float64)\ntensor_constant = torch.as_tensor(cdf_constant,dtype=torch.float64)\ntensor_weight = torch.as_tensor(weight,dtype=torch.float64)\ntensor_n = torch.as_tensor(train_n,dtype=torch.float64)\ntensor_sd = torch.as_tensor(target_sd,dtype=torch.float64)\nparameter_shape = (2,n_outer,features.shape[-1])\nlogit = lambda parameter:torch.einsum("mnpd,mgd->mgnp",tensor_features,\n    parameter.reshape(parameter_shape)/tensor_scale[None])\nlosses = lambda parameter:(\n    coefficients:=parameter.reshape(parameter_shape),\n    score:=logit(parameter),\n    individual:=-(torch.log_softmax(score,dim=-1)*tensor_teacher[None,None]*tensor_weight[:,:,:,None]).sum(dim=(-1,-2)),\n    cdf:=torch.softmax(score,dim=-1).cumsum(dim=-1)[:,:,:,:-1],\n    ordered:=((((cdf-tensor_cdf[None,None]).square().sum(dim=-1)*grid_step+tensor_constant[None,None])*tensor_weight).sum(dim=-1))/tensor_sd,\n    prior:=coefficients.square().sum(dim=-1)/(2.*tensor_n[None]),\n    torch.stack([individual,ordered,prior],dim=-1))[-1]\nobjective = lambda parameter:losses(parameter).sum(dim=-1).mean()\ngradient_value = torch.func.grad_and_value(objective)\nto_scipy = lambda gradient,value:(value.detach().item(),gradient.detach().numpy())\nscipy_objective = lambda parameter:to_scipy(*gradient_value(torch.from_numpy(parameter)))\ninitial_one = np.pad(parent["coefficient"]*parent["feature_scale"],((0,0),(0,slope.shape[-1])))\ninitial = np.broadcast_to(initial_one,parameter_shape).copy().ravel()\ninitial_value,initial_gradient = scipy_objective(initial)\nprobe = np.zeros_like(initial)\nprobe[original.shape[-1]] = 1e-4\nfinite_difference = (float(objective(torch.from_numpy(initial+probe)))-\n    float(objective(torch.from_numpy(initial-probe))))/(2e-4)\ngradient_check = abs(finite_difference-initial_gradient[original.shape[-1]])\nassert gradient_check<1e-7\ninitial_mass = torch.softmax(logit(torch.from_numpy(initial)),dim=-1).detach().numpy()\nwarm_start_check = np.max(abs(initial_mass-parent["posterior"][None]))\nassert warm_start_check<1e-10\nassert np.max(abs(weight.sum(axis=-1)-1.))<1e-12\nassert not np.any(weight[:,~train]>0.)\nhistory = [[0,initial_value]]\nprint("DENSITY_REFINE_SETUP",n_outer,"cases","dimensions",features.shape[-1],\n    "warm_start_check",warm_start_check,"gradient_check",gradient_check,\n    "initial_components",losses(torch.from_numpy(initial)).mean(dim=1).detach().numpy().tolist(),flush=True)\nresult = minimize(scipy_objective,initial,jac=True,method="L-BFGS-B",\n    callback=lambda intermediate_result:(history.append([len(history),float(intermediate_result.fun)]),\n        len(history)%solver_config["progress_every"]==0 and print("DENSITY_REFINE_PROGRESS",\n        len(history)-1,float(intermediate_result.fun),flush=True)),\n    options={"maxiter":solver_config["maxiter"],"ftol":solver_config["ftol"],"gtol":solver_config["gtol"],"maxls":solver_config["maxls"]})\nparameters = torch.as_tensor(result.x,dtype=torch.float64)\nscore = logit(parameters).detach().numpy()\nmass = torch.softmax(torch.as_tensor(score),dim=-1).numpy()\nmode = period[score.argmax(axis=-1)]\nmean = mass@period\nmedian = period[(np.cumsum(mass,axis=-1)>=.5).argmax(axis=-1)]\nestimate = np.stack([mean,mode,median],axis=-1).transpose(1,2,0,3).reshape(n_outer,len(data["trace_id"]),6)\nassert np.isfinite(estimate[data["outer_query"]]).all()\nnp.savez_compressed(output_path,\n    methods=np.asarray(["task_period_density_slope_mean","task_period_density_slope_mode","task_period_density_slope_median",\n        "task_period_density_runbalanced_mean","task_period_density_runbalanced_mode","task_period_density_runbalanced_median"]),\n    estimate=estimate,trace_id=data["trace_id"],period=period,\n    coefficient=result.x.reshape(parameter_shape)/scale[None],feature_scale=scale,posterior=mass,\n    objective_history=np.asarray(history),gradient_check=gradient_check,warm_start_check=warm_start_check,\n    final_objective=result.fun,optimizer_success=result.success,optimizer_message=str(result.message),\n    optimizer_iterations=result.nit,gradient_max=np.max(abs(result.jac)),\n    gradient_by_variant=np.max(abs(result.jac.reshape(parameter_shape)),axis=(1,2)),\n    loss_components=losses(parameters).detach().numpy(),target_sd=target_sd,\n    training_labels=train_n,training_weight=weight,\n    definition=np.asarray(["original_90_features_plus_12_candidate_period_derivatives",\n        "original_90_features_equal_weight_per_eligible_training_experiment"]),\n    fit="same_logloss_CRPS_unit_Gaussian_prior_original_29_outer_cases_no_new_validation",\n    warm_start="converged_same_fold_ordered_density_no_new_start_or_seed")\nprint("DENSITY_REFINE_FITTED",str(result.message),"iterations",result.nit,\n    "components",losses(parameters).mean(dim=1).detach().numpy().tolist(),\n    "max_gradient",np.max(abs(result.jac)),flush=True)\nraise SystemExit(0)\n'
exec(compile({True:task_density_refine_stage,False:""}[args.stage=="task-period-density-refine"],__file__,"exec"))
task_density_partial_stage = '\nimport torch\nfrom scipy.optimize import minimize\nsolver_config = {"maxiter":800,"ftol":1e-11,"gtol":1e-6,"maxls":30,"progress_every":50,"projection_rtol":1e-10}\nbench = application["task_supervised"]\nconfig = application["task_transfer"]\noutput_path = Path(str(config["stem"])+"_period_density_partial.npz")\ndata = np.load(str(bench["stem"])+"_context.npz",allow_pickle=False)\ncache = np.load(str(config["stem"])+"_period_profile_context.npz",allow_pickle=False)\nparent = np.load(str(config["stem"])+"_period_density_ordered.npz",allow_pickle=False)\ntorch.set_num_threads(int(os.environ["PERIOD_THREADS"]))\nperiod = cache["period"]\noriginal_base = cache["base_features"]\ntime = data["time"]\ncount = data["mask"].sum(axis=1)\nlengths = np.unique(count)\nlayout = pd.Index(lengths).get_indexer(count)\nlayout_mask = np.arange(len(time))[None]<lengths[:,None]\ncentered_time = (time[None]-np.sum(layout_mask*time[None],axis=1)[:,None]/lengths[:,None])*layout_mask\ntrend = np.stack([layout_mask/np.sqrt(lengths[:,None]),\n    centered_time/np.sqrt(np.sum(centered_time**2,axis=1))[:,None]],axis=-1)\nangle = 2.*np.pi*time[None]/period[:,None]\nharmonic = np.stack([np.cos(angle),np.sin(angle)],axis=-1)\ntrend_cross = np.einsum("lti,ptj->lpij",trend,harmonic,optimize=True)\ngram = np.einsum("lt,pti,ptj->lpij",layout_mask.astype(float),harmonic,harmonic,optimize=True)\ngram -= trend_cross.swapaxes(-1,-2)@trend_cross\nnuisance_index = original_base[:,:,4].argmax(axis=1)\nnuisance_design = harmonic[nuisance_index]*data["mask"][:,:,None]-trend[layout]@trend_cross[layout,nuisance_index]\ncross = np.einsum("pti,ntj->npij",harmonic,nuisance_design,optimize=True)\nrhs = np.stack([np.einsum("pti,nt->npi",harmonic,data["mixed"],optimize=True),\n    np.einsum("pti,nt->npi",harmonic,data["peer"],optimize=True)],axis=-1)\nnuisance_gram = gram[layout,nuisance_index]\nnuisance_rhs = rhs[np.arange(len(count)),nuisance_index]\nnuisance_coefficient = np.linalg.solve(nuisance_gram,nuisance_rhs)\npartial_gram = gram[layout]-cross@np.linalg.solve(nuisance_gram[:,None],cross.swapaxes(-1,-2))\npartial_gram = (partial_gram+partial_gram.swapaxes(-1,-2))/2.\npartial_rhs = rhs-cross@nuisance_coefficient[:,None]\neigenvalue,eigenvector = np.linalg.eigh(partial_gram)\ninverse = np.divide(1.,eigenvalue,out=np.zeros_like(eigenvalue),\n    where=eigenvalue>solver_config["projection_rtol"]*count[:,None,None])\npartial_coefficient = (eigenvector*inverse[:,:,None])@eigenvector.swapaxes(-1,-2)@partial_rhs\npartial_power = np.maximum(np.sum(partial_rhs*partial_coefficient,axis=2)/count[:,None,None],0.)\nnuisance_power = np.sum(nuisance_rhs*nuisance_coefficient,axis=1)/count[:,None]\nresidual_variance = np.maximum(1.-nuisance_power,np.finfo(float).eps)\npartial_fraction = np.clip(partial_power/residual_variance[:,None],0.,1.)\npartial_cross = np.sum(partial_rhs[:,:,:,0]*partial_coefficient[:,:,:,1],axis=-1)/count[:,None]\npartial_alignment = np.divide(partial_cross,np.sqrt(partial_power[:,:,0]*partial_power[:,:,1]),\n    out=np.zeros_like(partial_cross),where=(partial_power[:,:,0]*partial_power[:,:,1])>np.finfo(float).eps)\npartial_alignment = np.clip(partial_alignment,-1.,1.)\nbase_features = np.concatenate([original_base,partial_fraction,partial_alignment[:,:,None]],axis=-1)\nleft,right = np.triu_indices(base_features.shape[-1])\nfeatures = np.concatenate([base_features,base_features[:,:,left]*base_features[:,:,right]],axis=-1)\ncheck_record = 0\ncheck_period = int(np.argmin(abs(period-(period[nuisance_index[check_record]]-2.))))\nq_design = nuisance_design[check_record]\np_design = harmonic[check_period]*data["mask"][check_record,:,None]-trend[layout[check_record]]@trend_cross[layout[check_record],check_period]\ndesign = np.concatenate([q_design,p_design],axis=-1)\ncheck_target = np.stack([data["mixed"][check_record],data["peer"][check_record]],axis=-1)\ncheck_coef = np.linalg.lstsq(design,check_target,rcond=None)[0]\nq_residual = check_target-q_design@nuisance_coefficient[check_record]\njoint_residual = check_target-design@check_coef\nlibrary_power = (np.sum(q_residual**2,axis=0)-np.sum(joint_residual**2,axis=0))/count[check_record]\nprojection_check = np.max(abs(library_power-partial_power[check_record,check_period]))\nassert projection_check<1e-8\nassert np.max(partial_power[np.arange(len(count)),nuisance_index])<1e-8\nassert np.isfinite(features).all()\nn_outer = len(data["outer_protocol"])\ntrain = data["case_train"][:n_outer]\ntrain_n = train.sum(axis=1)\nweight = train/train_n[:,None]\nfeature_mean = weight@features.mean(axis=1)\nscale = np.sqrt(np.maximum(weight@np.mean(features**2,axis=1)-feature_mean**2,0.))\nscale = np.where(scale>0.,scale,1.)\nold_left,old_right = np.triu_indices(original_base.shape[-1])\nold_slots = np.concatenate([np.arange(original_base.shape[-1]),\n    base_features.shape[-1]+np.flatnonzero((left<original_base.shape[-1])&(right<original_base.shape[-1]))])\nassert np.array_equal(left[old_slots[original_base.shape[-1]:]-base_features.shape[-1]],old_left)\nassert np.max(abs(scale[:,old_slots]-parent["feature_scale"]))<1e-8\ntarget_mean = weight@data["target"]\ntarget_sd = np.sqrt(weight@(data["target"]**2)-target_mean**2)\ngrid_step = float(period[1]-period[0])\nteacher = np.maximum(1.-abs(period[None]-data["target"][:,None])/grid_step,0.)\nteacher_cdf = np.cumsum(teacher,axis=-1)[:,:-1]\ncdf_constant = grid_step*np.sum(teacher_cdf*(1.-teacher_cdf),axis=-1)\ntensor_features = torch.as_tensor(features,dtype=torch.float64)\ntensor_scale = torch.as_tensor(scale,dtype=torch.float64)\ntensor_teacher = torch.as_tensor(teacher,dtype=torch.float64)\ntensor_cdf = torch.as_tensor(teacher_cdf,dtype=torch.float64)\ntensor_constant = torch.as_tensor(cdf_constant,dtype=torch.float64)\ntensor_weight = torch.as_tensor(weight,dtype=torch.float64)\ntensor_n = torch.as_tensor(train_n,dtype=torch.float64)\ntensor_sd = torch.as_tensor(target_sd,dtype=torch.float64)\nparameter_shape = (n_outer,features.shape[-1])\nlogit = lambda parameter:torch.einsum("npd,gd->gnp",tensor_features,parameter.reshape(parameter_shape)/tensor_scale)\nlosses = lambda parameter:(\n    coefficients:=parameter.reshape(parameter_shape),\n    score:=logit(parameter),\n    individual:=-(torch.log_softmax(score,dim=-1)*tensor_teacher[None]*tensor_weight[:,:,None]).sum(dim=(-1,-2)),\n    cdf:=torch.softmax(score,dim=-1).cumsum(dim=-1)[:,:,:-1],\n    ordered:=((((cdf-tensor_cdf[None]).square().sum(dim=-1)*grid_step+tensor_constant[None])*tensor_weight).sum(dim=-1))/tensor_sd,\n    prior:=coefficients.square().sum(dim=-1)/(2.*tensor_n),\n    torch.stack([individual,ordered,prior],dim=-1))[-1]\nobjective = lambda parameter:losses(parameter).sum(dim=-1).mean()\ngradient_value = torch.func.grad_and_value(objective)\nto_scipy = lambda gradient,value:(value.detach().item(),gradient.detach().numpy())\nscipy_objective = lambda parameter:to_scipy(*gradient_value(torch.from_numpy(parameter)))\ninitial = np.zeros(parameter_shape)\ninitial[:,old_slots] = parent["coefficient"]*parent["feature_scale"]\ninitial = initial.ravel()\ninitial_value,initial_gradient = scipy_objective(initial)\nwarm_start_check = np.max(abs(torch.softmax(logit(torch.from_numpy(initial)),dim=-1).detach().numpy()-parent["posterior"]))\nassert warm_start_check<1e-9\nprobe = np.zeros_like(initial)\nprobe[original_base.shape[-1]] = 1e-4\nfinite_difference = (float(objective(torch.from_numpy(initial+probe)))-float(objective(torch.from_numpy(initial-probe))))/(2e-4)\ngradient_check = abs(finite_difference-initial_gradient[original_base.shape[-1]])\nassert gradient_check<1e-7\nhistory = [[0,initial_value]]\nprint("PARTIAL_DENSITY_SETUP",n_outer,"cases","dimensions",features.shape[-1],\n    "projection_check",projection_check,"warm_start_check",warm_start_check,"gradient_check",gradient_check,flush=True)\nresult = minimize(scipy_objective,initial,jac=True,method="L-BFGS-B",\n    callback=lambda intermediate_result:(history.append([len(history),float(intermediate_result.fun)]),\n        len(history)%solver_config["progress_every"]==0 and print("PARTIAL_DENSITY_PROGRESS",\n        len(history)-1,float(intermediate_result.fun),flush=True)),\n    options={"maxiter":solver_config["maxiter"],"ftol":solver_config["ftol"],"gtol":solver_config["gtol"],"maxls":solver_config["maxls"]})\nparameters = torch.as_tensor(result.x,dtype=torch.float64)\nscore = logit(parameters).detach().numpy()\nmass = torch.softmax(torch.as_tensor(score),dim=-1).numpy()\nestimate = np.stack([mass@period,period[score.argmax(axis=-1)],\n    period[(np.cumsum(mass,axis=-1)>=.5).argmax(axis=-1)]],axis=-1)\nnp.savez_compressed(output_path,\n    methods=np.asarray(["task_period_density_partial_mean","task_period_density_partial_mode","task_period_density_partial_median"]),\n    estimate=estimate,trace_id=data["trace_id"],period=period,\n    coefficient=result.x.reshape(parameter_shape)/scale,feature_scale=scale,posterior=mass,\n    nuisance_period=period[nuisance_index],partial_features=base_features[:,:,original_base.shape[-1]:],\n    objective_history=np.asarray(history),gradient_check=gradient_check,warm_start_check=warm_start_check,\n    projection_check=projection_check,final_objective=result.fun,\n    optimizer_success=result.success,optimizer_message=str(result.message),\n    optimizer_iterations=result.nit,gradient_max=np.max(abs(result.jac)),\n    loss_components=losses(parameters).detach().numpy(),target_sd=target_sd,training_labels=train_n,\n    definition="15_base_features_135_total_original_12_plus_own_peer_partial_power_and_alignment",\n    nuisance="leave_one_cell_out_peer_dominant_unfiltered_H1_period_no_reference",\n    fit="same_logloss_CRPS_unit_Gaussian_prior_original_29_outer_cases_no_new_validation",\n    warm_start="converged_same_fold_ordered_density_no_new_start_or_seed")\nprint("PARTIAL_DENSITY_FITTED",str(result.message),"iterations",result.nit,\n    "components",losses(parameters).mean(dim=0).detach().numpy().tolist(),\n    "max_gradient",np.max(abs(result.jac)),flush=True)\nraise SystemExit(0)\n'
exec(compile({True:task_density_partial_stage,False:""}[args.stage=="task-period-density-partial"],__file__,"exec"))
task_density_offset_stage = '\nbench = application["task_supervised"]\nconfig = application["task_transfer"]\noutput_path = Path(str(config["stem"])+"_period_density_offset.npz")\ndata = np.load(str(bench["stem"])+"_context.npz",allow_pickle=False)\ntemporal = np.load(str(config["stem"])+"_context.npz",allow_pickle=False)\nparent = np.load(str(config["stem"])+"_period_density_ordered.npz",allow_pickle=False)\ncontrols = np.load(str(config["stem"])+"_final_controls.npz",allow_pickle=False)\nfeatures = np.concatenate([data["predictors"],temporal["acf_features"]],axis=1)\nn_outer = len(data["outer_protocol"])\ntrain = data["case_train"][:n_outer]\ntrain_n = train.sum(axis=1)\nweight = train/train_n[:,None]\nmean_x = controls["lw_feature_mean"][1]\ncentered = features[None]-mean_x[:,None]\nactive = controls["lw_active"][1]\ncovariance = np.einsum("gn,gnd,gne->gde",weight,centered,centered,optimize=True)\nrho = controls["lw_shrinkage"][1]\nregularization = rho*np.trace(covariance,axis1=-2,axis2=-1)/active.sum(axis=1)/(1.-rho)\nidentity = np.eye(features.shape[1])\noperator = covariance+identity[None]*regularization[:,None,None]*active[:,None]\noperator += identity[None]*(~active[:,None])\nnative_target_mean = weight@data["target"]\nnative_cross = np.einsum("gn,gnd,n->gd",weight,centered,data["target"],optimize=True)\nnative_coefficient = np.linalg.solve(operator,native_cross[:,:,None])[:,:,0]\nnative_replay = native_target_mean[:,None]+np.einsum("gnd,gd->gn",centered,native_coefficient,optimize=True)\nnative_check = np.max(abs(native_replay-controls["estimate"][:,:,-1]))\nassert native_check<1e-8\nbase_prediction = parent["estimate"][:,:,0]\nresidual = data["target"][None]-base_prediction\nresidual_mean = np.sum(weight*residual,axis=1)\ncross = np.einsum("gn,gnd,gn->gd",weight,centered,residual,optimize=True)\ncoefficient = np.linalg.solve(operator,cross[:,:,None])[:,:,0]\ncorrection = residual_mean[:,None]+np.einsum("gnd,gd->gn",centered,coefficient,optimize=True)\nindividual_estimate = base_prediction+correction\nrun_average = data["run_membership"]/data["run_membership"].sum(axis=1)[:,None]\nrun_correction = correction@run_average.T\ncohort_estimate = base_prediction+run_correction[:,data["run_index"]]\nestimate = np.stack([individual_estimate,cohort_estimate],axis=-1)\nassert np.isfinite(estimate[data["outer_query"]]).all()\nnp.savez_compressed(output_path,\n    methods=np.asarray(["task_period_density_offset_mean","task_period_density_offset_cohort_mean"]),estimate=estimate,\n    trace_id=data["trace_id"],coefficient=coefficient,predictor_mean=mean_x,\n    residual_mean=residual_mean,base_prediction=base_prediction,correction=correction,run_correction=run_correction,\n    regularization=regularization,active=active,training_labels=train_n,native_replay_check=native_check,\n    definition="density_offset_residual_regression_individual_or_experiment_mean_correction_preserving_within_run_predictions",\n    penalty="unchanged_effective_penalty_of_native_joint_LedoitWolf_no_weight_tuning",\n    fit="same_original_29_outer_cases_only_eligible_training_labels_no_new_validation")\nprint("DENSITY_OFFSET_FITTED",output_path,"native_replay_check",native_check,\n    "training_residual_sd",np.sqrt(np.sum(weight*(residual-residual_mean[:,None])**2,axis=1)).tolist(),flush=True)\nraise SystemExit(0)\n'
task_density_run_cdf_stage = '\nimport torch\nfrom scipy.optimize import minimize\nsolver_config = {"maxiter":800,"ftol":1e-11,"gtol":1e-6,"maxls":30,"progress_every":25}\nbench = application["task_supervised"]\nconfig = application["task_transfer"]\noutput_path = Path(str(config["stem"])+"_period_density_run_cdf.npz")\ndata = np.load(str(bench["stem"])+"_context.npz",allow_pickle=False)\ncache = np.load(str(config["stem"])+"_period_profile_context.npz",allow_pickle=False)\nparent = np.load(str(config["stem"])+"_period_density_ordered.npz",allow_pickle=False)\ntorch.set_num_threads(int(os.environ["PERIOD_THREADS"]))\nperiod = cache["period"]\nbase_features = cache["base_features"]\nleft,right = np.triu_indices(base_features.shape[-1])\nfeatures = np.concatenate([base_features,base_features[:,:,left]*base_features[:,:,right]],axis=-1)\nn_outer = len(data["outer_protocol"])\ntrain = data["case_train"][:n_outer]\ntrain_n = train.sum(axis=1)\nweight = train/train_n[:,None]\ntarget_mean = weight@data["target"]\ntarget_sd = np.sqrt(weight@(data["target"]**2)-target_mean**2)\nassert target_sd.min()>0.\ngrid_step = float(period[1]-period[0])\nteacher = np.maximum(1.-abs(period[None]-data["target"][:,None])/grid_step,0.)\nteacher_cdf = np.cumsum(teacher,axis=-1)[:,:-1]\ncdf_constant = grid_step*np.sum(teacher_cdf*(1.-teacher_cdf),axis=-1)\ncheck_record = np.flatnonzero(train[0])[0]\ncheck_mass = parent["posterior"][0,check_record]\ncheck_crps_cdf = grid_step*np.sum((np.cumsum(check_mass)[:-1]-teacher_cdf[check_record])**2)+cdf_constant[check_record]\ncheck_crps_energy = check_mass@abs(period-data["target"][check_record])-.5*check_mass@abs(period[:,None]-period[None,:])@check_mass\ncrps_check = abs(check_crps_cdf-check_crps_energy)\nassert crps_check<1e-9\nscale = parent["feature_scale"]\ntensor_features = torch.as_tensor(features,dtype=torch.float64)\ntensor_scale = torch.as_tensor(scale,dtype=torch.float64)\ntensor_teacher = torch.as_tensor(teacher,dtype=torch.float64)\ntensor_cdf = torch.as_tensor(teacher_cdf,dtype=torch.float64)\ntensor_constant = torch.as_tensor(cdf_constant,dtype=torch.float64)\ntensor_weight = torch.as_tensor(weight,dtype=torch.float64)\ntensor_n = torch.as_tensor(train_n,dtype=torch.float64)\ntensor_sd = torch.as_tensor(target_sd,dtype=torch.float64)\nparameter_shape = (n_outer,features.shape[-1])\nrun_membership = data["run_membership"]\nrun_n = run_membership.sum(axis=1)\nrun_qualified = run_membership@data["qualified"].astype(float)\nrun_average = run_membership/run_n[:,None]\nrun_teacher_cdf = (run_membership@(teacher_cdf*data["qualified"][:,None]))/run_qualified[:,None]\ntrain_run = data["outer_train_run"]\nrun_weight = train_run/train_run.sum(axis=1)[:,None]\nrun_target = (run_membership@data["target"])/run_qualified\nrun_target_mean = run_weight@run_target\nrun_target_sd = np.sqrt(run_weight@(run_target**2)-run_target_mean**2)\nassert run_target_sd.min()>0.\ntensor_run_average = torch.as_tensor(run_average,dtype=torch.float64)\ntensor_run_teacher_cdf = torch.as_tensor(run_teacher_cdf,dtype=torch.float64)\ntensor_run_weight = torch.as_tensor(run_weight,dtype=torch.float64)\ntensor_run_sd = torch.as_tensor(run_target_sd,dtype=torch.float64)\nlogit = lambda parameter:torch.einsum("npd,gd->gnp",tensor_features,\n    parameter.reshape(parameter_shape)/tensor_scale)\nlosses = lambda parameter:(\n    coefficients:=parameter.reshape(parameter_shape),\n    score:=logit(parameter),\n    individual:=-(torch.log_softmax(score,dim=-1)*tensor_teacher[None]*tensor_weight[:,:,None]).sum(dim=(-1,-2)),\n    cdf:=torch.softmax(score,dim=-1).cumsum(dim=-1)[:,:,:-1],\n    run_cdf:=torch.einsum("rn,gnp->grp",tensor_run_average,cdf),\n    ordered:=(((run_cdf-tensor_run_teacher_cdf[None]).square().sum(dim=-1)*grid_step)*tensor_run_weight).sum(dim=-1)/tensor_sd,\n    prior:=coefficients.square().sum(dim=-1)/(2.*tensor_n),\n    torch.stack([individual,ordered,prior],dim=-1))[-1]\nobjective = lambda parameter:losses(parameter).sum(dim=-1).mean()\ngradient_value = torch.func.grad_and_value(objective)\nto_scipy = lambda gradient,value:(value.detach().item(),gradient.detach().numpy())\nscipy_objective = lambda parameter:to_scipy(*gradient_value(torch.from_numpy(parameter)))\ninitial = (parent["coefficient"]*scale).ravel()\ninitial_value,initial_gradient = scipy_objective(initial)\nprobe = np.zeros_like(initial)\nprobe[0] = 1e-4\nfinite_difference = (float(objective(torch.from_numpy(initial+probe)))-\n    float(objective(torch.from_numpy(initial-probe))))/(2e-4)\ngradient_check = abs(finite_difference-initial_gradient[0])\nassert gradient_check<1e-7\nhistory = [[0,initial_value]]\nprint("RUN_CDF_DENSITY_SETUP",n_outer,"cases","CRPS_identity_check",crps_check,\n    "initial_components",losses(torch.from_numpy(initial)).mean(dim=0).detach().numpy().tolist(),flush=True)\nresult = minimize(scipy_objective,initial,jac=True,method="L-BFGS-B",\n    callback=lambda intermediate_result:(history.append([len(history),float(intermediate_result.fun)]),\n        len(history)%solver_config["progress_every"]==0 and print("RUN_CDF_DENSITY_PROGRESS",\n        len(history)-1,float(intermediate_result.fun),flush=True)),\n    options={"maxiter":solver_config["maxiter"],"ftol":solver_config["ftol"],"gtol":solver_config["gtol"],"maxls":solver_config["maxls"]})\nparameters = torch.as_tensor(result.x,dtype=torch.float64)\nscore = logit(parameters).detach().numpy()\nmass = torch.softmax(torch.as_tensor(score),dim=-1).numpy()\nmode = period[score.argmax(axis=-1)]\nmean = mass@period\nmedian = period[(np.cumsum(mass,axis=-1)>=.5).argmax(axis=-1)]\nestimate = np.stack([mean,mode,median],axis=-1)\nassert np.isfinite(estimate[data["outer_query"]]).all()\nnp.savez_compressed(output_path,\n    methods=np.asarray(["task_period_density_run_cdf_mean","task_period_density_run_cdf_mode","task_period_density_run_cdf_median"]),\n    estimate=estimate,trace_id=data["trace_id"],period=period,\n    coefficient=result.x.reshape(parameter_shape)/scale,feature_scale=scale,\n    posterior=mass,objective_history=np.asarray(history),\n    gradient_check=gradient_check,crps_identity_check=crps_check,\n    final_objective=result.fun,optimizer_success=result.success,optimizer_message=str(result.message),\n    optimizer_iterations=result.nit,gradient_max=np.max(abs(result.jac)),\n    loss_components=losses(parameters).detach().numpy(),target_sd=target_sd,training_labels=train_n,run_target_sd=run_target_sd,training_run=train_run,\n    definition="point_period_log_loss_plus_training_experiment_marginal_CDF_distance",\n    fit="individual_logloss_plus_equal_experiment_CDF_loss_scaled_by_training_period_SD",\n    warm_start="converged_same_fold_ordered_density_no_new_start_or_seed",\n    reference="Gneiting_Raftery_2007_DOI_10.1198/016214506000001437")\nprint("RUN_CDF_DENSITY_FITTED",str(result.message),"iterations",result.nit,\n    "components",losses(parameters).mean(dim=0).detach().numpy().tolist(),\n    "max_gradient",np.max(abs(result.jac)),flush=True)\nraise SystemExit(0)\n'
exec(compile({"task-period-density-offset":task_density_offset_stage,"task-period-density-run-cdf":task_density_run_cdf_stage}.get(args.stage,""),__file__,"exec"))
task_density_run_offset_stage = '\nfrom sklearn.covariance import ledoit_wolf\nbench = application["task_supervised"]\nconfig = application["task_transfer"]\noutput_path = Path(str(config["stem"])+"_period_density_run_offset.npz")\ndata = np.load(str(bench["stem"])+"_context.npz",allow_pickle=False)\ntemporal = np.load(str(config["stem"])+"_context.npz",allow_pickle=False)\nparent = np.load(str(config["stem"])+"_period_density_ordered.npz",allow_pickle=False)\nnative = np.load(str(config["stem"])+"_final_controls.npz",allow_pickle=False)\nfeatures = np.concatenate([data["predictors"],temporal["acf_features"]],axis=1)\nrun_average = data["run_membership"]/data["run_membership"].sum(axis=1)[:,None]\nrun_features = run_average@features\nrun_qualified = data["run_membership"]@data["qualified"].astype(float)\nrun_reference = (data["run_membership"]@data["target"])/run_qualified\nbase_prediction = parent["estimate"][:,:,0]\nbase_run_prediction = base_prediction@run_average.T\nresidual = run_reference[None]-base_run_prediction\ntrain = data["outer_train_run"]\ntrain_n = train.sum(axis=1)\nweight = train/train_n[:,None]\nactive = native["lw_active"][1]\ndimension = active.sum(axis=1)\nmean_x = weight@run_features\nmean_residual = np.sum(weight*residual,axis=1)\ncentered = (run_features[None]-mean_x[:,None])*active[:,None]\ncovariance = np.einsum("gr,grd,gre->gde",weight,centered,centered,optimize=True)\ntrace = np.trace(covariance,axis1=-2,axis2=-1)\nsquare_sum = np.sum(covariance**2,axis=(1,2))\ndelta = (square_sum-trace**2/dimension)/dimension\nbeta = (np.sum(weight*np.sum(centered**2,axis=-1)**2,axis=-1)-square_sum)/(train_n*dimension)\nshrinkage = np.minimum(beta,delta)/delta\nmu = trace/dimension\nidentity = np.eye(features.shape[1])\noperator = (1.-shrinkage[:,None,None])*covariance\noperator += identity[None]*shrinkage[:,None,None]*mu[:,None,None]*active[:,None]\noperator += identity[None]*(~active[:,None])\ncross = np.einsum("gr,grd,gr->gd",weight,centered,residual,optimize=True)\ncoefficient = np.linalg.solve(operator,cross[:,:,None])[:,:,0]*(1.-shrinkage[:,None])\ncorrection = mean_residual[:,None]+np.einsum("grd,gd->gr",centered,coefficient,optimize=True)\nestimate = base_prediction+correction[:,data["run_index"]]\ncheck_covariance,check_shrinkage = ledoit_wolf(run_features[train[0]][:,active[0]])\nlibrary_covariance_check = np.max(abs(check_covariance-operator[0][active[0]][:,active[0]]))\nlibrary_shrinkage_check = abs(check_shrinkage-shrinkage[0])\nassert library_covariance_check<1e-8 and library_shrinkage_check<1e-10\nassert np.isfinite(estimate[data["outer_query"]]).all()\nwithin_run_check = np.max(abs((estimate-base_prediction)-\n    correction[:,data["run_index"]]))\nassert within_run_check<1e-10\nnp.savez_compressed(output_path,\n    methods=np.asarray(["task_period_density_run_offset_mean"]),estimate=estimate[:,:,None],\n    trace_id=data["trace_id"],coefficient=coefficient,predictor_mean=mean_x,\n    residual_mean=mean_residual,base_prediction=base_prediction,run_correction=correction,\n    shrinkage=shrinkage,active=active,training_experiments=train_n,training_run=train,\n    library_covariance_check=library_covariance_check,library_shrinkage_check=library_shrinkage_check,\n    within_run_check=within_run_check,\n    definition="density_period_mean_plus_run_mean_waveform_ACF_calibration_of_training_run_reference_residuals",\n    penalty="training_experiment_LedoitWolf_covariance_ridge_no_weight_tuning",\n    fit="same_original_29_outer_cases_only_eligible_training_experiments_no_new_validation")\nprint("DENSITY_RUN_OFFSET_FITTED",output_path,"library_checks",library_covariance_check,\n    library_shrinkage_check,"shrinkage",shrinkage.tolist(),flush=True)\nraise SystemExit(0)\n'
exec(compile({True:task_density_run_offset_stage,False:""}[args.stage=="task-period-density-run-offset"],__file__,"exec"))
task_density_acf_offset_stage = '\nfrom sklearn.covariance import ledoit_wolf\nbench = application["task_supervised"]\nconfig = application["task_transfer"]\noutput_path = Path(str(config["stem"])+"_period_density_acf_offset.npz")\ndata = np.load(str(bench["stem"])+"_context.npz",allow_pickle=False)\ntemporal = np.load(str(config["stem"])+"_context.npz",allow_pickle=False)\nparent = np.load(str(config["stem"])+"_period_density_ordered.npz",allow_pickle=False)\nfeatures = temporal["acf_features"]\nn_outer = len(data["outer_protocol"])\ntrain = data["case_train"][:n_outer]\ntrain_n = train.sum(axis=1)\nweight = train/train_n[:,None]\nmean_x = weight@features\ncentered = features[None]-mean_x[:,None]\ncovariance = np.einsum("gn,gnd,gne->gde",weight,centered,centered,optimize=True)\ndimension = features.shape[-1]\ntrace = np.trace(covariance,axis1=-2,axis2=-1)\nsquare_sum = np.sum(covariance**2,axis=(1,2))\ndelta = (square_sum-trace**2/dimension)/dimension\nbeta = (np.sum(weight*np.sum(centered**2,axis=-1)**2,axis=-1)-square_sum)/(train_n*dimension)\nshrinkage = np.minimum(beta,delta)/delta\noperator = (1.-shrinkage[:,None,None])*covariance\noperator += np.eye(dimension)[None]*shrinkage[:,None,None]*(trace/dimension)[:,None,None]\nbase_prediction = parent["estimate"][:,:,0]\nresidual = data["target"][None]-base_prediction\nresidual_mean = np.sum(weight*residual,axis=1)\ncross = np.einsum("gn,gnd,gn->gd",weight,centered,residual,optimize=True)\ncoefficient = np.linalg.solve(operator,cross[:,:,None])[:,:,0]*(1.-shrinkage[:,None])\ncorrection = residual_mean[:,None]+np.einsum("gnd,gd->gn",centered,coefficient,optimize=True)\nrun_average = data["run_membership"]/data["run_membership"].sum(axis=1)[:,None]\nrun_correction = correction@run_average.T\nindividual_estimate = base_prediction+correction\ncohort_estimate = base_prediction+run_correction[:,data["run_index"]]\nestimate = np.stack([individual_estimate,cohort_estimate],axis=-1)\ncheck_covariance,check_shrinkage = ledoit_wolf(features[train[0]])\nlibrary_covariance_check = np.max(abs(check_covariance-operator[0]))\nlibrary_shrinkage_check = abs(check_shrinkage-shrinkage[0])\nassert library_covariance_check<1e-8 and library_shrinkage_check<1e-10\nassert np.isfinite(estimate[data["outer_query"]]).all()\nnp.savez_compressed(output_path,\n    methods=np.asarray(["task_period_density_acf_offset_mean","task_period_density_acf_offset_cohort_mean"]),\n    estimate=estimate,trace_id=data["trace_id"],coefficient=coefficient,predictor_mean=mean_x,\n    residual_mean=residual_mean,base_prediction=base_prediction,correction=correction,run_correction=run_correction,\n    shrinkage=shrinkage,training_labels=train_n,training_mask=train,\n    library_covariance_check=library_covariance_check,library_shrinkage_check=library_shrinkage_check,\n    definition="density_offset_residual_regression_on_phase_invariant_own_and_peer_ACF",\n    penalty="training_record_LedoitWolf_covariance_ridge_no_weight_tuning",\n    fit="same_original_29_outer_cases_only_eligible_training_labels_no_new_validation")\nprint("DENSITY_ACF_OFFSET_FITTED",output_path,"library_checks",library_covariance_check,library_shrinkage_check,flush=True)\nraise SystemExit(0)\n'
exec(compile({True:task_density_acf_offset_stage,False:""}[args.stage=="task-period-density-acf-offset"],__file__,"exec"))
task_density_monotone_stage = '\nfrom sklearn.isotonic import isotonic_regression\nbench = application["task_supervised"]\nconfig = application["task_transfer"]\noutput_path = Path(str(config["stem"])+"_period_density_monotone.npz")\ndata = np.load(str(bench["stem"])+"_context.npz",allow_pickle=False)\nparent = np.load(str(config["stem"])+"_period_density_ordered.npz",allow_pickle=False)\nrun_average = data["run_membership"]/data["run_membership"].sum(axis=1)[:,None]\nrun_qualified = data["run_membership"]@data["qualified"].astype(float)\nrun_reference = (data["run_membership"]@data["target"])/run_qualified\nbase_prediction = parent["estimate"][:,:,0]\nbase_run_prediction = base_prediction@run_average.T\nresidual = run_reference[None]-base_run_prediction\ntrain = data["outer_train_run"]\ntrain_n = train.sum(axis=1)\nn_outer,n_run = train.shape\norder = np.argsort(np.where(train,base_run_prediction,np.inf),axis=1)\nposition = np.arange(n_run)\nsorted_x = np.take_along_axis(base_run_prediction,order,axis=1)\nsorted_residual = np.take_along_axis(residual,order,axis=1)\nsorted_eligible = position[None]<train_n[:,None]\nsorted_residual = np.where(sorted_eligible,sorted_residual,0.)\nprefix = np.pad(np.cumsum(sorted_residual,axis=1),((0,0),(1,0)))\ninterval_sum = prefix[:,None,1:]-prefix[:,:-1,None]\ninterval_n = position[None,:]-position[:,None]+1\nvalid_interval = (interval_n[None]>0)&(position[None,None]<train_n[:,None,None])\ninterval_mean = np.divide(interval_sum,interval_n[None],\n    out=np.full_like(interval_sum,np.inf),where=valid_interval)\nsuffix_minimum = np.minimum.accumulate(interval_mean[:,:,::-1],axis=-1)[:,:,::-1]\nfitted_residual = np.max(np.where(position[:,None]<=position[None,:],suffix_minimum,-np.inf),axis=1)\nfitted_residual = np.where(sorted_eligible,fitted_residual,0.)\nlibrary_fit = isotonic_regression(sorted_residual[0,:train_n[0]],increasing=True)\nlibrary_check = np.max(abs(library_fit-fitted_residual[0,:train_n[0]]))\nassert library_check<1e-10\nassert np.all(np.diff(fitted_residual,axis=1)[position[None,1:]<train_n[:,None]]>=-1e-10)\nsearch_x = np.where(sorted_eligible,sorted_x,np.inf)\nlower = np.sum(base_run_prediction[:,:,None]>=search_x[:,None,:],axis=-1)-1\nlower = np.maximum(np.minimum(lower,train_n[:,None]-1),0)\nupper = np.minimum(lower+1,train_n[:,None]-1)\nx_lower = np.take_along_axis(sorted_x,lower,axis=1)\nx_upper = np.take_along_axis(sorted_x,upper,axis=1)\nr_lower = np.take_along_axis(fitted_residual,lower,axis=1)\nr_upper = np.take_along_axis(fitted_residual,upper,axis=1)\nlast_x = sorted_x[np.arange(n_outer),train_n-1]\nquery_x = np.clip(base_run_prediction,sorted_x[:,0,None],last_x[:,None])\nfraction = np.divide(query_x-x_lower,x_upper-x_lower,out=np.zeros_like(query_x),where=x_upper>x_lower)\ncorrection = r_lower+fraction*(r_upper-r_lower)\nestimate = base_prediction+correction[:,data["run_index"]]\nrun_estimate = estimate@run_average.T\nquery_order = np.argsort(base_run_prediction,axis=1)\norder_check = np.min(np.diff(np.take_along_axis(run_estimate,query_order,axis=1),axis=1))\nassert order_check>-1e-10\nassert np.isfinite(estimate[data["outer_query"]]).all()\nsorted_weight = np.take_along_axis(np.broadcast_to(run_qualified,order.shape),order,axis=1)*sorted_eligible\nweighted_prefix = np.pad(np.cumsum(sorted_residual*sorted_weight,axis=1),((0,0),(1,0)))\nweight_prefix = np.pad(np.cumsum(sorted_weight,axis=1),((0,0),(1,0)))\nweighted_sum = weighted_prefix[:,None,1:]-weighted_prefix[:,:-1,None]\ninterval_weight = weight_prefix[:,None,1:]-weight_prefix[:,:-1,None]\nweighted_interval_mean = np.divide(weighted_sum,interval_weight,\n    out=np.full_like(weighted_sum,np.inf),where=valid_interval&(interval_weight>0.))\nweighted_suffix_minimum = np.minimum.accumulate(weighted_interval_mean[:,:,::-1],axis=-1)[:,:,::-1]\nweighted_fitted_residual = np.max(np.where(position[:,None]<=position[None,:],weighted_suffix_minimum,-np.inf),axis=1)\nweighted_fitted_residual = np.where(sorted_eligible,weighted_fitted_residual,0.)\nweighted_library_fit = isotonic_regression(sorted_residual[0,:train_n[0]],\n    sample_weight=sorted_weight[0,:train_n[0]],increasing=True)\nweighted_library_check = np.max(abs(weighted_library_fit-weighted_fitted_residual[0,:train_n[0]]))\nassert weighted_library_check<1e-10\nweighted_r_lower = np.take_along_axis(weighted_fitted_residual,lower,axis=1)\nweighted_r_upper = np.take_along_axis(weighted_fitted_residual,upper,axis=1)\nweighted_correction = weighted_r_lower+fraction*(weighted_r_upper-weighted_r_lower)\nweighted_estimate = base_prediction+weighted_correction[:,data["run_index"]]\nweighted_run_estimate = weighted_estimate@run_average.T\nweighted_order_check = np.min(np.diff(np.take_along_axis(weighted_run_estimate,query_order,axis=1),axis=1))\nassert weighted_order_check>-1e-10\nestimate = np.stack([estimate,weighted_estimate],axis=-1)\nnp.savez_compressed(output_path,\n    methods=np.asarray(["task_period_density_monotone_mean","task_period_density_monotone_precision_mean"]),estimate=estimate,\n    trace_id=data["trace_id"],training_run=train,training_experiments=train_n,\n    sorted_run_index=order,sorted_training_prediction=sorted_x,\n    fitted_training_residual=fitted_residual,run_correction=correction,\n    precision_fitted_training_residual=weighted_fitted_residual,precision_run_correction=weighted_correction,\n    precision_weight=sorted_weight,precision_library_check=weighted_library_check,precision_order_check=weighted_order_check,\n    base_prediction=base_prediction,library_check=library_check,run_order_check=order_check,\n    definition="add_monotone_training_run_reference_residual_to_density_mean_preserving_within_run_differences",\n    fit="equal_experiment_or_reference_count_weighted_isotonic_residual_interpolation",\n    property="calibrated_run_period_equals_input_run_period_plus_nondecreasing_residual",\n    information="same_original_29_outer_cases_only_eligible_training_experiments_no_new_validation")\nprint("DENSITY_MONOTONE_FITTED",output_path,"library_check",library_check,\n    "run_order_min_difference",order_check,flush=True)\nraise SystemExit(0)\n'
exec(compile({True:task_density_monotone_stage,False:""}[args.stage=="task-period-density-monotone"],__file__,"exec"))
task_density_quadrature_stage = '\nimport torch\nfrom scipy.optimize import minimize\nsolver_config = {"maxiter":800,"ftol":1e-11,"gtol":1e-6,"maxls":30,"progress_every":25}\nbench = application["task_supervised"]\nconfig = application["task_transfer"]\noutput_path = Path(str(config["stem"])+"_period_density_quadrature.npz")\ndata = np.load(str(bench["stem"])+"_context.npz",allow_pickle=False)\ncache = np.load(str(config["stem"])+"_period_profile_context.npz",allow_pickle=False)\nparent = np.load(str(config["stem"])+"_period_density_ordered.npz",allow_pickle=False)\ntorch.set_num_threads(int(os.environ["PERIOD_THREADS"]))\nperiod = cache["period"]\noriginal_base = cache["base_features"]\ntime = data["time"]\ncount = data["mask"].sum(axis=1)\nlengths = np.unique(count)\nlayout = pd.Index(lengths).get_indexer(count)\nlayout_mask = np.arange(len(time))[None]<lengths[:,None]\ncentered_time = (time[None]-np.sum(layout_mask*time[None],axis=1)[:,None]/lengths[:,None])*layout_mask\nbase = np.stack([layout_mask/np.sqrt(lengths[:,None]),\n    centered_time/np.sqrt(np.sum(centered_time**2,axis=1))[:,None]],axis=-1)\nangle = 2*np.pi*time[None]/period[:,None]\nharmonic = np.stack([np.cos(angle),np.sin(angle),np.cos(2*angle),np.sin(2*angle)],axis=-1)\nbase_cross = np.einsum("lti,ptj->lpij",base,harmonic,optimize=True)\ngram = np.einsum("lt,pti,ptj->lpij",layout_mask.astype(float),harmonic,harmonic,optimize=True)\ngram -= base_cross.swapaxes(-1,-2)@base_cross\nrhs_own = np.einsum("pti,nt->npi",harmonic,data["mixed"],optimize=True)\nrhs_peer = np.einsum("pti,nt->npi",harmonic,data["peer"],optimize=True)\nrhs = np.stack([rhs_own,rhs_peer],axis=-1)\ncoefficient_h2 = np.linalg.solve(gram[layout],rhs)\ncoefficient_h1 = np.linalg.solve(gram[layout,:,:2,:2],rhs[:,:,:2])\npower_h2 = np.sum(rhs*coefficient_h2,axis=2)/count[:,None,None]\npower_h1 = np.sum(rhs[:,:,:2]*coefficient_h1,axis=2)/count[:,None,None]\noriented_area = coefficient_h1[:,:,0,0]*coefficient_h1[:,:,1,1]-coefficient_h1[:,:,1,0]*coefficient_h1[:,:,0,1]\npower_norm = count[:,None]*np.sqrt(power_h1[:,:,0]*power_h1[:,:,1])\nquadrature = np.divide(oriented_area*np.sqrt(np.linalg.det(gram[:,:,:2,:2]))[layout],power_norm,\n    out=np.zeros_like(oriented_area),where=power_norm>np.finfo(float).eps)\nquadrature = np.clip(quadrature,-1.,1.)\nphase_identity_check = np.max(abs(original_base[:,:,10]**2+quadrature**2-1.))\nassert phase_identity_check<1e-8\nbase_features = np.concatenate([original_base,quadrature[:,:,None]],axis=-1)\nleft,right = np.triu_indices(base_features.shape[-1])\nfeatures = np.concatenate([base_features,base_features[:,:,left]*base_features[:,:,right]],axis=-1)\nn_outer = len(data["outer_protocol"])\ntrain = data["case_train"][:n_outer]\ntrain_n = train.sum(axis=1)\nweight = train/train_n[:,None]\ntarget_mean = weight@data["target"]\ntarget_sd = np.sqrt(weight@(data["target"]**2)-target_mean**2)\nassert target_sd.min()>0.\ngrid_step = float(period[1]-period[0])\nteacher = np.maximum(1.-abs(period[None]-data["target"][:,None])/grid_step,0.)\nteacher_cdf = np.cumsum(teacher,axis=-1)[:,:-1]\ncdf_constant = grid_step*np.sum(teacher_cdf*(1.-teacher_cdf),axis=-1)\ncheck_record = np.flatnonzero(train[0])[0]\ncheck_mass = parent["posterior"][0,check_record]\ncheck_crps_cdf = grid_step*np.sum((np.cumsum(check_mass)[:-1]-teacher_cdf[check_record])**2)+cdf_constant[check_record]\ncheck_crps_energy = check_mass@abs(period-data["target"][check_record])-.5*check_mass@abs(period[:,None]-period[None,:])@check_mass\ncrps_check = abs(check_crps_cdf-check_crps_energy)\nassert crps_check<1e-9\nfeature_mean = weight@features.mean(axis=1)\nscale = np.sqrt(np.maximum(weight@np.mean(features**2,axis=1)-feature_mean**2,0.))\nscale = np.where(scale>0.,scale,1.)\nold_slots = np.concatenate([np.arange(original_base.shape[-1]),\n    base_features.shape[-1]+np.flatnonzero((left<original_base.shape[-1])&(right<original_base.shape[-1]))])\nassert np.max(abs(scale[:,old_slots]-parent["feature_scale"]))<1e-8\ntensor_features = torch.as_tensor(features,dtype=torch.float64)\ntensor_scale = torch.as_tensor(scale,dtype=torch.float64)\ntensor_teacher = torch.as_tensor(teacher,dtype=torch.float64)\ntensor_cdf = torch.as_tensor(teacher_cdf,dtype=torch.float64)\ntensor_constant = torch.as_tensor(cdf_constant,dtype=torch.float64)\ntensor_weight = torch.as_tensor(weight,dtype=torch.float64)\ntensor_n = torch.as_tensor(train_n,dtype=torch.float64)\ntensor_sd = torch.as_tensor(target_sd,dtype=torch.float64)\nparameter_shape = (n_outer,features.shape[-1])\nlogit = lambda parameter:torch.einsum("npd,gd->gnp",tensor_features,\n    parameter.reshape(parameter_shape)/tensor_scale)\nlosses = lambda parameter:(\n    coefficients:=parameter.reshape(parameter_shape),\n    score:=logit(parameter),\n    individual:=-(torch.log_softmax(score,dim=-1)*tensor_teacher[None]*tensor_weight[:,:,None]).sum(dim=(-1,-2)),\n    cdf:=torch.softmax(score,dim=-1).cumsum(dim=-1)[:,:,:-1],\n    ordered:=((((cdf-tensor_cdf[None]).square().sum(dim=-1)*grid_step+tensor_constant[None])*tensor_weight).sum(dim=-1))/tensor_sd,\n    prior:=coefficients.square().sum(dim=-1)/(2.*tensor_n),\n    torch.stack([individual,ordered,prior],dim=-1))[-1]\nobjective = lambda parameter:losses(parameter).sum(dim=-1).mean()\ngradient_value = torch.func.grad_and_value(objective)\nto_scipy = lambda gradient,value:(value.detach().item(),gradient.detach().numpy())\nscipy_objective = lambda parameter:to_scipy(*gradient_value(torch.from_numpy(parameter)))\ninitial = np.zeros(parameter_shape)\ninitial[:,old_slots] = parent["coefficient"]*parent["feature_scale"]\ninitial = initial.ravel()\nwarm_start_check = np.max(abs(torch.softmax(logit(torch.from_numpy(initial)),dim=-1).detach().numpy()-parent["posterior"]))\nassert warm_start_check<1e-9\ninitial_value,initial_gradient = scipy_objective(initial)\nprobe = np.zeros_like(initial)\nprobe[original_base.shape[-1]] = 1e-4\nfinite_difference = (float(objective(torch.from_numpy(initial+probe)))-\n    float(objective(torch.from_numpy(initial-probe))))/(2e-4)\ngradient_check = abs(finite_difference-initial_gradient[original_base.shape[-1]])\nassert gradient_check<1e-7\nhistory = [[0,initial_value]]\nprint("QUADRATURE_DENSITY_SETUP",n_outer,"cases","CRPS_identity_check",crps_check,\n    "initial_components",losses(torch.from_numpy(initial)).mean(dim=0).detach().numpy().tolist(),flush=True)\nresult = minimize(scipy_objective,initial,jac=True,method="L-BFGS-B",\n    callback=lambda intermediate_result:(history.append([len(history),float(intermediate_result.fun)]),\n        len(history)%solver_config["progress_every"]==0 and print("QUADRATURE_DENSITY_PROGRESS",\n        len(history)-1,float(intermediate_result.fun),flush=True)),\n    options={"maxiter":solver_config["maxiter"],"ftol":solver_config["ftol"],"gtol":solver_config["gtol"],"maxls":solver_config["maxls"]})\nparameters = torch.as_tensor(result.x,dtype=torch.float64)\nscore = logit(parameters).detach().numpy()\nmass = torch.softmax(torch.as_tensor(score),dim=-1).numpy()\nmode = period[score.argmax(axis=-1)]\nmean = mass@period\nmedian = period[(np.cumsum(mass,axis=-1)>=.5).argmax(axis=-1)]\nestimate = np.stack([mean,mode,median],axis=-1)\nassert np.isfinite(estimate[data["outer_query"]]).all()\nnp.savez_compressed(output_path,\n    methods=np.asarray(["task_period_density_quadrature_mean","task_period_density_quadrature_mode","task_period_density_quadrature_median"]),\n    estimate=estimate,trace_id=data["trace_id"],period=period,\n    coefficient=result.x.reshape(parameter_shape)/scale,feature_scale=scale,\n    posterior=mass,objective_history=np.asarray(history),\n    gradient_check=gradient_check,crps_identity_check=crps_check,\n    phase_identity_check=phase_identity_check,warm_start_check=warm_start_check,quadrature=quadrature,\n    final_objective=result.fun,optimizer_success=result.success,optimizer_message=str(result.message),\n    optimizer_iterations=result.nit,gradient_max=np.max(abs(result.jac)),\n    loss_components=losses(parameters).detach().numpy(),target_sd=target_sd,training_labels=train_n,\n    definition="13_base_104_total_features_including_oriented_peer_relative_phase_same_logloss_CRPS",\n    fit="unit_weight_sum_of_two_proper_scores_with_same_unit_Gaussian_prior",\n    warm_start="converged_same_fold_ordered_density_no_new_start_or_seed",\n    reference="Gneiting_Raftery_2007_DOI_10.1198/016214506000001437")\nprint("QUADRATURE_DENSITY_FITTED",str(result.message),"iterations",result.nit,\n    "components",losses(parameters).mean(dim=0).detach().numpy().tolist(),\n    "max_gradient",np.max(abs(result.jac)),flush=True)\nraise SystemExit(0)\n'
exec(compile({True:task_density_quadrature_stage,False:""}[args.stage=="task-period-density-quadrature"],__file__,"exec"))
task_density_quadrature_fixed_stage = '\nimport torch\nfrom scipy.optimize import minimize\nsolver_config = {"maxiter":800,"ftol":1e-11,"gtol":1e-6,"maxls":30,"progress_every":25}\nbench = application["task_supervised"]\nconfig = application["task_transfer"]\noutput_path = Path(str(config["stem"])+"_period_density_quadrature_fixed.npz")\ndata = np.load(str(bench["stem"])+"_context.npz",allow_pickle=False)\ncache = np.load(str(config["stem"])+"_period_profile_context.npz",allow_pickle=False)\nparent = np.load(str(config["stem"])+"_period_density_ordered.npz",allow_pickle=False)\ntorch.set_num_threads(int(os.environ["PERIOD_THREADS"]))\nperiod = cache["period"]\noriginal_base = cache["base_features"]\ntime = data["time"]\ncount = data["mask"].sum(axis=1)\nlengths = np.unique(count)\nlayout = pd.Index(lengths).get_indexer(count)\nlayout_mask = np.arange(len(time))[None]<lengths[:,None]\ncentered_time = (time[None]-np.sum(layout_mask*time[None],axis=1)[:,None]/lengths[:,None])*layout_mask\nbase = np.stack([layout_mask/np.sqrt(lengths[:,None]),\n    centered_time/np.sqrt(np.sum(centered_time**2,axis=1))[:,None]],axis=-1)\nangle = 2*np.pi*time[None]/period[:,None]\nharmonic = np.stack([np.cos(angle),np.sin(angle),np.cos(2*angle),np.sin(2*angle)],axis=-1)\nbase_cross = np.einsum("lti,ptj->lpij",base,harmonic,optimize=True)\ngram = np.einsum("lt,pti,ptj->lpij",layout_mask.astype(float),harmonic,harmonic,optimize=True)\ngram -= base_cross.swapaxes(-1,-2)@base_cross\nrhs_own = np.einsum("pti,nt->npi",harmonic,data["mixed"],optimize=True)\nrhs_peer = np.einsum("pti,nt->npi",harmonic,data["peer"],optimize=True)\nrhs = np.stack([rhs_own,rhs_peer],axis=-1)\ncoefficient_h2 = np.linalg.solve(gram[layout],rhs)\ncoefficient_h1 = np.linalg.solve(gram[layout,:,:2,:2],rhs[:,:,:2])\npower_h2 = np.sum(rhs*coefficient_h2,axis=2)/count[:,None,None]\npower_h1 = np.sum(rhs[:,:,:2]*coefficient_h1,axis=2)/count[:,None,None]\noriented_area = coefficient_h1[:,:,0,0]*coefficient_h1[:,:,1,1]-coefficient_h1[:,:,1,0]*coefficient_h1[:,:,0,1]\npower_norm = count[:,None]*np.sqrt(power_h1[:,:,0]*power_h1[:,:,1])\nquadrature = np.divide(oriented_area*np.sqrt(np.linalg.det(gram[:,:,:2,:2]))[layout],power_norm,\n    out=np.zeros_like(oriented_area),where=power_norm>np.finfo(float).eps)\nquadrature = np.clip(quadrature,-1.,1.)\nphase_identity_check = np.max(abs(original_base[:,:,10]**2+quadrature**2-1.))\nassert phase_identity_check<1e-8\nbase_features = np.concatenate([original_base,quadrature[:,:,None]],axis=-1)\nleft,right = np.triu_indices(base_features.shape[-1])\nfeatures = np.concatenate([base_features,base_features[:,:,left]*base_features[:,:,right]],axis=-1)\nn_outer = len(data["outer_protocol"])\ntrain = data["case_train"][:n_outer]\ntrain_n = train.sum(axis=1)\nweight = train/train_n[:,None]\ntarget_mean = weight@data["target"]\ntarget_sd = np.sqrt(weight@(data["target"]**2)-target_mean**2)\nassert target_sd.min()>0.\ngrid_step = float(period[1]-period[0])\nteacher = np.maximum(1.-abs(period[None]-data["target"][:,None])/grid_step,0.)\nteacher_cdf = np.cumsum(teacher,axis=-1)[:,:-1]\ncdf_constant = grid_step*np.sum(teacher_cdf*(1.-teacher_cdf),axis=-1)\ncheck_record = np.flatnonzero(train[0])[0]\ncheck_mass = parent["posterior"][0,check_record]\ncheck_crps_cdf = grid_step*np.sum((np.cumsum(check_mass)[:-1]-teacher_cdf[check_record])**2)+cdf_constant[check_record]\ncheck_crps_energy = check_mass@abs(period-data["target"][check_record])-.5*check_mass@abs(period[:,None]-period[None,:])@check_mass\ncrps_check = abs(check_crps_cdf-check_crps_energy)\nassert crps_check<1e-9\nfeature_mean = weight@features.mean(axis=1)\nscale = np.sqrt(np.maximum(weight@np.mean(features**2,axis=1)-feature_mean**2,0.))\nscale = np.where(scale>0.,scale,1.)\nold_slots = np.concatenate([np.arange(original_base.shape[-1]),\n    base_features.shape[-1]+np.flatnonzero((left<original_base.shape[-1])&(right<original_base.shape[-1]))])\nassert np.max(abs(scale[:,old_slots]-parent["feature_scale"]))<1e-8\nnew_slots = np.setdiff1d(np.arange(features.shape[-1]),old_slots)\nfixed_score = np.einsum("npd,gd->gnp",features[:,:,old_slots],parent["coefficient"],optimize=True)\ntensor_fixed_score = torch.as_tensor(fixed_score,dtype=torch.float64)\ntensor_features = torch.as_tensor(features[:,:,new_slots],dtype=torch.float64)\ntensor_scale = torch.as_tensor(scale[:,new_slots],dtype=torch.float64)\ntensor_teacher = torch.as_tensor(teacher,dtype=torch.float64)\ntensor_cdf = torch.as_tensor(teacher_cdf,dtype=torch.float64)\ntensor_constant = torch.as_tensor(cdf_constant,dtype=torch.float64)\ntensor_weight = torch.as_tensor(weight,dtype=torch.float64)\ntensor_n = torch.as_tensor(train_n,dtype=torch.float64)\ntensor_sd = torch.as_tensor(target_sd,dtype=torch.float64)\nparameter_shape = (n_outer,len(new_slots))\nlogit = lambda parameter:tensor_fixed_score+torch.einsum("npd,gd->gnp",tensor_features,\n    parameter.reshape(parameter_shape)/tensor_scale)\nlosses = lambda parameter:(\n    coefficients:=parameter.reshape(parameter_shape),\n    score:=logit(parameter),\n    individual:=-(torch.log_softmax(score,dim=-1)*tensor_teacher[None]*tensor_weight[:,:,None]).sum(dim=(-1,-2)),\n    cdf:=torch.softmax(score,dim=-1).cumsum(dim=-1)[:,:,:-1],\n    ordered:=((((cdf-tensor_cdf[None]).square().sum(dim=-1)*grid_step+tensor_constant[None])*tensor_weight).sum(dim=-1))/tensor_sd,\n    prior:=coefficients.square().sum(dim=-1)/(2.*tensor_n),\n    torch.stack([individual,ordered,prior],dim=-1))[-1]\nobjective = lambda parameter:losses(parameter).sum(dim=-1).mean()\ngradient_value = torch.func.grad_and_value(objective)\nto_scipy = lambda gradient,value:(value.detach().item(),gradient.detach().numpy())\nscipy_objective = lambda parameter:to_scipy(*gradient_value(torch.from_numpy(parameter)))\ninitial = np.zeros(parameter_shape)\ninitial = initial.ravel()\nwarm_start_check = np.max(abs(torch.softmax(logit(torch.from_numpy(initial)),dim=-1).detach().numpy()-parent["posterior"]))\nassert warm_start_check<1e-9\ninitial_value,initial_gradient = scipy_objective(initial)\nprobe = np.zeros_like(initial)\nprobe[original_base.shape[-1]] = 1e-4\nfinite_difference = (float(objective(torch.from_numpy(initial+probe)))-\n    float(objective(torch.from_numpy(initial-probe))))/(2e-4)\ngradient_check = abs(finite_difference-initial_gradient[original_base.shape[-1]])\nassert gradient_check<1e-7\nhistory = [[0,initial_value]]\nprint("FIXED_QUADRATURE_DENSITY_SETUP",n_outer,"cases","CRPS_identity_check",crps_check,\n    "initial_components",losses(torch.from_numpy(initial)).mean(dim=0).detach().numpy().tolist(),flush=True)\nresult = minimize(scipy_objective,initial,jac=True,method="L-BFGS-B",\n    callback=lambda intermediate_result:(history.append([len(history),float(intermediate_result.fun)]),\n        len(history)%solver_config["progress_every"]==0 and print("FIXED_QUADRATURE_DENSITY_PROGRESS",\n        len(history)-1,float(intermediate_result.fun),flush=True)),\n    options={"maxiter":solver_config["maxiter"],"ftol":solver_config["ftol"],"gtol":solver_config["gtol"],"maxls":solver_config["maxls"]})\nparameters = torch.as_tensor(result.x,dtype=torch.float64)\nscore = logit(parameters).detach().numpy()\nmass = torch.softmax(torch.as_tensor(score),dim=-1).numpy()\nmode = period[score.argmax(axis=-1)]\nmean = mass@period\nmedian = period[(np.cumsum(mass,axis=-1)>=.5).argmax(axis=-1)]\nestimate = np.stack([mean,mode,median],axis=-1)\nassert np.isfinite(estimate[data["outer_query"]]).all()\nfull_coefficient = np.zeros((n_outer,features.shape[-1]))\nfull_coefficient[:,old_slots] = parent["coefficient"]\nfull_coefficient[:,new_slots] = result.x.reshape(parameter_shape)/scale[:,new_slots]\nassert np.array_equal(full_coefficient[:,old_slots],parent["coefficient"])\nnp.savez_compressed(output_path,\n    methods=np.asarray(["task_period_density_quadrature_fixed_mean","task_period_density_quadrature_fixed_mode","task_period_density_quadrature_fixed_median"]),\n    estimate=estimate,trace_id=data["trace_id"],period=period,\n    coefficient=full_coefficient,feature_scale=scale,\n    posterior=mass,objective_history=np.asarray(history),\n    gradient_check=gradient_check,crps_identity_check=crps_check,\n    phase_identity_check=phase_identity_check,warm_start_check=warm_start_check,quadrature=quadrature,\n    final_objective=result.fun,optimizer_success=result.success,optimizer_message=str(result.message),\n    optimizer_iterations=result.nit,gradient_max=np.max(abs(result.jac)),\n    loss_components=losses(parameters).detach().numpy(),target_sd=target_sd,training_labels=train_n,\n    definition="fixed_original_90_score_coefficients_plus_14_oriented_phase_features_logloss_CRPS",\n    fit="unit_weight_sum_of_two_proper_scores_with_same_unit_Gaussian_prior",\n    warm_start="converged_same_fold_ordered_density_no_new_start_or_seed",\n    reference="Gneiting_Raftery_2007_DOI_10.1198/016214506000001437")\nprint("FIXED_QUADRATURE_DENSITY_FITTED",str(result.message),"iterations",result.nit,\n    "components",losses(parameters).mean(dim=0).detach().numpy().tolist(),\n    "max_gradient",np.max(abs(result.jac)),flush=True)\nraise SystemExit(0)\n'
task_density_quadrature_monotone_stage = '\nfrom sklearn.isotonic import isotonic_regression\nbench = application["task_supervised"]\nconfig = application["task_transfer"]\noutput_path = Path(str(config["stem"])+"_period_density_quadrature_monotone.npz")\ndata = np.load(str(bench["stem"])+"_context.npz",allow_pickle=False)\nparent = np.load(str(config["stem"])+"_period_density_quadrature.npz",allow_pickle=False)\nrun_average = data["run_membership"]/data["run_membership"].sum(axis=1)[:,None]\nrun_qualified = data["run_membership"]@data["qualified"].astype(float)\nrun_reference = (data["run_membership"]@data["target"])/run_qualified\nbase_prediction = parent["estimate"][:,:,0]\nbase_run_prediction = base_prediction@run_average.T\nresidual = run_reference[None]-base_run_prediction\ntrain = data["outer_train_run"]\ntrain_n = train.sum(axis=1)\nn_outer,n_run = train.shape\norder = np.argsort(np.where(train,base_run_prediction,np.inf),axis=1)\nposition = np.arange(n_run)\nsorted_x = np.take_along_axis(base_run_prediction,order,axis=1)\nsorted_residual = np.take_along_axis(residual,order,axis=1)\nsorted_eligible = position[None]<train_n[:,None]\nsorted_residual = np.where(sorted_eligible,sorted_residual,0.)\nprefix = np.pad(np.cumsum(sorted_residual,axis=1),((0,0),(1,0)))\ninterval_sum = prefix[:,None,1:]-prefix[:,:-1,None]\ninterval_n = position[None,:]-position[:,None]+1\nvalid_interval = (interval_n[None]>0)&(position[None,None]<train_n[:,None,None])\ninterval_mean = np.divide(interval_sum,interval_n[None],\n    out=np.full_like(interval_sum,np.inf),where=valid_interval)\nsuffix_minimum = np.minimum.accumulate(interval_mean[:,:,::-1],axis=-1)[:,:,::-1]\nfitted_residual = np.max(np.where(position[:,None]<=position[None,:],suffix_minimum,-np.inf),axis=1)\nfitted_residual = np.where(sorted_eligible,fitted_residual,0.)\nlibrary_fit = isotonic_regression(sorted_residual[0,:train_n[0]],increasing=True)\nlibrary_check = np.max(abs(library_fit-fitted_residual[0,:train_n[0]]))\nassert library_check<1e-10\nassert np.all(np.diff(fitted_residual,axis=1)[position[None,1:]<train_n[:,None]]>=-1e-10)\nsearch_x = np.where(sorted_eligible,sorted_x,np.inf)\nlower = np.sum(base_run_prediction[:,:,None]>=search_x[:,None,:],axis=-1)-1\nlower = np.maximum(np.minimum(lower,train_n[:,None]-1),0)\nupper = np.minimum(lower+1,train_n[:,None]-1)\nx_lower = np.take_along_axis(sorted_x,lower,axis=1)\nx_upper = np.take_along_axis(sorted_x,upper,axis=1)\nr_lower = np.take_along_axis(fitted_residual,lower,axis=1)\nr_upper = np.take_along_axis(fitted_residual,upper,axis=1)\nlast_x = sorted_x[np.arange(n_outer),train_n-1]\nquery_x = np.clip(base_run_prediction,sorted_x[:,0,None],last_x[:,None])\nfraction = np.divide(query_x-x_lower,x_upper-x_lower,out=np.zeros_like(query_x),where=x_upper>x_lower)\ncorrection = r_lower+fraction*(r_upper-r_lower)\nestimate = base_prediction+correction[:,data["run_index"]]\nrun_estimate = estimate@run_average.T\nquery_order = np.argsort(base_run_prediction,axis=1)\norder_check = np.min(np.diff(np.take_along_axis(run_estimate,query_order,axis=1),axis=1))\nassert order_check>-1e-10\nassert np.isfinite(estimate[data["outer_query"]]).all()\nsorted_weight = np.take_along_axis(np.broadcast_to(run_qualified,order.shape),order,axis=1)*sorted_eligible\nweighted_prefix = np.pad(np.cumsum(sorted_residual*sorted_weight,axis=1),((0,0),(1,0)))\nweight_prefix = np.pad(np.cumsum(sorted_weight,axis=1),((0,0),(1,0)))\nweighted_sum = weighted_prefix[:,None,1:]-weighted_prefix[:,:-1,None]\ninterval_weight = weight_prefix[:,None,1:]-weight_prefix[:,:-1,None]\nweighted_interval_mean = np.divide(weighted_sum,interval_weight,\n    out=np.full_like(weighted_sum,np.inf),where=valid_interval&(interval_weight>0.))\nweighted_suffix_minimum = np.minimum.accumulate(weighted_interval_mean[:,:,::-1],axis=-1)[:,:,::-1]\nweighted_fitted_residual = np.max(np.where(position[:,None]<=position[None,:],weighted_suffix_minimum,-np.inf),axis=1)\nweighted_fitted_residual = np.where(sorted_eligible,weighted_fitted_residual,0.)\nweighted_library_fit = isotonic_regression(sorted_residual[0,:train_n[0]],\n    sample_weight=sorted_weight[0,:train_n[0]],increasing=True)\nweighted_library_check = np.max(abs(weighted_library_fit-weighted_fitted_residual[0,:train_n[0]]))\nassert weighted_library_check<1e-10\nweighted_r_lower = np.take_along_axis(weighted_fitted_residual,lower,axis=1)\nweighted_r_upper = np.take_along_axis(weighted_fitted_residual,upper,axis=1)\nweighted_correction = weighted_r_lower+fraction*(weighted_r_upper-weighted_r_lower)\nweighted_estimate = base_prediction+weighted_correction[:,data["run_index"]]\nweighted_run_estimate = weighted_estimate@run_average.T\nweighted_order_check = np.min(np.diff(np.take_along_axis(weighted_run_estimate,query_order,axis=1),axis=1))\nassert weighted_order_check>-1e-10\nestimate = np.stack([estimate,weighted_estimate],axis=-1)\nnp.savez_compressed(output_path,\n    methods=np.asarray(["task_period_density_quadrature_monotone_mean","task_period_density_quadrature_monotone_precision_mean"]),estimate=estimate,\n    trace_id=data["trace_id"],training_run=train,training_experiments=train_n,\n    sorted_run_index=order,sorted_training_prediction=sorted_x,\n    fitted_training_residual=fitted_residual,run_correction=correction,\n    precision_fitted_training_residual=weighted_fitted_residual,precision_run_correction=weighted_correction,\n    precision_weight=sorted_weight,precision_library_check=weighted_library_check,precision_order_check=weighted_order_check,\n    base_prediction=base_prediction,library_check=library_check,run_order_check=order_check,\n    definition="add_monotone_training_run_reference_residual_to_density_mean_preserving_within_run_differences",\n    fit="equal_experiment_or_reference_count_weighted_isotonic_residual_interpolation",\n    property="calibrated_run_period_equals_input_run_period_plus_nondecreasing_residual",\n    information="same_original_29_outer_cases_only_eligible_training_experiments_no_new_validation")\nprint("QUADRATURE_MONOTONE_FITTED",output_path,"library_check",library_check,\n    "run_order_min_difference",order_check,flush=True)\nraise SystemExit(0)\n'
