task_density_source_blocks_stage = '\nimport torch\nfrom scipy.optimize import minimize\nfrom sklearn.isotonic import isotonic_regression\nsolver_config = {"maxiter":900,"ftol":1e-11,"gtol":1e-6,"maxls":30,"progress_every":25}\nbench = application["task_supervised"]\nconfig = application["task_transfer"]\noutput_path = Path(str(config["stem"])+"_period_density_source_blocks.npz")\ndata = np.load(str(bench["stem"])+"_context.npz",allow_pickle=False)\ncache = np.load(str(config["stem"])+"_period_profile_context.npz",allow_pickle=False)\nparent = np.load(str(config["stem"])+"_period_density_quadrature_fixed.npz",allow_pickle=False)\ntorch.set_num_threads(int(os.environ["PERIOD_THREADS"]))\nperiod = cache["period"]\nbase_features = np.concatenate([cache["base_features"],parent["quadrature"][:,:,None]],axis=-1)\nleft,right = np.triu_indices(base_features.shape[-1])\nfeatures = np.concatenate([base_features,base_features[:,:,left]*base_features[:,:,right]],axis=-1)\nn_outer = len(data["outer_protocol"])\ntrain = data["case_train"][:n_outer]\ntrain_n = train.sum(axis=-1)\nweight = train/train_n[:,None]\ngrid_step = float(period[1]-period[0])\nteacher = np.maximum(1.-abs(period[None]-data["target"][:,None])/grid_step,0.)\nsource_index = cache["base_features"][:,:,[0,4]].argmax(axis=1)\nsource_negative = teacher[np.arange(len(data["trace_id"]))[:,None],source_index]==0.\nteacher_cdf = np.cumsum(teacher,axis=-1)[:,:-1]\ncdf_constant = grid_step*np.sum(teacher_cdf*(1.-teacher_cdf),axis=-1)\nrival_mask = np.stack([source_negative,source_negative,source_negative])\nphase_term = np.concatenate([np.arange(base_features.shape[-1])==base_features.shape[-1]-1,\n    (left==base_features.shape[-1]-1)|(right==base_features.shape[-1]-1)])\nactive_terms = np.stack([phase_term,phase_term,~phase_term])\nassert np.array_equal(active_terms.sum(axis=-1),np.asarray([14,14,90]))\nn_variant = len(active_terms)\n\ntensor_features = torch.as_tensor(features,dtype=torch.float64)\ntensor_scale = torch.as_tensor(parent["feature_scale"],dtype=torch.float64)\ntensor_parent_coefficient = torch.as_tensor(parent["coefficient"],dtype=torch.float64)\ntensor_parent_mass = torch.as_tensor(parent["posterior"],dtype=torch.float64)\ntensor_parent_log = torch.log(tensor_parent_mass.clamp_min(torch.finfo(torch.float64).tiny))\ntensor_target_feature = torch.as_tensor(np.einsum("np,npd->nd",teacher,features,optimize=True),dtype=torch.float64)\ntensor_source_feature = torch.as_tensor(features[np.arange(len(features))[:,None],source_index],dtype=torch.float64)\ntensor_source_negative = torch.as_tensor(source_negative,dtype=torch.float64)\ntensor_rival_mask = torch.as_tensor(rival_mask,dtype=torch.float64)\ntensor_sd = torch.as_tensor(parent["target_sd"],dtype=torch.float64)\ntensor_active = torch.as_tensor(active_terms[:,None],dtype=torch.float64)\ntensor_importance = 1.\ntensor_teacher = torch.as_tensor(teacher,dtype=torch.float64)\ntensor_cdf = torch.as_tensor(teacher_cdf,dtype=torch.float64)\ntensor_constant = torch.as_tensor(cdf_constant,dtype=torch.float64)\ntensor_weight = torch.as_tensor(weight,dtype=torch.float64)\ntensor_n = torch.as_tensor(train_n,dtype=torch.float64)\nparameter_shape = (n_variant,n_outer,features.shape[-1])\ncoefficient = lambda parameter:tensor_parent_coefficient[None]+parameter.reshape(parameter_shape)*tensor_active/tensor_scale[None]\nlogit = lambda parameter:torch.einsum("npd,mgd->mgnp",tensor_features,coefficient(parameter))\nlosses = lambda parameter:(\n    delta:=parameter.reshape(parameter_shape),\n    coef:=coefficient(parameter),\n    score:=logit(parameter),\n    log_mass:=torch.log_softmax(score,dim=-1),\n    positive:=torch.einsum("nd,mgd->mgn",tensor_target_feature,coef),\n    source_score:=torch.einsum("nkd,mgd->mgnk",tensor_source_feature,coef),\n    ranking:=((torch.nn.functional.softplus(source_score-positive[:,:,:,None])*\n        tensor_rival_mask[:,None]*tensor_importance).sum(dim=-1)/\n        tensor_rival_mask.sum(dim=-1).clamp_min(1.)[:,None]*tensor_weight[None]).sum(dim=-1),\n    kl:=((tensor_parent_mass[None]*(tensor_parent_log[None]-log_mass)).sum(dim=-1)*tensor_weight[None]).sum(dim=-1),\n    individual:=-(log_mass[1]*tensor_teacher[None]*tensor_weight[:,:,None]).sum(dim=(-1,-2)),\n    cdf:=torch.exp(log_mass[1]).cumsum(dim=-1)[:,:,:-1],\n    ordered:=((((cdf-tensor_cdf[None]).square().sum(dim=-1)*grid_step+\n        tensor_constant[None])*tensor_weight).sum(dim=-1))/tensor_sd,\n    preservation:=torch.stack([kl[0],individual+ordered,kl[2]]),\n    prior:=delta.square().sum(dim=-1)/(2.*tensor_n[None]),\n    torch.stack([ranking,preservation,prior],dim=-1))[-1]\nobjective = lambda parameter:losses(parameter).sum(dim=-1).mean()\ngradient_value = torch.func.grad_and_value(objective)\nto_scipy = lambda gradient,value:(value.detach().item(),gradient.detach().numpy())\nscipy_objective = lambda parameter:to_scipy(*gradient_value(torch.from_numpy(parameter)))\ninitial = np.zeros(parameter_shape).ravel()\nwarm_start_check = np.max(abs(torch.softmax(logit(torch.from_numpy(initial)),dim=-1).detach().numpy()-parent["posterior"][None]))\nassert warm_start_check<1e-9\nassert np.max(abs(losses(torch.from_numpy(initial))[[0,2],:,1].detach().numpy()))<1e-10\ninitial_value,initial_gradient = scipy_objective(initial)\nprobe = np.zeros_like(initial)\nprobe[0] = 1e-4\ngradient_check = abs((float(objective(torch.from_numpy(initial+probe)))-float(objective(torch.from_numpy(initial-probe))))/(2e-4)-initial_gradient[0])\nassert gradient_check<1e-7\nhistory = [[0,initial_value]]\nprint("SOURCE_BLOCK_SETUP",n_outer,"cases","no_new_features","gradient_check",gradient_check,\n    "initial_components",losses(torch.from_numpy(initial)).mean(dim=1).detach().numpy().tolist(),flush=True)\nresult = minimize(scipy_objective,initial,jac=True,method="L-BFGS-B",\n    callback=lambda intermediate_result:(history.append([len(history),float(intermediate_result.fun)]),\n        len(history)%solver_config["progress_every"]==0 and print("SOURCE_BLOCK_PROGRESS",len(history)-1,float(intermediate_result.fun),flush=True)),\n    options={"maxiter":solver_config["maxiter"],"ftol":solver_config["ftol"],"gtol":solver_config["gtol"],"maxls":solver_config["maxls"]})\nparameters = torch.as_tensor(result.x,dtype=torch.float64)\nscore = logit(parameters).detach().numpy()\nmass = torch.softmax(torch.as_tensor(score),dim=-1).numpy()\nmean = mass@period\nmode = period[score.argmax(axis=-1)]\nmedian = period[(np.cumsum(mass,axis=-1)>=.5).argmax(axis=-1)]\nrun_average = data["run_membership"]/data["run_membership"].sum(axis=1)[:,None]\nrun_reference = (data["run_membership"]@data["target"])/(data["run_membership"]@data["qualified"].astype(float))\nx = mean@run_average.T\nresidual = run_reference[None,None]-x\ncalibration_train = data["outer_train_run"]\ncalibration_n = calibration_train.sum(axis=-1)\nn_run = len(run_reference)\nposition = np.arange(n_run)\norder = np.argsort(np.where(calibration_train[None],x,np.inf),axis=-1)\nsorted_x = np.take_along_axis(x,order,axis=-1)\neligible = position[None,None]<calibration_n[None,:,None]\nsorted_y = np.where(eligible,np.take_along_axis(residual,order,axis=-1),0.)\nprefix = np.pad(np.cumsum(sorted_y,axis=-1),((0,0),(0,0),(1,0)))\ninterval_sum = prefix[:,:,None,1:]-prefix[:,:,:-1,None]\ninterval_n = position[None,:]-position[:,None]+1\nvalid_interval = (interval_n[None,None]>0)&(position[None,None,None]<calibration_n[None,:,None,None])\ninterval_mean = np.divide(interval_sum,interval_n[None,None],out=np.full_like(interval_sum,np.inf),where=valid_interval)\nsuffix_minimum = np.minimum.accumulate(interval_mean[:,:,:,::-1],axis=-1)[:,:,:,::-1]\nfitted_y = np.max(np.where(position[:,None]<=position[None,:],suffix_minimum,-np.inf),axis=2)\nfitted_y = np.where(eligible,fitted_y,0.)\nlibrary_check = np.max(abs(isotonic_regression(sorted_y[0,0,:calibration_n[0]])-fitted_y[0,0,:calibration_n[0]]))\nassert library_check<1e-10\nlower = np.sum(x[:,:,:,None]>=np.where(eligible,sorted_x,np.inf)[:,:,None,:],axis=-1)-1\nlower = np.maximum(np.minimum(lower,calibration_n[None,:,None]-1),0)\nupper = np.minimum(lower+1,calibration_n[None,:,None]-1)\nx_lower = np.take_along_axis(sorted_x,lower,axis=-1)\nx_upper = np.take_along_axis(sorted_x,upper,axis=-1)\ny_lower = np.take_along_axis(fitted_y,lower,axis=-1)\ny_upper = np.take_along_axis(fitted_y,upper,axis=-1)\nlast_x = np.take_along_axis(sorted_x,(calibration_n-1)[None,:,None],axis=-1)\nquery_x = np.clip(x,sorted_x[:,:,0,None],last_x)\nfraction = np.divide(query_x-x_lower,x_upper-x_lower,out=np.zeros_like(query_x),where=x_upper>x_lower)\ncorrection = y_lower+fraction*(y_upper-y_lower)\ncalibrated = mean+correction[:,:,data["run_index"]]\nestimate = np.stack([mean,mode,median,calibrated],axis=-1).transpose(1,2,0,3).reshape(n_outer,len(data["trace_id"]),n_variant*4)\nassert np.isfinite(estimate[data["outer_query"]]).all()\nnp.savez_compressed(output_path,\n    methods=np.char.add(np.asarray(["task_period_density_source_phase_rank","task_period_density_source_phase_proper","task_period_density_source_base_rank"])[:,None],\n        np.asarray(["_mean","_mode","_median","_monotone_mean"])[None]).ravel(),\n    estimate=estimate,trace_id=data["trace_id"],period=period,coefficient=coefficient(parameters).detach().numpy(),\n    feature_scale=parent["feature_scale"],posterior=mass,source_index=source_index,source_negative=source_negative,active_terms=active_terms,rival_mask=rival_mask,\n    objective_history=np.asarray(history),gradient_check=gradient_check,warm_start_check=warm_start_check,\n    final_objective=result.fun,optimizer_success=result.success,optimizer_message=str(result.message),optimizer_iterations=result.nit,\n    gradient_max=np.max(abs(result.jac)),loss_components=losses(parameters).detach().numpy(),training_labels=train_n,\n    calibration_training_run=calibration_train,calibration_training_experiments=calibration_n,\n    sorted_run_index=order,sorted_training_prediction=sorted_x,fitted_training_residual=fitted_y,run_correction=correction,\n    definition="source_ranking_refinement_of_14_phase_terms_only_KL_or_proper_preservation_or_90_base_terms_only_KL_same_unit_delta_prior",\n    information="original_29_outer_cases_same_target_period_labels_no_optical_background_labels_no_new_validation")\nprint("SOURCE_BLOCK_FITTED",str(result.message),result.nit,"gradient",np.max(abs(result.jac)),flush=True)\nraise SystemExit(0)\n'
