task_density_source_rank_export_stage = '\nimport torch\nfrom scipy.optimize import minimize\nfrom scipy.special import softmax\nfrom sklearn.isotonic import isotonic_regression\nsolver_config = {"maxiter":900,"ftol":1e-11,"gtol":1e-6,"maxls":30,"progress_every":25}\nbench = application["task_supervised"]\nconfig = application["task_transfer"]\noutput_path = Path(str(config["stem"])).with_name("lemna_task_period_density_source_rank_model.npz")\ndata = np.load(str(bench["stem"])+"_context.npz",allow_pickle=False)\ncache = np.load(str(config["stem"])+"_period_profile_context.npz",allow_pickle=False)\nparent = dict(np.load(output_path.with_name("lemna_task_period_density_response_model.npz"),allow_pickle=False))\nheld_phase = np.load(str(config["stem"])+"_period_density_quadrature_fixed.npz",allow_pickle=False)\ntorch.set_num_threads(int(os.environ["PERIOD_THREADS"]))\nperiod = cache["period"]\nbase_features = np.concatenate([cache["base_features"],held_phase["quadrature"][:,:,None]],axis=-1)\nleft,right = np.triu_indices(base_features.shape[-1])\nfeatures = np.concatenate([base_features,base_features[:,:,left]*base_features[:,:,right]],axis=-1)\nparent["posterior"] = softmax(np.einsum("npd,gd->gnp",features,parent["coefficient"],optimize=True),axis=-1)\nn_outer = len(parent["fit_length"])\ncount = data["mask"].sum(axis=-1)\ntrain = (parent["fit_length"][:,None]==count[None])&data["qualified"][None]\ntrain_n = train.sum(axis=-1)\nweight = train/train_n[:,None]\ngrid_step = float(period[1]-period[0])\nteacher = np.maximum(1.-abs(period[None]-data["target"][:,None])/grid_step,0.)\nsource_index = cache["base_features"][:,:,[0,4]].argmax(axis=1)\nsource_negative = teacher[np.arange(len(data["trace_id"]))[:,None],source_index]==0.\ngrid_negative = teacher==0.\ntensor_features = torch.as_tensor(features,dtype=torch.float64)\ntensor_scale = torch.as_tensor(parent["feature_scale"],dtype=torch.float64)\ntensor_parent_coefficient = torch.as_tensor(parent["coefficient"],dtype=torch.float64)\ntensor_parent_mass = torch.as_tensor(parent["posterior"],dtype=torch.float64)\ntensor_parent_log = torch.log(tensor_parent_mass.clamp_min(torch.finfo(torch.float64).tiny))\ntensor_target_feature = torch.as_tensor(np.einsum("np,npd->nd",teacher,features,optimize=True),dtype=torch.float64)\ntensor_source_feature = torch.as_tensor(features[np.arange(len(features))[:,None],source_index],dtype=torch.float64)\ntensor_source_negative = torch.as_tensor(source_negative,dtype=torch.float64)\ntensor_grid_negative = torch.as_tensor(grid_negative,dtype=torch.float64)\ntensor_weight = torch.as_tensor(weight,dtype=torch.float64)\ntensor_n = torch.as_tensor(train_n,dtype=torch.float64)\n\nparameter_shape = (n_outer,features.shape[-1])\ncoefficient = lambda parameter:tensor_parent_coefficient+parameter.reshape(parameter_shape)/tensor_scale\nlogit = lambda parameter:torch.einsum("npd,gd->gnp",tensor_features,coefficient(parameter))\nlosses = lambda parameter:(\n    delta:=parameter.reshape(parameter_shape),\n    coef:=coefficient(parameter),\n    score:=logit(parameter),\n    positive:=torch.einsum("nd,gd->gn",tensor_target_feature,coef),\n    source_score:=torch.einsum("nkd,gd->gnk",tensor_source_feature,coef),\n    ranking:=((torch.nn.functional.softplus(source_score-positive[:,:,None])*tensor_source_negative[None]).sum(dim=-1)/tensor_source_negative.sum(dim=-1).clamp_min(1.)[None]*tensor_weight).sum(dim=-1),\n    preservation:=((tensor_parent_mass*(tensor_parent_log-torch.log_softmax(score,dim=-1))).sum(dim=-1)*tensor_weight).sum(dim=-1),\n    prior:=delta.square().sum(dim=-1)/(2.*tensor_n),\n    torch.stack([ranking,preservation,prior],dim=-1))[-1]\nobjective = lambda parameter:losses(parameter).sum(dim=-1).mean()\ngradient_value = torch.func.grad_and_value(objective)\nto_scipy = lambda gradient,value:(value.detach().item(),gradient.detach().numpy())\nscipy_objective = lambda parameter:to_scipy(*gradient_value(torch.from_numpy(parameter)))\ninitial = np.zeros(parameter_shape).ravel()\nwarm_start_check = np.max(abs(torch.softmax(logit(torch.from_numpy(initial)),dim=-1).detach().numpy()-parent["posterior"]))\nassert warm_start_check<1e-9\ninitial_value,initial_gradient = scipy_objective(initial)\nprobe = np.zeros_like(initial)\nprobe[0] = 1e-4\ngradient_check = abs((float(objective(torch.from_numpy(initial+probe)))-float(objective(torch.from_numpy(initial-probe))))/(2e-4)-initial_gradient[0])\nassert gradient_check<1e-7\nhistory = [[0,initial_value]]\nprint("SOURCE_RANK_EXPORT_SETUP",parent["fit_length"].tolist(),train_n.tolist(),gradient_check,flush=True)\nresult = minimize(scipy_objective,initial,jac=True,method="L-BFGS-B",\n    callback=lambda intermediate_result:(history.append([len(history),float(intermediate_result.fun)]),\n        len(history)%solver_config["progress_every"]==0 and print("SOURCE_RANK_EXPORT_PROGRESS",len(history)-1,float(intermediate_result.fun),flush=True)),\n    options={"maxiter":solver_config["maxiter"],"ftol":solver_config["ftol"],"gtol":solver_config["gtol"],"maxls":solver_config["maxls"]})\nparameters = torch.as_tensor(result.x,dtype=torch.float64)\nfull_coefficient = coefficient(parameters).detach().numpy()\nmass = torch.softmax(logit(parameters),dim=-1).detach().numpy()\nmean = mass@period\nassert result.success\nrun_average = data["run_membership"]/data["run_membership"].sum(axis=1)[:,None]\nrun_qualified = data["run_membership"]@data["qualified"].astype(float)\nrun_reference = (data["run_membership"]@data["target"])/run_qualified\nbase_prediction = mean\nbase_run_prediction = base_prediction@run_average.T\nresidual = run_reference[None]-base_run_prediction\ntrain = parent["fit_length"][:,None]==data["run_length"][None]\ntrain_n = train.sum(axis=1)\nn_outer,n_run = train.shape\norder = np.argsort(np.where(train,base_run_prediction,np.inf),axis=1)\nposition = np.arange(n_run)\nsorted_x = np.take_along_axis(base_run_prediction,order,axis=1)\nsorted_residual = np.take_along_axis(residual,order,axis=1)\nsorted_eligible = position[None]<train_n[:,None]\nsorted_residual = np.where(sorted_eligible,sorted_residual,0.)\nprefix = np.pad(np.cumsum(sorted_residual,axis=1),((0,0),(1,0)))\ninterval_sum = prefix[:,None,1:]-prefix[:,:-1,None]\ninterval_n = position[None,:]-position[:,None]+1\nvalid_interval = (interval_n[None]>0)&(position[None,None]<train_n[:,None,None])\ninterval_mean = np.divide(interval_sum,interval_n[None],\n    out=np.full_like(interval_sum,np.inf),where=valid_interval)\nsuffix_minimum = np.minimum.accumulate(interval_mean[:,:,::-1],axis=-1)[:,:,::-1]\nfitted_residual = np.max(np.where(position[:,None]<=position[None,:],suffix_minimum,-np.inf),axis=1)\nfitted_residual = np.where(sorted_eligible,fitted_residual,0.)\nlibrary_fit = isotonic_regression(sorted_residual[0,:train_n[0]],increasing=True)\nlibrary_check = np.max(abs(library_fit-fitted_residual[0,:train_n[0]]))\nassert library_check<1e-10\nassert np.all(np.diff(fitted_residual,axis=1)[position[None,1:]<train_n[:,None]]>=-1e-10)\nsearch_x = np.where(sorted_eligible,sorted_x,np.inf)\nlower = np.sum(base_run_prediction[:,:,None]>=search_x[:,None,:],axis=-1)-1\nlower = np.maximum(np.minimum(lower,train_n[:,None]-1),0)\nupper = np.minimum(lower+1,train_n[:,None]-1)\nx_lower = np.take_along_axis(sorted_x,lower,axis=1)\nx_upper = np.take_along_axis(sorted_x,upper,axis=1)\nr_lower = np.take_along_axis(fitted_residual,lower,axis=1)\nr_upper = np.take_along_axis(fitted_residual,upper,axis=1)\nlast_x = sorted_x[np.arange(n_outer),train_n-1]\nquery_x = np.clip(base_run_prediction,sorted_x[:,0,None],last_x[:,None])\nfraction = np.divide(query_x-x_lower,x_upper-x_lower,out=np.zeros_like(query_x),where=x_upper>x_lower)\ncorrection = r_lower+fraction*(r_upper-r_lower)\nestimate = base_prediction+correction[:,data["run_index"]]\nrun_estimate = estimate@run_average.T\nquery_order = np.argsort(base_run_prediction,axis=1)\norder_check = np.min(np.diff(np.take_along_axis(run_estimate,query_order,axis=1),axis=1))\nassert order_check>-1e-10\nassert np.isfinite(estimate).all()\n\nmodel = {k:v for k,v in parent.items() if k!="posterior"}\nmodel.update(method="task_period_density_source_rank_monotone_mean",\n    coefficient=full_coefficient,feature_schema="13_linear_quadratic_features_104_source_specific_reranked",\n    primary_decision="source_reranked_conditional_mean_plus_monotone_training_experiment_residual",\n    calibration_prediction=sorted_x,calibration_residual=fitted_residual,\n    calibration_experiments=train_n,calibration_run_index=order,\n    source_ranking_iterations=result.nit,source_ranking_optimizer_success=result.success,\n    source_ranking_gradient_max=np.max(abs(result.jac)),source_ranking_gradient_check=gradient_check,\n    source_ranking_loss_components=losses(parameters).detach().numpy(),source_ranking_objective_history=np.asarray(history),\n    calibration_library_check=library_check,calibration_run_order_check=order_check,\n    parent_method=str(parent["method"]),loss="physical_source_logistic_rank_parent_KL_unit_delta_Gaussian",\n    reference_use="same_scalar_target_periods_training_experiments_only_no_background_labels")\nnp.savez_compressed(output_path,**model)\nfolds = np.asarray([13,17])\nreplay = dict(np.load(output_path.with_name("lemna_task_period_density_response_replay_model.npz"),allow_pickle=False))\nheld = np.load(str(config["stem"])+"_period_density_source_ranking.npz",allow_pickle=False)\nreplay.update(method=model["method"],coefficient=held["coefficient"][0,folds],\n    feature_scale=held["feature_scale"][folds],feature_schema=model["feature_schema"],\n    primary_decision=model["primary_decision"],parent_method=model["parent_method"],loss=model["loss"],\n    calibration_prediction=held["sorted_training_prediction"][0,folds],\n    calibration_residual=held["fitted_training_residual"][0,folds],\n    calibration_experiments=held["calibration_training_experiments"][folds],\n    calibration_run_index=held["sorted_run_index"][0,folds],\n    source_ranking_optimizer_success=held["optimizer_success"],source_ranking_gradient_max=held["gradient_max"])\nreplay_path = output_path.with_name("lemna_task_period_density_source_rank_replay_model.npz")\nnp.savez_compressed(replay_path,**replay)\nprint("SOURCE_RANK_MODELS_SAVED",output_path,replay_path,"iterations",result.nit,\n    "gradient",np.max(abs(result.jac)),"calibration_runs",train_n.tolist(),flush=True)\nraise SystemExit(0)\n'
