exec(compile({"task-period-supervised-acf-export":task_supervised_acf_export_stage,"task-period-acf-predict":task_supervised_acf_predict_stage,"task-period-supervised-within":task_supervised_within_stage,"task-period-supervised-within-report":task_supervised_within_report_stage,"task-period-supervised-acf-prepare":task_supervised_acf_prepare_stage,"task-period-supervised-acf-report":task_supervised_acf_report_stage,"task-period-supervised-prepare":task_supervised_prepare_stage,"task-period-supervised-fit":task_supervised_fit_stage,"task-period-supervised-report":task_supervised_report_stage,"task-period-supervised-refinement-report":task_supervised_refinement_report_stage}.get(args.stage,""),__file__,"exec"))

