all_stages = r'''
subprocess.run([sys.executable,"-X","utf8",ROOT/"software/sota_rebuild.py","--stage","all"],check=True)
raise SystemExit(0)
'''
exec(compile({True: all_stages, False: ""}[args.stage == "all"], __file__, "exec"))

prepare_stage = r'''
p=application["paths"]["builder"]
s=p.read_text(encoding="utf-8")
builder={"__file__":str(p)}
exec(compile(s[:s.index("\nexec(compile(transfer_text,")],str(p),"exec"),builder)
b=builder["proposal_builder"]
context={"__file__":str(b["source"])}
exec(b["signal_driver"]["source_header"],context)
context["CONFIG"].update({**b["CONFIG"],**b["template_options"],**b["startup_driver"]["CONFIG"]})
context["CONFIG"]["paths"]["interpolation_source"]=b["CONFIG"]["paths"]["interpolation_source"]
data=pd.read_parquet(application["paths"]["predictions"]).sort_values("trace_id").reset_index(drop=True)
observations=pd.read_parquet(application["paths"]["observations"])
base_periods=data[application["source_periods"]].to_numpy(dtype=float)
periods=np.concatenate([base_periods,base_periods/2.,base_periods*2.],axis=-1)
periods=np.where((periods>=application["period_bounds_h"][0])&(periods<=application["period_bounds_h"][1]),periods,np.nan)
names=np.asarray(application["source_periods"])
candidate_columns=pd.Index(np.concatenate([names,np.char.add(names,"_half"),np.char.add(names,"_double")]))
observations["bin"]=np.rint(observations["x"]/context["CONFIG"]["bin_h"]).astype(int)
binned=observations.groupby(["trace_id","bin"],sort=False)["signal_y"].mean().reset_index()
signal=np.full((len(data),int(context["CONFIG"]["input_hi_h"]/context["CONFIG"]["bin_h"])+1),np.nan)
signal[pd.Categorical(binned["trace_id"],categories=data["trace_id"]).codes,binned["bin"].to_numpy()]=binned["signal_y"].to_numpy()
context.update(data=data,periods=periods,candidate_columns=candidate_columns,n=len(data),signal=signal,grid_size=signal.shape[1])
source_text=b["signal_driver"]["source_text"]
signal_start=source_text.index("\nmask = np.isfinite(signal)")+1
feature_start=source_text.index("\n# Phase-conditional entropy",signal_start)
feature_end=source_text.index("\nrelative_features = np.stack([",feature_start)
exec(compile(source_text[signal_start:feature_start],str(b["source"]),"exec"),context)
exec(compile(source_text[feature_start:feature_end],str(b["source"]),"exec"),context)
context["old_periods"]=context["periods"].copy()
context["periods"]=periods
startup_code=b["startup_driver"]["startup_code"].replace("print('startup_half_life_quantiles_h', np.quantile(np.log(2.0) / startup_rate[startup_valid], [0.0, 0.25, 0.5, 0.75, 1.0]), flush=True)","")
startup_scope={"__file__":str(b["startup_source"]),"Path":Path,"startup_code":startup_code}
startup_start=b["startup_text"].index("proposal_code = compile(startup_code +")
startup_end=b["startup_text"].index("\noriginal =",startup_start)
exec(compile(b["startup_text"][startup_start:startup_end],str(b["startup_source"]),"exec"),startup_scope)
exec(startup_scope["proposal_code"],context)
exec(b["startup_driver"]["feature_body"],context)
assert context["periods"].shape==(len(data),26)
raw_background=context["background"].copy()
exec(b["noise_code"],context)
noise_features=context["features_joint"].copy()
exec(b["harmonic_code"],context)
spectral={**context,"samples":len(context["time"]),"valid":context["valid_candidate"],"signals":{"background":raw_background},"rates":{"startup_rate":context["startup_rate"],"startup_valid":context["startup_valid"]}}
exec(b["spectral_code"],spectral)
exec(b["correlation_code"],context)
exec(b["shape_code"],context)
template={"clock_context":context,"CONFIG":context["CONFIG"],"np":np,"n":len(data),"clock_periods":context["periods"]}
exec(b["template_fit_code"],template)
context["features_early"]=np.column_stack([noise_features,spectral["log_ratio"].reshape(len(data)*26,-1),context["adjusted_gain"].reshape(len(data)*26,-1),context["shape_power"].reshape(len(data)*26,-1),template["weighted_clock_fraction"].reshape(len(data)*26,-1)])
assert context["features_early"].shape==(len(data)*26,49)
external={**builder["transfer_context"],"context":context,"np":np,"proposal_builder":b}
exec(compile(builder["completion_input"],str(p),"exec"),external)
context=external["context"]
original_periods=context["periods"].copy()
original_valid=context["valid_candidate"].copy()
original_features=np.delete(context["features_joint"],application["source_columns"],axis=-1)
proposal_startup_rate=context["startup_rate"].copy()
proposal_startup_valid=context["startup_valid"].copy()
assert original_periods.shape==(len(data),32) and original_features.shape==(len(data)*32,44)
print(args.dataset+"_frozen_base_features",original_features.shape,flush=True)

noise_path=application["paths"]["difference"]
noise_text=noise_path.read_text(encoding="utf-8")
noise_driver={"__file__":str(noise_path)}
exec(compile(noise_text[:noise_text.index("\nparser =")],str(noise_path),"exec"),noise_driver)
context["background"]=raw_background
context["CONFIG"].update(local_startup_rank=b["startup_driver"]["CONFIG"]["subspace_rank"],local_startup_maximum_half_life_h=b["startup_driver"]["CONFIG"]["maximum_startup_half_life_h"])
current_noise=compile(noise_driver["local_startup_code"]+b["driver"]["driver"]["noise_preamble"].replace(noise_driver["noise_anchor"],noise_driver["noise_code"]),str(noise_path),"exec")
exec(current_noise,context)
native_path=application["paths"]["native"]
native_text=native_path.read_text(encoding="utf-8")
native_scope={"__file__":str(native_path),"b":b,"np":np,"Path":Path}
start=native_text.index('native_source=program["paths"]["native_source"]')
end=native_text.index('\nstart=text.index("signal_code = compile")',start)
native_scope["program"]={"paths":{"native_source":ROOT/"software/sota_sample_template_completion_selector.py"}}
exec(compile(native_text[start:end],str(native_path),"exec"),native_scope)
native_eval={"clock_context":context,"CONFIG":b["CONFIG"],"np":np,"n":len(data)}
exec(native_scope["native_search"],native_eval)
native_period=native_eval["observed_native_period"]
frame={"CONFIG":context["CONFIG"],"periods":original_periods,"valid_candidate":original_valid,"mask":context["mask"],"time":context["time"],"scale":context["scale"],"y":context["y"],"weighted_background":context["weighted_background"],"envelopes":np.exp(-np.log(2.)*context["time"][None]/np.asarray(b["CONFIG"]["half_lives_h"])[:,None]),"native_period":native_period}
field_path=application["paths"]["field"]
field_text=field_path.read_text(encoding="utf-8")
field_scope={"__file__":str(field_path),"b":b,"p":field_path,"np":np,"Path":Path,"program":{"paths":{"difference":noise_path,"edge":ROOT/"software/sota_exact_edge_selector.py"}}}
start=field_text.index('feature_text=b["startup_driver"]["feature_text"]')
end=field_text.index('\nprimary_context_setup=',start)
exec(compile(field_text[start:end],str(field_path),"exec"),field_scope)
edge_scope={"original":frame,"b":b,"np":np,"n":len(data),"p":field_path}
exec(field_scope["edge_code"],edge_scope)
features50=np.column_stack([original_features,edge_scope["extra"]])
smooth_scope={"original":frame,"b":b,"np":np,"n":len(data),"p":field_path}
exec(compile(noise_driver["profile_kernel"],str(noise_path),"exec"),smooth_scope)
features50[:,[39,41,43]]=smooth_scope["extra"][:,:3]
features80=np.column_stack([features50,smooth_scope["extra"][:,3:]])
assert features80.shape==(len(data)*32,80)
frame.update(cached_smooth=smooth_scope["extra"][:,:3],cached_smooth_gain=smooth_scope["smooth_gain"],cached_smooth_phase=smooth_scope["smooth_phase"],cached_period_grid=smooth_scope["search_periods"])
wave_scope={"original":frame,"b":b,"np":np,"n":len(data),"p":field_path}
exec(compile(noise_driver["wave_shape_kernel"],str(noise_path),"exec"),wave_scope)
gain=np.concatenate([smooth_scope["smooth_gain"],wave_scope["mechanism_gain"]],axis=2)
grid=smooth_scope["search_periods"]
proposals=grid[gain.argmax(-1)].reshape(len(data),-1)
# Retain the existing peak proposals and optionally expose the whole already
# computed grid, so a weaker source is not discarded by an early argmax.
completion=np.broadcast_to(grid,(len(data),len(grid)))[:,:len(grid)*application["complete_period_grid"]]
proposals=np.column_stack([proposals,completion])
old_duplicate=(np.abs(proposals[:,:,None]-original_periods[:,None])<application["alignment_tolerance_h"])&original_valid[:,None]
self_duplicate=np.tril(np.abs(proposals[:,:,None]-proposals[:,None])<application["alignment_tolerance_h"],k=-1)
proposal_valid=~old_duplicate.any(-1)&~self_duplicate.any(-1)
cache={"periods":original_periods,"valid":original_valid,"features":features80,"trace_id":data["trace_id"].to_numpy(dtype=str),"native_period":native_period,"smooth_gain":smooth_scope["smooth_gain"],"smooth_phase":smooth_scope["smooth_phase"],"period_grid":grid}
context.update(startup_rate=proposal_startup_rate,startup_valid=proposal_startup_valid)
field_scope.update(context=context,args=argparse.Namespace(dataset=args.dataset),cache=cache,query_slice=slice(None),proposals=proposals,proposal_k=proposals.shape[1],grid=grid,d=builder,primary_context_setup="",primary_rate_setup="",program={**field_scope["program"],"source_columns":application["source_columns"]})
field_marker="stage=compile(r"+chr(39)*3
start=field_text.index(field_marker)+len(field_marker)
end=field_text.index("\n"+chr(39)*3+',str(p),"exec")',start)
exec(compile(field_text[start:end],str(field_path),"exec"),field_scope)
new_features=field_scope["features"].reshape(len(data),proposals.shape[1],80)
periods=np.column_stack([original_periods,proposals])
valid=np.column_stack([original_valid,proposal_valid])
features=np.concatenate([features80.reshape(len(data),32,80),new_features],axis=1)
assert features.shape==(len(data),32+proposals.shape[1],80)
np.savez_compressed(application["paths"]["field_features"],features=features.reshape(-1,80),periods=periods,valid=valid,trace_id=data["trace_id"].to_numpy(dtype=str),native_period=native_period,truth=np.full(len(data),np.nan),groups=np.full(len(data),args.dataset.upper()),smooth_gain=cache["smooth_gain"],smooth_phase=cache["smooth_phase"],period_grid=grid)
np.savez_compressed(application["paths"]["context"],y=context["y"],mask=context["mask"],time=context["time"],background=context["adaptive_background"],scale=context["scale"],ridge=context["CONFIG"]["ridge"],trace_id=data["trace_id"].to_numpy(dtype=str))
print(args.dataset+"_full_field_ready",features.shape,valid.sum(-1).min(),valid.sum(-1).max(),flush=True)
raise SystemExit(0)
'''
exec(compile({True: prepare_stage, False: ""}[args.stage == "prepare"], __file__, "exec"))

p=application["paths"]["mechanism"]
s=p.read_text(encoding="utf-8")
scope={"__file__":str(p)}
exec(compile(s[:s.index('\nparser = argparse.ArgumentParser()')],str(p),"exec"),scope)
start=s.index("natural_context_code = r'''")+len("natural_context_code = r'''")
end=s.index("\n'''",start)
scope.update(p=p,s=s,output=OUTPUT,mode=args.dataset)
exec(compile(s[start:end],str(p),"exec"),scope)
geometry=scope["d"]
phase_stage = r'''
marker="exact_global_phase_readout="+"r"+chr(39)*3
start=s.index(marker)+len(marker)
global_code=s[start:s.index("\n"+chr(39)*3,start)]
exec(compile(global_code,str(p),"exec"),geometry)
np.savez_compressed(OUTPUT/("exact_square_phase_"+args.dataset+"_pool_20261004.npz"),trace_id=geometry["cache"]["trace_id"],periods=geometry["cache"]["periods"],valid=geometry["valid"],power=geometry["exact_power"][:,:,:,3,0],phase=geometry["exact_selected_phase"][:,:,:,3,0])
print(args.dataset+"_unmasked_square_phase_ready",geometry["periods"].shape,flush=True)
raise SystemExit(0)
'''
exec(compile({True:phase_stage,False:""}[args.stage=="phase"],__file__,"exec"))
source_path=application["paths"]["source"]
source_text=source_path.read_text(encoding="utf-8")
start=source_text.index('residual_source_predict_code = r"""')+len('residual_source_predict_code = r"""')
end=source_text.index('\n"""',start)
source_code=source_text[start:end]
source_code=source_code[:source_code.index('\ntraining_export=')]
geometry.update(p=p,s=s,output=OUTPUT,mode=args.dataset,source_fold="full",source_phase_reuse="")
exec(compile(source_code,str(source_path),"exec"),geometry)
previous=np.load(OUTPUT/("native_local_startup_anchored_cell_"+args.dataset+"_features_20261004.npz"))
valid=previous["valid"].reshape(previous["periods"].shape)
extra=np.where(valid[...,None],geometry["exact_power"][...,0].max(axis=2),np.nan)
features=np.column_stack([previous["features"],extra.reshape(-1,4)])
assert features.shape==(valid.size,87)
np.savez_compressed(OUTPUT/("native_local_startup_residual_source_"+args.dataset+"_features_20261004.npz"),**{**dict(previous),"features":features,"residual_source_power":geometry["exact_power"][...,0],"residual_source_mask":geometry["source_mask"]})
np.savez_compressed(OUTPUT/("event_source_phase_train_"+args.dataset+"_20261005.npz"),phase=geometry["exact_selected_phase"][...,0],power=geometry["exact_power"][...,0],trace_id=previous["trace_id"],valid=valid,periods=previous["periods"])

pair_path=application["paths"]["pair_source"]
pair_text=pair_path.read_text(encoding="utf-8")
pair_scope={"__file__":str(pair_path)}
exec(compile(pair_text[:pair_text.index("program_config =")],str(pair_path),"exec"),pair_scope)
decision_config=pair_scope["CONFIG"]
n,k=valid.shape
features=features.reshape(n,k,87)
parent_model=load(application["paths"]["parent_model"])
left_slots,right_slots=np.triu_indices(k,k=1)
pair_query,position=np.nonzero(valid[:,left_slots]&valid[:,right_slots])
left=left_slots[position];right=right_slots[position]
difference=(features[pair_query,left]-features[pair_query,right]).astype(np.float32)
totals=np.asarray(decision_config["pair_total_columns"]);source_columns=np.asarray(decision_config["template_gain_columns"]);context_columns=np.asarray(decision_config["context_columns"])
difference[:,totals]=(features[pair_query,left][:,source_columns]+features[pair_query,right][:,source_columns]).astype(np.float32)
difference[:,context_columns]=features[pair_query,left][:,context_columns]
reverse=np.full(features.shape[-1],-1.,dtype=np.float32);reverse[context_columns]=1.;reverse[totals]=1.
preference=(parent_model.predict(difference)-parent_model.predict(difference*reverse))/2.
parent_score=(np.bincount(pair_query*k+left,weights=preference,minlength=n*k)-np.bincount(pair_query*k+right,weights=preference,minlength=n*k)).reshape(n,k)
parent_score/=np.maximum(valid.sum(-1)-1,1)[:,None]
np.savez_compressed(OUTPUT/("native_local_startup_residual_source_utility_mean_"+args.dataset+"_scores.npz"),scores=np.where(valid,parent_score,-np.inf),periods=previous["periods"],valid=valid,trace_id=previous["trace_id"])
print(args.dataset+"_frozen_source_and_parent_ready",n,k,features.shape[-1],flush=True)
